func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run cmd/tools/add_command/main.go \"YOUR COMMAND HERE\"")
		fmt.Println("Example: go run cmd/tools/add_command/main.go \"TURN OFF FAN\"")
		return
	}

	rawCmd := strings.Join(os.Args[1:], " ")
	intent := strings.ToUpper(strings.ReplaceAll(strings.TrimSpace(rawCmd), " ", "_"))
	fmt.Printf("📝 Registering new command: '%s'\n", intent)
	fmt.Println()

	ae, te, headW, headB, classNames, prototypes, err := moe.LoadAudioModel("models/audio_gru.json")
	if err != nil {
		fmt.Println("❌ No trained model found. Run 'go run cmd/tools/train_audio/main.go' first.")
		return
	}

	if prototypes == nil {
		prototypes = make(map[string][]float32)
	}

	fmt.Printf("✅ Loaded trained model with %d existing commands.\n", len(prototypes))
	fmt.Printf("   Existing: %v\n\n", classNames)

	os.MkdirAll("dataset/audio", 0755)
	reader := bufio.NewReader(os.Stdin)

	var embeddings [][]float32

	for i := 1; i <= NumRecordings; i++ {
		fmt.Printf("🎙️  Sample %d of %d — say '%s'\n", i, NumRecordings, rawCmd)
		fmt.Println("   Press [ENTER] when ready...")
		reader.ReadBytes('\n')

		filename := fmt.Sprintf("dataset/audio/%s_%d.raw", intent, i)
		fmt.Println("🔴 RECORDING (3.5 seconds)...")

		cmd := exec.Command("ffmpeg",
			"-y",
			"-f", "alsa", "-i", "default",
			"-t", "3.5",
			"-ac", "1", "-ar", "16000",
			"-f", "s16le", filename,
		)
		if err := cmd.Run(); err != nil {
			fmt.Printf("❌ Recording failed: %v\n", err)
			return
		}
		fmt.Printf("✅ Recorded to %s\n\n", filename)

		emb, err := computeEmbedding(filename, ae, te)
		if err != nil {
			fmt.Printf("❌ Failed to compute embedding: %v\n", err)
			return
		}
		embeddings = append(embeddings, emb)
	}

	hiddenDim := te.HiddenDim
	prototype := make([]float32, hiddenDim)
	for _, emb := range embeddings {
		for d := 0; d < hiddenDim; d++ {
			prototype[d] += emb[d]
		}
	}
	for d := range prototype {
		prototype[d] /= float32(len(embeddings))
	}

	// Normalize prototype to unit length for stable cosine similarity
	var norm float64
	for _, v := range prototype {
		norm += float64(v) * float64(v)
	}
	norm = math.Sqrt(norm)
	if norm > 0 {
		for d := range prototype {
			prototype[d] = float32(float64(prototype[d]) / norm)
		}
	}

	if _, exists := prototypes[intent]; exists {
		fmt.Printf("⚠️  Updating existing prototype for '%s'\n", intent)
	} else {

		classNames = append(classNames, intent)
		fmt.Printf("🆕 Added new command '%s' to model!\n", intent)
	}

	prototypes[intent] = prototype

	if err := patchModelFile("models/audio_gru.json", classNames, prototypes); err != nil {

		err2 := moe.SaveAudioModel("models/audio_gru.json", ae, te, headW, headB, classNames, prototypes)
		if err2 != nil {
			fmt.Printf("❌ Failed to save: %v\n", err2)
			return
		}
	}

	fmt.Printf("\n🎉 Done! '%s' is now registered.\n", intent)
	fmt.Println("Run 'go run cmd/tools/voice_capture/main.go' to try it out!")
	fmt.Println()
	fmt.Println("All registered commands:")
	for name := range prototypes {
		fmt.Printf("  - %s\n", name)
	}
}

// computeEmbedding loads a raw audio file, finds the loudest 3-second window,
// and returns the GRU embedding vector for that audio.
func computeEmbedding(filename string, ae *moe.AudioEncoder, te *moe.TemporalEncoder) ([]float32, error) {
	rawBytes, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	samples := make([]float32, len(rawBytes)/2)
	for i := range samples {
		s16 := int16(binary.LittleEndian.Uint16(rawBytes[i*2 : i*2+2]))
		samples[i] = float32(s16) / 32768.0
	}

	target := NumSamples
	if len(samples) > target {
		bestStart, bestEnergy := 0, float32(0)
		for start := 0; start <= len(samples)-target; start += FrameSize {
			var energy float32
			for j := 0; j < target; j++ {
				energy += samples[start+j] * samples[start+j]
			}
			if energy > bestEnergy {
				bestEnergy = energy
				bestStart = start
			}
		}
		samples = samples[bestStart : bestStart+target]
	} else {
		padded := make([]float32, target)
		copy(padded, samples)
		samples = padded
	}

	numFrames := len(samples) / FrameSize
	frames := make([][]float32, numFrames)
	for i := 0; i < numFrames; i++ {
		frames[i] = samples[i*FrameSize : (i+1)*FrameSize]
	}

	audioTokens := ae.Forward(frames)
	embedding := te.Forward(audioTokens)
	return embedding, nil
}

// patchModelFile reads the existing JSON and only updates ClassNames + Prototypes,
// preserving all trained weight arrays exactly as-is.
func patchModelFile(path string, classNames []string, prototypes map[string][]float32) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}

	classJSON, err := json.Marshal(classNames)
	if err != nil {
		return err
	}
	raw["ClassNames"] = classJSON

	protoJSON, err := json.Marshal(prototypes)
	if err != nil {
		return err
	}
	raw["Prototypes"] = protoJSON

	out, err := json.MarshalIndent(raw, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, out, 0644)
}

type OllamaReq struct {
	Model	string	`json:"model"`
	Prompt	string	`json:"prompt"`
	Stream	bool	`json:"stream"`
	Format	string	`json:"format"`
}

type OllamaResp struct {
	Response string `json:"response"`
}

func main() {
	logFile := "logs/training_log.csv"
	configFile := "data/config/social_train.json"

	fmt.Println("🤖 Teacher AI Supervisor starting up...")
	fmt.Println("Watching", logFile, "and dynamically hot-patching", configFile)

	for {
		time.Sleep(15 * time.Second)

		content, err := os.ReadFile(logFile)
		if err != nil {
			fmt.Println("Waiting for training logs to generate...")
			continue
		}
		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) < 3 {
			continue
		}

		header := lines[0]
		startIdx := len(lines) - 10
		if startIdx < 1 {
			startIdx = 1
		}
		recentLogs := header + "\n" + strings.Join(lines[startIdx:], "\n")

		configData, err := os.ReadFile(configFile)
		if err != nil {
			fmt.Println("Error reading config:", err)
			continue
		}

		prompt := fmt.Sprintf(`You are an expert AI Training Supervisor dynamically tuning hyperparameters for an MoE model.
Current Configuration:
%s

Recent Training Logs (epoch,avg_loss,lb_loss,perplexity,learning_rate,e0_util...):
%s

Analyze the loss and perplexity trends. If loss is plateauing or jumping, you may want to adjust "learning_rate" or "router_temperature".
Output a JSON object containing ONLY the parameters you want to change. If training is going perfectly, output an empty JSON {}. 
Do not output anything outside the JSON. Example: {"learning_rate": 0.00002}
`, string(configData), recentLogs)

		reqBody, _ := json.Marshal(OllamaReq{
			Model:	"qwen2.5:3b",
			Prompt:	prompt,
			Stream:	false,
			Format:	"json",
		})

		resp, err := http.Post("http://127.0.0.1:11434/api/generate", "application/json", bytes.NewBuffer(reqBody))
		if err != nil {
			fmt.Println("Teacher offline:", err)
			continue
		}

		var oResp OllamaResp
		json.NewDecoder(resp.Body).Decode(&oResp)
		resp.Body.Close()

		text := strings.TrimSpace(oResp.Response)
		if text == "" || text == "{}" {
			fmt.Println("🤖 Teacher evaluated logs: No parameter changes needed right now.")
			continue
		}

		// Parse the Teacher's JSON update
		var teacherUpdates map[string]interface{}
		if err := json.Unmarshal([]byte(text), &teacherUpdates); err != nil {
			fmt.Printf("Teacher generated invalid JSON: %s\n", text)
			continue
		}

		if len(teacherUpdates) == 0 {
			continue
		}

		// 4. Merge changes into existing config
		var currentConfig map[string]interface{}
		json.Unmarshal(configData, &currentConfig)

		changesMade := false
		for k, v := range teacherUpdates {
			if oldV, exists := currentConfig[k]; exists {
				if fmt.Sprintf("%v", oldV) != fmt.Sprintf("%v", v) {
					fmt.Printf("  -> 🔧 Teacher patching %s: %v -> %v\n", k, oldV, v)
					currentConfig[k] = v
					changesMade = true
				}
			}
		}

		if changesMade {
			newConfigData, _ := json.MarshalIndent(currentConfig, "", "  ")
			if err := os.WriteFile(configFile, newConfigData, 0644); err == nil {
				fmt.Println("✅ Teacher dynamically hot-patched social_train.json!")
			}
		} else {
			fmt.Println("🤖 Teacher evaluated logs: Training stable.")
		}
	}
}

