func appendLive(line string) {
	line = ansiRe.ReplaceAllString(line, "")
	line = strings.TrimRight(line, "\r\n ")
	if line == "" {
		return
	}

	liveParseMu.Lock()
	liveStep++
	liveParseMu.Unlock()

	parseAndAppendSupervisorEvent(line)

	if m := reSentenceTest.FindStringSubmatch(line); m != nil {
		phase, _ := strconv.Atoi(m[1])
		sentence := strings.TrimSpace(m[2])
		confidence, _ := strconv.ParseFloat(m[3], 64)
		coherent := strings.EqualFold(m[4], "true")
		liveParseMu.Lock()
		liveSentenceTests = append(liveSentenceTests, SentenceTestPoint{
			Sentence:	sentence,
			Confidence:	confidence,
			Coherent:	coherent,
			Phase:		phase,
			Epoch:		liveEpoch,
			Timestamp:	time.Now().Format(time.RFC3339),
		})
		if len(liveSentenceTests) > 200 {
			liveSentenceTests = liveSentenceTests[len(liveSentenceTests)-200:]
		}
		liveParseMu.Unlock()
	}

	if m := reMultiphase.FindStringSubmatch(line); m != nil {
		epoch, _ := strconv.ParseFloat(m[2], 64)
		liveParseMu.Lock()
		liveEpoch = epoch
		liveParseMu.Unlock()
	}
	if m := reSocial.FindStringSubmatch(line); m != nil {
		epoch, _ := strconv.ParseFloat(m[2], 64)
		liveParseMu.Lock()
		liveEpoch = epoch
		liveParseMu.Unlock()
	}
	if m := reEpochTime.FindStringSubmatch(line); m != nil {
		liveParseMu.Lock()
		liveEpochTime = m[1] + "s"
		liveParseMu.Unlock()
	}
	if m := reActiveExp.FindStringSubmatch(line); m != nil {
		nums := strings.FieldsFunc(m[1], func(r rune) bool { return r == ',' || r == ' ' })
		var exps []int
		for _, n := range nums {
			if v, err := strconv.Atoi(strings.TrimSpace(n)); err == nil {
				exps = append(exps, v)
			}
		}
		liveParseMu.Lock()
		liveActiveExps = exps
		liveParseMu.Unlock()
	}

	liveMu.Lock()
	liveLines = append(liveLines, line)
	if len(liveLines) > maxLiveLines {
		liveLines = liveLines[len(liveLines)-maxLiveLines:]
	}
	liveMu.Unlock()
}

func streamToLive(r io.Reader) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		appendLive(scanner.Text())
	}
}

// handleMine runs the dataset_miner with a user-specified repo URL.
func handleMine(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	if r.Method != http.MethodPost {
		http.Error(w, "POST only", http.StatusMethodNotAllowed)
		return
	}
	var req struct {
		Repo	string	`json:"repo"`
		Max	int	`json:"max"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad JSON", http.StatusBadRequest)
		return
	}
	if req.Repo == "" {
		http.Error(w, `{"error":"repo is required"}`, http.StatusBadRequest)
		return
	}
	if req.Max <= 0 {
		req.Max = 5000
	}
	procMu.Lock()
	if runningCmd != nil {
		procMu.Unlock()
		http.Error(w, `{"error":"already running"}`, http.StatusConflict)
		return
	}
	appendLive("── Mining repo: " + req.Repo + " ──")
	cmd := exec.Command("go", "run", "cmd/tools/dataset_miner/main.go",
		"-repo="+req.Repo,
		"-out=data/training/mined_patches.json",
		"-max="+strconv.Itoa(req.Max),
	)
	cmd.Dir = rootDir
	cmd.Env = os.Environ()
	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	stdout, _ := cmd.StdoutPipe()
	stderr, _ := cmd.StderrPipe()
	if err := cmd.Start(); err != nil {
		procMu.Unlock()
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	runningCmd = cmd
	runningName = "mine:" + shortenRepo(req.Repo)
	procMu.Unlock()
	go streamToLive(stdout)
	go streamToLive(stderr)
	go func() {
		cmd.Wait()
		procMu.Lock()
		runningCmd = nil
		runningName = ""
		procMu.Unlock()
		appendLive("── Mining complete ──")
	}()
	json.NewEncoder(w).Encode(map[string]string{"ok": "true", "msg": "Mining " + req.Repo})
}

