		record, err := reader.Read()
		if err == io.EOF {
			break
		}

		if record[2] != "0" {
			continue
		}

		epoch := record[1]
		dom, _ := strconv.ParseFloat(record[len(record)-1], 64)

		fmt.Printf("%-5s |", epoch)

		numCols := len(record) - 1
		for i := 3; i < numCols && i <= 10; i++ {
