func printColoredCell(val float64) {

	color := 34
	if val > 0.10 && val <= 0.25 {
		color = 32
	} else if val > 0.25 && val <= 0.70 {
		color = 33
	} else if val > 0.70 {
		color = 31
	}
	fmt.Printf(" \033[%dm%0.2f\033[0m |", color, val)
}

type IntentTrainingExample struct {
