func main() {
	fmt.Println("=== Advanced NLP Project Scaffolder (Goal-Driven) ===")
	fmt.Println("Intelligent project manager with memory, goals, and context")
	fmt.Println("Commands: 'goal <desc>', 'work [-auto]', 'status', 'goals', 'resume <id>', 'tree', 'exit'")

	config := agent.AgentConfig{
		MaxIterations:		10,
		EnablePersistence:	true,
		PersistencePath:	"./agent_memory.json",
		WorkingDirectory:	"./generated_projects",
	}
	ag := agent.NewAgent(config)

	// Current active goal
	var currentGoal *agent.Goal

	scanner := bufio.NewScanner(os.Stdin)

	goals, err := ag.ListGoals()
	if err != nil {
		fmt.Printf("Error listing goals: %v\n", err)
	}

	if len(goals) > 0 {
		fmt.Println("\nSelect a project to resume:")
		for i, g := range goals {
			fmt.Printf("%d: %s (%s)\n", i+1, g.Description, g.ID)
		}
		fmt.Print("Enter number to resume, or press Enter to start a new goal: ")

		if scanner.Scan() {
			choiceStr := strings.TrimSpace(scanner.Text())
			if choiceStr != "" {
				choice, err := strconv.Atoi(choiceStr)
				if err == nil && choice > 0 && choice <= len(goals) {
					selectedGoal := goals[choice-1]
					goal, err := ag.GetGoal(selectedGoal.ID)
					if err != nil {
						fmt.Printf("Error loading goal: %v\n", err)
					} else {
						currentGoal = goal
						fmt.Printf("Resumed goal: %s\n", goal.Description)
						fmt.Println(ag.GetGoalStatus(goal))
					}
				} else {
					fmt.Println("Invalid selection.")
				}
			}
		}
	}

	for {
		if currentGoal != nil {
			fmt.Printf("[%s] > ", currentGoal.ID)
		} else {
			fmt.Print("> ")
		}

		if !scanner.Scan() {
			break
		}

		query := strings.TrimSpace(scanner.Text())
		if query == "" {
			continue
		}

		if query == "exit" || query == "quit" {
			fmt.Println("Goodbye!")
			break
		}

		parts := strings.Fields(query)
		command := parts[0]

		switch command {
		case "goal":
			if len(parts) < 2 {
				fmt.Println("Usage: goal <description>")
				continue
			}
			description := strings.Join(parts[1:], " ")
			goal, err := ag.CreateGoalFromDescription(description)
			if err != nil {
				fmt.Printf("Error creating goal: %v\n", err)
				continue
			}
			currentGoal = goal
			fmt.Printf("Goal created: %s (ID: %s)\n", goal.Description, goal.ID)
			fmt.Println(ag.GetGoalStatus(goal))

		case "work":
			if currentGoal == nil {
				fmt.Println("No active goal. Use 'goal <desc>' or 'resume <id>' first.")
				continue
			}

			autoMode := len(parts) > 1 && parts[1] == "-auto"

			if autoMode {

				fmt.Println("Starting continuous execution...")
				for {
					task, err := ag.WorkOnGoalStep(currentGoal)
					if err != nil {
						fmt.Printf("Error executing step: %v\n", err)
						break
					}
					if task == nil {
						fmt.Println("No more tasks to execute.")
						if currentGoal.Progress >= 1.0 {
							fmt.Println("Goal completed successfully!")
							currentGoal.Status = agent.GoalCompleted
						}
						break
					}
					fmt.Printf("Executed: %s -> %s\n", task.Description, task.Status)

					if currentGoal.Progress >= 1.0 {
						fmt.Println("Goal completed successfully!")
						break
					}
				}
			} else {

				task, err := ag.WorkOnGoalStep(currentGoal)
				if err != nil {
					fmt.Printf("Error executing step: %v\n", err)
					continue
				}
				if task == nil {
					fmt.Println("No more tasks to execute.")
					if currentGoal.Progress >= 1.0 {
						fmt.Println("Goal completed successfully!")
						currentGoal.Status = agent.GoalCompleted
					}
				} else {
					fmt.Printf("Executed: %s -> %s\n", task.Description, task.Status)
					fmt.Printf("Result: %s\n", task.Result)
				}
			}

			fmt.Println(ag.GetGoalStatus(currentGoal))

		case "status":
			if currentGoal == nil {
				fmt.Println("No active goal.")
				continue
			}
			fmt.Println(ag.GetGoalStatus(currentGoal))

		case "goals":
			goals, err := ag.ListGoals()
			if err != nil {
				fmt.Printf("Error listing goals: %v\n", err)
				continue
			}
			fmt.Println("Saved Goals:")
			for _, g := range goals {
				fmt.Printf("- %s: %s (%.0f%%)\n", g.ID, g.Description, g.Progress*100)
			}

		case "resume":
			if len(parts) < 2 {
				fmt.Println("Usage: resume <goal_id>")
				continue
			}
			goalID := parts[1]
			goal, err := ag.GetGoal(goalID)
			if err != nil {
				fmt.Printf("Error loading goal: %v\n", err)
				continue
			}
			currentGoal = goal
			fmt.Printf("Resumed goal: %s\n", goal.Description)
			fmt.Println(ag.GetGoalStatus(goal))

		case "tree":
			fmt.Println(ag.VFS.Tree())

		default:
			fmt.Println("Unknown command. Available: goal, work, status, goals, resume, tree, exit")
		}
	}
}

type Request struct {
	JSONRPC	string		`json:"jsonrpc"`
	ID	interface{}	`json:"id,omitempty"`
	Method	string		`json:"method"`
	Params	json.RawMessage	`json:"params,omitempty"`
}

type Response struct {
	JSONRPC	string		`json:"jsonrpc"`
	ID	interface{}	`json:"id,omitempty"`
	Result	interface{}	`json:"result,omitempty"`
	Error	interface{}	`json:"error,omitempty"`
}

type Notification struct {
	JSONRPC	string		`json:"jsonrpc"`
	Method	string		`json:"method"`
	Params	interface{}	`json:"params"`
}

type TextDocumentItem struct {
	URI	string	`json:"uri"`
	Text	string	`json:"text"`
}

type TextDocumentIdentifier struct {
	URI string `json:"uri"`
}

type DidOpenTextDocumentParams struct {
	TextDocument TextDocumentItem `json:"textDocument"`
}

type DidSaveTextDocumentParams struct {
	TextDocument TextDocumentIdentifier `json:"textDocument"`
}

type CodeActionParams struct {
	TextDocument TextDocumentIdentifier `json:"textDocument"`
}

type ExecuteCommandParams struct {
	Command		string		`json:"command"`
	Arguments	[]interface{}	`json:"arguments,omitempty"`
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	for {
		req, err := readMessage(reader)
		if err != nil {
			if err == io.EOF {
				break
			}
			log.Printf("LSP Reader error: %v", err)
			continue
		}

		handleMessage(req)
	}
}

func readMessage(r *bufio.Reader) (*Request, error) {
	var contentLength int
	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return nil, err
		}
		line = strings.TrimSpace(line)
		if line == "" {
			break
		}
		if strings.HasPrefix(line, "Content-Length:") {
			lenStr := strings.TrimSpace(strings.TrimPrefix(line, "Content-Length:"))
			contentLength, _ = strconv.Atoi(lenStr)
		}
	}

	if contentLength <= 0 {
		return nil, fmt.Errorf("invalid content length")
	}

	body := make([]byte, contentLength)
	if _, err := io.ReadFull(r, body); err != nil {
		return nil, err
	}

	var req Request
	if err := json.Unmarshal(body, &req); err != nil {
		return nil, err
	}

	return &req, nil
}

func writeMessage(msg interface{}) {
	body, err := json.Marshal(msg)
	if err != nil {
		return
	}
	header := fmt.Sprintf("Content-Length: %d\r\n\r\n", len(body))
	os.Stdout.WriteString(header)
	os.Stdout.Write(body)
}

func handleMessage(req *Request) {
	switch req.Method {
	case "initialize":
		res := map[string]interface{}{
			"capabilities": map[string]interface{}{
				"textDocumentSync":	1,
				"codeActionProvider": map[string]interface{}{
					"codeActionKinds": []string{"quickfix", "refactor"},
				},
				"executeCommandProvider": map[string]interface{}{
					"commands": []string{"gollemer.patch", "gollemer.test"},
				},
			},
		}
		writeMessage(Response{JSONRPC: "2.0", ID: req.ID, Result: res})

	case "initialized":

	case "textDocument/didOpen":
		var params DidOpenTextDocumentParams
		if err := json.Unmarshal(req.Params, &params); err == nil {
			publishDiagnostics(params.TextDocument.URI)
		}

	case "textDocument/didSave":
		var params DidSaveTextDocumentParams
		if err := json.Unmarshal(req.Params, &params); err == nil {
			publishDiagnostics(params.TextDocument.URI)
		}

	case "textDocument/codeAction":
		var params CodeActionParams
		_ = json.Unmarshal(req.Params, &params)

		actions := []map[string]interface{}{
			{
				"title":	"⚡ Gollemer: Apply AI Patch & Self-Heal",
				"kind":		"quickfix",
				"command": map[string]interface{}{
					"title":	"Apply AI Patch",
					"command":	"gollemer.patch",
					"arguments":	[]interface{}{params.TextDocument.URI, "fix code"},
				},
			},
			{
				"title":	"🧪 Gollemer: Scaffold Unit Tests",
				"kind":		"refactor",
				"command": map[string]interface{}{
					"title":	"Scaffold Unit Tests",
					"command":	"gollemer.test",
					"arguments":	[]interface{}{params.TextDocument.URI, "add unit test"},
				},
			},
		}
		writeMessage(Response{JSONRPC: "2.0", ID: req.ID, Result: actions})

	case "workspace/executeCommand":
		var params ExecuteCommandParams
		if err := json.Unmarshal(req.Params, &params); err == nil {
			targetURI := ""
			promptStr := "fix code"
			if len(params.Arguments) > 0 {
				if uri, ok := params.Arguments[0].(string); ok {
					targetURI = uri
				}
			}
			if len(params.Arguments) > 1 {
				if p, ok := params.Arguments[1].(string); ok {
					promptStr = p
				}
			}

			targetFile := strings.TrimPrefix(targetURI, "file://")
			if targetFile != "" {
				subcmd := "patch"
				if params.Command == "gollemer.test" {
					subcmd = "test"
				}
				_ = exec.Command("./bin/gollemer", subcmd, promptStr, "-target="+targetFile).Run()
				publishDiagnostics(targetURI)
			}
		}
		writeMessage(Response{JSONRPC: "2.0", ID: req.ID, Result: "OK"})

	case "shutdown":
		writeMessage(Response{JSONRPC: "2.0", ID: req.ID, Result: nil})

	case "exit":
		os.Exit(0)

	default:
		if req.ID != nil {
			writeMessage(Response{JSONRPC: "2.0", ID: req.ID, Result: nil})
		}
	}
}

func publishDiagnostics(uri string) {
	diags := []map[string]interface{}{}
	notif := Notification{
		JSONRPC:	"2.0",
		Method:		"textDocument/publishDiagnostics",
		Params: map[string]interface{}{
			"uri":		uri,
			"diagnostics":	diags,
		},
	}
	writeMessage(notif)
}

func main() {
	rand.Seed(time.Now().UnixNano())

	inputDim := 10
	hiddenDim := 20
	outputDim := 10
	numExperts := 4
	k := 2
	batchSize := 2

	expertBuilder := func(expertIdx int) (Expert, error) {

		return NewFeedForwardExpert(inputDim, hiddenDim, outputDim)
	}

	moeLayer, err := NewMoELayer(inputDim, outputDim, numExperts, k, expertBuilder)
	if err != nil {
		log.Fatalf("Failed to create MoE Layer: %v", err)
	}

	inputData := make([]float32, batchSize*inputDim)
	for i := range inputData {
		inputData[i] = float32(rand.Float64()) * 10
	}
	inputTensor := NewTensor([]int{batchSize, inputDim}, inputData, true)

	fmt.Printf("Input Tensor Shape: %v\n", inputTensor.Shape)

	output, err := moeLayer.Forward(inputTensor)
	if err != nil {
		log.Fatalf("MoE Layer forward pass failed: %v", err)
	}

	fmt.Printf("Output Tensor Shape: %v\n", output.Shape)
	fmt.Printf("Output Tensor Data (first 5): %v\n", output.Data[:min(5, len(output.Data))])

	moeLayer.VisualizeUtilization()

	gradData := make([]float32, len(output.Data))
	for i := range gradData {
		gradData[i] = 1.0
	}
	gradTensor := NewTensor(output.Shape, gradData, false)

	fmt.Println("\nPerforming backward pass...")
	err = moeLayer.Backward(gradTensor)
	if err != nil {
		log.Fatalf("MoE Layer backward pass failed: %v", err)
	}

	fmt.Println("Backward pass completed.")

	fmt.Printf("\nGating Network Weights Grad (first 5): %v\n", moeLayer.GatingNetwork.Linear.Weights.Grad.Data[:min(5, len(moeLayer.GatingNetwork.Linear.Weights.Grad.Data))])

	if len(moeLayer.Experts) > 0 {
		firstExpert := moeLayer.Experts[0].(*FeedForwardExpert)
		fmt.Printf("First Expert Linear1 Weights Grad (first 5): %v\n", firstExpert.Layer1.Weights.Grad.Data[:min(5, len(firstExpert.Layer1.Weights.Grad.Data))])
	}

	fmt.Printf("Input Tensor Grad (first 5): %v\n", inputTensor.Grad.Data[:min(5, len(inputTensor.Grad.Data))])

	fmt.Println("MoE Layer example finished successfully.")
}

func main() {
	rand.Seed(1)
	flag.Parse()

	queryText := *query
	if queryText == "" && *prompt != "" {
		queryText = *prompt
	}

	if queryText == "" {
		log.Fatal("Please provide a query using the -query or -prompt flag.")
	}

	sup := moe.NewSupervisor()

	var cartPaths []string
	if *cartridgePath != "" {
		for _, p := range strings.Split(*cartridgePath, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				cartPaths = append(cartPaths, p)
			}
		}
	} else {
		cartPaths = sup.TriageCartridgesMulti(queryText, nil)
	}

	if len(cartPaths) > 0 {
		log.Printf("Multi-Expert Router selected %d cartridges: %v", len(cartPaths), cartPaths)
		cm := moe.NewCartridgeManager()
		for _, p := range cartPaths {
			if err := cm.LoadCartridge(p, 0, 0); err != nil {
				log.Printf("Notice: Loaded cartridge %s (fallback/Gob): %v", p, err)
			} else {
				log.Printf("Successfully loaded cartridge into RAM: %s", p)
			}
		}
	}

	log.Printf("Running template-based inference for query: \"%s\"", queryText)

	log.Println("Using template-based JSON generation")

	classifier := semantic.NewIntentClassifier()
	intent := classifier.Classify(queryText)
	log.Printf("Classified intent: %s", intent)

	ruleNER, err := ner.NewRuleBasedNER(queryText, "")
	if err != nil {
		log.Fatalf("Failed to create NER: %v", err)
	}

	entityMap := ruleNER.GetEntityMap()
	extractor := semantic.NewEntityExtractor()
	entities := extractor.ExtractFromQuery(queryText, entityMap)

	log.Printf("Extracted entities: %v", entities)

	words := strings.Fields(queryText)
	templateRegistry := semantic.NewTemplateRegistry()
	hasTemplate := false
	for _, word := range words {
		lowerWord := strings.ToLower(word)
		for _, tmpl := range templateRegistry.ListTemplates() {
			if lowerWord == strings.ToLower(tmpl) {
				hasTemplate = true
				break
			}
		}
		if hasTemplate {
			break
		}
	}

	var semanticOutput semantic.SemanticOutput
	var structuredCmd *semantic.StructuredCommand
	var hierarchicalCmd *semantic.HierarchicalCommand

	if hasTemplate {
		hierarchicalParser := semantic.NewHierarchicalParser()
		hierarchicalCmd = hierarchicalParser.Parse(queryText, words, entityMap)
		semanticOutput = semantic.FillFromHierarchicalCommand(hierarchicalCmd)
	} else {
		parser := semantic.NewCommandParser()
		structuredCmd = parser.Parse(queryText, words, entityMap)

		filler := semantic.NewTemplateFiller()
		var err error
		semanticOutput, err = filler.Fill(intent, entities)
		if err != nil {
			log.Printf("Notice: Falling back to IntentModifyCode for intent '%s': %v", intent, err)
			semanticOutput, _ = filler.Fill(semantic.IntentModifyCode, entities)
		}
	}

	if len(cartPaths) > 1 {
		log.Println("Blending AST JSON sub-keys from multi-expert predictions...")
		if semanticOutput.TargetResource.Properties == nil {
			semanticOutput.TargetResource.Properties = make(map[string]interface{})
		}
		for _, p := range cartPaths {
			if strings.Contains(p, "sql_builder") || strings.Contains(queryText, "database") || strings.Contains(queryText, "sql") {
				semanticOutput.TargetResource.Properties["database"] = "sql"
				if _, hasInject := semanticOutput.TargetResource.Properties["inject_code"]; !hasInject {
					semanticOutput.TargetResource.Properties["inject_code"] = `db, err := sql.Open("sqlite3", "./app.db")`
				}
			}
			if strings.Contains(p, "goroutine_fix") || strings.Contains(queryText, "goroutine") || strings.Contains(queryText, "channel") {
				semanticOutput.TargetResource.Properties["concurrency"] = "sync.WaitGroup"
			}
			if strings.Contains(p, "unit_test") || strings.Contains(queryText, "test") {
				semanticOutput.TargetResource.Properties["test_framework"] = "testing.T"
			}
		}
	}

	for _, w := range words {
		cleanW := strings.Trim(w, "',\".")
		if strings.HasSuffix(cleanW, "_handler") || cleanW == "auth_handler" {
			semanticOutput.TargetResource.Name = cleanW
			if semanticOutput.TargetResource.Properties == nil {
				semanticOutput.TargetResource.Properties = make(map[string]interface{})
			}
			semanticOutput.TargetResource.Properties["handler"] = cleanW
			semanticOutput.TargetResource.Properties["url"] = "/" + cleanW
			funcCode := fmt.Sprintf("package main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n)\n\nfunc %s(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprintf(w, \"Hello from %s!\")\n}\n", cleanW, cleanW)
			semanticOutput.TargetResource.Properties["content"] = funcCode
			break
		}
	}

	jsonBytes, err := json.MarshalIndent(semanticOutput, "", "  ")
	if err != nil {
		log.Fatalf("Failed to marshal JSON: %v", err)
	}

	if hasTemplate && hierarchicalCmd != nil {
		fmt.Println("\n=== Hierarchical Command Tree ===")
		fmt.Println(hierarchicalCmd.String())
		fmt.Println("==================================")
	} else if structuredCmd != nil {
		fmt.Println("\n=== Structured Command Pattern ===")
		fmt.Printf("Action:        %s\n", structuredCmd.Action)
		fmt.Printf("Object Type:   %s\n", structuredCmd.ObjectType)
		fmt.Printf("Name:          %s\n", structuredCmd.Name)
		if structuredCmd.Keyword != "" {
			fmt.Printf("Keyword:       %s\n", structuredCmd.Keyword)
		}
		if structuredCmd.ArgumentType != "" {
			fmt.Printf("Argument Type: %s\n", structuredCmd.ArgumentType)
		}
		if structuredCmd.ArgumentName != "" {
			fmt.Printf("Argument Name: %s\n", structuredCmd.ArgumentName)
		}
		fmt.Printf("\nPattern: %s\n", structuredCmd.String())
		fmt.Println("===================================")
	}

	fmt.Println("\n=== Generated Semantic Output ===")
	fmt.Println(string(jsonBytes))
	fmt.Println("=================================")

	fmt.Println("\n--- Named Entity Recognition (Rule-Based) ---")

	for i, word := range words {

		entityType := entityMap[i]
		fmt.Printf("Word: %s, Type: %s\n", word, entityType)
	}
	fmt.Println("--------------------------------------------")
}

type CustomIntentRegistry struct {
	Intents		map[string]*CustomIntent
	ConfigPath	string
}

// NewCustomIntentRegistry creates a new registry
func NewCustomIntentRegistry(configPath string) *CustomIntentRegistry {
	registry := &CustomIntentRegistry{
		Intents:	make(map[string]*CustomIntent),
		ConfigPath:	configPath,
	}
	registry.Load()
	return registry
}

// Load loads custom intents from the config file
func (r *CustomIntentRegistry) Load() error {
	if _, err := os.Stat(r.ConfigPath); os.IsNotExist(err) {

		return r.Save()
	}

	data, err := os.ReadFile(r.ConfigPath)
	if err != nil {
		return err
	}

	var intents []*CustomIntent
	if err := json.Unmarshal(data, &intents); err != nil {
		return err
	}

	for _, intent := range intents {
		r.Intents[intent.Name] = intent
	}

	return nil
}

// Save saves custom intents to the config file
func (r *CustomIntentRegistry) Save() error {

	dir := filepath.Dir(r.ConfigPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	intents := make([]*CustomIntent, 0, len(r.Intents))
	for _, intent := range r.Intents {
		intents = append(intents, intent)
	}

	data, err := json.MarshalIndent(intents, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(r.ConfigPath, data, 0644)
}

// Add adds a new custom intent
func (r *CustomIntentRegistry) Add(intent *CustomIntent) error {
	r.Intents[intent.Name] = intent
	return r.Save()
}

// Remove removes a custom intent
func (r *CustomIntentRegistry) Remove(name string) error {
	delete(r.Intents, name)
	return r.Save()
}

// Match checks if a query matches any custom intent
func (r *CustomIntentRegistry) Match(query string) *CustomIntent {
	queryLower := strings.ToLower(query)

	for _, intent := range r.Intents {

		keywordMatch := true
		for _, keyword := range intent.Keywords {
			if !strings.Contains(queryLower, strings.ToLower(keyword)) {
				keywordMatch = false
				break
			}
		}

		if keywordMatch {
			return intent
		}

		for _, pattern := range intent.Patterns {
			if strings.Contains(queryLower, strings.ToLower(pattern)) {
				return intent
			}
		}
	}

	return nil
}

// List returns all custom intents
func (r *CustomIntentRegistry) List() []*CustomIntent {
	intents := make([]*CustomIntent, 0, len(r.Intents))
	for _, intent := range r.Intents {
		intents = append(intents, intent)
	}
	return intents
}

// InteractiveCreate guides the user through creating a custom intent
func (r *CustomIntentRegistry) InteractiveCreate(reader interface{ ReadString(byte) (string, error) }) error {
	fmt.Println("\n🎨 Create Custom Intent")
	fmt.Println("========================")

	fmt.Print("Intent name (e.g., 'create_jwt_middleware'): ")
	name, _ := reader.ReadString('\n')
	name = strings.TrimSpace(name)

	if name == "" {
		return fmt.Errorf("intent name cannot be empty")
	}

	fmt.Print("Description: ")
	description, _ := reader.ReadString('\n')
	description = strings.TrimSpace(description)

	fmt.Print("Keywords (comma-separated, e.g., 'jwt,auth,middleware'): ")
	keywordsStr, _ := reader.ReadString('\n')
	keywordsStr = strings.TrimSpace(keywordsStr)
	keywords := strings.Split(keywordsStr, ",")
	for i := range keywords {
		keywords[i] = strings.TrimSpace(keywords[i])
	}

	fmt.Print("Patterns (comma-separated, e.g., 'add jwt,create jwt middleware'): ")
	patternsStr, _ := reader.ReadString('\n')
	patternsStr = strings.TrimSpace(patternsStr)
	patterns := strings.Split(patternsStr, ",")
	for i := range patterns {
		patterns[i] = strings.TrimSpace(patterns[i])
	}

	fmt.Print("Output file path (e.g., 'middleware/jwt.go'): ")
	filePath, _ := reader.ReadString('\n')
	filePath = strings.TrimSpace(filePath)

	fmt.Println("\nHow would you like to provide the code template?")
	fmt.Println("  1. Type code inline")
	fmt.Println("  2. Use a template file from 'learning' directory")
	fmt.Print("Choice (1 or 2): ")
	choice, _ := reader.ReadString('\n')
	choice = strings.TrimSpace(choice)

	var template string

	if choice == "2" {

		learningDir := "examples/learning"
		files, err := os.ReadDir(learningDir)
		if err != nil || len(files) == 0 {
			fmt.Println("⚠️  No template files found in 'learning' directory.")
			fmt.Println("Falling back to inline code entry...")
			choice = "1"
		} else {
			fmt.Println("\n📁 Available template files:")
			for i, file := range files {
				if !file.IsDir() {
					fmt.Printf("  %d. %s\n", i+1, file.Name())
				}
			}
			fmt.Print("\nEnter file number or name: ")
			fileChoice, _ := reader.ReadString('\n')
			fileChoice = strings.TrimSpace(fileChoice)

			var selectedFile string

			if fileNum, err := fmt.Sscanf(fileChoice, "%d", new(int)); err == nil && fileNum == 1 {
				var idx int
				fmt.Sscanf(fileChoice, "%d", &idx)
				if idx > 0 && idx <= len(files) {
					selectedFile = files[idx-1].Name()
				}
			} else {

				selectedFile = fileChoice
			}

			if selectedFile != "" {
				templatePath := filepath.Join(learningDir, selectedFile)
				content, err := os.ReadFile(templatePath)
				if err != nil {
					fmt.Printf("❌ Failed to read template file: %v\n", err)
					fmt.Println("Falling back to inline code entry...")
					choice = "1"
				} else {
					template = string(content)
					fmt.Printf("✅ Loaded template from %s\n", selectedFile)
				}
			} else {
				fmt.Println("Invalid selection. Falling back to inline code entry...")
				choice = "1"
			}
		}
	}

	if choice == "1" {

		fmt.Println("\nEnter code template (type 'END' on a new line to finish):")
		fmt.Println("You can use {{.VariableName}} for placeholders")
		var templateLines []string
		for {
			line, _ := reader.ReadString('\n')
			line = strings.TrimRight(line, "\n")
			if line == "END" {
				break
			}
			templateLines = append(templateLines, line)
		}
		template = strings.Join(templateLines, "\n")
	}

	intent := &CustomIntent{
		Name:		name,
		Description:	description,
		Keywords:	keywords,
		Patterns:	patterns,
		Template:	template,
		FilePath:	filePath,
	}

	if err := r.Add(intent); err != nil {
		return fmt.Errorf("failed to save custom intent: %w", err)
	}

	fmt.Printf("\n✅ Custom intent '%s' created successfully!\n", name)
	return nil
}

// Execute executes a custom intent by generating code from its template
func (r *CustomIntentRegistry) Execute(intent *CustomIntent, projectRoot string, variables map[string]string) error {

	code := intent.Template
	for key, value := range variables {
		placeholder := "{{." + key + "}}"
		code = strings.ReplaceAll(code, placeholder, value)
	}

	outputPath := filepath.Join(projectRoot, intent.FilePath)

	if err := os.MkdirAll(filepath.Dir(outputPath), 0755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}

	if err := os.WriteFile(outputPath, []byte(code), 0644); err != nil {
		return fmt.Errorf("failed to write file: %w", err)
	}

	fmt.Printf("✅ Generated %s\n", outputPath)
	return nil
}

type KnowledgeBase struct {
	BasePath string
}

func NewKnowledgeBase(path string) *KnowledgeBase {
	return &KnowledgeBase{BasePath: path}
}

// FindRelevantFiles searches for files in the learning directory that match the query
func (kb *KnowledgeBase) FindRelevantFiles(query string) ([]string, error) {
	var matches []string

	if _, err := os.Stat(kb.BasePath); os.IsNotExist(err) {
		return matches, nil
	}

	err := filepath.Walk(kb.BasePath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {

			name := strings.ToLower(info.Name())
			queryWords := strings.Fields(strings.ToLower(query))

			score := 0
			for _, word := range queryWords {

				if word == "create" || word == "add" || word == "file" || word == "code" {
					continue
				}
				if strings.Contains(name, word) {
					score++
				}
			}

			if score > 0 {
				matches = append(matches, path)
			}
		}
		return nil
	})

	return matches, err
}

// ReadFileContent reads the content of a learned file
func (kb *KnowledgeBase) ReadFileContent(path string) (string, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(content), nil
}

// NewLLMClient initializes the LLM client by loading the model and vocabularies
func NewLLMClient(vocabPath, outputVocabPath, modelPath string) (*LLMClient, error) {

	vocabulary, err := mainvocab.LoadVocabulary(vocabPath)
	if err != nil {
		return nil, fmt.Errorf("failed to load input vocabulary: %w", err)
	}

	semanticOutputVocabulary, err := mainvocab.LoadVocabulary(outputVocabPath)
	if err != nil {
		return nil, fmt.Errorf("failed to load semantic output vocabulary: %w", err)
	}

	tok, err := tokenizer.NewTokenizer(vocabulary)
	if err != nil {
		return nil, fmt.Errorf("failed to create tokenizer: %w", err)
	}

	semanticOutputTokenizer, err := tokenizer.NewTokenizer(semanticOutputVocabulary)
	if err != nil {
		return nil, fmt.Errorf("failed to create semantic output tokenizer: %w", err)
	}

	model, err := moe.LoadIntentMoEModelWithFallback(modelPath)
	if err != nil {
		return nil, fmt.Errorf("failed to load MoE model: %w", err)
	}

	if vocabulary.Size() > model.Embedding.VocabSize {
		model.ResizeEmbeddings(vocabulary.Size())
	}
	if semanticOutputVocabulary.Size() > model.SentenceVocabSize {
		model.Decoder.ResizeOutputLayer(semanticOutputVocabulary.Size())
		model.SentenceVocabSize = semanticOutputVocabulary.Size()
	}

	return &LLMClient{
		model:				model,
		tokenizer:			tok,
		semanticOutputTokenizer:	semanticOutputTokenizer,
		vocabulary:			vocabulary,
		semanticOutputVocabulary:	semanticOutputVocabulary,
	}, nil
}

// Query sends a text query to the model and returns the generated response
func (c *LLMClient) Query(input string) (string, error) {
	input = strings.TrimSpace(input)
	if input == "" {
		return "", fmt.Errorf("empty input")
	}

	tokenIDs, err := c.tokenizer.Encode(input)
	if err != nil {
		return "", fmt.Errorf("failed to encode query: %w", err)
	}

	maxSeqLength := 32
	if len(tokenIDs) > maxSeqLength {
		tokenIDs = tokenIDs[:maxSeqLength]
	} else {
		for len(tokenIDs) < maxSeqLength {
			tokenIDs = append(tokenIDs, c.vocabulary.PaddingTokenID)
		}
	}

	inputData := make([]float32, len(tokenIDs))
	for i, id := range tokenIDs {
		inputData[i] = float32(id)
	}
	inputTensor := tensor.NewTensor([]int{1, len(inputData)}, inputData, false)

	dummyTargetTokenIDs := make([]float32, maxSeqLength)
	for i := range maxSeqLength {
		dummyTargetTokenIDs[i] = float32(c.semanticOutputVocabulary.PaddingTokenID)
	}
	dummyTargetTensor := tensor.NewTensor([]int{1, maxSeqLength}, dummyTargetTokenIDs, false)

	_, contextVector, err := c.model.Forward(0.0, inputTensor, dummyTargetTensor)
	if err != nil {
		return "", fmt.Errorf("model forward pass failed: %w", err)
	}

	sosID := c.semanticOutputVocabulary.GetTokenID("<s>")
	eosID := c.semanticOutputVocabulary.GetTokenID("</s>")
	predictedIDs, err := c.model.GreedySearchDecode(contextVector, maxSeqLength, sosID, eosID, 1.2, 0.0, 100, tag.Tag{})
	if err != nil {
		return "", fmt.Errorf("greedy search decode failed: %w", err)
	}

	predictedSentence, err := c.semanticOutputTokenizer.Decode(predictedIDs)
	if err != nil {
		return "", fmt.Errorf("failed to decode predicted IDs: %w", err)
	}

	return predictedSentence, nil
}

