type IntentTrainingExample struct {
	Query		string	`json:"query"`
	SemanticOutput	struct {
		Social struct {
			Intent		string	`json:"intent"`
			SubIntent	string	`json:"sub_intent"`
		} `json:"social"`
	}	`json:"semantic_output"`
}

type TaggedTrainingExample struct {
	Query	string		`json:"query"`
	Intent	string		`json:"intent"`
	Tokens	[]string	`json:"tokens"`
	Tags	[]string	`json:"tags"`	// IOB format (Inside, Outside, Beginning)
}

// LoadIntentTrainingData loads the intent training data from a JSON file.
func LoadIntentTrainingData(filePath string) (*IntentTrainingData, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open training data file %s: %w", filePath, err)
	}
	defer file.Close()

	bytes, err := io.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read training data file %s: %w", filePath, err)
	}

	var data IntentTrainingData
	err = json.Unmarshal(bytes, &data)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal training data JSON from %s: %w", filePath, err)
	}

	return &data, nil
}

func main() {
	const intentDataPath = "data/training/tiny_chat.json"
	const taggedDataPath = "data/training/trainingdata/tagged_training_data.json"

	trainingData, err := LoadIntentTrainingData(intentDataPath)
	if err != nil {
		log.Fatalf("Failed to load training data: %v", err)
	}

	var taggedTrainingData []TaggedTrainingExample

	for _, example := range *trainingData {
		tokens := tokenizer.Tokenize(example.Query)
		tags := make([]string, len(tokens))
		for i := range tags {
			tags[i] = "O"
		}

		intent := example.SemanticOutput.Social.Intent
		if intent == "" {
			intent = "social"
		}

		taggedExample := TaggedTrainingExample{
			Query:	example.Query,
			Intent:	intent,
			Tokens:	tokens,
			Tags:	tags,
		}
		taggedTrainingData = append(taggedTrainingData, taggedExample)
	}

	file, err := os.Create(taggedDataPath)
	if err != nil {
		log.Fatalf("Failed to create tagged training data file: %v", err)
	}
	defer file.Close()

	encoder := json.NewEncoder(file)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(taggedTrainingData); err != nil {
		log.Fatalf("Failed to encode tagged training data: %v", err)
	}

	log.Printf("Successfully converted %d examples to tagged format.", len(taggedTrainingData))
}

func main() {
	modelPath := "data/models/gob_models/moe_social_model.gob"
	ckpt, err := moe.LoadIntentMoECheckpoint(modelPath)
	if err != nil {
		log.Fatalf("Failed to load: %v", err)
	}

	targetExperts := 16

	layers := append(ckpt.Model.Encoder.GetMoELayers(), ckpt.Model.Decoder.OutputMoE)
	for i, l := range layers {
		if len(l.Experts) > targetExperts {
			fmt.Printf("Pruning Layer %d from %d to %d experts\n", i, len(l.Experts), targetExperts)
			l.Experts = l.Experts[:targetExperts]
			if l.ExpertOutputScale != nil && len(l.ExpertOutputScale) > targetExperts {
				l.ExpertOutputScale = l.ExpertOutputScale[:targetExperts]
			}

			if l.AccumulatedUtilization != nil && len(l.AccumulatedUtilization) > targetExperts {
				l.AccumulatedUtilization = l.AccumulatedUtilization[:targetExperts]
			}

			if l.StepRoutingBias != nil {
				for k, arr := range l.StepRoutingBias {
					if len(arr) > targetExperts {
						l.StepRoutingBias[k] = arr[:targetExperts]
					}
				}
			}

			if l.GatingNetwork != nil && l.GatingNetwork.Linear != nil && l.GatingNetwork.Linear.Weights != nil {
				oldWeights := l.GatingNetwork.Linear.Weights
				inputDim := oldWeights.Shape[0]
				oldNumExperts := oldWeights.Shape[1]

				newWeights := tensor.NewTensor([]int{inputDim, targetExperts}, make([]float32, inputDim*targetExperts), true)
				for d := 0; d < inputDim; d++ {
					for e := 0; e < targetExperts; e++ {
						newWeights.Data[d*targetExperts+e] = oldWeights.Data[d*oldNumExperts+e]
					}
				}
				l.GatingNetwork.Linear.Weights = newWeights
			}
		}
	}

	ckpt.Model.RebuildActiveLayers()

	runtime.GC()
	debug.FreeOSMemory()

	if err := moe.SaveIntentMoECheckpoint(ckpt, modelPath); err != nil {
		log.Fatalf("Failed to save: %v", err)
	}
	fmt.Println("Model pruned successfully!")
}

