	cmd := exec.Command("ffmpeg",
		"-y",
		"-f", "alsa", "-i", "default",
		"-t", "1.5",
		"-ac", "1", "-ar", "16000",
		"-f", "s16le", filename,
	)

	err := cmd.Run()
	if err != nil {
		fmt.Printf("❌ Failed to record: %v\n", err)
		return
	}

	fmt.Printf("✅ Saved to %s\n\n", filename)
	fmt.Println("Record 3-5 samples per intent for good accuracy.")
}

// This tool reads a list of commands from a text file and automatically
// prompts the user to record each one 3 times.
func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run cmd/tools/record_batch/main.go <commands_file.txt>")
		fmt.Println("Create a simple text file with one command per line.")
		return
	}

	filepath := os.Args[1]
	file, err := os.Open(filepath)
	if err != nil {
		fmt.Printf("❌ Could not open file: %v\n", err)
		return
	}
	defer file.Close()

	os.MkdirAll("dataset/audio", 0755)

	var commands []string
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" && !strings.HasPrefix(line, "#") {
			commands = append(commands, line)
		}
	}

	if len(commands) == 0 {
		fmt.Println("⚠️ No commands found in file.")
		return
	}

	fmt.Printf("🚀 Loaded %d commands to record.\n", len(commands))
	fmt.Println("We will record 3 samples for each command.")
	fmt.Println("Press [ENTER] when you are ready to begin...")
	bufio.NewReader(os.Stdin).ReadBytes('\n')

	for _, cmdStr := range commands {

		intent := strings.ToUpper(strings.ReplaceAll(cmdStr, " ", "_"))

		fmt.Printf("\n==========================================\n")
		fmt.Printf("🎙️  NEW COMMAND: '%s'\n", cmdStr)
		fmt.Printf("==========================================\n")

		for sampleNum := 1; sampleNum <= 3; sampleNum++ {
			fmt.Printf("\nGet ready to say '%s' (Sample %d of 3)...\n", cmdStr, sampleNum)
			fmt.Println("Press [ENTER] to start recording...")
			bufio.NewReader(os.Stdin).ReadBytes('\n')

			filename := fmt.Sprintf("dataset/audio/%s_%d.raw", intent, sampleNum)

			fmt.Println("🔴 RECORDING NOW (3.5 seconds)...")

			cmd := exec.Command("ffmpeg",
				"-y",
				"-f", "alsa", "-i", "default",
				"-t", "3.5",
				"-ac", "1", "-ar", "16000",
				"-f", "s16le", filename,
			)

			err := cmd.Run()
			if err != nil {
				fmt.Printf("❌ Failed to record: %v\n", err)
				return
			}

			fmt.Printf("✅ Saved to %s\n", filename)
			time.Sleep(500 * time.Millisecond)
		}
	}

	fmt.Printf("\n🎉 All %d commands recorded successfully!\n", len(commands))
	fmt.Println("You can now run 'go run cmd/tools/train_audio/main.go' to train the network.")
}

func main() {
	sourceFile := "internal/ai/training/chat/chat.go"
	file, err := os.Open(sourceFile)
	if err != nil {
		fmt.Println("Error opening chat.go:", err)
		return
	}
	defer file.Close()

	var lines []string
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	extractedCode := make(map[string][]string)
	for k := range targets {
		extractedCode[k] = []string{}
	}

	var remainingLines []string

	i := 0
	for i < len(lines) {
		matched := false
		for targetFile, patterns := range targets {
			for _, p := range patterns {
				if strings.HasPrefix(lines[i], p) {

					block, endIdx := extractBlock(lines, i)
					extractedCode[targetFile] = append(extractedCode[targetFile], block...)
					extractedCode[targetFile] = append(extractedCode[targetFile], "")
					i = endIdx
					matched = true
					break
				}
			}
			if matched {
				break
			}
		}

		if !matched {
			remainingLines = append(remainingLines, lines[i])
		}
		i++
	}

	for targetFile, code := range extractedCode {
		if len(code) > 0 {
			f, err := os.Create("internal/ai/training/chat/" + targetFile)
			if err != nil {
				fmt.Println("Error creating", targetFile, ":", err)
				return
			}
			f.WriteString("package chat\n\n")
			for _, line := range code {
				f.WriteString(line + "\n")
			}
			f.Close()
		}
	}

	f, err := os.Create(sourceFile)
	if err != nil {
		fmt.Println("Error writing chat.go:", err)
		return
	}
	for _, line := range remainingLines {
		f.WriteString(line + "\n")
	}
	f.Close()

	fmt.Println("Refactoring complete.")
}

func extractBlock(lines []string, startIdx int) ([]string, int) {
	var block []string
	openBraces := 0
	inBlock := false

	for i := startIdx; i < len(lines); i++ {
		line := lines[i]
		block = append(block, line)

		openBraces += strings.Count(line, "{")
		openBraces -= strings.Count(line, "}")

		if strings.Contains(line, "{") {
			inBlock = true
		}

		if inBlock && openBraces == 0 {
			return block, i
		}
	}

	return block, len(lines) - 1
}

