// computeEmbedding reads a raw s16le file and returns the GRU motion vector.
func computeEmbedding(rawFile string, ae *moe.AudioEncoder, te *moe.TemporalEncoder) ([]float32, error) {
	rawBytes, err := os.ReadFile(rawFile)
	if err != nil {
		return nil, fmt.Errorf("read raw: %w", err)
	}

	samples := make([]float32, len(rawBytes)/2)
	for i := range samples {
		s16 := int16(rawBytes[i*2]) | int16(rawBytes[i*2+1])<<8
		samples[i] = float32(s16) / 32768.0
	}

	if len(samples) > numSamples {
		bestStart, bestEnergy := 0, float32(0)
		for start := 0; start <= len(samples)-numSamples; start += frameSize {
			var energy float32
			for _, s := range samples[start : start+numSamples] {
				energy += s * s
			}
			if energy > bestEnergy {
				bestEnergy = energy
				bestStart = start
			}
		}
		samples = samples[bestStart : bestStart+numSamples]
	} else if len(samples) < numSamples {
		padded := make([]float32, numSamples)
		copy(padded, samples)
		samples = padded
	}

	numFrames := len(samples) / frameSize
	frames := make([][]float32, numFrames)
	for i := range frames {
		frames[i] = samples[i*frameSize : (i+1)*frameSize]
	}

	audioTokens := ae.Forward(frames)
	motionVec := te.Forward(audioTokens)
	return motionVec, nil
}

// cleanTranscript turns Whisper output like " Who are you?" into "WHO_ARE_YOU"
func cleanTranscript(text string) string {
	text = strings.ToUpper(strings.TrimSpace(text))
	for _, ch := range []string{".", ",", "?", "!", "'", "\"", "(", ")", "[", "]", "-"} {
		text = strings.ReplaceAll(text, ch, "")
	}

	fields := strings.Fields(text)
	return strings.Join(fields, "_")
}

// cosineSim computes cosine similarity between two vectors.
func cosineSim(a, b []float32) float32 {
	var dot, na, nb float64
	for i := range a {
		dot += float64(a[i]) * float64(b[i])
		na += float64(a[i]) * float64(a[i])
		nb += float64(b[i]) * float64(b[i])
	}
	if na == 0 || nb == 0 {
		return 0
	}
	return float32(dot / (math.Sqrt(na) * math.Sqrt(nb)))
}

func findWhisperBinaryAndModel() (string, string, error) {
	var checked []string
	if envBin := os.Getenv("WHISPER_CLI_BIN"); envBin != "" {
		checked = append(checked, envBin)
		if _, err := os.Stat(envBin); err == nil {
			if envModel := os.Getenv("WHISPER_MODEL_PATH"); envModel != "" {
				checked = append(checked, envModel)
				return envBin, envModel, nil
			}
			if modelPath, ok := resolveWhisperModelPath(envBin); ok {
				return envBin, modelPath, nil
			}
		}
	}

	candidateBins := []string{
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "whisper-cli"),
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "whisper"),
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "main"),
		"/tmp/whisper.cpp/build/bin/whisper-cli",
		"/tmp/whisper.cpp/build/bin/whisper",
		"/tmp/whisper.cpp/build/bin/main",
	}

	for _, bin := range candidateBins {
		checked = append(checked, bin)
		if _, err := os.Stat(bin); err == nil {
			if modelPath, ok := resolveWhisperModelPath(bin); ok {
				return bin, modelPath, nil
			}
		}
	}

	for _, binaryName := range []string{"whisper-cli", "whisper", "main"} {
		if bin, err := exec.LookPath(binaryName); err == nil {
			checked = append(checked, bin)
			if modelPath, ok := resolveWhisperModelPath(bin); ok {
				return bin, modelPath, nil
			}
		}
	}

	return "", "", fmt.Errorf("whisper binary/model not found; checked: %s; set WHISPER_CLI_BIN and WHISPER_MODEL_PATH to override; or run build_voice.sh to build whisper.cpp and download ggml-tiny.en.bin", strings.Join(checked, ", "))
}

func resolveWhisperModelPath(bin string) (string, bool) {
	candidateModels := []string{
		filepath.Join(filepath.Dir(bin), "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(bin), "..", "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(filepath.Dir(bin)), "..", "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(filepath.Dir(filepath.Dir(bin))), "models", "ggml-tiny.en.bin"),
		filepath.Join("build_whisper", "whisper.cpp", "models", "ggml-tiny.en.bin"),
		filepath.Join("models", "ggml-tiny.en.bin"),
		filepath.Join("/tmp", "whisper.cpp", "models", "ggml-tiny.en.bin"),
	}

	if home, err := os.UserHomeDir(); err == nil {
		candidateModels = append(candidateModels,
			filepath.Join(home, ".cache", "whisper", "ggml-tiny.en.bin"),
			filepath.Join(home, ".cache", "whisper.cpp", "ggml-tiny.en.bin"),
			filepath.Join(home, ".cache", "whisper.cpp", "models", "ggml-tiny.en.bin"),
		)
	}

	for _, modelPath := range candidateModels {
		modelPath = filepath.Clean(modelPath)
		if _, err := os.Stat(modelPath); err == nil {
			return modelPath, true
		}
	}
	return "", false
}

func main() {
	fmt.Println("🎓 Gollemer Whisper Teacher — Knowledge Distillation Mode")
	fmt.Println("==========================================================")
	fmt.Println("Speak naturally. Whisper transcribes your voice, then Gollemer")
	fmt.Println("learns the acoustic pattern for that exact phrase automatically.")
	fmt.Println()

	whisperBin, whisperModel, err := findWhisperBinaryAndModel()
	if err != nil {
		fmt.Println("❌", err)
		os.Exit(1)
	}

	ae, te, headW, headB, classNames, prototypes, err := moe.LoadAudioModel(modelPath)
	if err != nil {
		fmt.Printf("❌ Failed to load %s: %v\n", modelPath, err)
		os.Exit(1)
	}
	if prototypes == nil {
		prototypes = make(map[string][]float32)
	}
	fmt.Printf("✅ Loaded audio model (%d commands)\n\n", len(classNames))

	os.MkdirAll(datasetDir, 0755)
	reader := bufio.NewReader(os.Stdin)

	for {
		fmt.Println("─────────────────────────────────────────────")
		fmt.Print("Press [ENTER] to record (or type 'quit' to exit): ")
		line, _ := reader.ReadString('\n')
		if strings.TrimSpace(strings.ToLower(line)) == "quit" {
			fmt.Println("👋 Exiting teacher.")
			break
		}

		wavFile := datasetDir + "/teacher_temp.wav"
		rawFile := datasetDir + "/teacher_temp.raw"

		fmt.Printf("🔴 Recording %.1ss — speak now!\n", recordSecs)
		recCmd := exec.Command("ffmpeg",
			"-y", "-f", "alsa", "-i", "default",
			"-t", recordSecs,
			"-ac", "1", "-ar", "16000",
			wavFile,
		)
		recCmd.Stderr = nil
		if err := recCmd.Run(); err != nil {
			fmt.Printf("❌ ffmpeg error: %v\n", err)
			continue
		}

		fmt.Println("🔬 Transcribing with Whisper...")

		devNull, _ := os.Open(os.DevNull)
		defer devNull.Close()
		wCmd := exec.Command(whisperBin, "-m", whisperModel, "-f", wavFile, "-nt")
		wCmd.Stderr = devNull
		stdout, err := wCmd.Output()
		if err != nil {
			fmt.Printf("⚠️  Whisper returned error (may still have transcript): %v\n", err)
		}

		// Stdout is now ONLY the transcript lines — no debug noise
		var transcriptParts []string
		for _, raw := range strings.Split(string(stdout), "\n") {
			trimmed := strings.TrimSpace(raw)
			if trimmed == "" {
				continue
			}
			transcriptParts = append(transcriptParts, trimmed)
		}
		rawTranscript := strings.Join(transcriptParts, " ")
		intent := cleanTranscript(rawTranscript)

		if intent == "" {
			fmt.Println("⚠️  Whisper heard nothing useful. Try again, speaking louder.")
			continue
		}

		fmt.Printf("🧠 Whisper heard: \"%s\"\n", rawTranscript)
		fmt.Printf("🏷️  Intent label:  %s\n", intent)

		convCmd := exec.Command("ffmpeg",
			"-y", "-i", wavFile,
			"-f", "s16le", "-ac", "1", "-ar", "16000",
			rawFile,
		)
		convCmd.Stderr = nil
		convCmd.Run()

		emb, err := computeEmbedding(rawFile, ae, te)
		if err != nil {
			fmt.Printf("❌ Embedding error: %v\n", err)
			continue
		}

		if existing, ok := prototypes[intent]; ok {
			sim := cosineSim(existing, emb)
			fmt.Printf("📐 Similarity to existing prototype: %.1f%%\n", sim*100)
		}

		if existing, ok := prototypes[intent]; ok {
			averaged := make([]float32, len(emb))
			for i := range emb {
				averaged[i] = (existing[i] + emb[i]) * 0.5
			}
			prototypes[intent] = averaged
		} else {
			prototypes[intent] = emb

			classNames = append(classNames, intent)
			fmt.Printf("🆕 New command added: %s\n", intent)
		}

		if err := moe.SaveAudioModel(modelPath, ae, te, headW, headB, classNames, prototypes); err != nil {
			fmt.Printf("❌ Save failed: %v\n", err)
			continue
		}

		finalRaw := fmt.Sprintf("%s/%s_%d.raw", datasetDir, intent, time.Now().Unix())
		os.Rename(rawFile, finalRaw)

		fmt.Printf("✅ Gollemer now knows: \"%s\" → %s\n", rawTranscript, intent)
		fmt.Printf("   (Saved to %s)\n", finalRaw)
	}

	fmt.Printf("\n📊 Final command vocabulary (%d commands):\n", len(classNames))
	for i, name := range classNames {
		fmt.Printf("   %2d. %s\n", i+1, name)
	}
}

// GenerateSineWave generates a pure tone at a specific frequency
func GenerateSineWave(frequency float64) []float32 {
	samples := make([]float32, NumSamples)
	for i := 0; i < NumSamples; i++ {
		t := float64(i) / float64(SampleRate)
		samples[i] = float32(math.Sin(2 * math.Pi * frequency * t))
	}
	return samples
}

// GenerateWhiteNoise generates random noise (silence/background noise simulation)
func GenerateWhiteNoise() []float32 {
	samples := make([]float32, NumSamples)
	for i := 0; i < NumSamples; i++ {
		samples[i] = rand.Float32()*2 - 1
	}
	return samples
}

// ChunkAudio breaks a continuous audio buffer into smaller frames
func ChunkAudio(samples []float32, frameSize int) [][]float32 {
	numFrames := len(samples) / frameSize
	frames := make([][]float32, numFrames)
	for i := 0; i < numFrames; i++ {
		frames[i] = samples[i*frameSize : (i+1)*frameSize]
	}
	return frames
}

func softmax(logits []float32) []float32 {
	out := make([]float32, len(logits))
	maxV := logits[0]
	for _, v := range logits {
		if v > maxV {
			maxV = v
		}
	}
	var sum float32
	for i, v := range logits {
		out[i] = float32(math.Exp(float64(v - maxV)))
		sum += out[i]
	}
	for i := range out {
		out[i] /= sum
	}
	return out
}

func main() {
	fmt.Println("Initialising Temporal Audio Training…")
	fmt.Println("Classes: 0=LOW_PITCH(440Hz)  1=HIGH_PITCH(880Hz)  2=NOISE")
	fmt.Println()

	inputDim := FrameSize
	audioFeatureDim := 64
	gruHiddenDim := 32

	ae := moe.NewAudioEncoder(inputDim, audioFeatureDim)
	te := moe.NewTemporalEncoder(audioFeatureDim, gruHiddenDim)

	// ── Dataset ──────────────────────────────────────────────────────────────
	type sample struct {
		frames		[][]float32
		targetClass	int
		label		string
	}

	var dataset []sample
	var classNames []string
	classMap := make(map[string]int)

	files, err := os.ReadDir("dataset/audio")
	if err == nil && len(files) > 0 {
		fmt.Println("Loading real voice samples from dataset/audio/...")
		for _, f := range files {
			if strings.HasSuffix(f.Name(), ".raw") {

				parts := strings.Split(f.Name(), "_")
				if len(parts) < 2 {
					continue
				}

				intentName := strings.Join(parts[:len(parts)-1], "_")

				if _, exists := classMap[intentName]; !exists {
					classMap[intentName] = len(classNames)
					classNames = append(classNames, intentName)
				}
				classIdx := classMap[intentName]

				rawBytes, err := os.ReadFile("dataset/audio/" + f.Name())
				if err == nil {
					samples := make([]float32, len(rawBytes)/2)
					maxAmp := float32(0)
					for i := 0; i < len(samples); i++ {
						sample16 := int16(binary.LittleEndian.Uint16(rawBytes[i*2 : i*2+2]))
						v := float32(sample16) / 32768.0
						samples[i] = v
						if math.Abs(float64(v)) > float64(maxAmp) {
							maxAmp = float32(math.Abs(float64(v)))
						}
					}
					fmt.Printf("Loaded %s (Max Amplitude: %.4f)\n", f.Name(), maxAmp)

					targetSamples := 16000
					if len(samples) > targetSamples {
						bestStart := 0
						bestEnergy := float32(0)
						for start := 0; start <= len(samples)-targetSamples; start += 400 {
							var energy float32
							for j := 0; j < targetSamples; j++ {
								energy += samples[start+j] * samples[start+j]
							}
							if energy > bestEnergy {
								bestEnergy = energy
								bestStart = start
							}
						}
						samples = samples[bestStart : bestStart+targetSamples]
					} else {
						padded := make([]float32, targetSamples)
						copy(padded, samples)
						samples = padded
					}

					dataset = append(dataset, sample{
						frames:		ChunkAudio(samples, FrameSize),
						targetClass:	classIdx,
						label:		intentName,
					})
				}
			}
		}
	}

	if len(dataset) == 0 {
		fmt.Println("No real audio found. Using synthetic frequency samples.")
		classNames = []string{"LOW_PITCH", "HIGH_PITCH", "NOISE"}
		dataset = []sample{
			{ChunkAudio(GenerateSineWave(440), FrameSize), 0, "LOW_PITCH"},
			{ChunkAudio(GenerateSineWave(880), FrameSize), 1, "HIGH_PITCH"},
			{ChunkAudio(GenerateWhiteNoise(), FrameSize), 2, "NOISE"},
		}
	}

	classCounts := make(map[int]int)
	maxCount := 0
	for _, s := range dataset {
		classCounts[s.targetClass]++
		if classCounts[s.targetClass] > maxCount {
			maxCount = classCounts[s.targetClass]
		}
	}

	var balancedDataset []sample
	for classIdx, count := range classCounts {
		// Find all samples of this class
		var classSamples []sample
		for _, s := range dataset {
			if s.targetClass == classIdx {
				classSamples = append(classSamples, s)
			}
		}

		for i := 0; i < maxCount; i++ {
			balancedDataset = append(balancedDataset, classSamples[i%count])
		}
	}
	dataset = balancedDataset

	numClasses := len(classNames)
	fmt.Printf("Dataset prepared: %d balanced samples across %d intents.\n\n", len(dataset), numClasses)

	headW := make([]float32, numClasses*gruHiddenDim)
	headB := make([]float32, numClasses)
	limit := float32(math.Sqrt(1.0 / float64(gruHiddenDim)))
	for i := range headW {
		headW[i] = (rand.Float32()*2.0 - 1.0) * limit
	}

	headGradW := make([]float32, len(headW))
	headGradB := make([]float32, len(headB))

	epochs := 2500
	lr := float32(0.001)

	for epoch := 1; epoch <= epochs; epoch++ {
		totalLoss := float32(0)

		for _, s := range dataset {

			audioTokens := ae.Forward(s.frames)

			motionVec := te.Forward(audioTokens)

			logits := make([]float32, numClasses)
			for c := 0; c < numClasses; c++ {
				for d := 0; d < gruHiddenDim; d++ {
					logits[c] += headW[c*gruHiddenDim+d] * motionVec[d]
				}
				logits[c] += headB[c]
			}

			probs := softmax(logits)
			loss, dLogits := crossEntropyLoss(probs, s.targetClass)
			totalLoss += loss

			for i := range headGradW {
				headGradW[i] = 0
			}
			for i := range headGradB {
				headGradB[i] = 0
			}

			dMotion := make([]float32, gruHiddenDim)
			for c := 0; c < numClasses; c++ {
				for d := 0; d < gruHiddenDim; d++ {
					headGradW[c*gruHiddenDim+d] = dLogits[c] * motionVec[d]
					dMotion[d] += headW[c*gruHiddenDim+d] * dLogits[c]
				}
				headGradB[c] = dLogits[c]
			}

			dAudioTokens := te.Backward(dMotion, lr)

			ae.Backward(s.frames, dAudioTokens, lr)

			for i := range headW {
				headW[i] -= lr * headGradW[i]
			}
			for i := range headB {
				headB[i] -= lr * headGradB[i]
			}
		}

		if epoch%20 == 0 {
			fmt.Printf("Epoch %3d/%d  avg-loss=%.4f\n", epoch, epochs, totalLoss/float32(len(dataset)))
		}
	}

	fmt.Println()
	fmt.Println("─── Final Evaluation ───")
	correct := 0
	for _, s := range dataset {
		audioTokens := ae.Forward(s.frames)
		motionVec := te.Forward(audioTokens)

		logits := make([]float32, numClasses)
		for c := 0; c < numClasses; c++ {
			for d := 0; d < gruHiddenDim; d++ {
				logits[c] += headW[c*gruHiddenDim+d] * motionVec[d]
			}
			logits[c] += headB[c]
		}

		probs := softmax(logits)
		pred := 0
		for c := 1; c < numClasses; c++ {
			if probs[c] > probs[pred] {
				pred = c
			}
		}

		status := "✗"
		if pred == s.targetClass {
			correct++
			status = "✓"
		}
		fmt.Printf("  %s  Ground-truth=%-20s  Predicted=%-12s  Confidence=%.1f%%\n",
			status, s.label, classNames[pred], probs[pred]*100)
	}
	fmt.Printf("\nAccuracy: %d/%d (%.0f%%)\n", correct, len(dataset), float64(correct)/float64(len(dataset))*100)

	prototypes := make(map[string][]float32)
	protoCounts := make(map[string]int)
	for _, s := range dataset {
		audioTokens := ae.Forward(s.frames)
		emb := te.Forward(audioTokens)

		if prototypes[s.label] == nil {
			prototypes[s.label] = make([]float32, gruHiddenDim)
		}
		for d := 0; d < gruHiddenDim; d++ {
			prototypes[s.label][d] += emb[d]
		}
		protoCounts[s.label]++
	}

	for label, vec := range prototypes {
		count := float32(protoCounts[label])
		for d := range vec {
			vec[d] /= count
		}
	}
	fmt.Printf("✅ Computed %d prototype embeddings.\n", len(prototypes))

	os.MkdirAll("models", 0755)
	err = moe.SaveAudioModel("models/audio_gru.json", ae, te, headW, headB, classNames, prototypes)
	if err != nil {
		fmt.Printf("Failed to save audio model: %v\n", err)
	} else {
		fmt.Println("✅ Saved trained audio model to models/audio_gru.json")
		fmt.Println()
		fmt.Println("💡 To add a NEW command without retraining, run:")
		fmt.Println("   go run cmd/tools/add_command/main.go \"YOUR NEW COMMAND\"")
	}
}

