		fmt.Println("Use -interactive to teach the agent new error patterns.")
		os.Exit(1)
	}

	db := loadTrainingData(*trainDataPath)

	fmt.Printf("🔍 Analyzing %s...\n", *filePath)
	vetOut, _ := exec.Command("go", "vet", *filePath).CombinedOutput()
	vetStr := strings.TrimSpace(string(vetOut))

	if vetStr == "" {
		fmt.Println("✅ No errors found in file.")
		return
	}

	content, _ := os.ReadFile(*filePath)
	_, parseErr := parser.ParseFile(token.NewFileSet(), *filePath, content, parser.ParseComments)
	parseStr := ""
	if parseErr != nil {
		parseStr = parseErr.Error()
	}

	fmt.Printf("⚠️  Found errors:\n")
	if parseStr != "" {
		fmt.Printf("  📝 Parse error: %s\n", parseStr)
	}
	fmt.Printf("  🔧 Go vet: %s\n", vetStr)

	allErrors := vetStr
	if parseStr != "" {
		allErrors = parseStr + "\n" + vetStr
	}

	matches := findMatchingPatterns(db, allErrors)
	if len(matches) > 0 {
		fmt.Printf("\n✅ Matched %d existing patterns:\n", len(matches))
		for _, m := range matches {
			fmt.Printf("  - [%s] %s (confidence: %.0f%%)\n", m.ID, m.Description, m.Confidence*100)
		}
	} else {
		fmt.Println("\n❌ No matching patterns found in training data.")
	}

	unmatched := findUnmatchedErrors(allErrors, db)
	if len(unmatched) > 0 {
		fmt.Printf("\n📋 Unmatched error messages (%d):\n", len(unmatched))
		for _, e := range unmatched {
			fmt.Printf("  - %s\n", e)
		}

		if *interactive {
			teachNewPatterns(*trainDataPath, db, unmatched)
		} else {
			fmt.Println("\n💡 Run with -interactive to teach the agent new patterns.")
		}
	}

	fmt.Printf("\n📊 Training data: %d patterns in %s\n", len(db.Patterns), *trainDataPath)
}

// loadTrainingData loads the error pattern training data from a JSON file
func loadTrainingData(path string) *ErrorPatternsDB {
	data, err := os.ReadFile(path)
	if err != nil {
		fmt.Printf("⚠️  Could not load training data from %s: %v\n", path, err)
		return &ErrorPatternsDB{Version: 1, Patterns: []ErrorPattern{}}
	}

	var db ErrorPatternsDB
	if err := json.Unmarshal(data, &db); err != nil {
		fmt.Printf("⚠️  Could not parse training data: %v\n", err)
		return &ErrorPatternsDB{Version: 1, Patterns: []ErrorPattern{}}
	}

	return &db
}

// findMatchingPatterns finds all patterns that match the given error string
func findMatchingPatterns(db *ErrorPatternsDB, errStr string) []ErrorPattern {
	var matches []ErrorPattern
	lower := strings.ToLower(errStr)
	for _, p := range db.Patterns {
		if strings.Contains(lower, strings.ToLower(p.Match)) {
			matches = append(matches, p)
		}
	}
	return matches
}

// findUnmatchedErrors extracts error messages that don't match any pattern
func findUnmatchedErrors(errStr string, db *ErrorPatternsDB) []string {
	lower := strings.ToLower(errStr)
	lines := strings.Split(errStr, "\n")
	var unmatched []string

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		if strings.HasPrefix(line, "# ") || strings.HasPrefix(line, "[") {
			continue
		}

		matched := false
		for _, p := range db.Patterns {
			if strings.Contains(lower, strings.ToLower(p.Match)) {
				matched = true
				break
			}
		}
		if !matched {
			unmatched = append(unmatched, line)
		}
	}

	return unmatched
}

// teachNewPatterns interactively teaches the agent new error patterns
func teachNewPatterns(path string, db *ErrorPatternsDB, unmatched []string) {
	reader := bufio.NewReader(os.Stdin)

	for _, errMsg := range unmatched {
		fmt.Printf("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")
		fmt.Printf("🧠 Teach a new pattern for:\n")
		fmt.Printf("   %s\n", errMsg)
		fmt.Printf("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")

		fmt.Print("Enter a short ID (e.g., 'missing_brace_custom'): ")
		id, _ := reader.ReadString('\n')
		id = strings.TrimSpace(id)
		if id == "" {
			fmt.Println("  ⏭️  Skipped.")
			continue
		}

		fmt.Print("Enter the match string (substring to match in error): ")
		matchStr, _ := reader.ReadString('\n')
		matchStr = strings.TrimSpace(matchStr)
		if matchStr == "" {
			matchStr = extractMatchKey(errMsg)
			fmt.Printf("  Using auto-extracted: '%s'\n", matchStr)
		}

		fmt.Print("Enter a description: ")
		desc, _ := reader.ReadString('\n')
		desc = strings.TrimSpace(desc)
		if desc == "" {
			desc = "Auto-trained pattern for: " + matchStr
		}

		fmt.Print("Enter fix_type (add_brace_after_func, remove_duplicate_type, add_closing_paren, balance_braces, report_unfixable): ")
		fixType, _ := reader.ReadString('\n')
		fixType = strings.TrimSpace(fixType)
		if fixType == "" {
			fixType = "report_unfixable"
		}

		fmt.Print("Enter confidence (0.0-1.0, default 0.5): ")
		confStr, _ := reader.ReadString('\n')
		confStr = strings.TrimSpace(confStr)
		conf := 0.5
		if confStr != "" {
			fmt.Sscanf(confStr, "%f", &conf)
		}

		newPattern := ErrorPattern{
			ID:		id,
			Match:		matchStr,
			Description:	desc,
			FixType:	fixType,
			Examples:	[]string{errMsg},
			Confidence:	conf,
		}

		db.Patterns = append(db.Patterns, newPattern)
		fmt.Printf("  ✅ Added pattern '%s'\n", id)
	}

	saveTrainingData(path, db)
}

// extractMatchKey extracts a reasonable match key from an error message
func extractMatchKey(errMsg string) string {

	if idx := strings.Index(errMsg, ": "); idx >= 0 {
		after := errMsg[idx+2:]

		if idx2 := strings.Index(after, " ("); idx2 >= 0 {
			return after[:idx2]
		}
		return after
	}

	if len(errMsg) > 60 {
		return errMsg[:60]
	}
	return errMsg
}

// saveTrainingData saves the updated training data to the JSON file
func saveTrainingData(path string, db *ErrorPatternsDB) {

	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		fmt.Printf("⚠️  Could not create directory %s: %v\n", dir, err)
		return
	}

	data, err := json.MarshalIndent(db, "", "  ")
	if err != nil {
		fmt.Printf("⚠️  Could not marshal training data: %v\n", err)
		return
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		fmt.Printf("⚠️  Could not save training data: %v\n", err)
		return
	}

	fmt.Printf("\n💾 Saved %d patterns to %s\n", len(db.Patterns), path)
}

func main() {
	datasetPath := flag.String("data", "data/training/fim_dataset.json", "Path to FIM dataset JSON")
	epochs := flag.Int("epochs", 10, "Number of training epochs")
	batchSize := flag.Int("batch", 8, "Batch size")
	lr := flag.Float64("lr", 1e-4, "Learning rate")
	outputDir := flag.String("output", "models/fim_checkpoints", "Output directory for checkpoints")
	embedDim := flag.Int("embed-dim", 64, "Embedding dimension (smaller = less memory)")
	vocabSize := flag.Int("vocab-size", 1000, "Vocabulary size")
	flag.Parse()

	if err := run(*datasetPath, *epochs, *batchSize, *lr, *outputDir, *embedDim, *vocabSize); err != nil {
		log.Fatalf("Fatal: %v", err)
	}
}

func run(datasetPath string, epochs, batchSize int, lr float64, outputDir string, embedDim, vocabSize int) error {
	log.Printf("Loading FIM dataset from %s...", datasetPath)

	data, err := os.ReadFile(datasetPath)
	if err != nil {
		return fmt.Errorf("read dataset: %w", err)
	}

	var dataset struct {
		Train	[]interface{}	`json:"train"`
		Val	[]interface{}	`json:"val"`
		Meta	struct {
			FIMExamples	int	`json:"fim_examples"`
			SearchReplace	int	`json:"search_replace"`
		}	`json:"meta"`
	}
	if err := json.Unmarshal(data, &dataset); err != nil {
		return fmt.Errorf("unmarshal dataset: %w", err)
	}

	log.Printf("Dataset loaded: %d train examples, %d val examples", len(dataset.Train), len(dataset.Val))
	log.Printf("  FIM examples: %d, SEARCH/REPLACE: %d", dataset.Meta.FIMExamples, dataset.Meta.SearchReplace)

	// Extract FIM examples from the training data
	var fimExamples []training.FIMExample
	for _, item := range dataset.Train {
		if ex := extractFIMExample(item); ex != nil {
			fimExamples = append(fimExamples, *ex)
		}
	}
	log.Printf("Extracted %d FIM examples from training data", len(fimExamples))

	if len(fimExamples) == 0 {
		return fmt.Errorf("no FIM examples found in dataset")
	}

	if err := os.MkdirAll(outputDir, 0755); err != nil {
		return fmt.Errorf("create output dir: %w", err)
	}

	log.Printf("Creating MoE model (embed_dim=%d, vocab_size=%d)...", embedDim, vocabSize)
	model := createMOEModel(embedDim, vocabSize)

	adapter := training.NewFIMAdapter(model, embedDim, vocabSize)
	adapter.SetLearningRate(lr)

	runtime.GC()
	debug.SetGCPercent(50)

	config := training.DefaultFIMConfig()
	config.Epochs = epochs
	config.BatchSize = batchSize
	config.LearningRate = lr
	config.OutputDir = outputDir
	config.MaxSeqLen = 512
	config.ValInterval = 100
	config.SaveInterval = 500

	log.Printf("Starting FIM training:")
	log.Printf("  Epochs: %d", config.Epochs)
	log.Printf("  Batch size: %d", config.BatchSize)
	log.Printf("  Learning rate: %.6f", config.LearningRate)
	log.Printf("  Output dir: %s", config.OutputDir)

	trainer := training.NewFIMTrainer(config, adapter)
	if err := trainer.TrainFromExamples(fimExamples); err != nil {
		return fmt.Errorf("FIM training failed: %w", err)
	}

	log.Printf("FIM training complete! Checkpoints saved to %s", outputDir)
	return nil
}

// createMOEModel creates a minimal MoE model for FIM training.
// Uses small dimensions to fit within available memory.
func createMOEModel(embedDim, vocabSize int) *moe.MoEStack {

	numExperts := 2
	k := 1

	hiddenDim := embedDim
	expertBuilder := func(idx int) (moe.Expert, error) {
		return moe.NewFeedForwardExpert(embedDim, hiddenDim, embedDim)
	}

	layer, err := moe.NewMoELayer(embedDim, embedDim, numExperts, k, expertBuilder)
	if err != nil {
		log.Fatalf("Failed to create MoE layer: %v", err)
	}
	layer.Training = true

	return moe.NewMoEStack(layer)
}

// extractFIMExample attempts to extract a FIM example from a generic interface{}.
func extractFIMExample(item interface{}) *training.FIMExample {
	switch v := item.(type) {
	case map[string]interface{}:

		if prompt, ok := v["prompt"].(string); ok {
			if completion, ok := v["completion"].(string); ok {
				prefix, suffix, middle := parseFIMPrompt(prompt, completion)
				if middle != "" {
					ex := &training.FIMExample{
						Prefix:	prefix,
						Suffix:	suffix,
						Middle:	middle,
					}
					if inst, ok := v["instruction"].(string); ok {
						ex.Instruction = inst
					}
					return ex
				}
			}
		}

		if before, ok := v["before_code"].(string); ok {
			if patch, ok := v["target_patch"].(string); ok {
				after := extractAfterFromPatch(patch)
				if after != "" {
					prefix, middle, suffix := splitIntoFIM(before, after)
					if middle != "" {
						ex := &training.FIMExample{
							Prefix:	prefix,
							Suffix:	suffix,
							Middle:	middle,
						}
						if inst, ok := v["instruction"].(string); ok {
							ex.Instruction = inst
						}
						return ex
					}
				}
			}
		}
	}
	return nil
}

// parseFIMPrompt extracts prefix, suffix, middle from FIM-formatted prompt.
func parseFIMPrompt(prompt, completion string) (string, string, string) {
	preIdx := indexOf(prompt, "<PRE>")
	sufIdx := indexOf(prompt, "<SUF>")
	midIdx := indexOf(prompt, "<MID>")

	if preIdx == -1 || sufIdx == -1 || midIdx == -1 {
		return "", "", ""
	}

	prefix := prompt[preIdx+5 : sufIdx]
	suffix := prompt[sufIdx+5 : midIdx]
	middle := completion

	return prefix, suffix, middle
}

// extractAfterFromPatch extracts the REPLACE section from a SEARCH/REPLACE patch.
func extractAfterFromPatch(patch string) string {
	parts := splitOn(patch, "=======\n")
	if len(parts) != 2 {
		return ""
	}
	after := trimSuffix(parts[1], "\n>>>>>>> REPLACE")
	after = trimSuffix(after, ">>>>>>> REPLACE")
	return after
}

// splitIntoFIM splits before/after code into prefix/middle/suffix.
// Finds the changed region by comparing before and after line-by-line.
// Returns empty strings if no diff found.
func splitIntoFIM(before, after string) (string, string, string) {
	beforeLines := splitLines(before)
	afterLines := splitLines(after)

	if len(beforeLines) == 0 && len(afterLines) == 0 {
		return "", "", ""
	}

	firstDiff := -1
	maxCommon := len(beforeLines)
	if len(afterLines) < maxCommon {
		maxCommon = len(afterLines)
	}
	for i := 0; i < maxCommon; i++ {
		if beforeLines[i] != afterLines[i] {
			firstDiff = i
			break
		}
	}
	if firstDiff == -1 {

		if len(beforeLines) < len(afterLines) {

			prefix := joinLines(afterLines[:maxCommon])
			middle := joinLines(afterLines[maxCommon:])
			return prefix, middle, ""
		} else if len(beforeLines) > len(afterLines) {

			prefix := joinLines(afterLines)
			return prefix, "", ""
		}
		return "", "", ""
	}

	lastDiff := len(afterLines)
	maxCommonEnd := len(beforeLines)
	if len(afterLines) < maxCommonEnd {
		maxCommonEnd = len(afterLines)
	}
	for i := 1; i <= maxCommonEnd; i++ {
		bi := len(beforeLines) - i
		ai := len(afterLines) - i
		if bi < firstDiff || ai < firstDiff || beforeLines[bi] != afterLines[ai] {
			lastDiff = len(afterLines) - i + 1
			break
		}
	}

	if lastDiff < firstDiff {
		lastDiff = firstDiff
	}

	if lastDiff > len(afterLines) {
		lastDiff = len(afterLines)
	}

	prefix := joinLines(afterLines[:firstDiff])
	middle := joinLines(afterLines[firstDiff:lastDiff])
	suffix := joinLines(afterLines[lastDiff:])

	return prefix, middle, suffix
}

// Helper functions to avoid importing strings in this simple CLI
func indexOf(s, substr string) int {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return i
		}
	}
	return -1
}

func splitOn(s, sep string) []string {
	idx := indexOf(s, sep)
	if idx == -1 {
		return []string{s}
	}
	return []string{s[:idx], s[idx+len(sep):]}
}

func trimSuffix(s, suffix string) string {
	if len(s) >= len(suffix) && s[len(s)-len(suffix):] == suffix {
		return s[:len(s)-len(suffix)]
	}
	return s
}

func splitLines(s string) []string {
	if s == "" {
		return nil
	}
	var lines []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			lines = append(lines, s[start:i])
			start = i + 1
		}
	}
	lines = append(lines, s[start:])
	return lines
}

func joinLines(lines []string) string {
	if len(lines) == 0 {
		return ""
	}
	result := lines[0]
	for _, l := range lines[1:] {
		result += "\n" + l
	}
	return result
}

// LoadTrainingData loads the training data from a JSON file.
func LoadTrainingData(filePath string) (*TrainingData, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open training data file %s: %w", filePath, err)
	}
	defer file.Close()

	bytes, err := io.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read training data file %s: %w", filePath, err)
	}

	var data TrainingData
	err = json.Unmarshal(bytes, &data)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal training data JSON from %s: %w", filePath, err)
	}

	return &data, nil
}

func main() {
	rand.Seed(1)
	log.Printf("Random number after seeding: %f", rand.Float64())
	// Define paths
	const trainingDataPath = "data/training/trainingdata/intent_data.json"
	const queryVocabPath = "data/models/gob_models/query_vocabulary.gob"
	const parentIntentVocabPath = "data/models/gob_models/parent_intent_vocabulary.gob"
	const childIntentVocabPath = "data/models/gob_models/child_intent_vocabulary.gob"
	const sentenceVocabPath = "data/models/gob_models/sentence_vocabulary.gob"
	const modelSavePath = "data/models/gob_models/moe_classification_model.gob"

	trainingData, err := LoadTrainingData(trainingDataPath)
	if err != nil {
		log.Fatalf("Failed to load training data: %v", err)
	}

	queryVocabulary := mainvocab.NewVocabulary()
	queryVocabulary.AddToken("<s>")
	queryVocabulary.AddToken("</s>")
	parentIntentVocabulary := mainvocab.NewVocabulary()
	childIntentVocabulary := mainvocab.NewVocabulary()
	sentenceVocabulary := mainvocab.NewVocabulary()

	for _, example := range *trainingData {
		words := strings.FieldsSeq(example.Sentence)
		for word := range words {
			queryVocabulary.AddToken(word)
			sentenceVocabulary.AddToken(word)
		}
		parentIntentVocabulary.AddToken(example.ParentIntent)
		childIntentVocabulary.AddToken(example.ChildIntent)
	}

	if err := queryVocabulary.Save(queryVocabPath); err != nil {
		log.Fatalf("Failed to save query vocabulary: %v", err)
	}
	if err := parentIntentVocabulary.Save(parentIntentVocabPath); err != nil {
		log.Fatalf("Failed to save parent intent vocabulary: %v", err)
	}
	if err := childIntentVocabulary.Save(childIntentVocabPath); err != nil {
		log.Fatalf("Failed to save child intent vocabulary: %v", err)
	}
	if err := sentenceVocabulary.Save(sentenceVocabPath); err != nil {
		log.Fatalf("Failed to save sentence vocabulary: %v", err)
	}

	model, err := moemodel.NewMoEClassificationModel(
		queryVocabulary.Size(),
		256,
		parentIntentVocabulary.Size(),
		childIntentVocabulary.Size(),
		sentenceVocabulary.Size(),
		4,
		2,
		32,
	)
	if err != nil {
		log.Fatalf("Failed to create model: %v", err)
	}

	optimizer := nn.NewOptimizer(model.Parameters(), 0.001, 5.0)
	queryTokenizer, _ := tokenizer.NewTokenizer(queryVocabulary)
	sentenceTokenizer, _ := tokenizer.NewTokenizer(sentenceVocabulary)

	log.Printf("Sentence Vocabulary PaddingTokenID: %d", sentenceVocabulary.PaddingTokenID)
	log.Printf("Sentence Vocabulary Size: %d", sentenceVocabulary.Size())

	const batchSize = 32	// Define batch size

	for epoch := range 100 {

		for i := 0; i < len(*trainingData); i += batchSize {
			batchEnd := min(i+batchSize, len(*trainingData))
			batch := (*trainingData)[i:batchEnd]

			// Prepare batch inputs and targets
			var batchInputIDs [][]float32
			var batchParentTargetIDs []int
			var batchChildTargetIDs []int
			var batchSentenceTargetIDs [][]int
			currentBatchSize := len(batch)

			for _, example := range batch {
				tokenIDs, _ := queryTokenizer.Encode(example.Sentence)
				inputData := make([]float32, len(tokenIDs))
				for i, id := range tokenIDs {
					inputData[i] = float32(id)
				}
				batchInputIDs = append(batchInputIDs, inputData)
				batchParentTargetIDs = append(batchParentTargetIDs, parentIntentVocabulary.WordToToken[example.ParentIntent])
				batchChildTargetIDs = append(batchChildTargetIDs, childIntentVocabulary.WordToToken[example.ChildIntent])

				sentenceTokenIDs, _ := sentenceTokenizer.Encode(example.Sentence)
				batchSentenceTargetIDs = append(batchSentenceTargetIDs, sentenceTokenIDs)
			}

			paddedInputData := make([]float32, currentBatchSize*model.BertConfig.MaxPositionEmbeddings)
			for rowIdx, seq := range batchInputIDs {
				copy(paddedInputData[rowIdx*model.BertConfig.MaxPositionEmbeddings:], seq)

				for k := len(seq); k < model.BertConfig.MaxPositionEmbeddings; k++ {
					paddedInputData[rowIdx*model.BertConfig.MaxPositionEmbeddings+k] = float32(queryVocabulary.PaddingTokenID)
				}
			}

			paddedSentenceData := make([]float32, currentBatchSize*model.BertConfig.MaxPositionEmbeddings)
			for rowIdx, seq := range batchSentenceTargetIDs {
				floatSeq := make([]float32, len(seq))
				for i, v := range seq {
					floatSeq[i] = float32(v)
				}
				copy(paddedSentenceData[rowIdx*model.BertConfig.MaxPositionEmbeddings:], floatSeq)
				for k := len(seq); k < model.BertConfig.MaxPositionEmbeddings; k++ {
					paddedSentenceData[rowIdx*model.BertConfig.MaxPositionEmbeddings+k] = float32(sentenceVocabulary.PaddingTokenID)
				}
			}

			inputTensor := tensor.NewTensor([]int{currentBatchSize, model.BertConfig.MaxPositionEmbeddings}, paddedInputData, false)
			targetSentenceTensor := tensor.NewTensor([]int{currentBatchSize, model.BertConfig.MaxPositionEmbeddings}, paddedSentenceData, false)

			optimizer.ZeroGrad()

			parentLogits, childLogits, sentenceOutputs, err := model.Forward(inputTensor, targetSentenceTensor)
			if err != nil {
				log.Printf("Forward pass failed: %+v", err)
				continue
			}

			parentLoss, parentGrad := tensor.CrossEntropyLoss(parentLogits, batchParentTargetIDs, parentIntentVocabulary.PaddingTokenID, 0.0)
			childLoss, childGrad := tensor.CrossEntropyLoss(childLogits, batchChildTargetIDs, childIntentVocabulary.PaddingTokenID, 0.0)

			flatTargets := make([]int, 0, currentBatchSize*model.BertConfig.MaxPositionEmbeddings)
			for _, t := range batchSentenceTargetIDs {
				flatTargets = append(flatTargets, t...)

				for k := len(t); k < model.BertConfig.MaxPositionEmbeddings; k++ {
					flatTargets = append(flatTargets, sentenceVocabulary.PaddingTokenID)
				}
			}
			sentenceLoss, sentenceGrad := tensor.CrossEntropyLoss(sentenceOutputs, flatTargets, sentenceVocabulary.PaddingTokenID, 0.0)

			totalLoss := parentLoss + childLoss + sentenceLoss

			if err := model.Backward(parentGrad, childGrad, sentenceGrad); err != nil {
				log.Printf("Backward pass failed: %v", err)
				continue
			}

			optimizer.Step()
			log.Printf("Epoch: %d, Batch: %d, Loss: %f", epoch, i/batchSize, totalLoss)
		}
	}

	if err := moemodel.SaveMoEClassificationModelToGOB(model, modelSavePath); err != nil {
		log.Fatalf("Failed to save model: %v", err)
	}

	fmt.Println("Training complete.")
}

type IntentTrainingExample struct {
	Query		string	`json:"query"`
	SemanticOutput	struct {
		Social struct {
			Intent		string	`json:"intent"`
			SubIntent	string	`json:"sub_intent"`
		} `json:"social"`
	}	`json:"semantic_output"`
	FlatOutput	string	`json:"flat_output"`
}

// LoadIntentTrainingData loads the intent training data from a JSON file.
func LoadIntentTrainingData(filePath string) (*IntentTrainingData, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open training data file %s: %w", filePath, err)
	}
	defer file.Close()

	bytes, err := io.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read training data file %s: %w", filePath, err)
	}

	var data IntentTrainingData
	err = json.Unmarshal(bytes, &data)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal training data JSON from %s: %w", filePath, err)
	}

	return &data, nil
}

func main() {
	// Define paths
	const trainingDataPath = "data/training/tiny_chat.json"
	const queryVocabPath = "data/models/gob_models/query_vocabulary.gob"
	const parentIntentVocabPath = "data/models/gob_models/parent_intent_vocabulary.gob"
	const childIntentVocabPath = "data/models/gob_models/child_intent_vocabulary.gob"
	const sentenceVocabPath = "data/models/gob_models/sentence_vocabulary.gob"
	const modelSavePath = "data/models/gob_models/moe_classification_model.gob"

	trainingData, err := LoadIntentTrainingData(trainingDataPath)
	if err != nil {
		log.Fatalf("Failed to load intent training data: %v", err)
	}

	queryVocab, err := mainvocab.LoadVocabulary(queryVocabPath)
	if err != nil {
		log.Println("Failed to load query vocabulary, creating a new one.")
		queryVocab = mainvocab.NewVocabulary()
	}

	parentIntentVocab, err := mainvocab.LoadVocabulary(parentIntentVocabPath)
	if err != nil {
		log.Println("Failed to load parent intent vocabulary, creating a new one.")
		parentIntentVocab = mainvocab.NewVocabulary()
	}

	childIntentVocab, err := mainvocab.LoadVocabulary(childIntentVocabPath)
	if err != nil {
		log.Println("Failed to load child intent vocabulary, creating a new one.")
		childIntentVocab = mainvocab.NewVocabulary()
	}

	sentenceVocab, err := mainvocab.LoadVocabulary(sentenceVocabPath)
	if err != nil {
		log.Println("Failed to load sentence vocabulary, creating a new one.")
		sentenceVocab = mainvocab.NewVocabulary()
	}

	for _, example := range *trainingData {
		words := tokenizer.Tokenize(strings.ToLower(example.Query))
		for _, word := range words {
			queryVocab.AddToken(word)
		}
		parentIntentVocab.AddToken(example.SemanticOutput.Social.Intent)
		childIntentVocab.AddToken(example.SemanticOutput.Social.SubIntent)
		sentenceWords := tokenizer.Tokenize(strings.ToLower(example.FlatOutput))
		for _, word := range sentenceWords {
			sentenceVocab.AddToken(word)
		}
	}

	queryVocab.Save(queryVocabPath)
	parentIntentVocab.Save(parentIntentVocabPath)
	childIntentVocab.Save(childIntentVocabPath)
	sentenceVocab.Save(sentenceVocabPath)

	log.Printf("Query vocabulary size: %d", queryVocab.Size())
	log.Printf("Parent intent vocabulary size: %d", parentIntentVocab.Size())
	log.Printf("Child intent vocabulary size: %d", childIntentVocab.Size())
	log.Printf("Sentence vocabulary size: %d", sentenceVocab.Size())

	word2vecModel, err := word2vec.LoadModel("data/models/gob_models/word2vec_model.gob")
	if err != nil {
		log.Fatalf("Failed to load Word2Vec model: %v", err)
	}

	embeddingDim := 128
	hiddenSize := 256
	maxAttentionHeads := 4
	numLayers := 2
	dropoutRate := 0.1

	embedding := nn.NewEmbedding(queryVocab.Size(), embeddingDim)

	f32Vectors := make(map[int][]float32)
	for id, vec := range word2vecModel.WordVectors {
		f32Vec := make([]float32, len(vec))
		for i, v := range vec {
			f32Vec[i] = float32(v)
		}
		f32Vectors[id] = f32Vec
	}
	embedding.LoadPretrainedWeights(f32Vectors)

	encoder, err := moe.NewSimpleRNNEncoder(embeddingDim, hiddenSize, numLayers)
	if err != nil {
		log.Fatalf("Failed to create SimpleRNNEncoder: %v", err)
	}

	decoder, err := moe.NewRNNDecoder(hiddenSize, sentenceVocab.Size(), hiddenSize, maxAttentionHeads, numLayers, float32(dropoutRate), 1)
	if err != nil {
		log.Fatalf("Failed to create decoder: %v", err)
	}

	model := &moe.IntentMoE{
		Embedding:		embedding,
		Encoder:		encoder,
		Decoder:		decoder,
		SentenceVocabSize:	sentenceVocab.Size(),
	}
	if err != nil {
		log.Fatalf("Failed to create new MoE model: %v", err)
	}

	TrainIntentModel(model, trainingData, queryVocab, parentIntentVocab, childIntentVocab, sentenceVocab, 100, 0.001, 32, 32)

	log.Printf("Saving MoE Classification model to %s", modelSavePath)
	outputFile, err := os.Create(modelSavePath)
	if err != nil {
		log.Fatalf("Failed to create model file %s: %v", modelSavePath, err)
	}
	defer outputFile.Close()

	err = moe.SaveIntentMoEModelToGOB(model, modelSavePath)
	if err != nil {
		log.Fatalf("Failed to save MoE model: %v", err)
	}

	log.Println("Training complete.")
}

// TrainIntentModel trains the MoEClassificationModel for intent classification.
func TrainIntentModel(model *moe.IntentMoE, data *IntentTrainingData, queryVocab, parentIntentVocab, childIntentVocab, sentenceVocab *mainvocab.Vocabulary, epochs int, learningRate float32, batchSize int, maxSeqLength int) {
	optimizer := nn.NewOptimizer(model.Parameters(), learningRate, 5.0)

	for epoch := range epochs {
		log.Printf("Epoch %d/%d", epoch+1, epochs)
		var totalLoss float32 = 0.0
		numBatches := 0

		for i := 0; i < len(*data); i += batchSize {
			end := min(i+batchSize, len(*data))
			batch := (*data)[i:end]

			loss, err := trainIntentModelBatch(model, optimizer, batch, queryVocab, parentIntentVocab, childIntentVocab, sentenceVocab, maxSeqLength)
			if err != nil {
				log.Printf("Error training batch: %v", err)
				continue
			}
			totalLoss += loss
			numBatches++
		}
		if numBatches > 0 {
			log.Printf("Epoch %d, Average Loss: %f", epoch+1, totalLoss/float32(numBatches))
		}
	}
}

// trainIntentModelBatch performs a single training step on a batch of intent data.
func trainIntentModelBatch(model *moe.IntentMoE, optimizer nn.Optimizer, batch IntentTrainingData, queryVocab, parentIntentVocab, childIntentVocab, sentenceVocab *mainvocab.Vocabulary, maxSeqLength int) (float32, error) {
	optimizer.ZeroGrad()

	batchSize := len(batch)

	inputIDsBatch := make([]int, batchSize*maxSeqLength)
	parentIntentIDs := make([]int, batchSize)
	childIntentIDs := make([]int, batchSize)
	targetSentenceIDsBatch := make([]int, batchSize*maxSeqLength)

	tok, err := tokenizer.NewTokenizer(queryVocab)
	if err != nil {
		return 0, fmt.Errorf("failed to create tokenizer: %w", err)
	}

	sentenceTokenizer, err := tokenizer.NewTokenizer(sentenceVocab)
	if err != nil {
		return 0, fmt.Errorf("failed to create sentence tokenizer: %w", err)
	}

	for i, example := range batch {
		tokenIDs, err := tok.Encode(example.Query)
		if err != nil {
			return 0, fmt.Errorf("query tokenization failed for item %d: %w", i, err)
		}

		if len(tokenIDs) > maxSeqLength {
			tokenIDs = tokenIDs[:maxSeqLength]
		} else {
			padding := make([]int, maxSeqLength-len(tokenIDs))
			for j := range padding {
				padding[j] = queryVocab.PaddingTokenID
			}
			tokenIDs = append(tokenIDs, padding...)
		}
		copy(inputIDsBatch[i*maxSeqLength:(i+1)*maxSeqLength], tokenIDs)

		parentIntentIDs[i] = parentIntentVocab.GetTokenID(example.SemanticOutput.Social.Intent)
		childIntentIDs[i] = childIntentVocab.GetTokenID(example.SemanticOutput.Social.SubIntent)

		sentenceTokenIDs, err := sentenceTokenizer.Encode(example.FlatOutput)
		if err != nil {
			return 0, fmt.Errorf("sentence tokenization failed for item %d: %w", i, err)
		}

		if len(sentenceTokenIDs) > maxSeqLength {
			sentenceTokenIDs = sentenceTokenIDs[:maxSeqLength]
		} else {
			padding := make([]int, maxSeqLength-len(sentenceTokenIDs))
			for j := range padding {
				padding[j] = sentenceVocab.PaddingTokenID
			}
			sentenceTokenIDs = append(sentenceTokenIDs, padding...)
		}
		copy(targetSentenceIDsBatch[i*maxSeqLength:(i+1)*maxSeqLength], sentenceTokenIDs)
	}

	inputTensor := tensor.NewTensor([]int{batchSize, maxSeqLength}, convertIntsToFloat32s(inputIDsBatch), false)
	targetSentenceTensor := tensor.NewTensor([]int{batchSize, maxSeqLength}, convertIntsToFloat32s(targetSentenceIDsBatch), false)

	sentenceLogits, _, err := model.Forward(0.0, inputTensor, targetSentenceTensor)
	if err != nil {
		return 0, fmt.Errorf("model forward pass failed: %w", err)
	}

	var sentenceLoss float32 = 0.0
	var sentenceGrads []*tensor.Tensor

	if len(sentenceLogits) == 1 && len(sentenceLogits[0].Shape) == 3 {

		logits := sentenceLogits[0]

		fullTargets := make([]int, batchSize*(maxSeqLength-1))
		for i := 0; i < batchSize; i++ {
			for t := 0; t < maxSeqLength-1; t++ {
				fullTargets[i*(maxSeqLength-1)+t] = targetSentenceIDsBatch[i*maxSeqLength+t+1]
			}
		}

		loss, grad := tensor.CrossEntropyLoss(logits, fullTargets, sentenceVocab.PaddingTokenID, 0.1)
		sentenceLoss = loss
		sentenceGrads = []*tensor.Tensor{grad}
	} else {
		sentenceGrads = make([]*tensor.Tensor, maxSeqLength-1)
		for t := 0; t < maxSeqLength-1; t++ {
			targets := make([]int, batchSize)
			for i := 0; i < batchSize; i++ {
				targets[i] = int(targetSentenceIDsBatch[i*maxSeqLength+t+1])
			}
			loss, grad := tensor.CrossEntropyLoss(sentenceLogits[t], targets, sentenceVocab.PaddingTokenID, 0.1)
			sentenceLoss += loss
			sentenceGrads[t] = grad
		}
	}

	totalLoss := sentenceLoss

	err = model.Backward(sentenceGrads...)
	if err != nil {
		return 0, fmt.Errorf("model backward pass failed: %w", err)
	}

	optimizer.Step()

	return totalLoss, nil
}

func convertIntsToFloat32s(input []int) []float32 {
	output := make([]float32, len(input))
	for i, v := range input {
		output[i] = float32(v)
	}
	return output
}

func SequenceCrossEntropyLoss(predictions *tensor.Tensor, targets []int, paddingID int) (float32, *tensor.Tensor) {
	batchSize := predictions.Shape[0]
	seqLen := predictions.Shape[1]
	vocabSize := predictions.Shape[2]

	predictionsFlat, _ := predictions.Reshape([]int{batchSize * seqLen, vocabSize})
	softmax, _ := predictionsFlat.Softmax(1)
	logSoftmax, _ := softmax.Log()

	targetsFlat := targets

	var totalLoss float32 = 0.0
	numTokens := 0

	grad := make([]float32, len(logSoftmax.Data))

	for i := 0; i < batchSize*seqLen; i++ {
		targetID := targetsFlat[i]

		if targetID == paddingID {
			continue
		}

		numTokens++
		predictedLogProb := logSoftmax.Data[i*vocabSize+targetID]
		totalLoss -= predictedLogProb

		for j := range vocabSize {
			prob := logSoftmax.Data[i*vocabSize+j]
			if j == targetID {
				grad[i*vocabSize+j] = prob - 1
			} else {
				grad[i*vocabSize+j] = prob
			}
		}
	}

	if numTokens == 0 {
		return 0.0, nil
	}

	avgLoss := totalLoss / float32(numTokens)
	gradTensor := tensor.NewTensor(logSoftmax.Shape, grad, true)

	return avgLoss, gradTensor
}

