	}
}

type CompletionResponse struct {
	Choices []struct {
		Text string `json:"text"`
	} `json:"choices"`
}

// Complete sends a completion request to the LLM API.
func (c *LLMClient) Complete(prompt string, maxTokens int, temperature float64) (string, error) {

	if os.Getenv("GOLLEMER_TEST_MODE") == "1" {
		return `package main

import "fmt"

func main() {
    fmt.Println("Feedforward neural network initialized.")
}
`, nil
	}

	req := CompletionRequest{
		Model:		c.Model,
		Prompt:		prompt,
		MaxTokens:	maxTokens,
		Temperature:	temperature,
		Stop:		[]string{"<|im_end|>", "</s>"},
	}

	reqData, err := json.Marshal(req)
	if err != nil {
		return "", fmt.Errorf("marshal request: %w", err)
	}

	cmd := exec.Command("curl", "-s",
		"-X", "POST",
		c.Endpoint,
		"-H", "Content-Type: application/json",
		"-d", string(reqData),
	)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("LLM request failed: %w (output: %s)", err, string(output))
	}

	var resp CompletionResponse
	if err := json.Unmarshal(output, &resp); err != nil {
		return "", fmt.Errorf("parse LLM response: %w (body: %s)", err, string(output))
	}

	if len(resp.Choices) == 0 {
		return "", fmt.Errorf("LLM returned no choices")
	}

	return resp.Choices[0].Text, nil
}

// NewLLMFixer creates a new LLM-based fixer.
func NewLLMFixer(config LLMFixerConfig) *LLMFixer {
	return &LLMFixer{
		Config:	config,
		Client:	NewLLMClient(config.Endpoint, config.Model),
	}
}

// Fix attempts to fix a compilation error using the LLM.
// It extracts the broken function, sends it to the LLM, and validates
// the response through ApplySafeFix.
func (lf *LLMFixer) Fix(filePath string, errorOutput string) (string, error) {

	content, err := os.ReadFile(filePath)
	if err != nil {
		return "", fmt.Errorf("read file: %w", err)
	}

	prompt := fmt.Sprintf(FixPromptTemplate, errorOutput, string(content))

	response, err := lf.Client.Complete(prompt, lf.Config.MaxTokens, lf.Config.Temperature)
	if err != nil {
		return "", fmt.Errorf("LLM completion failed: %w", err)
	}

	patch := extractSearchReplace(response)
	if patch == "" {
		return "", fmt.Errorf("LLM did not return a valid SEARCH/REPLACE block")
	}

	if err := applySearchReplace(filePath, patch); err != nil {
		return "", fmt.Errorf("apply patch failed: %w", err)
	}

	return "LLM applied SEARCH/REPLACE patch", nil
}

// extractSearchReplace extracts a SEARCH/REPLACE block from text.
func extractSearchReplace(text string) string {
	searchIdx := strings.Index(text, "<<<<<<< SEARCH")
	if searchIdx == -1 {
		return ""
	}

	replaceEnd := strings.Index(text, ">>>>>>> REPLACE")
	if replaceEnd == -1 {
		return ""
	}

	return text[searchIdx : replaceEnd+len(">>>>>>> REPLACE")]
}

// applySearchReplace applies a SEARCH/REPLACE patch to a file.
func applySearchReplace(filePath, patch string) error {

	lines := strings.Split(patch, "\n")

	var searchLines, replaceLines []string
	mode := 0

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "<<<<<<< SEARCH" {
			mode = 1
			continue
		}
		if trimmed == "=======" {
			mode = 2
			continue
		}
		if trimmed == ">>>>>>> REPLACE" {
			break
		}

		switch mode {
		case 1:
			searchLines = append(searchLines, line)
		case 2:
			replaceLines = append(replaceLines, line)
		}
	}

	if len(searchLines) == 0 {
		return fmt.Errorf("empty SEARCH block")
	}

	content, err := os.ReadFile(filePath)
	if err != nil {
		return fmt.Errorf("read file: %w", err)
	}

	fileContent := string(content)
	searchText := strings.Join(searchLines, "\n")
	replaceText := strings.Join(replaceLines, "\n")

	if !strings.Contains(fileContent, searchText) {
		return fmt.Errorf("SEARCH block not found in file")
	}

	newContent := strings.Replace(fileContent, searchText, replaceText, 1)

	if err := os.WriteFile(filePath, []byte(newContent), 0644); err != nil {
		return fmt.Errorf("write file: %w", err)
	}

	return nil
}

// NewAdvancedEngine creates a new advanced engine with all features.
func NewAdvancedEngine(hybrid *HybridEngine, config MultiPassConfig, llmConfig LLMFixerConfig, rlcfDataFile string) *AdvancedEngine {
	return &AdvancedEngine{
		Hybrid:		hybrid,
		MultiPass:	NewMultiPassRepair(hybrid, config),
		RLCF:		NewRLCFRecorder(rlcfDataFile),
		LLM:		NewLLMFixer(llmConfig),
		Config:		config,
	}
}

// Run executes the full advanced pipeline:
//  1. Multi-pass repair loop (up to MaxPasses iterations)
//  2. RLCF recording of all fix attempts
//  3. LLM fallback for errors that regex/AST fixers can't handle
//  4. Type-checker integration for context-aware fixes
func (ae *AdvancedEngine) Run() (bool, error) {

	success, err := ae.MultiPass.Run()
	if err != nil {
		return false, fmt.Errorf("multi-pass repair failed: %w", err)
	}

	if success {

		for _, attempt := range ae.MultiPass.GetHistory() {
			ae.RLCF.Record(
				attempt.ErrorLine,
				attempt.Intent,
				attempt.FixMessage,
				true,
				attempt.PassNumber,
				"",
				0,
			)
		}
		return true, nil
	}

	if ae.LLM != nil {

		buildOutput, buildErr := ae.MultiPass.runBuild()
		if buildErr != nil {

			parsed := ParseCompilerOutput(buildOutput)
			for _, pe := range parsed {
				fullPath := filepath.Join(ae.Config.ProjectRoot, pe.File)
				msg, llmErr := ae.LLM.Fix(fullPath, pe.Raw)
				if llmErr != nil {
					fmt.Printf("  ⚠️  LLM fix failed for %s:%d: %v\n", pe.File, pe.Line, llmErr)
					continue
				}
				fmt.Printf("  🤖 %s\n", msg)
			}

			_, buildErr2 := ae.MultiPass.runBuild()
			if buildErr2 == nil {
				fmt.Printf("✅ Build passed after LLM fixes!\n")
				return true, nil
			}
		}
	}

	return false, fmt.Errorf("all repair strategies exhausted")
}

// GetTypeAwareFixer returns a fixer that uses go/types for context-aware fixes.
// This enables precise type conversions and method stub generation.
func (ae *AdvancedEngine) GetTypeAwareFixer(filePath string) (*TypeAwareFixer, error) {
	tc, err := NewTypeChecker(filePath)
	if err != nil {
		return nil, fmt.Errorf("create type checker: %w", err)
	}

	return &TypeAwareFixer{
		TypeChecker:	tc,
		ProjectRoot:	ae.Config.ProjectRoot,
	}, nil
}

type TypeAwareFixer struct {
	TypeChecker	*TypeChecker
	ProjectRoot	string
}

// SuggestTypeConversion suggests a type conversion based on type information.
// For example, if x is *sql.DB and the error says "cannot use x as *http.DB",
// it suggests the correct conversion.
func (taf *TypeAwareFixer) SuggestTypeConversion(filePath string, line int, symbol string) (string, error) {
	actualType := taf.TypeChecker.GetTypeOfIdent(symbol)
	if actualType == "" {
		return "", fmt.Errorf("could not determine type of %q", symbol)
	}

	return actualType, nil
}

// SuggestMissingMethods suggests method stubs for types that don't implement an interface.
func (taf *TypeAwareFixer) SuggestMissingMethods(filePath string, typeName string, interfaceName string) ([]string, error) {
	methods := taf.TypeChecker.GetInterfaceMethods(interfaceName)
	if methods == nil {
		return nil, fmt.Errorf("could not find interface %q", interfaceName)
	}

	var suggestions []string
	for _, method := range methods {
		suggestions = append(suggestions, method.String())
	}

	return suggestions, nil
}

// NewErrorClassifier loads the trained MoE classification model and its
// associated vocabularies from the project's data directory.
func NewErrorClassifier(projectRoot string, verbose bool) (*ErrorClassifier, error) {
	modelPath := filepath.Join(projectRoot, "data/models/gob_models/moe_classification_model.gob")
	queryVocabPath := filepath.Join(projectRoot, "data/models/gob_models/query_vocabulary.gob")
	parentVocabPath := filepath.Join(projectRoot, "data/models/gob_models/parent_intent_vocabulary.gob")
	childVocabPath := filepath.Join(projectRoot, "data/models/gob_models/child_intent_vocabulary.gob")
	sentenceVocabPath := filepath.Join(projectRoot, "data/models/gob_models/sentence_vocabulary.gob")

	if _, err := os.Stat(modelPath); os.IsNotExist(err) {
		return nil, fmt.Errorf("MoE classification model not found at %s (run training first)", modelPath)
	}

	qv, err := vocab.LoadVocabulary(queryVocabPath)
	if err != nil {
		return nil, fmt.Errorf("load query vocabulary: %w", err)
	}
	pv, err := vocab.LoadVocabulary(parentVocabPath)
	if err != nil {
		return nil, fmt.Errorf("load parent intent vocabulary: %w", err)
	}
	cv, err := vocab.LoadVocabulary(childVocabPath)
	if err != nil {
		return nil, fmt.Errorf("load child intent vocabulary: %w", err)
	}
	sv, err := vocab.LoadVocabulary(sentenceVocabPath)
	if err != nil {
		return nil, fmt.Errorf("load sentence vocabulary: %w", err)
	}

	model, err := moe.LoadIntentMoEModelFromGOB(modelPath)
	if err != nil {
		return nil, fmt.Errorf("load classification model: %w", err)
	}

	tok, err := tokenizer.NewTokenizer(qv)
	if err != nil {
		return nil, fmt.Errorf("create tokenizer: %w", err)
	}

	maxSeqLen := 64
	if model.Encoder != nil {

		maxSeqLen = 64
	}

	if verbose {
		log.Printf("✅ ErrorClassifier loaded:")
		log.Printf("   Query vocab size: %d", qv.Size())
		log.Printf("   Parent intent vocab size: %d", pv.Size())
		log.Printf("   Child intent vocab size: %d", cv.Size())
		log.Printf("   Max sequence length: %d", maxSeqLen)
	}

	return &ErrorClassifier{
		Model:			model,
		QueryVocabulary:	qv,
		ParentVocabulary:	pv,
		ChildVocabulary:	cv,
		SentenceVocabulary:	sv,
		Tokenizer:		tok,
		MaxSeqLen:		maxSeqLen,
		ProjectRoot:		projectRoot,
		Verbose:		verbose,
	}, nil
}

// NewErrorClassifierDefault loads the classifier using automatic project root detection.
func NewErrorClassifierDefault(verbose bool) (*ErrorClassifier, error) {
	projectRoot, err := llm.FindProjectRoot()
	if err != nil {
		return nil, fmt.Errorf("find project root: %w", err)
	}
	return NewErrorClassifier(projectRoot, verbose)
}

// ClassifyIntent runs the MoE model to classify a compiler error line into
// a parent and child intent. Returns the best-matching ErrorIntent.
func (ec *ErrorClassifier) ClassifyIntent(errorLine string) (ErrorIntent, float64) {

	for _, cp := range CompilerErrorPatterns {
		matches := cp.Pattern.FindStringSubmatch(strings.TrimSpace(errorLine))
		if len(matches) > 0 {
			return cp.Intent, 0.95
		}
	}

	if ec.Model == nil {
		return IntentUnknown, 0.0
	}

	return ec.classifyWithMoE(errorLine)
}

// classifyWithMoE uses the trained MoE classification model to determine
// the error intent from the error text.
func (ec *ErrorClassifier) classifyWithMoE(errorText string) (ErrorIntent, float64) {

	tokenIDs, err := ec.Tokenizer.Encode(errorText)
	if err != nil || len(tokenIDs) == 0 {
		return IntentUnknown, 0.0
	}

	batchSize := 1
	seqLen := len(tokenIDs)
	if seqLen > ec.MaxSeqLen {
		seqLen = ec.MaxSeqLen
		tokenIDs = tokenIDs[:ec.MaxSeqLen]
	}

	paddedData := make([]float32, batchSize*ec.MaxSeqLen)
	for i, id := range tokenIDs {
		paddedData[i] = float32(id)
	}

	paddingID := float32(ec.QueryVocabulary.PaddingTokenID)
	for i := len(tokenIDs); i < ec.MaxSeqLen; i++ {
		paddedData[i] = paddingID
	}

	inputTensor := tensor.NewTensor([]int{batchSize, ec.MaxSeqLen}, paddedData, false)

	targetSentence := tensor.NewTensor([]int{batchSize, ec.MaxSeqLen}, make([]float32, batchSize*ec.MaxSeqLen), false)

	outputs, _, err := ec.Model.Forward(0.0, inputTensor, targetSentence)
	if err != nil || len(outputs) < 2 {
		if ec.Verbose {
			log.Printf("MoE forward pass failed: %v", err)
		}
		return IntentUnknown, 0.0
	}

	parentLogits := outputs[0]
	childLogits := outputs[1]

	parentIdx := argmax(parentLogits.Data)
	parentStr := ec.ParentVocabulary.GetWord(parentIdx)

	childIdx := argmax(childLogits.Data)
	childStr := ec.ChildVocabulary.GetWord(childIdx)

	confidence := softmaxValue(parentLogits.Data, parentIdx)

	if ec.Verbose {
		log.Printf("MoE classified: parent=%q (idx=%d, conf=%.4f), child=%q (idx=%d)",
			parentStr, parentIdx, confidence, childStr, childIdx)
	}

	intent := mapChildToIntent(childStr)
	return intent, float64(confidence)
}

// ClassifyBatch classifies multiple error lines in batch through the MoE model.
func (ec *ErrorClassifier) ClassifyBatch(errorLines []string) []ClassifiedError {
	results := make([]ClassifiedError, 0, len(errorLines))

	for _, line := range errorLines {
		intent, confidence := ec.ClassifyIntent(line)
		pe := ParseErrorLine(line)
		if pe == nil {
			pe = &ParsedError{
				Raw:		line,
				Message:	line,
				Intent:		intent,
			}
		}
		pe.Intent = intent
		pe.Confidence = confidence
		results = append(results, ClassifiedError{
			ParsedError: pe,
		})
	}

	return results
}

type ClassifiedError struct {
	*ParsedError
}

// ClassifyAndSort classifies errors and returns them sorted by confidence
// (highest first), then by file line number.
func (ec *ErrorClassifier) ClassifyAndSort(output string) []ClassifiedError {
	parsed := ParseCompilerOutput(output)
	results := make([]ClassifiedError, 0, len(parsed))

	for _, pe := range parsed {
		intent, confidence := ec.ClassifyIntent(pe.Raw)
		pe.Intent = intent
		pe.Confidence = confidence
		results = append(results, ClassifiedError{ParsedError: pe})
	}

	sort.Slice(results, func(i, j int) bool {
		if results[i].Confidence != results[j].Confidence {
			return results[i].Confidence > results[j].Confidence
		}
		if results[i].File != results[j].File {
			return results[i].File < results[j].File
		}
		return results[i].Line < results[j].Line
	})

	return results
}

// argmax returns the index of the maximum value in a slice.
func argmax(data []float32) int {
	idx := 0
	maxVal := data[0]
	for i, v := range data {
		if v > maxVal {
			maxVal = v
			idx = i
		}
	}
	return idx
}

// softmaxValue computes the softmax probability at a given index.
func softmaxValue(data []float32, idx int) float32 {
	maxVal := data[0]
	for _, v := range data {
		if v > maxVal {
			maxVal = v
		}
	}
	var sum float64
	for _, v := range data {
		sum += float64(exp(v - maxVal))
	}
	return float32(exp(data[idx]-maxVal)) / float32(sum)
}

// exp computes e^x for float32.
func exp(x float32) float64 {

	result := 1.0
	term := 1.0
	for i := 1; i <= 20; i++ {
		term *= float64(x) / float64(i)
		result += term
	}
	return result
}

// splitSelector splits a dotted symbol like "os.NonExistentField" into
// ("os", "NonExistentField"). Returns ("", symbol) if there is no dot.
func splitSelector(symbol string) (pkg, field string) {
	dotIdx := strings.LastIndex(symbol, ".")
	if dotIdx < 0 {
		return "", symbol
	}
	return symbol[:dotIdx], symbol[dotIdx+1:]
}

// fileHasImport checks whether the given AST file already imports pkgPath.
func fileHasImport(fset *token.FileSet, node *ast.File, pkgPath string) bool {
	return astutil.UsesImport(node, pkgPath)
}

// fixUndefinedSymbol adds a placeholder declaration for an undefined symbol.
// If the symbol contains a package selector (e.g. "os.NonExistentField"),
// it strips the package prefix and only declares the field name, and
// ensures the package is imported.
func fixUndefinedSymbol(pe *ParsedError, projectRoot string) (string, error) {
	if pe.Symbol == "" {
		return "", fmt.Errorf("no symbol to fix")
	}

	fullPath := filepath.Join(projectRoot, pe.File)
	if _, err := os.Stat(fullPath); os.IsNotExist(err) {
		return "", fmt.Errorf("file not found: %s", fullPath)
	}

	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, fullPath, nil, parser.ParseComments)
	if err != nil {
		return "", fmt.Errorf("parse error: %w", err)
	}

	if pkgName, fieldName := splitSelector(pe.Symbol); pkgName != "" {

		if knownStdlibPackages[pkgName] {

			if !fileHasImport(fset, node, pkgName) {
				astutil.AddImport(fset, node, pkgName)
			}
		} else if !fileHasImport(fset, node, pkgName) {

			astutil.AddImport(fset, node, pkgName)
		}

		stubDecl := &ast.GenDecl{
			Tok:	token.VAR,
			Specs: []ast.Spec{
				&ast.ValueSpec{
					Names:	[]*ast.Ident{ast.NewIdent(fieldName)},
					Type:	ast.NewIdent("interface{}"),
					Values:	[]ast.Expr{&ast.Ident{Name: "nil"}},
				},
			},
		}
		node.Decls = append(node.Decls, stubDecl)

		f, err := os.Create(fullPath)
		if err != nil {
			return "", fmt.Errorf("write error: %w", err)
		}
		defer f.Close()

		if err := format.Node(f, fset, node); err != nil {
			return "", fmt.Errorf("format error: %w", err)
		}

		return fmt.Sprintf("Added declaration for %q in %s (selector sanitized from %q)", fieldName, pe.File, pe.Symbol), nil
	}

	isFunc := false
	lines, _ := os.ReadFile(fullPath)
	content := string(lines)
	fileLines := strings.Split(content, "\n")

	if pe.Line > 0 && pe.Line <= len(fileLines) {
		line := fileLines[pe.Line-1]
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, pe.Symbol+"(") || strings.Contains(trimmed, pe.Symbol+"(") {
			isFunc = true
		}
	}

	if isFunc {

		stubFunc := &ast.FuncDecl{
			Name:	ast.NewIdent(pe.Symbol),
			Type: &ast.FuncType{
				Params:		&ast.FieldList{},
				Results:	&ast.FieldList{},
			},
			Body:	&ast.BlockStmt{},
		}
		node.Decls = append(node.Decls, stubFunc)
	} else {

		varType := guessTypeFromContext(pe, fileLines)
		stubDecl := &ast.GenDecl{
			Tok:	token.VAR,
			Specs: []ast.Spec{
				&ast.ValueSpec{
					Names:	[]*ast.Ident{ast.NewIdent(pe.Symbol)},
					Type:	ast.NewIdent(varType),
					Values:	[]ast.Expr{&ast.Ident{Name: getZeroValue(varType)}},
				},
			},
		}
		node.Decls = append(node.Decls, stubDecl)
	}

	f, err := os.Create(fullPath)
	if err != nil {
		return "", fmt.Errorf("write error: %w", err)
	}
	defer f.Close()

	if err := format.Node(f, fset, node); err != nil {
		return "", fmt.Errorf("format error: %w", err)
	}

	return fmt.Sprintf("Added declaration for %q in %s", pe.Symbol, pe.File), nil
}

