type GenerativeIntent struct {
	Name		string
	Description	string
	SystemPrompt	string
	Examples	[]string
}

// DetectIntent matches a natural language prompt to a generative intent.
// Uses simple keyword matching as a fast path — the LLM can override if needed.
func DetectIntent(prompt string) *GenerativeIntent {
	lower := strings.ToLower(prompt)

	// Score each intent by keyword match count
	type scored struct {
		intent	*GenerativeIntent
		score	int
	}
	var scoredIntents []scored

	for _, intent := range GenerativeIntentCatalog {
		score := 0
		for _, example := range intent.Examples {
			if strings.Contains(lower, strings.ToLower(example)) {
				score += 3
			}
		}

		descWords := strings.Fields(strings.ToLower(intent.Description))
		for _, word := range descWords {
			if len(word) > 3 && strings.Contains(lower, word) {
				score++
			}
		}
		if score > 0 {
			scoredIntents = append(scoredIntents, scored{intent: &intent, score: score})
		}
	}

	if len(scoredIntents) == 0 {
		return nil
	}

	best := scoredIntents[0]
	for _, s := range scoredIntents[1:] {
		if s.score > best.score {
			best = s
		}
	}
	return best.intent
}

type SynthesizeResult struct {
	FilePath	string
	Passes		int
	FinalBuildOK	bool
	History		[]SynthesizeAttempt
}

type SynthesizeAttempt struct {
	Pass	int
	Phase	string	// "generate" or "repair"
	Content	string
	Errors	string
}

// Synthesize generates Go code from a natural language prompt and iteratively
// repairs it until compilation succeeds. The compiler serves as the iterative
// architect — each error provides a roadmap for the next repair pass.
func (se *SynthesizerEngine) Synthesize(prompt string, targetDir string, filename string) (*SynthesizeResult, error) {
	if filename == "" {
		filename = "generated.go"
	}
	filePath := filepath.Join(targetDir, filename)

	result := &SynthesizeResult{
		FilePath:	filePath,
		History:	make([]SynthesizeAttempt, 0),
	}

	intent := DetectIntent(prompt)
	systemPrompt := ""
	if intent != nil {
		systemPrompt = intent.SystemPrompt
		if se.Verbose {
			fmt.Printf("🧠 Detected generative intent: %s\n", intent.Name)
		}
	}
	if systemPrompt == "" {
		systemPrompt = "You are an expert Go programmer. Generate complete, compilable Go code."
	}

	genPrompt := fmt.Sprintf(CodeGenPromptTemplate, systemPrompt, prompt)
	if se.Verbose {
		fmt.Printf("🤖 Generating code from prompt...\n")
	}

	code, err := se.LLM.Client.Complete(genPrompt, 2048, 0.1)
	if err != nil {
		return nil, fmt.Errorf("initial generation failed: %w", err)
	}

	code = extractGoCode(code)

	if se.Verbose {
		fmt.Printf("📄 Generated %d bytes of Go code\n", len(code))
	}

	result.History = append(result.History, SynthesizeAttempt{
		Pass:		0,
		Phase:		"generate",
		Content:	code,
	})

	if err := os.MkdirAll(targetDir, 0755); err != nil {
		return nil, fmt.Errorf("create target directory: %w", err)
	}
	if err := os.WriteFile(filePath, []byte(code), 0644); err != nil {
		return nil, fmt.Errorf("write generated file: %w", err)
	}

	for pass := 1; pass <= se.MaxPasses; pass++ {
		if se.Verbose {
			fmt.Printf("\n📦 Compilation pass %d/%d\n", pass, se.MaxPasses)
		}

		buildOutput, buildErr := se.runBuild(targetDir)
		if buildErr == nil {
			result.Passes = pass
			result.FinalBuildOK = true
			if se.Verbose {
				fmt.Printf("✅ Build passed on pass %d!\n", pass)
			}
			return result, nil
		}

		if se.Verbose {
			fmt.Printf("  ❌ Build failed:\n  %s\n", truncateString(buildOutput, 300))
		}

		hybridResults, hybridErr := se.Hybrid.ProcessError(buildOutput)
		if hybridErr == nil && len(hybridResults) > 0 {
			hasFixes := false
			for _, r := range hybridResults {
				if strings.HasPrefix(r, "✅") {
					hasFixes = true
				}
				if se.Verbose {
					fmt.Printf("  %s\n", r)
				}
			}
			if hasFixes {
				continue
			}
		}

		currentContent, err := os.ReadFile(filePath)
		if err != nil {
			return nil, fmt.Errorf("read current file: %w", err)
		}

		repairPrompt := fmt.Sprintf(RepairPromptTemplate,
			filename, string(currentContent), buildOutput)
		repaired, err := se.LLM.Client.Complete(repairPrompt, 2048, 0.1)
		if err != nil {
			return nil, fmt.Errorf("LLM repair pass %d failed: %w", pass, err)
		}

		repaired = extractGoCode(repaired)

		if repaired == code {
			if se.Verbose {
				fmt.Printf("  ⚠️  LLM returned identical code — no progress made\n")
			}
		}

		code = repaired
		result.History = append(result.History, SynthesizeAttempt{
			Pass:		pass,
			Phase:		"repair",
			Content:	code,
			Errors:		buildOutput,
		})

		if err := os.WriteFile(filePath, []byte(code), 0644); err != nil {
			return nil, fmt.Errorf("write repaired file: %w", err)
		}
	}

	_, buildErr := se.runBuild(targetDir)
	result.FinalBuildOK = buildErr == nil

	if !result.FinalBuildOK {
		if se.Verbose {
			fmt.Printf("❌ Build still failing after %d passes\n", se.MaxPasses)
		}
	}

	return result, nil
}

// runBuild executes go build in the specified directory.
func (se *SynthesizerEngine) runBuild(dir string) (string, error) {
	cmd := exec.Command("go", "build", ".")
	cmd.Dir = dir
	output, err := cmd.CombinedOutput()
	outputStr := string(output)
	if err != nil {
		return outputStr, fmt.Errorf("build failed: %s", outputStr)
	}
	return outputStr, nil
}

// extractGoCode strips markdown code fences and extracts the raw Go source.
func extractGoCode(text string) string {

	text = strings.TrimSpace(text)

	if strings.HasPrefix(text, "```go") {
		text = text[5:]
	} else if strings.HasPrefix(text, "```") {
		text = text[3:]
	}

	if strings.HasSuffix(text, "```") {
		text = text[:len(text)-3]
	} else if last := strings.LastIndex(text, "```"); last >= 0 {
		text = text[:last]
	}

	text = strings.TrimSpace(text)
	return text
}

// HandleGenerativePrompt is the top-level entry point for code synthesis.
// Given a natural language prompt and a target package, it:
//  1. Asks the LLM/generative engine to draft the file structure
//  2. Writes it safely to the target file
//  3. Leverages the multi-pass engine to auto-fix compilation errors
//
// Example:
//
//	err := HandleGenerativePrompt(
//	    "Create a feedforward neural network with backpropagation from scratch",
//	    "./generated_projects/neural_net",
//	    "neural.go",
//	)
func HandleGenerativePrompt(prompt string, targetPackage string, filename string) error {

	llmConfig := DefaultLLMFixerConfig()
	llm := NewLLMFixer(llmConfig)

	classifier := NewRegexClassifier(targetPackage)
	hybrid := NewHybridEngine(targetPackage, classifier, true)

	synthesizer := NewSynthesizerEngine(llm, hybrid, 10, true)

	fmt.Printf("🧬 Code Synthesis Engine\n")
	fmt.Printf("   Prompt: %s\n", prompt)
	fmt.Printf("   Target: %s/%s\n", targetPackage, filename)
	fmt.Println()

	result, err := synthesizer.Synthesize(prompt, targetPackage, filename)
	if err != nil {
		return fmt.Errorf("synthesis failed: %w", err)
	}

	fmt.Printf("\n📊 Synthesis Result:\n")
	fmt.Printf("   File:     %s\n", result.FilePath)
	fmt.Printf("   Passes:   %d\n", result.Passes)
	fmt.Printf("   Build:    ")
	if result.FinalBuildOK {
		fmt.Println("✅ PASSED")
	} else {
		fmt.Println("❌ FAILED (after max passes)")
	}
	fmt.Printf("   History:  %d attempts\n", len(result.History))

	return nil
}

type ASTGenerator struct {
	Fset *token.FileSet
}

// NewASTGenerator creates a new AST generator.
func NewASTGenerator() *ASTGenerator {
	return &ASTGenerator{
		Fset: token.NewFileSet(),
	}
}

// GenerateFile generates a complete *ast.File from a Go source string.
// This is used to convert LLM-generated code into AST form for hybrid repairs.
func (ag *ASTGenerator) GenerateFile(source string) (*ast.File, error) {
	return parser.ParseFile(ag.Fset, "", source, parser.ParseComments)
}

// FormatFile formats an *ast.File back to source code.
func (ag *ASTGenerator) FormatFile(file *ast.File) (string, error) {
	var buf strings.Builder
	if err := format.Node(&buf, ag.Fset, file); err != nil {
		return "", fmt.Errorf("format AST: %w", err)
	}
	return buf.String(), nil
}

// InjectFunction adds a new function declaration to an existing AST file.
func (ag *ASTGenerator) InjectFunction(file *ast.File, funcDecl *ast.FuncDecl) {
	file.Decls = append(file.Decls, funcDecl)
}

// CreateFunctionDecl creates an *ast.FuncDecl from a name, params, results, and body.
func (ag *ASTGenerator) CreateFunctionDecl(name string, params, results []string, body string) (*ast.FuncDecl, error) {

	src := fmt.Sprintf("package p\nfunc %s(%s) %s {\n%s\n}", name,
		strings.Join(params, ", "),
		strings.Join(results, ", "),
		body)

	f, err := parser.ParseFile(ag.Fset, "", src, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse function: %w", err)
	}

	if len(f.Decls) == 0 {
		return nil, fmt.Errorf("no declaration generated")
	}

	funcDecl, ok := f.Decls[0].(*ast.FuncDecl)
	if !ok {
		return nil, fmt.Errorf("generated declaration is not a function")
	}

	return funcDecl, nil
}

// AnalyzeCode analyzes generated Go code for quality metrics.
func AnalyzeCode(source string) (*SynthesisMetrics, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "", source, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse source: %w", err)
	}

	metrics := &SynthesisMetrics{
		LinesOfCode:	strings.Count(source, "\n"),
		ImportCount:	len(file.Imports),
	}

	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			metrics.FunctionCount++
			if d.Name.Name == "main" {
				metrics.HasMain = true
			}
		case *ast.GenDecl:
			if d.Tok == token.TYPE {
				metrics.TypeCount += len(d.Specs)
			}
		}
	}

	return metrics, nil
}

// PrintMetrics prints the synthesis metrics in a human-readable format.
func (sm *SynthesisMetrics) PrintMetrics() {
	fmt.Printf("📊 Code Metrics:\n")
	fmt.Printf("   Lines:      %d\n", sm.LinesOfCode)
	fmt.Printf("   Functions:  %d\n", sm.FunctionCount)
	fmt.Printf("   Types:      %d\n", sm.TypeCount)
	fmt.Printf("   Imports:    %d\n", sm.ImportCount)
	fmt.Printf("   Has main(): %v\n", sm.HasMain)
}

type BookIngester struct {
	registry *Registry
}

// NewBookIngester creates a book ingester that populates the given registry.
func NewBookIngester(reg *Registry) *BookIngester {
	return &BookIngester{
		registry: reg,
	}
}

// IngestFile reads a Go book from a file path (Markdown, TXT, or PDF text dump)
// and extracts concepts into the registry. Returns the ingestion result.
func (bi *BookIngester) IngestFile(path string) (*IngestionResult, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read book file %q: %w", path, err)
	}

	ext := strings.ToLower(filepath.Ext(path))
	var text string

	switch ext {
	case ".md", ".markdown":
		text = string(data)
	case ".txt":
		text = string(data)
	case ".pdf":

		text = extractPDFText(string(data))
	default:

		text = string(data)
	}

	title := extractBookTitle(text, filepath.Base(path))
	result := bi.ingestText(text, title, path)
	return result, nil
}

// IngestText processes raw Go book content as a string.
func (bi *BookIngester) IngestText(text string, bookTitle string) *IngestionResult {
	return bi.ingestText(text, bookTitle, "(inline)")
}

// ExportConcepts serializes the registry's concepts to a JSON file for reuse.
func (bi *BookIngester) ExportConcepts(outputPath string) error {
	data, err := bi.registry.MarshalJSON()
	if err != nil {
		return fmt.Errorf("marshal registry: %w", err)
	}
	return os.WriteFile(outputPath, data, 0644)
}

// ImportConcepts loads previously exported concepts from a JSON file
// and merges them into the registry. Existing concepts are not overwritten.
func (bi *BookIngester) ImportConcepts(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read concepts file %q: %w", path, err)
	}

	var imported map[string]ConceptTemplate
	if err := json.Unmarshal(data, &imported); err != nil {
		return fmt.Errorf("unmarshal concepts: %w", err)
	}

	for key, ct := range imported {
		if _, exists := bi.registry.concepts[key]; !exists {
			bi.registry.concepts[key] = ct
		}
	}

	return nil
}

// ingestText parses the book text and extracts concept templates.
func (bi *BookIngester) ingestText(text string, bookTitle string, sourceFile string) *IngestionResult {
	result := &IngestionResult{
		BookTitle:	bookTitle,
		SourceFile:	sourceFile,
		Sections:	make([]BookSection, 0),
		Concepts:	make([]ConceptTemplate, 0),
		Errors:		make([]string, 0),
	}

	sections := parseSections(text)
	result.Sections = sections

	for _, section := range sections {
		concept := bi.extractConceptFromSection(section)
		if concept != nil {
			key := generateConceptKey(concept.Term)

			if _, exists := bi.registry.concepts[key]; !exists {
				bi.registry.concepts[key] = *concept
			}
			result.Concepts = append(result.Concepts, *concept)
		}
	}

	for _, s := range sections {
		result.TotalCodeRefs += len(s.CodeBlocks)
	}

	return result
}

// extractConceptFromSection analyzes a book section and creates a ConceptTemplate
// if the section contains identifiable Go idioms and code patterns.
func (bi *BookIngester) extractConceptFromSection(section BookSection) *ConceptTemplate {
	content := section.Content
	titleLower := strings.ToLower(section.Title)

	if len(strings.Fields(content)) < 20 && len(section.CodeBlocks) == 0 {
		return nil
	}

	required := extractRequiredConstructs(content)
	if len(required) == 0 && len(section.CodeBlocks) == 0 {
		return nil
	}

	synonyms := extractSynonyms(titleLower, content)

	mutations := extractMutationsFromCodeBlocks(section.CodeBlocks, section.Title)

	term := cleanTerm(section.Title)
	if term == "" {
		return nil
	}

	return &ConceptTemplate{
		Term:			term,
		Synonyms:		synonyms,
		RequiredConstructs:	required,
		ASTMutations:		mutations,
	}
}

// parseSections splits Markdown text into hierarchical sections.
func parseSections(text string) []BookSection {
	lines := strings.Split(text, "\n")
	var sections []BookSection
	var current *BookSection
	var codeBlock bool
	var currentCode []string

	headerRegex := regexp.MustCompile(`^(#{1,6})\s+(.+)$`)

	flushCode := func() {
		if current != nil && len(currentCode) > 0 {
			code := strings.Join(currentCode, "\n")
			current.CodeBlocks = append(current.CodeBlocks, code)
			currentCode = nil
		}
	}

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "```") {
			if codeBlock {

				codeBlock = false
				flushCode()
			} else {
				codeBlock = true
				currentCode = nil
			}
			continue
		}

		if codeBlock {
			currentCode = append(currentCode, line)
			continue
		}

		if matches := headerRegex.FindStringSubmatch(trimmed); len(matches) >= 3 {
			flushCode()
			level := len(matches[1])
			title := strings.TrimSpace(matches[2])

			current = &BookSection{
				Title:		title,
				Level:		level,
				Content:	"",
				CodeBlocks:	make([]string, 0),
				Terms:		make([]string, 0),
			}
			sections = append(sections, *current)
			continue
		}

		if strings.HasPrefix(line, "    ") || strings.HasPrefix(line, "\t") {
			currentCode = append(currentCode, strings.TrimLeft(line, " \t"))
			continue
		} else if len(currentCode) > 0 && trimmed != "" {

			flushCode()
		}

		if current != nil {
			if current.Content != "" {
				current.Content += "\n"
			}
			current.Content += line

			extractTermsFromLine(trimmed, current)
		}
	}

	flushCode()

	for i := range sections {
		if i < len(sections) {

		}
	}

	return sections
}

// extractTermsFromLine finds key terminology in a line of text.
func extractTermsFromLine(line string, section *BookSection) {

	boldRegex := regexp.MustCompile(`\*\*(.+?)\*\*`)
	for _, m := range boldRegex.FindAllStringSubmatch(line, -1) {
		term := strings.TrimSpace(m[1])
		if len(term) > 2 {
			section.Terms = append(section.Terms, term)
		}
	}

	codeRegex := regexp.MustCompile("`(.+?)`")
	for _, m := range codeRegex.FindAllStringSubmatch(line, -1) {
		term := strings.TrimSpace(m[1])
		if len(term) > 2 && !strings.Contains(term, " ") {
			section.Terms = append(section.Terms, term)
		}
	}
}

// extractRequiredConstructs finds Go language primitives mentioned in text.
func extractRequiredConstructs(content string) []string {

	primitives := []string{
		"chan", "go func", "goroutine", "sync.WaitGroup", "sync.Mutex",
		"sync.RWMutex", "sync.Once", "sync.Map", "context.Context",
		"context.WithCancel", "context.WithDeadline", "context.WithTimeout",
		"interface{}", "struct", "error", "error interface",
		"defer", "panic", "recover", "select", "range",
		"map[", "[]", "make(", "new(", "close(",
		"time.Ticker", "time.Timer", "time.Duration", "time.Sleep",
		"os.Signal", "os/signal", "io.Reader", "io.Writer",
		"string", "int", "float64", "bool", "byte",
		"json.Marshal", "json.Unmarshal", "encoding/json",
		"http.Handler", "http.HandlerFunc", "net/http",
		"io/ioutil", "fmt.Sprintf", "fmt.Errorf",
		"errors.New", "errors.Is", "errors.As",
		"atomic.", "math.", "sort.",
	}

	contentLower := strings.ToLower(content)
	found := make(map[string]bool)
	var result []string

	for _, p := range primitives {
		if strings.Contains(contentLower, strings.ToLower(p)) {
			if !found[p] {
				found[p] = true
				result = append(result, p)
			}
		}
	}

	return result
}

// extractSynonyms finds alternative phrasings for a concept in the content.
func extractSynonyms(titleLower string, content string) []string {
	synonyms := make(map[string]bool)
	contentLower := strings.ToLower(content)

	akaPatterns := []*regexp.Regexp{
		regexp.MustCompile(`also known as ["'“](.+?)["'”]`),
		regexp.MustCompile(`also called ["'“](.+?)["'”]`),
		regexp.MustCompile(`sometimes called ["'“](.+?)["'”]`),
		regexp.MustCompile(`referred to as ["'“](.+?)["'”]`),
		regexp.MustCompile(`known as ["'“](.+?)["'”]`),
	}

	for _, pat := range akaPatterns {
		matches := pat.FindAllStringSubmatch(contentLower, -1)
		for _, m := range matches {
			if len(m) >= 2 {
				syn := strings.TrimSpace(m[1])
				if len(syn) > 2 && syn != titleLower {
					synonyms[syn] = true
				}
			}
		}
	}

	parenPattern := regexp.MustCompile(titleLower + `\s*\((.+?)\)`)
	if matches := parenPattern.FindStringSubmatch(contentLower); len(matches) >= 2 {
		parts := strings.Split(matches[1], ",")
		for _, p := range parts {
			syn := strings.TrimSpace(p)
			if len(syn) > 2 {
				synonyms[syn] = true
			}
		}
	}

	// Filter results
	var result []string
	for s := range synonyms {
		if len(s) > 2 {
			result = append(result, s)
		}
	}

	return result
}

// extractMutationsFromCodeBlocks analyzes Go code blocks and creates MutationRules.
func extractMutationsFromCodeBlocks(blocks []string, sectionTitle string) []MutationRule {
	var mutations []MutationRule

	for _, block := range blocks {

		if len(strings.Fields(block)) < 3 {
			continue
		}

		mType := detectMutationType(block)
		target := detectTargetStruct(block, sectionTitle)

		template := cleanCodeTemplate(block)
		if template == "" {
			continue
		}

		mutations = append(mutations, MutationRule{
			Type:		mType,
			TargetStruct:	target,
			CodeTemplate:	template,
		})
	}

	return mutations
}

// detectMutationType determines the type of AST mutation from code patterns.
func detectMutationType(code string) string {
	codeTrimmed := strings.TrimSpace(code)

	if containsGoKeyword(codeTrimmed, "struct") || isFieldDeclaration(code) {
		return "add_field"
	}

	if strings.HasPrefix(codeTrimmed, "defer ") || strings.Contains(codeTrimmed, "\n\tdefer ") {
		return "add_defer"
	}

	if strings.HasPrefix(codeTrimmed, "for ") || strings.HasPrefix(codeTrimmed, "for ") {
		return "wrap_loop"
	}

	if strings.HasPrefix(codeTrimmed, "import") || strings.HasPrefix(codeTrimmed, "\"") {
		return "add_import"
	}

	if strings.HasPrefix(codeTrimmed, "func ") {

		if strings.Contains(codeTrimmed, "func (") {
			return "add_method"
		}
		return "wrap_body"
	}

	if strings.HasPrefix(codeTrimmed, "type ") {
		return "add_type"
	}

	return "add_field"
}

// detectTargetStruct tries to identify which struct a mutation targets.
func detectTargetStruct(code string, sectionTitle string) string {

	receiverRegex := regexp.MustCompile(`func\s+\([a-zA-Z]+\s+(\*?[A-Z][a-zA-Z0-9]*)\)`)
	if matches := receiverRegex.FindStringSubmatch(code); len(matches) >= 2 {
		return strings.TrimPrefix(matches[1], "*")
	}

	typeRegex := regexp.MustCompile(`type\s+([A-Z][a-zA-Z0-9]*)\s+struct`)
	if matches := typeRegex.FindStringSubmatch(code); len(matches) >= 2 {
		return matches[1]
	}

	titleWords := strings.Fields(sectionTitle)
	for _, w := range titleWords {
		if len(w) > 3 && w[0] >= 'A' && w[0] <= 'Z' {
			return w
		}
	}

	return ""
}

// isFieldDeclaration checks if code looks like struct field declarations.
func isFieldDeclaration(code string) bool {
	lines := strings.Split(strings.TrimSpace(code), "\n")
	if len(lines) == 0 {
		return false
	}

	fieldCount := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		fieldRegex := regexp.MustCompile(`^[a-z][a-zA-Z0-9]*\s+\*?[A-Za-z][A-Za-z0-9.]*`)
		if fieldRegex.MatchString(trimmed) {
			fieldCount++
		}
	}

	return fieldCount > 0
}

// cleanCodeTemplate normalizes a code block into a usable template string.
func cleanCodeTemplate(code string) string {
	lines := strings.Split(code, "\n")
	var cleaned []string

	for _, line := range lines {
		trimmed := strings.TrimRight(line, " \t")
		if trimmed == "" && len(cleaned) == 0 {
			continue
		}

		cleaned = append(cleaned, trimmed)
	}

	for len(cleaned) > 0 && cleaned[len(cleaned)-1] == "" {
		cleaned = cleaned[:len(cleaned)-1]
	}

	return strings.Join(cleaned, "\n")
}

// cleanTerm normalizes a section title into a concept term.
func cleanTerm(title string) string {

	re := regexp.MustCompile(`^[\d.]+[\s]*`)
	cleaned := re.ReplaceAllString(title, "")

	cleaned = strings.TrimRight(cleaned, ".:;!?,# ")

	if len(cleaned) > 0 {
		cleaned = strings.ToUpper(cleaned[:1]) + cleaned[1:]
	}

	return cleaned
}

// generateConceptKey creates a lowercase key for a concept term.
func generateConceptKey(term string) string {
	key := strings.ToLower(term)
	key = strings.NewReplacer(" ", "_", "-", "_", "/", "_").Replace(key)
	key = regexp.MustCompile(`[^a-z0-9_]`).ReplaceAllString(key, "")
	return key
}

// containsGoKeyword checks if the code contains a specific Go keyword.
func containsGoKeyword(code string, keyword string) bool {
	wordBoundary := regexp.MustCompile(`\b` + regexp.QuoteMeta(keyword) + `\b`)
	return wordBoundary.MatchString(code)
}

// extractBookTitle extracts the book title from the content or uses the filename.
func extractBookTitle(text string, filename string) string {

	headerRegex := regexp.MustCompile(`(?m)^#\s+(.+)$`)
	if matches := headerRegex.FindStringSubmatch(text); len(matches) >= 2 {
		return strings.TrimSpace(matches[1])
	}

	base := filepath.Base(filename)
	ext := filepath.Ext(base)
	title := strings.TrimSuffix(base, ext)
	title = strings.NewReplacer("_", " ", "-", " ", ".", " ").Replace(title)
	return strings.TrimSpace(title)
}

// extractPDFText performs basic text extraction from PDF-like content.
// This is a simple fallback; full PDF parsing would use a library.
func extractPDFText(content string) string {

	lines := strings.Split(content, "\n")
	var textLines []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || isPDFArtifact(trimmed) {
			continue
		}
		textLines = append(textLines, trimmed)
	}
	return strings.Join(textLines, "\n")
}

// isPDFArtifact checks if a line is likely a PDF rendering artifact.
func isPDFArtifact(line string) bool {

	if matched, _ := regexp.MatchString(`^-+\s*Page\s+\d+\s*-+$`, line); matched {
		return true
	}

	if matched, _ := regexp.MatchString(`^\d+$`, line); matched && len(line) <= 5 {
		return true
	}

	if len(line) < 3 && strings.ContainsAny(line, "|-_=+") {
		return true
	}
	return false
}

type ConceptTemplate struct {
	Term			string		`json:"term"`			// "Worker Pool"
	Synonyms		[]string	`json:"synonyms"`		// ["task queue", "goroutine pool"]
	RequiredConstructs	[]string	`json:"required_constructs"`	// ["chan", "go fn()", "sync.WaitGroup"]
	ASTMutations		[]MutationRule	`json:"ast_mutations"`		// Structural rules to apply
}

type MutationRule struct {
	Type		string	`json:"type"`		// "add_field", "wrap_body", "add_defer", "wrap_loop", "add_import"
	TargetStruct	string	`json:"target_struct"`	// The struct or type name to modify (empty for file-level mutations)
	CodeTemplate	string	`json:"code_template"`	// Go code template to inject
}

type Registry struct {
	concepts map[string]ConceptTemplate
}

// NewRegistry creates a registry pre-populated with the standard Go idiom catalog.
func NewRegistry() *Registry {
	r := &Registry{
		concepts: make(map[string]ConceptTemplate),
	}
	r.registerDefaults()
	return r
}

// Get returns the concept template for the given key, or false if not found.
func (r *Registry) Get(key string) (ConceptTemplate, bool) {
	c, ok := r.concepts[key]
	return c, ok
}

// All returns all registered concept templates.
func (r *Registry) All() []ConceptTemplate {
	all := make([]ConceptTemplate, 0, len(r.concepts))
	for _, c := range r.concepts {
		all = append(all, c)
	}
	return all
}

