        var x = [];
        var y = [];

        if (rawVectors.length > 0 && rawVectors[0].length > 2) {
            var vectors = PCA.getEigenVectors(rawVectors);
            var adData = PCA.computeAdjustedData(rawVectors, vectors[0], vectors[1]);
            x = adData.formattedAdjustedData[0];
            y = adData.formattedAdjustedData[1];
        } else {
             for (var i = 0; i < rawVectors.length; i++) {
                 x.push(rawVectors[i][0]);
                 y.push(rawVectors[i][1]);
             }
        }

        var trace = {
            x: x, y: y, mode: 'markers+text', type: 'scatter',
            text: words, textposition: 'top center', marker: { size: 8 }
        };
        var layout = { title: 'Word Vector Distribution (PCA Reduced)', hovermode: 'closest' };
        Plotly.newPlot('myDiv', [trace], layout);
    </script>
</body>
</html>`, string(wordsJSON), string(vectorsJSON))
}

func handleGenericCreate(objectType, fileName, targetDirectory, handlerURL string, kb *KnowledgeBase) (string, bool) {

	if handlerURL != "" {
		handlerName := fileName
		if handlerName == "" {
			handlerName = objectType
		}

		cleanName := strings.TrimSuffix(strings.Title(handlerName), "Handler")

		handlerContent := "package main\n\n" +
			"import (\n" +
			"\t\"fmt\"\n" +
			"\t\"net/http\"\n" +
			")\n\n" +
			"// " + cleanName + "Handler handles requests for " + handlerURL + "\n" +
			"func " + cleanName + "Handler(w http.ResponseWriter, r *http.Request) {\n" +
			"\tfmt.Fprintf(w, \"Hello from the " + cleanName + " handler!\")\n" +
			"}\n"

		filePath := strings.ToLower(cleanName) + ".go"
		if targetDirectory != "" {
			filePath = filepath.Join(targetDirectory, filePath)
			os.MkdirAll(targetDirectory, 0755)
		}
		os.WriteFile(filePath, []byte(handlerContent), 0644)
		goImports(filePath)

		mainPath := "main.go"
		if targetDirectory != "" {
			if _, err := os.Stat(filepath.Join(targetDirectory, "main.go")); err == nil {
				mainPath = filepath.Join(targetDirectory, "main.go")
			}
		}
		regMsg, _ := registerHandlerURL(cleanName, handlerURL, mainPath)
		return fmt.Sprintf("I created '%sHandler' and registered it at '%s'. %s", cleanName, handlerURL, regMsg), true
	}

	if fileName != "" {
		if strings.Contains(objectType, "folder") || strings.Contains(objectType, "directory") {

			folderPath := fileName
			if targetDirectory != "" {
				folderPath = filepath.Join(targetDirectory, fileName)
			}
			if err := os.MkdirAll(folderPath, 0755); err != nil {
				return fmt.Sprintf("I couldn't create the folder '%s': %v", folderPath, err), false
			}
			return fmt.Sprintf("I created the folder '%s' for you.", folderPath), true
		}

		content := "// " + strings.Title(fileName) + " implementation for the " + objectType + " object\n" +
			"package main\n\nimport \"fmt\"\n\nfunc main() {\n" +
			"\tfmt.Println(\"Executing " + fileName + " (" + objectType + " logic)\")\n}\n"
		filePath := fileName + ".go"
		if targetDirectory != "" {
			filePath = filepath.Join(targetDirectory, filePath)
			os.MkdirAll(targetDirectory, 0755)
		}
		os.WriteFile(filePath, []byte(content), 0644)
		goImports(filePath)
		return fmt.Sprintf("I created the Go file '%s.go' for you.", fileName), true
	}

	folderPath := objectType
	if targetDirectory != "" {
		folderPath = filepath.Join(targetDirectory, folderPath)
	}
	os.MkdirAll(folderPath, 0755)
	return fmt.Sprintf("I created a work directory '%s' for you.", folderPath), true
}

func registerHandlerURL(handlerName, handlerURL, mainGoPath string) (string, error) {
	mainGoContent, err := os.ReadFile(mainGoPath)
	if err != nil {
		return "", fmt.Errorf("could not read %s: %w", mainGoPath, err)
	}

	if handlerURL == "" {
		handlerURL = "/" + strings.ToLower(handlerName)
	}

	registration := fmt.Sprintf("http.HandleFunc(\"%s\", %sHandler)", handlerURL, handlerName)
	if !strings.Contains(string(mainGoContent), registration) {

		placeholder := "// HANDLER_REGISTRATIONS_GO_HERE"
		lines := strings.Split(string(mainGoContent), "\n")
		var updatedLines []string
		found := false
		for _, line := range lines {
			if strings.Contains(line, placeholder) {
				// preserve indentation
				var indent strings.Builder
				for _, char := range line {
					if char == ' ' || char == '\t' {
						indent.WriteString(string(char))
					} else {
						break
					}
				}
				updatedLines = append(updatedLines, fmt.Sprintf("%shttp.HandleFunc(\"%s\", %sHandler)", indent.String(), handlerURL, handlerName))
				updatedLines = append(updatedLines, line)
				found = true
			} else {
				updatedLines = append(updatedLines, line)
			}
		}

		if !found {
			return "", fmt.Errorf("placeholder '%s' not found in %s. Tip: Place it inside func main() to enable auto-registration.", placeholder, mainGoPath)
		}

		updatedMainGoContent := strings.Join(updatedLines, "\n")

		err = os.WriteFile(mainGoPath, []byte(updatedMainGoContent), 0644)
		if err != nil {
			return "", fmt.Errorf("could not write to %s: %w", mainGoPath, err)
		}
		goImports(mainGoPath)
		return fmt.Sprintf("And registered it to URL '%s' in %s.", handlerURL, mainGoPath), nil
	}

	return "Handler already registered.", nil
}

// InjectPlaceholder looks for the main function and injects the handler registration tag
func InjectPlaceholder(path string) error {
	content, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	if strings.Contains(string(content), "// HANDLER_REGISTRATIONS_GO_HERE") {
		return nil
	}

	re := regexp.MustCompile(`func main\(\) \{`)
	if !re.Match(content) {
		return fmt.Errorf("could not find func main in %s", path)
	}

	insertion := "func main() {\n\t// HANDLER_REGISTRATIONS_GO_HERE"
	newContent := re.ReplaceAllString(string(content), insertion)

	return os.WriteFile(path, []byte(newContent), 0644)
}

type GoFixer struct {
	FilePath	string
	Errors		[]string
}

// NewGoFixer creates a new GoFixer instance
func NewGoFixer(filePath string) *GoFixer {
	return &GoFixer{FilePath: filePath}
}

// Fix attempts to automatically fix common Go syntax errors
func (gf *GoFixer) Fix() error {

	backupPath := gf.FilePath + ".bak"
	if err := copyFile(gf.FilePath, backupPath); err != nil {
		return fmt.Errorf("failed to create backup: %v", err)
	}
	defer os.Remove(backupPath)

	content, err := ioutil.ReadFile(gf.FilePath)
	if err != nil {
		return fmt.Errorf("failed to read file: %v", err)
	}

	_, err = parser.ParseFile(token.NewFileSet(), gf.FilePath, content, parser.ParseComments)
	if err == nil {

		return nil
	}

	errStr := err.Error()
	lines := strings.Split(string(content), "\n")

	fixedContent, fixed := gf.analyzeAndFix(errStr, lines)
	if fixed {
		if err := ioutil.WriteFile(gf.FilePath, []byte(fixedContent), 0644); err != nil {
			return fmt.Errorf("failed to write fixed content: %v", err)
		}

		if err := exec.Command("gofmt", "-w", gf.FilePath).Run(); err != nil {
			log.Printf("Warning: gofmt failed: %v", err)
		}

		return nil
	}

	if err := copyFile(backupPath, gf.FilePath); err != nil {
		return fmt.Errorf("failed to restore backup: %v", err)
	}

	return fmt.Errorf("could not automatically fix the file: %v", errStr)
}

// analyzeAndFix analyzes the error and applies appropriate fixes
func (gf *GoFixer) analyzeAndFix(errorStr string, lines []string) (string, bool) {

	gf.Errors = append(gf.Errors, errorStr)

	if content, ok := gf.fixMissingStructKeyword(lines); ok {
		return content, true
	}

	if content, ok := gf.fixMissingOpeningBrace(lines); ok {
		return content, true
	}

	if strings.Contains(errorStr, "expected '}'") {
		if content, ok := gf.fixMissingClosingBrace(lines); ok {
			return content, true
		}
	}

	if strings.Contains(errorStr, "expected ')'") {
		if content, ok := gf.fixMissingParentheses(lines); ok {
			return content, true
		}
	}

	if strings.Contains(errorStr, "expected '(', found") {
		if content, ok := gf.fixMissingFuncKeyword(lines); ok {
			return content, true
		}
		if content, ok := gf.fixMissingParentheses(lines); ok {
			return content, true
		}
	}

	if strings.Contains(errorStr, "unexpected EOF") {
		if content, ok := gf.fixUnexpectedEOF(lines); ok {
			return content, true
		}
	}

	if strings.Contains(errorStr, "expected declaration") {
		if content, ok := gf.fixExpectedDeclaration(lines); ok {
			return content, true
		}
	}

	if fixed, resultLines := gf.tryCommonFixes(lines); fixed {
		return strings.Join(resultLines, "\n"), true
	}

	return strings.Join(lines, "\n"), false
}

// fixMissingStructKeyword fixes "type X {" declarations that are missing the
// 'struct' keyword, converting them to "type X struct {".
func (gf *GoFixer) fixMissingStructKeyword(lines []string) (string, bool) {
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "type ") && strings.Contains(trimmed, "{") &&
			!strings.Contains(trimmed, " struct ") && !strings.HasPrefix(trimmed, "type struct") {

			lines[i] = strings.Replace(trimmed, "{", "struct {", 1)
			return strings.Join(lines, "\n"), true
		}
	}
	return strings.Join(lines, "\n"), false
}

// fixMissingOpeningBrace fixes missing opening braces
func (gf *GoFixer) fixMissingOpeningBrace(lines []string) (string, bool) {
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "type ") && strings.Contains(trimmed, " struct") && !strings.Contains(trimmed, "{") {
			lines[i] = trimmed + " {"
			return strings.Join(lines, "\n"), true
		}

		if strings.HasPrefix(trimmed, "func ") && !strings.Contains(trimmed, "{") {
			lines[i] = trimmed + " {"
			return strings.Join(lines, "\n"), true
		}

		if (strings.HasPrefix(trimmed, "if ") ||
			strings.HasPrefix(trimmed, "for ") ||
			strings.HasPrefix(trimmed, "switch ")) &&
			!strings.HasSuffix(trimmed, "{") && !strings.Contains(trimmed, "{") {
			lines[i] = trimmed + " {"
			return strings.Join(lines, "\n"), true
		}
	}
	return strings.Join(lines, "\n"), false
}

// fixMissingClosingBrace fixes missing closing braces
func (gf *GoFixer) fixMissingClosingBrace(lines []string) (string, bool) {

	openBraces := 0
	closeBraces := 0
	for _, line := range lines {
		openBraces += strings.Count(line, "{")
		closeBraces += strings.Count(line, "}")
	}

	if openBraces > closeBraces {
		lines = append(lines, strings.Repeat("}", openBraces-closeBraces))
		return strings.Join(lines, "\n"), true
	}
	return strings.Join(lines, "\n"), false
}

// fixMissingParentheses fixes missing parentheses
func (gf *GoFixer) fixMissingParentheses(lines []string) (string, bool) {
	for i, line := range lines {
		if strings.Contains(line, "fmt.Println(") && !strings.Contains(line, ")") {
			lines[i] = strings.Replace(line, "fmt.Println(", "fmt.Println(", 1) + ")"
			return strings.Join(lines, "\n"), true
		}

		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func ") && !strings.Contains(trimmed, "()") && !strings.Contains(trimmed, "(") {

			parts := strings.Fields(trimmed)
			if len(parts) >= 2 {
				funcName := strings.TrimSuffix(parts[1], "{")
				lines[i] = fmt.Sprintf("func %s() {", funcName)
				return strings.Join(lines, "\n"), true
			}
		}
	}
	return strings.Join(lines, "\n"), false
}

// fixMissingFuncKeyword fixes missing 'func' keyword
func (gf *GoFixer) fixMissingFuncKeyword(lines []string) (string, bool) {
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "fn ") && strings.HasSuffix(trimmed, " {") {
			lines[i] = strings.Replace(trimmed, "fn ", "func ", 1)
			return strings.Join(lines, "\n"), true
		}
	}
	return strings.Join(lines, "\n"), false
}

// fixUnexpectedEOF fixes unexpected end of file
func (gf *GoFixer) fixUnexpectedEOF(lines []string) (string, bool) {

	openBraces := 0
	closeBraces := 0
	for _, line := range lines {
		openBraces += strings.Count(line, "{")
		closeBraces += strings.Count(line, "}")
	}

	if openBraces > closeBraces {
		lines = append(lines, strings.Repeat("}", openBraces-closeBraces))
		return strings.Join(lines, "\n"), true
	}
	return strings.Join(lines, "\n"), false
}

// fixExpectedDeclaration fixes expected declaration errors
func (gf *GoFixer) fixExpectedDeclaration(lines []string) (string, bool) {
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func ") && !strings.Contains(trimmed, "()") && !strings.Contains(trimmed, "{") {

			parts := strings.Fields(trimmed)
			if len(parts) >= 2 {
				funcName := parts[1]
				lines[i] = fmt.Sprintf("func %s() {", funcName)
				return strings.Join(lines, "\n"), true
			}
		}
	}
	return strings.Join(lines, "\n"), false
}

// tryCommonFixes tries common fixes even if error pattern doesn't match
func (gf *GoFixer) tryCommonFixes(lines []string) (bool, []string) {

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "fn ") && strings.HasSuffix(trimmed, " {") {
			lines[i] = strings.Replace(trimmed, "fn ", "func ", 1)
			return true, lines
		}
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func init") && !strings.Contains(trimmed, "()") {
			lines[i] = strings.Replace(trimmed, "func init", "func init()", 1)
			return true, lines
		}
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func init()") && !strings.HasSuffix(trimmed, "{") {
			lines[i] = trimmed + " {"
			return true, lines
		}
	}

	for i, line := range lines {
		if strings.Contains(line, "fmt.Println(") && !strings.Contains(line, ")") {
			lines[i] = strings.Replace(line, "fmt.Println(", "fmt.Println(", 1) + ")"
			return true, lines
		}
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func ") && !strings.Contains(trimmed, "()") && !strings.Contains(trimmed, "{") {

			parts := strings.Fields(trimmed)
			if len(parts) >= 2 {
				funcName := parts[1]
				lines[i] = fmt.Sprintf("func %s() {", funcName)
				return true, lines
			}
		}
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "func ") && !strings.HasSuffix(trimmed, "{") && !strings.Contains(trimmed, "{") {

			if len(strings.Fields(trimmed)) == 2 {
				funcName := strings.Fields(trimmed)[1]
				lines[i] = fmt.Sprintf("func %s() {", funcName)
				return true, lines
			}
		}
	}

	return false, lines
}

// copyFile copies a file from src to dst
func copyFile(src, dst string) error {
	input, err := ioutil.ReadFile(src)
	if err != nil {
		return err
	}
	return ioutil.WriteFile(dst, input, 0644)
}

