type Entity struct {
	Value	string
	Type	string
}

// ExtractUnixPath performs a specialized regex search to find file paths without trailing punctuation.
func ExtractUnixPath(input string) string {
	return pathRegex.FindString(input)
}

// ExtractEntities is an intent-aware heuristic extractor.
// It uses the predicted Intent to narrow down which "extractors" or patterns to run,
// preventing false positives cross-domain (e.g. file paths vs CPU labels).
func ExtractEntities(intent string, input string) []Entity {
	var entities []Entity

	switch intent {
	case "file_manage":

		fileRegex := regexp.MustCompile(`[a-zA-Z0-9._/-]+\.[a-z]+|(?:"[^"]+")`)
		matches := fileRegex.FindAllString(input, -1)
		for _, m := range matches {
			entities = append(entities, Entity{Value: m, Type: "target"})
		}

	case "sys_monitor":

		resources := []string{"cpu", "ram", "memory", "disk", "network", "load"}
		for _, r := range resources {
			if strings.Contains(strings.ToLower(input), r) {
				entities = append(entities, Entity{Value: r, Type: "resource"})
			}
		}
	}

	return entities
}

type AudioBuffer struct {
	mu	sync.Mutex
	samples	[]float32
}

func StartAudioCapture(ctx context.Context, ab *AudioBuffer) error {
	cmd := exec.CommandContext(ctx, "ffmpeg",
		"-f", "alsa", "-i", "default",
		"-ac", "1", "-ar", "16000",
		"-f", "s16le", "-",
	)

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}

	if err := cmd.Start(); err != nil {
		return err
	}

	go func() {
		buf := make([]byte, FrameSize*BytesPerSample)
		for {
			select {
			case <-ctx.Done():
				return
			default:
				n, err := stdout.Read(buf)
				if err != nil || n == 0 {
					continue
				}

				samples := make([]float32, n/BytesPerSample)
				for i := 0; i < len(samples); i++ {
					sample16 := int16(binary.LittleEndian.Uint16(buf[i*2 : i*2+2]))
					samples[i] = float32(sample16) / 32768.0
				}

				ab.mu.Lock()
				ab.samples = append(ab.samples, samples...)
				ab.mu.Unlock()
			}
		}
	}()

	return nil
}

func NewAudioWindow(capacity int, ae *moe.AudioEncoder, te *moe.TemporalEncoder, headW, headB []float32, classNames []string, prototypes map[string][]float32) *AudioWindow {
	return &AudioWindow{
		Capacity:	capacity,
		Frames:		make([][]float32, capacity),
		audioEnc:	ae,
		temporal:	te,
		headW:		headW,
		headB:		headB,
		ClassNames:	classNames,
		Prototypes:	prototypes,
	}
}

func (aw *AudioWindow) Push(frame []float32) {
	aw.mu.Lock()
	defer aw.mu.Unlock()
	aw.Frames[aw.Head] = frame
	aw.Head = (aw.Head + 1) % aw.Capacity
	if aw.filled < aw.Capacity {
		aw.filled++
	}
}

func (aw *AudioWindow) Ready() bool {
	aw.mu.RLock()
	defer aw.mu.RUnlock()
	return aw.filled >= aw.Capacity
}

func (aw *AudioWindow) GetOrderedSequence() [][]float32 {
	aw.mu.RLock()
	defer aw.mu.RUnlock()
	seq := make([][]float32, aw.Capacity)
	for i := 0; i < aw.Capacity; i++ {
		idx := (aw.Head + i) % aw.Capacity
		seq[i] = aw.Frames[idx]
	}
	return seq
}

func cosineSim(a, b []float32) float32 {
	var dot, normA, normB float64
	for i := range a {
		dot += float64(a[i]) * float64(b[i])
		normA += float64(a[i]) * float64(a[i])
		normB += float64(b[i]) * float64(b[i])
	}
	if normA == 0 || normB == 0 {
		return 0
	}
	return float32(dot / (math.Sqrt(normA) * math.Sqrt(normB)))
}

func (aw *AudioWindow) Classify() (string, float32) {
	seq := aw.GetOrderedSequence()
	audioTokens := aw.audioEnc.Forward(seq)
	motionVec := aw.temporal.Forward(audioTokens)

	if len(aw.Prototypes) > 0 {
		bestLabel := ""
		bestSim := float32(-2.0)
		for label, proto := range aw.Prototypes {
			sim := cosineSim(motionVec, proto)
			if sim > bestSim {
				bestSim = sim
				bestLabel = label
			}
		}
		conf := (bestSim + 1.0) / 2.0
		return bestLabel, conf
	}

	numClasses := len(aw.ClassNames)
	hiddenDim := aw.temporal.HiddenDim
	logits := make([]float32, numClasses)
	for c := 0; c < numClasses; c++ {
		for d := 0; d < hiddenDim; d++ {
			logits[c] += aw.headW[c*hiddenDim+d] * motionVec[d]
		}
		logits[c] += aw.headB[c]
	}

	maxVal := logits[0]
	for _, v := range logits {
		if v > maxVal {
			maxVal = v
		}
	}
	sum := float32(0)
	for i, v := range logits {
		logits[i] = float32(math.Exp(float64(v - maxVal)))
		sum += logits[i]
	}
	for c := 0; c < numClasses; c++ {
		logits[c] /= sum
	}

	best := 0
	for c := 1; c < numClasses; c++ {
		if logits[c] > logits[best] {
			best = c
		}
	}
	return aw.ClassNames[best], logits[best]
}

func getRMS(samples []float32) float32 {
	var sum float32
	for _, s := range samples {
		sum += s * s
	}
	return float32(math.Sqrt(float64(sum / float32(len(samples)))))
}

func findWhisperBinaryAndModel() (string, string, error) {
	var checked []string
	if envBin := os.Getenv("WHISPER_CLI_BIN"); envBin != "" {
		checked = append(checked, envBin)
		if _, err := os.Stat(envBin); err == nil {
			if envModel := os.Getenv("WHISPER_MODEL_PATH"); envModel != "" {
				checked = append(checked, envModel)
				return envBin, envModel, nil
			}
			if modelPath, ok := resolveWhisperModelPath(envBin); ok {
				return envBin, modelPath, nil
			}
		}
	}

	candidateBins := []string{
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "whisper-cli"),
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "whisper"),
		filepath.Join("build_whisper", "whisper.cpp", "build", "bin", "main"),
		"/tmp/whisper.cpp/build/bin/whisper-cli",
		"/tmp/whisper.cpp/build/bin/whisper",
		"/tmp/whisper.cpp/build/bin/main",
	}

	for _, bin := range candidateBins {
		checked = append(checked, bin)
		if _, err := os.Stat(bin); err == nil {
			if modelPath, ok := resolveWhisperModelPath(bin); ok {
				return bin, modelPath, nil
			}
		}
	}

	for _, binaryName := range []string{"whisper-cli", "whisper", "main"} {
		if bin, err := exec.LookPath(binaryName); err == nil {
			checked = append(checked, bin)
			if modelPath, ok := resolveWhisperModelPath(bin); ok {
				return bin, modelPath, nil
			}
		}
	}

	return "", "", fmt.Errorf("whisper binary/model not found; checked: %s; set WHISPER_CLI_BIN and WHISPER_MODEL_PATH to override; or run build_voice.sh to build whisper.cpp and download ggml-tiny.en.bin", strings.Join(checked, ", "))
}

func resolveWhisperModelPath(bin string) (string, bool) {
	candidateModels := []string{
		filepath.Join(filepath.Dir(bin), "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(bin), "..", "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(filepath.Dir(bin)), "..", "models", "ggml-tiny.en.bin"),
		filepath.Join(filepath.Dir(filepath.Dir(filepath.Dir(bin))), "models", "ggml-tiny.en.bin"),
		filepath.Join("build_whisper", "whisper.cpp", "models", "ggml-tiny.en.bin"),
		filepath.Join("models", "ggml-tiny.en.bin"),
		filepath.Join("/tmp", "whisper.cpp", "models", "ggml-tiny.en.bin"),
	}

	if home, err := os.UserHomeDir(); err == nil {
		candidateModels = append(candidateModels,
			filepath.Join(home, ".cache", "whisper", "ggml-tiny.en.bin"),
			filepath.Join(home, ".cache", "whisper.cpp", "ggml-tiny.en.bin"),
			filepath.Join(home, ".cache", "whisper.cpp", "models", "ggml-tiny.en.bin"),
		)
	}

	for _, modelPath := range candidateModels {
		modelPath = filepath.Clean(modelPath)
		if _, err := os.Stat(modelPath); err == nil {
			return modelPath, true
		}
	}
	return "", false
}

func loadTrainedHead() (*moe.AudioEncoder, *moe.TemporalEncoder, []float32, []float32, []string, map[string][]float32) {
	ae, te, headW, headB, classNames, prototypes, err := moe.LoadAudioModel("models/audio_gru.json")
	if err == nil {
		log.Printf("✅ Loaded trained audio model (%d commands, %d prototypes)", len(classNames), len(prototypes))
		return ae, te, headW, headB, classNames, prototypes
	}

	log.Println("⚠️  No trained audio model found. Voice commands disabled.")
	return nil, nil, nil, nil, nil, nil
}

// whisperAutoTeach snapshots the current audio window frames, runs Whisper STT on them,
// and automatically updates the in-memory prototype map with the new label.
// This is called in a goroutine when the acoustic model is uncertain (conf 0.75–0.98).
func whisperAutoTeach(frames [][]float32, aw *AudioWindow, ae *moe.AudioEncoder, te *moe.TemporalEncoder, headW, headB []float32) {
	whisperBin, whisperModel, err := findWhisperBinaryAndModel()
	if err != nil {
		return
	}

	rawTmp := filepath.Join(whisperTempDir, whisperRawTmp)
	wavTmp := filepath.Join(whisperTempDir, whisperWavTmp)

	os.MkdirAll(whisperTempDir, 0755)

	f, err := os.Create(rawTmp)
	if err != nil {
		log.Printf("⚠️ [AutoTeach] could not write temp raw audio: %v", err)
		return
	}
	for _, frame := range frames {
		for _, s := range frame {
			sample16 := int16(s * 32768.0)
			_ = binary.Write(f, binary.LittleEndian, sample16)
		}
	}
	f.Close()

	if err := exec.Command("ffmpeg", "-y", "-f", "s16le", "-ar", "16000", "-ac", "1",
		"-i", rawTmp, wavTmp).Run(); err != nil {
		log.Printf("⚠️ [Voice] ffmpeg conversion failed: %v", err)
		return
	}

	devNull, _ := os.Open(os.DevNull)
	defer devNull.Close()
	wCmd := exec.Command(whisperBin, "-m", whisperModel, "-f", wavTmp, "-nt")
	wCmd.Stderr = devNull
	out, err := wCmd.Output()
	if err != nil {
		log.Printf("⚠️ [Voice] Whisper failed: %v", err)
		return
	}

	// Parse transcript from stdout only
	var parts []string
	for _, line := range strings.Split(string(out), "\n") {
		t := strings.TrimSpace(line)
		if t != "" {
			parts = append(parts, t)
		}
	}
	rawTranscript := strings.Join(parts, " ")

	label := strings.ToUpper(strings.TrimSpace(rawTranscript))
	for _, ch := range []string{".", ",", "?", "!", "'", "\"", "(", ")", "[", "]", "-"} {
		label = strings.ReplaceAll(label, ch, "")
	}
	label = strings.Join(strings.Fields(label), "_")

	if label == "" || len(label) > 60 {
		log.Printf("🎤 [AutoTeach] Whisper transcript empty or too long, skipping.")
		return
	}

	log.Printf("🎤 [AutoTeach] Whisper heard: \"%s\" → teaching label: %s", rawTranscript, label)

	audioTokens := ae.Forward(frames)
	newEmb := te.Forward(audioTokens)

	aw.mu.Lock()
	if existing, ok := aw.Prototypes[label]; ok {
		avg := make([]float32, len(newEmb))
		for i := range newEmb {
			avg[i] = (existing[i] + newEmb[i]) * 0.5
		}
		aw.Prototypes[label] = avg
		log.Printf("📐 [AutoTeach] Updated existing prototype for %s", label)
	} else {
		aw.Prototypes[label] = newEmb
		aw.ClassNames = append(aw.ClassNames, label)
		log.Printf("🆕 [AutoTeach] New command added: %s", label)
	}
	currentNames := aw.ClassNames
	currentProtos := aw.Prototypes
	aw.mu.Unlock()

	if err := moe.SaveAudioModel("models/audio_gru.json", ae, te, headW, headB, currentNames, currentProtos); err != nil {
		log.Printf("⚠️  [AutoTeach] Failed to save model: %v", err)
	} else {
		finalRaw := fmt.Sprintf("dataset/audio/%s_live_%d.raw", label, time.Now().Unix())
		os.Rename(rawTmp, finalRaw)
		log.Printf("✅ [AutoTeach] Model saved. %s prototype persisted.", label)
	}
}

func StartVoiceListener(ctx context.Context, inputChan chan<- string) {
	ae, te, headW, headB, classNames, prototypes := loadTrainedHead()
	if ae == nil {
		return
	}

	ab := &AudioBuffer{}
	if err := StartAudioCapture(ctx, ab); err != nil {
		log.Printf("⚠️  Could not start ffmpeg audio capture: %v", err)
		return
	}

	switch len(classNames) {
	case 0:
		log.Println("⚠️  No voice commands loaded (empty command list)")
	case 1:
		log.Printf("⚠️  Only %d voice command loaded — audio input will be very unreliable", len(classNames))
	default:
		log.Printf("✅ Audio command set size: %d commands", len(classNames))
	}

	aw := NewAudioWindow(200, ae, te, headW, headB, classNames, prototypes)
	ticker := time.NewTicker(25 * time.Millisecond)
	defer ticker.Stop()

	// NEW state variables to control phrase endings
	var silenceFrames int
	var isUserSpeaking bool

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			ab.mu.Lock()
			if len(ab.samples) >= FrameSize {
				frame := ab.samples[:FrameSize]
				ab.samples = ab.samples[FrameSize:]
				ab.mu.Unlock()

				rms := getRMS(frame)
				aw.Push(frame)

				if rms > EnergyThreshold {
					silenceFrames = 0
					if !isUserSpeaking && atomic.LoadInt32(&isSpeaking) == 0 {
						isUserSpeaking = true
					}
				} else {
					silenceFrames++
				}

				if aw.Ready() && isUserSpeaking && silenceFrames >= 32 && atomic.LoadInt32(&isSpeaking) == 0 {

					log.Printf("\n🎤 [Voice] Phrase ended. Transcribing whole sequence via Whisper...")

					snapshot := aw.GetOrderedSequence()

					go func(frames [][]float32) {

						textTranscript := transcribeFullPhrase(frames)

						if textTranscript != "" {
							log.Printf("🤖 [Voice Transcribed]: \"%s\"", textTranscript)
							inputChan <- textTranscript
						}
					}(snapshot)

					isUserSpeaking = false
					silenceFrames = 0

					aw.mu.Lock()
					aw.filled = 0
					aw.mu.Unlock()

					ab.mu.Lock()
					ab.samples = ab.samples[:0]
					ab.mu.Unlock()
					continue
				}
			} else {
				ab.mu.Unlock()
			}
		}
	}
}

func transcribeFullPhrase(frames [][]float32) string {
	whisperBin, whisperModel, err := findWhisperBinaryAndModel()
	if err != nil {
		log.Printf("⚠️ Whisper not available: %v", err)
		return ""
	}

	rawTmp := filepath.Join(whisperTempDir, whisperRawTmp)
	wavTmp := filepath.Join(whisperTempDir, whisperWavTmp)

	_ = os.MkdirAll(whisperTempDir, 0755)

	f, err := os.Create(rawTmp)
	if err != nil {
		return ""
	}
	for _, frame := range frames {
		for _, s := range frame {
			sample16 := int16(s * 32768.0)
			_ = binary.Write(f, binary.LittleEndian, sample16)
		}
	}
	f.Close()

	exec.Command("ffmpeg", "-y", "-f", "s16le", "-ar", "16000", "-ac", "1", "-i", rawTmp, wavTmp).Run()

	devNull, _ := os.Open(os.DevNull)
	defer devNull.Close()
	wCmd := exec.Command(whisperBin, "-m", whisperModel, "-f", wavTmp, "-nt")
	wCmd.Stderr = devNull
	out, err := wCmd.Output()
	if err != nil {
		return ""
	}

	// Sanitize multi-line logs down to standard string text sentences
	var parts []string
	for _, line := range strings.Split(string(out), "\n") {
		t := strings.TrimSpace(line)
		if t != "" {
			parts = append(parts, t)
		}
	}

	return strings.Join(parts, " ")
}

type Record struct {
	ID		string		`json:"id"`
	Text		string		`json:"text"`
	Vector		[]float64	`json:"vector"`
	Timestamp	time.Time	`json:"timestamp"`
}

type VectorDB struct {
	mu	sync.RWMutex
	records	[]Record
	dim	int
	dbPath	string
}

func NewVectorDB(dim int, path string) *VectorDB {
	db := &VectorDB{
		records:	make([]Record, 0),
		dim:		dim,
		dbPath:		path,
	}
	db.Load()
	return db
}

// Embed generates a fast, pure Go vector representation of the text using a
// character n-gram hashing trick. This avoids heavy ML dependencies.
func (db *VectorDB) Embed(text string) []float64 {
	vec := make([]float64, db.dim)
	text = strings.ToLower(strings.TrimSpace(text))

	runes := []rune(text)
	for i := 0; i < len(runes)-2; i++ {
		trigram := string(runes[i : i+3])
		hash := sha256.Sum256([]byte(trigram))

		for j := 0; j < len(hash)-1; j += 2 {
			idx := (int(hash[j])<<8 | int(hash[j+1])) % db.dim
			vec[idx] += 1.0
		}
	}

	words := strings.Fields(text)
	for _, w := range words {
		hash := sha256.Sum256([]byte(w))
		for j := 0; j < len(hash)-1; j += 2 {
			idx := (int(hash[j])<<8 | int(hash[j+1])) % db.dim
			vec[idx] += 1.5
		}
	}

	// L2 Normalize
	var norm float64
	for _, v := range vec {
		norm += v * v
	}
	if norm > 0 {
		norm = math.Sqrt(norm)
		for i := range vec {
			vec[i] /= norm
		}
	}

	return vec
}

func (db *VectorDB) Insert(text string) {
	db.mu.Lock()
	defer db.mu.Unlock()

	vec := db.Embed(text)
	db.records = append(db.records, Record{
		ID:		time.Now().Format(time.RFC3339Nano),
		Text:		text,
		Vector:		vec,
		Timestamp:	time.Now(),
	})

	db.save()
}

type SearchResult struct {
	Record	Record
	Score	float64
}

// Search returns the top K most similar records.
func (db *VectorDB) Search(text string, topK int) []SearchResult {
	db.mu.RLock()
	defer db.mu.RUnlock()

	if len(db.records) == 0 {
		return nil
	}

	queryVec := db.Embed(text)

	var results []SearchResult
	for _, rec := range db.records {
		score := cosineSimilarity(queryVec, rec.Vector)

		if score > 0.1 {
			results = append(results, SearchResult{
				Record:	rec,
				Score:	score,
			})
		}
	}

	sort.Slice(results, func(i, j int) bool {
		return results[i].Score > results[j].Score
	})

	if len(results) > topK {
		results = results[:topK]
	}
	return results
}

func (db *VectorDB) save() error {
	if db.dbPath == "" {
		return nil
	}
	dir := filepath.Dir(db.dbPath)
	os.MkdirAll(dir, 0755)

	data, err := json.MarshalIndent(db.records, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(db.dbPath, data, 0644)
}

func (db *VectorDB) Load() error {
	if db.dbPath == "" {
		return nil
	}
	data, err := os.ReadFile(db.dbPath)
	if err != nil {
		return err
	}

	db.mu.Lock()
	defer db.mu.Unlock()
	return json.Unmarshal(data, &db.records)
}

func cosineSimilarity(a, b []float64) float64 {
	if len(a) != len(b) {
		return 0
	}
	var dotProduct, normA, normB float64
	for i := range a {
		dotProduct += a[i] * b[i]
		normA += a[i] * a[i]
		normB += b[i] * b[i]
	}
	if normA == 0 || normB == 0 {
		return 0
	}
	return dotProduct / (math.Sqrt(normA) * math.Sqrt(normB))
}

type AudioEncoder struct {
	InputDim	int		// Number of samples per frame (e.g., 400 samples for 25ms at 16kHz)
	DModel		int		// Output dimension (matches the MoE or TemporalEncoder input dimension)
	Weights		[]float32	// [InputDim * DModel]
}

// NewAudioEncoder initializes a new AudioEncoder with random Xavier weights.
func NewAudioEncoder(inputDim, dModel int) *AudioEncoder {
	ae := &AudioEncoder{
		InputDim:	inputDim,
		DModel:		dModel,
		Weights:	make([]float32, inputDim*dModel),
	}

	limit := float32(1.0 / float32(inputDim))
	for i := range ae.Weights {
		ae.Weights[i] = (rand.Float32()*2.0 - 1.0) * limit
	}

	return ae
}

// Forward linearly projects a sequence of raw audio frames into tokens.
func (ae *AudioEncoder) Forward(frames [][]float32) [][]float32 {
	if len(frames) == 0 {
		return nil
	}

	tokens := make([][]float32, len(frames))
	for i, frame := range frames {
		token := make([]float32, ae.DModel)
		for d := 0; d < ae.DModel; d++ {
			var sum float32
			for j := 0; j < ae.InputDim; j++ {
				sum += frame[j] * ae.Weights[j*ae.DModel+d]
			}
			token[d] = float32(math.Abs(float64(sum)))
		}
		tokens[i] = token
	}
	return tokens
}

// Backward computes gradients for the audio projection weights.
func (ae *AudioEncoder) Backward(frames [][]float32, dTokens [][]float32, lr float32) {
	for i, frame := range frames {
		dToken := dTokens[i]
		for d := 0; d < ae.DModel; d++ {
			// Recompute sum to get the sign
			var sum float32
			for j := 0; j < ae.InputDim; j++ {
				sum += frame[j] * ae.Weights[j*ae.DModel+d]
			}
			sign := float32(1.0)
			if sum < 0 {
				sign = -1.0
			}

			for j := 0; j < ae.InputDim; j++ {

				grad := frame[j] * dToken[d] * sign
				ae.Weights[j*ae.DModel+d] -= lr * grad
			}
		}
	}
}

