type CartridgeManager struct {
	requests	chan CartridgeRequest
	mu		sync.Mutex
	Loaded		map[string]Expert

	// LRU Cache & Centralized Context Pager
	lruOrder	[]string
	MaxWarm		int
	ContextPager	map[string][]float32
}

func getSlice(size int) []float32 {
	s := slicePool.Get().([]float32)
	if cap(s) < size {
		return make([]float32, size)
	}
	return s[:size]
}

func putSlice(s []float32) {
	if s == nil {
		return
	}

	slicePool.Put(s[:0])
}

func NewCartridgeManager() *CartridgeManager {
	cm := &CartridgeManager{
		requests:	make(chan CartridgeRequest, 10),
		Loaded:		make(map[string]Expert),
		MaxWarm:	3,
		ContextPager:	make(map[string][]float32),
	}
	go cm.loop()
	return cm
}

func (cm *CartridgeManager) loop() {
	for req := range cm.requests {
		switch req.Action {
		case "load":
			cm.mu.Lock()
			if _, exists := cm.Loaded[req.Path]; exists {
				cm.markUsed(req.Path)
				cm.mu.Unlock()
				if GlobalTelemetry != nil {
					GlobalTelemetry.RecordPoolHit()
					GlobalTelemetry.RecordTrace("cartridge", "pool_hit", map[string]interface{}{"path": req.Path})
				}
				req.Response <- nil
				continue
			}
			if GlobalTelemetry != nil {
				GlobalTelemetry.RecordPoolMiss()
				GlobalTelemetry.RecordTrace("cartridge", "pool_miss", map[string]interface{}{"path": req.Path})
			}
			cm.mu.Unlock()

			expert, err := cm.loadFromFile(req.Path)
			if err != nil {
				req.Response <- err
				continue
			}

			cm.mu.Lock()
			cm.Loaded[req.Path] = expert

			if ctx, exists := cm.ContextPager[req.Path]; exists {
				expert.RestoreContext(ctx)
				log.Printf("🧠 Cartridge Manager: Re-inflated memory context for %s", req.Path)
			}

			cm.markUsed(req.Path)
			cm.evictLRU()
			cm.mu.Unlock()
			if GlobalTelemetry != nil {
				GlobalTelemetry.SetWarmCartridges(len(cm.Loaded))
				GlobalTelemetry.RecordTrace("cartridge", "loaded", map[string]interface{}{"path": req.Path, "warm": len(cm.Loaded)})
			}
			_ = EmitRuntimeTelemetry("logs/telemetry.json", nil)
			log.Printf("🎮 Cartridge Manager: Loaded cartridge %s into RAM.", req.Path)
			req.Response <- nil
		case "unload":
			cm.mu.Lock()
			if expert, exists := cm.Loaded[req.Path]; exists {

				cm.ContextPager[req.Path] = expert.GetContext()

				cm.recycleExpert(expert)
				delete(cm.Loaded, req.Path)
				cm.removeFromLRU(req.Path)
				log.Printf("🎮 Cartridge Manager: UnLoaded cartridge %s from RAM. Context paged out.", req.Path)
			}
			cm.mu.Unlock()
			if GlobalTelemetry != nil {
				GlobalTelemetry.SetWarmCartridges(len(cm.Loaded))
				GlobalTelemetry.RecordTrace("cartridge", "unloaded", map[string]interface{}{"path": req.Path, "warm": len(cm.Loaded)})
			}
			_ = EmitRuntimeTelemetry("logs/telemetry.json", nil)
			req.Response <- nil
		}
	}
}

func (cm *CartridgeManager) markUsed(path string) {
	cm.removeFromLRU(path)
	cm.lruOrder = append(cm.lruOrder, path)
}

func (cm *CartridgeManager) removeFromLRU(path string) {
	for i, p := range cm.lruOrder {
		if p == path {
			cm.lruOrder = append(cm.lruOrder[:i], cm.lruOrder[i+1:]...)
			break
		}
	}
}

func (cm *CartridgeManager) evictLRU() {
	for len(cm.Loaded) > cm.MaxWarm && len(cm.lruOrder) > 0 {
		oldest := cm.lruOrder[0]
		if expert, exists := cm.Loaded[oldest]; exists {

			cm.ContextPager[oldest] = expert.GetContext()

			cm.recycleExpert(expert)
			delete(cm.Loaded, oldest)
			log.Printf("🧹 Cartridge Manager: LRU Evicted %s. Context paged out to Supervisor buffer.", oldest)
		}
		cm.lruOrder = cm.lruOrder[1:]
	}
}

func (cm *CartridgeManager) recycleExpert(expert Expert) {

	if ffe, ok := expert.(*FeedForwardExpert); ok {
		if ffe.Layer1 != nil && ffe.Layer1.Weights != nil {
			putSlice(ffe.Layer1.Weights.Data)
			if ffe.Layer1.Biases != nil {
				putSlice(ffe.Layer1.Biases.Data)
			}
		}
		if ffe.Layer2 != nil && ffe.Layer2.Weights != nil {
			putSlice(ffe.Layer2.Weights.Data)
			if ffe.Layer2.Biases != nil {
				putSlice(ffe.Layer2.Biases.Data)
			}
		}
	}
}

func (cm *CartridgeManager) loadFromFile(path string) (Expert, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("failed to open cartridge %s: %v", path, err)
	}
	defer file.Close()

	var header CartridgeHeader
	if err := binary.Read(file, binary.LittleEndian, &header); err != nil {
		return nil, fmt.Errorf("failed to read cartridge header %s: %v", path, err)
	}

	if string(header.Magic[:]) != "GLMR_CRT" {

		file.Seek(0, 0)
		var expert Expert
		decoder := gob.NewDecoder(file)
		if err := decoder.Decode(&expert); err != nil {
			return nil, fmt.Errorf("failed to decode gob cartridge %s: %v", path, err)
		}
		return expert, nil
	}

	expert, err := NewFeedForwardExpert(int(header.InputDim), int(header.HiddenDim), int(header.OutputDim))
	if err != nil {
		return nil, err
	}

	expert.Layer1.Weights.Data = getSlice(len(expert.Layer1.Weights.Data))
	if err := binary.Read(file, binary.LittleEndian, expert.Layer1.Weights.Data); err != nil {
		return nil, err
	}

	if expert.Layer1.Biases != nil {
		expert.Layer1.Biases.Data = getSlice(len(expert.Layer1.Biases.Data))
		if err := binary.Read(file, binary.LittleEndian, expert.Layer1.Biases.Data); err != nil {
			return nil, err
		}
	}

	expert.Layer2.Weights.Data = getSlice(len(expert.Layer2.Weights.Data))
	if err := binary.Read(file, binary.LittleEndian, expert.Layer2.Weights.Data); err != nil {
		return nil, err
	}

	if expert.Layer2.Biases != nil {
		expert.Layer2.Biases.Data = getSlice(len(expert.Layer2.Biases.Data))
		if err := binary.Read(file, binary.LittleEndian, expert.Layer2.Biases.Data); err != nil {
			return nil, err
		}
	}

	return expert, nil
}

// LoadCartridge sends a request to load a cartridge.
func (cm *CartridgeManager) LoadCartridge(path string, layerIdx, roleID int) error {
	resp := make(chan error, 1)
	cm.requests <- CartridgeRequest{
		Action:		"load",
		Path:		path,
		LayerIdx:	layerIdx,
		RoleID:		roleID,
		Response:	resp,
	}
	return <-resp
}

// UnloadCartridge sends a request to unload a cartridge.
func (cm *CartridgeManager) UnloadCartridge(path string) error {
	resp := make(chan error, 1)
	cm.requests <- CartridgeRequest{
		Action:		"unload",
		Path:		path,
		Response:	resp,
	}
	return <-resp
}

// PreloadCartridge sends a request to load a cartridge asynchronously.
// This enables zero-latency loading while the user is still typing.
func (cm *CartridgeManager) PreloadCartridge(path string, layerIdx, roleID int) {
	go func() {
		resp := make(chan error, 1)
		cm.requests <- CartridgeRequest{
			Action:		"load",
			Path:		path,
			LayerIdx:	layerIdx,
			RoleID:		roleID,
			Response:	resp,
		}

		<-resp
	}()
}

// Lock manually locks the CartridgeManager.
func (cm *CartridgeManager) Lock() {
	cm.mu.Lock()
}

// Unlock manually unlocks the CartridgeManager.
func (cm *CartridgeManager) Unlock() {
	cm.mu.Unlock()
}

// MountCartridgeToLayer adds a loaded expert to a specific MoE layer for hot-swapping.
func (s *Supervisor) MountCartridgeToLayer(model *IntentMoE, layerIdx int, expert Expert) (int, error) {
	layers := model.Encoder.GetMoELayers()
	if model.Decoder.OutputMoE != nil {
		layers = append(layers, model.Decoder.OutputMoE)
	}

	if layerIdx < 0 || layerIdx >= len(layers) {
		return -1, fmt.Errorf("MountCartridgeToLayer: layerIdx %d out of range", layerIdx)
	}
	layer := layers[layerIdx]

	s.mu.Lock()
	defer s.mu.Unlock()

	newID := len(layer.Experts)
	layer.Experts = append(layer.Experts, expert)
	layer.NumExperts++

	layer.ExpertOutputScale = append(layer.ExpertOutputScale, 1.0)
	layer.AccumulatedUtilization = append(layer.AccumulatedUtilization, 0)
	layer.ExpertFrozen = append(layer.ExpertFrozen, true)
	layer.StagnationCounters = append(layer.StagnationCounters, 0)
	layer.ExpertGradMultiplier = append(layer.ExpertGradMultiplier, 1.0)
	layer.ExpertHealth = append(layer.ExpertHealth, 1.0)
	layer.ExpertRole = append(layer.ExpertRole, "CARTRIDGE")

	if layer.GatingNetwork != nil {
		extendLinear := func(lin *nn.Linear, initWeight, initBias float32) {
			if lin == nil || lin.Weights == nil {
				return
			}
			gw := lin.Weights
			oldNumExperts := gw.Shape[1]
			newNumExperts := oldNumExperts + 1
			oldData := gw.Data
			newData := make([]float32, gw.Shape[0]*newNumExperts)
			for row := 0; row < gw.Shape[0]; row++ {
				copy(newData[row*newNumExperts:row*newNumExperts+oldNumExperts],
					oldData[row*oldNumExperts:row*oldNumExperts+oldNumExperts])
				newData[row*newNumExperts+oldNumExperts] = initWeight
			}
			lin.Weights = tensor.NewTensor([]int{gw.Shape[0], newNumExperts}, newData, true)

			if lin.Biases != nil {
				oldBias := lin.Biases.Data
				newBias := make([]float32, newNumExperts)
				copy(newBias, oldBias)
				newBias[oldNumExperts] = initBias
				lin.Biases = tensor.NewTensor([]int{newNumExperts}, newBias, true)
			}
		}

		if layer.GatingNetwork.Linear != nil {
			extendLinear(layer.GatingNetwork.Linear, 0.5, 2.0)
		}
		if layer.GatingNetwork.NoiseLinear != nil {
			extendLinear(layer.GatingNetwork.NoiseLinear, 0.0, 0.0)
		}
		layer.GatingNetwork.RepairArchitecture()
	}

	log.Printf("🔌 Cartridge Mounted: Expert %d added to Layer %d", newID, layerIdx)
	return newID, nil
}

// UnmountCartridgeFromLayer removes the dynamically added expert from a layer.
func (s *Supervisor) UnmountCartridgeFromLayer(model *IntentMoE, layerIdx int, expertIdx int) error {
	layers := model.Encoder.GetMoELayers()
	if model.Decoder.OutputMoE != nil {
		layers = append(layers, model.Decoder.OutputMoE)
	}

	if layerIdx < 0 || layerIdx >= len(layers) {
		return fmt.Errorf("UnmountCartridgeFromLayer: layerIdx out of range")
	}
	layer := layers[layerIdx]

	s.mu.Lock()
	defer s.mu.Unlock()

	if expertIdx < 0 || expertIdx >= len(layer.Experts) {
		return fmt.Errorf("UnmountCartridgeFromLayer: expertIdx out of range")
	}

	layer.Experts = append(layer.Experts[:expertIdx], layer.Experts[expertIdx+1:]...)
	layer.NumExperts--

	layer.ExpertOutputScale = append(layer.ExpertOutputScale[:expertIdx], layer.ExpertOutputScale[expertIdx+1:]...)
	layer.AccumulatedUtilization = append(layer.AccumulatedUtilization[:expertIdx], layer.AccumulatedUtilization[expertIdx+1:]...)
	layer.ExpertFrozen = append(layer.ExpertFrozen[:expertIdx], layer.ExpertFrozen[expertIdx+1:]...)
	layer.StagnationCounters = append(layer.StagnationCounters[:expertIdx], layer.StagnationCounters[expertIdx+1:]...)
	layer.ExpertGradMultiplier = append(layer.ExpertGradMultiplier[:expertIdx], layer.ExpertGradMultiplier[expertIdx+1:]...)
	layer.ExpertHealth = append(layer.ExpertHealth[:expertIdx], layer.ExpertHealth[expertIdx+1:]...)
	layer.ExpertRole = append(layer.ExpertRole[:expertIdx], layer.ExpertRole[expertIdx+1:]...)

	if layer.GatingNetwork != nil {
		shrinkLinear := func(lin *nn.Linear) {
			if lin == nil || lin.Weights == nil {
				return
			}
			gw := lin.Weights
			oldNumExperts := gw.Shape[1]
			newNumExperts := oldNumExperts - 1
			oldData := gw.Data
			newData := make([]float32, gw.Shape[0]*newNumExperts)
			for row := 0; row < gw.Shape[0]; row++ {
				copy(newData[row*newNumExperts:row*newNumExperts+expertIdx], oldData[row*oldNumExperts:row*oldNumExperts+expertIdx])
				copy(newData[row*newNumExperts+expertIdx:row*newNumExperts+newNumExperts], oldData[row*oldNumExperts+expertIdx+1:row*oldNumExperts+oldNumExperts])
			}
			lin.Weights = tensor.NewTensor([]int{gw.Shape[0], newNumExperts}, newData, true)

			if lin.Biases != nil {
				oldBias := lin.Biases.Data
				newBias := make([]float32, newNumExperts)
				copy(newBias[:expertIdx], oldBias[:expertIdx])
				copy(newBias[expertIdx:], oldBias[expertIdx+1:])
				lin.Biases = tensor.NewTensor([]int{newNumExperts}, newBias, true)
			}
		}

		if layer.GatingNetwork.Linear != nil {
			shrinkLinear(layer.GatingNetwork.Linear)
		}
		if layer.GatingNetwork.NoiseLinear != nil {
			shrinkLinear(layer.GatingNetwork.NoiseLinear)
		}
		layer.GatingNetwork.RepairArchitecture()
	}

	log.Printf("🔌 Cartridge Unmounted: Expert %d removed from Layer %d", expertIdx, layerIdx)
	return nil
}

