func init() {
	gob.Register(&RNNDecoder{})
}

// NewRNNDecoder creates a new RNNDecoder.
func NewRNNDecoder(inputDim, outputVocabSize, hiddenSize, maxAttentionHeads, numLayers int, dropoutRate float32, numExperts int) (*RNNDecoder, error) {

	lstmInputDim := inputDim

	lstm, err := nn.NewLSTM(lstmInputDim, hiddenSize, numLayers)
	if err != nil {
		return nil, fmt.Errorf("failed to create LSTM for decoder: %w", err)
	}
	lstm.DropoutRate = dropoutRate
	lstm.Training = true

	inputNorm := nn.NewLayerNorm(inputDim)
	hiddenNorm := nn.NewLayerNorm(hiddenSize)
	layerNorm := nn.NewLayerNorm(hiddenSize + inputDim)

	// Create output layer
	var outputLayer *nn.Linear
	var outputMoE *MoELayer

	if numExperts > 1 {
		expertBuilder := func(expertIdx int) (Expert, error) {
			return NewInternalExpert(expertIdx, hiddenSize+inputDim, (hiddenSize + inputDim), outputVocabSize)
		}
		moeLayer, err := NewMoELayer(hiddenSize+inputDim, outputVocabSize, numExperts, 2, expertBuilder)
		if err != nil {
			return nil, fmt.Errorf("failed to create MoE output layer: %w", err)
		}
		outputMoE = moeLayer
	} else {
		outputLayer, err = nn.NewLinear(hiddenSize+inputDim, outputVocabSize)
		if err != nil {
			return nil, fmt.Errorf("failed to create output linear layer: %w", err)
		}
	}

	embedding := nn.NewEmbedding(outputVocabSize, inputDim)

	attention, err := nn.NewMultiHeadCrossAttention(hiddenSize, inputDim, inputDim, maxAttentionHeads, maxAttentionHeads)
	if err != nil {
		return nil, fmt.Errorf("failed to create multi-head attention for decoder: %w", err)
	}

	return &RNNDecoder{
		LSTM:			lstm,
		InputNorm:		inputNorm,
		HiddenNorm:		hiddenNorm,
		LayerNorm:		layerNorm,
		OutputLayer:		outputLayer,
		OutputMoE:		outputMoE,
		OutputVocabSize:	outputVocabSize,
		Embedding:		embedding,
		MaxAttentionHeads:	maxAttentionHeads,
		Attention:		attention,
		ContextMultiplier:	10.0,
		ContextMultiplierDecay:	1.0,
	}, nil
}

// Forward performs the forward pass of the RNNDecoder.
func (d *RNNDecoder) Forward(contextVector, targetSequence *Tensor, scheduledSamplingProb float32, mask ...*Tensor) ([]*Tensor, error) {
	var attentionMask *Tensor
	if len(mask) > 0 {
		attentionMask = mask[0]
	}
	if len(contextVector.Shape) != 3 {
		return nil, fmt.Errorf("contextVector must be 3D tensor [batchSize, sequenceLength, embeddingDim], got shape %v", contextVector.Shape)
	}
	if len(targetSequence.Shape) != 2 {
		return nil, fmt.Errorf("targetSequence must be 2D tensor [batchSize, sequenceLength], got shape %v", targetSequence.Shape)
	}

	batchSize := targetSequence.Shape[0]
	maxSequenceLength := targetSequence.Shape[1]
	var err error
	hiddenSize := d.LSTM.HiddenSize
	d.contextVector = contextVector
	d.attentionMask = attentionMask

	initialHidden, err := contextVector.Mean(1)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate initial hidden state: %w", err)
	}
	dim := contextVector.Shape[2]
	initialHidden, _ = initialHidden.Reshape([]int{batchSize, dim})

	if initialHidden.Shape[1] != hiddenSize {
		if initialHidden.Shape[1] > hiddenSize {
			initialHidden, _ = initialHidden.Slice(1, 0, hiddenSize)
		} else {
			padding := NewTensor([]int{batchSize, hiddenSize - initialHidden.Shape[1]}, make([]float32, batchSize*(hiddenSize-initialHidden.Shape[1])), false)
			initialHidden, _ = Concat([]*Tensor{initialHidden, padding}, 1)
		}
	}

	hiddenState := initialHidden
	cellState, _ := initialHidden.Slice(0, 0, batchSize)
	if cellState.Shape[1] != hiddenSize {

		if cellState.Shape[1] > hiddenSize {
			cellState, _ = cellState.Slice(1, 0, hiddenSize)
		} else {
			padding := NewTensor([]int{batchSize, hiddenSize - cellState.Shape[1]}, make([]float32, batchSize*(hiddenSize-cellState.Shape[1])), false)
			cellState, _ = Concat([]*Tensor{cellState, padding}, 1)
		}
	}

	ctxMean, _ := d.contextVector.Mean(1)
	ctxMeanNorm := ctxMean.L2Norm()
	// 🛡️ NUMERICAL STABILITY: Use larger epsilon and cap the scaling factor
	// to prevent signal explosion when the context is weak (near zero).
	const ctxEpsilon = 1e-5
	if ctxMeanNorm > ctxEpsilon {
		scale := 1.0 / ctxMeanNorm
		if scale > 10.0 {
			scale = 10.0
		}
		ctxMean = ctxMean.Scale(scale)
	}
	ctxMeanReshaped, _ := ctxMean.Reshape([]int{batchSize, 1, d.contextVector.Shape[2]})

	if scheduledSamplingProb == 0.0 {
		fullInput, _ := targetSequence.Slice(1, 0, maxSequenceLength-1)
		allEmbedded, _ := d.Embedding.Forward(fullInput)
		normedEmbedded, _ := d.InputNorm.Forward(allEmbedded)

		if d.ContextMultiplierDecay > 0 && d.ContextMultiplierDecay < 1.0 {
			decayData := make([]float32, maxSequenceLength-1)
			scale := d.ContextMultiplier
			for t := 0; t < maxSequenceLength-1; t++ {
				decayData[t] = scale
				scale *= d.ContextMultiplierDecay
			}
			decayTensor := NewTensor([]int{1, maxSequenceLength - 1, 1}, decayData, false)
			scaledCtx, _ := ctxMeanReshaped.MulWithBroadcast(decayTensor)
			normedEmbedded, _ = normedEmbedded.AddWithBroadcast(scaledCtx)
			scaledCtx.Release()
			decayTensor.Release()
		} else {
			normedEmbedded, _ = normedEmbedded.AddWithBroadcast(ctxMeanReshaped.Scale(d.ContextMultiplier))
		}

		allHidden, lastCell, err := d.LSTM.Forward(normedEmbedded, initialHidden, cellState)
		if err != nil {
			return nil, fmt.Errorf("vectorized LSTM failed: %w", err)
		}
		cellState = lastCell

		normedHidden, err := d.HiddenNorm.Forward(allHidden)
		if err != nil {
			return nil, err
		}

		allAttention, err := d.Attention.Forward(normedHidden, contextVector, contextVector, attentionMask)
		if err != nil {
			return nil, fmt.Errorf("vectorized attention failed: %w", err)
		}

		combined, err := Concat([]*Tensor{allHidden, allAttention}, 2)
		if err != nil {
			return nil, err
		}

		normed, err := d.LayerNorm.Forward(combined)
		if err != nil {
			return nil, err
		}

		var allLogits *Tensor
		if d.OutputMoE != nil {
			allLogits, err = d.OutputMoE.Forward(normed)
		} else {
			allLogits, err = d.OutputLayer.Forward(normed)
		}
		if err != nil {
			return nil, err
		}

		d.hiddenStates = []*Tensor{allHidden}
		d.InitialHiddenState = initialHidden
		d.InitialCellState = cellState
		d.attentionOutputs = []*Tensor{allAttention}
		d.combinedInputs = []*Tensor{combined}

		return []*Tensor{allLogits}, nil
	}

	var outputs []*Tensor
	d.hiddenStates = make([]*Tensor, 0, maxSequenceLength-1)
	d.cellStates = make([]*Tensor, 0, maxSequenceLength-1)
	d.embeddedInputs = make([]*Tensor, 0, maxSequenceLength-1)
	d.attentionOutputs = make([]*Tensor, 0, maxSequenceLength-1)
	d.combinedInputs = make([]*Tensor, 0, maxSequenceLength-1)
	d.decoderInputs = make([]*Tensor, 0, maxSequenceLength-1)

	decoderInput, _ := targetSequence.Slice(1, 0, 1)

	for t := 0; t < maxSequenceLength-1; t++ {
		d.decoderInputs = append(d.decoderInputs, decoderInput)
		embeddedInput, _ := d.Embedding.Forward(decoderInput)
		d.embeddedInputs = append(d.embeddedInputs, embeddedInput)

		normedIn, _ := d.InputNorm.Forward(embeddedInput)
		stepScale := d.ContextMultiplier * float32(math.Pow(float64(d.ContextMultiplierDecay), float64(t)))
		normedIn, _ = normedIn.AddWithBroadcast(ctxMeanReshaped.Scale(stepScale))

		reshapedIn, _ := normedIn.Reshape([]int{batchSize, embeddedInput.Shape[2]})

		if len(reshapedIn.Data) > 0 && math.IsNaN(float64(reshapedIn.Data[0])) {
			fmt.Printf("⚠️ [Decoder] NaNs detected in LSTM input at step %d! Resetting to zero.\n", t)
			for i := range reshapedIn.Data {
				reshapedIn.Data[i] = 0
			}
		}

		hiddenState, cellState, err = d.LSTM.Forward(reshapedIn, hiddenState, cellState)
		if err != nil {
			return nil, err
		}
		d.hiddenStates = append(d.hiddenStates, hiddenState)
		d.cellStates = append(d.cellStates, cellState)

		hiddenQuery, _ := hiddenState.Reshape([]int{batchSize, 1, hiddenSize})
		normedHidden, _ := d.HiddenNorm.Forward(hiddenQuery)

		attentionOutput, err := d.Attention.Forward(normedHidden, contextVector, contextVector, attentionMask)
		if err != nil {
			return nil, err
		}
		d.attentionOutputs = append(d.attentionOutputs, attentionOutput)

		combined, _ := Concat([]*Tensor{hiddenQuery, attentionOutput}, 2)
		d.combinedInputs = append(d.combinedInputs, combined)

		normed, _ := d.LayerNorm.Forward(combined)
		var outputLogits *Tensor
		var fwdErr error
		if d.OutputMoE != nil {
			outputLogits, fwdErr = d.OutputMoE.Forward(normed)
		} else {
			outputLogits, fwdErr = d.OutputLayer.Forward(normed)
		}

		if fwdErr != nil {
			return nil, fmt.Errorf("decoder output forward failed: %w", fwdErr)
		}
		if outputLogits == nil {
			return nil, fmt.Errorf("decoder output forward returned nil tensor")
		}

		resLogits, err := outputLogits.Reshape([]int{batchSize, d.OutputVocabSize})
		if err != nil {
			return nil, fmt.Errorf("decoder output reshape failed: %w (outputLogits shape: %v, expected: [%d, %d])",
				err, outputLogits.Shape, batchSize, d.OutputVocabSize)
		}
		outputs = append(outputs, resLogits)

		if t < maxSequenceLength-2 {
			if rand.Float32() < scheduledSamplingProb {

				nextTokens := make([]float32, batchSize)
				for b := 0; b < batchSize; b++ {

					itemLogits, _ := resLogits.Slice(0, b, b+1)

					sampledID, err := SampleFromLogits(itemLogits, 0.8, 0, 0.9)
					if err != nil {

						argmax, _ := itemLogits.Argmax(1)
						sampledID = int(argmax.Data[0])
					}
					nextTokens[b] = float32(sampledID)
				}
				decoderInput = NewTensor([]int{batchSize, 1}, nextTokens, false)
			} else {
				decoderInput, _ = targetSequence.Slice(1, t+1, t+2)
			}
		}
	}

	d.InitialHiddenState = initialHidden
	d.InitialCellState = cellState
	ctxMean.Release()
	ctxMeanReshaped.Release()
	return outputs, nil
}

// ClearState clears the intermediate states of the decoder to free memory.
func (d *RNNDecoder) ClearState() {
	for _, t := range d.hiddenStates {
		if t != nil {
			t.Release()
		}
	}
	for _, t := range d.cellStates {
		if t != nil {
			t.Release()
		}
	}
	for _, t := range d.embeddedInputs {
		if t != nil {
			t.Release()
		}
	}
	for _, t := range d.attentionOutputs {
		if t != nil {
			t.Release()
		}
	}
	for _, t := range d.combinedInputs {
		if t != nil {
			t.Release()
		}
	}
	for _, t := range d.decoderInputs {
		if t != nil {
			t.Release()
		}
	}
	if d.InitialHiddenState != nil {
		d.InitialHiddenState.Release()
	}
	if d.InitialCellState != nil {
		d.InitialCellState.Release()
	}
	if d.contextVector != nil {
		d.contextVector.Release()
	}

	d.hiddenStates = nil
	d.cellStates = nil
	d.embeddedInputs = nil
	d.attentionOutputs = nil
	d.combinedInputs = nil
	d.decoderInputs = nil
	d.InitialHiddenState = nil
	d.InitialCellState = nil

	if d.LSTM != nil {
		d.LSTM.ClearState()
	}
	if d.Attention != nil {
		d.Attention.ClearState()
	}
	if d.OutputLayer != nil {
		d.OutputLayer.ClearState()
	}
	if d.OutputMoE != nil {
		d.OutputMoE.ClearState()
	}
	if d.Embedding != nil {
		d.Embedding.ClearState()
	}
	if d.LastQueryTokens != nil {
		d.LastQueryTokens.Release()
	}
	if d.LastTargetTokens != nil {
		d.LastTargetTokens.Release()
	}
	d.LastQueryTokens = nil
	d.LastTargetTokens = nil
	d.contextVector = nil
}

// Backward performs the backward pass of the RNNDecoder with proper BPTT.
func (d *RNNDecoder) Backward(grads []*Tensor) error {
	if len(grads) == 0 {
		return nil
	}

	batchSize := grads[0].Shape[0]
	hiddenSize := d.LSTM.HiddenSize
	embeddingDim := d.Embedding.DimModel

	var allGrads *Tensor
	var allInputs, allEmbedded, allHidden, allAttention, combined, normed *Tensor
	var reshapedGrads []*Tensor

	if len(grads) == 1 && len(grads[0].Shape) == 3 {
		allGrads = grads[0]
	} else {

		reshapedGrads = make([]*Tensor, len(grads))
		for i, g := range grads {
			reshapedGrads[i], _ = g.Reshape([]int{batchSize, 1, d.OutputVocabSize})
		}
		var err error
		allGrads, err = Concat(reshapedGrads, 1)
		if err != nil {
			return fmt.Errorf("failed to concat gradients for vectorized backward: %w", err)
		}

		allInputs, err = Concat(d.decoderInputs, 1)
		if err != nil {
			return fmt.Errorf("failed to concat decoder inputs: %w", err)
		}
		allEmbedded, _ = d.Embedding.Forward(allInputs)

		ctxMean, _ := d.contextVector.Mean(1)
		ctxMeanReshaped, _ := ctxMean.Reshape([]int{batchSize, 1, d.contextVector.Shape[2]})

		allEmbedded, _ = d.InputNorm.Forward(allEmbedded)

		if d.ContextMultiplierDecay > 0 && d.ContextMultiplierDecay < 1.0 {
			seqLen := allEmbedded.Shape[1]
			decayData := make([]float32, seqLen)
			scale := d.ContextMultiplier
			for t := 0; t < seqLen; t++ {
				decayData[t] = scale
				scale *= d.ContextMultiplierDecay
			}
			decayTensor := NewTensor([]int{1, seqLen, 1}, decayData, false)
			scaledCtx, _ := ctxMeanReshaped.MulWithBroadcast(decayTensor)
			allEmbedded, _ = allEmbedded.AddWithBroadcast(scaledCtx)
			scaledCtx.Release()
			decayTensor.Release()
		} else {
			ctxScaled := ctxMeanReshaped.Scale(d.ContextMultiplier)
			allEmbedded, _ = allEmbedded.AddWithBroadcast(ctxScaled)
			ctxScaled.Release()
		}

		allHidden, _, err = d.LSTM.Forward(allEmbedded, d.InitialHiddenState, initialCell(batchSize, hiddenSize))
		if err != nil {
			return fmt.Errorf("LSTM forward failed during backward re-vectorization: %w", err)
		}

		allHidden, _ = d.HiddenNorm.Forward(allHidden)

		allAttention, err = d.Attention.Forward(allHidden, d.contextVector, d.contextVector, d.attentionMask)
		if err != nil {
			return fmt.Errorf("attention forward failed during backward re-vectorization: %w", err)
		}

		combined, err = Concat([]*Tensor{allHidden, allAttention}, 2)
		if err != nil {
			return fmt.Errorf("concat failed during backward re-vectorization: %w", err)
		}
		normed, err = d.LayerNorm.Forward(combined)
		if err != nil {
			return fmt.Errorf("layer norm failed during backward re-vectorization: %w", err)
		}
		if d.OutputMoE != nil {
			_, err = d.OutputMoE.Forward(normed)
		} else {
			_, err = d.OutputLayer.Forward(normed)
		}
		if err != nil {
			return fmt.Errorf("output layer forward failed during backward re-vectorization: %w", err)
		}
	}

	// --- Optimized Vectorized Backward Path ---
	// 1. Output Layer Backward
	var normedGrad *Tensor
	if d.OutputMoE != nil {
		if err := d.OutputMoE.Backward(allGrads); err != nil {
			return fmt.Errorf("output MoE backward failed: %w", err)
		}
		if len(d.OutputMoE.Inputs()) > 0 {
			normedGrad = d.OutputMoE.Inputs()[0].Grad
		}
	} else if d.OutputLayer != nil {
		if err := d.OutputLayer.Backward(allGrads); err != nil {
			return fmt.Errorf("output layer backward failed: %w", err)
		}
		normedGrad = d.OutputLayer.Input().Grad
	}

	if err := d.LayerNorm.Backward(normedGrad); err != nil {
		return fmt.Errorf("layer norm backward failed: %w", err)
	}
	combinedGrad := d.LayerNorm.Input().Grad

	splits, err := Split(combinedGrad, 2, []int{hiddenSize, embeddingDim})
	if err != nil {
		return fmt.Errorf("combined grad split failed: %w", err)
	}
	hiddenGradFromOutput := splits[0]
	attentionGrad := splits[1]

	if d.Attention != nil && d.Attention.GetAttentionWeights() != nil && d.LastQueryTokens != nil && d.LastTargetTokens != nil && len(d.TokenToWord) > 0 {
		wShape := d.Attention.GetAttentionWeights().Shape
		b0 := wShape[0]
		h0 := wShape[1]
		qSeq := wShape[2]
		kvSeq := wShape[3]

		rewardData := make([]float32, b0*h0*qSeq*kvSeq)

		getWord := func(tokID float32) string {
			idx := int(tokID)
			if idx >= 0 && idx < len(d.TokenToWord) {
				return d.TokenToWord[idx]
			}
			return ""
		}

		for b := 0; b < b0; b++ {
			for t := 0; t < qSeq; t++ {
				var targetWord string
				targetIdx := b*qSeq + t
				if targetIdx < len(d.LastTargetTokens.Data) {
					targetWord = getWord(d.LastTargetTokens.Data[targetIdx])
				}

				if targetWord != "" && isVerbOrAux(targetWord) {
					for q := 0; q < kvSeq; q++ {
						var queryWord string
						queryIdx := b*kvSeq + q
						if queryIdx < len(d.LastQueryTokens.Data) {
							queryWord = getWord(d.LastQueryTokens.Data[queryIdx])
						}

						if queryWord != "" && isPronoun(queryWord) {
							for h := 0; h < h0; h++ {
								offset := ((b*h0+h)*qSeq+t)*kvSeq + q
								rewardData[offset] = -0.08
							}
						}
					}
				}
			}
		}

		d.Attention.AttentionWeightsReward = NewTensor(wShape, rewardData, false)
	}

	if err := d.Attention.Backward(attentionGrad); err != nil {
		return fmt.Errorf("attention backward failed: %w", err)
	}
	normedHiddenGrad := d.Attention.Query().Grad

	if err := d.HiddenNorm.Backward(normedHiddenGrad); err != nil {
		return fmt.Errorf("hidden norm backward failed: %w", err)
	}
	hiddenGradFromAttention := d.HiddenNorm.Input().Grad

	totalHiddenGrad := hiddenGradFromOutput
	if hiddenGradFromAttention != nil {
		totalHiddenGrad, err = hiddenGradFromOutput.Add(hiddenGradFromAttention)
		if err != nil {
			return fmt.Errorf("failed to add hidden gradients: %w", err)
		}
	}

	zeroCellGrad := NewTensor(initialCell(batchSize, hiddenSize).Shape, make([]float32, batchSize*hiddenSize), false)
	if err := d.LSTM.Backward(totalHiddenGrad, zeroCellGrad); err != nil {
		return fmt.Errorf("LSTM backward failed: %w", err)
	}

	lstmInputGrad := d.LSTM.GetInputGrad()
	if err := d.InputNorm.Backward(lstmInputGrad); err != nil {
		return fmt.Errorf("input norm backward failed: %w", err)
	}

	if lstmInputGrad != nil {

		if err := d.Embedding.Backward(d.InputNorm.Input().Grad); err != nil {
			return err
		}

		if d.ContextMultiplierDecay > 0 && d.ContextMultiplierDecay < 1.0 {
			seqLen := lstmInputGrad.Shape[1]
			decayData := make([]float32, seqLen)
			scale := d.ContextMultiplier
			for t := 0; t < seqLen; t++ {
				decayData[t] = scale
				scale *= d.ContextMultiplierDecay
			}
			decayTensor := NewTensor([]int{1, seqLen, 1}, decayData, false)

			decayedGrads, _ := lstmInputGrad.MulWithBroadcast(decayTensor)
			gradCtxMeanFromInputs, _ := decayedGrads.Sum(1)
			gradCtxMean := gradCtxMeanFromInputs.Scale(1.0)

			initialHiddenGrad := d.LSTM.GetPrevHiddenGrad()
			if initialHiddenGrad != nil {
				oldGrad := gradCtxMean
				gradCtxMean, _ = gradCtxMean.Add(initialHiddenGrad)
				oldGrad.Release()
			}

			encSeqLen := d.contextVector.Shape[1]
			distGrad := gradCtxMean.Scale(1.0 / float32(encSeqLen))
			expandedGrad := distGrad.Expand([]int{batchSize, encSeqLen, embeddingDim})

			if d.contextVector.Grad == nil {
				d.contextVector.Grad = expandedGrad
			} else {
				oldGrad := d.contextVector.Grad
				d.contextVector.Grad, _ = d.contextVector.Grad.Add(expandedGrad)
				oldGrad.Release()
				expandedGrad.Release()
			}

			decayedGrads.Release()
			decayTensor.Release()
			gradCtxMeanFromInputs.Release()
			gradCtxMean.Release()
			distGrad.Release()
		} else {

			gradCtxMeanFromInputs, _ := lstmInputGrad.Sum(1)
			gradCtxMean := gradCtxMeanFromInputs.Scale(d.ContextMultiplier)

			initialHiddenGrad := d.LSTM.GetPrevHiddenGrad()
			if initialHiddenGrad != nil {
				oldGrad := gradCtxMean
				gradCtxMean, _ = gradCtxMean.Add(initialHiddenGrad)
				oldGrad.Release()
			}

			encSeqLen := d.contextVector.Shape[1]
			distGrad := gradCtxMean.Scale(1.0 / float32(encSeqLen))
			expandedGrad := distGrad.Expand([]int{batchSize, encSeqLen, embeddingDim})

			if d.contextVector.Grad == nil {
				d.contextVector.Grad = expandedGrad
			} else {
				oldGrad := d.contextVector.Grad
				d.contextVector.Grad, _ = d.contextVector.Grad.Add(expandedGrad)
				oldGrad.Release()
				expandedGrad.Release()
			}

			gradCtxMeanFromInputs.Release()
			gradCtxMean.Release()
			distGrad.Release()
		}
	}

	if allGrads != nil && len(grads) > 1 {
		allGrads.Release()
	}
	for _, g := range reshapedGrads {
		if g != nil {
			g.Release()
		}
	}
	if allInputs != nil {
		allInputs.Release()
	}
	if allEmbedded != nil {
		allEmbedded.Release()
	}
	if allHidden != nil {
		allHidden.Release()
	}
	if allAttention != nil {
		allAttention.Release()
	}
	if combined != nil {
		combined.Release()
	}
	if normed != nil {
		normed.Release()
	}

	if zeroCellGrad != nil {
		zeroCellGrad.Release()
	}
	if totalHiddenGrad != nil && totalHiddenGrad != hiddenGradFromOutput {
		totalHiddenGrad.Release()
	}

	return nil
}

func initialCell(batchSize, hiddenSize int) *Tensor {
	return NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), false)
}

// DecodeStep performs a single decoding step.
func (d *RNNDecoder) DecodeStep(inputToken *Tensor, prevHiddenState, prevCellState, contextVector *Tensor, stepIndex int, mask ...*Tensor) (*Tensor, *Tensor, *Tensor, *Tensor, error) {
	var attentionMask *Tensor
	if len(mask) > 0 {
		attentionMask = mask[0]
	}
	batchSize := inputToken.Shape[0]
	hiddenSize := d.LSTM.HiddenSize

	if prevHiddenState == nil {
		prevHiddenState = NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), false)
	}
	if prevCellState == nil {
		prevCellState = NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), false)
	}

	embeddedInput, err := d.Embedding.Forward(inputToken)
	if err != nil {
		return nil, nil, nil, nil, err
	}

	normedIn, _ := d.InputNorm.Forward(embeddedInput)

	ctxMean, _ := contextVector.Mean(1)
	ctxMeanNorm := ctxMean.L2Norm()
	const ctxEpsilon = 1e-5
	if ctxMeanNorm > ctxEpsilon {
		scale := 1.0 / ctxMeanNorm
		if scale > 10.0 {
			scale = 10.0
		}
		ctxMean = ctxMean.Scale(scale)
	}
	ctxMeanReshaped, _ := ctxMean.Reshape([]int{batchSize, 1, contextVector.Shape[2]})

	decayedMultiplier := d.ContextMultiplier
	if d.ContextMultiplierDecay > 0 && d.ContextMultiplierDecay < 1.0 && stepIndex > 0 {
		decayedMultiplier *= float32(math.Pow(float64(d.ContextMultiplierDecay), float64(stepIndex)))
		if decayedMultiplier < 0.5 {
			decayedMultiplier = 0.5
		}
	}
	normedIn, _ = normedIn.AddWithBroadcast(ctxMeanReshaped.Scale(decayedMultiplier))

	reshapedIn, _ := normedIn.Reshape([]int{batchSize, embeddedInput.Shape[2]})
	hiddenState, cellState, err := d.LSTM.Forward(reshapedIn, prevHiddenState, prevCellState)
	if err != nil {
		return nil, nil, nil, nil, err
	}

	hiddenQuery, _ := hiddenState.Reshape([]int{batchSize, 1, hiddenSize})
	normedHidden, _ := d.HiddenNorm.Forward(hiddenQuery)

	attentionOutput, err := d.Attention.Forward(normedHidden, contextVector, contextVector, attentionMask)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	// Capture attention weights (before they are cleared)
	var attWeights *Tensor
	if d.Attention != nil {
		attWeights = d.Attention.GetAttentionWeights()
	}

	combined, _ := Concat([]*Tensor{hiddenQuery, attentionOutput}, 2)
	normed, _ := d.LayerNorm.Forward(combined)

	var outputLogits *Tensor
	if d.OutputMoE != nil {

		d.OutputMoE.CurrentStepIndex = stepIndex
		outputLogits, err = d.OutputMoE.Forward(normed)
	} else {
		outputLogits, err = d.OutputLayer.Forward(normed)
	}
	if err != nil {
		return nil, nil, nil, nil, err
	}

	resLogits, _ := outputLogits.Reshape([]int{batchSize, d.OutputVocabSize})
	return resLogits, hiddenState, cellState, attWeights, nil
}

// DecodeStepWithExpert is like DecodeStep but also returns the ID of the top expert used.
func (d *RNNDecoder) DecodeStepWithExpert(input *Tensor, prevHiddenState, prevCellState, contextVector *Tensor, stepIndex int) (*Tensor, *Tensor, *Tensor, []int, *Tensor, error) {
	logits, h, c, att, err := d.DecodeStep(input, prevHiddenState, prevCellState, contextVector, stepIndex)
	if err != nil {
		return nil, nil, nil, nil, nil, err
	}

	expertIDs := []int{}
	if d.OutputMoE != nil && len(d.OutputMoE.SelectedExperts) > 0 {
		expertIDs = d.OutputMoE.SelectedExperts[0]
	} else if d.OutputLayer != nil {
		expertIDs = []int{0}
	}

	return logits, h, c, expertIDs, att, nil
}

// Parameters returns all learnable parameters of the RNNDecoder.
func (d *RNNDecoder) Parameters() []*Tensor {
	params := []*Tensor{}
	params = append(params, d.Embedding.Parameters()...)
	params = append(params, d.LSTM.Parameters()...)
	if d.InputNorm != nil {
		params = append(params, d.InputNorm.Parameters()...)
	}
	if d.HiddenNorm != nil {
		params = append(params, d.HiddenNorm.Parameters()...)
	}
	if d.LayerNorm != nil {
		params = append(params, d.LayerNorm.Parameters()...)
	}
	if d.OutputLayer != nil {
		params = append(params, d.OutputLayer.Parameters()...)
	}
	if d.OutputMoE != nil {
		params = append(params, d.OutputMoE.Parameters()...)
	}
	params = append(params, d.Attention.Parameters()...)
	return params
}

// ResizeOutputLayer resizes the output layer and embedding layer to match a new vocabulary size, while preserving existing weights.
// Memory strategy: old data slices are explicitly zeroed/nilled before allocating new ones so the
// old and new buffers don't coexist at peak, reducing peak RSS by ~50% during resize.
func (d *RNNDecoder) ResizeOutputLayer(newSize int) {
	oldVocabSize := d.OutputVocabSize
	d.OutputVocabSize = newSize
	inputDim := d.LSTM.HiddenSize + d.Embedding.DimModel
	dimModel := d.Embedding.DimModel

	copyLimit := oldVocabSize
	if newSize < copyLimit {
		copyLimit = newSize
	}

	newEmbData := make([]float32, newSize*dimModel)
	oldEmbData := d.Embedding.Weight.Data
	for i := 0; i < copyLimit; i++ {
		start := i * dimModel
		copy(newEmbData[start:start+dimModel], oldEmbData[start:start+dimModel])
	}

	d.Embedding.Weight.Data = nil
	d.Embedding.Weight = nil
	d.Embedding = nil
	runtime.GC()

	newEmb := nn.NewEmbedding(newSize, dimModel)
	newEmb.Weight.Data = newEmbData
	d.Embedding = newEmb
	newEmbData = nil

	if d.OutputLayer != nil {

		oldLayerWeights := d.OutputLayer.Weights.Data
		oldLayerBiases := d.OutputLayer.Biases.Data

		newWeights := make([]float32, inputDim*newSize)
		for i := 0; i < inputDim; i++ {
			oldStart := i * oldVocabSize
			newStart := i * newSize
			copy(newWeights[newStart:newStart+copyLimit], oldLayerWeights[oldStart:oldStart+copyLimit])
		}

		newBiases := make([]float32, newSize)
		for j := 0; j < copyLimit && j < len(oldLayerBiases); j++ {
			newBiases[j] = oldLayerBiases[j]
		}

		d.OutputLayer.Weights.Data = nil
		d.OutputLayer.Biases.Data = nil
		d.OutputLayer.Weights = nil
		d.OutputLayer.Biases = nil
		d.OutputLayer = nil
		runtime.GC()

		newLinear, _ := nn.NewLinear(inputDim, newSize)
		newLinear.Weights.Data = newWeights
		newLinear.Biases.Data = newBiases
		d.OutputLayer = newLinear

	} else if d.OutputMoE != nil {

		d.OutputMoE.ResizeExperts(newSize)
	}

	if d.LayerNorm == nil || d.LayerNorm.NormalizedShape != inputDim {
		d.LayerNorm = nn.NewLayerNorm(inputDim)
	}
}

// ToGPU moves the decoder's parameters to the GPU.
func (d *RNNDecoder) ToGPU() {
	if d.LSTM != nil {
		d.LSTM.ToGPU()
	}
	if d.InputNorm != nil {
		d.InputNorm.ToGPU()
	}
	if d.HiddenNorm != nil {
		d.HiddenNorm.ToGPU()
	}
	if d.LayerNorm != nil {
		d.LayerNorm.ToGPU()
	}
	if d.OutputLayer != nil {
		d.OutputLayer.ToGPU()
	}
	if d.OutputMoE != nil {
		d.OutputMoE.ToGPU()
	}
	if d.Embedding != nil {
		d.Embedding.ToGPU()
	}
	if d.Attention != nil {
		d.Attention.ToGPU()
	}
}

func (d *RNNDecoder) SyncParameters() error {
	if d.OutputMoE != nil {
		return d.OutputMoE.SyncParameters()
	}
	return nil
}

// SetMode sets the decoder to training or inference mode.
func (d *RNNDecoder) SetMode(training bool) {
	if d.LSTM != nil {
		d.LSTM.Training = training
	}
	if d.OutputMoE != nil {
		d.OutputMoE.SetMode(training)
	}
	if d.Attention != nil {
		d.Attention.SetMode(training)
	}
}

func (d *RNNDecoder) RepairArchitecture() {
	if d.InputNorm == nil {
		d.InputNorm = nn.NewLayerNorm(d.Embedding.DimModel)
	}
	if d.HiddenNorm == nil {
		d.HiddenNorm = nn.NewLayerNorm(d.LSTM.HiddenSize)
	}
	if d.OutputMoE != nil {
		d.OutputMoE.RepairArchitecture()
	}
}

// Step performs a single step of decoding (used for inference and diagnostics)
func (d *RNNDecoder) Step(tokenID int, contextVector, prevHidden, prevCell *Tensor) (*Tensor, *Tensor, *Tensor, error) {
	batchSize := 1
	if prevHidden != nil {
		batchSize = prevHidden.Shape[0]
	}

	if prevHidden == nil {
		prevHidden = NewTensor([]int{batchSize, d.LSTM.HiddenSize}, make([]float32, batchSize*d.LSTM.HiddenSize), false)
	}
	if prevCell == nil {
		prevCell = NewTensor([]int{batchSize, d.LSTM.HiddenSize}, make([]float32, batchSize*d.LSTM.HiddenSize), false)
	}

	inputT := NewTensor([]int{batchSize, 1}, []float32{float32(tokenID)}, false)
	embedded, err := d.Embedding.Forward(inputT)
	if err != nil {
		return nil, nil, nil, err
	}

	normedIn, _ := d.InputNorm.Forward(embedded)

	ctxMean, _ := contextVector.Mean(1)
	ctxMeanNorm := ctxMean.L2Norm()
	if ctxMeanNorm > 1e-8 {
		ctxMean = ctxMean.Scale(1.0 / ctxMeanNorm)
	}
	ctxMeanReshaped, _ := ctxMean.Reshape([]int{batchSize, 1, contextVector.Shape[2]})
	normedIn, _ = normedIn.AddWithBroadcast(ctxMeanReshaped.Scale(d.ContextMultiplier))

	reshapedIn, _ := normedIn.Reshape([]int{batchSize, embedded.Shape[2]})
	hidden, cell, err := d.LSTM.Forward(reshapedIn, prevHidden, prevCell)
	if err != nil {
		return nil, nil, nil, err
	}

	hiddenQuery, _ := hidden.Reshape([]int{batchSize, 1, d.LSTM.HiddenSize})
	normedHidden, _ := d.HiddenNorm.Forward(hiddenQuery)

	attnOut, err := d.Attention.Forward(normedHidden, contextVector, contextVector, nil)
	if err != nil {
		return nil, nil, nil, err
	}

	combined, _ := Concat([]*Tensor{hiddenQuery, attnOut}, 2)
	normedOut, _ := d.LayerNorm.Forward(combined)

	var logits *Tensor
	if d.OutputMoE != nil {
		logits, err = d.OutputMoE.Forward(normedOut)
	} else {
		logits, err = d.OutputLayer.Forward(normedOut)
	}
	if err != nil {
		return nil, nil, nil, err
	}

	flatLogits, _ := logits.Reshape([]int{batchSize, d.OutputVocabSize})

	return flatLogits, hidden, cell, nil
}

func isPronoun(word string) bool {
	w := strings.ToLower(word)
	return w == "i" || w == "you" || w == "me" || w == "my" || w == "your" || w == "we" || w == "us" || w == "it" || w == "they" || w == "them" || w == "everything" || w == "anything"
}

func isVerbOrAux(word string) bool {
	w := strings.ToLower(word)
	switch w {
	case "am", "is", "are", "was", "were", "be", "been", "being", "have", "has", "had", "do", "does", "did", "done", "doing", "go", "goes", "went", "gone", "going", "see", "saw", "seen", "look", "looking", "say", "said", "tell", "told", "think", "thought", "know", "knew", "known", "help", "helping", "helped", "work", "working", "worked", "use", "using", "used", "make", "making", "made":
		return true
	case "can", "could", "will", "would", "should", "may", "might", "must":
		return true
	}
	return false
}

// NewExpertMonitor creates a monitor for the given number of experts.
func NewExpertMonitor(numExperts int) *ExpertMonitor {
	return &ExpertMonitor{
		Counts:		make([]int, numExperts),
		NumExperts:	numExperts,
		MaxEvents:	80,
	}
}

// LogSelection records that a token was dispatched to the given expert.
func (m *ExpertMonitor) LogSelection(expertID int) {
	if expertID >= 0 && expertID < m.NumExperts {
		m.mu.Lock()
		m.Counts[expertID]++
		m.Total++
		m.recordSample(expertID)
		m.mu.Unlock()
		if GlobalTelemetry != nil {
			GlobalTelemetry.RecordTrace("router", "dispatch", map[string]interface{}{"expert_id": expertID, "total": m.Total})
		}
	}
}

// LogSelections records a batch of expert selections at once.
func (m *ExpertMonitor) LogSelections(expertIDs []int) {
	for _, id := range expertIDs {
		m.LogSelection(id)
	}
}

// Reset clears all accumulated counts for the next epoch/window.
func (m *ExpertMonitor) Reset() {
	m.mu.Lock()
	for i := range m.Counts {
		m.Counts[i] = 0
	}
	m.Total = 0
	m.mu.Unlock()
}

// Fractions returns per-expert utilisation as [0, 1] float fractions.
func (m *ExpertMonitor) Fractions() []float64 {
	m.mu.Lock()
	defer m.mu.Unlock()

	fracs := make([]float64, m.NumExperts)
	if m.Total == 0 {
		return fracs
	}
	for i, c := range m.Counts {
		fracs[i] = float64(c) / float64(m.Total)
	}
	return fracs
}

// LoadLoss computes a mean-squared-error penalty for unbalanced expert usage.
// A perfectly balanced model returns 0. A model routing everything to one
// expert returns a large positive value. Use this as an auxiliary loss term.
func (m *ExpertMonitor) LoadLoss() float64 {
	return CalculateLoadLoss(m.Counts)
}

// CalculateLoadLoss computes the MSE-based load-balance penalty from integer
// hard-counts. This is complementary to CalculateImportanceLossTensor (which
// uses soft router probabilities). Use this for post-forward diagnostics.
//
//   - usage: slice of token counts per expert in the current forward pass.
//   - Returns 0 when perfectly balanced; larger when skewed.
func CalculateLoadLoss(usage []int) float64 {
	numExperts := len(usage)
	if numExperts == 0 {
		return 0
	}

	var totalTokens int
	for _, count := range usage {
		totalTokens += count
	}
	if totalTokens == 0 {
		return 0
	}

	target := float64(totalTokens) / float64(numExperts)

	var variance float64
	for _, count := range usage {
		diff := float64(count) - target
		variance += diff * diff
	}

	return variance / float64(numExperts)
}

// HeatmapASCII emits a compact CLI-native heatmap for recent routing utilization.
func (m *ExpertMonitor) HeatmapASCII(label string) string {
	m.mu.Lock()
	defer m.mu.Unlock()

	fracs := make([]float64, m.NumExperts)
	if m.Total > 0 {
		for i, c := range m.Counts {
			fracs[i] = float64(c) / float64(m.Total)
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "[%s]\n", label)
	for i := 0; i < m.NumExperts; i++ {
		pct := int(math.Round(fracs[i] * 100))
		bar := strings.Repeat("#", int(math.Max(1, float64(pct)/5)))
		if pct == 0 {
			bar = "-"
		}
		fmt.Fprintf(&b, "E%d | %-24s %3d%% (%d)\n", i, bar, pct, m.Counts[i])
	}
	return b.String()
}

func (m *ExpertMonitor) recordSample(expertID int) {
	if m.MaxEvents <= 0 {
		m.MaxEvents = 80
	}
	m.History = append(m.History, map[string]interface{}{"expert_id": expertID, "count": 1, "total": m.Total})
	if len(m.History) > m.MaxEvents {
		m.History = m.History[len(m.History)-m.MaxEvents:]
	}
}

// Snapshot writes a JSON file with a compact routing snapshot for debugging.
func (m *ExpertMonitor) Snapshot(path string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	fracs := make([]float64, m.NumExperts)
	if m.Total > 0 {
		for i, c := range m.Counts {
			fracs[i] = float64(c) / float64(m.Total)
		}
	}
	payload := map[string]interface{}{
		"total":	m.Total,
		"counts":	append([]int(nil), m.Counts...),
		"fractions":	fracs,
		"history":	append([]map[string]interface{}(nil), m.History...),
		"num_experts":	m.NumExperts,
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// MaxImbalance returns the largest deviation any single expert has from
// the perfect target, expressed as a fraction (0 = perfect, 1 = all tokens).
func (m *ExpertMonitor) MaxImbalance() float64 {
	if m.Total == 0 || m.NumExperts == 0 {
		return 0
	}
	target := float64(m.Total) / float64(m.NumExperts)
	maxDev := 0.0
	for _, c := range m.Counts {
		dev := math.Abs(float64(c)-target) / float64(m.Total)
		if dev > maxDev {
			maxDev = dev
		}
	}
	return maxDev
}

type FastExpert struct {
	Weights	[]float32	// Flattened [InputSize * OutputSize]
	Bias	[]float32
}

type FastMoELayer struct {
	NumExperts	int
	TopK		int
	Experts		[]FastExpert

	// Router weights [InputSize * NumExperts]
	RouterWeights	[]float32

	// Monitoring / Training State
	AuxLossWeight	float32
	ExpertCounts	[]int64		// Use sync/atomic to update
	ExpertProbs	[]float32	// Sum of probabilities for balancing
}

// NewMoELayerFast creates a new high-performance FastMoELayer.
func NewMoELayerFast(numExperts, inputSize, outputSize, topK int) *FastMoELayer {
	experts := make([]FastExpert, numExperts)
	for i := 0; i < numExperts; i++ {
		experts[i] = FastExpert{
			Weights:	make([]float32, inputSize*outputSize),
			Bias:		make([]float32, outputSize),
		}
	}
	return &FastMoELayer{
		NumExperts:	numExperts,
		TopK:		topK,
		Experts:	experts,
		RouterWeights:	make([]float32, inputSize*numExperts),
		ExpertCounts:	make([]int64, numExperts),
		ExpertProbs:	make([]float32, numExperts),
	}
}

// Forward performs the Scatter-Gather forward pass.
func (m *FastMoELayer) Forward(input []float32) []float32 {

	logits := m.computeRouterLogits(input)

	idx1, idx2, val1, val2 := getTop2(logits)

	w1, w2 := normalizeTwo(val1, val2)

	atomic.AddInt64(&m.ExpertCounts[idx1], 1)
	atomic.AddInt64(&m.ExpertCounts[idx2], 1)

	out1 := m.Experts[idx1].Compute(input)
	out2 := m.Experts[idx2].Compute(input)

	finalOut := make([]float32, len(out1))
	for i := 0; i < len(out1); i++ {
		finalOut[i] = (out1[i] * w1) + (out2[i] * w2)
	}

	return finalOut
}

// computeRouterLogits computes the logits for the routing decision.
func (m *FastMoELayer) computeRouterLogits(input []float32) []float32 {
	inputSize := len(input)
	logits := make([]float32, m.NumExperts)
	for i := 0; i < m.NumExperts; i++ {
		dot := float32(0)
		offset := i * inputSize
		for j := 0; j < inputSize; j++ {
			dot += m.RouterWeights[offset+j] * input[j]
		}
		logits[i] = dot
	}
	return logits
}

// getTop2 finds the indices and values of the top 2 elements in a slice.
func getTop2(logits []float32) (int, int, float32, float32) {
	idx1, idx2 := 0, 1
	val1, val2 := logits[0], logits[1]

	if val2 > val1 {
		idx1, idx2 = 1, 0
		val1, val2 = val2, val1
	}

	for i := 2; i < len(logits); i++ {
		v := logits[i]
		if v > val1 {
			val2 = val1
			idx2 = idx1
			val1 = v
			idx1 = i
		} else if v > val2 {
			val2 = v
			idx2 = i
		}
	}
	return idx1, idx2, val1, val2
}

// normalizeTwo performs a softmax normalization for two values.
func normalizeTwo(v1, v2 float32) (float32, float32) {
	maxV := v1
	if v2 > maxV {
		maxV = v2
	}
	ev1 := float32(math.Exp(float64(v1 - maxV)))
	ev2 := float32(math.Exp(float64(v2 - maxV)))
	sum := ev1 + ev2
	return ev1 / sum, ev2 / sum
}

// Compute performs the expert's computation with unrolled dot products.
func (e *FastExpert) Compute(input []float32) []float32 {
	outputSize := len(e.Bias)
	inputSize := len(input)
	res := make([]float32, outputSize)

	_ = input[len(input)-1]
	_ = e.Weights[len(e.Weights)-1]

	for i := 0; i < outputSize; i++ {
		dot := float32(0)
		offset := i * inputSize
		row := e.Weights[offset : offset+inputSize]

		j := 0
		for ; j <= inputSize-8; j += 8 {
			dot += row[j]*input[j] + row[j+1]*input[j+1] +
				row[j+2]*input[j+2] + row[j+3]*input[j+3] +
				row[j+4]*input[j+4] + row[j+5]*input[j+5] +
				row[j+6]*input[j+6] + row[j+7]*input[j+7]
		}
		for ; j < inputSize; j++ {
			dot += row[j] * input[j]
		}
		res[i] = dot + e.Bias[i]
	}
	return res
}

// CalculateAuxLoss computes the load balancing loss.
func (m *FastMoELayer) CalculateAuxLoss(batchSize int, counts []int64, probs []float32) float32 {
	if batchSize == 0 {
		return 0
	}

	var cvSum float32
	targetCount := float32(batchSize*m.TopK) / float32(m.NumExperts)

	for i := 0; i < m.NumExperts; i++ {
		diff := float32(counts[i]) - targetCount
		cvSum += diff * diff * probs[i]
	}

	return cvSum * m.AuxLossWeight
}

// GetExpertVariance calculates the variance of expert utilization.
func (m *FastMoELayer) GetExpertVariance() float64 {
	var sum, sumSq float64
	for _, count := range m.ExpertCounts {
		c := float64(count)
		sum += c
		sumSq += c * c
	}
	mean := sum / float64(m.NumExperts)
	return (sumSq / float64(m.NumExperts)) - (mean * mean)
}

// ProfileMoE runs the MoE forward pass multiple times with CPU profiling.
func ProfileMoE(m *FastMoELayer, input [][]float32) {
	f, err := os.Create("cpu.prof")
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	if err := pprof.StartCPUProfile(f); err != nil {
		log.Fatal(err)
	}
	defer pprof.StopCPUProfile()

	for i := 0; i < 1000; i++ {
		_ = m.Forward(input[i%len(input)])
	}
}

// NewAdamRouter initializes a new AdamRouter.
func NewAdamRouter(size int, lr float32) *AdamRouter {
	return &AdamRouter{
		M:	make([]float32, size),
		V:	make([]float32, size),
		Beta1:	0.9,
		Beta2:	0.999,
		Eps:	1e-8,
		LR:	lr,
	}
}

// Update updates the weights using the Adam optimizer with auxiliary gradients.
func (a *AdamRouter) Update(weights []float32, grads []float32) {
	a.T++

	b1t := 1.0 - float32(math.Pow(float64(a.Beta1), float64(a.T)))
	b2t := 1.0 - float32(math.Pow(float64(a.Beta2), float64(a.T)))

	i := 0
	for ; i <= len(weights)-8; i += 8 {
		for k := 0; k < 8; k++ {
			idx := i + k
			g := grads[idx]

			a.M[idx] = a.Beta1*a.M[idx] + (1-a.Beta1)*g

			a.V[idx] = a.Beta2*a.V[idx] + (1-a.Beta2)*g*g

			mHat := a.M[idx] / b1t
			vHat := a.V[idx] / b2t

			weights[idx] -= a.LR * mHat / (float32(math.Sqrt(float64(vHat))) + a.Eps)
		}
	}

	for ; i < len(weights); i++ {
		g := grads[i]
		a.M[i] = a.Beta1*a.M[i] + (1-a.Beta1)*g
		a.V[i] = a.Beta2*a.V[i] + (1-a.Beta2)*g*g

		mHat := a.M[i] / b1t
		vHat := a.V[i] / b2t

		weights[i] -= a.LR * mHat / (float32(math.Sqrt(float64(vHat))) + a.Eps)
	}
}

// NewFeedForwardExpert creates a new FeedForwardExpert.
// inputDim is the dimension of the input to the expert.
// hiddenDim is the dimension of the hidden layer.
// outputDim is the dimension of the output from the expert.
func NewFeedForwardExpert(inputDim, hiddenDim, outputDim int) (*FeedForwardExpert, error) {
	layer1, err := nn.NewLinear(inputDim, hiddenDim)
	if err != nil {
		return nil, fmt.Errorf("failed to create first linear layer for expert: %w", err)
	}
	layer2, err := nn.NewLinear(hiddenDim, outputDim)
	if err != nil {
		return nil, fmt.Errorf("failed to create second linear layer for expert: %w", err)
	}

	return &FeedForwardExpert{
		Layer1:		layer1,
		Layer2:		layer2,
		ActivationEMA:	0.125,
		Decay:		0.99,
	}, nil
}

// Forward performs the forward pass of the FeedForwardExpert.
func (e *FeedForwardExpert) Forward(input *tensor.Tensor) (*tensor.Tensor, error) {
	e.inputTensor = input

	output1, err := e.Layer1.Forward(input)
	if err != nil {
		return nil, fmt.Errorf("expert layer 1 forward failed: %w", err)
	}
	e.intermediateOutput = output1

	activationOutput, err := output1.ReLU()
	if err != nil {
		return nil, fmt.Errorf("expert activation ReLU failed: %w", err)
	}
	e.activationOutput = activationOutput

	output2, err := e.Layer2.Forward(activationOutput)
	if err != nil {
		return nil, fmt.Errorf("expert layer 2 forward failed: %w", err)
	}

	return output2, nil
}

// Backward performs the backward pass of the FeedForwardExpert.
func (e *FeedForwardExpert) Backward(grad *tensor.Tensor) error {
	if grad == nil || grad.Data == nil {
		return nil
	}

	err := e.Layer2.Backward(grad)
	if err != nil {
		return fmt.Errorf("expert layer 2 backward failed: %w", err)
	}

	if e.activationOutput == nil || e.activationOutput.Grad == nil {
		return fmt.Errorf("expert activation output or its gradient is nil in backward")
	}

	if e.intermediateOutput != nil {
		if e.intermediateOutput.Grad == nil {
			e.intermediateOutput.Grad = tensor.NewTensor(e.intermediateOutput.Shape, make([]float32, len(e.intermediateOutput.Data)), false)
		}
		for i := range e.intermediateOutput.Data {
			if e.intermediateOutput.Data[i] <= 0 {
				e.intermediateOutput.Grad.Data[i] = 0
			} else if i < len(e.activationOutput.Grad.Data) {
				e.intermediateOutput.Grad.Data[i] += e.activationOutput.Grad.Data[i]
			}
		}
	} else {
		err = e.activationOutput.Creator.Backward(e.activationOutput.Grad)
		if err != nil {
			return fmt.Errorf("expert activation backward failed: %w", err)
		}
	}

	if e.intermediateOutput == nil || e.intermediateOutput.Grad == nil {
		return fmt.Errorf("expert intermediate output or its gradient is nil in backward")
	}
	err = e.Layer1.Backward(e.intermediateOutput.Grad)
	if err != nil {
		return fmt.Errorf("expert layer 1 backward failed: %w", err)
	}

	return nil
}

// Parameters returns all learnable parameters of the FeedForwardExpert.
func (e *FeedForwardExpert) Parameters() []*tensor.Tensor {
	params := e.Layer1.Parameters()
	params = append(params, e.Layer2.Parameters()...)
	return params
}

// Inputs returns the input tensors of the FeedForwardExpert's last forward operation.
func (e *FeedForwardExpert) Inputs() []*tensor.Tensor {
	if e.inputTensor != nil {
		return []*tensor.Tensor{e.inputTensor}
	}
	return []*tensor.Tensor{}
}

// Description returns a string description of the expert.
func (e *FeedForwardExpert) Description() string {
	return "FeedForwardExpert"
}

// SetMode sets the mode for the expert.
func (e *FeedForwardExpert) SetMode(training bool) {

}

// ClearState clears the expert's internal states.
func (e *FeedForwardExpert) ClearState() {
	e.inputTensor = nil
	e.activationOutput = nil
	e.intermediateOutput = nil
	if e.Layer1 != nil {
		e.Layer1.ClearState()
	}
	if e.Layer2 != nil {
		e.Layer2.ClearState()
	}
}

// ClipWeights bounds the expert's learnable parameters.
func (e *FeedForwardExpert) ClipWeights(maxVal float32) {
	if e.Layer1 != nil {
		tensor.ClipWeights(e.Layer1.Weights.Data, maxVal)
		if e.Layer1.Biases != nil {
			tensor.ClipWeights(e.Layer1.Biases.Data, maxVal)
		}
	}
	if e.Layer2 != nil {
		tensor.ClipWeights(e.Layer2.Weights.Data, maxVal)
		if e.Layer2.Biases != nil {
			tensor.ClipWeights(e.Layer2.Biases.Data, maxVal)
		}
	}
}

// EvolutionaryReset performs a "Genetic Mutation" on the expert.
func (e *FeedForwardExpert) EvolutionaryReset(winner Expert, jitterScale float32) {
	wExpert, ok := winner.(*FeedForwardExpert)
	if !ok {
		return
	}

	e.Layer1.Weights.CopyFrom(wExpert.Layer1.Weights)
	e.Layer2.Weights.CopyFrom(wExpert.Layer2.Weights)

	if e.Layer1.Biases != nil && wExpert.Layer1.Biases != nil {
		e.Layer1.Biases.CopyFrom(wExpert.Layer1.Biases)
	}
	if e.Layer2.Biases != nil && wExpert.Layer2.Biases != nil {
		e.Layer2.Biases.CopyFrom(wExpert.Layer2.Biases)
	}

	e.Layer1.Weights.ApplyJitter(jitterScale)
	e.Layer2.Weights.ApplyJitter(jitterScale)

	if e.Layer1.Weights.L2Norm() < 1e-4 {
		e.Layer1.Weights.Scale(1.2)
	}

	e.Layer1.Weights.ZeroGrad()
	e.Layer2.Weights.ZeroGrad()
}

// Shake performs an in-place noise injection to break loops.
func (e *FeedForwardExpert) Shake(intensity float32) {

	src := rand.NewSource(time.Now().UnixNano())
	r := rand.New(src)

	weights1 := e.Layer1.Weights.Data
	for i := range weights1 {
		noise := (r.Float32() - 0.5) * intensity
		weights1[i] += noise
	}

	weights2 := e.Layer2.Weights.Data
	for i := range weights2 {
		noise := (r.Float32() - 0.5) * intensity
		weights2[i] += noise
	}
}

// IsStagnant returns true if the expert's relevance is below a minimal threshold.
func (e *FeedForwardExpert) IsStagnant() bool {

	return e.ActivationEMA < 0.01
}

// UpdateHealth updates the ActivationEMA based on usage.
func (e *FeedForwardExpert) UpdateHealth(wasUsed bool) {
	var current float32 = 0.0
	if wasUsed {
		current = 1.0
	}

	e.ActivationEMA = (current * (1.0 - e.Decay)) + (e.ActivationEMA * e.Decay)
}

// ToGPU moves the expert's parameters to the GPU.
func (e *FeedForwardExpert) ToGPU() {
	if e.Layer1 != nil {
		e.Layer1.ToGPU()
	}
	if e.Layer2 != nil {
		e.Layer2.ToGPU()
	}
}

// SyncParameters is a no-op for CPU-only FeedForwardExperts.
func (e *FeedForwardExpert) SyncParameters() error {
	return nil
}

// Resize updates the output dimension of the expert.
func (e *FeedForwardExpert) Resize(newOutputDim int) {
	if e.Layer2 == nil {
		return
	}

	oldWeightsData := e.Layer2.Weights.Data
	oldBiasData := e.Layer2.Biases.Data
	oldVocabSize := e.Layer2.Weights.Shape[1]
	inputDim := e.Layer2.Weights.Shape[0]

	copyLimit := oldVocabSize
	if newOutputDim < copyLimit {
		copyLimit = newOutputDim
	}

	newWeightsData := make([]float32, inputDim*newOutputDim)
	for row := 0; row < inputDim; row++ {
		oldStart := row * oldVocabSize
		newStart := row * newOutputDim
		copy(newWeightsData[newStart:newStart+copyLimit], oldWeightsData[oldStart:oldStart+copyLimit])
	}

	newBiasData := make([]float32, newOutputDim)
	copy(newBiasData, oldBiasData[:min(len(oldBiasData), newOutputDim)])

	newLayer, _ := nn.NewLinear(inputDim, newOutputDim)
	newLayer.Weights.Data = newWeightsData
	if newLayer.Biases != nil {
		newLayer.Biases.Data = newBiasData
	}
	e.Layer2 = newLayer
}

