// MmapWeights maps a weight file directly into RAM to avoid copies.
func MmapWeights(filename string) ([]float32, *os.File, error) {
	f, err := os.OpenFile(filename, os.O_RDONLY, 0)
	if err != nil {
		return nil, nil, err
	}

	info, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, nil, err
	}

	size := info.Size()
	data, err := syscall.Mmap(int(f.Fd()), 0, int(size), syscall.PROT_READ, syscall.MAP_SHARED)
	if err != nil {
		f.Close()
		return nil, nil, err
	}

	floatData := unsafe.Slice((*float32)(unsafe.Pointer(&data[0])), len(data)/4)
	return floatData, f, nil
}

// MmapWeights maps a weight file directly into RAM on Windows.
// Note: Using a simplified approach for Windows compatibility.
func MmapWeights(filename string) ([]float32, *os.File, error) {
	f, err := os.OpenFile(filename, os.O_RDONLY, 0)
	if err != nil {
		return nil, nil, err
	}

	info, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, nil, err
	}

	size := info.Size()
	if size == 0 {
		return []float32{}, f, nil
	}

	data := make([]byte, size)
	_, err = f.Read(data)
	if err != nil {
		f.Close()
		return nil, nil, err
	}

	header := *(*reflect.SliceHeader)(unsafe.Pointer(&data))
	header.Len /= 4
	header.Cap /= 4

	return *(*[]float32)(unsafe.Pointer(&header)), f, nil
}

type KVCache struct {
	// [Layer][SequenceLength][KVHeads][HeadDim]
	Keys	[][][][]float32
	Values	[][][][]float32

	NumQHeads	int
	NumKVHeads	int
	HeadDim		int
	MaxLen		int
	Cursor		int
}

// NewKVCache initializes a new KV cache with pre-allocated memory.
func NewKVCache(layers, qHeads, kvHeads, headDim, maxLen int) *KVCache {
	keys := make([][][][]float32, layers)
	values := make([][][][]float32, layers)

	for i := 0; i < layers; i++ {
		keys[i] = make([][][]float32, maxLen)
		values[i] = make([][][]float32, maxLen)
		for j := 0; j < maxLen; j++ {
			keys[i][j] = make([][]float32, kvHeads)
			values[i][j] = make([][]float32, kvHeads)
			for k := 0; k < kvHeads; k++ {
				keys[i][j][k] = make([]float32, headDim)
				values[i][j][k] = make([]float32, headDim)
			}
		}
	}

	return &KVCache{
		Keys:		keys,
		Values:		values,
		NumQHeads:	qHeads,
		NumKVHeads:	kvHeads,
		HeadDim:	headDim,
		MaxLen:		maxLen,
	}
}

// Reset clears the cache state.
func (c *KVCache) Reset() {
	c.Cursor = 0
	for l := range c.Keys {
		for t := range c.Keys[l] {
			for h := range c.Keys[l][t] {
				for i := range c.Keys[l][t][h] {
					c.Keys[l][t][h][i] = 0
					c.Values[l][t][h][i] = 0
				}
			}
		}
	}
}

type MoEModel struct {
	Tokenizer	*tokenizer.Tokenizer
	Cache		*KVCache
