// DefaultGenerationOptions returns the standard configuration for generation.
func DefaultGenerationOptions() GenerationOptions {
	return GenerationOptions{
		MaxLen:			50,
		Temperature:		1.0,
		TopP:			0.9,
		TopK:			40,
		Echo:			true,
		RouterTemperature:	1.0,
	}
}

// NewMoEModel creates a new instance of the model.
func NewMoEModel(t *tokenizer.Tokenizer, config MoEConfig) *MoEModel {

	qHeads := 8
	kvHeads := 2
	headDim := config.HiddenSize / qHeads

	m := &MoEModel{
		Tokenizer:	t,
		Cache:		NewKVCache(config.Layers, qHeads, kvHeads, headDim, config.MaxLen),
		Config:		config,
	}
	m.InitializeMockBigram()
	return m
}

// InitializeMockBigram populates the mock bigram model to make dummy generation more realistic.
func (m *MoEModel) InitializeMockBigram() {
	m.MockBigram = make(map[int][]int)
	vocabWords := m.Tokenizer.Vocabulary.TokenToWord

	for id1, w1 := range vocabWords {
		for id2, w2 := range vocabWords {

			isGood := false
			lw1, lw2 := strings.ToLower(w1), strings.ToLower(w2)

			if (lw1 == "the" || lw1 == "a") && !(lw2 == "the" || lw2 == "a") {
				isGood = true
			}

			if (lw1 == "gollemer" || lw1 == "network" || lw1 == "system") && (lw2 == "is" || lw2 == "processes" || lw2 == "thinks") {
				isGood = true
			}

			if (lw1 == "is" || lw1 == "becomes") && (lw2 == "fast" || lw2 == "powerful" || lw2 == "smart") {
				isGood = true
			}

			if isGood {
				m.MockBigram[id1] = append(m.MockBigram[id1], id2)
			}
		}
	}
}

func (m *MoEModel) Forward(tokens []int) []float32 {
	vocabSize := m.Tokenizer.Vocabulary.Size()
	logits := make([]float32, vocabSize)

	lastToken := -1
	if len(tokens) > 0 {
		lastToken = tokens[len(tokens)-1]
	}

	for i := range logits {
		logits[i] = rand.Float32() * 0.1
	}

	if lastToken != -1 {
		if followers, ok := m.MockBigram[lastToken]; ok {
			for _, id := range followers {
				logits[id] += 2.0
			}
		}
	}

	return logits
}

// SoftmaxSIMD normalizes the logits using a SIMD-ready approach.
func SoftmaxSIMD(logits []float32) {
	var max float32 = -math.MaxFloat32
	for _, v := range logits {
		if v > max {
			max = v
		}
	}

	var sum float64
	for i := 0; i < len(logits); i++ {
		logits[i] = float32(math.Exp(float64(logits[i] - max)))
		sum += float64(logits[i])
	}

	invSum := float32(1.0 / sum)
	for i := 0; i < len(logits); i++ {
		logits[i] *= invSum
	}
}

type TokenProb struct {
	ID	int
	Prob	float32
}

// Sample performs sampling using Temperature, Top-K, and Top-P (Nucleus) sampling.
func (m *MoEModel) Sample(logits []float32, opts GenerationOptions) int {

	if opts.Temperature != 1.0 && opts.Temperature > 0 {
		for i := range logits {
			logits[i] /= opts.Temperature
		}
	}

	SoftmaxSIMD(logits)

	tokenProbs := make([]TokenProb, len(logits))
	for i, prob := range logits {
		tokenProbs[i] = TokenProb{ID: i, Prob: prob}
	}

	sort.Slice(tokenProbs, func(i, j int) bool {
		return tokenProbs[i].Prob > tokenProbs[j].Prob
	})

	if opts.TopK > 0 && opts.TopK < len(tokenProbs) {
		tokenProbs = tokenProbs[:opts.TopK]
	}

	if opts.TopP > 0 && opts.TopP < 1.0 {
		var cumulativeProb float32
		cutoffIndex := len(tokenProbs) - 1
		for i, tp := range tokenProbs {
			cumulativeProb += tp.Prob
			if cumulativeProb >= opts.TopP {
				cutoffIndex = i
				break
			}
		}
		tokenProbs = tokenProbs[:cutoffIndex+1]
	}

	// 5. Sample from the filtered distribution
	var totalProb float32
	for _, tp := range tokenProbs {
		totalProb += tp.Prob
	}

	r := rand.Float32() * totalProb
	var currentSum float32
	for _, tp := range tokenProbs {
		currentSum += tp.Prob
		if r <= currentSum {
			return tp.ID
		}
	}

	return tokenProbs[0].ID
}

// GenerateWithStats handles the autoregressive generation with real-time TPS tracking.
func (m *MoEModel) GenerateWithStats(prompt string) string {
	return m.GenerateCustom(prompt, DefaultGenerationOptions())
}

// GenerateCustom performs generation with specific options.
func (m *MoEModel) GenerateCustom(prompt string, opts GenerationOptions) string {
	tokens, _ := m.Tokenizer.Encode(prompt)
	start := time.Now()
	generatedCount := 0
	var result strings.Builder

	if opts.Echo {
		fmt.Printf("/ʕ◡ϖ◡ʔ/ > ")
	}

	for generatedCount < opts.MaxLen {
		logits := m.Forward(tokens)

		nextToken := m.Sample(logits, opts)

		word, _ := m.Tokenizer.Decode([]int{nextToken})
		result.WriteString(word)
		if !strings.HasSuffix(word, " ") {
			result.WriteString(" ")
		}

		if opts.Echo {
			fmt.Print(word)
			if !strings.HasSuffix(word, " ") {
				fmt.Print(" ")
			}

			elapsed := time.Since(start).Seconds()
			tps := 0.0
			if elapsed > 0 {
				tps = float64(generatedCount+1) / elapsed
			}

			fmt.Printf("\033[s\033[K\n[ TPS: %.2f | Tokens: %d | Temp: %.1f | TopP: %.2f ]\033[u",
				tps, generatedCount+1, opts.Temperature, opts.TopP)
		}

		tokens = append(tokens, nextToken)
		generatedCount++

		isStop := false
		for _, stopID := range opts.StopTokens {
			if nextToken == stopID {
				isStop = true
				break
			}
		}
		if isStop || nextToken == 0 {
			break
		}
	}

	if opts.Echo {
		fmt.Println("\n— Done.")
	}
	return result.String()
}

func (m *MoEModel) AttendGQA(qLayer [][]float32, layerIdx int, cache *KVCache) []float32 {
	groupSize := cache.NumQHeads / cache.NumKVHeads
	output := make([]float32, cache.NumQHeads*cache.HeadDim)

	for qIdx := 0; qIdx < cache.NumQHeads; qIdx++ {
		kvIdx := qIdx / groupSize
		qHead := qLayer[qIdx]
		headOutput := m.ComputeScaledDotProduct(qHead, cache.Keys[layerIdx], cache.Values[layerIdx], kvIdx, cache.Cursor)
		copy(output[qIdx*cache.HeadDim:], headOutput)
	}
	return output
}

func (m *MoEModel) ComputeScaledDotProduct(qHead []float32, kCache [][][]float32, vCache [][][]float32, kvIdx int, cursor int) []float32 {
	headDim := len(qHead)
	scale := 1.0 / math.Sqrt(float64(headDim))
	scores := make([]float32, cursor+1)

	for t := 0; t <= cursor; t++ {
		kHead := kCache[t][kvIdx]
		var sum float32

		for i := 0; i < headDim; i++ {
			sum += qHead[i] * kHead[i]
		}
		scores[t] = sum * float32(scale)
	}

	SoftmaxSIMD(scores)

	output := make([]float32, headDim)
	for t := 0; t <= cursor; t++ {
		vHead := vCache[t][kvIdx]
		s := scores[t]
		for i := 0; i < headDim; i++ {
			output[i] += s * vHead[i]
		}
	}
	return output
}

// ApplyRoPE rotates the query or key vector based on its absolute position.
func ApplyRoPE(vec []float32, position int, headDim int, theta float32) {
	for i := 0; i < headDim/2; i++ {
		freq := float32(1.0 / math.Pow(float64(theta), float64(2*i)/float64(headDim)))
		angle := float32(position) * freq

		cos := float32(math.Cos(float64(angle)))
		sin := float32(math.Sin(float64(angle)))

		v0 := vec[i]
		v1 := vec[i+headDim/2]
		vec[i] = v0*cos - v1*sin
		vec[i+headDim/2] = v0*sin + v1*cos
	}
}

func init() {
	gob.Register(bert.BertConfig{})
}

type DecoderStepState struct {
	LSTMCell	*nn.LSTMCell
	EmbeddedInput	*tensor.Tensor
	DecoderHidden	*tensor.Tensor
	DecoderCell	*tensor.Tensor
}

func NewMoEClassificationModel(vocabSize, embeddingDim, numParentClasses, numChildClasses, sentenceVocabSize, numExperts, k, maxSeqLength int) (*MoEClassificationModel, error) {
	embedding := nn.NewEmbedding(vocabSize, embeddingDim)

	bertConfig := bert.BertConfig{
		VocabSize:		vocabSize,
		HiddenSize:		embeddingDim,
		MaxPositionEmbeddings:	maxSeqLength,
		NumHiddenLayers:	4,
		NumAttentionHeads:	4,
		IntermediateSize:	embeddingDim * 4,
		TypeVocabSize:		2,
		InitializerRange:	0.02,
	}
	bertModel := bert.NewBertModel(bertConfig, nil)

	parentClassifier, err := nn.NewLinear(embeddingDim, numParentClasses)
	if err != nil {
		return nil, err
	}
	childClassifier, err := nn.NewLinear(embeddingDim, numChildClasses)
	if err != nil {
		return nil, err
	}

	sentenceEmbedding := nn.NewEmbedding(sentenceVocabSize, embeddingDim)
	sentenceDecoderTemplate, err := nn.NewLSTMCell(embeddingDim, embeddingDim)
	if err != nil {
		return nil, err
	}
	sentenceClassifier, err := nn.NewLinear(embeddingDim, sentenceVocabSize)
	if err != nil {
		return nil, err
	}

	return &MoEClassificationModel{
		Embedding:			embedding,
		BertModel:			bertModel,
		ParentClassifier:		parentClassifier,
		ChildClassifier:		childClassifier,
		SentenceEmbedding:		sentenceEmbedding,
		SentenceDecoderTemplate:	sentenceDecoderTemplate,
		SentenceClassifier:		sentenceClassifier,
		BertConfig:			bertConfig,
	}, nil
}

func (m *MoEClassificationModel) Forward(inputs ...*tensor.Tensor) (*tensor.Tensor, *tensor.Tensor, *tensor.Tensor, error) {
	inputIDs := inputs[0]
	targetSentenceIDs := inputs[1]

	batchSize, seqLength := inputIDs.Shape[0], inputIDs.Shape[1]

	tokenTypeIDs := tensor.NewTensor([]int{batchSize, seqLength}, make([]float32, batchSize*seqLength), false)
	posTagIDs := tensor.NewTensor([]int{batchSize, seqLength}, make([]float32, batchSize*seqLength), false)
	nerTagIDs := tensor.NewTensor([]int{batchSize, seqLength}, make([]float32, batchSize*seqLength), false)

	bertOutput, err := m.BertModel.Forward(inputIDs, tokenTypeIDs, posTagIDs, nerTagIDs)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("bert model forward failed: %w", err)
	}

	clsTokenOutput, err := bertOutput.Slice(1, 0, 1)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to slice CLS token output: %w", err)
	}

	clsTokenOutputReshaped, err := clsTokenOutput.Reshape([]int{batchSize, m.BertConfig.HiddenSize})
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to reshape CLS token output: %w", err)
	}

	parentLogits, err := m.ParentClassifier.Forward(clsTokenOutputReshaped)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("parent classifier forward failed: %w", err)
	}

	childLogits, err := m.ChildClassifier.Forward(clsTokenOutputReshaped)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("child classifier forward failed: %w", err)
	}

	targetSeqLen := targetSentenceIDs.Shape[1]
	sentenceVocabSize := m.SentenceClassifier.Weights.Shape[1]
	decoderHidden := clsTokenOutputReshaped
	decoderCell := tensor.NewTensor(decoderHidden.Shape, make([]float32, len(decoderHidden.Data)), true)

	allLstmOutputs := make([]*tensor.Tensor, targetSeqLen)
	m.decoderStates = make([]*DecoderStepState, targetSeqLen)

	for t := range targetSeqLen {
		decoderInputData := make([]float32, batchSize)
		for b := range batchSize {
			decoderInputData[b] = targetSentenceIDs.Data[b*targetSeqLen+t]
		}
		decoderInput := tensor.NewTensor([]int{batchSize, 1}, decoderInputData, true)

		embedded, err := m.SentenceEmbedding.Forward(decoderInput)
		if err != nil {
			return nil, nil, nil, fmt.Errorf("decoder embedding failed: %w", err)
		}

		embeddedReshaped, err := embedded.Reshape([]int{batchSize, m.BertConfig.HiddenSize})
		if err != nil {
			return nil, nil, nil, fmt.Errorf("decoder embedding reshape failed: %w", err)
		}

		cell := &nn.LSTMCell{
			InputSize:	m.SentenceDecoderTemplate.InputSize,
			HiddenSize:	m.SentenceDecoderTemplate.HiddenSize,
			Wf:		m.SentenceDecoderTemplate.Wf,
			Wi:		m.SentenceDecoderTemplate.Wi,
			Wc:		m.SentenceDecoderTemplate.Wc,
			Wo:		m.SentenceDecoderTemplate.Wo,
			Bf:		m.SentenceDecoderTemplate.Bf,
			Bi:		m.SentenceDecoderTemplate.Bi,
			Bc:		m.SentenceDecoderTemplate.Bc,
			Bo:		m.SentenceDecoderTemplate.Bo,
		}

		lstmOutput, c, err := cell.Forward(embeddedReshaped, decoderHidden, decoderCell)
		if err != nil {
			return nil, nil, nil, fmt.Errorf("decoder lstm failed: %+v", err)
		}

		m.decoderStates[t] = &DecoderStepState{
			LSTMCell:	cell,
			EmbeddedInput:	embeddedReshaped,
			DecoderHidden:	decoderHidden,
			DecoderCell:	decoderCell,
		}

		decoderHidden = lstmOutput
		decoderCell = c
		allLstmOutputs[t] = lstmOutput
	}

	concatenatedLstmOutputsData := make([]float32, batchSize*targetSeqLen*m.BertConfig.HiddenSize)
	for t := range targetSeqLen {
		copy(concatenatedLstmOutputsData[t*batchSize*m.BertConfig.HiddenSize:(t+1)*batchSize*m.BertConfig.HiddenSize], allLstmOutputs[t].Data)
	}
	concatenatedLstmOutputs := tensor.NewTensor([]int{batchSize * targetSeqLen, m.BertConfig.HiddenSize}, concatenatedLstmOutputsData, true)

	predictions, err := m.SentenceClassifier.Forward(concatenatedLstmOutputs)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("decoder output linear layer failed: %w", err)
	}

	decoderOutputs, err := predictions.Reshape([]int{batchSize, targetSeqLen, sentenceVocabSize})
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to reshape decoder outputs: %w", err)
	}

	return parentLogits, childLogits, decoderOutputs, nil
}

func (m *MoEClassificationModel) Backward(parentGrad, childGrad, sentenceGrad *tensor.Tensor) error {

	reshapedSentenceGrad, err := sentenceGrad.Reshape([]int{sentenceGrad.Shape[0] * sentenceGrad.Shape[1], sentenceGrad.Shape[2]})
	if err != nil {
		return fmt.Errorf("failed to reshape sentenceGrad for SentenceClassifier backward: %w", err)
	}
	err = m.SentenceClassifier.Backward(reshapedSentenceGrad)
	if err != nil {
		return fmt.Errorf("sentence classifier backward failed: %w", err)
	}

	gradAllLstmOutputs := m.SentenceClassifier.Input().Grad
	batchSize := sentenceGrad.Shape[0]
	targetSeqLen := sentenceGrad.Shape[1]
	hiddenSize := m.BertConfig.HiddenSize

	gradDecoderHidden := tensor.NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), true)
	gradDecoderCell := tensor.NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), true)

	for t := targetSeqLen - 1; t >= 0; t-- {
		stepState := m.decoderStates[t]
		cell := stepState.LSTMCell

		offset := t * batchSize * hiddenSize
		gradLstmOutput := tensor.NewTensor(
			[]int{batchSize, hiddenSize},
			gradAllLstmOutputs.Data[offset:offset+batchSize*hiddenSize],
			true,
		)
		gradLstmOutput.Add(gradDecoderHidden)

		err := cell.Backward(gradLstmOutput, gradDecoderCell)
		if err != nil {
			return fmt.Errorf("sentence decoder backward failed at step %d: %w", t, err)
		}

		gradDecoderHidden = cell.PrevHidden.Grad
		gradDecoderCell = cell.PrevCell.Grad

		err = m.SentenceEmbedding.Backward(cell.InputTensor.Grad)
		if err != nil {
			return fmt.Errorf("sentence embedding backward failed at step %d: %w", t, err)
		}
	}

	err = m.ParentClassifier.Backward(parentGrad)
	if err != nil {
		return fmt.Errorf("parent classifier backward failed: %w", err)
	}

	err = m.ChildClassifier.Backward(childGrad)
	if err != nil {
		return fmt.Errorf("child classifier backward failed: %w", err)
	}

	clsTokenGrad := m.ParentClassifier.Input().Grad
	clsTokenGrad.Add(gradDecoderHidden)

	bertGrad := tensor.NewTensor([]int{clsTokenGrad.Shape[0], m.BertConfig.MaxPositionEmbeddings, m.BertConfig.HiddenSize}, make([]float32, clsTokenGrad.Shape[0]*m.BertConfig.MaxPositionEmbeddings*m.BertConfig.HiddenSize), false)

	batchSize = clsTokenGrad.Shape[0]
	hiddenSize = clsTokenGrad.Shape[1]

	for i := 0; i < batchSize; i++ {
		copy(bertGrad.Data[i*m.BertConfig.MaxPositionEmbeddings*hiddenSize:i*m.BertConfig.MaxPositionEmbeddings*hiddenSize+hiddenSize], clsTokenGrad.Data[i*hiddenSize:(i+1)*hiddenSize])
	}

	err = m.BertModel.Backward(bertGrad)
	if err != nil {
		return fmt.Errorf("bert model backward failed: %w", err)
	}

	return nil
}

func (m *MoEClassificationModel) Parameters() []*tensor.Tensor {
	var params []*tensor.Tensor
	if m.BertModel != nil {
		params = append(params, m.BertModel.Parameters()...)
	}
	params = append(params, m.ParentClassifier.Parameters()...)
	params = append(params, m.ChildClassifier.Parameters()...)
	params = append(params, m.SentenceEmbedding.Parameters()...)
	params = append(params, m.SentenceDecoderTemplate.Parameters()...)
	params = append(params, m.SentenceClassifier.Parameters()...)
	return params
}

