}

// SaveMoEClassificationModelToGOB saves the MoEClassificationModel to a file in Gob format.
func SaveMoEClassificationModelToGOB(model *MoEClassificationModel, filePath string) error {
	file, err := os.Create(filePath)
	if err != nil {
		return fmt.Errorf("failed to create file for saving MoE model: %w", err)
	}
	defer file.Close()

	encoder := gob.NewEncoder(file)
	if err := encoder.Encode(model); err != nil {
		return fmt.Errorf("failed to encode MoE model to Gob: %w", err)
	}

	return nil
}

// LoadMoEClassificationModelFromGOB loads a MoEClassificationModel from a Gob file.
func LoadMoEClassificationModelFromGOB(filePath string) (*MoEClassificationModel, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open file for loading MoE model: %w", err)
	}
	defer file.Close()

	decoder := gob.NewDecoder(file)
	var model MoEClassificationModel
	if err := decoder.Decode(&model); err != nil {
		return nil, fmt.Errorf("failed to decode MoE model from Gob: %w", err)
	}

	return &model, nil
}

type MoEEncoder struct {
	InputSize	int
	HiddenSize	int
	NumLayers	int
	NumExperts	int

	// Underlying MoE Layer
	Layer	*MoELayer
}

// NewMoEEncoder creates a new Mixture of Experts Encoder.
func NewMoEEncoder(inputSize, hiddenSize, numLayers, numExperts int) (*MoEEncoder, error) {

	expertBuilder := func(expertIdx int) (Expert, error) {
		return NewFeedForwardExpert(inputSize, hiddenSize, hiddenSize)
	}

	layer, err := NewMoELayer(inputSize, hiddenSize, numExperts, 2, expertBuilder)
	if err != nil {
		return nil, fmt.Errorf("failed to create MoE layer: %w", err)
	}

	return &MoEEncoder{
		InputSize:	inputSize,
		HiddenSize:	hiddenSize,
		NumLayers:	numLayers,
		NumExperts:	numExperts,
		Layer:		layer,
	}, nil
}

// Forward performs the forward pass for the MoE Encoder.
func (m *MoEEncoder) Forward(inputs ...*tensor.Tensor) (*tensor.Tensor, error) {
	if len(inputs) == 0 {
		return nil, fmt.Errorf("MoEEncoder.Forward expects at least 1 input")
	}

	return m.Layer.Forward(inputs[0])
}

