// UpdateRouterGrads handles the load balancing penalty in pure Go.
func (moe *MoELayer) UpdateRouterGrads(gateGrads [][]float32, scaledFractions []float32) {
	numExperts := len(scaledFractions)

	for i := range gateGrads {

		grads := gateGrads[i]
		if len(grads) < numExperts {
			continue
		}

		e := 0
		for ; e <= numExperts-4; e += 4 {
			grads[e] += scaledFractions[e]
			grads[e+1] += scaledFractions[e+1]
			grads[e+2] += scaledFractions[e+2]
			grads[e+3] += scaledFractions[e+3]
		}

		for ; e < numExperts; e++ {
			grads[e] += scaledFractions[e]
		}
	}
}

// CalculateDiversityLoss computes the cosine similarity between the outputs of the top-2 experts
// selected for each token and averages it over the batch.
func (moe *MoELayer) CalculateDiversityLoss() float32 {
	if moe.K < 2 {
		return 0
	}

	numTokens := len(moe.SelectedExperts)
	if numTokens == 0 {
		return 0
	}

	var totalSimilarity float32
	var count int

	for i := 0; i < numTokens; i++ {
		selected := moe.SelectedExperts[i]
		if len(selected) < 2 {
			continue
		}

		expertA := selected[0]
		expertB := selected[1]

		outA := moe.expertOutputs[expertA]
		outB := moe.expertOutputs[expertB]

		if outA == nil || outB == nil {
			continue
		}

		relIdxA := -1
		for idx, tIdx := range moe.ExpertTokenIndices[expertA] {
			if tIdx == i {
				relIdxA = idx
				break
			}
		}

		relIdxB := -1
		for idx, tIdx := range moe.ExpertTokenIndices[expertB] {
			if tIdx == i {
				relIdxB = idx
				break
			}
		}

		if relIdxA == -1 || relIdxB == -1 {
			continue
		}

		rowA := outA.Data[relIdxA*moe.OutputDim : (relIdxA+1)*moe.OutputDim]
		rowB := outB.Data[relIdxB*moe.OutputDim : (relIdxB+1)*moe.OutputDim]

		sim := CosineSimilarity(rowA, rowB)

		if sim > 0 {
			totalSimilarity += sim
		}
		count++
	}

	if count == 0 {
		return 0
	}
	return totalSimilarity / float32(count)
}

// CosineSimilarity calculates the cosine similarity between two vectors.
func CosineSimilarity(a, b []float32) float32 {
	if len(a) != len(b) || len(a) == 0 {
		return 0
	}
	var dot, normA, normB float32
	for i := range a {
		dot += a[i] * b[i]
		normA += a[i] * a[i]
		normB += b[i] * b[i]
	}
	if normA <= 0 || normB <= 0 || math.IsNaN(float64(normA)) || math.IsNaN(float64(normB)) {
		return 0
	}

	denom := float32(math.Sqrt(float64(normA)) * math.Sqrt(float64(normB)))
	if denom < 1e-12 {
		return 0
	}

	res := dot / denom
	if math.IsNaN(float64(res)) {
		return 0
	}
	return res
}

// UpdateExpertMultipliers adjusts the gradient multipliers based on expert utilization.
// Transitions an expert from "Recovery Mode" to "Standard Mode" once it proves it can handle a fair share of the load.
func (moe *MoELayer) UpdateExpertMultipliers() {
	const (
		TargetUsage		= 0.125	// 1/8 experts = 12.5% ideal
		MaxMult			= 2.5
		MinMult			= 1.0
		DecayRate		= 0.85
		LowUsageThreshold	= 0.02
		HealthyUsageThreshold	= 0.10
	)

	numExperts := len(moe.Experts)
	totalTokens := 0
	for _, count := range moe.AccumulatedUtilization {
		totalTokens += count
	}

	if totalTokens == 0 {
		return
	}

	for i := 0; i < numExperts; i++ {
		utilization := float32(moe.AccumulatedUtilization[i]) / float32(totalTokens)

		if utilization > HealthyUsageThreshold && moe.ExpertGradMultiplier[i] > MinMult {
			moe.ExpertGradMultiplier[i] *= float32(DecayRate)
			if moe.ExpertGradMultiplier[i] < MinMult {
				moe.ExpertGradMultiplier[i] = MinMult
			}
			fmt.Printf("🚀 Expert %d (L) stabilized: New Multiplier %.2f (Usage: %.2f%%)\n",
				i, moe.ExpertGradMultiplier[i], utilization*100)
		} else if utilization < LowUsageThreshold {

			moe.ExpertGradMultiplier[i] = float32(MaxMult)
		}
	}
}

// ShakeExperts performs an in-place noise injection to all stagnant experts.
func (moe *MoELayer) ShakeExperts(intensity float32, loopCount int) {

	adjustedIntensity := intensity * float32(math.Log1p(float64(loopCount)))
	if adjustedIntensity < intensity {
		adjustedIntensity = intensity
	}

	for i, expert := range moe.Experts {

		stagnancyScore := 0
		if moe.StagnationCounters != nil {
			stagnancyScore = moe.StagnationCounters[i]
		}

		if expert.IsStagnant() || stagnancyScore > 5 {
			fmt.Printf("🌊 Expert %d is stagnant (Score: %d). Shaking at intensity %.4f to break circuit...\n",
				i, stagnancyScore, adjustedIntensity)
			expert.Shake(adjustedIntensity)

			if moe.StagnationCounters != nil {
				moe.StagnationCounters[i] = 0
			}
		}
	}
}

func (moe *MoELayer) RepairArchitecture() {
	if moe.GatingNetwork != nil {
		moe.GatingNetwork.RepairArchitecture()
	}
}

// PruneUnderutilizedExperts removes a fraction of the least utilized experts from the layer,
// reducing memory footprint and forcing the gating network to route to remaining experts.
func (moe *MoELayer) PruneUnderutilizedExperts(fraction float32) {
	if fraction <= 0 || fraction >= 1 {
		return
	}
	dropCount := int(float32(len(moe.Experts)) * fraction)
	if dropCount < 1 {
		dropCount = 1
	}

	if len(moe.Experts)-dropCount < 8 {
		dropCount = len(moe.Experts) - 8
	}
	if dropCount <= 0 {
		return
	}

	type expertScore struct {
		idx	int
		util	int
	}
	var scores []expertScore
	for i := range moe.Experts {

		if i < len(moe.ExpertPinned) && moe.ExpertPinned[i] {
			continue
		}
		util := 0
		if i < len(moe.AccumulatedUtilization) {
			util = moe.AccumulatedUtilization[i]
		}
		scores = append(scores, expertScore{idx: i, util: util})
	}

	sort.Slice(scores, func(a, b int) bool {
		return scores[a].util < scores[b].util
	})

	if dropCount > len(scores) {
		dropCount = len(scores)
	}

	droppedIndices := make(map[int]bool)
	for i := 0; i < dropCount; i++ {
		droppedIndices[scores[i].idx] = true
	}

	newExperts := make([]Expert, 0, len(moe.Experts)-dropCount)
	newAccumulatedUtilization := make([]int, 0, len(moe.Experts)-dropCount)
	newExpertTokenIndices := make([][]int, 0, len(moe.Experts)-dropCount)
	newExpertFrozen := make([]bool, 0, len(moe.Experts)-dropCount)
	newStagnationCounters := make([]int, 0, len(moe.Experts)-dropCount)
	newStepStagnationCounters := make([]int, 0, len(moe.Experts)-dropCount)
	newExpertGradMultiplier := make([]float32, 0, len(moe.Experts)-dropCount)
	newExpertOutputScale := make([]float32, 0, len(moe.Experts)-dropCount)
	newExpertHealth := make([]float64, 0, len(moe.Experts)-dropCount)
	newExpertLastUsedAt := make([]time.Time, 0, len(moe.Experts)-dropCount)
	newExpertPinned := make([]bool, 0, len(moe.Experts)-dropCount)
	newExpertRole := make([]string, 0, len(moe.Experts)-dropCount)

	for i := 0; i < len(moe.Experts); i++ {
		if droppedIndices[i] {
			continue
		}
		newExperts = append(newExperts, moe.Experts[i])

		if i < len(moe.AccumulatedUtilization) {
			newAccumulatedUtilization = append(newAccumulatedUtilization, moe.AccumulatedUtilization[i])
		} else {
			newAccumulatedUtilization = append(newAccumulatedUtilization, 0)
		}
		newExpertTokenIndices = append(newExpertTokenIndices, []int{})

		if i < len(moe.ExpertFrozen) {
			newExpertFrozen = append(newExpertFrozen, moe.ExpertFrozen[i])
		} else {
			newExpertFrozen = append(newExpertFrozen, false)
		}
		if i < len(moe.StagnationCounters) {
			newStagnationCounters = append(newStagnationCounters, moe.StagnationCounters[i])
		} else {
			newStagnationCounters = append(newStagnationCounters, 0)
		}
		if i < len(moe.StepStagnationCounters) {
			newStepStagnationCounters = append(newStepStagnationCounters, moe.StepStagnationCounters[i])
		} else {
			newStepStagnationCounters = append(newStepStagnationCounters, 0)
		}
		if i < len(moe.ExpertGradMultiplier) {
			newExpertGradMultiplier = append(newExpertGradMultiplier, moe.ExpertGradMultiplier[i])
		} else {
			newExpertGradMultiplier = append(newExpertGradMultiplier, 1.0)
		}
		if i < len(moe.ExpertOutputScale) {
			newExpertOutputScale = append(newExpertOutputScale, moe.ExpertOutputScale[i])
		} else {
			newExpertOutputScale = append(newExpertOutputScale, 1.0)
		}
		if i < len(moe.ExpertHealth) {
			newExpertHealth = append(newExpertHealth, moe.ExpertHealth[i])
		} else {
			newExpertHealth = append(newExpertHealth, 1.0)
		}
		if i < len(moe.ExpertLastUsedAt) {
			newExpertLastUsedAt = append(newExpertLastUsedAt, moe.ExpertLastUsedAt[i])
		} else {
			newExpertLastUsedAt = append(newExpertLastUsedAt, time.Now())
		}
		if i < len(moe.ExpertPinned) {
			newExpertPinned = append(newExpertPinned, moe.ExpertPinned[i])
		} else {
			newExpertPinned = append(newExpertPinned, false)
		}
		if i < len(moe.ExpertRole) {
			newExpertRole = append(newExpertRole, moe.ExpertRole[i])
		} else {
			newExpertRole = append(newExpertRole, "")
		}
	}

	moe.Experts = newExperts
	moe.AccumulatedUtilization = newAccumulatedUtilization
	moe.ExpertTokenIndices = newExpertTokenIndices
	moe.ExpertFrozen = newExpertFrozen
	moe.StagnationCounters = newStagnationCounters
	moe.StepStagnationCounters = newStepStagnationCounters
	moe.ExpertGradMultiplier = newExpertGradMultiplier
	moe.ExpertOutputScale = newExpertOutputScale
	moe.ExpertHealth = newExpertHealth
	moe.ExpertLastUsedAt = newExpertLastUsedAt
	moe.ExpertPinned = newExpertPinned
	moe.ExpertRole = newExpertRole
	moe.NumExperts = len(newExperts)

	if moe.GatingNetwork != nil {
		moe.GatingNetwork.PruneExperts(droppedIndices)
	}
}

// FindLowestPerformingExpert returns the index of the expert with the lowest performance score.
// The score is computed by blending expert health (from logs/evaluation) and recency of utilization:
// score := health * (1.0 / (1.0 + age_seconds))
// Pinned experts (vital structural experts) are excluded.
// Returns -1 if no expert can be evicted.
func (moe *MoELayer) FindLowestPerformingExpert(newRole string) int {
	if len(moe.Experts) <= 4 {
		return -1
	}

	if len(moe.ExpertHealth) != len(moe.Experts) {
		moe.ExpertHealth = make([]float64, len(moe.Experts))
		for i := range moe.ExpertHealth {
			moe.ExpertHealth[i] = 1.0
		}
	}
	if len(moe.ExpertLastUsedAt) != len(moe.Experts) {
		moe.ExpertLastUsedAt = make([]time.Time, len(moe.Experts))
		now := time.Now()
		for i := range moe.ExpertLastUsedAt {
			moe.ExpertLastUsedAt[i] = now
		}
	}
	if len(moe.ExpertPinned) != len(moe.Experts) {
		moe.ExpertPinned = make([]bool, len(moe.Experts))
		for i := 0; i < 8 && i < len(moe.ExpertPinned); i++ {
			moe.ExpertPinned[i] = true
		}
	}

	weakestIdx := -1
	lowestScore := math.MaxFloat64
	now := time.Now()

	isLowValueNewRole := (newRole == "GREET" || newRole == "OTHER")

	totalUtilization := 0
	for _, u := range moe.AccumulatedUtilization {
		totalUtilization += u
	}
	averageUtilization := float64(0.0)
	if len(moe.Experts) > 0 {
		averageUtilization = float64(totalUtilization) / float64(len(moe.Experts))
	}

	for i := range moe.Experts {

		if i < len(moe.ExpertPinned) && moe.ExpertPinned[i] {
			continue
		}

		role := ""
		if i < len(moe.ExpertRole) {
			role = moe.ExpertRole[i]
		}

		if role == "structural_baseline" {
			continue
		}

		isStructural := (role == "PRON" || role == "VERB" || role == "AUX" || role == "ADJ" || role == "NOUN" || role == "PREP" || role == "")

		util := 0.0
		if i < len(moe.AccumulatedUtilization) {
			util = float64(moe.AccumulatedUtilization[i])
		}
		isHighlyActive := util > averageUtilization && util > 5.0

		if isLowValueNewRole && isStructural && isHighlyActive {
			continue
		}

		var health float64 = 1.0
		if i < len(moe.ExpertHealth) {
			health = moe.ExpertHealth[i]
		}

		var lastUsed time.Time = now
		if i < len(moe.ExpertLastUsedAt) {
			lastUsed = moe.ExpertLastUsedAt[i]
		}

		age := now.Sub(lastUsed).Seconds()

		score := health * (1.0 / (1.0 + age))

		if score < lowestScore {
			lowestScore = score
			weakestIdx = i
		}
	}

	if weakestIdx == -1 && (len(moe.Experts) >= 64 || moe.OverfitMode) {
		lowestScore = math.MaxFloat64
		var backupCandidate = -1
		var backupScore = math.MaxFloat64
		for i := 48; i < len(moe.Experts); i++ {
			role := ""
			if i < len(moe.ExpertRole) {
				role = moe.ExpertRole[i]
			}

			if role == "structural_baseline" {
				continue
			}
			isStructural := (role == "PRON" || role == "VERB" || role == "AUX" || role == "ADJ" || role == "NOUN" || role == "PREP" || role == "")

			isPinned := false
			if i < len(moe.ExpertPinned) {
				isPinned = moe.ExpertPinned[i]
			}

			util := 0.0
			if i < len(moe.AccumulatedUtilization) {
				util = float64(moe.AccumulatedUtilization[i])
			}
			isHighlyActive := util > averageUtilization && util > 5.0

			if isLowValueNewRole && isStructural && (isPinned || isHighlyActive) {
				continue
			}

			var health float64 = 1.0
			if i < len(moe.ExpertHealth) {
				health = moe.ExpertHealth[i]
			}

			var lastUsed time.Time = now
			if i < len(moe.ExpertLastUsedAt) {
				lastUsed = moe.ExpertLastUsedAt[i]
			}

			age := now.Sub(lastUsed).Seconds()

			var utilization float64 = 0.0
			if i < len(moe.AccumulatedUtilization) {
				utilization = float64(moe.AccumulatedUtilization[i])
			}

			score := health * (1.0 / (1.0 + age)) * (1.0 / (1.0 + utilization))

			if !isStructural && !isPinned {
				if score < lowestScore {
					lowestScore = score
					weakestIdx = i
				}
			} else {
				if score < backupScore {
					backupScore = score
					backupCandidate = i
				}
			}
		}

		if weakestIdx == -1 {
			weakestIdx = backupCandidate
		}
		if weakestIdx != -1 {
			log.Printf("⚠️ [MoELayer] Fallback Eviction selected Expert E%d (index >= 48, structural_baseline protected) due to capacity pressure.", weakestIdx)
		}
	}

	return weakestIdx
}

// EvictExpert removes a specific expert by index from the layer.
func (moe *MoELayer) EvictExpert(minIdx int) {
	if minIdx < 0 || minIdx >= len(moe.Experts) {
		return
	}

	newExperts := make([]Expert, 0, len(moe.Experts)-1)
	newAccumulatedUtilization := make([]int, 0, len(moe.Experts)-1)
	newExpertTokenIndices := make([][]int, 0, len(moe.Experts)-1)
	newExpertOutputScale := make([]float32, 0, len(moe.Experts)-1)
	newExpertFrozen := make([]bool, 0, len(moe.Experts)-1)
	newStagnationCounters := make([]int, 0, len(moe.Experts)-1)
	newStepStagnationCounters := make([]int, 0, len(moe.Experts)-1)
	newExpertGradMultiplier := make([]float32, 0, len(moe.Experts)-1)
	newExpertHealth := make([]float64, 0, len(moe.Experts)-1)
	newExpertLastUsedAt := make([]time.Time, 0, len(moe.Experts)-1)
	newExpertPinned := make([]bool, 0, len(moe.Experts)-1)
	newExpertRole := make([]string, 0, len(moe.Experts)-1)

	for i := 0; i < len(moe.Experts); i++ {
		if i == minIdx {
			continue
		}
		newExperts = append(newExperts, moe.Experts[i])
		if i < len(moe.AccumulatedUtilization) {
			newAccumulatedUtilization = append(newAccumulatedUtilization, moe.AccumulatedUtilization[i])
		} else {
			newAccumulatedUtilization = append(newAccumulatedUtilization, 0)
		}
		newExpertTokenIndices = append(newExpertTokenIndices, []int{})

		if i < len(moe.StagnationCounters) {
			newStagnationCounters = append(newStagnationCounters, moe.StagnationCounters[i])
		} else {
			newStagnationCounters = append(newStagnationCounters, 0)
		}

		if i < len(moe.StepStagnationCounters) {
			newStepStagnationCounters = append(newStepStagnationCounters, moe.StepStagnationCounters[i])
		} else {
			newStepStagnationCounters = append(newStepStagnationCounters, 0)
		}

		if i < len(moe.ExpertGradMultiplier) {
			newExpertGradMultiplier = append(newExpertGradMultiplier, moe.ExpertGradMultiplier[i])
		} else {
			newExpertGradMultiplier = append(newExpertGradMultiplier, 1.0)
		}
		if i < len(moe.ExpertOutputScale) {
			newExpertOutputScale = append(newExpertOutputScale, moe.ExpertOutputScale[i])
		} else {
			newExpertOutputScale = append(newExpertOutputScale, 1.0)
		}
		if i < len(moe.ExpertFrozen) {
			newExpertFrozen = append(newExpertFrozen, moe.ExpertFrozen[i])
		} else {
			newExpertFrozen = append(newExpertFrozen, false)
		}
		if i < len(moe.ExpertHealth) {
			newExpertHealth = append(newExpertHealth, moe.ExpertHealth[i])
		} else {
			newExpertHealth = append(newExpertHealth, 1.0)
		}
		if i < len(moe.ExpertLastUsedAt) {
			newExpertLastUsedAt = append(newExpertLastUsedAt, moe.ExpertLastUsedAt[i])
		} else {
			newExpertLastUsedAt = append(newExpertLastUsedAt, time.Now())
		}
		if i < len(moe.ExpertPinned) {
			newExpertPinned = append(newExpertPinned, moe.ExpertPinned[i])
		} else {
			newExpertPinned = append(newExpertPinned, false)
		}
		if i < len(moe.ExpertRole) {
			newExpertRole = append(newExpertRole, moe.ExpertRole[i])
		} else {
			newExpertRole = append(newExpertRole, "")
		}
	}

	moe.Experts = newExperts
	moe.AccumulatedUtilization = newAccumulatedUtilization
	moe.ExpertTokenIndices = newExpertTokenIndices
	moe.ExpertFrozen = newExpertFrozen
	moe.StagnationCounters = newStagnationCounters
	moe.StepStagnationCounters = newStepStagnationCounters
	moe.ExpertGradMultiplier = newExpertGradMultiplier
	moe.ExpertOutputScale = newExpertOutputScale
	moe.ExpertHealth = newExpertHealth
	moe.ExpertLastUsedAt = newExpertLastUsedAt
	moe.ExpertPinned = newExpertPinned
	moe.ExpertRole = newExpertRole
	moe.NumExperts = len(newExperts)

	if moe.GatingNetwork != nil {
		droppedIndices := map[int]bool{minIdx: true}
		moe.GatingNetwork.PruneExperts(droppedIndices)
	}
}

// AtCapacity returns true if the layer has reached the hard maximum expert count.
func (moe *MoELayer) AtCapacity() bool {
	return len(moe.Experts) >= 64
}

// CountStandardExperts returns the number of structural/standard experts in this layer.
// Standard roles: PRON, VERB, AUX, ADJ, NOUN, PREP, and untagged (empty string).
// Used by the supervisor's CanEvict floor check to enforce MinStandardExpertRatio.
func (moe *MoELayer) CountStandardExperts() int {
	count := 0
	for i := range moe.Experts {
		role := ""
		if i < len(moe.ExpertRole) {
			role = moe.ExpertRole[i]
		}
		if role == "PRON" || role == "VERB" || role == "AUX" ||
			role == "ADJ" || role == "NOUN" || role == "PREP" || role == "" {
			count++
		}
	}
	return count
}

// EvictLeastActive uses the standard FindLowestPerformingExpert heuristic to select and
// evict the weakest non-protected expert. Returns the evicted index and whether eviction
// succeeded. Returns (-1, false) if no standard eviction candidate is found.
func (moe *MoELayer) EvictLeastActive(newRole string) (int, bool) {
	idx := moe.FindLowestPerformingExpert(newRole)
	if idx == -1 {
		return -1, false
	}
	moe.EvictExpert(idx)
	return idx, true
}

// ForceEvictLowestUtility is a guaranteed fallback that ignores the Pinned flag for
// any dynamically spawned expert (index >= 32). Core structural experts (indices 0-31)
// remain absolutely protected. Selection is by absolute lowest utility score:
//
//	score = health * (1/(1+age_seconds)) * (1/(1+cumulative_utilization))
//
// Returns the evicted index, or -1 if fewer than 33 experts exist (nothing safe to
// evict under this policy).
func (moe *MoELayer) ForceEvictLowestUtility(newRole string) int {
	if len(moe.Experts) < 33 {
		return -1
	}

	now := time.Now()
	if len(moe.ExpertHealth) != len(moe.Experts) {
		moe.ExpertHealth = make([]float64, len(moe.Experts))
		for i := range moe.ExpertHealth {
			moe.ExpertHealth[i] = 1.0
		}
	}
	if len(moe.ExpertLastUsedAt) != len(moe.Experts) {
		moe.ExpertLastUsedAt = make([]time.Time, len(moe.Experts))
		for i := range moe.ExpertLastUsedAt {
			moe.ExpertLastUsedAt[i] = now
		}
	}
	if len(moe.AccumulatedUtilization) != len(moe.Experts) {
		moe.AccumulatedUtilization = make([]int, len(moe.Experts))
	}

	weakestIdx := -1
	lowestScore := math.MaxFloat64

	isLowValueNewRole := (newRole == "GREET" || newRole == "OTHER")

	totalUtilization := 0
	for _, u := range moe.AccumulatedUtilization {
		totalUtilization += u
	}
	averageUtilization := float64(0.0)
	if len(moe.Experts) > 0 {
		averageUtilization = float64(totalUtilization) / float64(len(moe.Experts))
	}

	var backupCandidate = -1
	var backupScore = math.MaxFloat64
	for i := 48; i < len(moe.Experts); i++ {
		role := ""
		if i < len(moe.ExpertRole) {
			role = moe.ExpertRole[i]
		}

		if role == "structural_baseline" {
			continue
		}
		isStructural := (role == "PRON" || role == "VERB" || role == "AUX" || role == "ADJ" || role == "NOUN" || role == "PREP" || role == "")

		isPinned := false
		if i < len(moe.ExpertPinned) {
			isPinned = moe.ExpertPinned[i]
		}

		util := 0.0
		if i < len(moe.AccumulatedUtilization) {
			util = float64(moe.AccumulatedUtilization[i])
		}
		isHighlyActive := util > averageUtilization && util > 5.0

		if isLowValueNewRole && isStructural && (isPinned || isHighlyActive) {
			continue
		}

		health := moe.ExpertHealth[i]
		age := now.Sub(moe.ExpertLastUsedAt[i]).Seconds()
		utilization := float64(moe.AccumulatedUtilization[i])
		score := health * (1.0 / (1.0 + age)) * (1.0 / (1.0 + utilization))

		if !isStructural && !isPinned {
			if score < lowestScore {
				lowestScore = score
				weakestIdx = i
			}
		} else {
			if score < backupScore {
				backupScore = score
				backupCandidate = i
			}
		}
	}
	if weakestIdx == -1 {
		weakestIdx = backupCandidate
	}

	if weakestIdx == -1 {
		return -1
	}

	log.Printf("🔥 [MoELayer] ForceEvictLowestUtility: Evicting Expert E%d (score=%.6f) to free capacity slot.", weakestIdx, lowestScore)
	moe.EvictExpert(weakestIdx)
	return weakestIdx
}

type LayerSelection struct {
	TokenIDs	[]int
	Selected	[][]int
	Confidences	[][]float32
}

type TokenRoutingHistogram struct {
	// expertToTokens[expertID] = map[tokenID]count
	expertToTokens	map[int]map[int]int
	mu		sync.Mutex
	windowSize	int
	currentStep	int
}

// NewTokenRoutingHistogram creates a histogram tracking tokens per expert over a window.
func NewTokenRoutingHistogram(numExperts, windowSize int) *TokenRoutingHistogram {
	h := &TokenRoutingHistogram{
		expertToTokens:	make(map[int]map[int]int),
		windowSize:	windowSize,
		currentStep:	0,
	}
	for i := 0; i < numExperts; i++ {
		h.expertToTokens[i] = make(map[int]int)
	}
	return h
}

// RecordTokenRoute records that a token routed to an expert.
func (h *TokenRoutingHistogram) RecordTokenRoute(expertID, tokenID int) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if expertID >= 0 && expertID < len(h.expertToTokens) {
		h.expertToTokens[expertID][tokenID]++
	}
	h.currentStep++
}

// RecordBatchTokenRoutes records multiple token-to-expert routings.
// If the batch contains more tokens than expert assignments, the expert list is cycled
// across the sequence so the dashboard still receives meaningful routing activity.
func (h *TokenRoutingHistogram) RecordBatchTokenRoutes(expertIDs, tokenIDs []int) {
	if len(expertIDs) == 0 || len(tokenIDs) == 0 {
		return
	}
	if len(expertIDs) == len(tokenIDs) {
		for i := range expertIDs {
			h.RecordTokenRoute(expertIDs[i], tokenIDs[i])
		}
		return
	}
	for i, tokenID := range tokenIDs {
		h.RecordTokenRoute(expertIDs[i%len(expertIDs)], tokenID)
	}
}

// Reset clears the histogram for the next window.
func (h *TokenRoutingHistogram) Reset() {
	h.mu.Lock()
	defer h.mu.Unlock()
	for i := range h.expertToTokens {
		h.expertToTokens[i] = make(map[int]int)
	}
	h.currentStep = 0
}

// GetTopKTokensPerExpert returns the top K tokens for each expert, decoded to strings.
func (h *TokenRoutingHistogram) GetTopKTokensPerExpert(k int, vocab *vocab.Vocabulary) map[int][]string {
	h.mu.Lock()
	defer h.mu.Unlock()

	result := make(map[int][]string)
	for expertID, tokenCounts := range h.expertToTokens {
		if len(tokenCounts) == 0 {
			result[expertID] = []string{}
			continue
		}

		// Sort by count descending
		type tokenCount struct {
			tokenID	int
			count	int
		}
		var sorted []tokenCount
		for tokenID, count := range tokenCounts {
			sorted = append(sorted, tokenCount{tokenID, count})
		}
		sort.Slice(sorted, func(i, j int) bool {
			return sorted[i].count > sorted[j].count
		})

		for i := 0; i < k && i < len(sorted); i++ {
			tokenID := sorted[i].tokenID
			word := ""
			if vocab != nil {
				word = vocab.GetWord(tokenID)
			}

			if word == "" && ObservabilityInstance != nil && ObservabilityInstance.SemanticDrift != nil && ObservabilityInstance.SemanticDrift.vocab != nil {
				word = ObservabilityInstance.SemanticDrift.vocab.GetWord(tokenID)
			}
			if word == "" || word == "UNK" || word == "<unk>" {
				word = fmt.Sprintf("ID:%d", tokenID)
			}
			result[expertID] = append(result[expertID], word)
		}
	}
	return result
}

type TokenCategory struct {
	Name		string
	TokenIDs	[]int
	Color		string
}

// LoadTokenCategories loads token categories from config (or hardcoded defaults).
func LoadTokenCategories(vocab *vocab.Vocabulary) []TokenCategory {

	categories := []TokenCategory{
		{
			Name:	"Structural Words",
			Color:	"#6366f1",
		},
		{
			Name:	"Core Verbs",
			Color:	"#ec4899",
		},
		{
			Name:	"Technical Terms",
			Color:	"#f59e0b",
		},
		{
			Name:	"Punctuation",
			Color:	"#8b5cf6",
		},
	}

	structuralWords := []string{"the", "a", "an", "is", "are", "to", "and", "or", "of", "in", "at", "on"}
	coreVerbs := []string{"make", "go", "run", "do", "get", "set", "see", "come", "go", "use", "help", "turn"}
	technicalTerms := []string{"file", "directory", "command", "script", "code", "function", "class", "module"}
	punctuation := []string{".", ",", "!", "?", ":", ";", "-", "(", ")", "[", "]"}

	for _, word := range structuralWords {
		id := vocab.GetTokenID(word)
		if id == -1 {

			id = vocab.AddToken(word)
		}
		if id != -1 {
			categories[0].TokenIDs = append(categories[0].TokenIDs, id)
		}
	}
	for _, word := range coreVerbs {
		id := vocab.GetTokenID(word)
		if id == -1 {
			id = vocab.AddToken(word)
		}
		if id != -1 {
			categories[1].TokenIDs = append(categories[1].TokenIDs, id)
		}
	}
	for _, word := range technicalTerms {
		id := vocab.GetTokenID(word)
		if id == -1 {
			id = vocab.AddToken(word)
		}
		if id != -1 {
			categories[2].TokenIDs = append(categories[2].TokenIDs, id)
		}
	}
	for _, word := range punctuation {
		id := vocab.GetTokenID(word)
		if id == -1 {
			id = vocab.AddToken(word)
		}
		if id != -1 {
			categories[3].TokenIDs = append(categories[3].TokenIDs, id)
		}
	}

	return categories
}

type TokenCategoryLossTracker struct {
	categories	[]TokenCategory
	categoryLosses	map[string]*CategoryLossStats
	mu		sync.Mutex
}

// NewTokenCategoryLossTracker creates a loss tracker for token categories.
func NewTokenCategoryLossTracker(categories []TokenCategory) *TokenCategoryLossTracker {
	tracker := &TokenCategoryLossTracker{
		categories:	categories,
		categoryLosses:	make(map[string]*CategoryLossStats),
	}
	for _, cat := range categories {
		tracker.categoryLosses[cat.Name] = &CategoryLossStats{}
	}
	return tracker
}

// RecordLossForTokens records the loss contribution for specific token IDs.
func (t *TokenCategoryLossTracker) RecordLossForTokens(loss float32, tokenIDs []int) {
	t.mu.Lock()
	defer t.mu.Unlock()

	matchedAny := false
	for _, tokenID := range tokenIDs {
		for _, cat := range t.categories {
			for _, catTokenID := range cat.TokenIDs {
				if catTokenID == tokenID {
					stats := t.categoryLosses[cat.Name]
					stats.TotalLoss += loss
					stats.Count++
					matchedAny = true
					break
				}
			}
		}
	}
	if !matchedAny && len(tokenIDs) > 0 {

	}
}

// GetCategoryLossMetrics returns loss stats per category.
func (t *TokenCategoryLossTracker) GetCategoryLossMetrics() map[string]map[string]interface{} {
	t.mu.Lock()
	defer t.mu.Unlock()

	result := make(map[string]map[string]interface{})
	for catName, stats := range t.categoryLosses {
		avgLoss := float32(0)
		if stats.Count > 0 {
			avgLoss = stats.TotalLoss / float32(stats.Count)
		}
		result[catName] = map[string]interface{}{
			"average_loss":		avgLoss,
			"sample_count":		stats.Count,
			"total_loss":		stats.TotalLoss,
			"improvement":		stats.Improvement,
			"improvement_rate":	float32(math.Abs(float64(stats.Improvement)) / float64(math.Max(float64(stats.PreviousDelta), 1e-6))),
		}
	}
	return result
}

// UpdateImprovement calculates loss improvement between epochs.
func (t *TokenCategoryLossTracker) UpdateImprovement() {
	t.mu.Lock()
	defer t.mu.Unlock()

	for _, stats := range t.categoryLosses {
		avgLoss := float32(0)
		if stats.Count > 0 {
			avgLoss = stats.TotalLoss / float32(stats.Count)
		}
		stats.PreviousDelta = stats.CurrentDelta
		stats.CurrentDelta = avgLoss
		stats.Improvement = stats.PreviousDelta - stats.CurrentDelta
		stats.TotalLoss = 0
		stats.Count = 0
	}
}

type WeightVelocityTracker struct {
	previousWeights	map[string][]float32
	velocities	map[string]float32
	mu		sync.Mutex
}

// NewWeightVelocityTracker creates a velocity tracker.
func NewWeightVelocityTracker() *WeightVelocityTracker {
	return &WeightVelocityTracker{
		previousWeights:	make(map[string][]float32),
		velocities:		make(map[string]float32),
	}
}

// RecordWeightSnapshot captures current weight state for delta calculation.
func (w *WeightVelocityTracker) RecordWeightSnapshot(layerName string, weights []float32) {
	w.mu.Lock()
	defer w.mu.Unlock()

	snapshot := make([]float32, len(weights))
	copy(snapshot, weights)
	w.previousWeights[layerName] = snapshot
}

// UpdateWeightVelocity calculates velocity (Frobenius norm of weight delta).
func (w *WeightVelocityTracker) UpdateWeightVelocity(layerName string, currentWeights []float32) {
	w.mu.Lock()
	defer w.mu.Unlock()

	if prev, ok := w.previousWeights[layerName]; ok {
		if len(prev) != len(currentWeights) {
			return
		}

		// Calculate Frobenius norm: sqrt(sum(dW_ij^2))
		var sumSq float32
		for i := range currentWeights {
			delta := currentWeights[i] - prev[i]
			sumSq += delta * delta
		}
		velocity := float32(math.Sqrt(float64(sumSq)))
		w.velocities[layerName] = velocity
	}
}

// GetVelocityHeatmap returns the velocity grid for visualization.
func (w *WeightVelocityTracker) GetVelocityHeatmap() map[string]interface{} {
	w.mu.Lock()
	defer w.mu.Unlock()

	// Normalize velocities to [0, 1] for heatmap coloring
	var maxVel float32
	for _, vel := range w.velocities {
		if vel > maxVel {
			maxVel = vel
		}
	}
	if maxVel == 0 {
		maxVel = 1
	}

	normalized := make(map[string]float32)
	for name, vel := range w.velocities {
		normalized[name] = vel / maxVel
	}

	return map[string]interface{}{
		"velocities":	w.velocities,
		"normalized":	normalized,
		"max_velocity":	maxVel,
	}
}

// NewSemanticDriftTracker creates a drift tracker with Word2Vec baseline.
func NewSemanticDriftTracker(w2vModel *word2vec.SimpleWord2Vec, vocab *vocab.Vocabulary) *SemanticDriftTracker {
	tracker := &SemanticDriftTracker{
		baselineEmbeddings:	make(map[int][]float32),
		currentEmbeddings:	make(map[int][]float32),
		w2vModel:		w2vModel,
		vocab:			vocab,
	}

	if w2vModel != nil && w2vModel.WordVectorsF32 != nil {
		for tokenID, vec := range w2vModel.WordVectorsF32 {
			baseline := make([]float32, len(vec))
			copy(baseline, vec)
			tracker.baselineEmbeddings[tokenID] = baseline
		}
	}

	return tracker
}

// RecordEmbeddingState captures current embedding vectors for specific tokens.
func (s *SemanticDriftTracker) RecordEmbeddingState(embeddingTensor *tensor.Tensor) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if embeddingTensor == nil {
		return
	}

	data := embeddingTensor.Data
	s.currentEmbeddings = make(map[int][]float32)

	numTokens := len(data) / 64
	for i := 0; i < numTokens && i*64 < len(data); i++ {
		embedding := make([]float32, 64)
		copy(embedding, data[i*64:(i+1)*64])
		s.currentEmbeddings[i] = embedding
	}

	if len(s.baselineEmbeddings) == 0 && len(s.currentEmbeddings) > 0 {
		s.baselineEmbeddings = make(map[int][]float32, len(s.currentEmbeddings))
		for tokenID, vec := range s.currentEmbeddings {
			baseline := make([]float32, len(vec))
			copy(baseline, vec)
			s.baselineEmbeddings[tokenID] = baseline
		}
	}
}

// cosineSimilarityInternal calculates cosine distance between two vectors.
// Note: Use the moe_layer.CosineSimilarity for consistency
func cosineSimilarityInternal(a, b []float32) float32 {
	if len(a) != len(b) || len(a) == 0 {
		return 0
	}

	var dotProd, normA, normB float32
	for i := range a {
		dotProd += a[i] * b[i]
		normA += a[i] * a[i]
		normB += b[i] * b[i]
	}

	normA = float32(math.Sqrt(float64(normA)))
	normB = float32(math.Sqrt(float64(normB)))

	if normA == 0 || normB == 0 {
		return 0
	}
	return dotProd / (normA * normB)
}

// GetTopSemanticShifts returns the top N tokens with largest embedding shifts.
func (s *SemanticDriftTracker) GetTopSemanticShifts(topN int) []map[string]interface{} {
	s.mu.Lock()
	defer s.mu.Unlock()

	type drift struct {
		tokenID		int
		distance	float32
		word		string
	}

	var drifts []drift
	for tokenID, currentVec := range s.currentEmbeddings {
		if baseVec, ok := s.baselineEmbeddings[tokenID]; ok {

			similarity := cosineSimilarityInternal(currentVec, baseVec)
			distance := 1 - similarity
			word := s.vocab.GetWord(tokenID)
			if word == "" {
				word = fmt.Sprintf("[%d]", tokenID)
			}
			drifts = append(drifts, drift{tokenID, distance, word})
		}
	}

	sort.Slice(drifts, func(i, j int) bool {
		return drifts[i].distance > drifts[j].distance
	})

	result := make([]map[string]interface{}, 0)
	for i := 0; i < topN && i < len(drifts); i++ {
		result = append(result, map[string]interface{}{
			"token":	drifts[i].word,
			"drift":	drifts[i].distance,
			"token_id":	drifts[i].tokenID,
		})
	}

	return result
}

