type TokenTrajectory struct {
	tokenID		int
	tokenStr	string
	layers		[]int		// expertID per layer
	confidence	[]float32	// routing confidence per layer
}

type TokenTrajectoryTracker struct {
	trajectories	[]TokenTrajectory
	mu		sync.Mutex
	maxSize		int
}

// NewTokenTrajectoryTracker creates a trajectory tracker.
func NewTokenTrajectoryTracker(maxSize int) *TokenTrajectoryTracker {
	return &TokenTrajectoryTracker{
		trajectories:	make([]TokenTrajectory, 0),
		maxSize:	maxSize,
	}
}

// RecordTokenTrajectory records the full layer-by-layer routing path for a token.
func (t *TokenTrajectoryTracker) RecordTokenTrajectory(tokenID int, tokenStr string, expertPath []int, confidences []float32) {
	t.mu.Lock()
	defer t.mu.Unlock()

	trajectory := TokenTrajectory{
		tokenID:	tokenID,
		tokenStr:	tokenStr,
		layers:		append([]int{}, expertPath...),
		confidence:	append([]float32{}, confidences...),
	}

	t.trajectories = append(t.trajectories, trajectory)

	if len(t.trajectories) > t.maxSize {
		t.trajectories = t.trajectories[len(t.trajectories)-t.maxSize:]
	}
}

// GetTrajectories returns all recorded token trajectories.
func (t *TokenTrajectoryTracker) GetTrajectories() []map[string]interface{} {
	t.mu.Lock()
	defer t.mu.Unlock()

	result := make([]map[string]interface{}, len(t.trajectories))
	for i, traj := range t.trajectories {
		result[i] = map[string]interface{}{
			"token":	traj.tokenStr,
			"token_id":	traj.tokenID,
			"layer_path":	traj.layers,
			"confidence":	traj.confidence,
			"avg_conf":	avgFloat32(traj.confidence),
		}
	}
	return result
}

type PCAProjection struct {
	words		[]string
	coordinates	[]map[string]float32	// {x, y} per word
	cluster		map[string]int		// cluster assignment per word
	mu		sync.Mutex
}

// NewPCAProjection creates a PCA projection tracker.
func NewPCAProjection() *PCAProjection {
	return &PCAProjection{
		words:		make([]string, 0),
		coordinates:	make([]map[string]float32, 0),
		cluster:	make(map[string]int),
	}
}

// ComputeEmbeddingProjection computes a 2D PCA-like projection of embeddings.
func (p *PCAProjection) ComputeEmbeddingProjection(vocab *vocab.Vocabulary, embeddingTensor *tensor.Tensor, topN int) {
	p.mu.Lock()
	defer p.mu.Unlock()

	if embeddingTensor == nil || vocab == nil {
		return
	}

	if len(embeddingTensor.Shape) < 2 {
		return
	}
	vocabSize := embeddingTensor.Shape[0]
	embDim := embeddingTensor.Shape[1]

	if topN <= 0 || topN > vocabSize {
		topN = vocabSize
	}

	data := make([]float64, topN*embDim)
	words := make([]string, 0, topN)
	for i := 0; i < topN; i++ {
		word := vocab.GetWord(i)
		if word == "" || word == "[PAD]" || word == "[UNK]" {
			words = append(words, word)
		} else {
			words = append(words, word)
		}
		for j := 0; j < embDim; j++ {
			idx := i*embDim + j
			if idx < len(embeddingTensor.Data) {
				data[i*embDim+j] = float64(embeddingTensor.Data[idx])
			} else {
				data[i*embDim+j] = 0
			}
		}
	}

	A := mat.NewDense(topN, embDim, data)

	colMean := make([]float64, embDim)
	for j := 0; j < embDim; j++ {
		var sum float64
		for i := 0; i < topN; i++ {
			sum += A.At(i, j)
		}
		colMean[j] = sum / float64(topN)
		for i := 0; i < topN; i++ {
			A.Set(i, j, A.At(i, j)-colMean[j])
		}
	}

	// SVD
	var svd mat.SVD
	ok := svd.Factorize(A, mat.SVDThin)
	if !ok {
		return
	}

	var V mat.Dense
	svd.VTo(&V)

	r, c := V.Dims()
	k := 2
	if c < 2 {
		k = c
	}
	Vsub := mat.NewDense(r, k, nil)
	for i := 0; i < r; i++ {
		for j := 0; j < k; j++ {
			Vsub.Set(i, j, V.At(i, j))
		}
	}

	// Project: coords = A * Vsub  (topN x k)
	var coords mat.Dense
	coords.Mul(A, Vsub)

	p.words = make([]string, topN)
	p.coordinates = make([]map[string]float32, topN)
	p.cluster = make(map[string]int)
	for i := 0; i < topN; i++ {
		x := float32(coords.At(i, 0))
		y := float32(0)
		if k >= 2 {
			y = float32(coords.At(i, 1))
		}

		nx := normalizeCoord(x)
		ny := normalizeCoord(y)
		p.words[i] = words[i]
		p.coordinates[i] = map[string]float32{"x": nx, "y": ny}
		p.cluster[words[i]] = i % 5
	}
}

// GetProjectionCoordinates returns the 2D coordinates for visualization.
func (p *PCAProjection) GetProjectionCoordinates() []map[string]interface{} {
	p.mu.Lock()
	defer p.mu.Unlock()

	result := make([]map[string]interface{}, len(p.words))
	for i, word := range p.words {
		cluster := 0
		if c, ok := p.cluster[word]; ok {
			cluster = c
		}

		result[i] = map[string]interface{}{
			"word":		word,
			"x":		p.coordinates[i]["x"],
			"y":		p.coordinates[i]["y"],
			"cluster":	cluster,
		}
	}
	return result
}

type ExpertSimilarityMatrix struct {
	expertWeights	map[int][][]float32	// expertID → weights
	similarities	[][]float32		// similarity matrix
	mu		sync.Mutex
}

// NewExpertSimilarityMatrix creates a similarity tracker.
func NewExpertSimilarityMatrix(numExperts int) *ExpertSimilarityMatrix {
	return &ExpertSimilarityMatrix{
		expertWeights:	make(map[int][][]float32),
		similarities:	nil,
	}
}

// RecordExpertWeights records the weight matrices of experts.
func (e *ExpertSimilarityMatrix) RecordExpertWeights(expertID int, weights []float32) {
	e.mu.Lock()
	defer e.mu.Unlock()

	e.expertWeights[expertID] = reshapeWeights(weights, 16)
}

// ComputeSimilarityMatrix computes cosine similarity between all expert pairs.
func (e *ExpertSimilarityMatrix) ComputeSimilarityMatrix() {
	e.mu.Lock()
	defer e.mu.Unlock()

	keys := make([]int, 0, len(e.expertWeights))
	for k := range e.expertWeights {
		keys = append(keys, k)
	}
	sort.Ints(keys)

	n := len(keys)
	if n == 0 {
		e.similarities = nil
		return
	}

	e.similarities = make([][]float32, n)
	for i := range e.similarities {
		e.similarities[i] = make([]float32, n)
	}

	flats := make([][]float32, n)
	for i, k := range keys {
		flats[i] = e.flattenWeights(e.expertWeights[k])
	}

	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if i == j {
				e.similarities[i][j] = 1.0
				continue
			}
			e.similarities[i][j] = cosineSimilarityInternal(flats[i], flats[j])
		}
	}
}

// GetSimilarityMatrix returns the similarity matrix as a 2D array.
func (e *ExpertSimilarityMatrix) GetSimilarityMatrix() [][]float32 {
	e.mu.Lock()
	defer e.mu.Unlock()

	if e.similarities == nil {
		return nil
	}
	result := make([][]float32, len(e.similarities))
	for i := range e.similarities {
		result[i] = make([]float32, len(e.similarities[i]))
		copy(result[i], e.similarities[i])
	}
	return result
}

// GetRedundancyWarnings returns list of experts that are too similar.
func (e *ExpertSimilarityMatrix) GetRedundancyWarnings(threshold float32) []map[string]interface{} {
	e.mu.Lock()
	defer e.mu.Unlock()

	warnings := make([]map[string]interface{}, 0)

	for i := 0; i < len(e.similarities); i++ {
		for j := i + 1; j < len(e.similarities); j++ {
			if e.similarities[i][j] > threshold {
				warnings = append(warnings, map[string]interface{}{
					"expert_a":	i,
					"expert_b":	j,
					"similarity":	e.similarities[i][j],
					"alert":	"⚠️ Experts are too similar - consider forcing surgery mutation",
				})
			}
		}
	}

	return warnings
}

// flattenWeights converts 2D weight matrix to 1D array.
func (e *ExpertSimilarityMatrix) flattenWeights(weights [][]float32) []float32 {
	result := make([]float32, 0)
	for _, row := range weights {
		result = append(result, row...)
	}
	return result
}

func normalizeCoord(val float32) float32 {

	return float32(math.Tanh(float64(val)))
}

func reshapeWeights(flat []float32, cols int) [][]float32 {
	if len(flat) == 0 || cols == 0 {
		return [][]float32{}
	}

	rows := (len(flat) + cols - 1) / cols
	result := make([][]float32, rows)

	for i := 0; i < rows; i++ {
		start := i * cols
		end := start + cols
		if end > len(flat) {
			end = len(flat)
		}
		result[i] = flat[start:end]
	}

	return result
}

func avgFloat32(arr []float32) float32 {
	if len(arr) == 0 {
		return 0
	}
	var sum float32
	for _, v := range arr {
		sum += v
	}
	return sum / float32(len(arr))
}

type MoEStack struct {
	Layers	[]*MoELayer
	Norms	[]*nn.LayerNormalization
}

// NewMoEStack creates a new MoEStack.
func NewMoEStack(layers ...*MoELayer) *MoEStack {
	norms := make([]*nn.LayerNormalization, len(layers))
	for i, l := range layers {
		norms[i] = nn.NewLayerNormalization(l.InputDim)
	}
	return &MoEStack{Layers: layers, Norms: norms}
}

// Forward performs the forward pass of the MoEStack with residual connections.
func (s *MoEStack) Forward(inputs ...*tensor.Tensor) (*tensor.Tensor, error) {
	if len(inputs) == 0 {
		return nil, fmt.Errorf("MoEStack.Forward expects at least 1 input")
	}

	x := inputs[0]
	for i, layer := range s.Layers {
		out, err := layer.Forward(x)
		if err != nil {
			return nil, err
		}

		// Residual: x = x + layer(x) * scale
		var outScaled *tensor.Tensor
		if layer.ResidualScale != nil {
			var err error
			outScaled, err = out.MulScalar(layer.ResidualScale.Data[0])
			if err != nil {
				return nil, fmt.Errorf("MoEStack residual scale failed: %w", err)
			}
			outScaled.Creator = out.Creator
		} else {
			outScaled = out
		}

		res, err := x.Add(outScaled)
		if err != nil {
			return nil, fmt.Errorf("MoEStack residual add failed: %w", err)
		}

		if i < len(s.Norms) {
			normed, err := s.Norms[i].Forward(res)
			if err != nil {
				return nil, fmt.Errorf("MoEStack layer norm forward failed: %w", err)
			}
			x = normed
		} else {
			x = res
		}
	}

	return x, nil
}

// Backward performs the backward pass for the MoEStack.
func (s *MoEStack) Backward(grad *tensor.Tensor) error {

	currGrad := grad
	for i := len(s.Layers) - 1; i >= 0; i-- {
		layer := s.Layers[i]

		if i < len(s.Norms) {
			if err := s.Norms[i].Backward(currGrad); err != nil {
				return fmt.Errorf("MoEStack layer norm backward failed: %w", err)
			}
			currGrad = s.Norms[i].Inputs()[0].Grad
		}

		layerGrad := currGrad
		if layer.ResidualScale != nil {
			layerGrad, _ = currGrad.MulScalar(layer.ResidualScale.Data[0])

			if layer.ResidualScale.RequiresGrad {
				if layer.ResidualScale.Grad == nil {
					layer.ResidualScale.Grad = tensor.NewTensor(layer.ResidualScale.Shape, make([]float32, 1), false)
				}

				stack := layer.GetStateStack()
				if len(stack) > 0 {
					lastOutput := stack[len(stack)-1].lastOutput
					normFactor := 1.0 / float32(len(currGrad.Data))
					var dScale float32
					for j := range currGrad.Data {
						dScale += currGrad.Data[j] * lastOutput.Data[j]
					}
					layer.ResidualScale.Grad.Data[0] += dScale * normFactor
				}
			}
		}

		if err := layer.Backward(layerGrad); err != nil {
			return err
		}

		if len(layer.Inputs()) == 0 {
			continue
		}

		input := layer.Inputs()[0]
		if input.Grad == nil {
			input.Grad = tensor.NewTensor(input.Shape, make([]float32, len(input.Data)), false)
		}

		tensor.AddAccumulate(input.Grad.Data, currGrad.Data)

		currGrad = input.Grad
	}
	return nil
}

// Parameters returns all learnable parameters of the MoEStack.
func (s *MoEStack) Parameters() []*tensor.Tensor {
	params := []*tensor.Tensor{}
	for _, layer := range s.Layers {
		params = append(params, layer.Parameters()...)
	}
	for _, norm := range s.Norms {
		params = append(params, norm.Parameters()...)
	}
	return params
}

// Inputs returns the input tensors of the MoEStack.
func (s *MoEStack) Inputs() []*tensor.Tensor {
	if len(s.Layers) > 0 {
		return s.Layers[0].Inputs()
	}
	return []*tensor.Tensor{}
}

// SetMode sets training/inference mode for all layers.
func (s *MoEStack) SetMode(training bool) {
	for _, l := range s.Layers {
		l.SetMode(training)
	}
}

// ClearState clears internal states for BPTT.
func (s *MoEStack) ClearState() {
	for _, l := range s.Layers {
		l.ClearState()
	}
}

func (s *MoEStack) GetMoELayers() []*MoELayer {
	return s.Layers
}

// SetGateTemperature updates the temperature for all layers in the stack.
func (s *MoEStack) SetGateTemperature(temp float32) {
	for _, l := range s.Layers {
		l.SetGateTemperature(temp)
	}
}

// ToGPU moves all layers in the stack to the GPU.
func (s *MoEStack) ToGPU() {
	for _, l := range s.Layers {
		if l != nil {
			l.ToGPU()
		}
	}
}

func (s *MoEStack) SyncParameters() error {
	for _, l := range s.Layers {
		if l != nil {
			if err := l.SyncParameters(); err != nil {
				return err
			}
		}
	}
	return nil
}

func (s *MoEStack) RepairArchitecture() {
	if s.Norms == nil || len(s.Norms) != len(s.Layers) {
		s.Norms = make([]*nn.LayerNormalization, len(s.Layers))
		for i, l := range s.Layers {
			s.Norms[i] = nn.NewLayerNormalization(l.InputDim)
		}
	}
	for _, l := range s.Layers {
		if l != nil {
			l.RepairArchitecture()
		}
	}
}

// NewMotionWindow creates a MotionWindow backed by the given TemporalEncoder and
// a pre-trained linear classification head (headW, headB).
// classNames must be ordered to match the class indices used during training.
func NewMotionWindow(capacity int, te *TemporalEncoder, headW, headB []float32, classNames []string) *MotionWindow {
	return &MotionWindow{
		Capacity:	capacity,
		Signatures:	make([][]float32, capacity),
		encoder:	te,
		headW:		headW,
		headB:		headB,
		ClassNames:	classNames,
	}
}

// NewMotionWindowSimple creates an untrained MotionWindow (no classifier).
// Useful for collecting frames before a trained head is available.
func NewMotionWindowSimple(capacity int) *MotionWindow {
	return &MotionWindow{
		Capacity:	capacity,
		Signatures:	make([][]float32, capacity),
	}
}

// Push appends a new frame's geometric feature vector, evicting the oldest.
// Safe to call from any goroutine.
func (mw *MotionWindow) Push(sig []float32) {
	mw.mu.Lock()
	defer mw.mu.Unlock()
	mw.Signatures[mw.Head] = sig
	mw.Head = (mw.Head + 1) % mw.Capacity
	if mw.filled < mw.Capacity {
		mw.filled++
	}
}

// Ready returns true once the buffer has received at least Capacity frames.
func (mw *MotionWindow) Ready() bool {
	mw.mu.RLock()
	defer mw.mu.RUnlock()
	return mw.filled >= mw.Capacity
}

// GetOrderedSequence returns the buffered frames in strict chronological order
// (oldest → newest), suitable for direct input to TemporalEncoder.Forward().
func (mw *MotionWindow) GetOrderedSequence() [][]float32 {
	mw.mu.RLock()
	defer mw.mu.RUnlock()
	seq := make([][]float32, mw.Capacity)
	for i := 0; i < mw.Capacity; i++ {
		idx := (mw.Head + i) % mw.Capacity
		seq[i] = mw.Signatures[idx]
	}
	return seq
}

// Classify runs a forward pass through the GRU and the linear head and returns
// a human-readable motion token string, e.g. "[MOTION: TILT_UP]".
// Returns an empty string and an error if the buffer is not yet full or no
// classifier has been wired in.
func (mw *MotionWindow) Classify() (string, error) {
	if !mw.Ready() {
		return "", fmt.Errorf("motion window not yet full (%d/%d frames)", mw.filled, mw.Capacity)
	}
	if mw.encoder == nil || len(mw.headW) == 0 {
		return "", fmt.Errorf("no classifier wired into MotionWindow")
	}

	seq := mw.GetOrderedSequence()

	motionVec := mw.encoder.Forward(seq)

	numClasses := len(mw.ClassNames)
	hiddenDim := mw.encoder.HiddenDim
	logits := make([]float32, numClasses)
	for c := 0; c < numClasses; c++ {
		for d := 0; d < hiddenDim; d++ {
			logits[c] += mw.headW[c*hiddenDim+d] * motionVec[d]
		}
		logits[c] += mw.headB[c]
	}

	best := 0
	for c := 1; c < numClasses; c++ {
		if logits[c] > logits[best] {
			best = c
		}
	}

	return fmt.Sprintf("[MOTION: %s]", mw.ClassNames[best]), nil
}

type IntentRule struct {
	ParentIntent	string
	ChildIntent	string

	// GrammarSkeleton defines the expected sequence of POS types (simplified)
	// Example: ["PRON", "VERB", "ADJ"] -> "I am happy"
	GrammarSkeleton	[]string

	// RequiredKeywords are words that SHOULD be present for this intent to be valid.
	RequiredKeywords	[]string

	// ForbiddenPatterns are sequences that make the sentence incoherent for this intent.
	ForbiddenPatterns	[]string
}

// EvaluateWindow evaluates a sliding window of three consecutive tokens (Tri-grams)
// to catch complex errors that bigrams miss, such as missing words in verb phrases
// or improper punctuation placement.
func (r *IntentRule) EvaluateWindow(prev, curr, next string) float32 {
	var penalty float32 = 0.0

	if prev == "AUX" && curr != "VERB" && curr != "ADJ" && curr != "PREP" && curr != "PRON" {
		penalty += 0.3
	}

	if next == "EOS" && (curr == "AUX" || curr == "PREP" || curr == "INTERROGATIVE") {
		penalty += 0.4
	}

	if prev == "PRON" && curr == "PRON" {
		penalty += 0.2
	}

	return penalty
}

