	maxIdx := 0
	maxVal := data[0]
	for i, v := range data {
		if v > maxVal {
			maxVal = v
			maxIdx = i
		}
	}
	return maxIdx
}

// SimdAddF32 computes a[i] += b[i] using SIMD.
func SimdAddF32(a, b []float32) {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	i := 0

	for ; i+32 <= n; i += 32 {
		va0 := archsimd.LoadFloat32x8Slice(a[i:])
		vb0 := archsimd.LoadFloat32x8Slice(b[i:])
		va1 := archsimd.LoadFloat32x8Slice(a[i+8:])
		vb1 := archsimd.LoadFloat32x8Slice(b[i+8:])
		va2 := archsimd.LoadFloat32x8Slice(a[i+16:])
		vb2 := archsimd.LoadFloat32x8Slice(b[i+16:])
		va3 := archsimd.LoadFloat32x8Slice(a[i+24:])
		vb3 := archsimd.LoadFloat32x8Slice(b[i+24:])

		va0.Add(vb0).StoreSlice(a[i:])
		va1.Add(vb1).StoreSlice(a[i+8:])
		va2.Add(vb2).StoreSlice(a[i+16:])
		va3.Add(vb3).StoreSlice(a[i+24:])
	}
	for ; i+8 <= n; i += 8 {
		va := archsimd.LoadFloat32x8Slice(a[i:])
		vb := archsimd.LoadFloat32x8Slice(b[i:])
		va.Add(vb).StoreSlice(a[i:])
	}
	for ; i < n; i++ {
		a[i] += b[i]
	}
}

// SimdSubF32 computes a[i] -= b[i] using SIMD.
func SimdSubF32(a, b []float32) {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	i := 0

	for ; i+32 <= n; i += 32 {
		va0 := archsimd.LoadFloat32x8Slice(a[i:])
		vb0 := archsimd.LoadFloat32x8Slice(b[i:])
		va1 := archsimd.LoadFloat32x8Slice(a[i+8:])
		vb1 := archsimd.LoadFloat32x8Slice(b[i+8:])
		va2 := archsimd.LoadFloat32x8Slice(a[i+16:])
		vb2 := archsimd.LoadFloat32x8Slice(b[i+16:])
		va3 := archsimd.LoadFloat32x8Slice(a[i+24:])
		vb3 := archsimd.LoadFloat32x8Slice(b[i+24:])

		va0.Sub(vb0).StoreSlice(a[i:])
		va1.Sub(vb1).StoreSlice(a[i+8:])
		va2.Sub(vb2).StoreSlice(a[i+16:])
		va3.Sub(vb3).StoreSlice(a[i+24:])
	}
	for ; i+8 <= n; i += 8 {
		va := archsimd.LoadFloat32x8Slice(a[i:])
		vb := archsimd.LoadFloat32x8Slice(b[i:])
		va.Sub(vb).StoreSlice(a[i:])
	}
	for ; i < n; i++ {
		a[i] -= b[i]
	}
}

// SimdIsFiniteF32 returns true if all elements in the slice are finite (not NaN or Inf).
func SimdIsFiniteF32(data []float32) bool {
	n := len(data)
	i := 0
	for ; i+8 <= n; i += 8 {
		v := archsimd.LoadFloat32x8Slice(data[i:])

		diff := v.Sub(v)
		var buf [8]float32
		diff.Store(&buf)
		for _, d := range buf {
			if d != 0 {
				return false
			}
		}
	}
	for ; i < n; i++ {
		if math.IsNaN(float64(data[i])) || math.IsInf(float64(data[i]), 0) {
			return false
		}
	}
	return true
}

// SimdExpF32 computes exp(x) for every element in data using a fast SIMD approximation.
// Uses the trick: exp(x) = 2^(x * log2(e))
func SimdExpF32(data []float32) {
	n := len(data)
	i := 0

	log2e := archsimd.BroadcastFloat32x8(12102203.0)
	offset := archsimd.BroadcastFloat32x8(1065353216.0)

	for ; i+8 <= n; i += 8 {
		v := archsimd.LoadFloat32x8Slice(data[i:])

		vexp := v.Mul(log2e).Add(offset)

		// In archsimd, we don't have direct bit manipulation yet in all versions,
		// so we store and use math.Float32frombits if needed, but we can try to use
		// the fact that adding to the bit representation of a float is roughly exp.
		// However, for best performance, we'll use a scalar fallback if archsimd doesn't expose bit casts.
		// For now, let's use the scalar fast-path if SIMD bit-cast is missing.
		var buf [8]float32
		vexp.Store(&buf)
		for j := 0; j < 8; j++ {
			data[i+j] = math.Float32frombits(uint32(buf[j]))
		}
	}

	for ; i < n; i++ {
		data[i] = float32(math.Exp(float64(data[i])))
	}
}

// SimdSoftmaxF32 performs an in-place softmax on a row.
func SimdSoftmaxF32(data []float32) float32 {
	n := len(data)
	if n == 0 {
		return 0
	}

	maxVal := SimdMaxSliceF32(data)

	vMax := archsimd.BroadcastFloat32x8(maxVal)
	i := 0
	for ; i+8 <= n; i += 8 {
		v := archsimd.LoadFloat32x8Slice(data[i:])
		v.Sub(vMax).StoreSlice(data[i:])
	}
	for ; i < n; i++ {
		data[i] -= maxVal
	}

	SimdExpF32(data)

	// 3. Sum and Normalize
	var sumExp float32
	i = 0
	var vSum8 archsimd.Float32x8
	for ; i+8 <= n; i += 8 {
		v := archsimd.LoadFloat32x8Slice(data[i:])
		vSum8 = vSum8.Add(v)
	}

	// Horizontal sum
	var buf [8]float32
	vSum8.Store(&buf)
	for _, v := range buf {
		sumExp += v
	}
	for ; i < n; i++ {
		sumExp += data[i]
	}

	if sumExp > 0 {
		SimdScaleF32(data, 1.0/sumExp)
	}
	return sumExp
}

// computeRouterLogitsSIMD is the pure-Go fallback.
func computeRouterLogitsSIMD(
	inputFlat []float32,
	routerWeightsData []float32,
	numTokens, numExperts, inputDim int,
	logitsOut []float32,
) {
	numWorkers := runtime.NumCPU()
	if numTokens < 64 {
		numWorkers = 1
	}
	tokensPerWorker := (numTokens + numWorkers - 1) / numWorkers

	var wg sync.WaitGroup
	for w := 0; w < numWorkers; w++ {
		start := w * tokensPerWorker
		end := (w + 1) * tokensPerWorker
		if start >= numTokens {
			break
		}
		if end > numTokens {
			end = numTokens
		}

		wg.Add(1)
		go func(tokenStart, tokenEnd int) {
			defer wg.Done()
			for tokenIdx := tokenStart; tokenIdx < tokenEnd; tokenIdx++ {
				tokenBase := tokenIdx * inputDim
				outBase := tokenIdx * numExperts
				for expertIdx := 0; expertIdx < numExperts; expertIdx++ {
					var dot float32
					k := 0

					for ; k+8 <= inputDim; k += 8 {
						dot += inputFlat[tokenBase+k] * routerWeightsData[k*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+1] * routerWeightsData[(k+1)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+2] * routerWeightsData[(k+2)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+3] * routerWeightsData[(k+3)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+4] * routerWeightsData[(k+4)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+5] * routerWeightsData[(k+5)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+6] * routerWeightsData[(k+6)*numExperts+expertIdx]
						dot += inputFlat[tokenBase+k+7] * routerWeightsData[(k+7)*numExperts+expertIdx]
					}
					for ; k < inputDim; k++ {
						dot += inputFlat[tokenBase+k] * routerWeightsData[k*numExperts+expertIdx]
					}
					logitsOut[outBase+expertIdx] = dot
				}
			}
		}(start, end)
	}
	wg.Wait()
}

// computeRouterGradSIMD is the pure-Go fallback for the router gradient.
func computeRouterGradSIMD(
	inputFlat []float32,
	routerWeightsData []float32,
	logitsGradFlat []float32,
	dWeightsOut []float32,
	dInputOut []float32,
	numTokens, numExperts, inputDim int,
	scaleFactor float32,
) {
	numWorkers := runtime.NumCPU()
	if numTokens < 64 {
		numWorkers = 1
	}
	tokensPerWorker := (numTokens + numWorkers - 1) / numWorkers

	var wg sync.WaitGroup
	for w := 0; w < numWorkers; w++ {
		start := w * tokensPerWorker
		end := (w + 1) * tokensPerWorker
		if start >= numTokens {
			break
		}
		if end > numTokens {
			end = numTokens
		}

		wg.Add(1)
		go func(tokenStart, tokenEnd int) {
			defer wg.Done()
			for tokenIdx := tokenStart; tokenIdx < tokenEnd; tokenIdx++ {
				tokenBase := tokenIdx * inputDim
				outBase := tokenIdx * numExperts
				for expertIdx := 0; expertIdx < numExperts; expertIdx++ {
					gradVal := logitsGradFlat[outBase+expertIdx] * scaleFactor
					if gradVal == 0 {
						continue
					}
					k := 0

					for ; k+8 <= inputDim; k += 8 {
						dWeightsOut[k*numExperts+expertIdx] += inputFlat[tokenBase+k] * gradVal
						dWeightsOut[(k+1)*numExperts+expertIdx] += inputFlat[tokenBase+k+1] * gradVal
						dWeightsOut[(k+2)*numExperts+expertIdx] += inputFlat[tokenBase+k+2] * gradVal
						dWeightsOut[(k+3)*numExperts+expertIdx] += inputFlat[tokenBase+k+3] * gradVal
						dWeightsOut[(k+4)*numExperts+expertIdx] += inputFlat[tokenBase+k+4] * gradVal
						dWeightsOut[(k+5)*numExperts+expertIdx] += inputFlat[tokenBase+k+5] * gradVal
						dWeightsOut[(k+6)*numExperts+expertIdx] += inputFlat[tokenBase+k+6] * gradVal
						dWeightsOut[(k+7)*numExperts+expertIdx] += inputFlat[tokenBase+k+7] * gradVal

						if dInputOut != nil {
							dInputOut[tokenBase+k] += routerWeightsData[k*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+1] += routerWeightsData[(k+1)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+2] += routerWeightsData[(k+2)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+3] += routerWeightsData[(k+3)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+4] += routerWeightsData[(k+4)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+5] += routerWeightsData[(k+5)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+6] += routerWeightsData[(k+6)*numExperts+expertIdx] * gradVal
							dInputOut[tokenBase+k+7] += routerWeightsData[(k+7)*numExperts+expertIdx] * gradVal
						}
					}
					for ; k < inputDim; k++ {
						dWeightsOut[k*numExperts+expertIdx] += inputFlat[tokenBase+k] * gradVal
						if dInputOut != nil {
							dInputOut[tokenBase+k] += routerWeightsData[k*numExperts+expertIdx] * gradVal
						}
					}
				}
			}
		}(start, end)
	}
	wg.Wait()
}

// updateWeightsSIMD fallback
func updateWeightsSIMD(weights, gradients, inputs []float32, delta float32) {
	n := len(inputs)
	if len(gradients) < n {
		n = len(gradients)
	}
	i := 0

	for ; i+8 <= n; i += 8 {
		gradients[i] += inputs[i] * delta
		gradients[i+1] += inputs[i+1] * delta
		gradients[i+2] += inputs[i+2] * delta
		gradients[i+3] += inputs[i+3] * delta
		gradients[i+4] += inputs[i+4] * delta
		gradients[i+5] += inputs[i+5] * delta
		gradients[i+6] += inputs[i+6] * delta
		gradients[i+7] += inputs[i+7] * delta
	}
	for ; i < n; i++ {
		gradients[i] += inputs[i] * delta
	}
}

