// GetTemplate retrieves a template by name
func (tr *TemplateRegistry) GetTemplate(name string) (*CodeTemplate, bool) {
	template, exists := tr.templates[name]
	return template, exists
}

// RenderTemplate renders a template with given parameters
func (tr *TemplateRegistry) RenderTemplate(templateName string, params map[string]any) (map[string]string, error) {
	template, exists := tr.GetTemplate(templateName)
	if !exists {
		return nil, fmt.Errorf("template not found: %s", templateName)
	}

	if params["ProjectName"] == nil {
		params["ProjectName"] = "myproject"
	}
	if params["GoVersion"] == nil {
		params["GoVersion"] = "1.21"
	}

	rendered := make(map[string]string)
	for filename, content := range template.Files {
		rendered[filename] = renderString(content, params)
	}

	return rendered, nil
}

// renderString performs simple string replacement for template variables
func renderString(template string, params map[string]any) string {
	result := template
	for key, value := range params {
		placeholder := fmt.Sprintf("{{.%s}}", key)
		result = strings.ReplaceAll(result, placeholder, fmt.Sprintf("%v", value))
	}
	return result
}

// InferTemplate infers which template to use based on goal description
func (tr *TemplateRegistry) InferTemplate(description string) string {
	lower := strings.ToLower(description)

	if strings.Contains(lower, "landing page") || strings.Contains(lower, "landing") {
		return "landing_page"
	}
	if strings.Contains(lower, "html") || strings.Contains(lower, "website") || strings.Contains(lower, "web page") {
		return "html"
	}

	if strings.Contains(lower, "rest") || strings.Contains(lower, "api") {
		return "rest_api"
	}
	if strings.Contains(lower, "webserver") || strings.Contains(lower, "web server") || strings.Contains(lower, "http server") {
		return "webserver"
	}
	if strings.Contains(lower, "handler") {
		return "handlers"
	}

	return "go_project"
}

type Observation struct {
	ToolName	string
	ToolResult	ToolResult
	Timestamp	time.Time
	SubtaskID	string
}

// NewFeedbackLoop creates a new feedback loop
func NewFeedbackLoop(maxIterations int) *FeedbackLoop {
	if maxIterations <= 0 {
		maxIterations = 10
	}

	return &FeedbackLoop{
		maxIterations:		maxIterations,
		currentIteration:	0,
		policy:			NewDefaultPolicy(),
		observations:		make([]Observation, 0),
		toolUsage:		make(map[string]int),
	}
}

// Evaluate analyzes a tool execution result and decides next action
func (fl *FeedbackLoop) Evaluate(obs Observation, plan *Plan) (FeedbackDecision, error) {
	fl.currentIteration++
	fl.observations = append(fl.observations, obs)
	if fl.toolUsage == nil {
		fl.toolUsage = make(map[string]int)
	}
	fl.toolUsage[obs.ToolName]++

	decision := FeedbackDecision{
		ShouldContinue:	true,
		ShouldRetry:	false,
		ShouldReplan:	false,
	}

	if fl.currentIteration >= fl.maxIterations {
		decision.ShouldContinue = false
		decision.ErrorMessage = fmt.Sprintf("max iterations (%d) reached", fl.maxIterations)
		decision.Critique = "Agent may be stuck in a loop. Consider breaking down the goal differently."
		fl.LogToolUsage()
		return decision, nil
	}

	if !obs.ToolResult.Success {
		decision.Critique = fl.generateCritique(obs, plan)

		if fl.shouldRetry(obs) {
			decision.ShouldRetry = true
			decision.ShouldContinue = false
		} else {
			decision.ShouldReplan = true
			decision.ShouldContinue = false
		}

		decision.ErrorMessage = fmt.Sprintf("Tool '%s' failed: %v", obs.ToolName, obs.ToolResult.Error)
		return decision, nil
	}

	if plan.IsComplete() {
		decision.ShouldContinue = false
		decision.Critique = "All subtasks completed successfully. Goal achieved!"
		return decision, nil
	}

	decision.Critique = fmt.Sprintf("Tool '%s' succeeded. Proceeding to next subtask.", obs.ToolName)
	return decision, nil
}

// Reset clears the iteration counter and observations
func (fl *FeedbackLoop) Reset() {
	fl.currentIteration = 0
	fl.observations = make([]Observation, 0)
	fl.toolUsage = make(map[string]int)
}

// generateCritique creates a self-assessment of what went wrong
func (fl *FeedbackLoop) generateCritique(obs Observation, plan *Plan) string {
	var critique strings.Builder

	critique.WriteString(fmt.Sprintf("Tool '%s' failed. ", obs.ToolName))

	if obs.ToolResult.Error != nil {
		critique.WriteString(fmt.Sprintf("Error: %v. ", obs.ToolResult.Error))
	}

	errorMsg := ""
	if obs.ToolResult.Error != nil {
		errorMsg = obs.ToolResult.Error.Error()
	}

	if strings.Contains(errorMsg, "not found") {
		critique.WriteString("The target resource doesn't exist. ")
		critique.WriteString("Consider creating required dependencies first. ")
	} else if strings.Contains(errorMsg, "already exists") {
		critique.WriteString("Resource already exists. ")
		critique.WriteString("Consider skipping this step or using a different name. ")
	} else if strings.Contains(errorMsg, "permission") {
		critique.WriteString("Permission denied. ")
		critique.WriteString("Verify access rights or policy constraints. ")
	} else {
		critique.WriteString("Unexpected error. ")
	}

	return critique.String()
}

// shouldRetry determines if a failed subtask should be retried
func (fl *FeedbackLoop) shouldRetry(obs Observation) bool {

	if obs.ToolResult.Error == nil {
		return false
	}

	errorMsg := obs.ToolResult.Error.Error()

	permanentErrors := []string{
		"not found",
		"already exists",
		"invalid",
		"forbidden",
	}

	for _, perm := range permanentErrors {
		if strings.Contains(strings.ToLower(errorMsg), perm) {
			return false
		}
	}

	return true
}

// GetObservations returns all recorded observations
func (fl *FeedbackLoop) GetObservations() []Observation {
	return fl.observations
}

// LogToolUsage prints the distribution of tool usage to help diagnose expert balance
func (fl *FeedbackLoop) LogToolUsage() {
	fmt.Println("Tool Usage (Expert Balance):")
	for tool, count := range fl.toolUsage {
		fmt.Printf("  %s: %d\n", tool, count)
	}
}

// NewDefaultPolicy creates a default policy validator
func NewDefaultPolicy() *DefaultPolicy {
	return &DefaultPolicy{}
}

// ValidatePath ensures paths don't escape project boundaries
func (dp *DefaultPolicy) ValidatePath(path string) error {

	if strings.Contains(path, "..") {
		return fmt.Errorf("path contains directory traversal: %s", path)
	}

	if strings.HasPrefix(path, "/etc") ||
		strings.HasPrefix(path, "/sys") ||
		strings.HasPrefix(path, "/proc") ||
		strings.HasPrefix(path, "/dev") {
		return fmt.Errorf("path accesses system directories: %s", path)
	}

	return nil
}

// ValidateOperation checks if an operation is allowed
func (dp *DefaultPolicy) ValidateOperation(operation string) error {

	dangerous := []string{
		"rm -rf /",
		"format",
		"mkfs",
	}

	lower := strings.ToLower(operation)
	for _, danger := range dangerous {
		if strings.Contains(lower, danger) {
			return fmt.Errorf("operation blocked by policy: %s", operation)
		}
	}

	return nil
}

// IsComplete checks if the goal is completed
func (g *Goal) IsComplete() bool {
	return g.Status == GoalCompleted
}

// IsBlocked checks if the goal is blocked
func (g *Goal) IsBlocked() bool {
	return g.Status == GoalBlocked
}

// UpdateProgress recalculates goal progress based on milestone completion
func (g *Goal) UpdateProgress() {
	if len(g.Milestones) == 0 {
		g.Progress = 0.0
		return
	}

	totalProgress := 0.0
	for _, milestone := range g.Milestones {
		totalProgress += milestone.Progress
	}

	g.Progress = totalProgress / float64(len(g.Milestones))
	g.UpdatedAt = time.Now()

	if g.Progress >= 1.0 {
		g.Status = GoalCompleted
		now := time.Now()
		g.CompletedAt = &now
	} else if g.Progress > 0.0 {
		g.Status = GoalInProgress
	}
}

// IsReady checks if all dependencies for this milestone are satisfied
func (m *Milestone) IsReady(goal *Goal) bool {
	if m.Status != MilestoneNotStarted {
		return false
	}

	for _, depID := range m.Dependencies {
		for _, milestone := range goal.Milestones {
			if milestone.ID == depID && milestone.Status != MilestoneCompleted {
				return false
			}
		}
	}

	return true
}

// UpdateProgress recalculates milestone progress based on task completion
func (m *Milestone) UpdateProgress() {
	if len(m.Tasks) == 0 {
		m.Progress = 0.0
		return
	}

	completed := 0
	for _, task := range m.Tasks {
		if task.Status == StatusCompleted {
			completed++
		}
	}

	m.Progress = float64(completed) / float64(len(m.Tasks))
	m.UpdatedAt = time.Now()

	if m.Progress >= 1.0 {
		m.Status = MilestoneCompleted
		now := time.Now()
		m.CompletedAt = &now
	} else if m.Progress > 0.0 {
		m.Status = MilestoneInProgress
	}
}

// GetNextTask returns the next ready-to-execute task in this milestone
func (m *Milestone) GetNextTask() *Subtask {
	for _, task := range m.Tasks {
		if task.Status == StatusPending {

			allDepsMet := true
			for _, depID := range task.DependsOn {
				for _, t := range m.Tasks {
					if t.ID == depID && t.Status != StatusCompleted {
						allDepsMet = false
						break
					}
				}
			}
			if allDepsMet {
				return task
			}
		}
	}
	return nil
}

type GoalEngine struct {
	idCounter int
}

// NewGoalEngine creates a new goal engine
func NewGoalEngine() *GoalEngine {
	return &GoalEngine{
		idCounter: 0,
	}
}

// CreateGoal creates a new goal from a description
func (ge *GoalEngine) CreateGoal(description string) *Goal {
	return &Goal{
		ID:		ge.generateGoalID(),
		Description:	description,
		Status:		GoalNotStarted,
		Progress:	0.0,
		Milestones:	make([]*Milestone, 0),
		CreatedAt:	time.Now(),
		UpdatedAt:	time.Now(),
		Metadata:	make(map[string]any),
	}
}

// DecomposeGoal breaks down a high-level goal into milestones and tasks
func (ge *GoalEngine) DecomposeGoal(goal *Goal) error {
	lower := strings.ToLower(goal.Description)

	milestones := make([]*Milestone, 0)

	templateReg := NewTemplateRegistry()
	templateName := templateReg.InferTemplate(goal.Description)

	projectName := ge.extractProjectName(goal.Description)
	if projectName == "" {
		projectName = "project"
	}

	if strings.Contains(lower, "rest") || strings.Contains(lower, "api") ||
		strings.Contains(lower, "webserver") || strings.Contains(lower, "web server") ||
		strings.Contains(lower, "http") {

		setupTasks := []*Subtask{
			{
				ID:		ge.generateTaskID(),
				Description:	fmt.Sprintf("Create project folder '%s'", projectName),
				Status:		StatusPending,
				Tool:		"create_folder",
				Args:		map[string]any{"name": projectName},
			},
			{
				ID:		ge.generateTaskID(),
				Description:	fmt.Sprintf("Generate code from '%s' template", templateName),
				Status:		StatusPending,
				Tool:		"apply_template",
				Args: map[string]any{
					"template":	templateName,
					"folder":	projectName,
				},
			},
		}
		milestones = append(milestones, ge.createMilestone(goal.ID, "Project Setup", setupTasks, nil))

		docTasks := []*Subtask{
			{
				ID:		ge.generateTaskID(),
				Description:	"Verify README exists",
				Status:		StatusPending,
				Tool:		"verify_files",
				Args: map[string]any{
					"folder":	projectName,
					"files":	[]string{"README.md", "main.go"},
				},
			},
		}
		milestones = append(milestones, ge.createMilestone(goal.ID, "Documentation", docTasks, []string{milestones[0].ID}))

	} else if strings.Contains(lower, "handler") {

		setupTasks := []*Subtask{
			{
				ID:		ge.generateTaskID(),
				Description:	"Generate handlers code",
				Status:		StatusPending,
				Tool:		"apply_template",
				Args: map[string]any{
					"template":	"handlers",
					"folder":	projectName,
				},
			},
		}
		milestones = append(milestones, ge.createMilestone(goal.ID, "Generate Handlers", setupTasks, nil))
	} else if strings.Contains(lower, "delete") || strings.Contains(lower, "remove") {

		deleteTasks := []*Subtask{
			{
				ID:		ge.generateTaskID(),
				Description:	fmt.Sprintf("Delete project folder '%s'", projectName),
				Status:		StatusPending,
				Tool:		"delete_folder",
				Args:		map[string]any{"name": projectName},
			},
		}
		milestones = append(milestones, ge.createMilestone(goal.ID, "Project Deletion", deleteTasks, nil))
	} else {

		setupTasks := []*Subtask{
			{
				ID:		ge.generateTaskID(),
				Description:	fmt.Sprintf("Create project folder '%s'", projectName),
				Status:		StatusPending,
				Tool:		"create_folder",
				Args:		map[string]any{"name": projectName},
			},
			{
				ID:		ge.generateTaskID(),
				Description:	fmt.Sprintf("Generate code from '%s' template", templateName),
				Status:		StatusPending,
				Tool:		"apply_template",
				Args: map[string]any{
					"template":	templateName,
					"folder":	projectName,
				},
			},
		}
		milestones = append(milestones, ge.createMilestone(goal.ID, "Project Setup", setupTasks, nil))
	}

	goal.Milestones = milestones
	goal.Status = GoalNotStarted
	goal.UpdatedAt = time.Now()

	return nil
}

// extractProjectName attempts to extract a project name from the goal description
func (ge *GoalEngine) extractProjectName(description string) string {
	words := strings.Fields(strings.ToLower(description))

	for i, word := range words {
		if (word == "called" || word == "named" || word == "for") && i+1 < len(words) {
			name := words[i+1]

			name = strings.Trim(name, ".,!?;:")
			if name != "a" && name != "an" && name != "the" {
				return name
			}
		}
	}

	if strings.Contains(description, "todo") {
		return "todo"
	}
	if strings.Contains(description, "blog") {
		return "blog"
	}
	if strings.Contains(description, "chat") {
		return "chat"
	}

	return "project"
}

// GetNextAction determines the next task to execute for a goal
func (ge *GoalEngine) GetNextAction(goal *Goal) *Subtask {

	for _, milestone := range goal.Milestones {
		if milestone.IsReady(goal) {

			if milestone.Status == MilestoneNotStarted {
				milestone.Status = MilestoneInProgress
			}

			task := milestone.GetNextTask()
			if task != nil {
				return task
			}
		} else if milestone.Status == MilestoneInProgress {

			task := milestone.GetNextTask()
			if task != nil {
				return task
			}
		}
	}

	return nil
}

// EvaluateProgress updates goal progress based on milestone completion
func (ge *GoalEngine) EvaluateProgress(goal *Goal) float64 {

	for _, milestone := range goal.Milestones {
		milestone.UpdateProgress()
	}

	goal.UpdateProgress()

	return goal.Progress
}

// Helper: Create milestone with tasks
func (ge *GoalEngine) createMilestone(goalID, description string, tasks []*Subtask, dependencies []string) *Milestone {
	milestone := &Milestone{
		ID:		ge.generateMilestoneID(),
		GoalID:		goalID,
		Description:	description,
		Tasks:		tasks,
		Status:		MilestoneNotStarted,
		Progress:	0.0,
		Dependencies:	dependencies,
		CreatedAt:	time.Now(),
		UpdatedAt:	time.Now(),
		Metadata:	make(map[string]any),
	}
	return milestone
}

// Infer which tool to use based on task description
func (ge *GoalEngine) inferToolFromDescription(description string) string {
	lower := strings.ToLower(description)

	if strings.Contains(lower, "create project") || strings.Contains(lower, "project structure") {
		return "create_folder"
	}
	if strings.Contains(lower, "initialize") || strings.Contains(lower, "go.mod") {
		return "execute_command"
	}
	if strings.Contains(lower, "add") || strings.Contains(lower, "install") {
		return "execute_command"
	}
	if strings.Contains(lower, "implement") || strings.Contains(lower, "create") {
		return "create_file"
	}

	return "execute_command"
}

// Infer arguments from task description
func (ge *GoalEngine) inferArgsFromDescription(description string) map[string]any {
	args := make(map[string]any)
	lower := strings.ToLower(description)

	if strings.Contains(lower, "go.mod") {
		args["command"] = "go mod init"
	} else if strings.Contains(lower, "project structure") {
		args["name"] = "project"
	}

	return args
}

func (ge *GoalEngine) generateGoalID() string {
	ge.idCounter++
	return fmt.Sprintf("goal_%d", ge.idCounter)
}

func (ge *GoalEngine) generateMilestoneID() string {
	ge.idCounter++
	return fmt.Sprintf("milestone_%d", ge.idCounter)
}

func (ge *GoalEngine) generateTaskID() string {
	ge.idCounter++
	return fmt.Sprintf("task_%d", ge.idCounter)
}

type FileBasedStore struct {
	BasePath string
}

// NewFileBasedStore creates a new file-based goal store
func NewFileBasedStore(basePath string) *FileBasedStore {

	os.MkdirAll(filepath.Join(basePath, "goals"), 0755)
	os.MkdirAll(filepath.Join(basePath, "sessions"), 0755)

	return &FileBasedStore{
		BasePath: basePath,
	}
}

// SaveGoal saves a goal to disk
func (fs *FileBasedStore) SaveGoal(goal *Goal) error {
	filename := filepath.Join(fs.BasePath, "goals", goal.ID+".json")
	data, err := json.MarshalIndent(goal, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal goal: %w", err)
	}

	err = os.WriteFile(filename, data, 0644)
	if err != nil {
		return fmt.Errorf("failed to write goal file: %w", err)
	}

	return nil
}

// LoadGoal loads a goal from disk
func (fs *FileBasedStore) LoadGoal(id string) (*Goal, error) {
	filename := filepath.Join(fs.BasePath, "goals", id+".json")
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read goal file: %w", err)
	}

	var goal Goal
	err = json.Unmarshal(data, &goal)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal goal: %w", err)
	}

	return &goal, nil
}

// ListGoals lists all goals
func (fs *FileBasedStore) ListGoals() ([]*Goal, error) {
	goalsDir := filepath.Join(fs.BasePath, "goals")
	entries, err := os.ReadDir(goalsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to read goals directory: %w", err)
	}

	goals := make([]*Goal, 0)
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}

		id := entry.Name()[:len(entry.Name())-5]
		goal, err := fs.LoadGoal(id)
		if err != nil {
			continue
		}
		goals = append(goals, goal)
	}

	return goals, nil
}

// DeleteGoal deletes a goal
func (fs *FileBasedStore) DeleteGoal(id string) error {
	filename := filepath.Join(fs.BasePath, "goals", id+".json")
	return os.Remove(filename)
}

// SaveSession saves a session to disk
func (fs *FileBasedStore) SaveSession(session *Session) error {
	filename := filepath.Join(fs.BasePath, "sessions", session.ID+".json")
	data, err := json.MarshalIndent(session, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal session: %w", err)
	}

	err = os.WriteFile(filename, data, 0644)
	if err != nil {
		return fmt.Errorf("failed to write session file: %w", err)
	}

	return nil
}

// LoadSession loads a session from disk
func (fs *FileBasedStore) LoadSession(id string) (*Session, error) {
	filename := filepath.Join(fs.BasePath, "sessions", id+".json")
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read session file: %w", err)
	}

	var session Session
	err = json.Unmarshal(data, &session)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal session: %w", err)
	}

	return &session, nil
}

// ListSessions lists all sessions
func (fs *FileBasedStore) ListSessions() ([]*Session, error) {
	sessionsDir := filepath.Join(fs.BasePath, "sessions")
	entries, err := os.ReadDir(sessionsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to read sessions directory: %w", err)
	}

	sessions := make([]*Session, 0)
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}

		id := entry.Name()[:len(entry.Name())-5]
		session, err := fs.LoadSession(id)
		if err != nil {
			continue
		}
		sessions = append(sessions, session)
	}

	return sessions, nil
