}

type LLMTool struct {
	Name		string		`json:"name"`
	Description	string		`json:"description"`
	Parameters	json.RawMessage	`json:"parameters"`
}

type ToolCall struct {
	Name		string		`json:"name"`
	Arguments	json.RawMessage	`json:"arguments"`
}

type LLMToolExecutor struct {
	WorkingDir string
}

// NewLLMToolExecutor creates a new tool executor.
func NewLLMToolExecutor(workingDir string) *LLMToolExecutor {
	return &LLMToolExecutor{
		WorkingDir: workingDir,
	}
}

// GetToolDefinitions returns the LLM function calling tool definitions.
func (e *LLMToolExecutor) GetToolDefinitions() []LLMTool {
	return []LLMTool{
		e.defineRunTests(),
		e.defineReadFile(),
		e.defineApplyPatch(),
	}
}

// defineRunTests returns the run_tests tool definition.
func (e *LLMToolExecutor) defineRunTests() LLMTool {
	return LLMTool{
		Name:		"run_tests",
		Description:	"Runs 'go test -v <package>' on the specified Go package and returns the stdout/stderr output. Use this to verify code changes or check test failures.",
		Parameters: json.RawMessage(`{
			"type": "object",
			"properties": {
				"package": {
					"type": "string",
					"description": "The Go package path to test (e.g., './cmd/tools/multi_orchestrator' or just '.')"
				},
				"run": {
					"type": "string",
					"description": "Optional: Specific test function to run (e.g., 'TestApplyPatch'). Uses -run flag."
				},
				"timeout": {
					"type": "string",
					"description": "Optional: Test timeout (e.g., '30s', '2m'). Defaults to '30s'.",
					"default": "30s"
				}
			},
			"required": ["package"]
		}`),
	}
}

// defineReadFile returns the read_file tool definition.
func (e *LLMToolExecutor) defineReadFile() LLMTool {
	return LLMTool{
		Name:		"read_file",
		Description:	"Reads the content of a specific file in the project. Use this to inspect code before making changes.",
		Parameters: json.RawMessage(`{
			"type": "object",
			"properties": {
				"path": {
					"type": "string",
					"description": "Relative path to the file from the project root (e.g., 'cmd/tools/multi_orchestrator/main.go')"
				},
				"start_line": {
					"type": "integer",
					"description": "Optional: Starting line number (1-based) to read from",
					"default": 1
				},
				"end_line": {
					"type": "integer",
					"description": "Optional: Ending line number (1-based) to read up to",
					"default": 0
				}
			},
			"required": ["path"]
		}`),
	}
}

// defineApplyPatch returns the apply_patch tool definition.
func (e *LLMToolExecutor) defineApplyPatch() LLMTool {
	return LLMTool{
		Name:		"apply_patch",
		Description:	"Applies code changes to a Go source file. Uses SEARCH/REPLACE blocks to make targeted edits. The SEARCH block must match the existing code exactly. After applying, runs gofmt to ensure formatting is correct.",
		Parameters: json.RawMessage(`{
			"type": "object",
			"properties": {
				"file": {
					"type": "string",
					"description": "Path to the file to modify (e.g., 'cmd/tools/multi_orchestrator/main.go')"
				},
				"patch": {
					"type": "string",
					"description": "The SEARCH/REPLACE patch in the format:\n<<<<<<< SEARCH\nexact code to find\n=======\nreplacement code\n>>>>>>> REPLACE"
				}
			},
			"required": ["file", "patch"]
		}`),
	}
}

// ExecuteToolCall executes a single LLM tool call and returns the result.
// Uses the existing ToolResult type from tool_registry.go (Error is error type).
func (e *LLMToolExecutor) ExecuteToolCall(call ToolCall) ToolResult {
	switch call.Name {
	case "run_tests":
		return e.executeRunTests(call.Arguments)
	case "read_file":
		return e.executeReadFile(call.Arguments)
	case "apply_patch":
		return e.executeApplyPatch(call.Arguments)
	default:
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("unknown tool: %s", call.Name),
		}
	}
}

// executeRunTests runs go test on the specified package.
func (e *LLMToolExecutor) executeRunTests(args json.RawMessage) ToolResult {
	var params struct {
		Package	string	`json:"package"`
		Run	string	`json:"run,omitempty"`
		Timeout	string	`json:"timeout,omitempty"`
	}
	if err := json.Unmarshal(args, &params); err != nil {
		return ToolResult{Success: false, Error: fmt.Errorf("invalid arguments: %v", err)}
	}

	if params.Timeout == "" {
		params.Timeout = "30s"
	}

	cmdArgs := []string{"test", "-v"}
	if params.Run != "" {
		cmdArgs = append(cmdArgs, "-run", params.Run)
	}
	cmdArgs = append(cmdArgs, "-timeout", params.Timeout, params.Package)

	cmd := exec.Command("go", cmdArgs...)
	cmd.Dir = e.WorkingDir

	output, err := cmd.CombinedOutput()
	outputStr := string(output)

	if err != nil {
		return ToolResult{
			Success:	false,
			Output:		outputStr,
			Error:		fmt.Errorf("tests failed (exit: %v)", err),
		}
	}

	return ToolResult{
		Success:	true,
		Output:		outputStr,
	}
}

// executeReadFile reads a file's contents.
func (e *LLMToolExecutor) executeReadFile(args json.RawMessage) ToolResult {
	var params struct {
		Path		string	`json:"path"`
		StartLine	int	`json:"start_line,omitempty"`
		EndLine		int	`json:"end_line,omitempty"`
	}
	if err := json.Unmarshal(args, &params); err != nil {
		return ToolResult{Success: false, Error: fmt.Errorf("invalid arguments: %v", err)}
	}

	fullPath := filepath.Join(e.WorkingDir, params.Path)
	if _, err := os.Stat(fullPath); os.IsNotExist(err) {
		return ToolResult{Success: false, Error: fmt.Errorf("file not found: %s", params.Path)}
	}

	data, err := os.ReadFile(fullPath)
	if err != nil {
		return ToolResult{Success: false, Error: fmt.Errorf("read error: %v", err)}
	}

	content := string(data)
	lines := strings.Split(content, "\n")

	if params.StartLine > 0 {
		start := params.StartLine - 1
		if start >= len(lines) {
			return ToolResult{Success: false, Error: fmt.Errorf("start line %d exceeds file length %d", params.StartLine, len(lines))}
		}
		if params.EndLine > 0 && params.EndLine <= len(lines) {
			content = strings.Join(lines[start:params.EndLine], "\n")
		} else {
			content = strings.Join(lines[start:], "\n")
		}
	}

	return ToolResult{
		Success:	true,
		Output:		content,
	}
}

// executeApplyPatch applies a SEARCH/REPLACE patch to a file.
// Delegates to the search_replace binary if available, otherwise does manual patching.
func (e *LLMToolExecutor) executeApplyPatch(args json.RawMessage) ToolResult {
	var params struct {
		File	string	`json:"file"`
		Patch	string	`json:"patch"`
	}
	if err := json.Unmarshal(args, &params); err != nil {
		return ToolResult{Success: false, Error: fmt.Errorf("invalid arguments: %v", err)}
	}

	fullPath := filepath.Join(e.WorkingDir, params.File)
	if _, err := os.Stat(fullPath); os.IsNotExist(err) {
		return ToolResult{Success: false, Error: fmt.Errorf("file not found: %s", params.File)}
	}

	original, err := os.ReadFile(fullPath)
	if err != nil {
		return ToolResult{Success: false, Error: fmt.Errorf("read error: %v", err)}
	}

	searchReplaceBin, err := exec.LookPath("search_replace")
	if err == nil {
		cmd := exec.Command(searchReplaceBin,
			"-file", fullPath,
			"-patch", params.Patch,
			"-apply",
			"-gofmt=true",
			"-verify=false",
		)
		output, execErr := cmd.CombinedOutput()
		if execErr != nil {
			os.WriteFile(fullPath, original, 0644)
			return ToolResult{
				Success:	false,
				Output:		string(output),
				Error:		fmt.Errorf("apply patch failed: %v", execErr),
			}
		}
		return ToolResult{
			Success:	true,
			Output:		fmt.Sprintf("Patch applied successfully to %s\n%s", params.File, string(output)),
		}
	}

	newContent := string(original)
	patch := params.Patch

	patch = strings.ReplaceAll(patch, "\\n", "\n")

	searchMarker := "<<<<<<< SEARCH\n"
	sepMarker := "=======\n"
	replaceMarker := "\n>>>>>>> REPLACE"

	searchIdx := strings.Index(patch, searchMarker)
	if searchIdx == -1 {
		return ToolResult{Success: false, Error: fmt.Errorf("invalid patch format: missing SEARCH marker")}
	}
	searchStart := searchIdx + len(searchMarker)

	sepIdx := strings.Index(patch[searchStart:], sepMarker)
	if sepIdx == -1 {
		return ToolResult{Success: false, Error: fmt.Errorf("invalid patch format: missing separator")}
	}

	search := patch[searchStart : searchStart+sepIdx]
	replaceStart := searchStart + sepIdx + len(sepMarker)

	replaceEnd := strings.Index(patch[replaceStart:], replaceMarker)
	if replaceEnd == -1 {
		replaceEnd = strings.Index(patch[replaceStart:], ">>>>>>> REPLACE")
		if replaceEnd == -1 {
			return ToolResult{Success: false, Error: fmt.Errorf("invalid patch format: missing REPLACE marker")}
		}
	}

	replace := patch[replaceStart : replaceStart+replaceEnd]

	search = strings.ReplaceAll(search, "\\t", "\t")
	replace = strings.ReplaceAll(replace, "\\t", "\t")

	if !strings.Contains(newContent, search) {
		return ToolResult{Success: false, Error: fmt.Errorf("search text not found in file:\n%s", truncateString(search, 200))}
	}

	newContent = strings.Replace(newContent, search, replace, 1)

	if err := os.WriteFile(fullPath, []byte(newContent), 0644); err != nil {
		os.WriteFile(fullPath, original, 0644)
		return ToolResult{Success: false, Error: fmt.Errorf("write error: %v", err)}
	}

	return ToolResult{
		Success:	true,
		Output:		fmt.Sprintf("Patch applied successfully to %s", params.File),
	}
}

// RunAutoFix runs the LLM-driven auto-fix loop for a Go package.
// It runs tests, sends failures to an LLM with tool access, executes tool
// choices, and repeats until tests pass or max iterations are reached.
func RunAutoFix(pkgTarget string, workingDir string, callLLM func(prompt string, tools []LLMTool) ([]ToolCall, string, error)) error {
	maxRetries := 5
	executor := NewLLMToolExecutor(workingDir)

	fmt.Printf("🔧 Auto-fix loop for %s (max %d iterations)\n", pkgTarget, maxRetries)

	for i := 0; i < maxRetries; i++ {
		fmt.Printf("\n📋 Iteration %d/%d: Running go test %s...\n", i+1, maxRetries, pkgTarget)

		result := executor.executeRunTests(json.RawMessage(
			fmt.Sprintf(`{"package": "%s", "timeout": "60s"}`, pkgTarget),
		))

		if result.Success {
			fmt.Printf("✅ All tests passed!\n%s\n", truncateString(result.Output, 500))
			return nil
		}

		fmt.Printf("❌ Tests failed (iteration %d/%d)\n", i+1, maxRetries)

		prompt := fmt.Sprintf(
			"The command 'go test -v %s' failed with the following output:\n\n%s\n\n"+
				"Inspect the relevant files using 'read_file' and apply code fixes using 'apply_patch' to fix the failing tests.\n"+
				"The patch must use the SEARCH/REPLACE format:\n"+
				"<<<<<<< SEARCH\ncode that currently exists\n=======\nreplacement code\n>>>>>>> REPLACE\n\n"+
				"Make sure the SEARCH block matches the existing code exactly.",
			pkgTarget,
			truncateString(result.Output, 4000),
		)

		tools := executor.GetToolDefinitions()
		toolCalls, responseText, err := callLLM(prompt, tools)
		if err != nil {
			fmt.Printf("⚠️  LLM call failed: %v\n", err)
			continue
		}

		if len(toolCalls) == 0 {
			fmt.Printf("⚠️  LLM returned no tool calls. Response: %s\n", truncateString(responseText, 300))
			continue
		}

		for _, call := range toolCalls {
			fmt.Printf("  🛠️  Executing: %s(%s)\n", call.Name, truncateString(string(call.Arguments), 100))
			toolResult := executor.ExecuteToolCall(call)
			if toolResult.Success {
				fmt.Printf("  ✅ %s succeeded\n", call.Name)
				if len(toolResult.Output) > 0 {
					fmt.Printf("     Output: %s\n", truncateString(toolResult.Output, 200))
				}
			} else {
				errMsg := ""
				if toolResult.Error != nil {
					errMsg = toolResult.Error.Error()
				}
				fmt.Printf("  ❌ %s failed: %s\n", call.Name, errMsg)
				if len(toolResult.Output) > 0 {
					fmt.Printf("     Output: %s\n", truncateString(toolResult.Output, 200))
				}
			}
		}
	}

	return fmt.Errorf("failed to fix tests within %d iterations", maxRetries)
}

// truncateString truncates a string to the specified max length, adding "..." if truncated.
func truncateString(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen] + "..."
}

type Message struct {
	Role		string		`json:"role"`	// "user" or "assistant" or "system"
	Content		string		`json:"content"`
	Timestamp	time.Time	`json:"timestamp"`
	Metadata	map[string]any	`json:"metadata,omitempty"`
}

type ActionFilters struct {
	Type		string
	StartTime	time.Time
	EndTime		time.Time
	Limit		int
}

// NewInMemoryStore creates a new in-memory store
func NewInMemoryStore() *InMemoryStore {
	return &InMemoryStore{
		conversations:	make([]Message, 0),
		knowledge:	make(map[string]KnowledgeItem),
		actions:	make([]Action, 0),
		maxMessages:	100,
		persist:	false,
	}
}

// NewPersistentStore creates an in-memory store with disk persistence
func NewPersistentStore(path string) *InMemoryStore {
	store := &InMemoryStore{
		conversations:	make([]Message, 0),
		knowledge:	make(map[string]KnowledgeItem),
		actions:	make([]Action, 0),
		maxMessages:	100,
		persist:	true,
		persistPath:	path,
	}

	_ = store.Load()

	return store
}

// AppendMessage adds a message to conversation history
func (ims *InMemoryStore) AppendMessage(role string, content string) error {
	ims.mu.Lock()
	defer ims.mu.Unlock()

	message := Message{
		Role:		role,
		Content:	content,
		Timestamp:	time.Now(),
		Metadata:	make(map[string]any),
	}

	ims.conversations = append(ims.conversations, message)

	if len(ims.conversations) > ims.maxMessages {
		ims.conversations = ims.conversations[len(ims.conversations)-ims.maxMessages:]
	}

	if ims.persist {
		return ims.save()
	}

	return nil
}

// GetConversationHistory retrieves recent messages
func (ims *InMemoryStore) GetConversationHistory(limit int) ([]Message, error) {
	ims.mu.RLock()
	defer ims.mu.RUnlock()

	if limit <= 0 || limit > len(ims.conversations) {
		limit = len(ims.conversations)
	}

	start := max(len(ims.conversations)-limit, 0)

	return ims.conversations[start:], nil
}

// ClearConversation removes all conversation history
func (ims *InMemoryStore) ClearConversation() error {
	ims.mu.Lock()
	defer ims.mu.Unlock()

	ims.conversations = make([]Message, 0)

	if ims.persist {
		return ims.save()
	}

	return nil
}

// StoreKnowledge adds a knowledge item
func (ims *InMemoryStore) StoreKnowledge(key string, content string, tags []string) error {
	ims.mu.Lock()
	defer ims.mu.Unlock()

	item := KnowledgeItem{
		Key:		key,
		Content:	content,
		Tags:		tags,
		CreatedAt:	time.Now(),
		Metadata:	make(map[string]any),
	}

	ims.knowledge[key] = item

	if ims.persist {
		return ims.save()
	}

	return nil
}

// GetKnowledge retrieves a knowledge item by key
func (ims *InMemoryStore) GetKnowledge(key string) (*KnowledgeItem, error) {
	ims.mu.RLock()
	defer ims.mu.RUnlock()

	item, exists := ims.knowledge[key]
	if !exists {
		return nil, fmt.Errorf("knowledge item not found: %s", key)
	}

	return &item, nil
}

// SearchKnowledge performs simple keyword-based search
// TODO: Replace with vector similarity search for better RAG
func (ims *InMemoryStore) SearchKnowledge(query string, topK int) ([]KnowledgeItem, error) {
	ims.mu.RLock()
	defer ims.mu.RUnlock()

	results := make([]KnowledgeItem, 0)

	for _, item := range ims.knowledge {
		if containsKeyword(item.Content, query) || containsKeyword(item.Key, query) {
			results = append(results, item)
			if len(results) >= topK {
				break
			}
		}
	}

	return results, nil
}

// LogAction records an agent action
func (ims *InMemoryStore) LogAction(action Action) error {
	ims.mu.Lock()
	defer ims.mu.Unlock()

	action.Timestamp = time.Now()
	ims.actions = append(ims.actions, action)

	if ims.persist {
		return ims.save()
	}

	return nil
}

// GetActionHistory retrieves action history with filters
func (ims *InMemoryStore) GetActionHistory(filters ActionFilters) ([]Action, error) {
	ims.mu.RLock()
	defer ims.mu.RUnlock()

	results := make([]Action, 0)

	for _, action := range ims.actions {

		if filters.Type != "" && action.Type != filters.Type {
			continue
		}

		if !filters.StartTime.IsZero() && action.Timestamp.Before(filters.StartTime) {
			continue
		}

		if !filters.EndTime.IsZero() && action.Timestamp.After(filters.EndTime) {
			continue
		}

		results = append(results, action)

		if filters.Limit > 0 && len(results) >= filters.Limit {
			break
		}
	}

	return results, nil
}

// Save persists memory to disk
func (ims *InMemoryStore) Save() error {
	if !ims.persist || ims.persistPath == "" {
		return nil
	}

	ims.mu.RLock()
	defer ims.mu.RUnlock()

	return ims.save()
}

// save writes data to disk (assumes lock is held)
func (ims *InMemoryStore) save() error {

	dir := filepath.Dir(ims.persistPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}

	data := map[string]any{
		"conversations":	ims.conversations,
		"knowledge":		ims.knowledge,
		"actions":		ims.actions,
		"saved_at":		time.Now(),
	}

	jsonData, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal data: %w", err)
	}

	if err := os.WriteFile(ims.persistPath, jsonData, 0644); err != nil {
		return fmt.Errorf("failed to write file: %w", err)
	}

	return nil
}

// Load reads memory from disk
func (ims *InMemoryStore) Load() error {
	if !ims.persist || ims.persistPath == "" {
		return nil
	}

	if _, err := os.Stat(ims.persistPath); os.IsNotExist(err) {
		return nil
	}

	jsonData, err := os.ReadFile(ims.persistPath)
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}

	// Unmarshal
	var data map[string]any
	if err := json.Unmarshal(jsonData, &data); err != nil {
		return fmt.Errorf("failed to unmarshal data: %w", err)
	}

	ims.mu.Lock()
	defer ims.mu.Unlock()

	if convData, ok := data["conversations"]; ok {
		convJSON, _ := json.Marshal(convData)
		json.Unmarshal(convJSON, &ims.conversations)
	}

	if knowData, ok := data["knowledge"]; ok {
		knowJSON, _ := json.Marshal(knowData)
		json.Unmarshal(knowJSON, &ims.knowledge)
	}

	if actData, ok := data["actions"]; ok {
		actJSON, _ := json.Marshal(actData)
		json.Unmarshal(actJSON, &ims.actions)
	}

	return nil
}

// Helper function for simple keyword matching
func containsKeyword(text, query string) bool {
	return len(query) > 0 && len(text) > 0 &&
		(text == query ||
			(len(text) > len(query) &&
				(text[:len(query)] == query ||
					text[len(text)-len(query):] == query)))
}

// IsReady checks if all dependencies are satisfied
func (st *Subtask) IsReady(plan *Plan) bool {
	if st.Status != StatusPending {
		return false
	}

	for _, depID := range st.DependsOn {
		depTask := plan.GetSubtask(depID)
		if depTask == nil || depTask.Status != StatusCompleted {
			return false
		}
	}

	return true
}

// GetSubtask retrieves a subtask by ID
func (p *Plan) GetSubtask(id string) *Subtask {
	for _, task := range p.Subtasks {
		if task.ID == id {
			return task
		}
	}
	return nil
}

// GetNextSubtask returns the next ready-to-execute subtask
func (p *Plan) GetNextSubtask() *Subtask {
	for _, task := range p.Subtasks {
		if task.IsReady(p) {
			return task
		}
	}
	return nil
}

// IsComplete checks if all subtasks are completed
func (p *Plan) IsComplete() bool {
	for _, task := range p.Subtasks {
		if task.Status != StatusCompleted && task.Status != StatusSkipped {
			return false
		}
	}
	return true
}

// HasErrors checks if any subtask has failed
func (p *Plan) HasErrors() bool {
	for _, task := range p.Subtasks {
		if task.Status == StatusFailed {
			return true
		}
	}
	return false
}

// Progress returns completion percentage
func (p *Plan) Progress() float64 {
	if len(p.Subtasks) == 0 {
		return 1.0
	}

	completed := 0
	for _, task := range p.Subtasks {
		if task.Status == StatusCompleted || task.Status == StatusSkipped {
			completed++
		}
	}

	return float64(completed) / float64(len(p.Subtasks))
}

type PlanningEngine struct {
	idCounter int
}

// NewPlanningEngine creates a new planning engine
func NewPlanningEngine() *PlanningEngine {
	return &PlanningEngine{
		idCounter: 0,
	}
}

// DecomposeGoal analyzes a user request and creates a plan with subtasks
func (pe *PlanningEngine) DecomposeGoal(userRequest string) (*Plan, error) {
	plan := &Plan{
		ID:		pe.generatePlanID(),
		Goal:		userRequest,
		Subtasks:	make([]*Subtask, 0),
		CreatedAt:	time.Now(),
		UpdatedAt:	time.Now(),
		Metadata:	make(map[string]any),
	}

	subtasks, reasoning := pe.ruleBasedDecomposition(userRequest)
	plan.Subtasks = subtasks
	plan.Reasoning = reasoning

	return plan, nil
}

// ruleBasedDecomposition performs simple rule-based task breakdown
func (pe *PlanningEngine) ruleBasedDecomposition(request string) ([]*Subtask, string) {
	lower := strings.ToLower(request)
	subtasks := make([]*Subtask, 0)
	reasoning := "Decomposing request based on detected patterns:\n"

	if strings.Contains(lower, "project") || strings.Contains(lower, "app") || strings.Contains(lower, "application") {
		reasoning += "- Detected project creation request\n"

		projectType := pe.detectProjectType(lower)
		reasoning += fmt.Sprintf("- Project type: %s\n", projectType)

		subtasks = append(subtasks, &Subtask{
			ID:		pe.generateSubtaskID(),
			Description:	"Create project root folder",
			Status:		StatusPending,
			Tool:		"create_folder",
			Args: map[string]any{
				"name": pe.extractProjectName(request),
			},
			DependsOn:	[]string{},
		})

		if projectType != "generic" {
			subtasks = append(subtasks, &Subtask{
				ID:		pe.generateSubtaskID(),
				Description:	fmt.Sprintf("Apply %s template", projectType),
				Status:		StatusPending,
				Tool:		"apply_template",
				Args: map[string]any{
					"template":	projectType,
					"folder":	pe.extractProjectName(request),
				},
				DependsOn:	[]string{subtasks[0].ID},
			})
		}

		if strings.Contains(lower, "auth") {
			subtasks = append(subtasks, &Subtask{
				ID:		pe.generateSubtaskID(),
				Description:	"Add authentication module",
				Status:		StatusPending,
				Tool:		"add_feature",
				Args: map[string]any{
					"feature":	"auth",
					"folder":	pe.extractProjectName(request),
				},
				DependsOn:	[]string{subtasks[len(subtasks)-1].ID},
			})
		}

		if strings.Contains(lower, "database") || strings.Contains(lower, "db") {
			subtasks = append(subtasks, &Subtask{
				ID:		pe.generateSubtaskID(),
				Description:	"Add database integration",
				Status:		StatusPending,
				Tool:		"add_feature",
				Args: map[string]any{
					"feature":	"database",
					"folder":	pe.extractProjectName(request),
				},
				DependsOn:	[]string{subtasks[len(subtasks)-1].ID},
			})
		}
	} else if strings.Contains(lower, "folder") && (strings.Contains(lower, "file") || pe.extractFileName(request) != "") {

		reasoning += "- Detected folder and file creation\n"

		folderName := pe.extractFolderName(request)
		fileName := pe.extractFileName(request)

		subtasks = append(subtasks, &Subtask{
			ID:		pe.generateSubtaskID(),
			Description:	fmt.Sprintf("Create folder '%s'", folderName),
			Status:		StatusPending,
			Tool:		"create_folder",
			Args: map[string]any{
				"name": folderName,
			},
			DependsOn:	[]string{},
		})

		if fileName != "" {
			subtasks = append(subtasks, &Subtask{
				ID:		pe.generateSubtaskID(),
				Description:	fmt.Sprintf("Create file '%s' in '%s'", fileName, folderName),
				Status:		StatusPending,
				Tool:		"create_file",
				Args: map[string]any{
					"name":		fileName,
					"folder":	folderName,
				},
				DependsOn:	[]string{subtasks[0].ID},
			})
		}
	} else {

		reasoning += "- Simple single-step request\n"
		subtasks = append(subtasks, &Subtask{
			ID:		pe.generateSubtaskID(),
			Description:	request,
			Status:		StatusPending,
			Tool:		"execute_command",
			Args: map[string]any{
				"command": request,
			},
			DependsOn:	[]string{},
		})
	}

	return subtasks, reasoning
}

// Helper functions for pattern extraction
func (pe *PlanningEngine) detectProjectType(request string) string {
	patterns := map[string][]string{
		"webserver":	{"webserver", "web server", "http server", "api server"},
		"rest-api":	{"rest api", "rest", "restful"},
		"cli":		{"cli", "command line", "command-line"},
		"microservice":	{"microservice", "micro service"},
	}

	for projectType, keywords := range patterns {
		for _, keyword := range keywords {
			if strings.Contains(request, keyword) {
				return projectType
			}
		}
	}

	return "generic"
}

func (pe *PlanningEngine) extractProjectName(request string) string {
	words := strings.Fields(request)
	for i, word := range words {
		if (word == "project" || word == "app" || word == "application") && i+1 < len(words) {
			return words[i+1]
		}
	}
	return "myproject"
}

func (pe *PlanningEngine) extractFolderName(request string) string {
	words := strings.Fields(request)
	for i, word := range words {
		if (word == "folder" || word == "directory") && i+1 < len(words) {
			return words[i+1]
		}
	}
	return "newfolder"
}

func (pe *PlanningEngine) extractFileName(request string) string {
	words := strings.FieldsSeq(request)
	for word := range words {
		if strings.Contains(word, ".") {
			return word
		}
	}
	return ""
}

func (pe *PlanningEngine) generatePlanID() string {
	pe.idCounter++
	return fmt.Sprintf("plan_%d", pe.idCounter)
}

func (pe *PlanningEngine) generateSubtaskID() string {
	pe.idCounter++
	return fmt.Sprintf("task_%d", pe.idCounter)
}

// UpdatePlan adjusts the plan based on feedback
func (pe *PlanningEngine) UpdatePlan(plan *Plan, feedback string) error {
	plan.UpdatedAt = time.Now()

	if strings.Contains(strings.ToLower(feedback), "error") ||
		strings.Contains(strings.ToLower(feedback), "fail") {
		for _, task := range plan.Subtasks {
			if task.Status == StatusFailed {

				for _, depTask := range plan.Subtasks {
					for _, depID := range depTask.DependsOn {
						if depID == task.ID {
							depTask.Status = StatusPending
						}
					}
				}
			}
		}
	}

	return nil
}

// String returns a human-readable representation of the plan
func (p *Plan) String() string {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Plan: %s\n", p.Goal))
	sb.WriteString(fmt.Sprintf("  Progress: %.0f%%\n", p.Progress()*100))
	sb.WriteString("  Subtasks:\n")

	for i, task := range p.Subtasks {
		status := "⬜"
		switch task.Status {
		case StatusCompleted:
			status = "✅"
		case StatusRunning:
			status = "🔄"
		case StatusFailed:
			status = "❌"
		case StatusSkipped:
			status = "⏭️"
		}

		sb.WriteString(fmt.Sprintf("    %d. %s %s\n", i+1, status, task.Description))
	}

	return sb.String()
}

type RealFilesystemTool struct {
	vfs		*semantic.VFSTree
	roleReg		*semantic.RoleRegistry
	templateReg	*TemplateRegistry
	baseDir		string	// Base directory for project files
}

// NewRealFilesystemTool creates a new real filesystem tool
func NewRealFilesystemTool(vfs *semantic.VFSTree, roleReg *semantic.RoleRegistry, baseDir string) *RealFilesystemTool {
	return &RealFilesystemTool{
		vfs:		vfs,
		roleReg:	roleReg,
		templateReg:	NewTemplateRegistry(),
		baseDir:	baseDir,
	}
}

func (rft *RealFilesystemTool) Name() string {
	return "write_files"
}

func (rft *RealFilesystemTool) Description() string {
	return "Writes files from VFS to the actual filesystem"
}

func (rft *RealFilesystemTool) Schema() ToolSchema {
	return ToolSchema{
		Parameters: map[string]ParameterDef{
			"folder": {
				Type:		"string",
				Description:	"Target folder to write to filesystem",
			},
		},
		Required:	[]string{"folder"},
	}
}

func (rft *RealFilesystemTool) Execute(args map[string]any) (ToolResult, error) {
	folder, ok := args["folder"].(string)
	if !ok || folder == "" {
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("folder is required"),
		}, nil
	}

	path := "/" + folder
	node, found := rft.vfs.ResolvePath(path)
	if !found {
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("folder not found in VFS: %s", folder),
		}, nil
	}

	targetDir := filepath.Join(rft.baseDir, folder)
	if err := os.MkdirAll(targetDir, 0755); err != nil {
		return ToolResult{
			Success:	false,
			Error:		err,
		}, nil
	}

	filesWritten := 0
	for _, child := range node.Children {
		if child.Type == "file" {
			filePath := filepath.Join(targetDir, child.Name)
			if err := os.WriteFile(filePath, []byte(child.Content), 0644); err != nil {
				return ToolResult{
					Success:	false,
					Error:		fmt.Errorf("failed to write %s: %w", child.Name, err),
				}, nil
			}
			filesWritten++
		}
	}

	return ToolResult{
		Success:	true,
		Output:		fmt.Sprintf("Wrote %d files to %s", filesWritten, targetDir),
		Metadata: map[string]any{
			"files_written":	filesWritten,
			"target_dir":		targetDir,
		},
	}, nil
}

type RealApplyTemplateTool struct {
	vfs		*semantic.VFSTree
	roleReg		*semantic.RoleRegistry
	templateReg	*TemplateRegistry
	baseDir		string
}

// NewRealApplyTemplateTool creates a new real template application tool
func NewRealApplyTemplateTool(vfs *semantic.VFSTree, roleReg *semantic.RoleRegistry, baseDir string) *RealApplyTemplateTool {
	return &RealApplyTemplateTool{
		vfs:		vfs,
		roleReg:	roleReg,
		templateReg:	NewTemplateRegistry(),
		baseDir:	baseDir,
	}
}

func (rat *RealApplyTemplateTool) Name() string {
	return "apply_template"
}

func (rat *RealApplyTemplateTool) Description() string {
	return "Generates code from template and writes to filesystem"
}

func (rat *RealApplyTemplateTool) Schema() ToolSchema {
	return ToolSchema{
		Parameters: map[string]ParameterDef{
			"template": {
				Type:		"string",
				Description:	"Template name (e.g., 'webserver', 'rest_api')",
			},
			"folder": {
				Type:		"string",
				Description:	"Target folder",
			},
		},
		Required:	[]string{"template", "folder"},
	}
}

func (rat *RealApplyTemplateTool) Execute(args map[string]any) (ToolResult, error) {
	template, ok := args["template"].(string)
	if !ok || template == "" {
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("template name is required"),
		}, nil
	}

	folder, ok := args["folder"].(string)
	if !ok || folder == "" {
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("folder is required"),
		}, nil
	}

	params := map[string]any{
		"ProjectName":	folder,
		"GoVersion":	"1.21",
	}

	files, err := rat.templateReg.RenderTemplate(template, params)
	if err != nil {

		available := []string{}
		for name := range rat.templateReg.templates {
			available = append(available, name)
		}
		return ToolResult{
			Success:	false,
			Error:		fmt.Errorf("%w. Available templates: %v", err, available),
		}, nil
	}

	targetDir := filepath.Join(rat.baseDir, folder)
	if err := os.MkdirAll(targetDir, 0755); err != nil {
		return ToolResult{
			Success:	false,
			Error:		err,
		}, nil
	}

	filesWritten := 0
	var fileList []string
	for filename, content := range files {
		filePath := filepath.Join(targetDir, filename)
		if err := os.WriteFile(filePath, []byte(content), 0644); err != nil {
			return ToolResult{
				Success:	false,
				Error:		fmt.Errorf("failed to write %s: %w", filename, err),
			}, nil
		}
		filesWritten++
		fileList = append(fileList, filename)

		vfsPath := "/" + folder + "/" + filename
		role := rat.roleReg.InferRole(filename, "file", content)
		rat.vfs.CreateFile(vfsPath, role, content)
	}

	return ToolResult{
		Success:	true,
		Output:		fmt.Sprintf("Applied template '%s' to %s: created %s", template, targetDir, strings.Join(fileList, ", ")),
		Metadata: map[string]any{
			"files_created":	filesWritten,
			"template":		template,
			"target_dir":		targetDir,
		},
	}, nil
}

