type ToolRegistry struct {
	tools map[string]Tool
}

// NewToolRegistry creates a new tool registry
func NewToolRegistry() *ToolRegistry {
	return &ToolRegistry{
		tools: make(map[string]Tool),
	}
}

// RegisterTool adds a tool to the registry
func (tr *ToolRegistry) RegisterTool(tool Tool) error {
	if tool == nil {
		return fmt.Errorf("cannot register nil tool")
	}

	name := tool.Name()
	if name == "" {
		return fmt.Errorf("tool name cannot be empty")
	}

	if _, exists := tr.tools[name]; exists {
		return fmt.Errorf("tool already registered: %s", name)
	}

	tr.tools[name] = tool
	return nil
}

// GetTool retrieves a tool by name
func (tr *ToolRegistry) GetTool(name string) (Tool, error) {
	tool, exists := tr.tools[name]
	if !exists {
		return nil, fmt.Errorf("tool not found: %s", name)
	}
	return tool, nil
}

// ListTools returns all registered tool names
func (tr *ToolRegistry) ListTools() []string {
	names := make([]string, 0, len(tr.tools))
	for name := range tr.tools {
		names = append(names, name)
	}
	return names
}

// HasTool checks if a tool is registered
func (tr *ToolRegistry) HasTool(name string) bool {
	_, exists := tr.tools[name]
	return exists
}

// Execute runs a tool by name with given arguments
func (tr *ToolRegistry) Execute(toolName string, args map[string]any) (ToolResult, error) {
	tool, err := tr.GetTool(toolName)
	if err != nil {
		return ToolResult{
			Success:	false,
			Error:		err,
		}, err
	}

	return tool.Execute(args)
}

