func (mha *MultiHeadCrossAttention) Backward(grad *Tensor) error {
	if grad == nil || grad.Data == nil {
		return nil
	}

	if mha.attentionOutput == nil {
		return errors.New("mha.attentionOutput is nil in backward pass")
	}
	if mha.attentionOutput.Grad == nil {
		mha.attentionOutput.Grad = NewTensor(grad.Shape, make([]float32, len(grad.Data)), false)
	}
	if len(mha.attentionOutput.Grad.Data) != len(grad.Data) {
		return fmt.Errorf("MHCA backward: gradient data length mismatch: expected %d, got %d", len(mha.attentionOutput.Grad.Data), len(grad.Data))
	}
	safeAccumulate(mha.attentionOutput.Grad.Data, grad.Data)

	if mha.OutputLinear != nil {
		err := mha.OutputLinear.Backward(mha.attentionOutput.Grad)
		if err != nil {
			return err
		}
	}

	batchSize := mha.attentionOutput.Grad.Shape[0]
	querySeqLen := mha.attentionOutput.Grad.Shape[1]
	dimModel := mha.attentionOutput.Grad.Shape[2]
	numQHeads := mha.NumQHeads
	depth := mha.Depth

	weightsT, wtErr := mha.OutputLinear.Weights.Transpose(0, 1)
	if wtErr != nil {
		return fmt.Errorf("MHCA backward: transpose output weights failed: %w", wtErr)
	}
	batchSeq := batchSize * querySeqLen
	gradFlat := NewTensor([]int{batchSeq, dimModel}, mha.attentionOutput.Grad.Data, false)
	gradContextFlat, matErr := gradFlat.MatMul(weightsT)
	if matErr != nil {
		return fmt.Errorf("MHCA backward: grad @ OutputWeights^T failed: %w", matErr)
	}
	gradContext3D := NewTensor([]int{batchSize, querySeqLen, dimModel}, gradContextFlat.Data, false)
	gradReshaped, reshErr := gradContext3D.Reshape([]int{batchSize, querySeqLen, numQHeads, depth})
	if reshErr != nil {
		return fmt.Errorf("MHCA backward: reshape grad failed: %w", reshErr)
	}
	gradBeforeConcat, transpErr := gradReshaped.Transpose(1, 2)
	if transpErr != nil {
		return fmt.Errorf("MHCA backward: transpose grad failed: %w", transpErr)
	}

	vTransposed, _ := mha.v.Transpose(2, 3)
	gradAttentionWeights, _ := gradBeforeConcat.MatMul(vTransposed)
	if len(gradAttentionWeights.Data) != len(mha.attentionWeights.Data) {
		return fmt.Errorf("MHCA backward: gradAttentionWeights size mismatch: %d vs %d", len(gradAttentionWeights.Data), len(mha.attentionWeights.Data))
	}

	if mha.attentionWeights.Grad == nil {
		mha.attentionWeights.Grad = NewTensor(mha.attentionWeights.Shape, make([]float32, len(mha.attentionWeights.Data)), false)
	}
	safeAccumulate(mha.attentionWeights.Grad.Data, gradAttentionWeights.Data)

	if mha.AttentionWeightsReward != nil && len(mha.AttentionWeightsReward.Data) == len(mha.attentionWeights.Grad.Data) {
		safeAccumulate(mha.attentionWeights.Grad.Data, mha.AttentionWeightsReward.Data)
	}

	attentionWeightsTransposed, _ := mha.attentionWeights.Transpose(2, 3)
	gradV_per_head, _ := attentionWeightsTransposed.MatMul(gradBeforeConcat)

	if mha.v.Grad == nil {
		mha.v.Grad = NewTensor(mha.v.Shape, make([]float32, len(mha.v.Data)), false)
	}
	safeAccumulate(mha.v.Grad.Data, gradV_per_head.Data)

	// 3. Backprop through Softmax: dL/dS[i] = P[i]*(dL/dP[i] - dot(dL/dP, P))
	// Uses SIMD-accelerated SoftmaxBackwardRow.
	var gradAttentionScoresMHCA *Tensor
	{
		attScoresShape := mha.attentionWeights.Shape
		b0 := attScoresShape[0]
		h0 := attScoresShape[1]
		s0 := attScoresShape[2]
		s1 := attScoresShape[3]
		gradScoresData := make([]float32, len(mha.attentionWeights.Data))
		for b := range b0 {
			for h := range h0 {
				for i := range s0 {
					base := (b*h0*s0 + h*s0 + i) * s1
					p := mha.attentionWeights.Data[base : base+s1]
					dp := mha.attentionWeights.Grad.Data[base : base+s1]
					out := gradScoresData[base : base+s1]
					SoftmaxBackwardRow(p, dp, out)
				}
			}
		}
		gradAttentionScoresMHCA = NewTensor(attScoresShape, gradScoresData, false)
	}

	scale := float32(1.0 / math.Sqrt(float64(mha.Depth)))
	scaledGradScoresData := make([]float32, len(gradAttentionScoresMHCA.Data))
	MulScalar(gradAttentionScoresMHCA.Data, scale, scaledGradScoresData)
	gradAttentionScoresMHCA = NewTensor(gradAttentionScoresMHCA.Shape, scaledGradScoresData, false)

	kForMatMul := mha.k

	if (len(gradAttentionScoresMHCA.Shape) == 3 || len(gradAttentionScoresMHCA.Shape) == 4) && len(mha.k.Shape) == 2 {
		b := gradAttentionScoresMHCA.Shape[0]
		var kvSeq int
		if len(gradAttentionScoresMHCA.Shape) == 3 {
			kvSeq = gradAttentionScoresMHCA.Shape[2]
		} else {
			kvSeq = gradAttentionScoresMHCA.Shape[3]
		}
		dim := mha.k.Shape[1]

		if kvSeq > 1 {

			newData := make([]float32, b*kvSeq*dim)
			for i := 0; i < b; i++ {
				srcStart := i * dim
				if srcStart+dim > len(mha.k.Data) {
					continue
				}
				src := mha.k.Data[srcStart : srcStart+dim]
				for s := 0; s < kvSeq; s++ {
					dstStart := (i*kvSeq + s) * dim
					copy(newData[dstStart:dstStart+dim], src)
				}
			}

			if len(gradAttentionScoresMHCA.Shape) == 4 {

				h := gradAttentionScoresMHCA.Shape[1]
				fullData := make([]float32, b*h*kvSeq*dim)
				chunkSize := kvSeq * dim
				for i := 0; i < b; i++ {
					srcChunk := newData[i*chunkSize : (i+1)*chunkSize]
					for j := 0; j < h; j++ {
						dstStart := (i*h + j) * chunkSize
						copy(fullData[dstStart:dstStart+chunkSize], srcChunk)
					}
				}
				kForMatMul = NewTensor([]int{b, h, kvSeq, dim}, fullData, mha.k.RequiresGrad)
			} else {
				kForMatMul = NewTensor([]int{b, kvSeq, dim}, newData, mha.k.RequiresGrad)
			}
		}
	}

	gradQ_per_head, err := gradAttentionScoresMHCA.MatMul(kForMatMul)
	if err != nil {
		return fmt.Errorf("MHCA backward: gradQ MatMul failed: %w", err)
	}

	if mha.q.Grad == nil {
		mha.q.Grad = NewTensor(mha.q.Shape, make([]float32, len(mha.q.Data)), false)
	}
	safeAccumulate(mha.q.Grad.Data, gradQ_per_head.Data)

	gradScoresMHCATransposed, _ := gradAttentionScoresMHCA.Transpose(2, 3)

	qForMatMul := mha.q

	if (len(gradScoresMHCATransposed.Shape) == 3 || len(gradScoresMHCATransposed.Shape) == 4) && len(mha.q.Shape) == 2 {
		b := gradScoresMHCATransposed.Shape[0]
		var qSeq int
		if len(gradScoresMHCATransposed.Shape) == 3 {
			qSeq = gradScoresMHCATransposed.Shape[2]
		} else {
			qSeq = gradScoresMHCATransposed.Shape[3]
		}
		dim := mha.q.Shape[1]

		if qSeq > 1 {
			newData := make([]float32, b*qSeq*dim)
			for i := 0; i < b; i++ {
				srcStart := i * dim
				if srcStart+dim > len(mha.q.Data) {
					continue
				}
				src := mha.q.Data[srcStart : srcStart+dim]
				for s := 0; s < qSeq; s++ {
					dstStart := (i*qSeq + s) * dim
					copy(newData[dstStart:dstStart+dim], src)
				}
			}

			if len(gradScoresMHCATransposed.Shape) == 4 {

				h := gradScoresMHCATransposed.Shape[1]
				fullData := make([]float32, b*h*qSeq*dim)
				chunkSize := qSeq * dim
				for i := 0; i < b; i++ {
					srcChunk := newData[i*chunkSize : (i+1)*chunkSize]
					for j := 0; j < h; j++ {
						dstStart := (i*h + j) * chunkSize
						copy(fullData[dstStart:dstStart+chunkSize], srcChunk)
					}
				}
				qForMatMul = NewTensor([]int{b, h, qSeq, dim}, fullData, mha.q.RequiresGrad)
			} else {
				qForMatMul = NewTensor([]int{b, qSeq, dim}, newData, mha.q.RequiresGrad)
			}
		}
	}
	gradK_per_head, err := gradScoresMHCATransposed.MatMul(qForMatMul)
	if err != nil {
		return fmt.Errorf("MHCA backward: gradK MatMul failed: %w", err)
	}

	if mha.k.Grad == nil {
		mha.k.Grad = NewTensor(mha.k.Shape, make([]float32, len(mha.k.Data)), false)
	}
	safeAccumulate(mha.k.Grad.Data, gradK_per_head.Data)

	qGradTransposed, _ := mha.q.Grad.Transpose(1, 2)
	gradQCombined, _ := qGradTransposed.Reshape([]int{batchSize, querySeqLen, dimModel})
	if err = mha.QueryLinear.Backward(gradQCombined); err != nil {
		return err
	}

	if mha.queryTensor != nil {
		if mha.queryTensor.Grad == nil {
			mha.queryTensor.Grad = NewTensor(mha.queryTensor.Shape, make([]float32, len(mha.queryTensor.Data)), false)
		}
		if mha.QueryLinear.Input() != nil && mha.QueryLinear.Input().Grad != nil {
			qlg := mha.QueryLinear.Input().Grad
			if len(qlg.Data) == len(mha.queryTensor.Grad.Data) {
				safeAccumulate(mha.queryTensor.Grad.Data, qlg.Data)
			}
		}
	}

	kvSeqLen := mha.k.Shape[2]
	kGradTransposed, _ := mha.k.Grad.Transpose(1, 2)
	gradKCombined, _ := kGradTransposed.Reshape([]int{batchSize, kvSeqLen, dimModel})
	if err = mha.KeyLinear.Backward(gradKCombined); err != nil {
		return err
	}

	if mha.keyTensor != nil {
		if mha.keyTensor.Grad == nil {
			mha.keyTensor.Grad = NewTensor(mha.keyTensor.Shape, make([]float32, len(mha.keyTensor.Data)), false)
		}
		if mha.KeyLinear.Input() != nil && mha.KeyLinear.Input().Grad != nil {
			klg := mha.KeyLinear.Input().Grad
			if len(klg.Data) == len(mha.keyTensor.Grad.Data) {
				safeAccumulate(mha.keyTensor.Grad.Data, klg.Data)
			}
		}
	}

	vkvSeqLen := mha.v.Shape[2]
	vGradTransposed, _ := mha.v.Grad.Transpose(1, 2)
	gradVCombined, _ := vGradTransposed.Reshape([]int{batchSize, vkvSeqLen, dimModel})
	if err = mha.ValueLinear.Backward(gradVCombined); err != nil {
		return err
	}

	if mha.valueTensor != nil {
		if mha.valueTensor.Grad == nil {
			mha.valueTensor.Grad = NewTensor(mha.valueTensor.Shape, make([]float32, len(mha.valueTensor.Data)), false)
		}
		if mha.ValueLinear.Input() != nil && mha.ValueLinear.Input().Grad != nil {
			vlg := mha.ValueLinear.Input().Grad
			if len(vlg.Data) == len(mha.valueTensor.Grad.Data) {
				safeAccumulate(mha.valueTensor.Grad.Data, vlg.Data)
			}
		}
	}

	if mha.AttentionWeightsReward != nil {
		mha.AttentionWeightsReward.Release()
		mha.AttentionWeightsReward = nil
	}
	return nil
}

// Forward performs the forward pass of the MultiHeadCrossAttention layer.
// query: Input from the decoder layer (shape: [batch_size, target_sequence_length, dim_model]).
// key/value: Input from the encoder output (shape: [batch_size, source_sequence_length, dim_model]).
// mask: Optional mask for attention (e.g., padding mask for encoder output).
func (mha *MultiHeadCrossAttention) Forward(inputs ...*Tensor) (*Tensor, error) {

	if len(inputs) < 3 || len(inputs) > 4 {
		return nil, fmt.Errorf("MultiHeadCrossAttention.Forward expects 3 or 4 inputs (query, key, value, optional mask), got %d", len(inputs))
	}

	query := inputs[0]
	key := inputs[1]
	value := inputs[2]
	var mask *Tensor	// Declare mask as optional

	if len(inputs) == 4 {
		mask = inputs[3]
	}

	mha.queryTensor = query
	mha.keyTensor = key
	mha.valueTensor = value

	batchSize := query.Shape[0]
	qSeqLength := query.Shape[1]
	kvSeqLength := key.Shape[1]

	q, err := mha.QueryLinear.Forward(query)
	if err != nil {
		return nil, fmt.Errorf("cross-attention query linear failed: %w", err)
	}
	k, err := mha.KeyLinear.Forward(key)
	if err != nil {
		return nil, fmt.Errorf("cross-attention key linear failed: %w", err)
	}
	v, err := mha.ValueLinear.Forward(value)
	if err != nil {
		return nil, fmt.Errorf("cross-attention value linear failed: %w", err)
	}

	qReshaped, err := q.Reshape([]int{batchSize, qSeqLength, mha.NumQHeads, mha.DimModel / mha.NumQHeads})
	if err != nil {
		return nil, fmt.Errorf("failed to reshape cross-attention query tensor: %w", err)
	}

	qTransposed, err := qReshaped.Transpose(1, 2)
	if err != nil {
		return nil, fmt.Errorf("failed to transpose cross-attention query tensor: %w", err)
	}
	mha.q = qTransposed

	kReshaped, err := k.Reshape([]int{batchSize, kvSeqLength, mha.NumKVHeads, mha.DimKVHeads})
	if err != nil {
		return nil, fmt.Errorf("failed to reshape cross-attention key tensor: %w", err)
	}
	kTransposed, err := kReshaped.Transpose(1, 2)
	if err != nil {
		return nil, fmt.Errorf("failed to transpose cross-attention key tensor: %w", err)
	}
	mha.k = kTransposed

	vReshaped, err := v.Reshape([]int{batchSize, kvSeqLength, mha.NumKVHeads, mha.DimKVHeads})
	if err != nil {
		return nil, fmt.Errorf("failed to reshape cross-attention value tensor: %w", err)
	}
	vTransposed, err := vReshaped.Transpose(1, 2)
	if err != nil {
		return nil, fmt.Errorf("failed to transpose cross-attention value tensor: %w", err)
	}
	mha.v = vTransposed

	kT_Transposed, err := kTransposed.Transpose(len(kTransposed.Shape)-2, len(kTransposed.Shape)-1)
	if err != nil {
		return nil, fmt.Errorf("failed to transpose key tensor for cross-attention multiplication: %w", err)
	}

	if mha.NumQHeads != mha.NumKVHeads {
		return nil, errors.New("cross-attention simplified model requires NumQHeads == NumKVHeads")
	}

	attentionScores, err := qTransposed.MatMul(kT_Transposed)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate cross-attention scores (Q@K^T): %w", err)
	}
	mha.attentionScores = attentionScores

	scale := float32(1.0 / math.Sqrt(float64(mha.DimModel/mha.NumQHeads)))
	scaledAttentionScores, err := attentionScores.MulScalar(scale)
	if err != nil {
		return nil, fmt.Errorf("failed to scale cross-attention scores: %w", err)
	}

	if mask != nil {
		if len(mask.Shape) == 4 && mask.Shape[1] == 1 && mask.Shape[2] == 1 && mask.Shape[0] == scaledAttentionScores.Shape[0] && mask.Shape[3] == scaledAttentionScores.Shape[3] {

			resultData := make([]float32, len(scaledAttentionScores.Data))
			kvSeq := scaledAttentionScores.Shape[3]
			qSeq := scaledAttentionScores.Shape[2]
			heads := scaledAttentionScores.Shape[1]
			batchSize := scaledAttentionScores.Shape[0]

			for b := 0; b < batchSize; b++ {
				mOffset := b * kvSeq
				for h := 0; h < heads; h++ {
					for q := 0; q < qSeq; q++ {
						offset := ((b*heads+h)*qSeq + q) * kvSeq
						for k := 0; k < kvSeq; k++ {
							resultData[offset+k] = scaledAttentionScores.Data[offset+k] + mask.Data[mOffset+k]
						}
					}
				}
			}
			maskedScores := NewTensor(scaledAttentionScores.Shape, resultData, scaledAttentionScores.RequiresGrad || mask.RequiresGrad)
			if maskedScores.RequiresGrad {
				maskedScores.Creator = &AddWithBroadcastOperation{A: scaledAttentionScores, B: mask}
			}
			scaledAttentionScores = maskedScores
		} else {

			maskedAttentionScores, err := scaledAttentionScores.AddWithBroadcast(mask)
			if err != nil {
				return nil, fmt.Errorf("failed to apply mask to cross-attention scores: %w", err)
			}
			scaledAttentionScores = maskedAttentionScores
		}
	}

	attentionWeights, err := scaledAttentionScores.Softmax(len(scaledAttentionScores.Shape) - 1)
	if err != nil {
		return nil, fmt.Errorf("failed to apply softmax to attention scores: %w", err)
	}
	mha.attentionWeights = attentionWeights

	contextLayer, err := attentionWeights.MatMul(vTransposed)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate context layer (Attention@V): %w", err)
	}

	mha.attentionOutputBeforeConcat = contextLayer

	contextLayerTransposed, err := contextLayer.Transpose(1, 2)
	if err != nil {
		return nil, fmt.Errorf("failed to transpose context layer: %w", err)
	}

	outputShape := []int{batchSize, qSeqLength, mha.DimModel}
	contextLayerReshaped, err := contextLayerTransposed.Reshape(outputShape)
	if err != nil {
		return nil, fmt.Errorf("failed to reshape cross-attention context layer: %w", err)
	}

	output, err := mha.OutputLinear.Forward(contextLayerReshaped)
	if err != nil {
		return nil, fmt.Errorf("cross-attention output linear failed: %w", err)
	}

	mha.attentionOutput = output

	outputRequiresGrad := query.RequiresGrad || key.RequiresGrad || value.RequiresGrad ||
		mha.QueryLinear.Weights.RequiresGrad || (mha.QueryLinear.Biases != nil && mha.QueryLinear.Biases.RequiresGrad) ||
		mha.KeyLinear.Weights.RequiresGrad || (mha.KeyLinear.Biases != nil && mha.KeyLinear.Biases.RequiresGrad) ||
		mha.ValueLinear.Weights.RequiresGrad || (mha.ValueLinear.Biases != nil && mha.ValueLinear.Biases.RequiresGrad) ||
		mha.OutputLinear.Weights.RequiresGrad || (mha.OutputLinear.Biases != nil && mha.OutputLinear.Biases.RequiresGrad)

	output.RequiresGrad = outputRequiresGrad
	if output.RequiresGrad {
		output.Creator = mha
	}

	mha.attentionOutput = output

	return output, nil
}

// SetMode sets the attention layer to training or inference mode.
func (mha *MultiHeadAttention) SetMode(training bool) {
	if mha.QueryLinear != nil {
		mha.QueryLinear.SetMode(training)
	}
	if mha.KeyLinear != nil {
		mha.KeyLinear.SetMode(training)
	}
	if mha.ValueLinear != nil {
		mha.ValueLinear.SetMode(training)
	}
	if mha.OutputLinear != nil {
		mha.OutputLinear.SetMode(training)
	}
}

// SetMode sets the cross-attention layer to training or inference mode.
func (mhca *MultiHeadCrossAttention) SetMode(training bool) {
	if mhca.QueryLinear != nil {
		mhca.QueryLinear.SetMode(training)
	}
	if mhca.KeyLinear != nil {
		mhca.KeyLinear.SetMode(training)
	}
	if mhca.ValueLinear != nil {
		mhca.ValueLinear.SetMode(training)
	}
	if mhca.OutputLinear != nil {
		mhca.OutputLinear.SetMode(training)
	}
}

// SetMode sets the linear layer to training or inference mode.
func (l *Linear) SetMode(training bool) {

}

func init() {
	log.SetOutput(os.Stderr)
	log.SetFlags(log.LstdFlags | log.Lshortfile)
}

// applyDropout applies dropout to a tensor during training.
// During training, randomly sets dropoutRate fraction of values to 0 and scales remaining by 1/(1-dropoutRate).
// During inference (training=false), returns the tensor unchanged.
func applyDropout(tensor *Tensor, dropoutRate float32, training bool) *Tensor {
	if !training || dropoutRate == 0.0 {
		return tensor
	}

	mask := NewTensor(tensor.Shape, make([]float32, len(tensor.Data)), false)
	scale := 1.0 / (1.0 - dropoutRate)

	for i := range mask.Data {
		if rand.Float32() < dropoutRate {
			mask.Data[i] = 0.0
		} else {
			mask.Data[i] = scale
		}
	}

	output := NewTensor(tensor.Shape, make([]float32, len(tensor.Data)), tensor.RequiresGrad)
	MulVectors(tensor.Data, mask.Data, output.Data)

	return output
}

type LSTMCell struct {
	InputSize	int
	HiddenSize	int

	// Weight matrices
	Wf, Wi, Wc, Wo	*Tensor
	// Bias vectors
	Bf, Bi, Bc, Bo	*Tensor

	// Stored for backward pass
	InputTensor	*Tensor
	PrevHidden	*Tensor
	PrevCell	*Tensor
	ft, it, ct, ot	*Tensor
	cct		*Tensor
}

// NewLSTMCell creates a new LSTMCell.
func NewLSTMCell(inputSize, hiddenSize int) (*LSTMCell, error) {

	wf, err := NewLinear(inputSize+hiddenSize, hiddenSize)
	if err != nil {
		return nil, err
	}
	wi, err := NewLinear(inputSize+hiddenSize, hiddenSize)
	if err != nil {
		return nil, err
	}
	wc, err := NewLinear(inputSize+hiddenSize, hiddenSize)
	if err != nil {
		return nil, err
	}
	wo, err := NewLinear(inputSize+hiddenSize, hiddenSize)
	if err != nil {
		return nil, err
	}

	cell := &LSTMCell{
		InputSize:	inputSize,
		HiddenSize:	hiddenSize,
		Wf:		wf.Weights,
		Wi:		wi.Weights,
		Wc:		wc.Weights,
		Wo:		wo.Weights,
		Bf:		wf.Biases,
		Bi:		wi.Biases,
		Bc:		wc.Biases,
		Bo:		wo.Biases,
	}
	cell.SetForgetGateBias(1.0)
	return cell, nil
}

// Parameters returns all learnable parameters of the LSTMCell.
func (c *LSTMCell) ClearState() {
	if c.InputTensor != nil {
		c.InputTensor.Release()
	}
	if c.PrevHidden != nil {
		c.PrevHidden.Release()
	}
	if c.PrevCell != nil {
		c.PrevCell.Release()
	}
	if c.ft != nil {
		c.ft.Release()
	}
	if c.it != nil {
		c.it.Release()
	}
	if c.ct != nil {
		c.ct.Release()
	}
	if c.ot != nil {
		c.ot.Release()
	}
	if c.cct != nil {
		c.cct.Release()
	}

	c.InputTensor = nil
	c.PrevHidden = nil
	c.PrevCell = nil
	c.ft = nil
	c.it = nil
	c.ct = nil
	c.ot = nil
	c.cct = nil
}

// Parameters returns all learnable parameters of the LSTMCell.
func (c *LSTMCell) Parameters() []*Tensor {
	return []*Tensor{c.Wf, c.Wi, c.Wc, c.Wo, c.Bf, c.Bi, c.Bc, c.Bo}
}

// ToGPU moves the layer's parameters to the GPU.
func (c *LSTMCell) ToGPU() {
	if c.Wf != nil {
		c.Wf.ToGPU()
	}
	if c.Wi != nil {
		c.Wi.ToGPU()
	}
	if c.Wc != nil {
		c.Wc.ToGPU()
	}
	if c.Wo != nil {
		c.Wo.ToGPU()
	}
	if c.Bf != nil {
		c.Bf.ToGPU()
	}
	if c.Bi != nil {
		c.Bi.ToGPU()
	}
	if c.Bc != nil {
		c.Bc.ToGPU()
	}
	if c.Bo != nil {
		c.Bo.ToGPU()
	}
}

// SetForgetGateBias sets the bias for the forget gate.
func (c *LSTMCell) SetForgetGateBias(val float32) {
	if c.Bf != nil {
		for i := range c.Bf.Data {
			c.Bf.Data[i] = val
		}
	}
}

// SetForgetGateBias sets the forget gate bias for all cells in the LSTM.
func (l *LSTM) SetForgetGateBias(val float32) {
	for _, layer := range l.Cells {
		for _, cell := range layer {
			cell.SetForgetGateBias(val)
		}
	}
}

// Forward performs the forward pass of the LSTMCell.
func (c *LSTMCell) Forward(inputs ...*Tensor) (*Tensor, *Tensor, error) {
	if len(inputs) != 3 {
		return nil, nil, fmt.Errorf("LSTMCell.Forward expects 3 inputs (input, prevHidden, prevCell), got %d", len(inputs))
	}
	if inputs[0] == nil || inputs[1] == nil || inputs[2] == nil {
		return nil, nil, fmt.Errorf("LSTMCell.Forward received nil input tensor(s)")
	}
	input, prevHidden, prevCell := inputs[0], inputs[1], inputs[2]

	c.InputTensor = input
	c.PrevHidden = prevHidden
	c.PrevCell = prevCell

	inputSize := c.InputSize

	wf_in, err := c.Wf.Slice(0, 0, inputSize)
	if err != nil {
		return nil, nil, err
	}
	wf_hid, err := c.Wf.Slice(0, inputSize, c.Wf.Shape[0])
	if err != nil {
		return nil, nil, err
	}

	wi_in, err := c.Wi.Slice(0, 0, inputSize)
	if err != nil {
		return nil, nil, err
	}
	wi_hid, err := c.Wi.Slice(0, inputSize, c.Wi.Shape[0])
	if err != nil {
		return nil, nil, err
	}

	wc_in, err := c.Wc.Slice(0, 0, inputSize)
	if err != nil {
		return nil, nil, err
	}
	wc_hid, err := c.Wc.Slice(0, inputSize, c.Wc.Shape[0])
	if err != nil {
		return nil, nil, err
	}

	wo_in, err := c.Wo.Slice(0, 0, inputSize)
	if err != nil {
		return nil, nil, err
	}
	wo_hid, err := c.Wo.Slice(0, inputSize, c.Wo.Shape[0])
	if err != nil {
		wf_in.Release()
		wf_hid.Release()
		wi_in.Release()
		wi_hid.Release()
		wc_in.Release()
		wc_hid.Release()
		wo_in.Release()
		return nil, nil, err
	}

	cleanupSlices := func() {
		wf_in.Release()
		wf_hid.Release()
		wi_in.Release()
		wi_hid.Release()
		wc_in.Release()
		wc_hid.Release()
		wo_in.Release()
		wo_hid.Release()
	}
	defer cleanupSlices()

	f_in, err := input.MatMul(wf_in)
	if err != nil {
		return nil, nil, err
	}
	f_hid, err := prevHidden.MatMul(wf_hid)
	if err != nil {
		return nil, nil, err
	}
	ft, err := f_in.Add(f_hid)
	if err != nil {
		return nil, nil, err
	}
	ft, err = ft.AddWithBroadcast(c.Bf)
	if err != nil {
		return nil, nil, err
	}
	ft, err = ft.Sigmoid()
	if err != nil {
		return nil, nil, err
	}
	c.ft = ft
	f_in.Release()
	f_hid.Release()

	i_in, err := input.MatMul(wi_in)
	if err != nil {
		return nil, nil, err
	}
	i_hid, err := prevHidden.MatMul(wi_hid)
	if err != nil {
		return nil, nil, err
	}
	it, err := i_in.Add(i_hid)
	if err != nil {
		return nil, nil, err
	}
	it, err = it.AddWithBroadcast(c.Bi)
	if err != nil {
		return nil, nil, err
	}
	it, err = it.Sigmoid()
	if err != nil {
		return nil, nil, err
	}
	c.it = it
	i_in.Release()
	i_hid.Release()

	cc_in, err := input.MatMul(wc_in)
	if err != nil {
		return nil, nil, err
	}
	cc_hid, err := prevHidden.MatMul(wc_hid)
	if err != nil {
		return nil, nil, err
	}
	cct, err := cc_in.Add(cc_hid)
	if err != nil {
		return nil, nil, err
	}
	cct, err = cct.AddWithBroadcast(c.Bc)
	if err != nil {
		return nil, nil, err
	}
	cct, err = cct.Tanh()
	if err != nil {
		return nil, nil, err
	}
	c.cct = cct
	cc_in.Release()
	cc_hid.Release()

	o_in, err := input.MatMul(wo_in)
	if err != nil {
		return nil, nil, err
	}
	o_hid, err := prevHidden.MatMul(wo_hid)
	if err != nil {
		return nil, nil, err
	}
	ot, err := o_in.Add(o_hid)
	if err != nil {
		return nil, nil, err
	}
	ot, err = ot.AddWithBroadcast(c.Bo)
	if err != nil {
		return nil, nil, err
	}
	ot, err = ot.Sigmoid()
	if err != nil {
		return nil, nil, err
	}
	c.ot = ot

	term1, err := ft.Mul(prevCell)
	if err != nil {
		return nil, nil, err
	}
	term2, err := it.Mul(cct)
	if err != nil {
		return nil, nil, err
	}
	ct, err := term1.Add(term2)
	if err != nil {
		return nil, nil, err
	}
	c.ct = ct

	ct_tanh, err := ct.Tanh()
	if err != nil {
		return nil, nil, fmt.Errorf("LSTMCell.Forward: Tanh operation failed: %w", err)
	}
	ht, err := ot.Mul(ct_tanh)
	if err != nil {
		return nil, nil, fmt.Errorf("LSTMCell.Forward: Mul operation failed for hidden state: %w", err)
	}

	return ht, ct, nil
}

// Backward performs the backward pass for the LSTMCell.
func (c *LSTMCell) Backward(gradHt, gradCt *Tensor) error {

	ct_tanh, err := c.ct.Tanh()
	if err != nil {
		return err
	}
	gradOt, err := gradHt.Mul(ct_tanh)
	if err != nil {
		return err
	}
	grad_ct_tanh, err := gradHt.Mul(c.ot)
	if err != nil {
		return err
	}

	grad_ct_from_ht, err := grad_ct_tanh.OneMinusSquareTanh(c.ct)
	if err != nil {
		return err
	}
	gradCt, err = gradCt.Add(grad_ct_from_ht)
	if err != nil {
		return err
	}

	gradPrevCell, err := gradCt.Mul(c.ft)
	if err != nil {
		return err
	}
	gradFt, err := gradCt.Mul(c.PrevCell)
	if err != nil {
		return err
	}
	gradIt, err := gradCt.Mul(c.cct)
	if err != nil {
		return err
	}
	gradCct, err := gradCt.Mul(c.it)
	if err != nil {
		return err
	}

	gradOt_linear, err := gradOt.SigmoidBackward(c.ot)
	if err != nil {
		return err
	}
	gradFt_linear, err := gradFt.SigmoidBackward(c.ft)
	if err != nil {
		return err
	}
	gradIt_linear, err := gradIt.SigmoidBackward(c.it)
	if err != nil {
		return err
	}

	gradCct_linear, err := gradCct.OneMinusSquareTanh(c.cct)
	if err != nil {
		return err
	}

	combined, err := Concat([]*Tensor{c.InputTensor, c.PrevHidden}, 1)
	if err != nil {
		return err
	}
	combinedT, err := combined.Transpose(0, 1)
	if err != nil {
		return err
	}

	gradWf, err := combinedT.MatMul(gradFt_linear)
	if err != nil {
		return err
	}
	gradWi, err := combinedT.MatMul(gradIt_linear)
	if err != nil {
		return err
	}
	gradWc, err := combinedT.MatMul(gradCct_linear)
	if err != nil {
		return err
	}
	gradWo, err := combinedT.MatMul(gradOt_linear)
	if err != nil {
		return err
	}

	gradBf, err := gradFt_linear.Sum(0)
	if err != nil {
		return err
	}
	gradBi, err := gradIt_linear.Sum(0)
	if err != nil {
		return err
	}
	gradBc, err := gradCct_linear.Sum(0)
	if err != nil {
		return err
	}
	gradBo, err := gradOt_linear.Sum(0)
	if err != nil {
		return err
	}

	if c.Wf.RequiresGrad {
		if c.Wf.Grad == nil {
			c.Wf.Grad = NewTensor(c.Wf.Shape, make([]float32, len(c.Wf.Data)), false)
		}
		safeAccumulate(c.Wf.Grad.Data, gradWf.Data)
	}

	if c.Wi.RequiresGrad {
		if c.Wi.Grad == nil {
			c.Wi.Grad = NewTensor(c.Wi.Shape, make([]float32, len(c.Wi.Data)), false)
		}
		safeAccumulate(c.Wi.Grad.Data, gradWi.Data)
	}

	if c.Wc.RequiresGrad {
		if c.Wc.Grad == nil {
			c.Wc.Grad = NewTensor(c.Wc.Shape, make([]float32, len(c.Wc.Data)), false)
		}
		safeAccumulate(c.Wc.Grad.Data, gradWc.Data)
	}

	if c.Wo.RequiresGrad {
		if c.Wo.Grad == nil {
			c.Wo.Grad = NewTensor(c.Wo.Shape, make([]float32, len(c.Wo.Data)), false)
		}
		safeAccumulate(c.Wo.Grad.Data, gradWo.Data)
	}

	if c.Bf.RequiresGrad {
		if c.Bf.Grad == nil {
			c.Bf.Grad = NewTensor(c.Bf.Shape, make([]float32, len(c.Bf.Data)), false)
		}
		safeAccumulate(c.Bf.Grad.Data, gradBf.Data)
	}

	if c.Bi.RequiresGrad {
		if c.Bi.Grad == nil {
			c.Bi.Grad = NewTensor(c.Bi.Shape, make([]float32, len(c.Bi.Data)), false)
		}
		safeAccumulate(c.Bi.Grad.Data, gradBi.Data)
	}

	if c.Bc.RequiresGrad {
		if c.Bc.Grad == nil {
			c.Bc.Grad = NewTensor(c.Bc.Shape, make([]float32, len(c.Bc.Data)), false)
		}
		safeAccumulate(c.Bc.Grad.Data, gradBc.Data)
	}

	if c.Bo.RequiresGrad {
		if c.Bo.Grad == nil {
			c.Bo.Grad = NewTensor(c.Bo.Shape, make([]float32, len(c.Bo.Data)), false)
		}
		safeAccumulate(c.Bo.Grad.Data, gradBo.Data)
	}

	transposedWf, err := c.Wf.Transpose(0, 1)
	if err != nil {
		return err
	}
	gradCombined_f, err := gradFt_linear.MatMul(transposedWf)
	if err != nil {
		return err
	}
	transposedWi, err := c.Wi.Transpose(0, 1)
	if err != nil {
		return err
	}
	gradCombined_i, err := gradIt_linear.MatMul(transposedWi)
	if err != nil {
		return err
	}
	transposedWc, err := c.Wc.Transpose(0, 1)
	if err != nil {
		return err
	}
	gradCombined_c, err := gradCct_linear.MatMul(transposedWc)
	if err != nil {
		return err
	}
	transposedWo, err := c.Wo.Transpose(0, 1)
	if err != nil {
		return err
	}
	gradCombined_o, err := gradOt_linear.MatMul(transposedWo)
	if err != nil {
		return err
	}
	transposedWf.Release()
	transposedWi.Release()
	transposedWc.Release()
	transposedWo.Release()

	gradCombined, err := gradCombined_f.Add(gradCombined_i)
	if err != nil {
		return err
	}
	gradCombined, err = gradCombined.Add(gradCombined_c)
	if err != nil {
		return err
	}
	gradCombined, err = gradCombined.Add(gradCombined_o)
	if err != nil {
		return err
	}
	gradCombined_f.Release()
	gradCombined_i.Release()
	gradCombined_c.Release()
	gradCombined_o.Release()

	gradInput, err := gradCombined.Slice(1, 0, c.InputSize)
	if err != nil {
		return err
	}
	gradPrevHidden, err := gradCombined.Slice(1, c.InputSize, c.InputSize+c.HiddenSize)
	if err != nil {
		return err
	}
	gradCombined.Release()

	if c.InputTensor.RequiresGrad {
		if c.InputTensor.Grad == nil {
			c.InputTensor.Grad = NewTensor(c.InputTensor.Shape, make([]float32, len(c.InputTensor.Data)), false)
		}
		c.InputTensor.Grad, err = c.InputTensor.Grad.Add(gradInput)
		if err != nil {
			return err
		}
	}
	if c.PrevHidden.RequiresGrad {
		if c.PrevHidden.Grad == nil {
			c.PrevHidden.Grad = NewTensor(c.PrevHidden.Shape, make([]float32, len(c.PrevHidden.Data)), false)
		}
		c.PrevHidden.Grad, err = c.PrevHidden.Grad.Add(gradPrevHidden)
		if err != nil {
			return err
		}
	}
	if c.PrevCell.RequiresGrad {
		if c.PrevCell.Grad == nil {
			c.PrevCell.Grad = NewTensor(c.PrevCell.Shape, make([]float32, len(c.PrevCell.Data)), false)
		}
		c.PrevCell.Grad, err = c.PrevCell.Grad.Add(gradPrevCell)
		if err != nil {
			return err
		}
	}

	return nil
}

// NewLSTM creates a new LSTM.
func NewLSTM(inputSize, hiddenSize, numLayers int) (*LSTM, error) {
	cells := make([][]*LSTMCell, numLayers)
	for i := range numLayers {
		layerInputSize := inputSize
		if i > 0 {
			layerInputSize = hiddenSize
		}
		cells[i] = make([]*LSTMCell, 1)
		cell, err := NewLSTMCell(layerInputSize, hiddenSize)
		if err != nil {
			return nil, err
		}
		cells[i][0] = cell
	}
	return &LSTM{
		InputSize:	inputSize,
		HiddenSize:	hiddenSize,
		NumLayers:	numLayers,
		Cells:		cells,
	}, nil
}

// Parameters returns all learnable parameters of the LSTM.
func (l *LSTM) Parameters() []*Tensor {
	params := []*Tensor{}
	for _, layer := range l.Cells {
		for _, cell := range layer {
			params = append(params, cell.Parameters()...)
		}
	}
	return params
}

// ToGPU moves all cells' parameters to the GPU.
func (l *LSTM) ClearState() {
	for _, layer := range l.Cells {
		for _, cell := range layer {
			cell.ClearState()
		}
	}
	if l.timeStepCells != nil {
		for _, layer := range l.timeStepCells {
			for _, cell := range layer {
				if cell != nil {
					cell.ClearState()
				}
			}
		}
	}
	l.timeStepCells = nil
}

// ToGPU moves all cells' parameters to the GPU.
func (l *LSTM) ToGPU() {
	for _, layer := range l.Cells {
		for _, cell := range layer {
			cell.ToGPU()
		}
	}
}

// Forward performs the forward pass of the LSTM.
func (l *LSTM) Forward(inputs ...*Tensor) (*Tensor, *Tensor, error) {
	if len(inputs) != 3 {
		return nil, nil, fmt.Errorf("LSTM.Forward expects 3 inputs (input, initialHidden, initialCell), got %d", len(inputs))
	}
	input, initialHidden, initialCell := inputs[0], inputs[1], inputs[2]

	if len(input.Shape) == 3 {
		batchSize := input.Shape[0]
		sequenceLength := input.Shape[1]

		l.timeStepCells = make([][]*LSTMCell, l.NumLayers)
		for i := range l.timeStepCells {
			l.timeStepCells[i] = make([]*LSTMCell, sequenceLength)
		}

		layerInput := input
		var lastCellState *Tensor

		for i := 0; i < l.NumLayers; i++ {
			h, c := initialHidden, initialCell
			if i > 0 {
				h = NewTensor([]int{batchSize, l.HiddenSize}, make([]float32, batchSize*l.HiddenSize), false)
				c = NewTensor([]int{batchSize, l.HiddenSize}, make([]float32, batchSize*l.HiddenSize), false)
			}

			cell0 := l.Cells[i][0]
			inSize := layerInput.Shape[2]

			wf_in, _ := cell0.Wf.Slice(0, 0, inSize)
			wi_in, _ := cell0.Wi.Slice(0, 0, inSize)
			wc_in, _ := cell0.Wc.Slice(0, 0, inSize)
			wo_in, _ := cell0.Wo.Slice(0, 0, inSize)
			w_in_all, _ := Concat([]*Tensor{wf_in, wi_in, wc_in, wo_in}, 1)

			b_all, _ := Concat([]*Tensor{cell0.Bf, cell0.Bi, cell0.Bc, cell0.Bo}, 0)

			wf_hid, _ := cell0.Wf.Slice(0, inSize, cell0.Wf.Shape[0])
			wi_hid, _ := cell0.Wi.Slice(0, inSize, cell0.Wi.Shape[0])
			wc_hid, _ := cell0.Wc.Slice(0, inSize, cell0.Wc.Shape[0])
			wo_hid, _ := cell0.Wo.Slice(0, inSize, cell0.Wo.Shape[0])
			w_hid_all, _ := Concat([]*Tensor{wf_hid, wi_hid, wc_hid, wo_hid}, 1)

			reshapedInput, _ := layerInput.Reshape([]int{batchSize * sequenceLength, inSize})
			inputProjAll, err := reshapedInput.MatMul(w_in_all)
			if err != nil {
				return nil, nil, fmt.Errorf("failed to pre-project input: %w", err)
			}
			inputProjAll, _ = inputProjAll.AddWithBroadcast(b_all)

			inputProjAll3D, _ := inputProjAll.Reshape([]int{batchSize, sequenceLength, 4 * l.HiddenSize})
			inputProjTrans, _ := inputProjAll3D.Transpose(0, 1)

			outputs := make([]*Tensor, sequenceLength)
			for t := range sequenceLength {

				projTData := inputProjTrans.Data[t*batchSize*4*l.HiddenSize : (t+1)*batchSize*4*l.HiddenSize]
				projT := NewTensor([]int{batchSize, 4 * l.HiddenSize}, projTData, false)

				cellForTimeStep := *cell0
				l.timeStepCells[i][t] = &cellForTimeStep

				hidProjAll, _ := h.MatMul(w_hid_all)

				gatesAll, _ := projT.Add(hidProjAll)

				ft, _ := gatesAll.Slice(1, 0, l.HiddenSize)
				it, _ := gatesAll.Slice(1, l.HiddenSize, 2*l.HiddenSize)
				cct, _ := gatesAll.Slice(1, 2*l.HiddenSize, 3*l.HiddenSize)
				ot, _ := gatesAll.Slice(1, 3*l.HiddenSize, 4*l.HiddenSize)

				ft, _ = ft.Sigmoid()
				it, _ = it.Sigmoid()
				cct, _ = cct.Tanh()
				ot, _ = ot.Sigmoid()

				cellForTimeStep.ft = ft
				cellForTimeStep.it = it
				cellForTimeStep.cct = cct
				cellForTimeStep.ot = ot

				inputSlice, _ := layerInput.Slice(1, t, t+1)
				inputT, _ := inputSlice.Reshape([]int{batchSize, inSize})
				cellForTimeStep.InputTensor = inputT
				cellForTimeStep.PrevHidden = h
				cellForTimeStep.PrevCell = c

				term1, _ := ft.Mul(c)
				term2, _ := it.Mul(cct)
				c, _ = term1.Add(term2)
				cellForTimeStep.ct = c

				ct_tanh, _ := c.Tanh()
				h, _ = ot.Mul(ct_tanh)

				outputs[t] = h
			}

			lastCellState = c

			stackedOutputData := make([]float32, batchSize*sequenceLength*l.HiddenSize)
			for t, ht := range outputs {
				for b := 0; b < batchSize; b++ {
					copy(stackedOutputData[(b*sequenceLength+t)*l.HiddenSize:(b*sequenceLength+t+1)*l.HiddenSize], ht.Data[b*l.HiddenSize:(b+1)*l.HiddenSize])
				}
			}
			stackedOutput := NewTensor([]int{batchSize, sequenceLength, l.HiddenSize}, stackedOutputData, true)

			for t := range sequenceLength {
				l.timeStepCells[i][t].InputTensor.Creator = layerInput
			}

			if i < l.NumLayers-1 {
				layerInput = applyDropout(stackedOutput, l.DropoutRate, l.Training)
			} else {
				return stackedOutput, lastCellState, nil
			}
		}
		return nil, nil, fmt.Errorf("LSTM forward loop finished without returning")
	} else if len(input.Shape) == 2 {

		l.timeStepCells = nil

		var currentHidden, currentCell *Tensor = initialHidden, initialCell
		var layerOutput *Tensor = input

		for i := 0; i < l.NumLayers; i++ {
			if i > 0 {
				layerOutput = currentHidden
				if i < l.NumLayers {
					layerOutput = applyDropout(layerOutput, l.DropoutRate, l.Training)
				}
			}

			ht, ct, err := l.Cells[i][0].Forward(layerOutput, currentHidden, currentCell)
			if err != nil {
				log.Printf("LSTMCell.Forward in LSTM.Forward failed: %+v", err)
				return nil, nil, err
			}
			currentHidden = ht
			currentCell = ct
		}
		return currentHidden, currentCell, nil
	} else {
		return nil, nil, fmt.Errorf("LSTM.Forward expects a 2D or 3D input tensor, got %d dimensions", len(input.Shape))
	}
}

// Backward performs the backward pass for the entire LSTM layer.
func (l *LSTM) Backward(gradNextHidden, gradNextCell *Tensor) error {

	if len(l.timeStepCells) == 0 {
		gradH := gradNextHidden
		gradC := gradNextCell
		var err error
		for i := l.NumLayers - 1; i >= 0; i-- {
			cell := l.Cells[i][0]
			err = cell.Backward(gradH, gradC)
			if err != nil {
				return fmt.Errorf("failed to backpropagate through LSTM cell in layer %d: %w", i, err)
			}
			if i > 0 {
				if cell.InputTensor.Grad == nil || cell.PrevHidden.Grad == nil {
					return fmt.Errorf("gradient not computed for input or hidden state in layer %d", i)
				}
				gradH, err = cell.InputTensor.Grad.Add(cell.PrevHidden.Grad)
				if err != nil {
					return err
				}
				gradC = cell.PrevCell.Grad
			}
		}
		return nil
	}

	gradH := gradNextHidden
	gradC := gradNextCell

	for i := l.NumLayers - 1; i >= 0; i-- {
		sequenceLength := len(l.timeStepCells[i])
		layerInputTensor := l.timeStepCells[i][0].InputTensor.Creator.(*Tensor)

		if layerInputTensor.Grad == nil {
			layerInputTensor.Grad = NewTensor(layerInputTensor.Shape, make([]float32, len(layerInputTensor.Data)), false)
		}

		batchSize := gradH.Shape[0]
		gradHFromFuture := NewTensor([]int{batchSize, l.HiddenSize}, make([]float32, batchSize*l.HiddenSize), false)
		gradCFromFuture := NewTensor([]int{batchSize, l.HiddenSize}, make([]float32, batchSize*l.HiddenSize), false)

		for t := sequenceLength - 1; t >= 0; t-- {
			cell := l.timeStepCells[i][t]

			// Total gradient for ht = (grad from layer above) + (grad from h_{t+1})
			// Get incoming gradient for this time step
			var currentStepGradH *Tensor
			if len(gradH.Shape) == 3 {

				shSlice, _ := gradH.Slice(1, t, t+1)
				currentStepGradH, _ = shSlice.Squeeze(1)
			} else if t == sequenceLength-1 {

				currentStepGradH = gradH
			} else {

				currentStepGradH = NewTensor(gradHFromFuture.Shape, make([]float32, len(gradHFromFuture.Data)), false)
			}

			totalGradH, err := currentStepGradH.Add(gradHFromFuture)
			if err != nil {
				return err
			}

			totalGradC := gradCFromFuture
			if t == sequenceLength-1 {
				totalGradC, err = gradC.Add(gradCFromFuture)
				if err != nil {
					return err
				}
			}

			err = cell.Backward(totalGradH, totalGradC)
			if err != nil {
				return fmt.Errorf("BPTT: cell.Backward at t=%d, layer=%d failed: %w", t, i, err)
			}

			gradHFromFuture = cell.PrevHidden.Grad
			gradCFromFuture = cell.PrevCell.Grad

			totalGradH.Release()
			if totalGradC != gradCFromFuture && totalGradC != gradC {
				totalGradC.Release()
			}

			if cell.InputTensor.Grad != nil {
				batchSize := cell.InputTensor.Shape[0]
				inputSize := cell.InputTensor.Shape[1]
				for b := 0; b < batchSize; b++ {
					outOffset := (b*sequenceLength + t) * inputSize
					inOffset := b * inputSize
					if outOffset >= 0 && outOffset+inputSize <= len(layerInputTensor.Grad.Data) && inOffset >= 0 && inOffset+inputSize <= len(cell.InputTensor.Grad.Data) {
						safeAccumulate(layerInputTensor.Grad.Data[outOffset:outOffset+inputSize], cell.InputTensor.Grad.Data[inOffset:inOffset+inputSize])
					} else {

					}
				}
			}
		}

		if gradH != layerInputTensor.Grad && gradH != gradNextHidden {
			gradH.Release()
		}
		gradH = layerInputTensor.Grad

		if gradC != gradNextCell {
			gradC.Release()
		}
		gradC = NewTensor(gradC.Shape, make([]float32, len(gradC.Data)), false)
	}
	return nil
}

func (l *LSTM) GetInputGrad() *Tensor {
	if len(l.timeStepCells) > 0 && len(l.timeStepCells[0]) > 0 {
		creator := l.timeStepCells[0][0].InputTensor.Creator
		if creator != nil {
			if t, ok := creator.(*Tensor); ok {
				return t.Grad
			}
		}
	}
	return nil
}

func (l *LSTM) GetCellState(layer, timestep int) *Tensor {
	if layer < 0 || layer >= l.NumLayers || l.timeStepCells == nil || timestep < 0 || timestep >= len(l.timeStepCells[0]) {
		return nil
	}
	return l.timeStepCells[layer][timestep].ct
}

func (l *LSTM) SetCellState(hidden, cell *Tensor) {
	for i := 0; i < l.NumLayers; i++ {
		l.Cells[i][0].PrevHidden = hidden
		l.Cells[i][0].PrevCell = cell
	}
}

func (l *LSTM) BackwardStep(gradH, gradC *Tensor, timestep int) error {
	if l.timeStepCells == nil || timestep < 0 || timestep >= len(l.timeStepCells[0]) {
		return fmt.Errorf("invalid timestep for BackwardStep")
	}

	currentGradH := gradH
	currentGradC := gradC

	for layer := l.NumLayers - 1; layer >= 0; layer-- {
		cell := l.timeStepCells[layer][timestep]
		err := cell.Backward(currentGradH, currentGradC)
		if err != nil {
			return err
		}
		currentGradH = cell.InputTensor.Grad
		currentGradC = cell.PrevCell.Grad
	}
	return nil
}

func (l *LSTM) GetPrevHiddenGrad() *Tensor {
	if l.timeStepCells == nil || len(l.timeStepCells[0]) == 0 {
		return nil
	}
	return l.timeStepCells[0][0].PrevHidden.Grad
}

func (l *LSTM) GetPrevCellGrad() *Tensor {
	if l.timeStepCells == nil || len(l.timeStepCells[0]) == 0 {
		return nil
	}
	return l.timeStepCells[0][0].PrevCell.Grad
}

func (l *LSTM) GetInputGradStep(t int) *Tensor {
	if l.timeStepCells == nil || t < 0 || t >= len(l.timeStepCells[0]) {
		return nil
	}
	return l.timeStepCells[0][t].InputTensor.Grad
}

// GetSingleStepInputGrad returns the input gradient from the bottom LSTM layer
// after a single-step (2D input) backward pass.
func (l *LSTM) GetSingleStepInputGrad() *Tensor {
	if len(l.Cells) == 0 || len(l.Cells[0]) == 0 {
		return nil
	}
	return l.Cells[0][0].InputTensor.Grad
}

// GetSingleStepPrevHiddenGrad returns the previous-hidden gradient from the
// bottom LSTM layer after a single-step backward pass.
func (l *LSTM) GetSingleStepPrevHiddenGrad() *Tensor {
	if len(l.Cells) == 0 || len(l.Cells[0]) == 0 {
		return nil
	}
	return l.Cells[0][0].PrevHidden.Grad
}

// GetSingleStepPrevCellGrad returns the previous-cell gradient from the
// bottom LSTM layer after a single-step backward pass.
func (l *LSTM) GetSingleStepPrevCellGrad() *Tensor {
	if len(l.Cells) == 0 || len(l.Cells[0]) == 0 {
		return nil
	}
	return l.Cells[0][0].PrevCell.Grad
}

// Forward pass https://wiki.pathmind.com/neural-network
func ForwardPassNer(n *nnu.SimpleNN, inputs []float64) []float64 {

	hidden := make([]float64, n.HiddenSize)

	for i := range hidden {

		sum := 0.0

		for j := range inputs {

			sum += n.WeightsIH[i][j] * inputs[j]
		}

		hidden[i] = n.Sigmoid(sum)
	}

	output := make([]float64, n.OutputSize)

	for i := range output {

		sum := 0.0

		for j := range hidden {

			sum += n.WeightsHO[i][j] * hidden[j]
		}

		output[i] = n.Sigmoid(sum)
	}

	return output
}

func CalculateErrorNer(nn *nnu.SimpleNN, targetTag string, outputs []float64, trainingData []tag.Tag) ([]float64, map[string]int) {

	targetOutput := make([]float64, nn.OutputSize)
	nerTagVocab := CreateTagVocabNer(trainingData)
	targetNerTagIndex, ok := nerTagVocab[targetTag]

	if ok {

		targetOutput[targetNerTagIndex] = 1
	}

	errors := make([]float64, nn.OutputSize)

	for i := range errors {
		errors[i] = targetOutput[i] - outputs[i]
	}
	return errors, nerTagVocab
}

func CreateTagVocabNer(trainingData []tag.Tag) map[string]int {
	nerTagVocab := make(map[string]int)
	index := 0

	for _, taggedSentence := range trainingData {
		for _, nerTag := range taggedSentence.NerTag {
			if _, ok := nerTagVocab[nerTag]; !ok {
				nerTagVocab[nerTag] = index
				index++
			}
		}
	}

	return nerTagVocab
}

func IndexToNerTag(nerTagVocab map[string]int, predictedTagIndex int) (string, bool) {
	for tag, index := range nerTagVocab {
		if index == predictedTagIndex {
			return tag, true
		}
	}
	return "", false
}

func PredictNerTags(nn *nnu.SimpleNN, inputs []float64, nerTagVocab map[string]int, predictedNerTags []string, predictedTagIndex int) []string {

	predictedTagNer, ok := IndexToNerTag(nerTagVocab, predictedTagIndex)

	if !ok {

		fmt.Printf("NER tag index %d not found in vocabulary\n", predictedTagIndex)

		predictedNerTags = append(predictedNerTags, "O")
	}

	predictedNerTags = append(predictedNerTags, predictedTagNer)
	return predictedNerTags
}

type SemanticOutput struct {
	Operation	string	`json:"operation"`
	TargetResource	struct {
		Type		string	`json:"type"`
		Name		string	`json:"name"`
		Properties	struct {
			Path string `json:"path"`
		}	`json:"properties"`
		Children	[]struct {
			Type		string		`json:"type"`
			Name		string		`json:"name"`
			Properties	map[string]any	`json:"properties"`
		}	`json:"children"`
	}	`json:"target_resource"`
	Context	struct {
		UserRole string `json:"user_role"`
	}	`json:"context"`
}

type Entity struct {
	Word	string
	Type	EntityType
	Start	int	// word index in query
	End	int	// word index in query
}

type RuleBasedNER struct {
	semanticOutput	*SemanticOutput
	queryWords	[]string
}

// NewRuleBasedNER creates a new rule-based NER instance
func NewRuleBasedNER(query string, semanticOutputJSON string) (*RuleBasedNER, error) {
	// Parse semantic output
	var semOut SemanticOutput

	cleanJSON := strings.TrimSpace(semanticOutputJSON)
	cleanJSON = strings.TrimPrefix(cleanJSON, "<s>")
	cleanJSON = strings.TrimSuffix(cleanJSON, "</s>")
	cleanJSON = strings.TrimSpace(cleanJSON)

	err := json.Unmarshal([]byte(cleanJSON), &semOut)
	if err != nil {

		return &RuleBasedNER{
			semanticOutput:	nil,
			queryWords:	strings.Fields(strings.ToLower(query)),
		}, nil
	}

	return &RuleBasedNER{
		semanticOutput:	&semOut,
		queryWords:	strings.Fields(strings.ToLower(query)),
	}, nil
}

// ExtractEntities extracts named entities from the query using semantic context
func (r *RuleBasedNER) ExtractEntities() []Entity {
	entities := make([]Entity, 0)

	if r.semanticOutput == nil {

		return r.extractWithPatterns()
	}

	targetName := strings.ToLower(r.semanticOutput.TargetResource.Name)
	targetType := r.semanticOutput.TargetResource.Type

	// Determine entity type based on resource type
	var entityType EntityType
	if strings.Contains(targetType, "File") {
		entityType = EntityTypeFileName
	} else if strings.Contains(targetType, "Folder") {
		entityType = EntityTypeFolderName
	} else {
		entityType = EntityTypeOutside
	}

	if targetName != "" && targetName != "." {
		nameWords := strings.Fields(targetName)
		entities = append(entities, r.findEntityInQuery(nameWords, entityType)...)
	}

	for _, child := range r.semanticOutput.TargetResource.Children {
		childName := strings.ToLower(child.Name)
		if childName != "" {
			childType := EntityTypeFileName
			if strings.Contains(child.Type, "Folder") {
				childType = EntityTypeFolderName
			}
			nameWords := strings.Fields(childName)
			entities = append(entities, r.findEntityInQuery(nameWords, childType)...)
		}
	}

	operation := strings.ToLower(r.semanticOutput.Operation)
	if operation != "" {
		opWords := []string{operation}
		entities = append(entities, r.findEntityInQuery(opWords, EntityTypeOperation)...)
	}

	return entities
}

// findEntityInQuery finds entity words in the query
func (r *RuleBasedNER) findEntityInQuery(entityWords []string, entityType EntityType) []Entity {
	entities := make([]Entity, 0)

	if len(entityWords) == 1 {
		word := entityWords[0]
		for i, queryWord := range r.queryWords {

			cleanQueryWord := strings.Trim(queryWord, "\"',.;:")
			if cleanQueryWord == word || queryWord == word {
				entities = append(entities, Entity{
					Word:	queryWord,
					Type:	entityType,
					Start:	i,
					End:	i,
				})
			}
		}
		return entities
	}

	for i := 0; i <= len(r.queryWords)-len(entityWords); i++ {
		match := true
		for j, entityWord := range entityWords {
			cleanQueryWord := strings.Trim(r.queryWords[i+j], "\"',.;:")
			if cleanQueryWord != entityWord {
				match = false
				break
			}
		}
		if match {

			for j := range entityWords {
				entities = append(entities, Entity{
					Word:	r.queryWords[i+j],
					Type:	entityType,
					Start:	i + j,
					End:	i + j,
				})
			}
			break
		}
	}

	return entities
}

// extractWithPatterns uses pattern-based rules when semantic output is unavailable
func (r *RuleBasedNER) extractWithPatterns() []Entity {
	entities := make([]Entity, 0)

	for i := 0; i < len(r.queryWords)-1; i++ {
		if r.queryWords[i] == "folder" || r.queryWords[i] == "directory" || r.queryWords[i] == "dir" {
			entities = append(entities, Entity{
				Word:	r.queryWords[i+1],
				Type:	EntityTypeFolderName,
				Start:	i + 1,
				End:	i + 1,
			})
		}
	}

	for i := 1; i < len(r.queryWords); i++ {
		if r.queryWords[i] == "folder" || r.queryWords[i] == "directory" || r.queryWords[i] == "dir" {

			prevWord := r.queryWords[i-1]
			if prevWord != "move" && prevWord != "to" && prevWord != "into" &&
				prevWord != "create" && prevWord != "add" && prevWord != "delete" {
				entities = append(entities, Entity{
					Word:	prevWord,
					Type:	EntityTypeFolderName,
					Start:	i - 1,
					End:	i - 1,
				})
			}
		}
	}

	for i := 0; i < len(r.queryWords)-1; i++ {
		if r.queryWords[i] == "into" || r.queryWords[i] == "to" {
			nextWord := r.queryWords[i+1]

			if nextWord != "folder" && nextWord != "directory" && nextWord != "file" {
				entities = append(entities, Entity{
					Word:	nextWord,
					Type:	EntityTypeFolderName,
					Start:	i + 1,
					End:	i + 1,
				})
			}
		}
	}

	fileTypes := []string{
		"html", "css", "js", "javascript", "typescript", "ts",
		"python", "py", "java", "go", "c", "cpp", "c++",
		"json", "yaml", "yml", "xml", "toml", "ini",
		"markdown", "md", "txt", "csv", "log",
		"sql", "sh", "bash", "zsh",
		"php", "ruby", "rb", "swift", "kt", "kotlin",
		"rust", "rs", "scala", "r",
	}
	for i := 0; i < len(r.queryWords)-1; i++ {
		if r.queryWords[i+1] == "file" {
			word := r.queryWords[i]
			if slices.Contains(fileTypes, word) {
				entities = append(entities, Entity{
					Word:	word,
					Type:	EntityTypeFileType,
					Start:	i,
					End:	i,
				})
			}
		}
	}

	for i, word := range r.queryWords {
		cleanWord := strings.Trim(word, "\"',.;:")
		if strings.Contains(cleanWord, ".") {

			entities = append(entities, Entity{
				Word:	word,
				Type:	EntityTypeFileName,
				Start:	i,
				End:	i,
			})
		}
	}

	operations := []string{"create", "delete", "add", "remove", "make", "list", "read", "move", "relocate", "transfer", "mv", "rename", "renaming"}
	for i, word := range r.queryWords {
		for _, op := range operations {
			if word == op {
				entities = append(entities, Entity{
					Word:	word,
					Type:	EntityTypeOperation,
					Start:	i,
					End:	i,
				})
			}
		}
	}

	codeTypeKeywords := []string{"handler", "test", "config", "util", "helper", "service", "controller", "model", "middleware"}
	for i := 0; i < len(r.queryWords); i++ {
		word := r.queryWords[i]

		if i < len(r.queryWords)-1 && r.queryWords[i+1] == "code" {
			if slices.Contains(codeTypeKeywords, word) {

				entities = append(entities, Entity{
					Word:	word,
					Type:	EntityTypeCodeType,
					Start:	i,
					End:	i,
				})
				entities = append(entities, Entity{
					Word:	"code",
					Type:	EntityTypeCodeType,
					Start:	i + 1,
					End:	i + 1,
				})
			}
		}
	}

	featureKeywords := []string{
		"jwt", "auth", "authentication", "authorization",
		"logging", "logger", "log",
		"caching", "cache",
		"database", "db",
		"validation", "validator",
		"encryption", "decrypt",
		"oauth", "session",
		"cors", "csrf",
		"rate-limiting", "throttle",
		"websocket", "ws",
		"graphql", "rest",
		"metrics", "monitoring",
		"tracing", "telemetry",
	}
	for i, word := range r.queryWords {
		cleanWord := strings.Trim(word, "\"',.;:")
		if slices.Contains(featureKeywords, cleanWord) {
			entities = append(entities, Entity{
				Word:	word,
				Type:	EntityTypeFeatureName,
				Start:	i,
				End:	i,
			})
		}
	}

	componentKeywords := []string{
		"webserver", "server", "web-server",
		"api", "rest-api", "graphql-api",
		"service", "microservice",
		"handler", "controller",
		"middleware", "interceptor",
		"router", "route",
		"gateway", "proxy",
		"worker", "job",
		"queue", "stream",
		"database", "db", "store",
		"repository", "repo",
		"model", "entity",
		"client", "consumer",
		"producer", "publisher",
		"application", "app",
		"module", "component",
	}
	for i, word := range r.queryWords {
		cleanWord := strings.Trim(word, "\"',.;:")
		if slices.Contains(componentKeywords, cleanWord) {
			entities = append(entities, Entity{
				Word:	word,
				Type:	EntityTypeComponentName,
				Start:	i,
				End:	i,
			})

			if cleanWord == "handler" && i < len(r.queryWords)-1 {
				nextIdx := i + 1

				if strings.Trim(r.queryWords[nextIdx], "\"',.;:") == "named" && i < len(r.queryWords)-2 {
					nextIdx++
				}
				nextWord := strings.Trim(r.queryWords[nextIdx], "\"',.;:")
				if nextWord != "with" && nextWord != "at" && !slices.Contains(operations, nextWord) {
					entities = append(entities, Entity{
						Word:	r.queryWords[nextIdx],
						Type:	EntityTypeComponentName,
						Start:	nextIdx,
						End:	nextIdx,
					})
				}
			}
		}
	}

	for i, word := range r.queryWords {
		if (word == "url" || word == "path") && i < len(r.queryWords)-1 {
			entities = append(entities, Entity{
				Word:	r.queryWords[i+1],
				Type:	EntityTypeFileName,
				Start:	i + 1,
				End:	i + 1,
			})
		}
	}

	return entities
}

// GetEntityMap returns a map of word index to entity type for easy lookup
func (r *RuleBasedNER) GetEntityMap() map[int]EntityType {
	entities := r.ExtractEntities()
	entityMap := make(map[int]EntityType)

	for i := range r.queryWords {
		entityMap[i] = EntityTypeOutside
	}

	for _, entity := range entities {
		entityMap[entity.Start] = entity.Type
	}

	return entityMap
}

func GetProfile(name string) TrainingProfile {
	switch name {
	case "aggressive":
		return TrainingProfile{
			Name:	"Aggressive", LR: 2e-3, Lambda: 0.005,
			ClipThreshold:	2.0, HealThreshold: 0.70, WarmupSteps: 100,
		}
	case "stable":
		return TrainingProfile{
			Name:	"Stable", LR: 5e-4, Lambda: 0.01,
			ClipThreshold:	1.0, HealThreshold: 0.90, WarmupSteps: 500,
		}
	default:

		return TrainingProfile{
			Name:	"Standard", LR: 1e-3, Lambda: 0.01,
			ClipThreshold:	1.0, HealThreshold: 0.85, WarmupSteps: 200,
		}
	}
}

// NewOptimizer creates a new Adam optimizer.
// M/V moment tensors are allocated lazily on first Step() to avoid a
// burst memory spike (2× model params) that can trigger the OOM killer on
// memory-constrained hardware.
func NewOptimizer(parameters []*Tensor, learningRate float32, clipThreshold float32) Optimizer {
	o := &Adam{
		parameters:	parameters,
		learningRate:	learningRate,
		beta1:		0.9,
		beta2:		0.999,
		epsilon:	1e-8,
		t:		0,
		m:		make(map[*Tensor]*Tensor),
		v:		make(map[*Tensor]*Tensor),
		ClipThreshold:	clipThreshold,
		Lambda:		0.001,
		RouterLR:	learningRate * 15.0,
	}
	return o
}

// ClipGradients scales the gradients of all parameters if their total L2 norm exceeds ClipThreshold.
func (o *Adam) ClipGradients() {
	if o.ClipThreshold <= 0 {
		return
	}
	totalNorm := float32(0.0)
	for _, p := range o.parameters {
		if p.Grad != nil {
			for _, g := range p.Grad.Data {
				totalNorm += g * g
			}
		}
	}
	totalNorm = float32(math.Sqrt(float64(totalNorm)))
	if totalNorm > o.ClipThreshold {
		scale := o.ClipThreshold / totalNorm
		for _, p := range o.parameters {
			if p.Grad != nil {

				MulScalar(p.Grad.Data, scale, p.Grad.Data)
			}
		}
	}
}

// ResetStagnantMoments clears Adam moment vectors for weights identified as stagnant.
// This prevents the search history from damping the effect of a nudge (perturbation).
func (o *Adam) ResetStagnantMoments(t *Tensor) {
	if t.TimidMask() == nil {
		return
	}
	m, okM := o.m[t]
	v, okV := o.v[t]
	if !okM || !okV {
		return
	}
	for i, stagnant := range t.TimidMask() {
		if stagnant {
			m.Data[i] = 0
			v.Data[i] = 0
		}
	}
}

// Step performs a single optimization step, now with Timid-Aware LR boosting.
func (o *Adam) Step() {
	o.t++

	for _, p := range o.parameters {
		if p.Grad != nil {
			if _, ok := o.m[p]; !ok {
				o.m[p] = NewTensor(p.Shape, make([]float32, len(p.Data)), false)
				o.v[p] = NewTensor(p.Shape, make([]float32, len(p.Data)), false)
			}
		}
	}

	var wg sync.WaitGroup

	numWorkers := runtime.NumCPU()
	if numWorkers > 16 {
		numWorkers = 16
	}

	paramChan := make(chan *Tensor, len(o.parameters))
	for _, p := range o.parameters {
		if p.Grad != nil {
			paramChan <- p
		}
	}
	close(paramChan)

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for p := range paramChan {
				m := o.m[p].Data
				v := o.v[p].Data
				grad := p.Grad.Data
				param := p.Data

				lr := o.learningRate
				if p.IsRouter {
					lr = o.RouterLR
				}

				if p.TimidMask() != nil {
					b1t := float32(1.0 - math.Pow(float64(o.beta1), float64(o.t)))
					b2t := float32(1.0 - math.Pow(float64(o.beta2), float64(o.t)))

					mask := p.TimidMask()
					for i := range param {
						m[i] = o.beta1*m[i] + (1-o.beta1)*grad[i]
						v[i] = o.beta2*v[i] + (1-o.beta2)*grad[i]*grad[i]

						effectiveLR := lr
						if mask[i] {
							effectiveLR *= 3.0
						}

						mHat := m[i] / b1t
						vHat := v[i] / b2t
						denom := float32(math.Sqrt(float64(vHat))) + o.epsilon

						update := (mHat / denom) + (o.Lambda * param[i])
						param[i] -= effectiveLR * update
					}
				} else {
					AdamWUpdate(param, grad, m, v, lr, o.beta1, o.beta2, o.epsilon, o.Lambda, o.t)
				}

				if p.IsRouter {
					for i := range param {
						if param[i] > 2.5 {
							param[i] = 2.5
						}
						if param[i] < -2.5 {
							param[i] = -2.5
						}
					}
				}
			}
		}()
	}
	wg.Wait()
}

// ZeroGrad resets the gradients of all parameters in parallel.
func (o *Adam) ZeroGrad() {
	var wg sync.WaitGroup
	numWorkers := runtime.NumCPU()
	if numWorkers > 16 {
		numWorkers = 16
	}

	workCh := make(chan *Tensor, len(o.parameters))
	for _, p := range o.parameters {
		workCh <- p
	}
	close(workCh)

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for p := range workCh {
				p.ZeroGrad()
			}
		}()
	}
	wg.Wait()
}

func (o *Adam) SetLearningRate(lr float32) {
	o.learningRate = lr
	o.RouterLR = lr * 15.0
}

// GetLearningRate returns the current learning rate
func (o *Adam) GetLearningRate() float32 {
	return o.learningRate
}

// SetRouterLR updates the router-specific learning rate
func (o *Adam) SetRouterLR(lr float32) {
	o.RouterLR = lr
}

// GetRouterLR returns the current router learning rate
func (o *Adam) GetRouterLR() float32 {
	return o.RouterLR
}

type CoolingOptimizer struct {
	Base		Optimizer	// Your SIMD AdamW / SGD
	Cooldown	int		// Remaining steps in cooldown
	IsActive	bool
	OriginalLR	float32	// To store where we should be post-recovery
}

// Step executes the base optimizer but overrides LR if cooling
func (o *CoolingOptimizer) Step() {
	if o.IsActive {
		o.Cooldown--
		if o.Cooldown <= 0 {
			o.IsActive = false
			fmt.Printf("❄️ Recovery period over. Experts stabilized. Resuming LR: %.6f\n", o.OriginalLR)
			o.Base.SetLearningRate(o.OriginalLR)
		}
	}
	o.Base.Step()
}

// ZeroGrad resets the gradients of all parameters.
func (o *CoolingOptimizer) ZeroGrad() {
	o.Base.ZeroGrad()
}

// ClipGradients scales the gradients of all parameters.
func (o *CoolingOptimizer) ClipGradients() {
	o.Base.ClipGradients()
}

// SetLearningRate updates the learning rate of the optimizer
func (o *CoolingOptimizer) SetLearningRate(lr float32) {
	if o.IsActive {

		o.OriginalLR = lr
	} else {
		o.Base.SetLearningRate(lr)
	}
}

// GetLearningRate returns the current learning rate
func (o *CoolingOptimizer) GetLearningRate() float32 {
	return o.Base.GetLearningRate()
}

// ResetStagnantMoments delegates to the base optimizer.
func (o *CoolingOptimizer) ResetStagnantMoments(t *Tensor) {
	o.Base.ResetStagnantMoments(t)
}

// Trigger enters the cooling state
func (o *CoolingOptimizer) Trigger(steps int, reduction float32) {
	if !o.IsActive {
		o.OriginalLR = o.Base.GetLearningRate()
	}

	o.IsActive = true
	o.Cooldown = steps

	current := o.Base.GetLearningRate()
	o.Base.SetLearningRate(current * reduction)
	fmt.Printf("📉 Circuit Breaker: Cooling for %d steps at LR %f (Was: %f)\n", steps, current*reduction, current)
}

func CreatePhraseTagVocab(trainingData []tag.Tag) map[string]int {
	phraseTagVocab := make(map[string]int)
	index := 0

	for _, taggedSentence := range trainingData {
		for _, phraseTag := range taggedSentence.PhraseTag {
			if _, ok := phraseTagVocab[phraseTag]; !ok {
				phraseTagVocab[phraseTag] = index
				index++
			}
		}
	}

	return phraseTagVocab
}

func IndexToPhraseTag(phraseTagVocab map[string]int, predictedTagIndex int) (string, bool) {
	for tag, index := range phraseTagVocab {
		if index == predictedTagIndex {
			return tag, true
		}
	}
	return "", false
}

// Forward pass https://wiki.pathmind.com/neural-network
func ForwardPassPhrase(n *nnu.SimpleNN, inputs []float64) []float64 {

	hidden := make([]float64, n.HiddenSize)

	for i := range hidden {

		sum := 0.0

		for j := range inputs {

			sum += n.WeightsIH[i][j] * inputs[j]
		}

		hidden[i] = n.Sigmoid(sum)
	}

	output := make([]float64, n.OutputSize)

	for i := range output {

		sum := 0.0

		for j := range hidden {

			sum += n.WeightsHO[i][j] * hidden[j]
		}

		output[i] = n.Sigmoid(sum)
	}

	return output
}

func PredictPhraseTags(nn *nnu.SimpleNN, inputs []float64, phraseTagVocab map[string]int, predictedPhraseTags []string, predictedTagIndex int) []string {

	if predictedTagIndex != -1 {
		predictedTagPhrase, ok := IndexToPhraseTag(phraseTagVocab, predictedTagIndex)
		if !ok {
			fmt.Printf("Phrase tag index %d not found in vocabulary\n", predictedTagIndex)
			predictedPhraseTags = append(predictedPhraseTags, "O")
		}
		predictedPhraseTags = append(predictedPhraseTags, predictedTagPhrase)

	} else {
		predictedPhraseTags = append(predictedPhraseTags, "O")
		fmt.Printf("predictedOutput is empty or length 0\n")
	}

	return predictedPhraseTags
}

// Forward pass https://wiki.pathmind.com/neural-network
func ForwardPassPos(n *nnu.SimpleNN, inputs []float64) []float64 {

	if n.WeightsIH == nil || len(n.WeightsIH) == 0 || len(inputs) == 0 {
		fmt.Printf("n.WeightsIH is nil or empty. len(n.WeightsIH): %d, n.InputSize: %d\n", len(n.WeightsIH), n.InputSize)

		return []float64{}

	}

	hidden := make([]float64, n.HiddenSize)

	for i := range hidden {

		sum := 0.0

		for j := range inputs {

			sum += n.WeightsIH[i][j] * inputs[j]
		}

		hidden[i] = n.Sigmoid(sum)
	}

	output := make([]float64, n.OutputSize)

	for i := range output {

		sum := 0.0

		for j := range hidden {

			sum += n.WeightsHO[i][j] * hidden[j]
		}

		output[i] = n.Sigmoid(sum)
	}

	return output
}

