// SetupVocabulary attempts to load a vocabulary from vocabPath, and if it fails,
// builds a new one from the provided dataPaths.
func SetupVocabulary(vocabPath string, dataPaths []string) (*mainvocab.Vocabulary, error) {
	vocab, err := mainvocab.LoadVocabulary(vocabPath)
	if err == nil {
		log.Printf("Loaded vocabulary from %s", vocabPath)
		return vocab, nil
	}

	log.Printf("Could not load vocabulary from %s, building new one.", vocabPath)
	if len(dataPaths) < 2 {
		return nil, fmt.Errorf("at least two data paths are required to build vocabulary")
	}
	vocab = BuildVocabulary(dataPaths[0], dataPaths[1])
	if vocab == nil {
		return nil, fmt.Errorf("failed to build vocabulary")
	}

	if err := vocab.Save(vocabPath); err != nil {
		return nil, fmt.Errorf("failed to save vocabulary: %w", err)
	}
	log.Printf("Saved new vocabulary to %s", vocabPath)

	return vocab, nil
}

// BuildVocabulary builds a vocabulary from the provided training data file and additional software commands data.
func BuildVocabulary(trainingDataPath, softwareCommandsPath string) *mainvocab.Vocabulary {
	wordSet := make(map[string]bool)

	file, err := os.Open(trainingDataPath)
	if err != nil {
		log.Printf("Error opening training data file: %v", err)
		return nil
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	queryRe := regexp.MustCompile(`^Query: "(.*)"$`)
	intentRe := regexp.MustCompile(`^Intent: (.*)$`)

	for scanner.Scan() {
		line := scanner.Text()
		if matches := queryRe.FindStringSubmatch(line); matches != nil {
			tokenizeAndAddWords(matches[1], wordSet)
		} else if matches := intentRe.FindStringSubmatch(line); matches != nil {
			tokenizeAndAddWords(matches[1], wordSet)
		}
	}

	if err := scanner.Err(); err != nil {
		log.Printf("Error reading training data file: %v", err)
		return nil
	}

	addWordsFromSoftwareCommands(softwareCommandsPath, wordSet)

	words := make([]string, 0, len(wordSet))
	for word := range wordSet {
		words = append(words, word)
	}

	vocab := mainvocab.NewVocabulary()
	for _, word := range words {
		vocab.AddToken(word)
	}

	log.Printf("Built vocabulary with %d words", len(vocab.TokenToWord))
	return vocab
}

// tokenizeAndAddWords tokenizes the input text and adds the tokens to the word set.
func tokenizeAndAddWords(text string, wordSet map[string]bool) {

	tokens := strings.FieldsSeq(text)
	for token := range tokens {
		cleanedToken := strings.Trim(token, ".,!?\"'()[]{}:;`")
		if cleanedToken != "" {
			wordSet[cleanedToken] = true
		}
	}
}

// parseTrainingData reads and parses the training data file into query-intent pairs.
func parseTrainingData(filePath string) ([]struct {
	Query	string
	Intent	string
}, error) {
	log.Printf("Parsing training data from %s", filePath)
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("could not open training data file: %w", err)
	}
	defer file.Close()

	var data []struct {
		Query	string
		Intent	string
	}

	scanner := bufio.NewScanner(file)
	queryRe := regexp.MustCompile(`^Query: "(.*)"$`)
	intentRe := regexp.MustCompile(`^Intent: (.*)$`)

	currentQuery := ""
	currentIntent := ""

	log.Println("Starting to parse training data...")
	for scanner.Scan() {
		line := scanner.Text()
		log.Printf("Read line: %s", line)

		if matches := queryRe.FindStringSubmatch(line); len(matches) > 1 {

			if currentQuery != "" && currentIntent != "" {
				data = append(data, struct {
					Query	string
					Intent	string
				}{Query: currentQuery, Intent: currentIntent})
				log.Printf("Appended training example: Query=\"%s\", Intent=\"%s\"", currentQuery, currentIntent)
			}
			currentQuery = matches[1]
			currentIntent = ""
			log.Printf("Matched Query: %s", currentQuery)
		} else if matches := intentRe.FindStringSubmatch(line); len(matches) > 1 {
			currentIntent = matches[1]
			log.Printf("Matched Intent: %s", currentIntent)

			if currentQuery != "" && currentIntent != "" {
				data = append(data, struct {
					Query	string
					Intent	string
				}{Query: currentQuery, Intent: currentIntent})
				log.Printf("Appended training example: Query=\"%s\", Intent=\"%s\"", currentQuery, currentIntent)
				currentQuery = ""
				currentIntent = ""
			}
		} else if line == "" {
			log.Println("Empty line encountered.")

		}
	}

	if currentQuery != "" && currentIntent != "" {
		data = append(data, struct {
			Query	string
			Intent	string
		}{Query: currentQuery, Intent: currentIntent})
		log.Printf("Appended final training example: Query=\"%s\", Intent=\"%s\"", currentQuery, currentIntent)
	}

	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("error reading training data file: %w", err)
	}

	log.Printf("Finished parsing training data. Total examples: %d", len(data))
	return data, nil
}

// addWordsFromSoftwareCommands extracts words from the software commands JSON data.
func addWordsFromSoftwareCommands(filePath string, wordSet map[string]bool) {
	log.Printf("Expanding vocabulary with words from %s", filePath)
	file, err := os.Open(filePath)
	if err != nil {
		log.Printf("Warning: could not open software commands data to expand vocabulary: %v", err)
		return
	}
	defer file.Close()

	var data []struct {
		Query		string
		Intent		string
		Entities	map[string]string
	}
	if err := json.NewDecoder(file).Decode(&data); err != nil {
		log.Printf("Warning: could not decode software commands data from %s: %v", filePath, err)
		return
	}

	for _, entry := range data {
		tokenizeAndAddWords(entry.Query, wordSet)
		tokenizeAndAddWords(entry.Intent, wordSet)
		for _, value := range entry.Entities {
			tokenizeAndAddWords(value, wordSet)
		}
	}
}

func CalculateError(targetTag string, outputs []float64, trainingData []tag.Tag, nn *nnu.SimpleNN) ([]float64, map[string]int, map[string]int, map[string]int, map[string]int) {
	targetOutput := make([]float64, nn.OutputSize)
	vocabularies := []func([]tag.Tag) map[string]int{
		pos.CreatePosTagVocab,
		ner.CreateTagVocabNer,
		phrase.CreatePhraseTagVocab,
		dr.CreateDRTagVocab,
	}
	vocabs := make([]map[string]int, len(vocabularies))

	for i, createVocab := range vocabularies {
		vocabs[i] = createVocab(trainingData)
		tagIndex, ok := vocabs[i][targetTag]
		if ok && tagIndex < nn.OutputSize {
			targetOutput[tagIndex] = 1
		}
	}

	errors := make([]float64, nn.OutputSize)
	for i := range errors {
		errors[i] = targetOutput[i] - outputs[i]
	}
	return errors, vocabs[0], vocabs[1], vocabs[2], vocabs[3]
}

// Function to calculate accuracy
func CalculateAccuracy(nn *nnu.SimpleNN, trainingData []tag.Tag, tokenVocab map[string]int, posTagVocab map[string]int, nerTagVocab map[string]int, phraseTagVocab map[string]int, drTagVocab map[string]int) (float64, float64, float64, float64) {
	var (
		poscorrectPredictions		= 0
		nercorrectPredictions		= 0
		phrasecorrectPredictions	= 0
		drcorrectPredictions		= 0
		postotalPredictions		= 0
		nertotalPredictions		= 0
		phrasetotalPredictions		= 0
		drtotalPredictions		= 0
	)

	for _, taggedSentence := range trainingData {
		for i := range taggedSentence.Tokens {
			inputs := make([]float64, nn.InputSize)

			for j := 0; j < nn.InputSize; j++ {
				inputs[j] = 0
			}
			tokenIndex, ok := tokenVocab[taggedSentence.Tokens[i]]
			if ok {
				inputs[tokenIndex] = 1
			} else {
				if _, ok := tokenVocab["UNK"]; ok {
					inputs[tokenVocab["UNK"]] = 1
				} else {

					log.Printf("CalculateAccuracy: Error: UNK token is not in the vocabulary: %s", taggedSentence.Tokens[i])
					continue
				}
			}

			predictedPosTag, predictedNerTag, predictedPhraseTag, predictedDRTag, _ := predict.PredictTag(nn, inputs, posTagVocab, nerTagVocab, phraseTagVocab, drTagVocab)

			if predictedPosTag == taggedSentence.PosTag[i] {
				poscorrectPredictions++
			}
			if predictedNerTag == taggedSentence.NerTag[i] {
				nercorrectPredictions++
			}
			if predictedPhraseTag == taggedSentence.PhraseTag[i] {
				phrasecorrectPredictions++
			}
			if i < len(taggedSentence.Dependencies) {
				if len(taggedSentence.Dependencies) >= len(taggedSentence.Tokens) {
					if predictedDRTag == taggedSentence.Dependencies[i].Dep {
						drcorrectPredictions++
					} else {

					}
				}
			}

			postotalPredictions++
			nertotalPredictions++
			phrasetotalPredictions++
			drtotalPredictions++
		}
	}

	pacc := float64(poscorrectPredictions) / float64(postotalPredictions)
	nacc := float64(nercorrectPredictions) / float64(nertotalPredictions)
	phacc := float64(phrasecorrectPredictions) / float64(phrasetotalPredictions)
	dracc := float64(drcorrectPredictions) / float64(drtotalPredictions)

	return pacc, nacc, phacc, dracc
}

type Entity struct {
	Type	string
	Value	string
}

// NewConversationContext initializes a new ConversationContext with a specified history size.
func NewConversationContext(maxTurns int) *ConversationContext {
	return &ConversationContext{
		MaxTurns:		maxTurns,
		TurnHistory:		make([]string, 0, maxTurns),
		ResponseHistory:	make([]string, 0, maxTurns),
		LastIntents:		make([]string, 0, maxTurns),
		LastEntities:		make([][]Entity, 0, maxTurns),
	}
}

// AddTurn adds the current turn's information to the conversation context.
func (cc *ConversationContext) AddTurn(intent string, entities []Entity, rawText string) {

	cc.CurrentIntent = intent
	cc.CurrentEntities = entities

	cc.TurnHistory = append(cc.TurnHistory, rawText)
	cc.LastIntents = append(cc.LastIntents, intent)
	cc.LastEntities = append(cc.LastEntities, entities)

	if len(cc.TurnHistory) > cc.MaxTurns {
		cc.TurnHistory = cc.TurnHistory[1:]
		cc.LastIntents = cc.LastIntents[1:]
		cc.LastEntities = cc.LastEntities[1:]
	}
}

// AddResponse adds the system's response to the conversation context.
func (cc *ConversationContext) AddResponse(response string) {
	cc.ResponseHistory = append(cc.ResponseHistory, response)
	if len(cc.ResponseHistory) > cc.MaxTurns {
		cc.ResponseHistory = cc.ResponseHistory[1:]
	}
}

// GetConversationHistory returns the full conversation history formatted as a string.
func (cc *ConversationContext) GetConversationHistory() string {
	var sb strings.Builder
	turns := len(cc.TurnHistory)
	responses := len(cc.ResponseHistory)
	maxLen := turns
	if responses > maxLen {
		maxLen = responses
	}

	for i := 0; i < maxLen; i++ {
		if i < turns {
			sb.WriteString("Human: " + cc.TurnHistory[i] + "\n")
		}
		if i < responses {
			sb.WriteString("AI: " + cc.ResponseHistory[i] + "\n")
		}
	}
	return sb.String()
}

// GetLastIntent retrieves the most recent intent from the history.
func (cc *ConversationContext) GetLastIntent() string {
	if len(cc.LastIntents) > 0 {
		return cc.LastIntents[len(cc.LastIntents)-1]
	}
	return ""
}

// GetLastEntities retrieves the most recent set of entities from the history.
func (cc *ConversationContext) GetLastEntities() []Entity {
	if len(cc.LastEntities) > 0 {
		return cc.LastEntities[len(cc.LastEntities)-1]
	}
	return nil
}

// GetLastResponse retrieves the most recent system response from the history.
func (cc *ConversationContext) GetLastResponse() string {
	if len(cc.ResponseHistory) > 0 {
		return cc.ResponseHistory[len(cc.ResponseHistory)-1]
	}
	return ""
}

// ResolveCoReference attempts to resolve simple pronominal co-references in the input text.
// For example, if the last command was "create handler login" and the current command is "delete it",
// this function should resolve "it" to "login".
func (cc *ConversationContext) ResolveCoReference(inputText string) string {
	tokens := strings.Fields(inputText)
	resolvedTokens := make([]string, len(tokens))
	copy(resolvedTokens, tokens)

	pronouns := map[string]bool{
		"it":	true,
		"that":	true,
		"this":	true,
		"them":	true,
	}

	for i, token := range tokens {
		lowerToken := strings.ToLower(token)
		if pronouns[lowerToken] {

			antecedent := cc.findAntecedent()
			if antecedent != "" {
				fmt.Printf("Context: Resolved pronoun '%s' to '%s'\n", token, antecedent)
				resolvedTokens[i] = antecedent

			}
		}
	}

	return strings.Join(resolvedTokens, " ")
}

// findAntecedent searches backwards in the context for the most likely entity.
func (cc *ConversationContext) findAntecedent() string {

	for i := len(cc.LastEntities) - 1; i >= 0; i-- {
		entities := cc.LastEntities[i]

		// Prioritize specific, named entities over generic component types.
		var bestCandidate string

		for _, entity := range entities {

			switch entity.Type {
			case "handler_name", "database_name", "project_name", "file", "folder", "name", "FILENAME", "NAME":
				return entity.Value
			case "component", "feature":
				if bestCandidate == "" {
					bestCandidate = entity.Value
				}
			}
		}

		if bestCandidate != "" {
			return bestCandidate
		}
	}
	return ""
}

