// ToVocabulary converts the Word2Vec vocabulary into a standard Vocabulary instance.
func (sw2v *SimpleWord2Vec) ToVocabulary() *vocab.Vocabulary {
	v := vocab.NewVocabulary()

	for i := 0; i < sw2v.VocabSize; i++ {
		if word, ok := sw2v.IndexToWord[i]; ok {
			v.AddToken(word)
		}
	}
	return v
}

// SyncF32 populates WordVectorsF32 from WordVectors.
func (sw2v *SimpleWord2Vec) SyncF32() {
	if sw2v.WordVectors == nil {
		return
	}
	sw2v.WordVectorsF32 = make(map[int][]float32)
	for idx, vec := range sw2v.WordVectors {
		f32vec := make([]float32, len(vec))
		for i, v := range vec {
			f32vec[i] = float32(v)
		}
		sw2v.WordVectorsF32[idx] = f32vec
	}
}

// convertToMap converts WordVectors to a map[string][]float64.
func ConvertToMap(wv WordVectors, vocab map[string]int) map[string][]float64 {
	result := make(map[string][]float64)
	for word, index := range vocab {
		result[word] = wv[index]
	}
	return result
}

// ReadTrainingData reads the training data from a plain text file, one sentence per line.
func ReadTrainingData(filePath string) ([]string, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("error opening training data file: %w", err)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var sentences []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if len(line) > 0 {
			sentences = append(sentences, line)
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("error reading training data file: %w", err)
	}

	return sentences, nil
}

func (sw2v *SimpleWord2Vec) TrainSentenceContext(sentences []string) map[string][]float64 {
	for _, sentence := range sentences {
		words := strings.Fields(sentence)
		context := make([]float64, sw2v.VectorSize)

		for _, word := range words {
			wordIndex, ok := sw2v.Vocabulary[word]
			if !ok {

				wordIndex, ok = sw2v.Vocabulary[UNKToken]
				if !ok {
					fmt.Printf("Warning: Unknown word '%s' and no UNK token found\n", word)
					continue
				}
			}
			for i := 0; i < sw2v.VectorSize; i++ {
				context[i] += sw2v.WordVectors[wordIndex][i]
			}
		}
		sw2v.ContextEmbeddings[sentence] = context
	}

	return sw2v.ContextEmbeddings
}

// InitializeWeights initializes the weights and biases of the RNN.
func (sw2v *SimpleWord2Vec) InitializeWeights() {
	sw2v.Weights = make([][]float64, sw2v.HiddenSize)
	sw2v.Biases = make([][]float64, sw2v.HiddenSize)
	for i := 0; i < sw2v.HiddenSize; i++ {
		sw2v.Weights[i] = make([]float64, sw2v.VectorSize)
		sw2v.Biases[i] = make([]float64, 1)

		for j := 0; j < sw2v.VectorSize; j++ {
			sw2v.Weights[i][j] = rand.Float64()
		}

		for j := range 1 {
			sw2v.Biases[i][j] = rand.Float64()
		}
	}
}

// forwardPass performs the forward pass of the RNN.
func (sw2v *SimpleWord2Vec) ForwardPass(words []string) []float64 {
	hiddenState := make([]float64, sw2v.VectorSize)

	for _, word := range words {
		wordIndex, ok := sw2v.Vocabulary[word]
		if !ok {
			wordIndex, ok = sw2v.Vocabulary[UNKToken]
			if !ok {
				continue
			}
		}

		inputVector := sw2v.WordVectors[wordIndex]
		if inputVector == nil {
			continue
		}

		newHiddenState := make([]float64, sw2v.VectorSize)
		for i := 0; i < sw2v.VectorSize; i++ {
			weightedSum := 0.0
			iMod := i % sw2v.HiddenSize
			if sw2v.VectorSize == sw2v.HiddenSize {
				weightedSum += sw2v.Weights[iMod][i] * inputVector[i]
			} else {
				for j := range inputVector {
					if iMod == j%sw2v.HiddenSize {
						weightedSum += sw2v.Weights[iMod][j] * inputVector[j]
					}
				}
			}
			weightedSum += sw2v.Biases[iMod][0]
			weightedSum += hiddenState[i]

			newHiddenState[i] = math.Tanh(weightedSum)
		}
		hiddenState = newHiddenState
	}

	output := make([]float64, sw2v.VectorSize)
	copy(output, hiddenState)
	return output
}

// calculateLoss calculates the Mean Squared Error (MSE) loss.
func (sw2v *SimpleWord2Vec) CalculateLoss(output, context []float64) float64 {
	loss := 0.0
	for i := 0; i < sw2v.VectorSize; i++ {
		diff := output[i] - context[i]
		loss += diff * diff
	}
	loss /= float64(sw2v.VectorSize)
	return loss
}

// backpropagate performs backpropagation and updates weights and biases.
func (sw2v *SimpleWord2Vec) Backpropagate(output, context []float64, learningRate float64) {
	maxGrad := 1.0
	for i := 0; i < sw2v.HiddenSize; i++ {
		grad := output[i] - context[i]
		weightNorm := math.Abs(grad) * math.Sqrt(float64(sw2v.VectorSize))

		scale := 1.0
		if weightNorm > maxGrad {
			scale = maxGrad / weightNorm
		}

		scaledGrad := grad * scale
		sw2v.Weights[i][i] -= learningRate * scaledGrad
		sw2v.Biases[i][0] -= learningRate * grad
	}
}

// contains checks if a string slice contains a specific string.
func contains(slice []string, str string) bool {
	return slices.Contains(slice, str)
}

// Helper function to calculate the sum of squares of a slice
func sumOfSquares(slice []float64) float64 {
	sum := 0.0
	for _, val := range slice {
		sum += val * val
	}
	return sum
}

// getWordByIndex retrieves the word associated with the given index.
func (sw2v *SimpleWord2Vec) getWordByIndex(index int) string {
	return sw2v.IndexToWord[index]
}

// SaveModel saves the trained model to a GOB file.
func (sw2v *SimpleWord2Vec) SaveModel(filename string) error {
	file, err := os.Create(filename)
	if err != nil {
		return fmt.Errorf("error creating model file: %w", err)
	}
	defer file.Close()

	encoder := gob.NewEncoder(file)
	err = encoder.Encode(sw2v)
	if err != nil {
		return fmt.Errorf("error encoding model: %w", err)
	}

	return nil
}

// LoadModel loads a trained model from a GOB file.
func LoadModel(filename string) (*SimpleWord2Vec, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("error opening model file: %w", err)
	}
	defer file.Close()

	decoder := gob.NewDecoder(file)
	var sw2v SimpleWord2Vec
	err = decoder.Decode(&sw2v)
	if err != nil {
		return nil, fmt.Errorf("error decoding model: %w", err)
	}

	return &sw2v, nil
}

// Train implements a simplified Skip-gram model for training word embeddings.
func (sw2v *SimpleWord2Vec) Train(trainingData []string) {

	if sw2v.Epochs == 0 {
		sw2v.Epochs = 10
	}
	if sw2v.LearningRate == 0.0 {
		sw2v.LearningRate = 0.01
	}
	if sw2v.Window == 0 {
		sw2v.Window = 2
	}
	if sw2v.NegativeSamples == 0 {
		sw2v.NegativeSamples = 5
	}
	if sw2v.MinWordFrequency == 0 {
	}

	if sw2v.Vocabulary == nil {
		sw2v.Vocabulary = make(map[string]int)
		wordCounts := make(map[string]int)
		for _, sentence := range trainingData {
			words := strings.FieldsSeq(sentence)
			for word := range words {
				wordCounts[word]++
			}
		}

		filteredWords := make([]string, 0)
		for word, count := range wordCounts {
			if count >= sw2v.MinWordFrequency {
				filteredWords = append(filteredWords, word)
			}
		}

		sort.Strings(filteredWords)

		sw2v.Vocabulary[UNKToken] = 0
		sw2v.IndexToWord = make(map[int]string)
		sw2v.IndexToWord[0] = UNKToken
		wordCount := 1
		for _, word := range filteredWords {
			sw2v.Vocabulary[word] = wordCount
			sw2v.IndexToWord[wordCount] = word
			wordCount++
		}
		sw2v.VocabSize = wordCount
	}

	if sw2v.WordVectors == nil {
		sw2v.WordVectors = make(WordVectors)
		for _, index := range sw2v.Vocabulary {
			sw2v.WordVectors[index] = make([]float64, sw2v.VectorSize)
			for i := 0; i < sw2v.VectorSize; i++ {
				sw2v.WordVectors[index][i] = rand.Float64()
			}

			if index >= sw2v.VocabSize {
				sw2v.VocabSize = index + 1
			}
		}
	}

	if sw2v.NgramVectors == nil {
		sw2v.NgramVectors = make(map[string][]float64)
	}
	if sw2v.NgramSize == 0 {
		sw2v.NgramSize = 3
	}
	sw2v.InitializeWeights()

	wordIndices := make([]int, sw2v.VocabSize)
	for i := range wordIndices {
		wordIndices[i] = i
	}

	tokenizedTrainingData := make([][]string, len(trainingData))
	for i, sentence := range trainingData {
		tokenizedTrainingData[i] = strings.Fields(sentence)
	}

	totalSents := len(tokenizedTrainingData)
	for i := 0; i < sw2v.Epochs; i++ {
		//totalLoss = 0
		var learningRate = sw2v.LearningRate - sw2v.LearningRate*0.99*float64(i)/float64(sw2v.Epochs)

		for sIdx, words := range tokenizedTrainingData {
			if sIdx%500 == 0 && sIdx > 0 {
				fmt.Printf("Epoch %d/%d: Processed %d/%d sentences (%.2f%%)\n", i+1, sw2v.Epochs, sIdx, totalSents, float64(sIdx)/float64(totalSents)*100.0)
			}
			if sw2v.UseCBOW {
				for j, targetWord := range words {
					_, ok := sw2v.Vocabulary[targetWord]
					if !ok {
						_ = sw2v.Vocabulary[UNKToken]
					}
					contextWords := make([]string, 0)
					for k := -sw2v.Window; k <= sw2v.Window; k++ {
						if k == 0 || j+k < 0 || j+k >= len(words) {
							continue
						}
						contextWords = append(contextWords, words[j+k])
					}
					if len(contextWords) == 0 {
						continue
					}
					contextVector := make([]float64, sw2v.VectorSize)
					for _, contextWord := range contextWords {
						contextIndex, ok := sw2v.Vocabulary[contextWord]
						if !ok {
							contextIndex = sw2v.Vocabulary[UNKToken]
						}
						for index, value := range sw2v.WordVectors[contextIndex] {
							contextVector[index] += value
						}
					}

					output := sw2v.ForwardPass([]string{targetWord})
					sw2v.Backpropagate(output, contextVector, learningRate)

					for n := 0; n < sw2v.NegativeSamples; n++ {
						negIndex := wordIndices[rand.IntN(len(wordIndices))]
						if contains(contextWords, sw2v.getWordByIndex(negIndex)) {
							continue
						}
						sw2v.Backpropagate(output, sw2v.WordVectors[negIndex], learningRate)
					}
				}
			} else {
				for j, targetWord := range words {
					_, ok := sw2v.Vocabulary[targetWord]
					if !ok {
						_ = sw2v.Vocabulary[UNKToken]
					}
					for k := -sw2v.Window; k <= sw2v.Window; k++ {
						if k == 0 || j+k < 0 || j+k >= len(words) {
							continue
						}
						contextWord := words[j+k]
						contextIndex, ok := sw2v.Vocabulary[contextWord]
						if !ok {
							contextIndex = sw2v.Vocabulary[UNKToken]
						}
						output := sw2v.ForwardPass([]string{targetWord})
						sw2v.Backpropagate(output, sw2v.WordVectors[contextIndex], learningRate)

						for n := 0; n < sw2v.NegativeSamples; n++ {
							negIndex := wordIndices[rand.IntN(len(wordIndices))]
							if negIndex == contextIndex {
								continue
							}
							if sw2v.WordVectors[negIndex] == nil {
								sw2v.WordVectors[negIndex] = make([]float64, sw2v.VectorSize)
							}
							sw2v.Backpropagate(output, sw2v.WordVectors[negIndex], learningRate)
						}
					}
				}
			}
		}
		fmt.Printf("\rEpoch %d/%d: Completed %d/%d sentences (100.00%%)\n", i+1, sw2v.Epochs, totalSents, totalSents)

	}
}

// TrainWord2VecModel initializes, trains, and saves a SimpleWord2Vec model.
func TrainWord2VecModel(trainingDataPath, modelSavePath string, vectorSize, epochs, window, negativeSamples, minWordFrequency int, useCBOW bool) (*SimpleWord2Vec, error) {

	sw2v := &SimpleWord2Vec{
		VectorSize:		vectorSize,
		HiddenSize:		vectorSize,
		LearningRate:		0.01,
		Window:			window,
		Epochs:			epochs,
		NegativeSamples:	negativeSamples,
		UseCBOW:		useCBOW,
		MinWordFrequency:	minWordFrequency,
	}

	trainingData, err := ReadTrainingData(trainingDataPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read word2vec training data: %w", err)
	}

	fmt.Printf("Starting Word2Vec model training for %d epochs...\n", epochs)
	sw2v.Train(trainingData)
	fmt.Println("Word2Vec model training finished.")

	if err := sw2v.SaveModel(modelSavePath); err != nil {
		return nil, fmt.Errorf("failed to save word2vec model: %w", err)
	}
	fmt.Printf("Word2Vec model saved to %s\n", modelSavePath)

	return sw2v, nil
}

type Parser struct {
	// Add necessary components like tokenizer, POS tagger, NER, etc.
	ruleEngine *ParsingRuleEngine
}

// NewParser creates a new Parser.
func NewParser() *Parser {
	re := NewParsingRuleEngine()
	re.RegisterDefaultParsingRules()
	return &Parser{
		ruleEngine: re,
	}
}

// Parse takes a natural language query and returns a structured workflow.
func (p *Parser) Parse(query string) (*workflow.Workflow, error) {

	tokens := p.tokenize(query)

	posTags := p.posTag(tokens)

	nerTags := p.nerTag(tokens, posTags)

	log.Printf("Tokens: %v", tokens)
	log.Printf("POS Tags: %v", posTags)
	log.Printf("NER Tags: %v", nerTags)

	semanticOutput, err := p.mapToSemanticOutput(tokens, posTags, nerTags)
	if err != nil {
		return nil, fmt.Errorf("failed to map to semantic output: %w", err)
	}

	if err := semantic.ValidateAndInferProperties(semanticOutput); err != nil {
		return nil, fmt.Errorf("semantic validation and inference failed: %w", err)
	}

	wf, err := workflow.GenerateWorkflow(semanticOutput)
	if err != nil {
		return nil, fmt.Errorf("failed to generate workflow: %w", err)
	}

	return wf, nil
}

func (p *Parser) tokenize(query string) []string {
	return tokenizer.Tokenize(query)
}

func (p *Parser) posTag(tokens []string) []string {
	return postagger.TagTokens(tokens)
}

func (p *Parser) nerTag(tokens []string, posTags []string) []string {
	return nertagger.TagTokens(tokens, posTags)
}

func (p *Parser) mapToSemanticOutput(tokens, posTags, nerTags []string) (*semantic.SemanticOutput, error) {
	output := &semantic.SemanticOutput{}
	output.Context.UserRole = ""

	var folderResource *semantic.Resource
	var webserverResource *semantic.Resource
	var fileResource *semantic.Resource
	var lastFolderResource *semantic.Resource

	// lastObjectType is no longer needed as rules will directly set resource types
	// var lastObjectType string
	var lastCreatedResourceName string
	log.Print(lastCreatedResourceName)
	var lastProcessedResource *semantic.Resource	// Track the actual resource object

	expectingDependencyTarget := false
	expectingDependencySource := false
	dependencyType := ""

	for i := 0; i < len(tokens); i++ {
		applied, tokensConsumed, err := p.ruleEngine.ApplyRules(tokens, posTags, nerTags, i, output,
			&fileResource, &folderResource, &webserverResource, &lastFolderResource,
			&lastProcessedResource, &expectingDependencyTarget, &expectingDependencySource, &dependencyType)
		if err != nil {
			return nil, err
		}
		if applied {
			i += tokensConsumed - 1
			continue
		}

	}

	log.Printf("Before final target assignment, output.TargetResource: %+v", output.TargetResource)

	var target *semantic.Resource
	if fileResource != nil {
		target = fileResource
	} else if folderResource != nil {
		target = folderResource
	} else if webserverResource != nil {
		target = webserverResource
	}
	output.TargetResource = target

	log.Printf("SemanticOutput TargetResource Type before returning: %s", output.TargetResource.Type)
	return output, nil
}

// Helper to get resource name from token and type
func getResourceName(tokens []string, nerTags []string, idx int, objType string) string {
	if idx < len(tokens) {

		if nerTags[idx] == "NAME" {
			return tokens[idx]
		}

		if idx+1 < len(tokens) && nerTags[idx+1] == "NAME" {
			return tokens[idx+1]
		}

		if nerTags[idx] == "OBJECT_TYPE" && idx+1 < len(tokens) {

			if nerTags[idx+1] != "OBJECT_TYPE" && nerTags[idx+1] != "PREPOSITION" && nerTags[idx+1] != "DETERMINER" {
				return tokens[idx+1]
			}
		}
	}
	return ""
}

type ParsingRuleEngine struct {
	rules []ParsingRule
}

// NewParsingRuleEngine creates a new ParsingRuleEngine.
func NewParsingRuleEngine() *ParsingRuleEngine {
	return &ParsingRuleEngine{}
}

// RegisterRule adds a new parsing rule to the engine.
func (pre *ParsingRuleEngine) RegisterRule(rule ParsingRule) {
	pre.rules = append(pre.rules, rule)
}

// ApplyRules attempts to apply the registered rules to the given tokens and tags.
// It returns true if a rule was applied, the number of tokens consumed by the rule, and an error if one occurred.
func (pre *ParsingRuleEngine) ApplyRules(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
	fileResource **semantic.Resource, folderResource **semantic.Resource,
	webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
	lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
	expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
	for _, rule := range pre.rules {
		if pre.matchPattern(tokens, nerTags, posTags, i, rule.Pattern) {
			applied, tokensConsumed, err := rule.Action(tokens, posTags, nerTags, i, output,
				fileResource, folderResource, webserverResource, lastFolderResource,
				lastProcessedResource, expectingDependencyTarget, expectingDependencySource, dependencyType)
			if err != nil {
				return false, 0, fmt.Errorf("rule '%s' failed: %w", rule.Name, err)
			}
			if applied {
				return true, tokensConsumed, nil
			}
		}
	}
	return false, 0, nil
}

// matchPattern checks if the given NER tags (or tokens) match the rule's pattern starting from index i.
func (pre *ParsingRuleEngine) matchPattern(tokens, nerTags, posTags []string, i int, pattern []string) bool {
	if len(pattern) == 0 {
		return false
	}
	if i+len(pattern) > len(tokens) {
		return false
	}

	for j, p := range pattern {

		if nerTags[i+j] != p && posTags[i+j] != p && tokens[i+j] != p {
			return false
		}
	}
	return true
}

// RegisterDefaultParsingRules registers a set of default parsing rules.
func (pre *ParsingRuleEngine) RegisterDefaultParsingRules() {

	pre.RegisterRule(ParsingRule{
		Name:		"AddCommand",
		Pattern:	[]string{"VB"},
		Action: func(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
			fileResource **semantic.Resource, folderResource **semantic.Resource,
			webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
			lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
			expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
			if strings.ToLower(tokens[i]) == "add" || strings.ToLower(tokens[i]) == "make" || strings.ToLower(tokens[i]) == "create" {
				output.Operation = "CREATE"
				return true, 1, nil
			}
			return false, 0, nil
		},
	})

	pre.RegisterRule(ParsingRule{
		Name:		"MoveCommand",
		Pattern:	[]string{"COMMAND", "NAME", "PREPOSITION", "NAME"},
		Action: func(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
			fileResource **semantic.Resource, folderResource **semantic.Resource,
			webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
			lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
			expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
			if strings.ToLower(tokens[i]) == "move" || strings.ToLower(tokens[i]) == "mv" {
				sourcePath := tokens[i+1]
				destinationPath := tokens[i+3]

				*fileResource = &semantic.Resource{
					Type:		"Filesystem::File",
					Name:		sourcePath,
					Destination:	destinationPath,
				}
				output.TargetResource = *fileResource
				output.Operation = "MOVE"
				log.Printf("MoveCommand rule applied. Source: %s, Destination: %s", sourcePath, destinationPath)
				return true, 4, nil
			}
			return false, 0, nil
		},
	})

	pre.RegisterRule(ParsingRule{
		Name:		"CreateFolder",
		Pattern:	[]string{"OBJECT_TYPE", "NN"},
		Action: func(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
			fileResource **semantic.Resource, folderResource **semantic.Resource,
			webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
			lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
			expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
			if strings.ToLower(tokens[i]) == "folder" {
				folderName := getResourceName(tokens, nerTags, i, "folder")
				if folderName != "" {
					*folderResource = &semantic.Resource{Type: "Filesystem::Folder", Name: folderName, Properties: map[string]any{"permissions": 0755}}
					*lastFolderResource = *folderResource
					*folderResource = &semantic.Resource{Type: "Filesystem::Folder", Name: folderName, Properties: map[string]any{"permissions": 0755}}
					*lastFolderResource = *folderResource
					output.TargetResource = *folderResource
					log.Printf("CreateFolder rule applied. folderName: %s, folderResource: %+v", folderName, **folderResource)
					return true, 2, nil
				}
			}
			return false, 0, nil
		},
	})

	pre.RegisterRule(ParsingRule{
		Name:		"CreateFile",
		Pattern:	[]string{"OBJECT_TYPE", "NAME"},
		Action: func(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
			fileResource **semantic.Resource, folderResource **semantic.Resource,
			webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
			lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
			expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
			if strings.ToLower(tokens[i]) == "file" {
				fileName := getResourceName(tokens, nerTags, i, "file")
				if fileName != "" {
					log.Printf("Inside CreateFile rule: fileName=%s", fileName)
					*fileResource = &semantic.Resource{Type: "Filesystem::File", Name: fileName}
					log.Printf("Inside CreateFile rule: *fileResource.Type=%s", (*fileResource).Type)
					output.TargetResource = *fileResource
					log.Printf("Inside CreateFile rule: output.TargetResource.Type=%s", output.TargetResource.Type)
					output.TargetResource.Type = "Filesystem::File"
					output.Operation = "CREATE"
					log.Printf("CreateFile rule applied. fileName: %s, fileResource: %+v", fileName, **fileResource)
					return true, 2, nil
				}
			}
			return false, 0, nil
		},
	})

	pre.RegisterRule(ParsingRule{
		Name:		"InFolder",
		Pattern:	[]string{"PREPOSITION", "OBJECT_TYPE", "NN"},
		Action: func(tokens, posTags, nerTags []string, i int, output *semantic.SemanticOutput,
			fileResource **semantic.Resource, folderResource **semantic.Resource,
			webserverResource **semantic.Resource, lastFolderResource **semantic.Resource,
			lastProcessedResource **semantic.Resource, expectingDependencyTarget *bool,
			expectingDependencySource *bool, dependencyType *string) (bool, int, error) {
			if strings.ToLower(tokens[i]) == "in" && strings.ToLower(tokens[i+1]) == "folder" {
				folderName := getResourceName(tokens, nerTags, i+1, "folder")
				if folderName != "" {

					if output.TargetResource != nil && output.TargetResource.Name != "" {
						output.TargetResource.Directory = folderName
					} else {

						*folderResource = &semantic.Resource{Type: "Filesystem::Folder", Name: folderName, Properties: map[string]any{"permissions": 0755}}
						output.TargetResource = *folderResource
					}
					return true, 3, nil
				}
			}
			return false, 0, nil
		},
	})
}

type AbstractSemanticGraph struct {
	Nodes		map[string]*GraphNode	`json:"nodes"`
	Edges		[]*GraphEdge		`json:"edges"`
	Root		*GraphNode		`json:"root_node"`
	Metadata	map[string]any		`json:"metadata"`
}

type ASGGenerator struct {
	NodeIDCounter	int
	RoleMapping	map[string]string	// Maps role types to node types
}

// NewASGGenerator creates a new ASG generator
func NewASGGenerator() *ASGGenerator {
	return &ASGGenerator{
		NodeIDCounter:	0,
		RoleMapping: map[string]string{
			"OPERATION":	"OPERATION",
			"RESOURCE":	"RESOURCE",
			"ARGUMENT":	"ARGUMENT",
			"MODIFIER":	"CONSTRAINT",
		},
	}
}

// GenerateFromSemanticRoles constructs an ASG from extracted semantic roles
// This is the core method that builds structured graphs from flat semantic role output
func (ag *ASGGenerator) GenerateFromSemanticRoles(
	operation string,
	resources []map[string]string,
	arguments []map[string]string,
	modifiers []map[string]string,
) *AbstractSemanticGraph {
	asg := &AbstractSemanticGraph{
		Nodes:		make(map[string]*GraphNode),
		Edges:		make([]*GraphEdge, 0),
		Metadata:	make(map[string]any),
	}

	opNodeID := ag.generateNodeID()
	opNode := &GraphNode{
		ID:		opNodeID,
		NodeType:	"OPERATION",
		Label:		strings.ToTitle(operation),
		Value:		operation,
		Properties: map[string]any{
			"main_verb": true,
		},
		Dependencies:	make([]string, 0),
	}
	asg.Nodes[opNodeID] = opNode
	asg.Root = opNode

	resourceNodeIDs := make([]string, 0)
	for _, resource := range resources {
		resNodeID := ag.generateNodeID()
		resType := resource["type"]
		resName := resource["name"]

		resNode := &GraphNode{
			ID:		resNodeID,
			NodeType:	"RESOURCE",
			Label:		resName,
			Value:		resName,
			Properties: map[string]any{
				"resource_type":	resType,
				"canonical_path":	resource["path"],
			},
			Dependencies:	make([]string, 0),
		}
		asg.Nodes[resNodeID] = resNode
		resourceNodeIDs = append(resourceNodeIDs, resNodeID)

		asg.Edges = append(asg.Edges, &GraphEdge{
			SourceID:	opNodeID,
			TargetID:	resNodeID,
			RelationType:	"ACTS_ON",
			Weight:		1.0,
			Properties:	make(map[string]any),
		})

		opNode.Dependencies = append(opNode.Dependencies, resNodeID)
	}

	for _, arg := range arguments {
		argNodeID := ag.generateNodeID()
		argRole := arg["role"]
		argValue := arg["value"]

		argNode := &GraphNode{
			ID:		argNodeID,
			NodeType:	"ARGUMENT",
			Label:		fmt.Sprintf("%s: %s", argRole, argValue),
			Value:		argValue,
			Properties: map[string]any{
				"argument_role": argRole,
			},
			Dependencies:	make([]string, 0),
		}
		asg.Nodes[argNodeID] = argNode

		asg.Edges = append(asg.Edges, &GraphEdge{
			SourceID:	opNodeID,
			TargetID:	argNodeID,
			RelationType:	"HAS_ARGUMENT",
			Weight:		0.9,
			Properties: map[string]any{
				"arg_type": argRole,
			},
		})

		for _, resID := range resourceNodeIDs {
			if argRole == "PATH" || argRole == "NAME" || argRole == "MODE" {
				asg.Edges = append(asg.Edges, &GraphEdge{
					SourceID:	resID,
					TargetID:	argNodeID,
					RelationType:	"HAS_PROPERTY",
					Weight:		0.85,
					Properties: map[string]any{
						"property_name": argRole,
					},
				})
				asg.Nodes[resID].Dependencies = append(asg.Nodes[resID].Dependencies, argNodeID)
			}
		}
	}

	for _, modifier := range modifiers {
		modNodeID := ag.generateNodeID()
		modValue := modifier["value"]

		modNode := &GraphNode{
			ID:		modNodeID,
			NodeType:	"CONSTRAINT",
			Label:		modValue,
			Value:		modValue,
			Properties: map[string]any{
				"constraint_type": "MODIFIER",
			},
			Dependencies:	make([]string, 0),
		}
		asg.Nodes[modNodeID] = modNode

		asg.Edges = append(asg.Edges, &GraphEdge{
			SourceID:	modNodeID,
			TargetID:	opNodeID,
			RelationType:	"MODIFIES",
			Weight:		0.8,
			Properties: map[string]any{
				"affects_operation": true,
			},
		})

		opNode.Dependencies = append(opNode.Dependencies, modNodeID)
	}

	asg.Metadata["operation"] = operation
	asg.Metadata["resource_count"] = len(resourceNodeIDs)
	asg.Metadata["argument_count"] = len(arguments)
	asg.Metadata["modifier_count"] = len(modifiers)
	asg.Metadata["total_nodes"] = len(asg.Nodes)
	asg.Metadata["total_edges"] = len(asg.Edges)

	return asg
}

// GenerateExecutionPlan converts ASG into an executable workflow
func (ag *ASGGenerator) GenerateExecutionPlan(asg *AbstractSemanticGraph) map[string]any {
	plan := make(map[string]any)

	if asg.Root == nil {
		return plan
	}

	plan["operation"] = asg.Root.Value

	targetResources := make([]map[string]any, 0)
	for nodeID, node := range asg.Nodes {
		if node.NodeType == "RESOURCE" {
			resource := make(map[string]any)
			resource["id"] = nodeID
			resource["name"] = node.Value
			resource["type"] = node.Properties["resource_type"]
			resource["path"] = node.Properties["canonical_path"]

			properties := make(map[string]any)
			for _, edge := range asg.Edges {
				if edge.TargetID == nodeID && edge.RelationType == "HAS_PROPERTY" {
					if propNode, exists := asg.Nodes[edge.SourceID]; exists {
						propRole := propNode.Properties["argument_role"]
						properties[fmt.Sprintf("%v", propRole)] = propNode.Value
					}
				}
			}
			if len(properties) > 0 {
				resource["properties"] = properties
			}

			targetResources = append(targetResources, resource)
		}
	}
	if len(targetResources) > 0 {
		plan["target_resources"] = targetResources
	}

	arguments := make(map[string]any)
	for _, node := range asg.Nodes {
		if node.NodeType == "ARGUMENT" {
			argRole := node.Properties["argument_role"]
			arguments[fmt.Sprintf("%v", argRole)] = node.Value
		}
	}
	if len(arguments) > 0 {
		plan["arguments"] = arguments
	}

	constraints := make([]string, 0)
	for _, node := range asg.Nodes {
		if node.NodeType == "CONSTRAINT" {
			constraints = append(constraints, node.Value)
		}
	}
	if len(constraints) > 0 {
		plan["constraints"] = constraints
	}

	plan["metadata"] = asg.Metadata

	return plan
}

// ValidateASG checks the structural validity of the ASG
func (ag *ASGGenerator) ValidateASG(asg *AbstractSemanticGraph) error {
	if asg.Root == nil {
		return fmt.Errorf("ASG must have a root operation node")
	}

	if asg.Root.NodeType != "OPERATION" {
		return fmt.Errorf("root node must be an OPERATION, got %s", asg.Root.NodeType)
	}

	for _, edge := range asg.Edges {
		if _, exists := asg.Nodes[edge.SourceID]; !exists {
			return fmt.Errorf("edge references non-existent source node: %s", edge.SourceID)
		}
		if _, exists := asg.Nodes[edge.TargetID]; !exists {
			return fmt.Errorf("edge references non-existent target node: %s", edge.TargetID)
		}
	}

	hasResources := false
	for _, node := range asg.Nodes {
		if node.NodeType == "RESOURCE" {
			hasResources = true
			break
		}
	}

	if !hasResources && asg.Root.Value != "" {

		if !strings.EqualFold(asg.Root.Value, "list") && !strings.EqualFold(asg.Root.Value, "show") {

		}
	}

	return nil
}

