// RegisterBlueprint adds a blueprint to the registry
func (be *BlueprintEngine) RegisterBlueprint(bp *Blueprint) {
	be.registry[bp.Name] = bp
}

// GetBlueprint retrieves a blueprint by name
func (be *BlueprintEngine) GetBlueprint(name string) (*Blueprint, bool) {
	bp, exists := be.registry[name]
	return bp, exists
}

// Execute renders a blueprint with parameters
func (be *BlueprintEngine) Execute(blueprintName string, params map[string]any) (string, error) {
	bp, exists := be.GetBlueprint(blueprintName)
	if !exists {
		return "", fmt.Errorf("blueprint '%s' not found", blueprintName)
	}

	finalParams := be.mergeWithDefaults(bp, params)

	tmpl, err := template.New(bp.Name).Parse(bp.CodeTemplate)
	if err != nil {
		return "", fmt.Errorf("template parse error: %v", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, finalParams); err != nil {
		return "", fmt.Errorf("template execution error: %v", err)
	}

	return buf.String(), nil
}

// ExecuteFile renders a blueprint file with parameters
func (be *BlueprintEngine) ExecuteFile(bp *Blueprint, file BlueprintFile, params map[string]any) (string, error) {

	finalParams := be.mergeWithDefaults(bp, params)

	tmpl, err := template.New(file.Name).Parse(file.Template)
	if err != nil {
		return "", fmt.Errorf("template parse error: %v", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, finalParams); err != nil {
		return "", fmt.Errorf("template execution error: %v", err)
	}

	return buf.String(), nil
}

// mergeWithDefaults merges provided params with blueprint defaults
func (be *BlueprintEngine) mergeWithDefaults(bp *Blueprint, params map[string]any) map[string]any {
	result := make(map[string]any)

	for _, param := range bp.Parameters {
		result[param.Name] = param.DefaultValue
	}

	maps.Copy(result, params)

	return result
}

// ExtractParameters parses parameters from a query string
// Example: "create server named MyAPI on port 3000" → {ServerName: "MyAPI", Port: 3000}
func (be *BlueprintEngine) ExtractParameters(query string, bp *Blueprint) map[string]any {
	params := make(map[string]any)

	words := splitWords(query)

	for i, word := range words {
		lowerWord := toLower(word)

		if lowerWord == "named" && i+1 < len(words) {
			params["ServerName"] = words[i+1]
			params["APIName"] = words[i+1]
			params["HandlerName"] = words[i+1]
		}

		if (lowerWord == "port" || lowerWord == "on") && i+1 < len(words) {
			if i+2 < len(words) && toLower(words[i+1]) == "port" {

				params["Port"] = parseInt(words[i+2])
			} else {

				params["Port"] = parseInt(words[i+1])
			}
		}

		if lowerWord == "version" && i+1 < len(words) {
			params["Version"] = words[i+1]
		}
	}

	return params
}

// Helper functions
func splitWords(s string) []string {
	return strings.Fields(s)
}

func toLower(s string) string {
	return strings.ToLower(s)
}

func parseInt(s string) int {
	var i int
	fmt.Sscanf(s, "%d", &i)
	return i
}

type CommandParser struct {
	classifier	*IntentClassifier
	extractor	*EntityExtractor
}

// NewCommandParser creates a new command parser
func NewCommandParser() *CommandParser {
	return &CommandParser{
		classifier:	NewIntentClassifier(),
		extractor:	NewEntityExtractor(),
	}
}

// Parse converts a query into a structured command
func (cp *CommandParser) Parse(query string, words []string, entityMap map[int]ner.EntityType) *StructuredCommand {

	intent := cp.classifier.Classify(query)

	entities := cp.extractor.Extract(words, entityMap)

	return cp.BuildCommand(intent, entities, words)
}

// BuildCommand constructs a StructuredCommand from intent and entities
func (cp *CommandParser) BuildCommand(intent IntentType, entities map[string]string, words []string) *StructuredCommand {
	cmd := NewStructuredCommand()

	cmd.Action = IntentToAction(intent)

	cmd.ObjectType = IntentToObjectType(intent)

	switch cmd.ObjectType {
	case ObjectFile:
		if name, ok := entities["file"]; ok {
			cmd.Name = name
		} else if name, ok := entities["source_file"]; ok {
			cmd.Name = name
		}
	case ObjectFolder:
		if name, ok := entities["folder"]; ok {
			cmd.Name = name
		} else if name, ok := entities["source_folder"]; ok {
			cmd.Name = name
		}
	case ObjectComponent:
		if name, ok := entities["component"]; ok {
			cmd.Name = name
		}
	case ObjectCode:
		if name, ok := entities["code_type"]; ok {
			cmd.Name = name
		}
	}

	if path, ok := entities["path"]; ok {
		cmd.Path = path
	} else if dest, ok := entities["destination_folder"]; ok {
		cmd.Path = dest
	}

	keyword := cp.detectKeyword(words)
	if keyword != "" {
		cmd.Keyword = keyword
	}

	secondaryType := IntentToSecondaryObjectType(intent)
	if secondaryType != "" {
		cmd.ArgumentType = secondaryType

		switch secondaryType {
		case ObjectFile:
			if name, ok := entities["file"]; ok {
				cmd.ArgumentName = name
			} else if name, ok := entities["destination_file"]; ok {
				cmd.ArgumentName = name
			}
		case ObjectFolder:
			if name, ok := entities["destination_folder"]; ok {
				cmd.ArgumentName = name
			}
		}
	}

	if cmd.Action == ActionRename {
		if newName, ok := entities["destination_file"]; ok {
			cmd.ArgumentName = newName
			cmd.ArgumentType = cmd.ObjectType
		} else if newName, ok := entities["destination_folder"]; ok {
			cmd.ArgumentName = newName
			cmd.ArgumentType = cmd.ObjectType
		}
	} else if cmd.Action == ActionMove {
		if dest, ok := entities["destination_folder"]; ok {
			cmd.ArgumentName = dest
			cmd.ArgumentType = ObjectFolder
		}
	}

	if intent == IntentAddHandler {
		if url, ok := entities["file"]; ok {
			if cmd.Properties == nil {
				cmd.Properties = make(map[string]string)
			}
			cmd.Properties["url"] = url
		}
	}

	if cmd.Properties == nil {
		cmd.Properties = make(map[string]string)
	}
	for key, value := range entities {

		if key == "file" || key == "folder" || key == "source_file" || key == "source_folder" ||
			key == "destination_file" || key == "destination_folder" || key == "path" ||
			key == "component" || key == "code_type" {
			continue
		}
		cmd.Properties[key] = value
	}

	return cmd
}

// detectKeyword identifies keywords in the query
func (cp *CommandParser) detectKeyword(words []string) CommandKeyword {
	for _, word := range words {
		lowerWord := strings.ToLower(word)
		switch lowerWord {
		case "with":
			return KeywordWith
		case "and":
			return KeywordAnd
		case "in":
			return KeywordIn
		case "into":
			return KeywordInto
		case "to":
			return KeywordTo
		case "inside":
			return KeywordInside
		}
	}
	return ""
}

// ParseQuery is a convenience method that parses a query string directly
func (cp *CommandParser) ParseQuery(query string, entityMap map[int]ner.EntityType) *StructuredCommand {
	words := strings.Fields(query)
	return cp.Parse(query, words, entityMap)
}

type StructuredCommand struct {
	// Primary operation
	Action		CommandAction	// e.g., "create"
	ObjectType	ObjectType	// e.g., "folder"
	Name		string		// e.g., "jime"

	// Secondary/nested operation (optional)
	Keyword		CommandKeyword	// e.g., "with"
	ArgumentType	ObjectType	// e.g., "file"
	ArgumentName	string		// e.g., "Jill.go"

	// Additional context
	Path		string			// Path/location for the operation
	Properties	map[string]string	// Additional properties
}

// NewStructuredCommand creates a new structured command
func NewStructuredCommand() *StructuredCommand {
	return &StructuredCommand{
		Properties: make(map[string]string),
	}
}

// HasSecondaryOperation checks if the command has a nested/secondary operation
func (sc *StructuredCommand) HasSecondaryOperation() bool {
	return sc.Keyword != "" && sc.ArgumentType != ""
}

// IsValid checks if the command has the minimum required elements
func (sc *StructuredCommand) IsValid() bool {
	return sc.Action != "" && sc.ObjectType != ""
}

// String returns a human-readable representation of the command
func (sc *StructuredCommand) String() string {
	result := string(sc.Action) + " " + string(sc.ObjectType)
	if sc.Name != "" {
		result += " " + sc.Name
	}
	if sc.HasSecondaryOperation() {
		result += " " + string(sc.Keyword) + " " + string(sc.ArgumentType)
		if sc.ArgumentName != "" {
			result += " " + sc.ArgumentName
		}
	}
	return result
}

// IntentToObjectType extracts the primary object type from an intent
func IntentToObjectType(intent IntentType) ObjectType {
	switch intent {
	case IntentCreateFile, IntentDeleteFile, IntentMoveFile, IntentRenameFile, IntentReadFile:
		return ObjectFile
	case IntentCreateFolder, IntentDeleteFolder, IntentMoveFolder, IntentRenameFolder, IntentCreateFolderWithFile:
		return ObjectFolder
	case IntentModifyCode:
		return ObjectCode
	case IntentAddFeature, IntentAddHandler:
		return ObjectComponent
	default:
		return ""
	}
}

// IntentToSecondaryObjectType extracts the secondary object type from an intent
func IntentToSecondaryObjectType(intent IntentType) ObjectType {
	switch intent {
	case IntentCreateFolderWithFile:
		return ObjectFile
	default:
		return ""
	}
}

type ContextualQueryEnhancer struct {
	context *FilesystemContext
}

// NewContextualQueryEnhancer creates a new query enhancer
func NewContextualQueryEnhancer(context *FilesystemContext) *ContextualQueryEnhancer {
	return &ContextualQueryEnhancer{
		context: context,
	}
}

// Enhance transforms a query by adding contextual information
func (cqe *ContextualQueryEnhancer) Enhance(query string) string {
	words := strings.Fields(query)
	enhanced := make([]string, 0, len(words)+5)

	i := 0
	for i < len(words) {
		word := words[i]
		lowerWord := strings.ToLower(word)

		if lowerWord == "add" && i+2 < len(words) && strings.ToLower(words[i+2]) == "to" {

			fileName := words[i+1]

			if i+3 < len(words) {
				folderRef := words[i+3]

				if _, found := cqe.context.FindFolder(folderRef); found {

					enhanced = append(enhanced, "create", "file", fileName, "in", "folder", folderRef)
					i += 4
					continue
				}
			}
		}

		if lowerWord == "add" && i+1 < len(words) {
			nextWord := words[i+1]

			if strings.Contains(nextWord, ".") || (i+2 < len(words) && strings.ToLower(words[i+2]) != "to") {
				enhanced = append(enhanced, "create", "file")
				i++
				continue
			}
		}

		if i > 0 && (strings.ToLower(words[i-1]) == "in" || strings.ToLower(words[i-1]) == "to") {
			if _, found := cqe.context.FindFolder(word); found {

				if i+1 >= len(words) || strings.ToLower(words[i+1]) != "folder" {
					enhanced = append(enhanced, "folder")
				}
			}
		}

		enhanced = append(enhanced, word)
		i++
	}

	result := strings.Join(enhanced, " ")

	if result != query {

		return result
	}

	return query
}

type Dependency struct {
	SourceFile	string		// File that has the dependency
	TargetFile	string		// File being depended on
	Type		DependencyType	// Type of dependency
	LineNumber	int		// Where the dependency is declared (0 if unknown)
}

type DependencyGraph struct {
	// Outgoing dependencies: file -> list of files it depends on
	outgoing	map[string][]Dependency

	// Incoming dependencies: file -> list of files that depend on it
	incoming	map[string][]Dependency
}

// NewDependencyGraph creates a new dependency graph
func NewDependencyGraph() *DependencyGraph {
	return &DependencyGraph{
		outgoing:	make(map[string][]Dependency),
		incoming:	make(map[string][]Dependency),
	}
}

// AddDependency records a dependency relationship
func (dg *DependencyGraph) AddDependency(sourceFile, targetFile string, depType DependencyType) {
	dep := Dependency{
		SourceFile:	sourceFile,
		TargetFile:	targetFile,
		Type:		depType,
	}

	dg.outgoing[sourceFile] = append(dg.outgoing[sourceFile], dep)

	dg.incoming[targetFile] = append(dg.incoming[targetFile], dep)
}

// GetDependencies returns all files that sourceFile depends on
func (dg *DependencyGraph) GetDependencies(sourceFile string) []Dependency {
	return dg.outgoing[sourceFile]
}

// GetDependents returns all files that depend on targetFile
func (dg *DependencyGraph) GetDependents(targetFile string) []Dependency {
	return dg.incoming[targetFile]
}

// UpdateReferences updates all references when a file is renamed
func (dg *DependencyGraph) UpdateReferences(oldPath, newPath string) []string {
	affected := make([]string, 0)

	dependents := dg.incoming[oldPath]

	for _, dep := range dependents {
		affected = append(affected, dep.SourceFile)
	}

	if deps, exists := dg.outgoing[oldPath]; exists {
		dg.outgoing[newPath] = deps
		delete(dg.outgoing, oldPath)

		for i := range dg.outgoing[newPath] {
			dg.outgoing[newPath][i].SourceFile = newPath
		}
	}

	if deps, exists := dg.incoming[oldPath]; exists {
		dg.incoming[newPath] = deps
		delete(dg.incoming, oldPath)

		for _, dep := range deps {

			if outList, ok := dg.outgoing[dep.SourceFile]; ok {
				for i := range outList {
					if outList[i].TargetFile == oldPath {
						outList[i].TargetFile = newPath
					}
				}
			}
		}
	}

	return affected
}

// HasCycle detects circular dependencies
func (dg *DependencyGraph) HasCycle() bool {
	visited := make(map[string]bool)
	recStack := make(map[string]bool)

	for file := range dg.outgoing {
		if dg.hasCycleUtil(file, visited, recStack) {
			return true
		}
	}

	return false
}

func (dg *DependencyGraph) hasCycleUtil(file string, visited, recStack map[string]bool) bool {
	if recStack[file] {
		return true
	}

	if visited[file] {
		return false
	}

	visited[file] = true
	recStack[file] = true

	for _, dep := range dg.outgoing[file] {
		if dg.hasCycleUtil(dep.TargetFile, visited, recStack) {
			return true
		}
	}

	recStack[file] = false
	return false
}

// Summary returns a string representation of the dependency graph
func (dg *DependencyGraph) Summary() string {
	var result strings.Builder

	result.WriteString("Dependency Graph:\n")
	for file, deps := range dg.outgoing {
		if len(deps) > 0 {
			result.WriteString(fmt.Sprintf("  %s depends on:\n", file))
			for _, dep := range deps {
				result.WriteString(fmt.Sprintf("    - %s (%s)\n", dep.TargetFile, dep.Type))
			}
		}
	}

	return result.String()
}

// NewEntityExtractor creates a new entity extractor
func NewEntityExtractor() *EntityExtractor {
	return &EntityExtractor{}
}

// Extract converts NER entity map to a simple key-value map
// entityMap: map[wordIndex]entityType
// words: the tokenized words from the query
func (ee *EntityExtractor) Extract(words []string, entityMap map[int]ner.EntityType) map[string]string {
	entities := make(map[string]string)

	directionalIdx := -1
	for i, word := range words {
		lowerWord := strings.ToLower(word)
		if lowerWord == "into" || lowerWord == "to" {
			directionalIdx = i
			break
		}
	}

	folderCount := 0
	fileCount := 0

	stopWords := map[string]bool{
		"of":	true, "the": true, "a": true, "an": true,
		"at":	true, "by": true, "for": true, "from": true,
		"on":	true, "with": true, "in": true, "named": true,
	}

	hasDatabaseComponent := false
	for i, word := range words {
		if entityMap[i] == "COMPONENT_NAME" || entityMap[i] == "FEATURE_NAME" {
			lower := strings.ToLower(word)
			if lower == "database" || lower == "db" || lower == "sqlite" {
				hasDatabaseComponent = true
				break
			}
		}
	}

	for i, word := range words {
		entityType, exists := entityMap[i]
		if !exists || entityType == "O" {
			continue
		}

		lowerWord := strings.ToLower(word)
		if lowerWord == "into" || lowerWord == "to" {
			continue
		}

		if stopWords[lowerWord] {
			continue
		}

		switch entityType {
		case "FOLDER_NAME":
			folderCount++
			if directionalIdx != -1 {

				if i < directionalIdx {
					entities["source_folder"] = word
					if folderCount == 1 {
						entities["folder"] = word
					}
				} else {
					entities["destination_folder"] = word
				}
			} else {

				if folderCount == 1 {
					entities["source_folder"] = word
					entities["folder"] = word
				} else if folderCount == 2 {
					entities["destination_folder"] = word
				} else {

					entities["folder"] = word
				}
			}
		case "FILE_NAME":
			fileCount++
			if directionalIdx != -1 && i < directionalIdx {
				entities["source_file"] = word
				entities["file"] = word
			} else if directionalIdx != -1 && i > directionalIdx {

				entities["destination_file"] = word
			} else {

				if fileCount == 1 {
					entities["source_file"] = word
					entities["file"] = word
				} else if fileCount == 2 {
					entities["destination_file"] = word
				} else {

					entities["file"] = word
				}
			}

			if hasDatabaseComponent || strings.HasSuffix(word, ".db") {
				entities["database_name"] = word
			}
		case "FILE_TYPE":
			entities["file_type"] = word
		case "PATH":
			entities["path"] = word
		case "CODE_TYPE":

			if existingCodeType, ok := entities["code_type"]; ok {
				entities["code_type"] = existingCodeType + " " + word
			} else {
				entities["code_type"] = word
			}
		case "FEATURE_NAME":
			entities["feature"] = word
		case "COMPONENT_NAME":
			entities["component"] = word
		}
	}

	return entities
}

// ExtractFromQuery is a convenience method that splits the query and extracts
func (ee *EntityExtractor) ExtractFromQuery(query string, entityMap map[int]ner.EntityType) map[string]string {
	words := strings.Fields(query)
	return ee.Extract(words, entityMap)
}

type FilesystemContext struct {
	// Current working directory in virtual filesystem
	CurrentDirectory	string

	// Map of all known files: filepath -> properties
	Files	map[string]map[string]any

	// Map of all known folders: folderpath -> children
	Folders	map[string][]string

	// Last created project root
	LastProjectRoot	string
}

// NewFilesystemContext creates a new filesystem context
func NewFilesystemContext() *FilesystemContext {
	return &FilesystemContext{
		CurrentDirectory:	"./",
		Files:			make(map[string]map[string]any),
		Folders:		make(map[string][]string),
	}
}

// RecordCommand updates context based on a semantic output
func (fc *FilesystemContext) RecordCommand(output SemanticOutput) {
	if output.Operation == "create" || output.Operation == "Create" {
		fc.recordCreation(output.TargetResource)
	}
}

// recordCreation records a created resource and its children
func (fc *FilesystemContext) recordCreation(resource *Resource) {
	if resource == nil {
		return
	}
	resourceType := strings.ToLower(resource.Type)

	basePath := "./"
	if path, ok := resource.Properties["path"].(string); ok && path != "" {
		basePath = path
	}

	fullPath := filepath.Join(basePath, resource.Name)

	if strings.Contains(resourceType, "folder") {

		fc.Folders[fullPath] = make([]string, 0)

		if len(fc.Folders) == 1 || basePath == "./" {
			fc.CurrentDirectory = fullPath
			fc.LastProjectRoot = fullPath
		}

		for i := range resource.Children {
			child := &resource.Children[i]
			childPath := filepath.Join(fullPath, child.Name)

			if strings.Contains(strings.ToLower(child.Type), "folder") {
				fc.Folders[childPath] = make([]string, 0)
				fc.Folders[fullPath] = append(fc.Folders[fullPath], child.Name)
			} else if strings.Contains(strings.ToLower(child.Type), "file") {
				fc.Files[childPath] = child.Properties
				fc.Folders[fullPath] = append(fc.Folders[fullPath], child.Name)
			}

			fc.recordCreation(child)
		}
	} else if strings.Contains(resourceType, "file") {

		fc.Files[fullPath] = resource.Properties

		parentDir := filepath.Dir(fullPath)
		if children, ok := fc.Folders[parentDir]; ok {
			fc.Folders[parentDir] = append(children, resource.Name)
		}
	}
}

// ResolvePath attempts to resolve a name to a full path
func (fc *FilesystemContext) ResolvePath(name string) string {

	if strings.HasPrefix(name, "./") || strings.HasPrefix(name, "/") {
		return name
	}

	currentPath := filepath.Join(fc.CurrentDirectory, name)
	if fc.FileExists(currentPath) || fc.FolderExists(currentPath) {
		return currentPath
	}

	if fc.LastProjectRoot != "" {
		projectPath := filepath.Join(fc.LastProjectRoot, name)
		if fc.FileExists(projectPath) || fc.FolderExists(projectPath) {
			return projectPath
		}
	}

	for folderPath := range fc.Folders {
		testPath := filepath.Join(folderPath, name)
		if fc.FileExists(testPath) || fc.FolderExists(testPath) {
			return testPath
		}
	}

	return currentPath
}

// FileExists checks if a file exists in context
func (fc *FilesystemContext) FileExists(path string) bool {
	_, exists := fc.Files[path]
	return exists
}

// FolderExists checks if a folder exists in context
func (fc *FilesystemContext) FolderExists(path string) bool {
	_, exists := fc.Folders[path]
	return exists
}

// GetFolderContents returns the contents of a folder
func (fc *FilesystemContext) GetFolderContents(path string) []string {
	if children, ok := fc.Folders[path]; ok {
		return children
	}
	return []string{}
}

// FindFolder searches for a folder by name
func (fc *FilesystemContext) FindFolder(name string) (string, bool) {

	currentPath := filepath.Join(fc.CurrentDirectory, name)
	if fc.FolderExists(currentPath) {
		return currentPath, true
	}

	for folderPath := range fc.Folders {
		if filepath.Base(folderPath) == name {
			return folderPath, true
		}

		subPath := filepath.Join(folderPath, name)
		if fc.FolderExists(subPath) {
			return subPath, true
		}
	}

	return "", false
}

// FindFile searches for a file by name
func (fc *FilesystemContext) FindFile(name string) (string, bool) {

	currentPath := filepath.Join(fc.CurrentDirectory, name)
	if fc.FileExists(currentPath) {
		return currentPath, true
	}

	for filePath := range fc.Files {
		if filepath.Base(filePath) == name {
			return filePath, true
		}
	}

	return "", false
}

// Summary returns a summary of the current context
func (fc *FilesystemContext) Summary() string {
	var sb strings.Builder
	sb.WriteString("Current Directory: ")
	sb.WriteString(fc.CurrentDirectory)
	sb.WriteString("\n")

	if fc.LastProjectRoot != "" {
		sb.WriteString("Project Root: ")
		sb.WriteString(fc.LastProjectRoot)
		sb.WriteString("\n")
	}

	if len(fc.Folders) > 0 {
		sb.WriteString("\nFolders:\n")
		for folder, children := range fc.Folders {
			sb.WriteString("  ")
			sb.WriteString(folder)
			if len(children) > 0 {
				sb.WriteString(" (")
				sb.WriteString(strings.Join(children, ", "))
				sb.WriteString(")")
			}
			sb.WriteString("\n")
		}
	}

	if len(fc.Files) > 0 {
		sb.WriteString("\nFiles:\n")
		for file := range fc.Files {
			sb.WriteString("  ")
			sb.WriteString(file)
			sb.WriteString("\n")
		}
	}

	return sb.String()
}

type HierarchicalCommand struct {
	// Primary operation
	Action		CommandAction	// e.g., "create"
	ObjectType	ObjectType	// e.g., "folder"
	Name		string		// e.g., "myproject"

	// Template/boilerplate to apply
	Template	string	// e.g., "webserver", "react-app", "go-cli"

	// Nested children (files, folders, etc.)
	Children	[]*HierarchicalCommand

	// Additional context
	Path		string			// Path/location for the operation
	Properties	map[string]string	// Additional properties
}

// NewHierarchicalCommand creates a new hierarchical command
func NewHierarchicalCommand() *HierarchicalCommand {
	return &HierarchicalCommand{
		Children:	make([]*HierarchicalCommand, 0),
		Properties:	make(map[string]string),
	}
}

// AddChild adds a child command to this command
func (hc *HierarchicalCommand) AddChild(child *HierarchicalCommand) {
	hc.Children = append(hc.Children, child)
}

// HasChildren checks if the command has nested children
func (hc *HierarchicalCommand) HasChildren() bool {
	return len(hc.Children) > 0
}

// IsValid checks if the command has the minimum required elements
func (hc *HierarchicalCommand) IsValid() bool {
	return hc.Action != "" && hc.ObjectType != ""
}

// String returns a human-readable representation of the command tree
func (hc *HierarchicalCommand) String() string {
	return hc.stringWithIndent(0)
}

func (hc *HierarchicalCommand) stringWithIndent(indent int) string {
	var prefix strings.Builder
	for range indent {
		prefix.WriteString("  ")
	}

	var result strings.Builder
	result.WriteString(prefix.String() + string(hc.Action) + " " + string(hc.ObjectType))
	if hc.Name != "" {
		result.WriteString(" " + hc.Name)
	}
	if hc.Template != "" {
		result.WriteString(" (template: " + hc.Template + ")")
	}

	if hc.HasChildren() {
		for _, child := range hc.Children {
			result.WriteString("\n" + child.stringWithIndent(indent+1))
		}
	}

	return result.String()
}

// ToStructuredCommand converts to legacy StructuredCommand (for backward compatibility)
// Only preserves the first child
func (hc *HierarchicalCommand) ToStructuredCommand() *StructuredCommand {
	cmd := NewStructuredCommand()
	cmd.Action = hc.Action
	cmd.ObjectType = hc.ObjectType
	cmd.Name = hc.Name
	cmd.Path = hc.Path
	cmd.Properties = hc.Properties

	if len(hc.Children) > 0 {
		firstChild := hc.Children[0]
		cmd.ArgumentType = firstChild.ObjectType
		cmd.ArgumentName = firstChild.Name

		if hc.ObjectType == ObjectFolder && firstChild.ObjectType == ObjectFile {
			cmd.Keyword = KeywordWith
		}
	}

	return cmd
}

type HierarchicalParser struct {
	classifier		*IntentClassifier
	extractor		*EntityExtractor
	templateRegistry	*TemplateRegistry
}

// NewHierarchicalParser creates a new hierarchical parser
func NewHierarchicalParser() *HierarchicalParser {
	return &HierarchicalParser{
		classifier:		NewIntentClassifier(),
		extractor:		NewEntityExtractor(),
		templateRegistry:	NewTemplateRegistry(),
	}
}

// Parse converts a complex query into a hierarchical command tree
func (hp *HierarchicalParser) Parse(query string, words []string, entityMap map[int]ner.EntityType) *HierarchicalCommand {

	intent := hp.classifier.Classify(query)

	entities := hp.extractor.Extract(words, entityMap)

	return hp.BuildHierarchicalCommand(query, words, intent, entities, entityMap)
}

// BuildHierarchicalCommand constructs a hierarchical command from parsed elements
func (hp *HierarchicalParser) BuildHierarchicalCommand(
	query string,
	words []string,
	intent IntentType,
	entities map[string]string,
	entityMap map[int]ner.EntityType,
) *HierarchicalCommand {

	cmd := NewHierarchicalCommand()

	cmd.Action = IntentToAction(intent)
	cmd.ObjectType = IntentToObjectType(intent)

	if cmd.ObjectType == ObjectFolder {
		if name, ok := entities["folder"]; ok && name != "" {
			cmd.Name = name
		} else if name, ok := entities["source_folder"]; ok && name != "" {
			cmd.Name = name
		}
	} else if cmd.ObjectType == ObjectFile {
		if name, ok := entities["file"]; ok && name != "" {
			cmd.Name = name
		} else if name, ok := entities["source_file"]; ok && name != "" {
			cmd.Name = name
		}
	}

	template := hp.detectTemplate(words)
	if template != "" && hp.templateRegistry.HasTemplate(template) {
		cmd.Template = template

		hp.templateRegistry.ApplyTemplate(cmd, template)
	}

	children := hp.parseChildren(query, words, entityMap)

	explicitNames := make(map[string]bool)
	for _, child := range children {
		explicitNames[child.Name] = true
		cmd.AddChild(child)
	}

	if template != "" {
		filteredChildren := make([]*HierarchicalCommand, 0)
		for _, child := range cmd.Children {
			if !explicitNames[child.Name] {
				filteredChildren = append(filteredChildren, child)
			}
		}
		cmd.Children = append(children, filteredChildren...)
	}

	return cmd
}

// detectTemplate detects project template keywords in the query
func (hp *HierarchicalParser) detectTemplate(words []string) string {
	templates := hp.templateRegistry.ListTemplates()

	for _, word := range words {
		lowerWord := strings.ToLower(word)
		for _, template := range templates {
			if lowerWord == strings.ToLower(template) {
				return template
			}
		}
	}

	return ""
}

// parseChildren extracts child files/folders from query
// Handles patterns like:
//
//	"in the file main.go"
//	"with handler.go"
//	"and a folder for templates"
func (hp *HierarchicalParser) parseChildren(query string, words []string, entityMap map[int]ner.EntityType) []*HierarchicalCommand {
	children := make([]*HierarchicalCommand, 0)

	for i := 0; i < len(words); i++ {
		word := strings.ToLower(words[i])

		if word == "file" || (word == "the" && i+1 < len(words) && strings.ToLower(words[i+1]) == "file") {
			if word == "the" {
				i++
			}

			if i+1 < len(words) {
				entityType, hasEntity := entityMap[i+1]
				if hasEntity && entityType == "FILE_NAME" {
					child := NewHierarchicalCommand()
					child.Action = ActionCreate
					child.ObjectType = ObjectFile
					child.Name = words[i+1]
					children = append(children, child)
				}
			}
		}

		if word == "folder" {

			if i >= 1 && strings.ToLower(words[i-1]) == "a" {

				if i+1 < len(words) && strings.ToLower(words[i+1]) == "for" && i+2 < len(words) {
					child := NewHierarchicalCommand()
					child.Action = ActionCreate
					child.ObjectType = ObjectFolder
					child.Name = words[i+2]
					children = append(children, child)
				}
			} else {

				if i+1 < len(words) {
					entityType, hasEntity := entityMap[i+1]
					if hasEntity && entityType == "FOLDER_NAME" {
						child := NewHierarchicalCommand()
						child.Action = ActionCreate
						child.ObjectType = ObjectFolder
						child.Name = words[i+1]
						children = append(children, child)
					}
				}
			}
		}
	}

	return children
}

// ParseQuery is a convenience method that parses a query string directly
func (hp *HierarchicalParser) ParseQuery(query string, entityMap map[int]ner.EntityType) *HierarchicalCommand {
	words := strings.Fields(query)
	return hp.Parse(query, words, entityMap)
}

// InferProperties applies dynamic property inference to a resource.
func InferProperties(resource *Resource) {
	if resource == nil {
		return
	}

	switch resource.Type {
	case "Deployment::GoWebserver":
		if _, ok := resource.Properties["port"]; !ok {
			if resource.Properties == nil {
				resource.Properties = make(map[string]any)
			}
			resource.Properties["port"] = 8080
		}
		if _, ok := resource.Properties["runtime_image"]; !ok {
			if resource.Properties == nil {
				resource.Properties = make(map[string]any)
			}
			resource.Properties["runtime_image"] = "golang:latest"
		}
	case "Filesystem::Folder":
		if _, ok := resource.Properties["permissions"]; !ok {
			if resource.Properties == nil {
				resource.Properties = make(map[string]any)
			}
			resource.Properties["permissions"] = "0755"
		}
	case "Filesystem::File":
		if resource.Name == "" {
			resource.Name = "untitled.txt"
		}
		if resource.Directory == "" {
			resource.Directory = "/home/user/documents"
		}
	}

	for i := range resource.Children {
		InferProperties(&resource.Children[i])
	}
}

// NewIntentClassifier creates a new intent classifier
func NewIntentClassifier() *IntentClassifier {
	return &IntentClassifier{}
}

// Classify determines the intent type from a query string
// Uses simple rule-based classification based on keywords
func (ic *IntentClassifier) Classify(query string) IntentType {
	query = strings.ToLower(strings.TrimSpace(query))

	hasFeatureKeyword := containsAny(query, []string{
		"jwt", "auth", "authentication", "authorization",
		"logging", "logger", "log",
		"caching", "cache",
		"validation", "validator",
		"encryption",
		"oauth", "session",
		"cors", "csrf",
		"websocket", "graphql", "rest",
		"rate-limiting", "throttle",
		"metrics", "monitoring",
		"database", "db", "sql", "sqlite",
	})

	hasComponentKeyword := containsAny(query, []string{
		"webserver", "server",
		"api",
		"service",
		"handler", "controller",
		"middleware",
		"router",
		"application", "app",
		"component",
	})

	if containsAny(query, []string{"add", "implement", "integrate", "enable", "connect", "use", "configure"}) &&
		containsAny(query, []string{"to", "in", "into"}) &&
		hasFeatureKeyword &&
		hasComponentKeyword {
		return IntentAddFeature
	}

	if (containsAny(query, []string{"add", "create", "new"}) && strings.Contains(query, "handler")) ||
		(strings.Contains(query, "handler") && containsAny(query, []string{"with url", "at url"})) {
		return IntentAddHandler
	}

	if containsAny(query, []string{"add", "create", "make", "new"}) &&
		containsAny(query, []string{"database", "db", "sql", "sqlite"}) {
		return IntentAddFeature
	}

	if containsAny(query, []string{"modify", "update", "change", "refactor", "fix", "repair", "gofix", "debug"}) {
		return IntentModifyCode
	}

	hasFolder := containsAny(query, []string{"folder", "directory", "dir"})
	hasFile := hasFileReference(query)
	hasConjunction := containsAny(query, []string{"and", "with", "in it", "inside", "into"})
	hasCreateAction := containsAny(query, []string{"add", "create", "make", "new"})

	if hasFolder && hasFile && (hasConjunction || hasCreateAction) {
		return IntentCreateFolderWithFile
	}

	if containsAny(query, []string{"add", "create", "make", "new"}) &&
		containsAny(query, []string{"folder", "directory", "dir"}) &&
		!hasFeatureKeyword && !hasComponentKeyword {
		return IntentCreateFolder
	}

	if containsAny(query, []string{"add", "create", "make", "new"}) &&
		(containsAny(query, []string{"file"}) || hasFileReference(query)) &&
		!hasFeatureKeyword {
		return IntentCreateFile
	}

	if containsAny(query, []string{"delete", "remove", "rm"}) &&
		containsAny(query, []string{"file"}) {
		return IntentDeleteFile
	}

	if containsAny(query, []string{"delete", "remove", "rm"}) &&
		containsAny(query, []string{"folder", "directory", "dir"}) {
		return IntentDeleteFolder
	}

	if containsAny(query, []string{"read", "open", "view", "show"}) &&
		containsAny(query, []string{"file"}) {
		return IntentReadFile
	}

	hasMoveAction := containsAny(query, []string{"move", "relocate", "mv", "transfer"})
	hasDirectional := containsAny(query, []string{"into", "to", "in"})

	if hasMoveAction && hasDirectional {

		if hasFileReference(query) {
			return IntentMoveFile
		} else if containsAny(query, []string{"folder", "directory", "dir"}) {
			return IntentMoveFolder
		}
	}

	hasRenameAction := containsAny(query, []string{"rename", "renaming"})
	hasToKeyword := containsAny(query, []string{"to"})

	if hasRenameAction && hasToKeyword {

		if hasFileReference(query) {
			return IntentRenameFile
		} else if containsAny(query, []string{"folder", "directory", "dir"}) {
			return IntentRenameFolder
		}
	}

	if containsAny(query, []string{"go into", "go to", "open", "cd"}) &&
		containsAny(query, []string{"computer", "project", "workspace"}) {
		return GoToProject
	}

	if containsAny(query, []string{"remember", "scan for"}) &&
		containsAny(query, []string{"projects", "workspaces"}) {
		return RememberProjects
	}

	return IntentUnknown
}

// containsAny checks if the text contains any of the keywords
func containsAny(text string, keywords []string) bool {
	for _, keyword := range keywords {
		if strings.Contains(text, keyword) {
			return true
		}
	}
	return false
}

// hasFileReference checks if the query contains a file reference
// This includes the literal word "file" or common file extensions
func hasFileReference(query string) bool {

	if strings.Contains(query, "file") {
		return true
	}

	extensions := []string{
		".go", ".py", ".js", ".ts", ".java", ".c", ".cpp", ".h", ".hpp",
		".txt", ".md", ".json", ".yaml", ".yml", ".xml", ".html", ".css",
		".sh", ".bash", ".sql", ".rs", ".rb", ".php", ".swift", ".kt",
		".scala", ".r", ".m", ".pl", ".lua", ".vim", ".toml", ".ini",
		".conf", ".cfg", ".env", ".proto", ".graphql", ".vue", ".jsx", ".tsx",
	}

	for _, ext := range extensions {
		if strings.Contains(query, ext) {
			return true
		}
	}

	return false
}

