// NewStructuredSemanticLoss creates a new loss function with default weights
func NewStructuredSemanticLoss() *StructuredSemanticLoss {
	return &StructuredSemanticLoss{
		OperationWeight:	0.4,
		ResourceWeight:		0.3,
		ArgumentWeight:		0.2,
		StructureWeight:	0.1,
		LabelSmoothing:		0.1,
	}
}

// ComputeLoss calculates the total structured semantic loss
func (ssl *StructuredSemanticLoss) ComputeLoss(
	operationLogits *Tensor,
	operationTargets []int,
	resourceLogits *Tensor,
	resourceTargets []int,
	argumentLogits *Tensor,
	argumentTargets []int,
	asgEdgeLogits *Tensor,
	asgEdgeTargets []int,
	paddingID int,
) (float32, map[string]float32, error) {

	losses := make(map[string]float32)
	var totalLoss float32 = 0.0

	if operationLogits != nil && len(operationTargets) > 0 {
		opLoss, err := ssl.computeOperationLoss(operationLogits, operationTargets, paddingID)
		if err != nil {
			return 0, nil, fmt.Errorf("operation loss computation failed: %w", err)
		}
		losses["operation"] = opLoss
		totalLoss += ssl.OperationWeight * opLoss
	}

	if resourceLogits != nil && len(resourceTargets) > 0 {
		resLoss, err := ssl.computeResourceLoss(resourceLogits, resourceTargets, paddingID)
		if err != nil {
			return 0, nil, fmt.Errorf("resource loss computation failed: %w", err)
		}
		losses["resource"] = resLoss
		totalLoss += ssl.ResourceWeight * resLoss
	}

	if argumentLogits != nil && len(argumentTargets) > 0 {
		argLoss, err := ssl.computeArgumentLoss(argumentLogits, argumentTargets, paddingID)
		if err != nil {
			return 0, nil, fmt.Errorf("argument loss computation failed: %w", err)
		}
		losses["argument"] = argLoss
		totalLoss += ssl.ArgumentWeight * argLoss
	}

	if asgEdgeLogits != nil && len(asgEdgeTargets) > 0 {
		structLoss, err := ssl.computeStructureLoss(asgEdgeLogits, asgEdgeTargets, paddingID)
		if err != nil {
			return 0, nil, fmt.Errorf("structure loss computation failed: %w", err)
		}
		losses["structure"] = structLoss
		totalLoss += ssl.StructureWeight * structLoss
	}

	losses["total"] = totalLoss
	return totalLoss, losses, nil
}

// computeOperationLoss calculates loss for operation classification
func (ssl *StructuredSemanticLoss) computeOperationLoss(
	logits *Tensor,
	targets []int,
	paddingID int,
) (float32, error) {
	if logits == nil || len(targets) == 0 {
		return 0.0, nil
	}

	// Use standard cross-entropy loss
	var loss float32 = 0.0
	batchSize := len(targets)

	if len(logits.Shape) == 2 {

		vocabSize := logits.Shape[1]

		for i := range batchSize {
			targetID := targets[i]

			if targetID == paddingID {
				continue
			}

			if i*vocabSize+targetID >= len(logits.Data) {
				continue
			}

			logit := logits.Data[i*vocabSize+targetID]

			labelSmoothed := 1.0 - ssl.LabelSmoothing*(1.0/float32(vocabSize-1))

			loss -= labelSmoothed * logit

			maxLogit := getMaxLogit(logits.Data, i*vocabSize, vocabSize)
			loss += float32(math.Log(float64(computeSumExp(logits.Data, i*vocabSize, vocabSize) - maxLogit)))
		}
	}

	return loss / float32(batchSize), nil
}

// computeResourceLoss calculates loss for resource identification
// Resources are typically multi-token spans, so we use sequence loss
func (ssl *StructuredSemanticLoss) computeResourceLoss(
	logits *Tensor,
	targets []int,
	paddingID int,
) (float32, error) {
	if logits == nil || len(targets) == 0 {
		return 0.0, nil
	}

	var loss float32 = 0.0
	count := 0

	vocabSize := logits.Shape[len(logits.Shape)-1]

	for i, targetID := range targets {
		if targetID == paddingID {
			continue
		}

		idx := i * vocabSize

		if idx+targetID >= len(logits.Data) {
			continue
		}

		logit := logits.Data[idx+targetID]
		loss -= logit
		loss += float32(math.Log(float64(computeSumExp(logits.Data, idx, vocabSize))))
		count++
	}

	if count == 0 {
		return 0.0, nil
	}

	return loss / float32(count), nil
}

// computeArgumentLoss calculates loss for argument role classification
func (ssl *StructuredSemanticLoss) computeArgumentLoss(
	logits *Tensor,
	targets []int,
	paddingID int,
) (float32, error) {
	if logits == nil || len(targets) == 0 {
		return 0.0, nil
	}

	var loss float32 = 0.0
	count := 0

	vocabSize := logits.Shape[len(logits.Shape)-1]

	for i, targetID := range targets {
		if targetID == paddingID {
			continue
		}

		idx := i * vocabSize

		if idx+targetID >= len(logits.Data) {
			continue
		}

		logit := logits.Data[idx+targetID]
		loss -= logit
		loss += float32(math.Log(float64(computeSumExp(logits.Data, idx, vocabSize))))
		count++
	}

	if count == 0 {
		return 0.0, nil
	}

	return loss / float32(count), nil
}

// computeStructureLoss calculates loss for graph edge validity
// This ensures the generated ASG has valid structure
func (ssl *StructuredSemanticLoss) computeStructureLoss(
	logits *Tensor,
	targets []int,
	paddingID int,
) (float32, error) {
	if logits == nil || len(targets) == 0 {
		return 0.0, nil
	}

	// For edge classification (valid/invalid relation types)
	var loss float32 = 0.0
	count := 0

	vocabSize := logits.Shape[len(logits.Shape)-1]

	for i, targetID := range targets {
		if targetID == paddingID {
			continue
		}

		idx := i * vocabSize

		if idx+targetID >= len(logits.Data) {
			continue
		}

		logit := logits.Data[idx+targetID]
		loss -= logit
		loss += float32(math.Log(float64(computeSumExp(logits.Data, idx, vocabSize))))
		count++
	}

	if count == 0 {
		return 0.0, nil
	}

	// Apply structure penalty - invalid edges should have higher loss
	var structurePenalty float32 = 0.1 * float32(len(targets)-count) / float32(len(targets))
	return (loss / float32(count)) + structurePenalty, nil
}

// ValidateSemanticStructure checks if generated ASG is structurally valid
func (ssl *StructuredSemanticLoss) ValidateSemanticStructure(asg *AbstractSemanticGraph) (bool, []string) {
	errors := make([]string, 0)

	if asg == nil || asg.Root == nil {
		errors = append(errors, "ASG is nil or has no root")
		return false, errors
	}

	if asg.Root.NodeType != "OPERATION" {
		errors = append(errors, fmt.Sprintf("root node type should be OPERATION, got %s", asg.Root.NodeType))
	}

	for _, edge := range asg.Edges {
		if _, exists := asg.Nodes[edge.SourceID]; !exists {
			errors = append(errors, fmt.Sprintf("edge references non-existent source: %s", edge.SourceID))
		}
		if _, exists := asg.Nodes[edge.TargetID]; !exists {
			errors = append(errors, fmt.Sprintf("edge references non-existent target: %s", edge.TargetID))
		}
	}

	hasResource := false
	for _, node := range asg.Nodes {
		if node.NodeType == "RESOURCE" {
			hasResource = true
			break
		}
	}

	if !hasResource {

		errors = append(errors, "ASG has no resource nodes (this may be valid for query-only operations)")
	}

	hasOutgoingEdges := false
	for _, edge := range asg.Edges {
		if edge.SourceID == asg.Root.ID {
			hasOutgoingEdges = true
			break
		}
	}

	if !hasOutgoingEdges && len(asg.Nodes) > 1 {
		errors = append(errors, "root operation has no outgoing edges")
	}

	return len(errors) == 0, errors
}

func getMaxLogit(data []float32, start, size int) float32 {
	if len(data) == 0 || start+size > len(data) {
		return 0.0
	}

	var maxVal float32 = data[start]
	for i := start + 1; i < start+size; i++ {
		if data[i] > maxVal {
			maxVal = data[i]
		}
	}
	return maxVal
}

func computeSumExp(data []float32, start, size int) float32 {
	if len(data) == 0 || start+size > len(data) {
		return 0.0
	}

	maxVal := getMaxLogit(data, start, size)
	var sum float32 = 0.0

	for i := start; i < start+size; i++ {
		sum += float32(math.Exp(float64(data[i] - maxVal)))
	}

	return sum + maxVal
}

// ComputeMetrics calculates evaluation metrics for semantic parsing
func (ssl *StructuredSemanticLoss) ComputeMetrics(
	predictions *AbstractSemanticGraph,
	ground_truth *AbstractSemanticGraph,
) map[string]float32 {
	metrics := make(map[string]float32)

	if predictions == nil || ground_truth == nil {
		metrics["node_accuracy"] = 0.0
		metrics["edge_accuracy"] = 0.0
		metrics["structure_validity"] = 0.0
		return metrics
	}

	correctNodes := 0
	totalNodes := len(ground_truth.Nodes)

	for nodeID, gtNode := range ground_truth.Nodes {
		if predNode, exists := predictions.Nodes[nodeID]; exists {
			if predNode.NodeType == gtNode.NodeType && predNode.Value == gtNode.Value {
				correctNodes++
			}
		}
	}

	if totalNodes > 0 {
		metrics["node_accuracy"] = float32(correctNodes) / float32(totalNodes)
	}

	correctEdges := 0
	totalEdges := len(ground_truth.Edges)

	for _, gtEdge := range ground_truth.Edges {
		for _, predEdge := range predictions.Edges {
			if predEdge.SourceID == gtEdge.SourceID &&
				predEdge.TargetID == gtEdge.TargetID &&
				predEdge.RelationType == gtEdge.RelationType {
				correctEdges++
				break
			}
		}
	}

	if totalEdges > 0 {
		metrics["edge_accuracy"] = float32(correctEdges) / float32(totalEdges)
	}

	isValid, _ := ssl.ValidateSemanticStructure(predictions)
	if isValid {
		metrics["structure_validity"] = 1.0
	} else {
		metrics["structure_validity"] = 0.0
	}

	return metrics
}

type TemplateFiller struct {
	templates map[IntentType]Template
}

// NewTemplateFiller creates a new template filler
func NewTemplateFiller() *TemplateFiller {
	return &TemplateFiller{
		templates: GetTemplates(),
	}
}

// Fill generates SemanticOutput from intent and entities
func (tf *TemplateFiller) Fill(intent IntentType, entities map[string]string) (SemanticOutput, error) {
	template, exists := tf.templates[intent]
	if !exists {
		return SemanticOutput{}, fmt.Errorf("no template for intent: %s", intent)
	}

	return template.Fill(entities), nil
}

// GetIntent returns the template for a given intent type
func (tf *TemplateFiller) GetIntent(intent IntentType) (Template, bool) {
	template, exists := tf.templates[intent]
	return template, exists
}

type TemplateFile struct {
	Name	string	// Filename (e.g., "main.go")
	Content	string	// Boilerplate content
}

type TemplateRegistry struct {
	templates map[string]*ProjectTemplate
}

// NewTemplateRegistry creates a new template registry with built-in templates
func NewTemplateRegistry() *TemplateRegistry {
	registry := &TemplateRegistry{
		templates: make(map[string]*ProjectTemplate),
	}

	registry.registerBuiltInTemplates()

	return registry
}

// registerBuiltInTemplates registers common project templates
func (tr *TemplateRegistry) registerBuiltInTemplates() {

	tr.RegisterTemplate(&ProjectTemplate{
		Name:		"webserver",
		Description:	"Go HTTP web server with handler",
		Files: []TemplateFile{
			{
				Name:	"main.go",
				Content: `package main

import (
	"fmt"
	"log"
	"net/http"
)

func main() {
	http.HandleFunc("/", Handler)

	fmt.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
`,
			},
			{
				Name:	"handler.go",
				Content: `package main

import (
	"fmt"
	"net/http"
)

// Handler handles HTTP requests
func Handler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Hello, World!")
}
`,
			},
		},
		Folders:	[]string{"templates", "static"},
	})

	tr.RegisterTemplate(&ProjectTemplate{
		Name:		"api",
		Description:	"REST API server with routes",
		Files: []TemplateFile{
			{
				Name:	"main.go",
				Content: `package main

import (
	"encoding/json"
	"log"
	"net/http"
)

func main() {
	http.HandleFunc("/api/health", healthHandler)
	http.HandleFunc("/api/data", dataHandler)

	log.Println("API server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
}

func dataHandler(w http.ResponseWriter, r *http.Request) {
	json.NewEncoder(w).Encode(map[string]interface{}{
		"message": "Data endpoint",
		"version": "1.0",
	})
}
`,
			},
		},
		Folders:	[]string{"models", "routes", "middleware"},
	})

	tr.RegisterTemplate(&ProjectTemplate{
		Name:		"cli",
		Description:	"Command-line tool",
		Files: []TemplateFile{
			{
				Name:	"main.go",
				Content: `package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	var name string
	flag.StringVar(&name, "name", "World", "Name to greet")
	flag.Parse()

	fmt.Printf("Hello, %s!\n", name)
	os.Exit(0)
}
`,
			},
		},
		Folders:	[]string{"cmd", "internal"},
	})
}

// RegisterTemplate adds a template to the registry
func (tr *TemplateRegistry) RegisterTemplate(template *ProjectTemplate) {
	tr.templates[template.Name] = template
}

// GetTemplate retrieves a template by name
func (tr *TemplateRegistry) GetTemplate(name string) (*ProjectTemplate, error) {
	template, exists := tr.templates[name]
	if !exists {
		return nil, fmt.Errorf("template '%s' not found", name)
	}
	return template, nil
}

// HasTemplate checks if a template exists
func (tr *TemplateRegistry) HasTemplate(name string) bool {
	_, exists := tr.templates[name]
	return exists
}

// ListTemplates returns all available template names
func (tr *TemplateRegistry) ListTemplates() []string {
	names := make([]string, 0, len(tr.templates))
	for name := range tr.templates {
		names = append(names, name)
	}
	return names
}

// ApplyTemplate applies a template to a hierarchical command
func (tr *TemplateRegistry) ApplyTemplate(cmd *HierarchicalCommand, templateName string) error {
	template, err := tr.GetTemplate(templateName)
	if err != nil {
		return err
	}

	for _, file := range template.Files {
		fileCmd := NewHierarchicalCommand()
		fileCmd.Action = ActionCreate
		fileCmd.ObjectType = ObjectFile
		fileCmd.Name = file.Name
		fileCmd.Properties = map[string]string{
			"content": file.Content,
		}
		cmd.AddChild(fileCmd)
	}

	for _, folder := range template.Folders {
		folderCmd := NewHierarchicalCommand()
		folderCmd.Action = ActionCreate
		folderCmd.ObjectType = ObjectFolder
		folderCmd.Name = folder
		cmd.AddChild(folderCmd)
	}

	cmd.Template = templateName

	return nil
}

// ValidateAndInferProperties orchestrates the validation and inference process
func ValidateAndInferProperties(output *SemanticOutput) error {
	if output == nil {
		return nil
	}

	InferProperties(output.TargetResource)

	if err := ValidateResource(output.TargetResource, output.Context); err != nil {
		return err
	}

	return nil
}

// NewVFSTree creates a new virtual file system
func NewVFSTree() *VFSTree {
	root := &VFSNode{
		Name:		"",
		Path:		"/",
		Type:		"folder",
		Role:		"root",
		Children:	make(map[string]*VFSNode),
		Properties:	make(map[string]any),
		CreatedAt:	time.Now(),
		ModifiedAt:	time.Now(),
	}

	tree := &VFSTree{
		Root:		root,
		CurrentDir:	root,
		PathIndex:	make(map[string]*VFSNode),
		RoleIndex:	make(map[string][]*VFSNode),
		NameIndex:	make(map[string][]*VFSNode),
	}

	tree.PathIndex["/"] = root
	tree.indexRole(root)

	return tree
}

// CreateFolder creates a new folder in the VFS
func (vfs *VFSTree) CreateFolder(path string, role string) (*VFSNode, error) {

	path = vfs.normalizePath(path)

	if existing, exists := vfs.PathIndex[path]; exists {
		return nil, fmt.Errorf("path '%s' already exists as %s", path, existing.Type)
	}

	parentPath := filepath.Dir(path)
	parent, exists := vfs.PathIndex[parentPath]
	if !exists {
		return nil, fmt.Errorf("parent directory '%s' does not exist", parentPath)
	}

	if parent.Type != "folder" {
		return nil, fmt.Errorf("parent '%s' is not a folder", parentPath)
	}

	name := filepath.Base(path)
	node := &VFSNode{
		Name:		name,
		Path:		path,
		Type:		"folder",
		Role:		role,
		Children:	make(map[string]*VFSNode),
		Properties:	make(map[string]any),
		Parent:		parent,
		CreatedAt:	time.Now(),
		ModifiedAt:	time.Now(),
	}

	parent.Children[name] = node
	parent.ModifiedAt = time.Now()

	vfs.PathIndex[path] = node
	vfs.indexRole(node)
	vfs.indexName(node)

	return node, nil
}

// CreateFile creates a new file in the VFS
func (vfs *VFSTree) CreateFile(path string, role string, content string) (*VFSNode, error) {

	path = vfs.normalizePath(path)

	if existing, exists := vfs.PathIndex[path]; exists {
		return nil, fmt.Errorf("path '%s' already exists as %s", path, existing.Type)
	}

	parentPath := filepath.Dir(path)
	parent, exists := vfs.PathIndex[parentPath]
	if !exists {
		return nil, fmt.Errorf("parent directory '%s' does not exist", parentPath)
	}

	if parent.Type != "folder" {
		return nil, fmt.Errorf("parent '%s' is not a folder", parentPath)
	}

	name := filepath.Base(path)
	node := &VFSNode{
		Name:		name,
		Path:		path,
		Type:		"file",
		Role:		role,
		Content:	content,
		Properties:	make(map[string]any),
		Parent:		parent,
		Children:	nil,
		CreatedAt:	time.Now(),
		ModifiedAt:	time.Now(),
	}

	parent.Children[name] = node
	parent.ModifiedAt = time.Now()

	vfs.PathIndex[path] = node
	vfs.indexRole(node)
	vfs.indexName(node)

	return node, nil
}

// ResolvePath finds a node by name (searches from current dir, then globally)
func (vfs *VFSTree) ResolvePath(name string) (*VFSNode, bool) {

	if node, exists := vfs.PathIndex[name]; exists {
		return node, true
	}

	currentPath := filepath.Join(vfs.CurrentDir.Path, name)
	if node, exists := vfs.PathIndex[currentPath]; exists {
		return node, true
	}

	if nodes, exists := vfs.NameIndex[name]; exists && len(nodes) > 0 {
		return nodes[0], true
	}

	return nil, false
}

// GetByRole returns all nodes with a specific role
func (vfs *VFSTree) GetByRole(role string) []*VFSNode {
	if nodes, exists := vfs.RoleIndex[role]; exists {
		return nodes
	}
	return []*VFSNode{}
}

// Rename renames a node and updates all indices
func (vfs *VFSTree) Rename(oldPath string, newName string) error {
	node, exists := vfs.PathIndex[oldPath]
	if !exists {
		return fmt.Errorf("path '%s' not found", oldPath)
	}

	parentPath := filepath.Dir(oldPath)
	newPath := filepath.Join(parentPath, newName)

	if _, exists := vfs.PathIndex[newPath]; exists {
		return fmt.Errorf("path '%s' already exists", newPath)
	}

	delete(vfs.PathIndex, oldPath)
	vfs.removeFromNameIndex(node)

	oldName := node.Name
	node.Name = newName
	node.Path = newPath
	node.ModifiedAt = time.Now()

	if node.Parent != nil {
		delete(node.Parent.Children, oldName)
		node.Parent.Children[newName] = node
	}

	vfs.PathIndex[newPath] = node
	vfs.indexName(node)

	if node.Type == "folder" {
		vfs.updateChildrenPaths(node)
	}

	return nil
}

// ChangeDirectory changes the current working directory
func (vfs *VFSTree) ChangeDirectory(path string) error {
	node, exists := vfs.PathIndex[path]
	if !exists {
		return fmt.Errorf("path '%s' not found", path)
	}

	if node.Type != "folder" {
		return fmt.Errorf("'%s' is not a folder", path)
	}

	vfs.CurrentDir = node
	return nil
}

// Exists checks if a path exists
func (vfs *VFSTree) Exists(path string) bool {
	_, exists := vfs.PathIndex[path]
	return exists
}

// Get retrieves a node by path
func (vfs *VFSTree) Get(path string) (*VFSNode, bool) {
	node, exists := vfs.PathIndex[path]
	return node, exists
}

// normalizePath normalizes a path (removes ./, handles relative paths)
func (vfs *VFSTree) normalizePath(path string) string {

	path = strings.TrimPrefix(path, "./")

	if !strings.HasPrefix(path, "/") {
		path = filepath.Join(vfs.CurrentDir.Path, path)
	}

	return filepath.Clean(path)
}

// indexRole adds a node to the role index
func (vfs *VFSTree) indexRole(node *VFSNode) {
	if node.Role == "" {
		return
	}

	if _, exists := vfs.RoleIndex[node.Role]; !exists {
		vfs.RoleIndex[node.Role] = make([]*VFSNode, 0)
	}

	vfs.RoleIndex[node.Role] = append(vfs.RoleIndex[node.Role], node)
}

// indexName adds a node to the name index
func (vfs *VFSTree) indexName(node *VFSNode) {
	if _, exists := vfs.NameIndex[node.Name]; !exists {
		vfs.NameIndex[node.Name] = make([]*VFSNode, 0)
	}

	vfs.NameIndex[node.Name] = append(vfs.NameIndex[node.Name], node)
}

// removeFromNameIndex removes a node from the name index
func (vfs *VFSTree) removeFromNameIndex(node *VFSNode) {
	if nodes, exists := vfs.NameIndex[node.Name]; exists {

		filtered := make([]*VFSNode, 0)
		for _, n := range nodes {
			if n != node {
				filtered = append(filtered, n)
			}
		}
		if len(filtered) > 0 {
			vfs.NameIndex[node.Name] = filtered
		} else {
			delete(vfs.NameIndex, node.Name)
		}
	}
}

// updateChildrenPaths recursively updates paths for all children
func (vfs *VFSTree) updateChildrenPaths(node *VFSNode) {
	if node.Type != "folder" {
		return
	}

	for _, child := range node.Children {
		oldPath := child.Path
		newPath := filepath.Join(node.Path, child.Name)

		delete(vfs.PathIndex, oldPath)
		child.Path = newPath
		vfs.PathIndex[newPath] = child

		if child.Type == "folder" {
			vfs.updateChildrenPaths(child)
		}
	}
}

// Tree returns a string representation of the tree
func (vfs *VFSTree) Tree() string {
	var sb strings.Builder
	vfs.printNode(&sb, vfs.Root, "", true)
	return sb.String()
}

func (vfs *VFSTree) printNode(sb *strings.Builder, node *VFSNode, prefix string, isLast bool) {
	if node == vfs.Root {
		sb.WriteString("/\n")
	} else {
		connector := "├── "
		if isLast {
			connector = "└── "
		}

		sb.WriteString(prefix)
		sb.WriteString(connector)
		sb.WriteString(node.Name)

		if node.Role != "" {
			sb.WriteString(" [")
			sb.WriteString(node.Role)
			sb.WriteString("]")
		}
		sb.WriteString("\n")
	}

	if node.Type == "folder" && len(node.Children) > 0 {
		childPrefix := prefix
		if node != vfs.Root {
			if isLast {
				childPrefix += "    "
			} else {
				childPrefix += "│   "
			}
		}

		i := 0
		total := len(node.Children)
		for _, child := range node.Children {
			i++
			vfs.printNode(sb, child, childPrefix, i == total)
		}
	}
}

// Delete removes a node from the tree
func (vfs *VFSTree) Delete(path string) error {
	path = vfs.normalizePath(path)
	node, exists := vfs.ResolvePath(path)
	if !exists {
		return fmt.Errorf("path not found: %s", path)
	}

	if node.Parent == nil {
		return fmt.Errorf("cannot delete root node")
	}

	delete(node.Parent.Children, node.Name)

	delete(vfs.PathIndex, path)

	if node.Role != "" {
		if roles, ok := vfs.RoleIndex[node.Role]; ok {
			for i, n := range roles {
				if n == node {
					vfs.RoleIndex[node.Role] = append(roles[:i], roles[i+1:]...)
					break
				}
			}
		}
	}

	vfs.removeFromNameIndex(node)

	return nil
}

