func NewMatMulIterator(resultRows, resultCols, chunkRows, chunkCols int) *MatMulIterator {
	return &MatMulIterator{
		resultRows:	resultRows,
		resultCols:	resultCols,
		chunkRows:	chunkRows,
		chunkCols:	chunkCols,
		currentI:	0,
		currentJ:	-chunkCols,
		hasMore:	true,
	}
}

// Next moves the iterator to the next chunk.
func (it *MatMulIterator) Next() bool {
	it.currentJ += it.chunkCols
	if it.currentJ >= it.resultCols {
		it.currentJ = 0
		it.currentI += it.chunkRows
	}
	it.hasMore = it.currentI < it.resultRows
	return it.hasMore
}

// Current returns the current starting row (i) and column (j) of the chunk.
func (it *MatMulIterator) Current() (i, j int) {
	return it.currentI, it.currentJ
}

// CurrentChunkSize returns the actual size of the current chunk.
func (it *MatMulIterator) CurrentChunkSize() (rows, cols int) {
	rows = it.chunkRows
	if it.currentI+rows > it.resultRows {
		rows = it.resultRows - it.currentI
	}
	cols = it.chunkCols
	if it.currentJ+cols > it.resultCols {
		cols = it.resultCols - it.currentJ
	}
	return rows, cols
}

// NewMatMul4DIterator creates a new MatMul4DIterator with initial indices.
func NewMatMul4DIterator(batchSize, numHeads, resultRows, resultCols int) *MatMul4DIterator {
	return &MatMul4DIterator{
		batchSize:	batchSize,
		numHeads:	numHeads,
		resultRows:	resultRows,
		resultCols:	resultCols,

		chunkSizeRows:	32,
		chunkSizeCols:	32,

		currentB:	0,
		currentH:	0,
		currentI:	0,
		currentJ:	-1,
	}
}

// Next updates the iterator's internal indices to move to the next element
// in the 4D result tensor. It returns true if there are more elements, false otherwise.
func (it *MatMul4DIterator) Next() bool {
	it.currentJ += it.chunkSizeCols

	if it.currentJ >= it.resultCols {
		it.currentJ = 0
		it.currentI += it.chunkSizeRows

		if it.currentI >= it.resultRows {
			it.currentI = 0
			it.currentH++

			if it.currentH >= it.numHeads {
				it.currentH = 0
				it.currentB++
			}
		}
	}

	return it.currentB < it.batchSize
}

// GobEncode implements the gob.GobEncoder interface.
func (t *Tensor) GobEncode() ([]byte, error) {
	var buf bytes.Buffer

	shapeLen := int32(len(t.Shape))
	if err := binary.Write(&buf, binary.LittleEndian, shapeLen); err != nil {
		return nil, err
	}
	for _, dim := range t.Shape {
		if err := binary.Write(&buf, binary.LittleEndian, int32(dim)); err != nil {
			return nil, err
		}
	}

	dataLen := int32(len(t.Data))
	if err := binary.Write(&buf, binary.LittleEndian, dataLen); err != nil {
		return nil, err
	}

	if err := binary.Write(&buf, binary.LittleEndian, t.Data); err != nil {
		return nil, err
	}

	// Write RequiresGrad
	var reqGradByte byte
	if t.RequiresGrad {
		reqGradByte = 1
	}
	if err := buf.WriteByte(reqGradByte); err != nil {
		return nil, err
	}

	if t.Mask == nil {
		if err := buf.WriteByte(0); err != nil {
			return nil, err
		}
	} else {
		if err := buf.WriteByte(1); err != nil {
			return nil, err
		}
		maskBytes, err := t.Mask.GobEncode()
		if err != nil {
			return nil, err
		}

		maskLen := int32(len(maskBytes))
		if err := binary.Write(&buf, binary.LittleEndian, maskLen); err != nil {
			return nil, err
		}
		if _, err := buf.Write(maskBytes); err != nil {
			return nil, err
		}
	}

	return buf.Bytes(), nil
}

// GobDecode implements the gob.GobDecoder interface.
func (t *Tensor) GobDecode(data []byte) error {
	reader := bytes.NewReader(data)

	// Read shape length
	var shapeLen int32
	if err := binary.Read(reader, binary.LittleEndian, &shapeLen); err != nil {
		return err
	}
	t.Shape = make([]int, shapeLen)
	for i := range t.Shape {
		var dim int32
		if err := binary.Read(reader, binary.LittleEndian, &dim); err != nil {
			return err
		}
		t.Shape[i] = int(dim)
	}

	// Read data length
	var dataLen int32
	if err := binary.Read(reader, binary.LittleEndian, &dataLen); err != nil {
		return err
	}
	t.Data = make([]float32, dataLen)
	if err := binary.Read(reader, binary.LittleEndian, t.Data); err != nil {
		return err
	}

	reqGradByte, err := reader.ReadByte()
	if err != nil {
		return err
	}
	t.RequiresGrad = reqGradByte == 1

	maskFlag, err := reader.ReadByte()
	if err != nil {
		return err
	}
	if maskFlag == 0 {
		t.Mask = nil
	} else {
		var maskLen int32
		if err := binary.Read(reader, binary.LittleEndian, &maskLen); err != nil {
			return err
		}
		maskBytes := make([]byte, maskLen)
		if _, err := reader.Read(maskBytes); err != nil {
			return err
		}
		t.Mask = &Tensor{}
		if err := t.Mask.GobDecode(maskBytes); err != nil {
			return err
		}
	}

	t.Device = CPU
	return nil
}

// NewTensor creates a new Tensor with the given shape and optional data on the CPU.
func NewTensor(shape []int, data []float32, requiresGrad bool) *Tensor {
	if data == nil {
		size := 1
		for _, dim := range shape {
			size *= dim
		}
		data = make([]float32, size)
	}
	return &Tensor{
		Data:		data,
		Shape:		shape,
		Device:		CPU,
		RequiresGrad:	requiresGrad,
	}
}

