			data[i] *= alpha
		}
	}
}

// vecMatMul performs a generic matrix multiplication (C = A @ B).
// A: [m x k], B: [k x n], C: [m x n]
func MatMulRaw(a, b, res []float32, m, n, k int) {
	if m < 4 {
		matMulRawSequential(a, b, res, m, n, k, 0, m)
		return
	}

	numWorkers := 8
	if m < 8 {
		numWorkers = m
	}

	var wg sync.WaitGroup
	rowsPerWorker := (m + numWorkers - 1) / numWorkers
	for w := 0; w < numWorkers; w++ {
		startRow := w * rowsPerWorker
		endRow := startRow + rowsPerWorker
		if startRow >= m {
			break
		}
		if endRow > m {
			endRow = m
		}
		wg.Add(1)
		go func(sRow, eRow int) {
			defer wg.Done()
			matMulRawSequential(a, b, res, m, n, k, sRow, eRow)
		}(startRow, endRow)
	}
	wg.Wait()
}

func matMulRawSequential(a, b, res []float32, m, n, k, startRow, endRow int) {

	for i := startRow; i < endRow; i++ {
		rowA := a[i*k : (i+1)*k]
		rowRes := res[i*n : (i+1)*n]
		for ik := 0; ik < k; ik++ {
			aik := rowA[ik]
			if aik == 0 {
				continue
			}
			rowB := b[ik*n : (ik+1)*n]
			for j := 0; j < n; j++ {
				rowRes[j] += aik * rowB[j]
			}
		}
	}
}

type BPEMerge struct {
	Left	string
	Right	string
}

type BPETokenizer struct {
	// Vocabulary maps subword tokens to IDs (compatible with mainvocab.Vocabulary)
	Vocab	*mainvocab.Vocabulary

	// Merges ordered list of learned merges (applied in order during encoding)
	Merges	[]BPEMerge

	// MaxVocabSize target vocabulary size (default ~16k)
	MaxVocabSize	int

	// SpecialTokens tracks control tokens that should never be split
	SpecialTokens	map[string]bool
}

// NewBPETokenizer creates a BPE tokenizer with the given target vocab size.
func NewBPETokenizer(vocabSize int) *BPETokenizer {
	return &BPETokenizer{
		Vocab:		mainvocab.NewVocabulary(),
		Merges:		make([]BPEMerge, 0),
		MaxVocabSize:	vocabSize,
		SpecialTokens:	make(map[string]bool),
	}
}

// AddSpecialToken registers a token that should never be split by BPE.
func (b *BPETokenizer) AddSpecialToken(tok string) {
	b.SpecialTokens[tok] = true
	b.Vocab.AddToken(tok)
}

// collectCorpus scans Go source files and CSV text data to build a word frequency map.
func (b *BPETokenizer) collectCorpus(projectRoot string) (map[string]int, error) {
	freq := make(map[string]int)

	err := filepath.Walk(filepath.Join(projectRoot, "internal"), func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return nil
		}
		words := tokenizeSource(string(data))
		for _, w := range words {
			freq[w]++
		}
		return nil
	})
	if err != nil {
		log.Printf("⚠️  BPE corpus: error walking internal/ (Go files): %v", err)
	}

	filepath.Walk(filepath.Join(projectRoot, "cmd"), func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return nil
		}
		words := tokenizeSource(string(data))
		for _, w := range words {
			freq[w]++
		}
		return nil
	})

	csvFiles := []string{
		filepath.Join(projectRoot, "data/training/trainingdata/conversations.csv"),
		filepath.Join(projectRoot, "data/training/trainingdata/conversing.csv"),
		filepath.Join(projectRoot, "data/training/trainingdata/synthetic_pairs.csv"),
	}
	for _, csvPath := range csvFiles {
		data, err := os.ReadFile(csvPath)
		if err != nil {
			log.Printf("⚠️  BPE corpus: cannot read %s: %v", csvPath, err)
			continue
		}
		words := tokenizeText(string(data))
		for _, w := range words {
			freq[w]++
		}
	}

	return freq, nil
}

// tokenizeSource splits Go source code into tokens (preserving identifiers, keywords, operators).
func tokenizeSource(text string) []string {
	var tokens []string
	var current strings.Builder
	runes := []rune(text)

	flush := func() {
		if current.Len() > 0 {
			tokens = append(tokens, current.String())
			current.Reset()
		}
	}

	for _, r := range runes {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {

				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

// tokenizeText splits natural language text into word tokens.
func tokenizeText(text string) []string {
	var tokens []string
	var current strings.Builder

	flush := func() {
		if current.Len() > 0 {
			word := strings.ToLower(current.String())
			if word != "" {
				tokens = append(tokens, word)
			}
			current.Reset()
		}
	}

	for _, r := range text {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\'' || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {
				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

// Train runs the BPE training algorithm on the corpus and builds the vocabulary.
func (b *BPETokenizer) Train(projectRoot string) error {
	log.Printf("📚 BPE: Collecting corpus (Go source + CSV text data)...")
	freq, err := b.collectCorpus(projectRoot)
	if err != nil {
		return fmt.Errorf("BPE corpus collection failed: %w", err)
	}
	log.Printf("📚 BPE: Collected %d unique word types from corpus", len(freq))

	for tok := range b.SpecialTokens {
		delete(freq, tok)
	}

	for tok := range b.SpecialTokens {
		b.Vocab.AddToken(tok)
	}

	// Convert words to character-level representations for BPE
	type wordEntry struct {
		text	string
		freq	int
		chars	[]string	// current segmentation
	}
	entries := make([]*wordEntry, 0, len(freq))
	for word, count := range freq {
		if count < 1 || word == "" {
			continue
		}
		chars := make([]string, 0)
		for _, r := range word {
			chars = append(chars, string(r))

			b.Vocab.AddToken(string(r))
		}
		entries = append(entries, &wordEntry{text: word, freq: count, chars: chars})
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].freq > entries[j].freq
	})

	log.Printf("📚 BPE: Starting merge training (target vocab size: %d)...", b.MaxVocabSize)

	uniqueSubwords := make(map[string]bool)
	for _, e := range entries {
		for _, c := range e.chars {
			uniqueSubwords[c] = true
		}
	}

	for len(uniqueSubwords) < b.MaxVocabSize && len(entries) > 0 {

		pairFreq := make(map[[2]string]int)
		for _, e := range entries {
			for i := 0; i < len(e.chars)-1; i++ {
				key := [2]string{e.chars[i], e.chars[i+1]}
				pairFreq[key] += e.freq
			}
		}

		if len(pairFreq) == 0 {
			break
		}

		// Find the most frequent pair
		var bestPair [2]string
		bestCount := 0
		for pair, count := range pairFreq {
			if count > bestCount {
				bestCount = count
				bestPair = pair
			}
		}

		if bestCount < 2 {
			break
		}

		merged := bestPair[0] + bestPair[1]
		b.Merges = append(b.Merges, BPEMerge{Left: bestPair[0], Right: bestPair[1]})
		b.Vocab.AddToken(merged)
		uniqueSubwords[merged] = true

		for _, e := range entries {
			var newChars []string
			i := 0
			for i < len(e.chars) {
				if i+1 < len(e.chars) && e.chars[i] == bestPair[0] && e.chars[i+1] == bestPair[1] {
					newChars = append(newChars, merged)
					i += 2
				} else {
					newChars = append(newChars, e.chars[i])
					i++
				}
			}
			e.chars = newChars
		}
	}

	log.Printf("📚 BPE: Training complete. Vocab size: %d, Merges: %d", b.Vocab.Size(), len(b.Merges))
	return nil
}

// Encode converts a text string into a slice of token IDs using special token matching and BPE merges.
func (b *BPETokenizer) Encode(text string) []int {
	if len(text) == 0 {
		return nil
	}

	var ids []int
	remaining := text

	for len(remaining) > 0 {
		matchedSpecial := false

		for specTok := range b.SpecialTokens {
			if strings.HasPrefix(remaining, specTok) {
				if id := b.Vocab.GetTokenID(specTok); id >= 0 {
					ids = append(ids, id)
					remaining = remaining[len(specTok):]
					matchedSpecial = true
					break
				}
			}
		}

		if matchedSpecial {
			continue
		}

		nextSpecialIdx := len(remaining)
		for specTok := range b.SpecialTokens {
			if idx := strings.Index(remaining, specTok); idx > 0 && idx < nextSpecialIdx {
				nextSpecialIdx = idx
			}
		}

		chunk := remaining[:nextSpecialIdx]
		remaining = remaining[nextSpecialIdx:]

		words := tokenizeText(chunk)
		for _, word := range words {
			if word == "\n" {
				if id := b.Vocab.GetTokenID(word); id >= 0 {
					ids = append(ids, id)
				}
				continue
			}

			segments := b.segmentWord(word)
			for _, seg := range segments {
				id := b.Vocab.GetTokenID(seg)
				if id < 0 {
					id = b.Vocab.UnkID
				}
				ids = append(ids, id)
			}
		}
	}

	return ids
}

// segmentWord applies learned BPE merges to segment a single word into subword units.
func (b *BPETokenizer) segmentWord(word string) []string {
	if word == "" {
		return nil
	}

	segments := make([]string, 0, len(word))
	for _, r := range word {
		segments = append(segments, string(r))
	}

	for _, merge := range b.Merges {
		var newSegments []string
		i := 0
		for i < len(segments) {
			if i+1 < len(segments) && segments[i] == merge.Left && segments[i+1] == merge.Right {
				newSegments = append(newSegments, merge.Left+merge.Right)
				i += 2
			} else {
				newSegments = append(newSegments, segments[i])
				i++
			}
		}
		segments = newSegments
	}

	return segments
}

// Decode converts token IDs back to text.
func (b *BPETokenizer) Decode(ids []int) string {
	var parts []string
	for _, id := range ids {
		word := b.Vocab.GetWord(id)
		if word == "" || word == "<pad>" || word == "UNK" {
			continue
		}
		if word == "</s>" || word == "<s>" {
			continue
		}

		if id == b.Vocab.BosID || id == b.Vocab.EosID {
			continue
		}
		parts = append(parts, word)
	}
	return strings.Join(parts, " ")
}

// Save persists the BPE tokenizer (vocab + merges) to a GOB file.
func (b *BPETokenizer) Save(path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("mkdir %s: %w", dir, err)
	}
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create %s: %w", path, err)
	}
	defer f.Close()
	return gob.NewEncoder(f).Encode(b)
}

// LoadBPETokenizer loads a BPE tokenizer from a GOB file.
func LoadBPETokenizer(path string) (*BPETokenizer, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()
	var b BPETokenizer
	if err := gob.NewDecoder(f).Decode(&b); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	return &b, nil
}

// TrainBPETokenizer is a convenience function that creates, trains, and saves
// a BPE tokenizer. Returns the path to the saved model.
func TrainBPETokenizer(projectRoot string, vocabSize int) (string, error) {
	bpe := NewBPETokenizer(vocabSize)

	bpe.AddSpecialToken("<|im_start|>")
	bpe.AddSpecialToken("<|im_end|>")
	bpe.AddSpecialToken("<pad>")
	bpe.AddSpecialToken("<s>")
	bpe.AddSpecialToken("</s>")
	bpe.AddSpecialToken("UNK")
	bpe.AddSpecialToken("\n")

	if err := bpe.Train(projectRoot); err != nil {
		return "", fmt.Errorf("BPE training failed: %w", err)
	}

	path := filepath.Join(projectRoot, "data/models/gob_models/bpe_tokenizer.gob")
	if err := bpe.Save(path); err != nil {
		return "", fmt.Errorf("BPE save failed: %w", err)
	}

	vocabPath := filepath.Join(projectRoot, "data/models/gob_models/bpe_vocabulary.gob")
	if err := bpe.Vocab.Save(vocabPath); err != nil {
		log.Printf("⚠️  BPE vocab save warning: %v", err)
	}

	log.Printf("✅ BPE Tokenizer saved to %s (vocab=%d, merges=%d)", path, bpe.Vocab.Size(), len(bpe.Merges))
	return path, nil
}

// AddGoTokensToTokenizer adds all Go-specific high-frequency tokens to the given BPE tokenizer.
func AddGoTokensToTokenizer(bpe *BPETokenizer) {
	tokens := GoHighFreqTokens()
	for _, tok := range tokens {

		bpe.AddSpecialToken(tok)

		if strings.Contains(tok, " ") {
			protected := strings.ReplaceAll(tok, " ", "\u00A0")
			bpe.AddSpecialToken(protected)
		}
	}
	log.Printf("🧩 Go Tokenizer: Added %d Go-specific high-frequency tokens to vocabulary", len(tokens))
}

// IsGoHighFreqToken checks if a given text is a registered Go high-frequency token.
func IsGoHighFreqToken(text string) bool {
	for _, tok := range GoHighFreqTokens() {
		if tok == text {
			return true
		}
	}
	return false
}

// GoTokenizePreprocess replaces registered multi-character Go tokens
// with exact special token identifiers that the BPE encoder recognizes.
func GoTokenizePreprocess(code string) string {
	result := code

	tokens := GoHighFreqTokens()
	for _, tok := range tokens {
		if len(tok) > 1 && strings.Contains(result, tok) {

			result = strings.ReplaceAll(result, tok, tok)
		}
	}
	return result
}

// protectPattern replaces spaces inside high-frequency phrases with
// a non-breaking space (U+00A0) or special boundary marker so the BPE
// encoder treats the entire sequence as a single atomic token unit.
func protectPattern(code, pattern string) string {
	if !strings.Contains(code, pattern) {
		return code
	}

	protected := strings.ReplaceAll(pattern, " ", "\u00A0")
	return strings.ReplaceAll(code, pattern, protected)
}

type Tokenizer struct {
	// Reference the Vocabulary type from the tagger/vocab package
	Vocabulary *vocab.Vocabulary
}

// NewTokenizer creates a new Tokenizer for the MoE package,
// using a Vocabulary from the tagger/vocab package.
func NewTokenizer(vocabulary *vocab.Vocabulary) (*Tokenizer, error) {
	if vocabulary == nil {
		return nil, errors.New("vocabulary cannot be nil for MoE tokenizer")
	}
	return &Tokenizer{
			Vocabulary: vocabulary,
		},
		nil
}

// Encode converts a string into a slice of token IDs using the tagger/vocab Vocabulary.
// This is a basic implementation using whitespace tokenization.
func (t *Tokenizer) Encode(text string) ([]int, error) {
	if t.Vocabulary == nil {
		return nil, errors.New("tokenizer's vocabulary is not set")
	}

	tokenIDs, err := TokenizeAndConvertToIDs(text, t.Vocabulary, -1)
	if err != nil {
		return nil, err
	}

	return tokenIDs, nil
}

// Decode converts a slice of token IDs back into a string using the tagger/vocab Vocabulary.
// This version is JSON-aware and does not add extra spaces or punctuation.
func (t *Tokenizer) Decode(tokenIDs []int) (string, error) {
	if t.Vocabulary == nil {
		return "", errors.New("tokenizer's vocabulary is not set")
	}

	var sb strings.Builder
	var lastToken string
	for _, id := range tokenIDs {

		word := t.Vocabulary.GetWord(id)
		if word == "" {
			word = fmt.Sprintf("[%d]", id)
		}

		if sb.Len() > 0 && !isJSONPunct(lastToken) && !isJSONPunct(word) {
			sb.WriteString(" ")
		}
		sb.WriteString(word)
		lastToken = word
	}

	return sb.String(), nil
}

func isJSONPunct(s string) bool {
	if len(s) != 1 {
		return false
	}
	return strings.ContainsRune(`{}[],:"`, []rune(s)[0])
}

// Tokenize splits a string into words based on whitespace and JSON punctuation.
func Tokenize(text string) []string {
	var tokens []string
	runes := []rune(text)
	i := 0
	for i < len(runes) {
		r := runes[i]

		if unicode.IsSpace(r) {
			i++
			continue
		}

		if strings.ContainsRune(`{}[],:"?!.`, r) {
			tokens = append(tokens, string(r))
			i++
			continue
		}

		start := i
		for i < len(runes) && !unicode.IsSpace(runes[i]) && !strings.ContainsRune(`{}[],:"?!.`, runes[i]) {
			i++
		}
		token := string(runes[start:i])
		if token != "" {
			tokens = append(tokens, token)
		}
	}
	return tokens
}

// TokenizeAndConvertToIDs converts a string of text into a slice of token IDs
// using the provided vocabulary and pads the sequence to a maximum length.
// This version is more JSON-aware.
func TokenizeAndConvertToIDs(text string, vocab *vocab.Vocabulary, maxLen int) ([]int, error) {
	if vocab == nil {
		return nil, errors.New("vocabulary is nil")
	}

	tokenIDs := []int{}

	runes := []rune(text)
	i := 0
	for i < len(runes) {
		r := runes[i]

		if unicode.IsSpace(r) {
			i++
			continue
		}

		if strings.ContainsRune(`{}[],:"?!.`, r) {
			tokenIDs = append(tokenIDs, vocab.GetTokenID(string(r)))
			i++
			continue
		}

		start := i
		for i < len(runes) && !unicode.IsSpace(runes[i]) && !strings.ContainsRune(`{}[],:"`, runes[i]) {
			i++
		}
		token := string(runes[start:i])
		if token != "" {

			id := vocab.GetTokenID(token)
			if id == vocab.UnkID && len(token) > 4 {

				p1 := token[:3]
				p2 := token[3:]
				tokenIDs = append(tokenIDs, vocab.GetTokenID(p1))
				tokenIDs = append(tokenIDs, vocab.GetTokenID(p2))
			} else {
				tokenIDs = append(tokenIDs, id)
			}
		}
	}

	if maxLen != -1 {
		if len(tokenIDs) > maxLen {
			tokenIDs = tokenIDs[:maxLen]
		} else if len(tokenIDs) < maxLen {
			paddingSize := maxLen - len(tokenIDs)
			padding := make([]int, paddingSize)
			for i := range padding {
				padding[i] = vocab.GetTokenID("<pad>")
			}
			tokenIDs = append(tokenIDs, padding...)
		}
	}

	return tokenIDs, nil
}

type Executor struct {
	ruleEngine *RuleEngine	// Add the rule engine
}

// NewExecutor creates a new Executor.
func NewExecutor() *Executor {
	re := NewRuleEngine()
	re.RegisterDefaultCreateRules()
	re.RegisterDefaultExecuteRules()
	re.RegisterDefaultWriteFileRules()
	re.RegisterDefaultStartRules()
	re.RegisterDefaultDeleteRules()
	re.RegisterDefaultMoveRules()

	return &Executor{
		ruleEngine: re,
	}
}

// ExecuteWorkflow executes the given workflow by traversing its nodes
// in topological order.
func (e *Executor) ExecuteWorkflow(wf *Workflow) error {
	if wf == nil {
		return fmt.Errorf("workflow cannot be nil")
	}

	sortedNodeIDs, err := wf.TopologicalSort()
	if err != nil {
		return fmt.Errorf("failed to get topological sort of workflow: %w", err)
	}

	log.Printf("Executing workflow with %d nodes in topological order: %v", len(sortedNodeIDs), sortedNodeIDs)

	for _, nodeID := range sortedNodeIDs {
		node := wf.GetNode(nodeID)
		if node == nil {
			return fmt.Errorf("node with ID '%s' not found in workflow", nodeID)
		}

		log.Printf("Executing node '%s': Operation=%s, ResourceType=%s, ResourceName=%s, Directory=%s",
			node.ID, node.Operation, node.Resource.Type, node.Resource.Name, node.Directory)

		if err := e.executeNode(node); err != nil {
			return fmt.Errorf("failed to execute node '%s': %w", node.ID, err)
		}
	}

	log.Println("Workflow execution completed successfully.")
	return nil
}

// executeNode performs the action defined by a single workflow node.
func (e *Executor) executeNode(node *Node) error {

	semantic.InferProperties(&node.Resource)

	if err := semantic.ValidateResource(&node.Resource, node.Context); err != nil {
		return fmt.Errorf("resource validation failed for node '%s': %w", node.ID, err)
	}

	log.Printf("Node Resource Type before rule execution: %s", node.Resource.Type)

	if err := e.ruleEngine.ExecuteRules(node); err != nil {
		return fmt.Errorf("failed to execute node operation via rule engine: %w", err)
	}

	return nil
}

// GenerateWorkflow takes a SemanticOutput and converts it into a Workflow DAG.
func GenerateWorkflow(so *semantic.SemanticOutput) (*Workflow, error) {
	if so == nil {
		return nil, fmt.Errorf("SemanticOutput cannot be nil")
	}

	wf := NewWorkflow()

	primaryResource := so.TargetResource
	primaryNodeID := generateNodeID(primaryResource.Type, primaryResource.Name, 0)
	primaryNode := &Node{
		ID:		primaryNodeID,
		Operation:	OperationType(so.Operation),
		Resource:	*primaryResource,
		Directory:	primaryResource.Directory,
	}

	if primaryNode.Operation == OperationExecute {
		primaryNode.Command = so.Command
		if primaryNode.Command == "" {
			fmt.Print("\nEnter a command to execute: ")
			reader := bufio.NewReader(os.Stdin)
			input, _ := reader.ReadString('\n')
			input = strings.TrimSpace(input)

			if input == "" {
				return nil, fmt.Errorf("command cannot be empty for EXECUTE operation")
			}
			primaryNode.Command = input
		}
	}

	if primaryNode.Resource.Name == "" {
		fmt.Print("\nEnter a resource name: ")
		reader := bufio.NewReader(os.Stdin)
		input, _ := reader.ReadString('\n')
		input = strings.TrimSpace(input)

		if input == "" {
			return nil, fmt.Errorf("resource name cannot be empty")
		}
		primaryNode.Resource.Name = input
	}

	if err := wf.AddNode(primaryNode); err != nil {
		return nil, fmt.Errorf("failed to add primary node to workflow: %w", err)
	}

	if file, ok := so.TargetResource.Properties["file"]; ok {
		if fileName, ok := file.(string); ok {
			fileNodeID := generateNodeID("file", fileName, 0)
			fileNode := &Node{
				ID:		fileNodeID,
				Operation:	OperationWriteFile,
				FilePath:	fileName,
				Content:	"",
				Dependencies:	[]string{primaryNodeID},
				Directory:	fmt.Sprintf("%s/%s", so.TargetResource.Directory, so.TargetResource.Name),
			}
			if err := wf.AddNode(fileNode); err != nil {
				return nil, fmt.Errorf("failed to add file node: %w", err)
			}
		}
	}

	if primaryResource.Type == "Filesystem::File" && so.Operation == "CREATE" {
		createFileNodeID := generateNodeID("file", "createfile", 0)
		createFileNode := &Node{
			ID:		createFileNodeID,
			Operation:	OperationWriteFile,
			Resource:	*primaryResource,
			FilePath:	primaryResource.Name,
			Content:	primaryResource.Content,
			Dependencies:	[]string{primaryNodeID},
			Directory:	primaryResource.Directory,
		}
		if err := wf.AddNode(createFileNode); err != nil {
			return nil, fmt.Errorf("failed to add create file node to workflow: %w", err)
		}
	}

	if err := addChildrenNodes(*primaryResource, primaryNodeID, wf, so.Operation, primaryResource.Name); err != nil {
		return nil, err
	}

	return wf, nil
}

// addChildrenNodes recursively adds nodes for child resources.
// currentParentPath is the full relative path to the parentResource from the application's CWD.
func addChildrenNodes(parentResource semantic.Resource, parentNodeID string, wf *Workflow, operation string, currentParentPath string) error {
	for i, childResource := range parentResource.Children {
		childNodeID := generateNodeID(childResource.Type, childResource.Name, i)

		childNodeDirectory := currentParentPath

		childNode := &Node{
			ID:		childNodeID,
			Operation:	OperationType(operation),
			Resource:	childResource,
			Dependencies:	[]string{parentNodeID},
			Directory:	childNodeDirectory,
		}
		if err := wf.AddNode(childNode); err != nil {
			return fmt.Errorf("failed to add child node to workflow: %w", err)
		}

		if childResource.Type == "Deployment::GoWebserver" && operation == "CREATE" {
		} else if childResource.Type == "Filesystem::File" && operation == "CREATE" {

			createFileNodeID := generateNodeID("file", "createfile", i)
			createFileNode := &Node{
				ID:		createFileNodeID,
				Operation:	OperationWriteFile,
				FilePath:	childResource.Name,
				Content:	childResource.Content,
				Dependencies:	[]string{childNodeID},
				Directory:	childNodeDirectory,
			}
			if err := wf.AddNode(createFileNode); err != nil {
				return fmt.Errorf("failed to add create file node to workflow: %w", err)
			}
		}

		if err := addChildrenNodes(childResource, childNodeID, wf, operation, childNodeDirectory+"/"+childResource.Name); err != nil {
			return err
		}
	}
	return nil
}

func generateNodeID(resourceType, resourceName string, index int) string {
	return fmt.Sprintf("%s-%s-%d", resourceType, resourceName, index)
}

// RegisterDefaultMoveRules registers rules for move operations.
func (re *RuleEngine) RegisterDefaultMoveRules() {
	re.RegisterRule(
		RuleCondition{Operation: "MOVE", ResourceType: "Filesystem::File"},
		func(node *Node) error {
			sourcePath := node.Resource.Name
			destinationPath := node.Resource.Destination
			if err := os.Rename(sourcePath, destinationPath); err != nil {
				return fmt.Errorf("failed to move file from %s to %s: %w", sourcePath, destinationPath, err)
			}
			return nil
		},
	)
}

type RuleCondition struct {
	Operation	OperationType
	ResourceType	string
}

type Rule struct {
	Condition	RuleCondition
	Action		RuleAction
}

type RuleEngine struct {
	rules []Rule
}

// NewRuleEngine creates a new RuleEngine.
func NewRuleEngine() *RuleEngine {
	return &RuleEngine{
		rules: make([]Rule, 0),
	}
}

// RegisterRule adds a new rule to the engine.
func (re *RuleEngine) RegisterRule(condition RuleCondition, action RuleAction) {
	re.rules = append(re.rules, Rule{Condition: condition, Action: action})
}

// ExecuteRules evaluates the rules against a given node and executes the action of the first matching rule.
func (re *RuleEngine) ExecuteRules(node *Node) error {
	for _, rule := range re.rules {

		if rule.Condition.Operation == node.Operation && (rule.Condition.ResourceType == "" || rule.Condition.ResourceType == node.Resource.Type) {
			log.Printf("Applying rule for Operation=%s, ResourceType=%s", node.Operation, node.Resource.Type)
			return rule.Action(node)
		}
	}
	return fmt.Errorf("no rule found for Operation=%s, ResourceType=%s", node.Operation, node.Resource.Type)
}

// RegisterDefaultCreateRules registers the default rules for CREATE operations.
func (re *RuleEngine) RegisterDefaultCreateRules() {
	re.RegisterRule(
		RuleCondition{Operation: OperationCreate, ResourceType: "Filesystem::Folder"},
		func(node *Node) error {
			folderPath := node.Resource.Name
			if node.Directory != "" {
				folderPath = filepath.Join(node.Directory, node.Resource.Name)
			}
			log.Printf("Creating folder: %s", folderPath)
			if err := os.MkdirAll(folderPath, 0755); err != nil {
				return fmt.Errorf("failed to create folder %s: %w", folderPath, err)
			}
			return nil
		},
	)

	re.RegisterRule(
		RuleCondition{Operation: OperationCreate, ResourceType: "Deployment::GoWebserver"},
		func(node *Node) error {
			log.Printf("Simulating Go Webserver deployment: %s on port %v with image %s",
				node.Resource.Name, node.Resource.Properties["port"], node.Resource.Properties["runtime_image"])
			folderPath := node.Resource.Name
			if node.Directory != "" {
				folderPath = filepath.Join(node.Directory, node.Resource.Name)
			}
			log.Printf("Creating folder for GoWebserver: %s", folderPath)
			if err := os.MkdirAll(folderPath, 0755); err != nil {
				return fmt.Errorf("failed to create folder %s: %w", folderPath, err)
			}
			return nil
		},
	)

	re.RegisterRule(
		RuleCondition{Operation: OperationCreate, ResourceType: "Filesystem::File"},
		func(node *Node) error {
			filePath := node.Resource.Name
			if node.Directory != "" {
				filePath = filepath.Join(node.Directory, filePath)
			}

			log.Printf("Creating file: %s", filePath)

			dir := filepath.Dir(filePath)
			if dir != "." && dir != "/" {
				if err := os.MkdirAll(dir, 0755); err != nil {
					return fmt.Errorf("failed to create directory %s: %w", dir, err)
				}
			}

			file, err := os.Create(filePath)
			if err != nil {
				return fmt.Errorf("failed to create file %s: %w", filePath, err)
			}
			file.Close()

			return nil
		},
	)
}

// RegisterDefaultExecuteRules registers the default rules for EXECUTE operations.
func (re *RuleEngine) RegisterDefaultExecuteRules() {
	re.RegisterRule(
		RuleCondition{Operation: OperationExecute, ResourceType: ""},
		func(node *Node) error {
			if node.Command == "" {
				return fmt.Errorf("EXECUTE operation requires a command")
			}
			log.Printf("Executing command: %s in directory: %s", node.Command, node.Directory)

			if strings.HasPrefix(node.Command, "go mod init") {
				goModPath := "go.mod"
				if node.Directory != "" {
					goModPath = filepath.Join(node.Directory, "go.mod")
				}
				if _, err := os.Stat(goModPath); err == nil {
					log.Printf("go.mod already exists, skipping 'go mod init'.")
					return nil
				}
			}

			cmd := exec.Command("bash", "-c", node.Command)
			if node.Directory != "" {
				cmd.Dir = node.Directory
			}
			output, err := cmd.CombinedOutput()
			if err != nil {
				return fmt.Errorf("command execution failed: %s, output: %s", err, string(output))
			}

			log.Printf("Command output: %s", string(output))
			return nil
		},
	)
}

// RegisterDefaultWriteFileRules registers the default rules for WRITE_FILE operations.
func (re *RuleEngine) RegisterDefaultWriteFileRules() {
	re.RegisterRule(
		RuleCondition{Operation: OperationWriteFile, ResourceType: ""},
		func(node *Node) error {
			if node.FilePath == "" {
				return fmt.Errorf("WRITE_FILE operation requires a file path")
			}

			filePath := node.FilePath
			if node.Directory != "" {
				filePath = filepath.Join(node.Directory, filePath)
			}

			log.Printf("Writing file: %s", filePath)

			if err := os.WriteFile(filePath, []byte(node.Content), 0644); err != nil {
				return fmt.Errorf("failed to write file %s: %w", filePath, err)
			}
			return nil
		},
	)
}

// RegisterDefaultStartRules registers the default rules for START operations.
func (re *RuleEngine) RegisterDefaultStartRules() {
	re.RegisterRule(
		RuleCondition{Operation: OperationStart, ResourceType: ""},
		func(node *Node) error {
			if node.Command == "" {
				return fmt.Errorf("START operation requires a command")
			}
			log.Printf("Starting process: %s (in background) in directory: %s", node.Command, node.Directory)

			cmd := exec.Command("bash", " -c", node.Command)
			if node.Directory != "" {
				cmd.Dir = node.Directory
			}

			err := cmd.Start()
			if err != nil {
				return fmt.Errorf("failed to start command: %w", err)
			}
			log.Printf("Process started with PID: %d", cmd.Process.Pid)
			return nil
		},
	)
}

