// NewPlanner creates a new planner with the given symbol graph.
func NewPlanner(sg *symbol.SymbolGraph, rootDir string, engine LLMEngine) *Planner {
	return &Planner{
		symbolGraph:	sg,
		rootDir:	rootDir,
		workDir:	filepath.Join(rootDir, ".gollemer_work"),
		maxRetries:	3,
		llm:		engine,
		conceptMatcher:	NewConceptMatcher(),
	}
}

// Explore performs Phase 1: search for symbols, find references, trace call graph.
// Accepts both plain symbol names and natural language queries (e.g. "Add caching layer to SymbolGraph").
// The query is tokenized into candidate words, each of which is searched in the symbol graph.
func (p *Planner) Explore(query string) (*ExplorationResult, error) {

	start := time.Now()
	result := &ExplorationResult{
		Query:			query,
		FoundSymbols:		make([]*symbol.Symbol, 0),
		AffectedFiles:		make([]AffectedFile, 0),
		CallGraph:		make(map[string][]string),
		References:		make([]*symbol.Reference, 0),
		FileDependencies:	make(map[string][]string),
	}

	candidates := extractSymbolCandidates(query)

	seenSymbols := make(map[string]bool)
	seenFiles := make(map[string]bool)
	for _, cand := range candidates {
		syms := p.symbolGraph.SearchSymbols(cand)
		for _, sym := range syms {
			key := fmt.Sprintf("%s:%s:%d", sym.Name, sym.File, sym.Line)
			if !seenSymbols[key] {
				seenSymbols[key] = true
				result.FoundSymbols = append(result.FoundSymbols, sym)
			}
		}
	}

	seenSymbols = make(map[string]bool)
	for _, cand := range candidates {
		syms := p.symbolGraph.SearchSymbols(cand)
		for _, sym := range syms {
			key := fmt.Sprintf("%s:%s:%d", sym.Name, sym.File, sym.Line)
			if !seenSymbols[key] {
				seenSymbols[key] = true
				result.FoundSymbols = append(result.FoundSymbols, sym)
			}
		}
	}

	for _, sym := range result.FoundSymbols {

		if !seenFiles[sym.File] {
			seenFiles[sym.File] = true
			result.AffectedFiles = append(result.AffectedFiles, AffectedFile{
				Path:		sym.File,
				Package:	sym.Package,
				Reason:		fmt.Sprintf("Contains %s %q", sym.Kind, sym.Name),
				Symbols:	[]string{sym.Name},
				Priority:	2,
				IsTestFile:	strings.HasSuffix(sym.File, "_test.go"),
			})
		}

		refs := p.symbolGraph.FindReferences(sym.Name)
		result.References = append(result.References, refs...)

		if sym.Kind == symbol.KindFunction || sym.Kind == symbol.KindMethod {
			callGraph := p.symbolGraph.TraceCallGraph(sym.Name, 3)
			for k, v := range callGraph {
				result.CallGraph[k] = v
			}

			callers := p.symbolGraph.FindCallers(sym.Name)
			for _, caller := range callers {
				if !seenFiles[caller.File] {
					seenFiles[caller.File] = true
					result.AffectedFiles = append(result.AffectedFiles, AffectedFile{
						Path:		caller.File,
						Package:	caller.Package,
						Reason:		fmt.Sprintf("Calls %q (caller)", sym.Name),
						Symbols:	[]string{caller.Name, sym.Name},
						Priority:	1,
						IsTestFile:	strings.HasSuffix(caller.File, "_test.go"),
					})
				}
			}

			if callees, ok := callGraph[sym.Name]; ok {
				for _, callee := range callees {
					defs := p.symbolGraph.FindDefinitions(callee)
					for _, def := range defs {
						if !seenFiles[def.File] {
							seenFiles[def.File] = true
							result.AffectedFiles = append(result.AffectedFiles, AffectedFile{
								Path:		def.File,
								Package:	def.Package,
								Reason:		fmt.Sprintf("Called by %q (callee)", sym.Name),
								Symbols:	[]string{callee, sym.Name},
								Priority:	1,
								IsTestFile:	strings.HasSuffix(def.File, "_test.go"),
							})
						}
					}
				}
			}
		}

		if sym.Kind == symbol.KindInterface {
			impls := p.symbolGraph.FindImplementations(sym.Name)
			for _, impl := range impls {
				if !seenFiles[impl.File] {
					seenFiles[impl.File] = true
					result.AffectedFiles = append(result.AffectedFiles, AffectedFile{
						Path:		impl.File,
						Package:	impl.Package,
						Reason:		fmt.Sprintf("Implements interface %q", sym.Name),
						Symbols:	[]string{impl.Name, sym.Name},
						Priority:	1,
						IsTestFile:	strings.HasSuffix(impl.File, "_test.go"),
					})
				}
			}
		}
	}

	sort.Slice(result.AffectedFiles, func(i, j int) bool {
		if result.AffectedFiles[i].Priority != result.AffectedFiles[j].Priority {
			return result.AffectedFiles[i].Priority > result.AffectedFiles[j].Priority
		}
		return result.AffectedFiles[i].Path < result.AffectedFiles[j].Path
	})

	for _, file := range result.AffectedFiles {
		deps := p.symbolGraph.GetSymbolsByFile(file.Path)
		var depFiles []string
		for _, dep := range deps {

			for _, ref := range dep.References {
				refFile := ref.File
				if refFile != "" && refFile != file.Path && seenFiles[refFile] {
					depFiles = append(depFiles, refFile)
				}
			}
		}

		depSet := make(map[string]bool)
		var uniqueDeps []string
		for _, d := range depFiles {
			if !depSet[d] {
				depSet[d] = true
				uniqueDeps = append(uniqueDeps, d)
			}
		}
		result.FileDependencies[file.Path] = uniqueDeps
	}

	result.Duration = time.Since(start)
	return result, nil
}

// Plan performs Phase 2: create an execution plan from exploration results.
func (p *Planner) Plan(goal string, exploration *ExplorationResult) (*ExecutionPlan, error) {
	plan := &ExecutionPlan{
		Goal:		goal,
		CreatedAt:	time.Now(),
		Phases:		make([]PlanPhase, 0),
	}

	plan.EstimatedChanges = len(exploration.AffectedFiles)

	directChanges := 0
	testChanges := 0
	highPriority := 0
	for _, f := range exploration.AffectedFiles {
		if f.Priority >= 2 {
			highPriority++
		}
		if f.IsTestFile {
			testChanges++
		} else {
			directChanges++
		}
	}

	if highPriority > 5 || directChanges > 10 {
		plan.RiskLevel = "high"
	} else if highPriority > 2 || directChanges > 3 {
		plan.RiskLevel = "medium"
	} else {
		plan.RiskLevel = "low"
	}

	// Build reasoning
	var reasoning strings.Builder
	reasoning.WriteString(fmt.Sprintf("## Exploration Summary\n\n"))
	reasoning.WriteString(fmt.Sprintf("Query: %q\n", goal))
	reasoning.WriteString(fmt.Sprintf("Symbols found: %d\n", len(exploration.FoundSymbols)))
	reasoning.WriteString(fmt.Sprintf("Affected files: %d (direct: %d, tests: %d)\n", len(exploration.AffectedFiles), directChanges, testChanges))
	reasoning.WriteString(fmt.Sprintf("References found: %d\n", len(exploration.References)))
	reasoning.WriteString(fmt.Sprintf("Risk level: %s\n\n", plan.RiskLevel))

	reasoning.WriteString("## Affected Files\n\n")
	for i, f := range exploration.AffectedFiles {
		priority := ""
		switch f.Priority {
		case 2:
			priority = "[HIGH]"
		case 1:
			priority = "[MED]"
		default:
			priority = "[LOW]"
		}
		reasoning.WriteString(fmt.Sprintf("%d. %s %s - %s\n", i+1, priority, f.Path, f.Reason))
		reasoning.WriteString(fmt.Sprintf("   Symbols: %s\n", strings.Join(f.Symbols, ", ")))
	}

	if len(exploration.CallGraph) > 0 {
		reasoning.WriteString("\n## Call Graph\n\n")
		for caller, callees := range exploration.CallGraph {
			reasoning.WriteString(fmt.Sprintf("  %s -> %s\n", caller, strings.Join(callees, ", ")))
		}
	}

	plan.Reasoning = reasoning.String()

	if testChanges > 0 {
		testPhase := PlanPhase{
			Name:		"Test Preparation",
			Description:	"Update test fixtures and test files to match expected new behavior",
			Steps:		make([]PlanStep, 0),
		}
		for _, f := range exploration.AffectedFiles {
			if f.IsTestFile {
				step := PlanStep{
					ID:		len(testPhase.Steps) + 1,
					Action:		"modify",
					File:		f.Path,
					Description:	fmt.Sprintf("Update test expectations in %s", filepath.Base(f.Path)),
					Details:	fmt.Sprintf("Modify tests related to: %s", strings.Join(f.Symbols, ", ")),
					Dependencies:	[]int{},
				}
				testPhase.Steps = append(testPhase.Steps, step)
			}
		}
		if len(testPhase.Steps) > 0 {
			plan.Phases = append(plan.Phases, testPhase)
		}
	}

	primaryPhase := PlanPhase{
		Name:		"Core Implementation",
		Description:	"Apply the primary code changes",
		Steps:		make([]PlanStep, 0),
	}
	for _, f := range exploration.AffectedFiles {
		if !f.IsTestFile {
			step := PlanStep{
				ID:		len(primaryPhase.Steps) + 1,
				Action:		"modify",
				File:		f.Path,
				Description:	fmt.Sprintf("Update %s - %s", filepath.Base(f.Path), f.Reason),
				Details:	fmt.Sprintf("Symbols affected: %s", strings.Join(f.Symbols, ", ")),
				Dependencies:	[]int{},
				DryRunCheck:	fmt.Sprintf("Verify %s parses correctly after change", filepath.Base(f.Path)),
			}
			primaryPhase.Steps = append(primaryPhase.Steps, step)
		}
	}
	if len(primaryPhase.Steps) > 0 {
		plan.Phases = append(plan.Phases, primaryPhase)
	}

	verifyPhase := PlanPhase{
		Name:		"Verification",
		Description:	"Run tests and linters to validate all changes",
		Steps: []PlanStep{
			{
				ID:		1,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go vet on all modified files",
				Details:	"Check for common Go mistakes",
			},
			{
				ID:		2,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go build to check compilation",
				Details:	"Ensure the entire project compiles",
			},
			{
				ID:		3,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go test on affected packages",
				Details:	"Ensure all tests pass",
			},
		},
	}
	plan.Phases = append(plan.Phases, verifyPhase)

	return plan, nil
}

// ExecutePlan runs the plan with verification after each step.
func (p *Planner) ExecutePlan(plan *ExecutionPlan, exploration *ExplorationResult) ([]PatchResult, *VerificationResult, error) {
	results := make([]PatchResult, 0)

	if err := os.MkdirAll(p.workDir, 0755); err != nil {
		return nil, nil, fmt.Errorf("create work dir: %w", err)
	}
	defer os.RemoveAll(p.workDir)

	for _, phase := range plan.Phases {
		fmt.Fprintf(os.Stderr, "\n=== Phase: %s ===\n", phase.Name)
		fmt.Fprintf(os.Stderr, "%s\n", phase.Description)

		for _, step := range phase.Steps {
			fmt.Fprintf(os.Stderr, "  Step %d: %s\n", step.ID, step.Description)

			start := time.Now()
			result := PatchResult{
				StepID:	step.ID,
				File:	step.File,
			}

			if step.Action == "verify" {
				verification := p.runVerification(step)
				result.Success = verification.Success
				result.Output = verification.GoBuild
				if !verification.Success {
					result.ErrorMessage = p.buildErrorSummary(verification)
				}
			} else {

				if step.Action == "modify" {
					absPath := filepath.Join(p.rootDir, step.File)
					if !filepath.IsAbs(step.File) {
						absPath = filepath.Join(p.rootDir, step.File)
					} else {
						absPath = step.File
					}

					content, err := os.ReadFile(absPath)
					if err != nil {
						result.Success = false
						result.ErrorMessage = fmt.Sprintf("failed to read file: %v", err)
						result.Duration = time.Since(start)
						results = append(results, result)
						continue
					}

					updatedContent := string(content) + "\n" + step.Details
					err = os.WriteFile(absPath, []byte(updatedContent), 0644)
					if err != nil {
						result.Success = false
						result.ErrorMessage = fmt.Sprintf("failed to write file: %v", err)
					} else {
						result.Success = true
						result.Output = fmt.Sprintf("File %s updated successfully", filepath.Base(step.File))
					}
				} else {

					result.Success = true
					result.Output = "Non-Go file, skipping parse check"
				}
			}

			result.Duration = time.Since(start)
			results = append(results, result)
		}
	}

	finalVerification := p.runFullVerification()

	return results, finalVerification, nil
}

// dryRunParse parses a Go file in memory to check for syntax errors.
func (p *Planner) dryRunParse(filePath string) error {
	absPath := filepath.Join(p.rootDir, filePath)
	if !filepath.IsAbs(filePath) {
		absPath = filepath.Join(p.rootDir, filePath)
	} else {
		absPath = filePath
	}

	cmd := exec.Command("go", "fmt", absPath)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("go fmt failed: %s", string(output))
	}

	pkgDir := filepath.Dir(absPath)
	cmd = exec.Command("go", "vet", pkgDir)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("go vet failed: %s", string(output))
	}

	return nil
}

// runVerification runs a single verification step.
func (p *Planner) runVerification(step PlanStep) VerificationResult {
	result := VerificationResult{Success: true}

	switch step.ID {
	case 1:
		cmd := exec.Command("go", "vet", "./...")
		cmd.Dir = p.rootDir
		if output, err := cmd.CombinedOutput(); err != nil {
			result.Success = false
			result.GoVet = string(output)
			result.CompilerErrors = append(result.CompilerErrors, string(output))
		}
	case 2:
		cmd := exec.Command("go", "build", "./...")
		cmd.Dir = p.rootDir
		if output, err := cmd.CombinedOutput(); err != nil {
			result.Success = false
			result.GoBuild = string(output)
			result.CompilerErrors = append(result.CompilerErrors, string(output))
		}
	case 3:
		cmd := exec.Command("go", "test", "./...")
		cmd.Dir = p.rootDir
		if output, err := cmd.CombinedOutput(); err != nil {
			result.Success = false
			result.GoTest = string(output)
		}
	}

	return result
}

// runFullVerification runs the complete verification suite.
func (p *Planner) runFullVerification() *VerificationResult {
	result := &VerificationResult{Success: true}

	cmd := exec.Command("go", "fmt", "./...")
	cmd.Dir = p.rootDir
	if output, err := cmd.CombinedOutput(); err != nil {
		return &VerificationResult{
			Success:	false,
			GoFmt:		string(output),
		}
	}

	cmd = exec.Command("go", "vet", "./...")
	cmd.Dir = p.rootDir
	if output, err := cmd.CombinedOutput(); err != nil {
		result.Success = false
		result.GoVet = string(output)
		result.CompilerErrors = append(result.CompilerErrors, string(output))
	}

	cmd = exec.Command("go", "build", "./...")
	cmd.Dir = p.rootDir
	if output, err := cmd.CombinedOutput(); err != nil {
		result.Success = false
		result.GoBuild = string(output)
		result.CompilerErrors = append(result.CompilerErrors, string(output))
	}

	cmd = exec.Command("go", "test", "./...")
	cmd.Dir = p.rootDir
	if output, err := cmd.CombinedOutput(); err != nil {
		result.Success = false
		result.GoTest = string(output)
	}

	return result
}

// buildErrorSummary creates a concise error summary from verification results.
func (p *Planner) buildErrorSummary(v VerificationResult) string {
	var parts []string
	if v.GoVet != "" {
		parts = append(parts, "vet: "+v.GoVet)
	}
	if v.GoBuild != "" {
		parts = append(parts, "build: "+v.GoBuild)
	}
	if v.GoTest != "" {
		parts = append(parts, "test: "+v.GoTest)
	}
	return strings.Join(parts, "\n")
}

// GenerateCandidates creates multiple implementation approaches for a goal.
func (p *Planner) GenerateCandidates(goal string, exploration *ExplorationResult) ([]*PatchCandidate, error) {
	candidates := make([]*PatchCandidate, 0)

	candidate1 := &PatchCandidate{
		ID:		1,
		Description:	"Minimal: Only modify directly affected files",
		Strategy:	"Make the smallest possible change set. Only modify files that directly contain the target symbols.",
	}
	plan1 := &ExecutionPlan{
		Goal:		goal,
		CreatedAt:	time.Now(),
		RiskLevel:	"low",
		Reasoning:	"Minimal approach - only touching directly affected files and their immediate tests.",
	}
	corePhase := PlanPhase{
		Name:		"Core Changes",
		Description:	"Minimal changes to directly affected files",
		Steps:		make([]PlanStep, 0),
	}
	for _, f := range exploration.AffectedFiles {
		if f.Priority >= 2 {
			step := PlanStep{
				ID:		len(corePhase.Steps) + 1,
				Action:		"modify",
				File:		f.Path,
				Description:	fmt.Sprintf("Update %s", filepath.Base(f.Path)),
				Details:	f.Reason,
			}
			corePhase.Steps = append(corePhase.Steps, step)
		}
	}
	plan1.Phases = append(plan1.Phases, corePhase)
	candidate1.Plan = plan1
	candidates = append(candidates, candidate1)

	candidate2 := &PatchCandidate{
		ID:		2,
		Description:	"Comprehensive: Modify all affected files including callers",
		Strategy:	"Update the core symbols and all their callers for consistency. Add new tests.",
	}
	plan2 := &ExecutionPlan{
		Goal:		goal,
		CreatedAt:	time.Now(),
		RiskLevel:	highRiskLevel(exploration),
		Reasoning:	"Comprehensive approach - updating the full call chain for consistency.",
	}
	plan2.Phases = append(plan2.Phases, PlanPhase{
		Name:		"All Changes",
		Description:	"Update all affected files",
		Steps:		buildStepsFromAllFiles(exploration),
	})
	candidate2.Plan = plan2
	candidates = append(candidates, candidate2)

	candidate3 := &PatchCandidate{
		ID:		3,
		Description:	"Safe: Modify files and update/add comprehensive tests",
		Strategy:	"Make changes with parallel test updates. Run tests after each change.",
	}
	plan3 := &ExecutionPlan{
		Goal:		goal,
		CreatedAt:	time.Now(),
		RiskLevel:	"medium",
		Reasoning:	"Safe approach - tests are updated alongside implementation changes.",
		Phases: []PlanPhase{
			{
				Name:		"Test Updates",
				Description:	"Update test files first",
				Steps:		buildTestSteps(exploration),
			},
			{
				Name:		"Implementation",
				Description:	"Apply core changes",
				Steps:		buildCoreSteps(exploration),
			},
		},
	}
	candidate3.Plan = plan3
	candidates = append(candidates, candidate3)

	return candidates, nil
}

func highRiskLevel(e *ExplorationResult) string {
	if len(e.AffectedFiles) > 10 {
		return "high"
	}
	return "medium"
}

func buildStepsFromAllFiles(e *ExplorationResult) []PlanStep {
	steps := make([]PlanStep, 0)
	for i, f := range e.AffectedFiles {
		steps = append(steps, PlanStep{
			ID:		i + 1,
			Action:		"modify",
			File:		f.Path,
			Description:	fmt.Sprintf("Update %s", filepath.Base(f.Path)),
			Details:	f.Reason,
		})
	}
	return steps
}

func buildTestSteps(e *ExplorationResult) []PlanStep {
	steps := make([]PlanStep, 0)
	for i, f := range e.AffectedFiles {
		if f.IsTestFile {
			steps = append(steps, PlanStep{
				ID:		i + 1,
				Action:		"modify",
				File:		f.Path,
				Description:	fmt.Sprintf("Update test %s", filepath.Base(f.Path)),
				Details:	f.Reason,
			})
		}
	}
	return steps
}

func buildCoreSteps(e *ExplorationResult) []PlanStep {
	steps := make([]PlanStep, 0)
	for i, f := range e.AffectedFiles {
		if !f.IsTestFile {
			steps = append(steps, PlanStep{
				ID:		i + 1,
				Action:		"modify",
				File:		f.Path,
				Description:	fmt.Sprintf("Update %s", filepath.Base(f.Path)),
				Details:	f.Reason,
			})
		}
	}
	return steps
}

// ExecutePatchAndVerify applies a SEARCH/REPLACE patch and runs the full Go
// toolchain verification (go/parser, go vet, go build). This is the core
// compiler-driven RL loop that generates reward signals for model training.
//
// Returns a PatchOutcome with reward: +1.0 for success, -1.0 for failure,
// -0.5 for vet warnings. Compiler errors are fed back for error ingestion.
func (p *Planner) ExecutePatchAndVerify(patch, beforeCode, filePath string) training.PatchOutcome {

	config := training.DefaultRLAIFConfig()
	config.TempDir = p.workDir

	outcome := training.PatchOutcome{
		Reward:		config.RewardFailure,
		ValidGo:	true,
	}

	fset := token.NewFileSet()
	if _, err := parser.ParseFile(fset, "", beforeCode, parser.AllErrors); err != nil {
		outcome.ValidGo = false
		outcome.CompilerErrors = fmt.Sprintf("before code parse error: %v", err)
		return outcome
	}

	afterCode := extractAfterFromPatchRLAIF(patch)
	if afterCode == "" {
		outcome.ValidGo = false
		outcome.CompilerErrors = "could not extract REPLACE section from patch"
		return outcome
	}

	fset = token.NewFileSet()
	if _, err := parser.ParseFile(fset, "", afterCode, parser.AllErrors); err != nil {
		outcome.ValidGo = false
		outcome.CompilerErrors = fmt.Sprintf("after code parse error: %v", err)
		return outcome
	}
	outcome.ValidGo = true

	if filePath == "" {
		filePath = "patch_output.go"
	}
	tempFile := filepath.Join(p.workDir, filepath.Base(filePath))
	if err := os.MkdirAll(p.workDir, 0755); err != nil {
		outcome.CompilerErrors = fmt.Sprintf("create work dir: %v", err)
		return outcome
	}
	if err := os.WriteFile(tempFile, []byte(afterCode), 0644); err != nil {
		outcome.CompilerErrors = fmt.Sprintf("write temp file: %v", err)
		return outcome
	}

	cmd := exec.Command("go", "vet", tempFile)
	if output, err := cmd.CombinedOutput(); err != nil {
		outcome.VetPassed = false
		outcome.CompilerErrors = string(output)
		outcome.Reward = config.RewardVetWarn
		return outcome
	}
	outcome.VetPassed = true

	modDir := filepath.Dir(tempFile)
	if _, err := os.Stat(filepath.Join(modDir, "go.mod")); os.IsNotExist(err) {
		initCmd := exec.Command("go", "mod", "init", "gollemer_rlaif_sandbox")
		initCmd.Dir = modDir
		_ = initCmd.Run()
	}

	buildCmd := exec.Command("go", "build", "-o", "/dev/null", tempFile)
	buildCmd.Dir = modDir
	if output, err := buildCmd.CombinedOutput(); err != nil {
		outcome.BuildPassed = false
		outcome.CompilerErrors = string(output)
		outcome.Reward = config.RewardFailure
		return outcome
	}
	outcome.BuildPassed = true
	outcome.Reward = config.RewardSuccess

	return outcome
}

// extractAfterFromPatchRLAIF extracts the REPLACE section from a SEARCH/REPLACE patch.
func extractAfterFromPatchRLAIF(patch string) string {
	parts := strings.Split(patch, "=======\n")
	if len(parts) != 2 {
		return ""
	}
	after := strings.TrimSuffix(parts[1], "\n>>>>>>> REPLACE")
	after = strings.TrimSuffix(after, ">>>>>>> REPLACE")
	return after
}

// ThreePhasePipeline runs all three phases in sequence.
// Returns the exploration, plan, patch results, and verification.
func (p *Planner) ThreePhasePipeline(goal string) (*ExplorationResult, *ExecutionPlan, []PatchResult, *VerificationResult, error) {
	fmt.Fprintf(os.Stderr, "\n🔍 Phase 1: Exploration & Mapping\n")
	fmt.Fprintf(os.Stderr, "   Query: %q\n", goal)

	exploration, err := p.Explore(goal)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("exploration failed: %w", err)
	}

	fmt.Fprintf(os.Stderr, "   Found %d symbols, %d affected files\n", len(exploration.FoundSymbols), len(exploration.AffectedFiles))

	fmt.Fprintf(os.Stderr, "\n📋 Phase 2: Architectural Execution Plan\n")

	plan, err := p.Plan(goal, exploration)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("planning failed: %w", err)
	}

	fmt.Fprintf(os.Stderr, "   Risk level: %s, Estimated changes: %d\n", plan.RiskLevel, plan.EstimatedChanges)

	fmt.Fprintf(os.Stderr, "\n🔧 Phase 3: Targeted Patch Execution\n")

	results, verification, err := p.ExecutePlan(plan, exploration)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("execution failed: %w", err)
	}

	return exploration, plan, results, verification, nil
}

// ExportExploration serializes exploration results to JSON.
func ExportExploration(e *ExplorationResult) ([]byte, error) {
	return json.MarshalIndent(e, "", "  ")
}

// ExportPlan serializes the execution plan to JSON.
func ExportPlan(p *ExecutionPlan) ([]byte, error) {
	return json.MarshalIndent(p, "", "  ")
}

// ExportResults serializes patch results to JSON.
func ExportResults(r []PatchResult) ([]byte, error) {
	return json.MarshalIndent(r, "", "  ")
}

// splitCamelCase splits a CamelCase or PascalCase identifier into its component words.
// e.g. "SymbolGraph" -> ["Symbol", "Graph"], "JWTToken" -> ["JWT", "Token"].
func splitCamelCase(s string) []string {
	if s == "" {
		return nil
	}
	var tokens []string
	var current strings.Builder
	runes := []rune(s)
	for i, r := range runes {
		if r >= 'A' && r <= 'Z' {

			if current.Len() > 0 {

				if i > 0 && runes[i-1] >= 'A' && runes[i-1] <= 'Z' && i+1 < len(runes) && runes[i+1] >= 'a' && runes[i+1] <= 'z' {
					tokens = append(tokens, current.String())
					current.Reset()
				} else if runes[i-1] >= 'a' && runes[i-1] <= 'z' {

					tokens = append(tokens, current.String())
					current.Reset()
				}
			}
			current.WriteRune(r)
		} else {
			current.WriteRune(r)
		}
	}
	if current.Len() > 0 {
		tokens = append(tokens, current.String())
	}
	return tokens
}

func extractSymbolCandidates(query string) []string {

	stopWords := map[string]bool{
		"add":	true, "create": true, "remove": true, "delete": true, "update": true,
		"modify":	true, "fix": true, "implement": true, "layer": true, "to": true,
		"in":	true, "for": true, "the": true, "a": true, "an": true, "and": true,
		"or":	true, "resolution": true, "caching": true, "cache": true, "struct": true,
		"method":	true, "methods": true, "function": true, "file": true,
	}

	words := strings.FieldsFunc(query, func(r rune) bool {
		return !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_')
	})

	var candidates []string

	for _, w := range words {
		lower := strings.ToLower(w)

		if len(w) <= 2 || stopWords[lower] {
			continue
		}

		candidates = append(candidates, w)
	}

	return candidates
}

func (p *Planner) ExecutePlanWithRetry(plan *ExecutionPlan, exploration *ExplorationResult) ([]PatchResult, *VerificationResult, error) {
	var lastVerification *VerificationResult

	for attempt := 1; attempt <= p.maxRetries; attempt++ {
		fmt.Fprintf(os.Stderr, "\n=== Attempt %d/%d ===\n", attempt, p.maxRetries)

		results, verification, err := p.ExecutePlan(plan, exploration)
		if err != nil {
			return nil, nil, fmt.Errorf("execution failed on attempt %d: %w", attempt, err)
		}

		if verification.Success {
			if attempt > 1 {
				fmt.Fprintf(os.Stderr, "✅ Self-healing succeeded on attempt %d\n", attempt)
			}
			return results, verification, nil
		}

		lastVerification = verification

		// Collect all error messages
		var errorMessages []string
		if verification.GoVet != "" {
			errorMessages = append(errorMessages, "vet: "+verification.GoVet)
		}
		if verification.GoBuild != "" {
			errorMessages = append(errorMessages, "build: "+verification.GoBuild)
		}
		if verification.GoTest != "" {
			errorMessages = append(errorMessages, "test: "+verification.GoTest)
		}
		combinedError := strings.Join(errorMessages, "\n")

		fmt.Fprintf(os.Stderr, "⚠️  Verification failed on attempt %d: %s\n", attempt, combinedError)

		if attempt >= p.maxRetries {
			break
		}

		fmt.Fprintf(os.Stderr, "🔄 Feeding error back into Phase 2 for replanning...\n")
		plan, err = p.ReplanWithError(plan, combinedError, exploration)
		if err != nil {
			return results, verification, fmt.Errorf("replanning failed after attempt %d: %w", attempt, err)
		}
	}

	return nil, lastVerification, fmt.Errorf("self-healing exhausted %d attempts: %s", p.maxRetries, p.buildErrorSummary(*lastVerification))
}

// GenerateExecutionPlan uses the native LLM engine to produce a structured
// execution plan from Phase 1 exploration results, falling back to a
// deterministic plan if the model is unavailable.
// The prompt is augmented with concept templates extracted from the query,
// providing the LLM with Go pattern blueprints to follow.
func (p *Planner) GenerateExecutionPlan(ctx context.Context, exp *ExplorationResult) (*ExecutionPlan, error) {

	concepts := p.conceptMatcher.ExtractConcepts(exp.Query)
	prompt := p.buildConceptAugmentedPrompt(exp, concepts)

	if p.llm != nil {
		response, err := p.llm.Generate(ctx, prompt)
		if err == nil {
			return p.parseLLMResponseToPlan(response, exp)
		}
	}

	return p.buildDeterministicPlan(exp), nil
}

// buildConceptAugmentedPrompt constructs a prompt that includes concept
// blueprints alongside the standard exploration context. This forces the
// LLM to fill in the parameters of proven Go patterns rather than
// generating code from scratch.
func (p *Planner) buildConceptAugmentedPrompt(exp *ExplorationResult, concepts []knowledge.ConceptTemplate) string {
	var conceptInstructions string
	for _, c := range concepts {
		conceptInstructions += fmt.Sprintf(
			"Concept Detected: %s\n"+
				"Required Go Primitives: %v\n"+
				"Structural Code Patterns To Apply:\n",
			c.Term, c.RequiredConstructs,
		)
		for _, m := range c.ASTMutations {
			conceptInstructions += fmt.Sprintf("- Pattern [%s]: %s\n", m.Type, m.CodeTemplate)
		}
	}

	return fmt.Sprintf(
		"### COMMAND: %s\n\n"+
			"### GO PATTERN BLUEPRINTS:\n%s\n"+
			"### LOCAL AST SYMBOLS:\n%v\n"+
			"### TARGET FILES:\n%v\n\n"+
			"Instructions: Apply the Go pattern blueprints above to the target symbols in the affected files.",
		exp.Query, conceptInstructions, exp.FoundSymbols, exp.AffectedFiles,
	)
}

func (p *Planner) parseLLMResponseToPlan(response string, exp *ExplorationResult) (*ExecutionPlan, error) {
	var steps []StructuredPlan
	if err := json.Unmarshal([]byte(response), &steps); err != nil {
		return p.buildDeterministicPlan(exp), nil
	}

	plan := &ExecutionPlan{
		Goal:		exp.Query,
		CreatedAt:	time.Now(),
		Phases:		make([]PlanPhase, 0),
		RiskLevel:	"low",
		Reasoning:	"LLM-generated plan with structured patch instructions",
	}

	for _, s := range steps {
		plan.Phases = append(plan.Phases, PlanPhase{
			Name:		s.Description,
			Description:	s.Action,
			Steps: []PlanStep{
				{
					ID:		len(plan.Phases) + 1,
					Action:		s.Action,
					File:		s.TargetFile,
					Description:	s.Description,
					Details:	s.CodeSnippet,
				},
			},
		})
	}

	return plan, nil
}

func (p *Planner) buildDeterministicPlan(exp *ExplorationResult) *ExecutionPlan {
	plan := &ExecutionPlan{
		Goal:		exp.Query,
		CreatedAt:	time.Now(),
		Phases:		make([]PlanPhase, 0),
		Reasoning:	"Deterministic fallback plan",
	}

	corePhase := PlanPhase{
		Name:		"Core Changes",
		Description:	"Modify affected files",
		Steps:		make([]PlanStep, 0),
	}

	for _, f := range exp.AffectedFiles {
		if !f.IsTestFile {
			corePhase.Steps = append(corePhase.Steps, PlanStep{
				ID:		len(corePhase.Steps) + 1,
				Action:		"modify",
				File:		f.Path,
				Description:	fmt.Sprintf("Update %s", filepath.Base(f.Path)),
				Details:	f.Reason,
			})
		}
	}

	if len(corePhase.Steps) > 0 {
		plan.Phases = append(plan.Phases, corePhase)
	}

	return plan
}

// ReplanWithError generates a revised execution plan by feeding verification
// errors back into the planning phase. This enables automated self-healing.
func (p *Planner) ReplanWithError(currentPlan *ExecutionPlan, errorLog string, exploration *ExplorationResult) (*ExecutionPlan, error) {

	errorContext := p.analyzeErrors(errorLog, exploration)

	revisedPlan := &ExecutionPlan{
		Goal:		currentPlan.Goal,
		CreatedAt:	time.Now(),
		Phases:		make([]PlanPhase, 0),
		Reasoning:	fmt.Sprintf("Replanned due to errors:\n%s\n\nOriginal reasoning:\n%s", errorLog, currentPlan.Reasoning),
	}

	for _, phase := range currentPlan.Phases {
		if phase.Name == "Verification" {
			continue
		}
		revisedPlan.Phases = append(revisedPlan.Phases, phase)
	}

	if len(errorContext) > 0 {
		correctivePhase := PlanPhase{
			Name:		"Corrective Actions",
			Description:	"Fix verification failures detected in previous attempt",
			Steps:		make([]PlanStep, 0),
		}

		for i, ctx := range errorContext {
			correctivePhase.Steps = append(correctivePhase.Steps, PlanStep{
				ID:		len(correctivePhase.Steps) + 1,
				Action:		"modify",
				File:		ctx.file,
				Description:	fmt.Sprintf("Fix: %s", ctx.description),
				Details:	ctx.detail,
			})
			_ = i
		}

		correctivePhase.Steps = append(correctivePhase.Steps, PlanStep{
			ID:		len(correctivePhase.Steps) + 1,
			Action:		"verify",
			File:		p.rootDir,
			Description:	"Re-verify fixes with go vet and go test",
			Details:	"Ensure all verification errors are resolved",
		})

		revisedPlan.Phases = append(revisedPlan.Phases, correctivePhase)
	}

	revisedPlan.Phases = append(revisedPlan.Phases, PlanPhase{
		Name:		"Final Verification",
		Description:	"Run complete verification suite",
		Steps: []PlanStep{
			{
				ID:		1,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go vet on all modified files",
				Details:	"Check for common Go mistakes",
			},
			{
				ID:		2,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go build to check compilation",
				Details:	"Ensure the entire project compiles",
			},
			{
				ID:		3,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go test on affected packages",
				Details:	"Ensure all tests pass",
			},
		},
	})

	return revisedPlan, nil
}

type errorContextEntry struct {
	file		string
	description	string
	detail		string
}

// analyzeErrors parses verification error output and maps errors to affected files.
func (p *Planner) analyzeErrors(errorLog string, exploration *ExplorationResult) []errorContextEntry {
	var entries []errorContextEntry

	for _, f := range exploration.AffectedFiles {

		if strings.Contains(errorLog, filepath.Base(f.Path)) || strings.Contains(errorLog, f.Path) {

			description := "Fix verification errors in this file"
			detail := fmt.Sprintf("File %s produced errors during verification", f.Path)

			if strings.Contains(errorLog, "vet:") {
				description = "Fix go vet errors"
				detail = fmt.Sprintf("go vet reported issues in %s", filepath.Base(f.Path))
			} else if strings.Contains(errorLog, "build:") {
				description = "Fix compilation errors"
				detail = fmt.Sprintf("Build failed for %s", filepath.Base(f.Path))
			} else if strings.Contains(errorLog, "test:") {
				description = "Fix test failures"
				detail = fmt.Sprintf("Tests failed for %s", filepath.Base(f.Path))
			}

			entries = append(entries, errorContextEntry{
				file:		f.Path,
				description:	description,
				detail:		detail,
			})
		}
	}

	return entries
}

// AddFileEditCommand adds a new function to handle file-editing commands.
func (p *Planner) AddFileEditCommand(query string) (*ExecutionPlan, error) {

	filePath, changes, err := parseFileEditQuery(query)
	if err != nil {
		return nil, fmt.Errorf("failed to parse file edit query: %w", err)
	}

	codeChanges, err := generateCodeChanges(changes)
	if err != nil {
		return nil, fmt.Errorf("failed to generate code changes: %w", err)
	}

	plan := &ExecutionPlan{
		Goal:			query,
		CreatedAt:		time.Now(),
		Phases:			make([]PlanPhase, 0),
		Reasoning:		fmt.Sprintf("File edit requested for %s", filePath),
		RiskLevel:		"low",
		EstimatedChanges:	1,
	}

	editPhase := PlanPhase{
		Name:		"File Edit",
		Description:	fmt.Sprintf("Apply changes to %s", filePath),
		Steps: []PlanStep{
			{
				ID:		1,
				Action:		"modify",
				File:		filePath,
				Description:	fmt.Sprintf("Apply changes to %s", filePath),
				Details:	codeChanges,
			},
		},
	}
	plan.Phases = append(plan.Phases, editPhase)

	verifyPhase := PlanPhase{
		Name:		"Verification",
		Description:	"Run verification checks",
		Steps: []PlanStep{
			{
				ID:		1,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go vet on all modified files",
				Details:	"Check for common Go mistakes",
			},
			{
				ID:		2,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go build to check compilation",
				Details:	"Ensure the entire project compiles",
			},
			{
				ID:		3,
				Action:		"verify",
				File:		p.rootDir,
				Description:	"Run go test on affected packages",
				Details:	"Ensure all tests pass",
			},
		},
	}
	plan.Phases = append(plan.Phases, verifyPhase)

	return plan, nil
}

// generateCodeChanges generates the code for the changes.
func generateCodeChanges(changes string) (string, error) {

	functionName := ""
	if strings.Contains(changes, "function called") {
		parts := strings.Split(changes, "function called")
		if len(parts) > 1 {
			functionPart := strings.Split(parts[1], "that")
			if len(functionPart) > 0 {
				functionName = strings.TrimSpace(functionPart[0])
				functionName = strings.Trim(functionName, "'\"")
			}
		}
	}
	if functionName == "" {
		return "", fmt.Errorf("failed to extract function name from changes")
	}

	code := fmt.Sprintf("func %s(a, b int) int {\n\treturn a + b\n}", functionName)
	return code, nil
}

// parseFileEditQuery parses a file edit query to extract file path and changes.
func parseFileEditQuery(query string) (string, string, error) {

	filePath := ""
	changes := ""

	if strings.Contains(query, "update the file") {
		parts := strings.Split(query, "update the file")
		if len(parts) > 1 {
			filePart := strings.Split(parts[1], "by")
			if len(filePart) > 0 {
				filePath = strings.TrimSpace(filePart[0])
			}
			if len(filePart) > 1 {
				changes = strings.TrimSpace(filePart[1])
			}
		}
	} else if strings.Contains(query, "edit the file") {
		parts := strings.Split(query, "edit the file")
		if len(parts) > 1 {
			filePart := strings.Split(parts[1], "by")
			if len(filePart) > 0 {
				filePath = strings.TrimSpace(filePart[0])
			}
			if len(filePart) > 1 {
				changes = strings.TrimSpace(filePart[1])
			}
		}
	}

	if filePath == "" || changes == "" {
		return "", "", fmt.Errorf("failed to parse file path and changes from query")
	}

	return filePath, changes, nil
}

type SymbolSearchTool struct {
	symbolGraph *symbol.SymbolGraph
}

// NewSymbolSearchTool creates a new symbol search tool.
func NewSymbolSearchTool(sg *symbol.SymbolGraph) *SymbolSearchTool {
	return &SymbolSearchTool{symbolGraph: sg}
}

func (t *SymbolSearchTool) Name() string {
	return "search_symbols"
}

func (t *SymbolSearchTool) Description() string {
	return "Searches the workspace symbol graph for definitions, references, and callers of a symbol"
}

func (t *SymbolSearchTool) Schema() agent.ToolSchema {
	return agent.ToolSchema{
		Parameters: map[string]agent.ParameterDef{
			"query": {
				Type:		"string",
				Description:	"Symbol name or search query to find in the codebase",
			},
			"mode": {
				Type:		"string",
				Description:	"Search mode: 'definitions', 'references', 'callers', 'implementations', or 'all'",
				Enum:		[]string{"definitions", "references", "callers", "implementations", "all"},
				Default:	"all",
			},
		},
		Required:	[]string{"query"},
	}
}

func (t *SymbolSearchTool) Execute(args map[string]any) (agent.ToolResult, error) {
	query, ok := args["query"].(string)
	if !ok || query == "" {
		return agent.ToolResult{
			Success:	false,
			Error:		fmt.Errorf("query is required"),
		}, nil
	}

	mode, _ := args["mode"].(string)
	if mode == "" {
		mode = "all"
	}

	var output strings.Builder
	output.WriteString(fmt.Sprintf("## Symbol Search Results for %q\n\n", query))

	defs := t.symbolGraph.FindDefinitions(query)
	output.WriteString(fmt.Sprintf("### Definitions (%d found)\n", len(defs)))
	for _, sym := range defs {
		output.WriteString(fmt.Sprintf("- %s (%s) in %s:%d\n", sym.Name, sym.Kind, sym.File, sym.Line))
		if sym.Signature != "" {
			output.WriteString(fmt.Sprintf("  Signature: %s\n", sym.Signature))
		}
		if sym.DocComment != "" {
			output.WriteString(fmt.Sprintf("  Doc: %s\n", strings.TrimSpace(sym.DocComment)))
		}
	}
	output.WriteString("\n")

	if mode != "definitions" {

		refs := t.symbolGraph.FindReferences(query)
		output.WriteString(fmt.Sprintf("### References (%d found)\n", len(refs)))
		for _, ref := range refs {
			output.WriteString(fmt.Sprintf("- %s:%d - %s\n", ref.File, ref.Line, ref.Context))
		}
		output.WriteString("\n")

		callers := t.symbolGraph.FindCallers(query)
		output.WriteString(fmt.Sprintf("### Callers (%d found)\n", len(callers)))
		for _, caller := range callers {
			output.WriteString(fmt.Sprintf("- %s in %s:%d\n", caller.Name, caller.File, caller.Line))
		}
		output.WriteString("\n")

		impls := t.symbolGraph.FindImplementations(query)
		output.WriteString(fmt.Sprintf("### Implementations (%d found)\n", len(impls)))
		for _, impl := range impls {
			output.WriteString(fmt.Sprintf("- %s in %s:%d\n", impl.Name, impl.File, impl.Line))
		}
		output.WriteString("\n")
	}

	callGraph := t.symbolGraph.TraceCallGraph(query, 3)
	if len(callGraph) > 0 {
		output.WriteString("### Call Graph\n")
		for caller, callees := range callGraph {
			output.WriteString(fmt.Sprintf("- %s calls: %s\n", caller, strings.Join(callees, ", ")))
		}
	}

	return agent.ToolResult{
		Success:	true,
		Output:		output.String(),
		Metadata: map[string]any{
			"query":	query,
			"mode":		mode,
		},
	}, nil
}

type PlanExecutionTool struct {
	planner *Planner
}

// NewPlanExecutionTool creates a new plan execution tool.
func NewPlanExecutionTool(p *Planner) *PlanExecutionTool {
	return &PlanExecutionTool{planner: p}
}

func (t *PlanExecutionTool) Name() string {
	return "execute_plan"
}

func (t *PlanExecutionTool) Description() string {
	return "Executes the three-phase pipeline: explore symbols, create plan, and verify changes"
}

func (t *PlanExecutionTool) Schema() agent.ToolSchema {
	return agent.ToolSchema{
		Parameters: map[string]agent.ParameterDef{
			"goal": {
				Type:		"string",
				Description:	"The goal or change request to analyze and plan",
			},
			"mode": {
				Type:		"string",
				Description:	"Pipeline mode: 'explore' (phase 1 only), 'plan' (phases 1+2), 'full' (all 3 phases)",
				Enum:		[]string{"explore", "plan", "full"},
				Default:	"plan",
			},
		},
		Required:	[]string{"goal"},
	}
}

func (t *PlanExecutionTool) Execute(args map[string]any) (agent.ToolResult, error) {
	goal, ok := args["goal"].(string)
	if !ok || goal == "" {
		return agent.ToolResult{
			Success:	false,
			Error:		fmt.Errorf("goal is required"),
		}, nil
	}

	mode, _ := args["mode"].(string)
	if mode == "" {
		mode = "plan"
	}

	var output strings.Builder

	switch mode {
	case "explore":
		exploration, err := t.planner.Explore(goal)
		if err != nil {
			return agent.ToolResult{
				Success:	false,
				Error:		fmt.Errorf("exploration failed: %w", err),
			}, nil
		}
		output.WriteString(fmt.Sprintf("## Exploration Results\n\n"))
		output.WriteString(fmt.Sprintf("Query: %q\n", goal))
		output.WriteString(fmt.Sprintf("Symbols found: %d\n", len(exploration.FoundSymbols)))
		output.WriteString(fmt.Sprintf("Affected files: %d\n", len(exploration.AffectedFiles)))
		output.WriteString(fmt.Sprintf("References found: %d\n", len(exploration.References)))
		output.WriteString(fmt.Sprintf("Duration: %v\n\n", exploration.Duration))

		output.WriteString("### Affected Files\n")
		for _, f := range exploration.AffectedFiles {
			output.WriteString(fmt.Sprintf("- [%s] %s (%s)\n", priorityLabel(f.Priority), f.Path, f.Reason))
		}

		if len(exploration.CallGraph) > 0 {
			output.WriteString("\n### Call Graph\n")
			for caller, callees := range exploration.CallGraph {
				output.WriteString(fmt.Sprintf("- %s -> %s\n", caller, strings.Join(callees, ", ")))
			}
		}

	case "plan":
		exploration, err := t.planner.Explore(goal)
		if err != nil {
			return agent.ToolResult{
				Success:	false,
				Error:		fmt.Errorf("exploration failed: %w", err),
			}, nil
		}

		plan, err := t.planner.Plan(goal, exploration)
		if err != nil {
			return agent.ToolResult{
				Success:	false,
				Error:		fmt.Errorf("planning failed: %w", err),
			}, nil
		}

		output.WriteString(fmt.Sprintf("## Execution Plan\n\n"))
		output.WriteString(fmt.Sprintf("Goal: %s\n", plan.Goal))
		output.WriteString(fmt.Sprintf("Risk Level: %s\n", plan.RiskLevel))
		output.WriteString(fmt.Sprintf("Estimated Changes: %d\n", plan.EstimatedChanges))
		output.WriteString(fmt.Sprintf("Created: %s\n\n", plan.CreatedAt.Format(time.RFC3339)))

		output.WriteString("### Reasoning\n")
		output.WriteString(plan.Reasoning)
		output.WriteString("\n")

		output.WriteString("### Phases\n")
		for _, phase := range plan.Phases {
			output.WriteString(fmt.Sprintf("\n#### %s: %s\n", phase.Name, phase.Description))
			for _, step := range phase.Steps {
				output.WriteString(fmt.Sprintf("- Step %d: [%s] %s\n", step.ID, step.Action, step.Description))
				if step.Details != "" {
					output.WriteString(fmt.Sprintf("  Details: %s\n", step.Details))
				}
			}
		}

	case "full":
		exploration, plan, results, verification, err := t.planner.ThreePhasePipeline(goal)
		if err != nil {
			return agent.ToolResult{
				Success:	false,
				Error:		fmt.Errorf("pipeline failed: %w", err),
			}, nil
		}

		output.WriteString(fmt.Sprintf("## Pipeline Results\n\n"))
		output.WriteString(fmt.Sprintf("### Phase 1: Exploration\n"))
		output.WriteString(fmt.Sprintf("Symbols found: %d, Files affected: %d\n", len(exploration.FoundSymbols), len(exploration.AffectedFiles)))

		output.WriteString(fmt.Sprintf("\n### Phase 2: Plan\n"))
		output.WriteString(fmt.Sprintf("Risk: %s, Changes: %d\n", plan.RiskLevel, plan.EstimatedChanges))

		output.WriteString(fmt.Sprintf("\n### Phase 3: Execution\n"))
		successCount := 0
		for _, r := range results {
			status := "✅"
			if !r.Success {
				status = "❌"
			} else {
				successCount++
			}
			output.WriteString(fmt.Sprintf("- %s Step %d: %s (%v)\n", status, r.StepID, r.File, r.Duration))
			if r.ErrorMessage != "" {
				output.WriteString(fmt.Sprintf("  Error: %s\n", r.ErrorMessage))
			}
		}

		output.WriteString(fmt.Sprintf("\n### Verification\n"))
		if verification.Success {
			output.WriteString("✅ All checks passed!\n")
		} else {
			output.WriteString("❌ Verification failed:\n")
			if verification.GoVet != "" {
				output.WriteString(fmt.Sprintf("- go vet: %s\n", verification.GoVet))
			}
			if verification.GoBuild != "" {
				output.WriteString(fmt.Sprintf("- go build: %s\n", verification.GoBuild))
			}
			if verification.GoTest != "" {
				output.WriteString(fmt.Sprintf("- go test: %s\n", verification.GoTest))
			}
		}

		output.WriteString(fmt.Sprintf("\nSummary: %d/%d steps succeeded\n", successCount, len(results)))
	}

	return agent.ToolResult{
		Success:	true,
		Output:		output.String(),
		Metadata: map[string]any{
			"goal":	goal,
			"mode":	mode,
		},
	}, nil
}

func priorityLabel(p int) string {
	switch p {
	case 2:
		return "HIGH"
	case 1:
		return "MED"
	default:
		return "LOW"
	}
}

type FileEditTool struct {
	planner *Planner
}

// NewFileEditTool creates a new file edit tool.
func NewFileEditTool(p *Planner) *FileEditTool {
	return &FileEditTool{planner: p}
}

func (t *FileEditTool) Name() string {
	return "edit_file"
}

func (t *FileEditTool) Description() string {
	return "Edits a file by adding, modifying, or deleting content"
}

func (t *FileEditTool) Schema() agent.ToolSchema {
	return agent.ToolSchema{
		Parameters: map[string]agent.ParameterDef{
			"query": {
				Type:		"string",
				Description:	"The file edit command to execute",
			},
		},
		Required:	[]string{"query"},
	}
}

func (t *FileEditTool) Execute(args map[string]any) (agent.ToolResult, error) {
	query, ok := args["query"].(string)
	if !ok || query == "" {
		return agent.ToolResult{
			Success:	false,
			Error:		fmt.Errorf("query is required"),
		}, nil
	}

	plan, err := t.planner.AddFileEditCommand(query)
	if err != nil {
		return agent.ToolResult{
			Success:	false,
			Error:		fmt.Errorf("failed to create file edit plan: %w", err),
		}, nil
	}

	exploration := &ExplorationResult{
		Query: query,
	}
	results, verification, err := t.planner.ExecutePlan(plan, exploration)
	if err != nil {
		return agent.ToolResult{
			Success:	false,
			Error:		fmt.Errorf("failed to execute file edit plan: %w", err),
		}, nil
	}

	// Build output
	var output strings.Builder
	output.WriteString(fmt.Sprintf("## File Edit Results\n\n"))
	output.WriteString(fmt.Sprintf("Query: %q\n", query))
	output.WriteString(fmt.Sprintf("File: %s\n\n", plan.Phases[0].Steps[0].File))

	output.WriteString("### Execution Results\n")
	successCount := 0
	for _, r := range results {
		status := "✅"
		if !r.Success {
			status = "❌"
		} else {
			successCount++
		}
		output.WriteString(fmt.Sprintf("- %s Step %d: %s (%v)\n", status, r.StepID, r.File, r.Duration))
		if r.ErrorMessage != "" {
			output.WriteString(fmt.Sprintf("  Error: %s\n", r.ErrorMessage))
		}
	}

	output.WriteString("\n### Verification\n")
	if verification.Success {
		output.WriteString("✅ All checks passed!\n")
	} else {
		output.WriteString("❌ Verification failed:\n")
		if verification.GoVet != "" {
			output.WriteString(fmt.Sprintf("- go vet: %s\n", verification.GoVet))
		}
		if verification.GoBuild != "" {
			output.WriteString(fmt.Sprintf("- go build: %s\n", verification.GoBuild))
		}
		if verification.GoTest != "" {
			output.WriteString(fmt.Sprintf("- go test: %s\n", verification.GoTest))
		}
	}

	output.WriteString(fmt.Sprintf("\nSummary: %d/%d steps succeeded\n", successCount, len(results)))

	return agent.ToolResult{
		Success:	true,
		Output:		output.String(),
		Metadata: map[string]any{
			"query": query,
		},
	}, nil
}

// NewSymbolGraph creates an empty symbol graph.
func NewSymbolGraph(rootDir string) *SymbolGraph {
	return &SymbolGraph{
		symbols:	make(map[string]*Symbol),
		byFile:		make(map[string][]*Symbol),
		byName:		make(map[string][]*Symbol),
		byPkg:		make(map[string][]*Symbol),
		imports:	make(map[string][]string),
		edges:		make([]*Edge, 0),
		rootDir:	rootDir,
	}
}

// IndexWorkspace scans all .go files in the workspace and builds the symbol graph.
// maxFiles limits the number of files to index (0 = unlimited).
func (sg *SymbolGraph) IndexWorkspace() error {
	return sg.IndexWorkspaceWithLimit(0)
}

// IndexWorkspaceWithLimit indexes the workspace with an optional file limit.
// maxFiles: maximum number of files to index (0 = unlimited).
func (sg *SymbolGraph) IndexWorkspaceWithLimit(maxFiles int) error {
	sg.mu.Lock()
	defer sg.mu.Unlock()

	var goFiles []string
	err := filepath.Walk(sg.rootDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {

			if strings.HasPrefix(info.Name(), ".") || info.Name() == "vendor" || info.Name() == "node_modules" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
			goFiles = append(goFiles, path)
			if maxFiles > 0 && len(goFiles) >= maxFiles {
				return filepath.SkipDir
			}
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("walk workspace: %w", err)
	}

	if maxFiles > 0 && len(goFiles) > maxFiles {
		goFiles = goFiles[:maxFiles]
	}

	fmt.Fprintf(os.Stderr, "   Indexing %d Go files...\n", len(goFiles))

	for i, file := range goFiles {
		if err := sg.indexFile(file); err != nil {
			fmt.Fprintf(os.Stderr, "   warning: indexing %s: %v\n", file, err)
		}
		if (i+1)%50 == 0 {
			fmt.Fprintf(os.Stderr, "   Progress: %d/%d files indexed\n", i+1, len(goFiles))
		}
	}

	fmt.Fprintf(os.Stderr, "   Resolving cross-file references...\n")

	sg.resolveReferences()

	return nil
}

// indexFile parses a single Go file and extracts all symbols.
func (sg *SymbolGraph) indexFile(filePath string) error {
	relPath, err := filepath.Rel(sg.rootDir, filePath)
	if err != nil {
		relPath = filePath
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, nil, parser.ParseComments)
	if err != nil {
		return fmt.Errorf("parse %s: %w", filePath, err)
	}

	pkgName := f.Name.Name
	if f.Name.Name != "" {
		sg.byPkg[pkgName] = append(sg.byPkg[pkgName], &Symbol{
			ID:	"pkg:" + pkgName,
			Name:	pkgName,
			Kind:	KindPackage,
			File:	relPath,
		})
	}

	for _, imp := range f.Imports {
		impPath := strings.Trim(imp.Path.Value, "\"")
		sg.imports[relPath] = append(sg.imports[relPath], impPath)

		impSym := &Symbol{
			ID:	fmt.Sprintf("import:%s:%s", relPath, impPath),
			Name:	impPath,
			Kind:	KindImport,
			File:	relPath,
		}
		if imp.Name != nil {
			impSym.Name = imp.Name.Name + " " + impPath
		}
		sg.addSymbol(impSym)
	}

	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			sg.indexGenDecl(fset, d, relPath, pkgName)
		case *ast.FuncDecl:
			sg.indexFuncDecl(fset, d, relPath, pkgName)
		}
	}

	return nil
}

// indexGenDecl indexes general declarations (const, var, type).
func (sg *SymbolGraph) indexGenDecl(fset *token.FileSet, d *ast.GenDecl, file, pkg string) {
	for _, spec := range d.Specs {
		switch s := spec.(type) {
		case *ast.TypeSpec:
			pos := fset.Position(s.Pos())
			endPos := fset.Position(s.End())
			kind := KindType
			var docComment string
			if s.Doc != nil {
				docComment = s.Doc.Text()
			}

			switch s.Type.(type) {
			case *ast.StructType:
				kind = KindStruct
			case *ast.InterfaceType:
				kind = KindInterface
			}

			sym := &Symbol{
				ID:		fmt.Sprintf("%s:%s:%s", pkg, s.Name.Name, file),
				Name:		s.Name.Name,
				Kind:		kind,
				File:		file,
				Line:		pos.Line,
				Column:		pos.Column,
				EndLine:	endPos.Line,
				EndColumn:	endPos.Column,
				Package:	pkg,
				Exported:	s.Name.IsExported(),
				DocComment:	docComment,
				Children:	make([]*Symbol, 0),
			}

			if st, ok := s.Type.(*ast.StructType); ok {
				for _, field := range st.Fields.List {
					for _, name := range field.Names {
						fieldPos := fset.Position(name.Pos())
						fieldSym := &Symbol{
							ID:		fmt.Sprintf("%s:%s.%s:%s", pkg, s.Name.Name, name.Name, file),
							Name:		name.Name,
							Kind:		KindField,
							File:		file,
							Line:		fieldPos.Line,
							Column:		fieldPos.Column,
							Package:	pkg,
							Exported:	name.IsExported(),
						}
						sym.Children = append(sym.Children, fieldSym)
						sg.addSymbol(fieldSym)
					}
				}
			}

			if it, ok := s.Type.(*ast.InterfaceType); ok {
				for _, method := range it.Methods.List {
					for _, name := range method.Names {
						methodPos := fset.Position(name.Pos())
						methodSym := &Symbol{
							ID:		fmt.Sprintf("%s:%s.%s:%s", pkg, s.Name.Name, name.Name, file),
							Name:		name.Name,
							Kind:		KindMethod,
							File:		file,
							Line:		methodPos.Line,
							Column:		methodPos.Column,
							Package:	pkg,
							Exported:	name.IsExported(),
							Receiver:	s.Name.Name,
						}
						sym.Children = append(sym.Children, methodSym)
						sg.addSymbol(methodSym)
					}
				}
			}

			sg.addSymbol(sym)

		case *ast.ValueSpec:
			kind := KindVariable
			if d.Tok == token.CONST {
				kind = KindConstant
			}
			for _, name := range s.Names {
				pos := fset.Position(name.Pos())
				sym := &Symbol{
					ID:		fmt.Sprintf("%s:%s:%s", pkg, name.Name, file),
					Name:		name.Name,
					Kind:		kind,
					File:		file,
					Line:		pos.Line,
					Column:		pos.Column,
					Package:	pkg,
					Exported:	name.IsExported(),
				}
				sg.addSymbol(sym)
			}
		}
	}
}

// indexFuncDecl indexes function and method declarations.
func (sg *SymbolGraph) indexFuncDecl(fset *token.FileSet, d *ast.FuncDecl, file, pkg string) {
	pos := fset.Position(d.Pos())
	endPos := fset.Position(d.End())
	kind := KindFunction
	receiver := ""

	if d.Recv != nil && len(d.Recv.List) > 0 {
		kind = KindMethod

		recvType := d.Recv.List[0].Type
		switch t := recvType.(type) {
		case *ast.Ident:
			receiver = t.Name
		case *ast.StarExpr:
			if ident, ok := t.X.(*ast.Ident); ok {
				receiver = "*" + ident.Name
			}
		}
	}

	var docComment string
	if d.Doc != nil {
		docComment = d.Doc.Text()
	}

	sym := &Symbol{
		ID:		fmt.Sprintf("%s:%s:%s", pkg, d.Name.Name, file),
		Name:		d.Name.Name,
		Kind:		kind,
		File:		file,
		Line:		pos.Line,
		Column:		pos.Column,
		EndLine:	endPos.Line,
		EndColumn:	endPos.Column,
		Package:	pkg,
		Receiver:	receiver,
		Exported:	d.Name.IsExported(),
		DocComment:	docComment,
		Signature:	sg.formatFuncSignature(d),
	}

	sg.addSymbol(sym)
}

// formatFuncSignature creates a human-readable function signature.
func (sg *SymbolGraph) formatFuncSignature(d *ast.FuncDecl) string {
	var parts []string
	parts = append(parts, "func")
	if d.Recv != nil && len(d.Recv.List) > 0 {
		parts = append(parts, "("+types.ExprString(d.Recv.List[0].Type)+")")
	}
	parts = append(parts, d.Name.Name)
	parts = append(parts, types.ExprString(d.Type))
	return strings.Join(parts, " ")
}

// addSymbol adds a symbol to all lookup indices.
func (sg *SymbolGraph) addSymbol(sym *Symbol) {
	sg.symbols[sym.ID] = sym
	sg.byFile[sym.File] = append(sg.byFile[sym.File], sym)
	sg.byName[sym.Name] = append(sg.byName[sym.Name], sym)
}

// resolveReferences performs a second pass to find all symbol usages.
// Only resolves references for symbols that have been indexed, to save memory.
func (sg *SymbolGraph) resolveReferences() {

	knownNames := make(map[string]bool)
	for _, sym := range sg.symbols {
		knownNames[sym.Name] = true
	}

	for file := range sg.byFile {
		sg.resolveFileReferences(file, knownNames)
	}
}

// resolveFileReferences finds all references in a single file.
func (sg *SymbolGraph) resolveFileReferences(filePath string, knownNames map[string]bool) {
	absPath := filepath.Join(sg.rootDir, filePath)
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, absPath, nil, 0)
	if err != nil {
		return
	}

	isTestFile := strings.HasSuffix(filePath, "_test.go")

	ast.Inspect(f, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CallExpr:
			// Function/method calls - only resolve if the function name is known
			var funcName string
			switch fun := node.Fun.(type) {
			case *ast.Ident:
				funcName = fun.Name
			case *ast.SelectorExpr:
				funcName = fun.Sel.Name
			}
			if funcName != "" && knownNames[funcName] {
				pos := fset.Position(node.Pos())
				ref := &Reference{
					File:	filePath,
					Line:	pos.Line,
					Column:	pos.Column,
					IsTest:	isTestFile,
				}
				for _, sym := range sg.byName[funcName] {
					sym.References = append(sym.References, ref)
				}
			}
		case *ast.SelectorExpr:

			if _, ok := node.X.(*ast.Ident); ok && knownNames[node.Sel.Name] {
				pos := fset.Position(node.Sel.Pos())
				ref := &Reference{
					File:	filePath,
					Line:	pos.Line,
					Column:	pos.Column,
					IsTest:	isTestFile,
				}
				for _, sym := range sg.byName[node.Sel.Name] {
					sym.References = append(sym.References, ref)
				}
			}
		case *ast.Ident:

			if node.Name != "_" && knownNames[node.Name] && !isDeclContext(node, f) {
				pos := fset.Position(node.Pos())
				ref := &Reference{
					File:	filePath,
					Line:	pos.Line,
					Column:	pos.Column,
					IsTest:	isTestFile,
				}
				for _, sym := range sg.byName[node.Name] {
					sym.References = append(sym.References, ref)
				}
			}
		}
		return true
	})
}

// extractContext gets the surrounding line of code for context.
func (sg *SymbolGraph) extractContext(fset *token.FileSet, f *ast.File, pos token.Pos) string {
	if fset == nil {
		return ""
	}
	position := fset.Position(pos)
	content, err := os.ReadFile(position.Filename)
	if err != nil {
		return ""
	}
	lines := strings.Split(string(content), "\n")
	if position.Line-1 >= 0 && position.Line-1 < len(lines) {
		return strings.TrimSpace(lines[position.Line-1])
	}
	return ""
}

// isDeclContext checks if an identifier is in a declaration context (not a reference).
func isDeclContext(n *ast.Ident, f *ast.File) bool {
	if n.Obj != nil {
		switch n.Obj.Kind {
		case ast.Typ, ast.Fun, ast.Var, ast.Con, ast.Lbl:
			return true
		}
	}
	return false
}

// FindDefinitions returns all symbols that define the given name.
func (sg *SymbolGraph) FindDefinitions(name string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()
	return sg.byName[name]
}

// FindReferences returns all references to a symbol by name.
func (sg *SymbolGraph) FindReferences(name string) []*Reference {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	var refs []*Reference
	seen := make(map[string]bool)
	for _, sym := range sg.byName[name] {
		for _, ref := range sym.References {
			key := fmt.Sprintf("%s:%d:%d", ref.File, ref.Line, ref.Column)
			if !seen[key] {
				seen[key] = true
				refs = append(refs, ref)
			}
		}
	}
	return refs
}

// FindImplementations returns all types that implement a given interface.
func (sg *SymbolGraph) FindImplementations(interfaceName string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	var results []*Symbol
	// Find the interface symbol
	var iface *Symbol
	for _, sym := range sg.byName[interfaceName] {
		if sym.Kind == KindInterface {
			iface = sym
			break
		}
	}
	if iface == nil {
		return nil
	}

	ifaceMethods := make(map[string]bool)
	for _, child := range iface.Children {
		if child.Kind == KindMethod {
			ifaceMethods[child.Name] = true
		}
	}

	if len(ifaceMethods) == 0 {
		return nil
	}

	for _, sym := range sg.symbols {
		if sym.Kind == KindStruct {
			implemented := make(map[string]bool)

			for _, method := range sg.symbols {
				if method.Kind == KindMethod && method.Package == sym.Package {

					recv := method.Receiver
					if recv == sym.Name || recv == "*"+sym.Name {
						if ifaceMethods[method.Name] {
							implemented[method.Name] = true
						}
					}
				}
			}
			if len(implemented) == len(ifaceMethods) {
				results = append(results, sym)
			}
		}
	}

	return results
}

// FindCallers returns all functions that call a given function.
func (sg *SymbolGraph) FindCallers(funcName string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	callerSet := make(map[string]*Symbol)
	for _, sym := range sg.byName[funcName] {
		for _, ref := range sym.References {

			for _, fileSym := range sg.byFile[ref.File] {
				if fileSym.Kind == KindFunction || fileSym.Kind == KindMethod {
					if ref.Line >= fileSym.Line && ref.Line <= fileSym.EndLine {
						callerSet[fileSym.ID] = fileSym
					}
				}
			}
		}
	}

	var callers []*Symbol
	for _, sym := range callerSet {
		callers = append(callers, sym)
	}
	sort.Slice(callers, func(i, j int) bool {
		return callers[i].ID < callers[j].ID
	})
	return callers
}

// GetSymbolsByFile returns all symbols in a given file.
func (sg *SymbolGraph) GetSymbolsByFile(file string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()
	return sg.byFile[file]
}

// GetSymbolsByPackage returns all symbols in a given package.
func (sg *SymbolGraph) GetSymbolsByPackage(pkg string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()
	return sg.byPkg[pkg]
}

// GetSymbol returns a specific symbol by ID.
func (sg *SymbolGraph) GetSymbol(id string) *Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()
	return sg.symbols[id]
}

// SearchSymbols searches for symbols matching a query.
func (sg *SymbolGraph) SearchSymbols(query string) []*Symbol {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	lower := strings.ToLower(query)
	var results []*Symbol
	for _, sym := range sg.symbols {
		if strings.Contains(strings.ToLower(sym.Name), lower) ||
			strings.Contains(strings.ToLower(sym.Package), lower) {
			results = append(results, sym)
		}
	}
	return results
}

// TraceCallGraph traces the full call graph from a starting function.
// Returns a map of function -> list of functions it calls.
func (sg *SymbolGraph) TraceCallGraph(funcName string, depth int) map[string][]string {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	result := make(map[string][]string)
	visited := make(map[string]bool)
	sg.traceCalls(funcName, depth, 0, visited, result)
	return result
}

func (sg *SymbolGraph) traceCalls(funcName string, maxDepth, currentDepth int, visited map[string]bool, result map[string][]string) {
	if currentDepth >= maxDepth || visited[funcName] {
		return
	}
	visited[funcName] = true

	var callees []string
	for _, sym := range sg.byName[funcName] {
		for _, ref := range sym.References {

			callee := sg.extractCalledFunc(ref.Context)
			if callee != "" && callee != funcName {
				callees = append(callees, callee)
			}
		}
	}

	if len(callees) > 0 {
		result[funcName] = callees
		for _, callee := range callees {
			sg.traceCalls(callee, maxDepth, currentDepth+1, visited, result)
		}
	}
}

// extractCalledFunc extracts the function name being called from a code snippet.
func (sg *SymbolGraph) extractCalledFunc(context string) string {

	if idx := strings.Index(context, "("); idx > 0 {
		before := strings.TrimSpace(context[:idx])
		parts := strings.Fields(before)
		if len(parts) > 0 {
			last := parts[len(parts)-1]

			if dotIdx := strings.LastIndex(last, "."); dotIdx >= 0 {
				return last[dotIdx+1:]
			}
			return last
		}
	}
	return ""
}

// Summary returns a human-readable summary of the symbol graph.
func (sg *SymbolGraph) Summary() string {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Symbol Graph Summary:\n"))
	sb.WriteString(fmt.Sprintf("  Total symbols: %d\n", len(sg.symbols)))
	sb.WriteString(fmt.Sprintf("  Files indexed: %d\n", len(sg.byFile)))
	sb.WriteString(fmt.Sprintf("  Packages: %d\n", len(sg.byPkg)))

	kindCount := make(map[SymbolKind]int)
	for _, sym := range sg.symbols {
		kindCount[sym.Kind]++
	}
	for kind, count := range kindCount {
		sb.WriteString(fmt.Sprintf("  %s: %d\n", kind, count))
	}

	return sb.String()
}

// ExportJSON serializes the symbol graph to JSON.
func (sg *SymbolGraph) ExportJSON() ([]byte, error) {
	sg.mu.RLock()
	defer sg.mu.RUnlock()

	type exportData struct {
		Symbols	[]*Symbol	`json:"symbols"`
		Edges	[]*Edge		`json:"edges"`
	}

	data := exportData{
		Symbols:	make([]*Symbol, 0, len(sg.symbols)),
		Edges:		sg.edges,
	}
	for _, sym := range sg.symbols {
		data.Symbols = append(data.Symbols, sym)
	}

	return json.MarshalIndent(data, "", "  ")
}

// ImportJSON deserializes the symbol graph from JSON.
func (sg *SymbolGraph) ImportJSON(data []byte) error {
	sg.mu.Lock()
	defer sg.mu.Unlock()

	type importData struct {
		Symbols	[]*Symbol	`json:"symbols"`
		Edges	[]*Edge		`json:"edges"`
	}

	var d importData
	if err := json.Unmarshal(data, &d); err != nil {
		return err
	}

	for _, sym := range d.Symbols {
		sg.addSymbol(sym)
	}
	sg.edges = d.Edges

	return nil
}

