// PredictDependencies predicts the dependency relationships between tokens in a sentence.
// It uses a combination of POS tags, NER tags, and phrase tags to infer the relationships.
// The function iterates through each token in the input tag.Tag and applies a set of rules
// to determine the head, dependent, and relation for each token.
func PredictDependencies(t tag.Tag) (tag.Tag, error) {

	rootIndex := -1

	for i := 0; i < len(t.Tokens); i++ {
		if t.PhraseTag[i] == "verbPhrase:generate_a_webserver" {

			rootIndex = i
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: -1, Dependent: i, Relation: "root"})

			for j := i + 1; j < len(t.Tokens); j++ {
				if t.Tokens[j] == "webserver" {
					t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: j, Relation: "dobj"})

					for k := i; k < j; k++ {
						if t.Tokens[k] == "a" {
							t.Dependencies = append(t.Dependencies, tag.Dependency{Head: j, Dependent: k, Relation: "det"})
						}
					}
				}
			}
		}
	}
	for i := range t.Tokens {
		switch {
		case t.PhraseTag[i] == "command:generate_a_webserver" && t.PosTag[i] == "COMMAND_VERB":

			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: -1, Dependent: i, Relation: "root"})

		case t.PosTag[i] == "WDT":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "nsubj"})
		case t.PosTag[i] == "VBG" && t.NerTag[i] == "AUXILIARY_VERB":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "aux"})

		case t.PosTag[i] == "VBN" && t.NerTag[i] == "ACTION":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "amod"})

		case t.PosTag[i] == "IN" && t.NerTag[i] == "RELATION":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "case"})

		case i > 1 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "OBJECT_TYPE":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "dobj"})

		case i > 1 && t.NerTag[i] == "OBJECT_TYPE" && t.NerTag[i-1] == "ACTION":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "dobj"})
		case t.NerTag[i] == "ACTION" && t.PosTag[i] == "COMMAND_VERB":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "root"})

		case t.PosTag[i] == "VBG" && t.Tokens[i] == "has":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "aux"})
		case t.PosTag[i] == "VBN" && t.Tokens[i] == "named":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "amod"})
		case t.NerTag[i] == "NAME" && t.PosTag[i] == "NN":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "dobj"})
		case t.PhraseTag[i] == "handlerName:dog" && t.Tokens[i] == "handler":

			for j := i + 1; j < len(t.Tokens); j++ {
				if t.Tokens[j] == "dog" {
					t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "handlerName"})
					break
				}
			}
		case t.NerTag[i] == "OBJECT_TYPE" && t.PosTag[i] == "NN":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "nsubj"})
		case i > 0 && t.Tokens[i] == "DATABASE" || t.Tokens[i] == "Database" || t.Tokens[i] == "database" || t.Tokens[i] == "db" || t.Tokens[i] == "DB" || t.Tokens[i] == "data":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "NOUN"})
		case rootIndex != -1 && t.Tokens[i] == "Inventory" && t.NerTag[i] == "OBJECT_NAME":
		case rootIndex != -1:
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: -1, Dependent: rootIndex, Relation: "root"})
		case t.Tokens[i] == "with":

			for j := i + 1; j < len(t.Tokens); j++ {
				if t.NerTag[j] == "OBJECT_NAME" || t.PosTag[j] == "NN" || t.PosTag[j] == "NNS" {
					t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: j, Relation: "nmod:with"})
					break
				}
			}

		case i > 0 && t.Tokens[i] == "containing":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "case"})

		case i > 0 && t.Tokens[i] == "2" && t.Tokens[i+1] == "string":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "nummod"})

		case i > 0 && len(t.Tokens[i])-1 >= i && t.Tokens[i] == "string" && t.Tokens[i+1] == "fields":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "amod"})

		case i > 0 && t.Tokens[i] == "fields" && (t.Tokens[i-1] == "string" || t.Tokens[i+1] == "and"):
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: i, Relation: "nmod"})

		case t.Tokens[i] == "and":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "cc"})
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i + 2, Relation: "conj"})

		case i > 0 && t.Tokens[i] == "integer" && t.Tokens[i+1] == "field":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "amod"})

		case i > 0 && t.Tokens[i] == "field" && t.Tokens[i-1] == "integer":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: 14, Dependent: i, Relation: "conj"})

		case i > 0 && t.Tokens[i] == "1" && t.Tokens[i+1] == "integer":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "nummod"})

		case t.PosTag[i] == "IN":

			for j := i + 1; j < len(t.Tokens); j++ {
				if t.PosTag[j] == "NN" || t.PosTag[j] == "NNS" {
					t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: j, Relation: "pobj"})
					break
				}
			}
		case t.PosTag[i] == "DT":

			nounIndex := -1
			for j := i + 1; j < len(t.Tokens); j++ {
				if t.PosTag[j] == "NN" || t.PosTag[j] == "NNS" || t.NerTag[j] == "OBJECT_NAME" || t.NerTag[j] == "OBJECT_TYPE" {
					nounIndex = j
					break
				}
			}
			if nounIndex != -1 {
				t.Dependencies = append(t.Dependencies, tag.Dependency{Head: nounIndex, Dependent: i, Relation: "det"})
			}

			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "nsubj"})
		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "VB":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "nsubj"})
		case i > 0 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "ACTION":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "dobj"})
		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "DET":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "det"})
		case i > 0 && t.PosTag[i] == "VB" && t.PosTag[i-1] == "RB":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "advmod"})
		case i > 1 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "RELATION":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "pobj"})

		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "IN":

			if i > 1 && t.PhraseTag[i-1] == "PP" {
				t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 2, Dependent: i, Relation: "pobj"})
			}

		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "VB":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"nsubj",
			})
		case i > 0 && t.Tokens[i] == "and" && t.PosTag[i] == "CC":

			if i > 1 && t.Tokens[i-1] == "fields" && t.PosTag[i-1] == "NNS" && i < len(t.Tokens)-1 && t.Tokens[i+1] == "field" && t.PosTag[i+1] == "NN" {
				t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "cc"})
				t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i + 1, Relation: "conj"})
			}

		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "VB" && t.NerTag[i] == "OBJECT_NAME":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "dobj"})

		case i > 0 && t.PosTag[i] == "NN" && t.PosTag[i-1] == "JJ":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"amod",
			})
		case i > 0 && t.NerTag[i] == "ORG" && t.NerTag[i-1] == "PER":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"nsubj",
			})
		case i > 0 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "COMMAND":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"dobj",
			})
		case i > 0 && t.NerTag[i] == "FIELDS" && t.NerTag[i-1] == "OBJECT_NAME":
			for j := i - 1; j >= 0; j-- {
				if t.NerTag[j] == "DATA_TYPE" && t.Tokens[j] == "integer" {
					t.Dependencies = append(t.Dependencies, tag.Dependency{Head: j, Dependent: i, Relation: "integer_field"})
					break
				}
			}
		case i > 0 && t.NerTag[i] == "ARGUMENT" && t.NerTag[i-1] == "COMMAND":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"dobj",
			})
		case i > 0 && t.PhraseTag[i] == "ADVP" && t.PhraseTag[i-1] == "VP":
			t.Dependencies = append(t.Dependencies, tag.Dependency{
				Head:		i - 1,
				Dependent:	i,
				Relation:	"advmod",
			})

		case i > 0 && t.NerTag[i] == "DATABASE_NAME" && t.NerTag[i-1] == "DATABASE":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "NOUN"})
		case i > 0 && t.NerTag[i] == "DATA_STRUCTURE_NAME" && t.NerTag[i-1] == "DATABASE":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "has_data_structure"})
		case i > 0 && t.NerTag[i] == "FIELD" && t.PosTag[i-1] == "CD":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "nummod"})

		case i > 0 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "ACTION" && t.Tokens[i] == "Inventory":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "named"})

		case i > 0 && t.NerTag[i] == "OBJECT_NAME" && t.NerTag[i-1] == "OBJECT_TYPE" && t.Tokens[i] == "Product":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "has_data_structure"})
		case t.NerTag[i] == "OBJECT_TYPE" && t.NerTag[i-1] == "DETERMINER":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: i - 1, Relation: "det"})

		case i > 0 && t.NerTag[i] == "DATA_STRUCTURE_FIELD" && t.NerTag[i-1] == "DATA_TYPE" && t.Tokens[i-1] == "string":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "string_fields"})

		case i > 0 && t.NerTag[i] == "OBJECT_TYPE" && t.NerTag[i-1] == "DATA_TYPE" && t.Tokens[i-1] == "integer":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i - 1, Dependent: i, Relation: "integer_field"})
		case i < len(t.Tokens)-1 && t.NerTag[i] == "COMMAND":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: i + 1, Relation: "command"})
		case i > 0 && t.Tokens[i-1] == "data" && t.Tokens[i] == "structure":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i, Dependent: i - 1, Relation: "compound"})
		case t.Tokens[i] == "the" && t.PosTag[i] == "DET":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "det"})
		case t.Tokens[i] == "named" && t.PosTag[i] == "JJ" || t.PosTag[i] == "NN":
			t.Dependencies = append(t.Dependencies, tag.Dependency{Head: i + 1, Dependent: i, Relation: "det"})
			if rootIndex != -1 {
				t.Dependencies = append(t.Dependencies, tag.Dependency{Head: -1, Dependent: rootIndex, Relation: "root"})
			}
			for i := range t.Tokens {
				switch {
				case t.PosTag[i] == "DT":

					nounIndex := -1
					for j := i + 1; j < len(t.Tokens); j++ {
						if t.PosTag[j] == "NN" || t.PosTag[j] == "NNS" || t.NerTag[j] == "OBJECT_NAME" || t.NerTag[j] == "OBJECT_TYPE" {
							nounIndex = j
							break
						}
					}
					if nounIndex != -1 {
						t.Dependencies = append(t.Dependencies, tag.Dependency{Head: nounIndex, Dependent: i, Relation: "det"})
					}
				}
			}

			if len(t.Tokens) != len(t.Dependencies) {
				diff := len(t.Tokens) - len(t.Dependencies)

				if diff > 0 {
					for range diff {
						t.Dependencies = append(t.Dependencies, tag.Dependency{Relation: " "})
					}
				} else {

					t.Dependencies = t.Dependencies[:len(t.Tokens)]
				}
			}
		}
	}
	return t, nil

}

// NewEntityPostProcessor creates a new entity post-processor
func NewEntityPostProcessor(tokens []string, posTags []string) *EntityPostProcessor {
	parser := NewSemanticParser(tokens, posTags)
	tree, srl := parser.Parse()

	return &EntityPostProcessor{
		tokens:		tokens,
		posTags:	posTags,
		stopWordFilter:	NewStopWordFilter(),
		semanticParser:	parser,
		tree:		tree,
		srl:		srl,
	}
}

// ProcessParameters applies semantic filtering to command parameters
func (ep *EntityPostProcessor) ProcessParameters(params map[string]string) map[string]string {
	processed := make(map[string]string)

	for key, value := range params {

		filtered := ep.stopWordFilter.FilterParameter(value)

		filtered = strings.TrimSpace(filtered)

		if filtered != "" {
			processed[key] = filtered
		}
	}

	return processed
}

// ExtractPrimaryEntity extracts the most likely entity name from the sentence
// Uses leaf nodes and entity heads from the dependency tree
func (ep *EntityPostProcessor) ExtractPrimaryEntity() string {

	if patients, ok := ep.srl.Arguments[Patient]; ok && len(patients) > 0 {
		return ep.tokens[patients[0]]
	}

	leaves := ep.tree.ExtractLeafNodes()
	for _, leaf := range leaves {
		lower := strings.ToLower(leaf)

		if !ep.stopWordFilter.IntentKeywords[lower] && !ep.stopWordFilter.ObjectKeywords[lower] {
			return leaf
		}
	}

	for i, pos := range ep.posTags {
		if pos == "NNP" {
			return ep.tokens[i]
		}
	}

	heads := ep.tree.FindEntityHeads()
	if len(heads) > 0 {
		return ep.tokens[heads[0]]
	}

	return ""
}

// ExtractEntitiesByRole extracts all entities for a given semantic role
func (ep *EntityPostProcessor) ExtractEntitiesByRole(role SemanticRole) []string {
	var entities []string

	if indices, ok := ep.srl.Arguments[role]; ok {
		for _, idx := range indices {
			entity := ep.tokens[idx]
			lower := strings.ToLower(entity)

			if !ep.stopWordFilter.IntentKeywords[lower] && !ep.stopWordFilter.ObjectKeywords[lower] {

				entity = strings.TrimRight(entity, ".,!?;:")
				if entity != "" {
					entities = append(entities, entity)
				}
			}
		}
	}

	return entities
}

// ValidateAndCleanEntity validates an entity against stop-word filter
func (ep *EntityPostProcessor) ValidateAndCleanEntity(entity string) (string, bool) {
	cleaned := strings.TrimSpace(entity)
	cleaned = strings.TrimRight(cleaned, ".,!?;:")

	tokens := strings.Fields(cleaned)
	hasNonKeyword := false

	for _, token := range tokens {
		cleanToken := strings.ToLower(strings.TrimRight(token, ".,!?;:"))
		if !ep.stopWordFilter.IntentKeywords[cleanToken] && !ep.stopWordFilter.ObjectKeywords[cleanToken] {
			hasNonKeyword = true
			break
		}
	}

	return cleaned, hasNonKeyword && cleaned != ""
}

// NertaggerWithSRL performs Named Entity Recognition with Semantic Role Labeling
// This combines IOB tagging with semantic understanding for better accuracy
func NertaggerWithSRL(t tag.Tag) tag.Tag {

	t = NertaggerWithIOB(t)

	postProcessor := NewEntityPostProcessor(t.Tokens, t.PosTag)

	enhancedTags := make([]string, len(t.Tokens))
	copy(enhancedTags, t.NerTag)

	for role, indices := range postProcessor.srl.Arguments {
		for _, idx := range indices {
			if idx < len(enhancedTags) {

				switch role {
				case Agent, Patient:
					if !strings.HasPrefix(enhancedTags[idx], "B-NAME") {
						enhancedTags[idx] = "B-NAME"
					}
				case Predicate:
					if !strings.HasPrefix(enhancedTags[idx], "B-ACTION") {
						enhancedTags[idx] = "B-ACTION"
					}
				case Location:
					if !strings.HasPrefix(enhancedTags[idx], "B-PATH") {
						enhancedTags[idx] = "B-PATH"
					}
				case Instrument, Attribute:
					if !strings.HasPrefix(enhancedTags[idx], "B-ATTRIBUTE") {
						enhancedTags[idx] = "B-ATTRIBUTE"
					}
				}
			}
		}
	}

	t.NerTag = enhancedTags
	return t
}

// ExtractCleanParameters extracts and cleans parameters using SRL
func ExtractCleanParameters(tokens []string, posTags []string, paramTriggers map[string]string) map[string]string {
	postProcessor := NewEntityPostProcessor(tokens, posTags)
	rawParams := make(map[string]string)

	for i, token := range tokens {
		lower := strings.ToLower(token)
		if paramKey, isParam := paramTriggers[lower]; isParam {

			if i+1 < len(tokens) {
				value := tokens[i+1]

				j := i + 1
				for j < len(tokens) {
					if tokens[j] == "the" || tokens[j] == "a" || tokens[j] == "an" {
						j++
						continue
					}
					value = tokens[j]
					break
				}
				rawParams[paramKey] = value
			}
		}
	}

	return postProcessor.ProcessParameters(rawParams)
}

// AnalyzeSentence provides detailed analysis of a sentence for debugging
func AnalyzeSentence(tokens []string, posTags []string) map[string]any {
	parser := NewSemanticParser(tokens, posTags)
	tree, srl := parser.Parse()
	postProcessor := NewEntityPostProcessor(tokens, posTags)

	analysis := map[string]any{
		"tokens":		tokens,
		"pos_tags":		posTags,
		"predicate":		srl.Predicate,
		"predicate_idx":	srl.PredIdx,
		"dependency_tree": map[string]any{
			"edges":	tree.Edges,
			"parents":	tree.Parent,
			"leaf_nodes":	tree.ExtractLeafNodes(),
			"entity_heads":	tree.FindEntityHeads(),
		},
		"semantic_roles":	map[string][]string{},
		"primary_entity":	postProcessor.ExtractPrimaryEntity(),
	}

	for role, indices := range srl.Arguments {
		var roleTokens []string
		for _, idx := range indices {
			roleTokens = append(roleTokens, tokens[idx])
		}
		analysis["semantic_roles"].(map[string][]string)[string(role)] = roleTokens
	}

	return analysis
}

// NewIntentPipeline creates a new intent processing pipeline
func NewIntentPipeline(text string, tokens []string, posTags []string) *IntentPipeline {
	return &IntentPipeline{
		text:			text,
		segmenter:		NewIntentSegmenter(text),
		verbCounter:		NewVerbCounter(),
		postProcessor:		NewEntityPostProcessor(tokens, posTags),
		prepositionMatcher:	NewPrepositionMatcher(),
	}
}

// Process orchestrates the full intent analysis pipeline
func (ip *IntentPipeline) Process() (*TaskGraph, error) {

	segments := ip.segmenter.Segment()
	log.Printf("DEBUG: Segmented %d intent(s)", len(segments))

	enrichedSegments := ip.enrichSegments(segments)

	ip.converter = NewSegmentToTaskConverter(enrichedSegments)
	taskGraph := ip.converter.Convert()

	if err := taskGraph.SortTopologically(); err != nil {
		log.Printf("ERROR: Failed to sort tasks: %v", err)
		return nil, err
	}

	log.Printf("DEBUG: Generated task graph with %d task(s)", len(taskGraph.Tasks))
	return taskGraph, nil
}

// enrichSegments enhances segments with extracted entities
func (ip *IntentPipeline) enrichSegments(segments []IntentSegment) []IntentSegment {
	registry := NewActionRegistry()

	for i := range segments {

		primary := ip.postProcessor.ExtractPrimaryEntity()
		if primary != "" {
			segments[i].Entities[primary] = "IDENTIFIER"
		}

		prepPairs := ip.prepositionMatcher.ExtractPrepositionPairs(segments[i].RawText)

		for _, action := range segments[i].Actions {
			actionType := registry.GetActionType(action)
			segments[i].Parameters["action_type"] = actionType

			switch actionType {
			case "CREATE":
				if primary != "" {
					segments[i].Parameters["name"] = primary
				}
				if destinations, ok := prepPairs["destination"]; ok && len(destinations) > 0 {
					segments[i].Parameters["path"] = destinations[0]
				}

			case "MOVE":
				if sources, ok := prepPairs["source"]; ok && len(sources) > 0 {
					segments[i].Parameters["source"] = sources[0]
				}
				if destinations, ok := prepPairs["destination"]; ok && len(destinations) > 0 {
					segments[i].Parameters["destination"] = destinations[0]
				} else if primary != "" {
					segments[i].Parameters["destination"] = primary
				}

			case "DELETE":
				if primary != "" {
					segments[i].Parameters["target"] = primary
				}

			case "UPDATE":
				if primary != "" {
					segments[i].Parameters["target"] = primary
				}
				if attributes, ok := prepPairs["attribute"]; ok && len(attributes) > 0 {
					segments[i].Parameters["attribute"] = attributes[0]
				}
			}
		}

		segments[i].Parameters = ip.postProcessor.ProcessParameters(segments[i].Parameters)
	}

	return segments
}

type VerbCounterMiddleware struct {
	verbCounter *VerbCounter
}

// NewVerbCounterMiddleware creates the middleware
func NewVerbCounterMiddleware() *VerbCounterMiddleware {
	return &VerbCounterMiddleware{
		verbCounter: NewVerbCounter(),
	}
}

// ValidateParameters checks if parameters might be echoed/duplicated
func (vcm *VerbCounterMiddleware) ValidateParameters(params map[string]string) map[string]string {
	validated := make(map[string]string)
	seenValues := make(map[string][]string)

	for key, value := range params {
		seenValues[value] = append(seenValues[value], key)
	}

	for key, value := range params {
		if keys, ok := seenValues[value]; ok && len(keys) > 1 {

			if keys[0] == key {
				validated[key] = value
			}

		} else {
			validated[key] = value
		}
	}

	return validated
}

