// NewActionRegistry creates a registry of known action verbs
func NewActionRegistry() *ActionRegistry {
	return &ActionRegistry{
		CreationActions: map[string]bool{
			"create":	true, "make": true, "build": true, "generate": true,
			"add":	true, "insert": true, "append": true, "write": true,
			"initialize":	true, "init": true, "setup": true, "new": true,
		},
		DeletionActions: map[string]bool{
			"delete":	true, "remove": true, "drop": true, "erase": true,
			"destroy":	true, "unlink": true,
		},
		MovementActions: map[string]bool{
			"move":	true, "copy": true, "rename": true, "mv": true,
			"cp":	true, "put": true, "place": true, "transfer": true,
		},
		ModificationActions: map[string]bool{
			"update":	true, "modify": true, "change": true, "alter": true,
			"edit":	true, "patch": true,
		},
		QueryActions: map[string]bool{
			"list":	true, "show": true, "display": true, "print": true,
			"read":	true, "cat": true, "grep": true, "search": true,
		},
	}
}

// GetActionType returns the type of action
func (ar *ActionRegistry) GetActionType(verb string) string {
	lower := strings.ToLower(verb)
	if ar.CreationActions[lower] {
		return "CREATE"
	}
	if ar.DeletionActions[lower] {
		return "DELETE"
	}
	if ar.MovementActions[lower] {
		return "MOVE"
	}
	if ar.ModificationActions[lower] {
		return "UPDATE"
	}
	if ar.QueryActions[lower] {
		return "QUERY"
	}
	return "UNKNOWN"
}

// IsActionVerb checks if a word is an action verb
func (ar *ActionRegistry) IsActionVerb(verb string) bool {
	lower := strings.ToLower(verb)
	return ar.CreationActions[lower] ||
		ar.DeletionActions[lower] ||
		ar.MovementActions[lower] ||
		ar.ModificationActions[lower] ||
		ar.QueryActions[lower]
}

type ConjunctionSplitter struct {
	conjunctions	map[string]bool
	transitions	map[string]bool
}

// NewConjunctionSplitter creates a splitter for multi-intent sentences
func NewConjunctionSplitter() *ConjunctionSplitter {
	return &ConjunctionSplitter{
		conjunctions: map[string]bool{
			"and":	true, "or": true, "then": true, "afterwards": true,
			"next":	true, "also": true, "additionally": true, "furthermore": true,
		},
		transitions: map[string]bool{
			"followed by":	true, "after that": true, "subsequently": true,
			"then":	true, "next": true, "finally": true,
		},
	}
}

// FindSplitPoints identifies where to split multi-intent sentences
func (cs *ConjunctionSplitter) FindSplitPoints(text string) []int {
	tokens := strings.Fields(text)
	var splitPoints []int

	for i, token := range tokens {
		lower := strings.ToLower(token)

		if cs.conjunctions[lower] {
			splitPoints = append(splitPoints, i)
		}

		if i+1 < len(tokens) {
			twoWord := lower + " " + strings.ToLower(tokens[i+1])
			if cs.transitions[twoWord] {
				splitPoints = append(splitPoints, i)
			}
		}
	}

	return splitPoints
}

// NewIntentSegmenter creates a segmenter for multi-intent text
func NewIntentSegmenter(text string) *IntentSegmenter {
	return &IntentSegmenter{
		originalText:	text,
		segments:	[]IntentSegment{},
	}
}

// Segment splits text into individual intent segments
func (is *IntentSegmenter) Segment() []IntentSegment {
	splitter := NewConjunctionSplitter()
	splitPoints := splitter.FindSplitPoints(is.originalText)

	if len(splitPoints) == 0 {

		segment := is.createSegment(is.originalText, 0)
		is.segments = []IntentSegment{segment}
		return is.segments
	}

	tokens := strings.Fields(is.originalText)
	var segmentTexts []string
	lastIdx := 0

	for _, splitIdx := range splitPoints {

		if splitIdx > lastIdx {
			segment := strings.Join(tokens[lastIdx:splitIdx], " ")
			if strings.TrimSpace(segment) != "" {
				segmentTexts = append(segmentTexts, segment)
			}
		}
		lastIdx = splitIdx + 1
	}

	if lastIdx < len(tokens) {
		segment := strings.Join(tokens[lastIdx:], " ")
		if strings.TrimSpace(segment) != "" {
			segmentTexts = append(segmentTexts, segment)
		}
	}

	for i, text := range segmentTexts {
		segment := is.createSegment(text, i)
		is.segments = append(is.segments, segment)
	}

	is.identifyDependencies()

	return is.segments
}

// createSegment creates a single IntentSegment from text
func (is *IntentSegmenter) createSegment(text string, priority int) IntentSegment {
	segment := IntentSegment{
		RawText:	text,
		Tokens:		strings.Fields(text),
		Actions:	[]string{},
		Entities:	make(map[string]string),
		Parameters:	make(map[string]string),
		Priority:	priority,
		Dependencies:	[]int{},
	}

	registry := NewActionRegistry()
	for _, token := range segment.Tokens {
		if registry.IsActionVerb(token) {
			segment.Actions = append(segment.Actions, token)
		}
	}

	return segment
}

// identifyDependencies tracks which segments depend on which
func (is *IntentSegmenter) identifyDependencies() {
	registry := NewActionRegistry()

	for i := range is.segments {

		for _, action := range is.segments[i].Actions {
			if registry.GetActionType(action) == "MOVE" {

				for j := range i {
					for _, priorAction := range is.segments[j].Actions {
						if registry.GetActionType(priorAction) == "CREATE" {
							is.segments[i].Dependencies = append(is.segments[i].Dependencies, j)
						}
					}
				}
			}
		}
	}
}

type SlotConstraintValidator struct {
	constraints map[string][]SlotConstraint
}

// NewSlotConstraintValidator creates a validator with default constraints
func NewSlotConstraintValidator() *SlotConstraintValidator {
	return &SlotConstraintValidator{
		constraints: map[string][]SlotConstraint{
			"CREATE": {
				{
					SlotName:	"name",
					IsRequired:	true,
					AllowedTypes:	[]string{"FILENAME", "DIRNAME", "IDENTIFIER"},
					PriorityRank:	1,
				},
				{
					SlotName:	"path",
					IsRequired:	false,
					AllowedTypes:	[]string{"PATH"},
					PriorityRank:	2,
				},
			},
			"MOVE": {
				{
					SlotName:	"source",
					IsRequired:	true,
					AllowedTypes:	[]string{"FILENAME", "DIRNAME"},
					PriorityRank:	1,
				},
				{
					SlotName:	"destination",
					IsRequired:	true,
					AllowedTypes:	[]string{"PATH", "DIRNAME"},
					PriorityRank:	2,
				},
			},
			"DELETE": {
				{
					SlotName:	"target",
					IsRequired:	true,
					AllowedTypes:	[]string{"FILENAME", "DIRNAME"},
					PriorityRank:	1,
				},
			},
		},
	}
}

// AssignSlots assigns entities to slots based on constraints and priority
func (scv *SlotConstraintValidator) AssignSlots(actionType string, entities []string, entityTypes []string) map[string]string {
	slots := make(map[string]string)

	constraints, ok := scv.constraints[actionType]
	if !ok {

		for i, entity := range entities {
			if i == 0 {
				slots["primary"] = entity
			} else {
				slots["secondary"] = entity
			}
		}
		return slots
	}

	entityIdx := 0
	for _, constraint := range constraints {
		if entityIdx < len(entities) && constraint.IsRequired {

			if entityIdx < len(entityTypes) {
				if is_allowed_type(entityTypes[entityIdx], constraint.AllowedTypes) {
					slots[constraint.SlotName] = entities[entityIdx]
					entityIdx++
				}
			}
		}
	}

	return slots
}

// is_allowed_type checks if an entity type is in the allowed list
func is_allowed_type(entityType string, allowedTypes []string) bool {
	if slices.Contains(allowedTypes, entityType) {
		return true
	}
	return len(allowedTypes) == 0
}

type VerbCounter struct {
	registry	*ActionRegistry
	actionCounts	map[string]int	// Action type -> count
}

// NewVerbCounter creates a new verb counter
func NewVerbCounter() *VerbCounter {
	return &VerbCounter{
		registry:	NewActionRegistry(),
		actionCounts:	make(map[string]int),
	}
}

// CountVerbs analyzes verbs in tokens and returns counts
func (vc *VerbCounter) CountVerbs(tokens []string) map[string]int {
	for _, token := range tokens {
		if vc.registry.IsActionVerb(token) {
			actionType := vc.registry.GetActionType(token)
			vc.actionCounts[actionType]++
		}
	}
	return vc.actionCounts
}

// HasMultipleActions checks if multiple different actions are present
func (vc *VerbCounter) HasMultipleActions() bool {
	actionTypeCount := 0
	for _, count := range vc.actionCounts {
		if count > 0 {
			actionTypeCount++
		}
	}
	return actionTypeCount > 1
}

type TaskGraph struct {
	Tasks	map[int]*Task
	Order	[]int	// Topologically sorted task IDs
}

// NewTaskGraph creates an empty task graph
func NewTaskGraph() *TaskGraph {
	return &TaskGraph{
		Tasks:	make(map[int]*Task),
		Order:	[]int{},
	}
}

// AddTask adds a task to the graph
func (tg *TaskGraph) AddTask(task *Task) {
	tg.Tasks[task.ID] = task
}

// SortTopologically sorts tasks by dependencies using Kahn's algorithm
func (tg *TaskGraph) SortTopologically() error {

	inDegree := make(map[int]int)
	adjList := make(map[int][]int)

	for id := range tg.Tasks {
		if _, ok := inDegree[id]; !ok {
			inDegree[id] = 0
		}
	}

	for _, task := range tg.Tasks {
		for _, depID := range task.DependsOn {
			inDegree[task.ID]++
			adjList[depID] = append(adjList[depID], task.ID)
		}
	}

	// Find all nodes with in-degree 0
	var queue []int
	for id, degree := range inDegree {
		if degree == 0 {
			queue = append(queue, id)
		}
	}

	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		tg.Order = append(tg.Order, current)

		for _, neighbor := range adjList[current] {
			inDegree[neighbor]--
			if inDegree[neighbor] == 0 {
				queue = append(queue, neighbor)
			}
		}
	}

	if len(tg.Order) != len(tg.Tasks) {
		return &CycleError{Message: "Circular dependency detected in task graph"}
	}

	return nil
}

type CycleError struct {
	Message string
}

func (e *CycleError) Error() string {
	return e.Message
}

type SegmentToTaskConverter struct {
	segments	[]IntentSegment
	actionReg	*ActionRegistry
	validator	*SlotConstraintValidator
}

// NewSegmentToTaskConverter creates a converter
func NewSegmentToTaskConverter(segments []IntentSegment) *SegmentToTaskConverter {
	return &SegmentToTaskConverter{
		segments:	segments,
		actionReg:	NewActionRegistry(),
		validator:	NewSlotConstraintValidator(),
	}
}

// Convert transforms segments into a task graph
func (stc *SegmentToTaskConverter) Convert() *TaskGraph {
	graph := NewTaskGraph()
	taskID := 0

	for segIdx, segment := range stc.segments {

		for _, action := range segment.Actions {
			actionType := stc.actionReg.GetActionType(action)

			entities := stc.extractEntities(segment)
			slots := stc.validator.AssignSlots(actionType, entities, stc.getEntityTypes(segment, entities))

			task := &Task{
				ID:		taskID,
				Action:		actionType,
				Target:		slots["source"] + slots["name"] + slots["primary"],
				Destination:	slots["destination"] + slots["secondary"],
				Parameters:	slots,
				Status:		"PENDING",
			}

			for _, depIdx := range segment.Dependencies {
				if depIdx < segIdx {

					for _, otherTask := range graph.Tasks {
						if len(otherTask.DependsOn) == 0 && depIdx < segIdx {
							task.DependsOn = append(task.DependsOn, otherTask.ID)
						}
					}
				}
			}

			graph.AddTask(task)
			taskID++
		}
	}

	_ = graph.SortTopologically()
	return graph
}

// extractEntities pulls entity names from segment
func (stc *SegmentToTaskConverter) extractEntities(segment IntentSegment) []string {
	var entities []string
	for entity := range segment.Entities {
		entities = append(entities, entity)
	}
	return entities
}

// getEntityTypes returns types for extracted entities
func (stc *SegmentToTaskConverter) getEntityTypes(segment IntentSegment, entities []string) []string {
	var types []string
	for _, entity := range entities {
		if etype, ok := segment.Entities[entity]; ok {
			types = append(types, etype)
		} else {
			types = append(types, "IDENTIFIER")
		}
	}
	return types
}

type PrepositionMatcher struct {
	patterns map[string]*regexp.Regexp
}

// NewPrepositionMatcher creates a matcher for prepositions
func NewPrepositionMatcher() *PrepositionMatcher {
	return &PrepositionMatcher{
		patterns: map[string]*regexp.Regexp{
			"destination":	regexp.MustCompile(`\b(in|into|to|within|inside|under)\s+(\w+)`),
			"source":	regexp.MustCompile(`\b(from|out of|off)\s+(\w+)`),
			"attribute":	regexp.MustCompile(`\b(with|using|via)\s+(\w+)`),
			"location":	regexp.MustCompile(`\b(at|on|near|beside)\s+(\w+)`),
		},
	}
}

// ExtractPrepositionPairs extracts entity-preposition-entity relationships
func (pm *PrepositionMatcher) ExtractPrepositionPairs(text string) map[string][]string {
	pairs := make(map[string][]string)

	for relation, pattern := range pm.patterns {
		matches := pattern.FindAllStringSubmatch(text, -1)
		for _, match := range matches {
			if len(match) > 2 {
				pairs[relation] = append(pairs[relation], match[2])
			}
		}
	}

	return pairs
}

type iobRule struct {
	pattern		*regexp.Regexp
	entityType	string
	triggerWords	map[string]bool	// Words that can trigger continuation
}

// initIOBRules initializes the IOB pattern matching rules
func initIOBRules() {
	iobRules = []iobRule{

		{
			pattern:	regexp.MustCompile(`(?i)\b(create|add|make|generate|initialize|init|new|setup|start|put|copy)\b`),
			entityType:	"ACTION",
			triggerWords: map[string]bool{
				"a":	false, "an": false, "the": false, "with": false, "for": false,
			},
		},

		{
			pattern:	regexp.MustCompile(`(?i)\b(delete|remove|mv|move)\b`),
			entityType:	"ACTION",
			triggerWords: map[string]bool{
				"a":	false, "an": false, "the": false,
			},
		},

		{
			pattern:	regexp.MustCompile(`(?i)\b(webserver|website|site|application|app)\b`),
			entityType:	"TYPE",
			triggerWords: map[string]bool{
				"named":	true, "called": true,
			},
		},
		{
			pattern:	regexp.MustCompile(`(?i)\b(database|db|table)\b`),
			entityType:	"TYPE",
			triggerWords: map[string]bool{
				"named":	true, "called": true, "with": false,
			},
		},
		{
			pattern:	regexp.MustCompile(`(?i)\b(handler|endpoint|route)\b`),
			entityType:	"TYPE",
			triggerWords: map[string]bool{
				"named":	true, "called": true, "at": true, "url": true,
			},
		},
		{
			pattern:	regexp.MustCompile(`(?i)\b(page|view|component)\b`),
			entityType:	"TYPE",
			triggerWords: map[string]bool{
				"named":	true, "called": true,
			},
		},
		{
			pattern:	regexp.MustCompile(`(?i)\b(file|folder|directory|structure|data\s+structure)\b`),
			entityType:	"TYPE",
			triggerWords: map[string]bool{
				"named":	true, "called": true, "in": true, "into": true,
			},
		},

		{
			pattern:	regexp.MustCompile(`(?i)\b(named|called)\b`),
			entityType:	"NAME",
			triggerWords:	map[string]bool{},
		},

		{
			pattern:	regexp.MustCompile(`^/[a-zA-Z0-9/_-]*`),
			entityType:	"URL",
			triggerWords: map[string]bool{
				"at":	false, "url": false,
			},
		},

		{
			pattern:	regexp.MustCompile(`^[a-zA-Z0-9_./\\-]+$`),
			entityType:	"PATH",
			triggerWords: map[string]bool{
				"in":	true, "into": true, "to": true,
			},
		},
	}
}

type IOBTagger struct {
	tokens		[]string
	posTags		[]string
	iobTags		[]string
	entityBounds	map[int]string	// Maps token index to entity type
}

// NewIOBTagger creates a new IOB tagger
func NewIOBTagger(tokens []string, posTags []string) *IOBTagger {
	iobRulesOnce.Do(initIOBRules)

	tagger := &IOBTagger{
		tokens:		tokens,
		posTags:	posTags,
		iobTags:	make([]string, len(tokens)),
		entityBounds:	make(map[int]string),
	}

	for i := range tagger.iobTags {
		tagger.iobTags[i] = O_TAG
	}

	return tagger
}

// Tag performs the IOB tagging process
func (t *IOBTagger) Tag() []string {

	t.markEntityBeginnings()

	t.extendEntities()

	t.resolveConflicts()

	t.applyPOSFallback()

	return t.iobTags
}

// markEntityBeginnings identifies the start of entities (B- tags)
func (t *IOBTagger) markEntityBeginnings() {
	for i, token := range t.tokens {
		if t.iobTags[i] != O_TAG {
			continue
		}

		for _, rule := range iobRules {
			if rule.pattern.MatchString(token) {
				// Determine the B- tag
				var btag string
				switch rule.entityType {
				case "ACTION":
					btag = B_ACTION
				case "TYPE":
					btag = B_TYPE
				case "NAME":
					btag = B_NAME
				case "ATTRIBUTE":
					btag = B_ATTRIBUTE
				case "TARGET":
					btag = B_TARGET
				case "SOURCE":
					btag = B_SOURCE
				case "URL":
					btag = B_URL
				case "PATH":
					btag = B_PATH
				default:
					btag = "B-" + rule.entityType
				}

				t.iobTags[i] = btag
				t.entityBounds[i] = rule.entityType
				break
			}
		}

		if t.iobTags[i] == O_TAG && (t.posTags[i] == "NNP" || t.posTags[i] == "NNPS") {
			t.iobTags[i] = B_NAME
			t.entityBounds[i] = "NAME"
		}
	}
}

// extendEntities marks continuation tokens as "I-" (Inside)
func (t *IOBTagger) extendEntities() {
	var lastEntityType string
	var lastWasEntity bool

	for i := 0; i < len(t.tokens); i++ {
		currentTag := t.iobTags[i]

		if after, ok := strings.CutPrefix(currentTag, "B-"); ok {
			lastEntityType = after
			lastWasEntity = true
			continue
		}

		if currentTag == O_TAG && lastWasEntity && lastEntityType != "" {

			lower := strings.ToLower(t.tokens[i])

			separators := map[string]bool{
				"named":	true, "called": true, "in": true, "into": true,
				"to":	true, "for": true, "with": true, "from": true,
				"at":	true, "url": true, "is": true, "and": true,
			}

			if separators[lower] || t.posTags[i] == "IN" || t.posTags[i] == "CC" {
				lastWasEntity = false
				continue
			}

			if (lastEntityType == "TYPE" || lastEntityType == "NAME") &&
				(t.posTags[i] == "NN" || t.posTags[i] == "NNS" || t.posTags[i] == "NNP" || t.posTags[i] == "NNPS" || t.posTags[i] == "CD") {
				itag := "I-" + lastEntityType
				t.iobTags[i] = itag
				continue
			}

			if lastEntityType == "TYPE" && (t.posTags[i] == "JJ" || t.posTags[i] == "NN" || t.posTags[i] == "NNS") {
				itag := "I-" + lastEntityType
				t.iobTags[i] = itag
				continue
			}

			lastWasEntity = false
		} else if currentTag == O_TAG {
			lastWasEntity = false
		}
	}
}

// resolveConflicts handles overlapping entity boundaries and special cases
func (t *IOBTagger) resolveConflicts() {

	for i := 0; i < len(t.tokens)-1; i++ {
		if strings.ToLower(t.tokens[i]) == "data" && strings.ToLower(t.tokens[i+1]) == "structure" {
			if t.iobTags[i] == O_TAG {
				t.iobTags[i] = B_TYPE
				t.iobTags[i+1] = I_TYPE
				t.entityBounds[i] = "TYPE"
			}
		}
	}

	for i := 0; i < len(t.tokens); i++ {
		if strings.HasPrefix(t.iobTags[i], "B-URL") {

			j := i + 1
			for j < len(t.tokens) && (strings.Contains(t.tokens[j], "/") || strings.Contains(t.tokens[j], "-") || t.posTags[j] == "NN") {
				t.iobTags[j] = "I-URL"
				j++
			}
		}
	}

	for i := 1; i < len(t.tokens); i++ {
		if strings.HasPrefix(t.iobTags[i], "B-NAME") {
			prev := strings.ToLower(t.tokens[i-1])
			prevTag := t.iobTags[i-1]

			if prev == "named" || prev == "called" {
				continue
			}

			if strings.HasPrefix(prevTag, "B-TYPE") || strings.HasPrefix(prevTag, "I-TYPE") {
				continue
			}

			if t.posTags[i] == "NNP" || t.posTags[i] == "NNPS" {
				continue
			}

			if prev != "named" && prev != "called" {
				t.iobTags[i] = O_TAG
			}
		}
	}
}

// applyPOSFallback assigns POS tags to untagged tokens
func (t *IOBTagger) applyPOSFallback() {
	for i := 0; i < len(t.iobTags); i++ {
		if t.iobTags[i] == O_TAG {

			t.iobTags[i] = t.posTags[i]
		}
	}
}

// TagTokensWithIOB performs IOB tagging on tokens
func TagTokensWithIOB(tokens []string, posTags []string) []string {
	tagger := NewIOBTagger(tokens, posTags)
	return tagger.Tag()
}

// NertaggerWithIOB extends the Tag struct with IOB tags
func NertaggerWithIOB(t tag.Tag) tag.Tag {

	t.NerTag = TagTokensWithIOB(t.Tokens, t.PosTag)
	return t
}

type EntitySpan struct {
	StartIdx	int
	EndIdx		int
	Text		string
}

// ParseIOBTags extracts entity spans from IOB-tagged tokens
// Returns a map of entity types to slices of entity spans
func ParseIOBTags(tokens []string, iobTags []string) map[string][]EntitySpan {
	entities := make(map[string][]EntitySpan)

	var currentEntity string
	var currentStart int

	for i := range iobTags {
		tag := iobTags[i]

		if strings.HasPrefix(tag, "B-") {

			if currentEntity != "" {
				entityType := currentEntity
				text := strings.Join(tokens[currentStart:i], " ")
				entities[entityType] = append(entities[entityType], EntitySpan{
					StartIdx:	currentStart,
					EndIdx:		i,
					Text:		text,
				})
			}

			currentEntity = strings.TrimPrefix(tag, "B-")
			currentStart = i
		} else if after, ok := strings.CutPrefix(tag, "I-"); ok {
			entityType := after

			if currentEntity != entityType {

				if currentEntity != "" {
					text := strings.Join(tokens[currentStart:i], " ")
					entities[currentEntity] = append(entities[currentEntity], EntitySpan{
						StartIdx:	currentStart,
						EndIdx:		i,
						Text:		text,
					})
				}
				currentEntity = entityType
				currentStart = i
			}
		} else {

			if currentEntity != "" {
				text := strings.Join(tokens[currentStart:i], " ")
				entities[currentEntity] = append(entities[currentEntity], EntitySpan{
					StartIdx:	currentStart,
					EndIdx:		i,
					Text:		text,
				})
				currentEntity = ""
			}
		}
	}

	if currentEntity != "" {
		text := strings.Join(tokens[currentStart:], " ")
		entities[currentEntity] = append(entities[currentEntity], EntitySpan{
			StartIdx:	currentStart,
			EndIdx:		len(tokens),
			Text:		text,
		})
	}

	return entities
}

// ValidateIOBSequence checks if an IOB tag sequence is valid
// Returns true if the sequence follows IOB rules
func ValidateIOBSequence(tags []string) bool {
	if len(tags) == 0 {
		return true
	}

	var lastType string

	for i, tag := range tags {
		if tag == "O" {
			lastType = ""
			continue
		}

		if after, ok := strings.CutPrefix(tag, "B-"); ok {
			lastType = after
			continue
		}

		if after, ok := strings.CutPrefix(tag, "I-"); ok {
			currentType := after

			if lastType != currentType {

				if i == 0 {
					return false
				}
				prevTag := tags[i-1]
				if !strings.HasPrefix(prevTag, "B-"+currentType) && !strings.HasPrefix(prevTag, "I-"+currentType) {
					return false
				}
			}
			lastType = currentType
			continue
		}

		return false
	}

	return true
}

func TagTokens(tokens []string, posTags []string) []string {
	return RefactoredTagTokens(tokens, posTags)
}

func Nertagger(t tag.Tag) tag.Tag {
	t.NerTag = RefactoredTagTokens(t.Tokens, t.PosTag)
	return t
}

type nerRule struct {
	pattern	*regexp.Regexp
	tag	string
}

func RefactoredTagTokens(tokens []string, posTags []string) []string {
	tags := make([]string, len(tokens))
	for i, token := range tokens {

		tags[i] = posTags[i]

		for _, rule := range rules {
			if rule.pattern.MatchString(token) {
				tags[i] = rule.tag
				break
			}
		}

		if posTags[i] == "NNP" || posTags[i] == "NNPS" {
			tags[i] = "NAME"
		}

		if i > 0 && (tags[i-1] == "OBJECT_TYPE" || tags[i-1] == "PREPOSITION" || tags[i-1] == "NAME_PREFIX") && posTags[i] == "NN" && token != "named" {
			tags[i] = "NAME"
		}
	}
	return tags
}

type DependencyEdge struct {
	Governor	int	// Index of the head
	Dependent	int	// Index of the dependent
	Relation	DependencyRelation
}

type SemanticParser struct {
	tokens	[]string
	posTags	[]string
	tree	*DependencyTree
	srl	*SRLAnalysis
}

// NewSemanticParser creates a new semantic parser
func NewSemanticParser(tokens []string, posTags []string) *SemanticParser {
	return &SemanticParser{
		tokens:		tokens,
		posTags:	posTags,
	}
}

// Parse performs semantic role labeling and dependency parsing
func (sp *SemanticParser) Parse() (*DependencyTree, *SRLAnalysis) {
	sp.tree = sp.buildDependencyTree()
	sp.srl = sp.performSRL()
	return sp.tree, sp.srl
}

// buildDependencyTree constructs a simplified dependency tree
// Based on POS tags and heuristics
func (sp *SemanticParser) buildDependencyTree() *DependencyTree {
	tree := &DependencyTree{
		Tokens:		sp.tokens,
		Edges:		[]DependencyEdge{},
		Children:	make(map[int][]int),
		Parent:		make(map[int]int),
		Relations:	make(map[int]DependencyRelation),
	}

	for i := range sp.tokens {
		tree.Parent[i] = -1
	}

	rootIdx := sp.findMainVerb()
	if rootIdx == -1 {
		rootIdx = 0
	}

	tree.Parent[rootIdx] = rootIdx
	tree.Relations[rootIdx] = Root

	for i := range sp.posTags {
		if i == rootIdx {
			continue
		}

		relation, headIdx := sp.determineRelation(i, rootIdx)
		if headIdx == -1 {
			headIdx = rootIdx
		}

		tree.Parent[i] = headIdx
		tree.Relations[i] = relation
		tree.Children[headIdx] = append(tree.Children[headIdx], i)

		tree.Edges = append(tree.Edges, DependencyEdge{
			Governor:	headIdx,
			Dependent:	i,
			Relation:	relation,
		})
	}

	return tree
}

// findMainVerb locates the main verb in the sentence
func (sp *SemanticParser) findMainVerb() int {
	for i, pos := range sp.posTags {

		if strings.HasPrefix(pos, "VB") && i > 0 {

			token := strings.ToLower(sp.tokens[i])
			if !isAuxiliary(token) && !isModal(token) {
				return i
			}
		}
	}

	for i, token := range sp.tokens {
		lower := strings.ToLower(token)
		if isActionVerb(lower) {
			return i
		}
	}

	return -1
}

// determineRelation determines the dependency relation between a token and a head
func (sp *SemanticParser) determineRelation(tokenIdx, rootIdx int) (DependencyRelation, int) {
	pos := sp.posTags[tokenIdx]

	if (strings.HasPrefix(pos, "NN") || strings.HasPrefix(pos, "PRP")) && tokenIdx < rootIdx {
		return Nsubj, rootIdx
	}

	if strings.HasPrefix(pos, "NN") && tokenIdx > rootIdx {
		return Obj, rootIdx
	}

	if strings.HasPrefix(pos, "JJ") {

		for i := tokenIdx + 1; i < len(sp.tokens); i++ {
			if strings.HasPrefix(sp.posTags[i], "NN") {
				return Amod, i
			}
		}
		return Amod, rootIdx
	}

	if strings.HasPrefix(pos, "RB") {
		return Advmod, rootIdx
	}

	if pos == "IN" {
		return Case, rootIdx
	}

	if pos == "DT" {

		for i := tokenIdx + 1; i < len(sp.tokens); i++ {
			if strings.HasPrefix(sp.posTags[i], "NN") {
				return Det, i
			}
		}
		return Det, rootIdx
	}

	if strings.HasPrefix(pos, "NN") && tokenIdx > 0 {
		if strings.HasPrefix(sp.posTags[tokenIdx-1], "NN") {
			return Compound, tokenIdx - 1
		}
	}

	return Dep, rootIdx
}

// performSRL performs semantic role labeling
func (sp *SemanticParser) performSRL() *SRLAnalysis {
	analysis := &SRLAnalysis{
		Tokens:		sp.tokens,
		Roles:		make(map[int]SemanticRole),
		Arguments:	make(map[SemanticRole][]int),
	}

	predIdx := sp.findMainVerb()
	if predIdx == -1 {
		predIdx = 0
	}

	analysis.PredIdx = predIdx
	analysis.Predicate = sp.tokens[predIdx]
	analysis.Roles[predIdx] = Predicate
	analysis.Arguments[Predicate] = append(analysis.Arguments[Predicate], predIdx)

	for i := range sp.tokens {
		if i == predIdx {
			continue
		}

		role := sp.assignSemanticRole(i, predIdx)
		analysis.Roles[i] = role
		analysis.Arguments[role] = append(analysis.Arguments[role], i)
	}

	return analysis
}

// assignSemanticRole assigns a semantic role to a token
func (sp *SemanticParser) assignSemanticRole(tokenIdx, predIdx int) SemanticRole {
	token := strings.ToLower(sp.tokens[tokenIdx])
	pos := sp.posTags[tokenIdx]

	if strings.HasPrefix(pos, "NNP") || strings.HasPrefix(pos, "NN") {
		if tokenIdx < predIdx {
			return Agent
		} else {
			return Patient
		}
	}

	if strings.HasPrefix(pos, "NNP") {
		return Patient
	}

	if strings.HasPrefix(pos, "JJ") {
		return Modifier
	}

	if strings.HasPrefix(pos, "RB") {
		return Modifier
	}

	if pos == "IN" {
		if isLocationPrep(token) {
			return Location
		}
		if isTimePrep(token) {
			return TimeArg
		}
		return Attribute
	}

	if pos == "DT" {
		return Modifier
	}

	return Modifier
}

func isAuxiliary(token string) bool {
	auxiliaries := map[string]bool{
		"is":	true, "are": true, "am": true, "was": true, "were": true,
		"be":	true, "been": true, "being": true,
		"have":	true, "has": true, "had": true,
		"do":	true, "does": true, "did": true,
	}
	return auxiliaries[strings.ToLower(token)]
}

func isModal(token string) bool {
	modals := map[string]bool{
		"can":	true, "could": true, "may": true, "might": true,
		"must":	true, "should": true, "would": true, "will": true,
		"shall":	true, "ought": true,
	}
	return modals[strings.ToLower(token)]
}

func isLocationPrep(token string) bool {
	locPreps := map[string]bool{
		"in":	true, "at": true, "on": true, "under": true,
		"over":	true, "above": true, "below": true, "inside": true,
		"outside":	true, "near": true, "between": true, "among": true,
	}
	return locPreps[token]
}

func isTimePrep(token string) bool {
	timePreps := map[string]bool{
		"at":	true, "on": true, "in": true, "during": true,
		"before":	true, "after": true, "since": true, "until": true,
		"throughout":	true, "within": true,
	}
	return timePreps[token]
}

// ExtractEntitiesWithSRL extracts entities using semantic role labeling
// This improves accuracy by understanding grammatical roles
func ExtractEntitiesWithSRL(tokens []string, posTags []string) map[SemanticRole][]string {
	parser := NewSemanticParser(tokens, posTags)
	_, srl := parser.Parse()

	entities := make(map[SemanticRole][]string)

	for role, indices := range srl.Arguments {
		for _, idx := range indices {
			entities[role] = append(entities[role], tokens[idx])
		}
	}

	return entities
}

type StopWordFilter struct {
	IntentKeywords	map[string]bool
	ObjectKeywords	map[string]bool
	FilteredTokens	map[string]bool
}

// NewStopWordFilter creates a new stop word filter
func NewStopWordFilter() *StopWordFilter {
	return &StopWordFilter{
		IntentKeywords: map[string]bool{
			"create":	true, "make": true, "add": true, "generate": true,
			"delete":	true, "remove": true, "update": true, "modify": true,
			"list":	true, "show": true, "display": true,
			"go":	true, "move": true, "copy": true,
			"run":	true, "start": true, "stop": true,
			"read":	true, "cat": true, "grep": true,
			"named":	true, "called": true, "for": true, "with": true,
			"in":	true, "into": true, "to": true, "from": true,
		},
		ObjectKeywords: map[string]bool{
			"file":	true, "folder": true, "directory": true, "database": true,
			"handler":	true, "webserver": true, "page": true, "form": true,
			"structure":	true, "table": true, "component": true, "endpoint": true,
			"route":	true, "view": true, "app": true, "application": true,
		},
		FilteredTokens:	make(map[string]bool),
	}
}

// FilterParameter removes intent/object keywords from a parameter value
func (sf *StopWordFilter) FilterParameter(paramValue string) string {
	tokens := strings.Fields(paramValue)
	var filtered []string

	for _, token := range tokens {
		lower := strings.ToLower(token)

		cleanToken := strings.TrimRight(lower, ".,!?;:")

		if sf.IntentKeywords[cleanToken] || sf.ObjectKeywords[cleanToken] {
			sf.FilteredTokens[cleanToken] = true
			continue
		}

		filtered = append(filtered, token)
	}

	return strings.Join(filtered, " ")
}

// IsValidParameter checks if a parameter is valid (not empty after filtering)
func (sf *StopWordFilter) IsValidParameter(paramValue string) bool {
	filtered := sf.FilterParameter(paramValue)
	return strings.TrimSpace(filtered) != ""
}

// ExtractLeafNodes extracts leaf nodes (entities) from the dependency tree
// Leaf nodes are tokens with no dependent children
func (dt *DependencyTree) ExtractLeafNodes() []string {
	var leaves []string

	for i := range dt.Tokens {

		if len(dt.Children[i]) == 0 {
			leaves = append(leaves, dt.Tokens[i])
		} else {

			allFunctionWords := true
			for _, childIdx := range dt.Children[i] {
				relation := dt.Relations[childIdx]
				if relation != Det && relation != Case && relation != Punct {
					allFunctionWords = false
					break
				}
			}
			if allFunctionWords {
				leaves = append(leaves, dt.Tokens[i])
			}
		}
	}

	return leaves
}

// FindEntityHeads finds the head nouns that are likely entity names
// In "Create a bash file named Jim", Jim is the entity head
func (dt *DependencyTree) FindEntityHeads() []int {
	var heads []int

	for i, pos := range dt.Tokens {

		if strings.HasPrefix(pos, "NN") {

			parent := dt.Parent[i]
			if parent != -1 && parent != i {
				parentPos := dt.Tokens[parent]

				if strings.HasPrefix(parentPos, "VB") || strings.HasPrefix(parentPos, "JJ") {
					heads = append(heads, i)
				}
			}
		}
	}

	return heads
}

