// take in text and return a map of tokens to NER tags
func Postagger(text string) tag.Tag {

	re := regexp.MustCompile(`[[:punct:]]`)

	striptext := re.ReplaceAllString(text, "")

	tokens := strings.Fields(striptext)
	t := tag.Tag{}
	var stemtoken string
	for _, token := range tokens {

		if token != "tls" {
			stemtoken = stem.Stem(token)
		}

		for pattern, tag := range posTags {
			re = regexp.MustCompile(pattern)

			if re.MatchString(stemtoken) {

				t.PosTag = append(t.PosTag, tag)
				break
			} else {
				match, err := regexp.MatchString(pattern, stemtoken)
				if err != nil {
					fmt.Println(err)
				}
				if match {
					t.PosTag = append(t.PosTag, tag)
					break
				}
			}
		}

	}
	t.Tokens = addMissingValues(t.Tokens, tokens)

	t.PosTag = padMissingvalues(t)
	t.Tokens = tokens

	return t
}

func TagTokens(tokens []string) []string {
	t := tag.Tag{
		Tokens: tokens,
	}
	var stemtoken string
	for _, token := range tokens {
		if token != "tls" {
			stemtoken = stem.Stem(token)
		}

		found := false
		for pattern, tag := range posTags {
			re := regexp.MustCompile(pattern)
			if re.MatchString(stemtoken) {
				t.PosTag = append(t.PosTag, tag)
				found = true
				break
			}
		}
		if !found {
			t.PosTag = append(t.PosTag, "NN")
		}
	}
	t = VerbCheck(t)
	t = NounCheck(t)

	if len(t.PosTag) > len(tokens) {
		t.PosTag = t.PosTag[:len(tokens)]
	}

	return t.PosTag
}

func addSpaces(word string) string {
	return " " + word + " "
}

func isNumber(token string) bool {
	_, err := strconv.Atoi(token)
	return err == nil
}

func addMissingValues(slice1, slice2 []string) []string {

	slice2Map := make(map[string]bool)
	for _, val := range slice2 {
		slice2Map[val] = true
	}

	for _, val := range slice1 {
		if _, ok := slice2Map[val]; !ok {
			slice2 = append(slice2, val)
		}
	}
	return slice2
}

func padMissingvaluesWithNN(target, source []string) []string {
	if len(target) >= len(source) {
		return target
	}
	diff := len(source) - len(target)
	padding := make([]string, diff)
	for i := range padding {

		padding[i] = "NN"
	}
	return append(target, padding...)
}

func padMissingvalues(t tag.Tag) []string {
	diff := len(t.Tokens) - len(t.PosTag)

	if diff <= 0 {
		return t.PosTag
	}
	padding := make([]string, diff)
	for i := range diff {

		for pattern, tag := range posTags {
			if regexp.MustCompile(pattern).MatchString(t.Tokens[len(t.PosTag)+i]) {
				padding[i] = tag
				break
			} else {
				padding[i] = "NN"
			}
		}
	}
	return append(t.PosTag, padding...)
}

type SuffixFrequency struct {
	Suffix		string
	Frequency	int
}

func Stem(word string) string {
	if word == "" {
		return ""
	}

	re := regexp.MustCompile(`ing$`)
	if re.MatchString(word) && len(word) >= 3 {
		if len(word) >= 4 && word[len(word)-4] == word[len(word)-3] {
			return word[:len(word)-3]
		}
		return re.ReplaceAllString(word, "")
	}

	re = regexp.MustCompile(`ed$`)
	if re.MatchString(word) {
		return re.ReplaceAllString(word, "")
	}

	re = regexp.MustCompile(`(s|es)$`)
	if re.MatchString(word) {
		return re.ReplaceAllString(word, "")
	}

	re = regexp.MustCompile(`ly$`)
	if re.MatchString(word) {
		return re.ReplaceAllString(word, "")
	}

	re = regexp.MustCompile(`([^aeiou])y$`)
	if re.MatchString(word) {
		return re.ReplaceAllString(word, "$1i")
	}

	suffixes := getSuffixesByFrequency(word)
	for _, suffixFreq := range suffixes {
		suffix := suffixFreq.Suffix
		stem := word[:len(word)-len(suffix)]
		if _, ok := stemFrequencies[stem]; ok && suffixFreq.Frequency >= minimumSuffixFrequency {
			return stem
		}
	}

	return word
}

// ... (other functions) ...
// Get suffixes sorted by frequency, considering only those present in commonSuffixes
func getSuffixesByFrequency(word string) []SuffixFrequency {
	var suffixes []SuffixFrequency
	for suffix, freq := range suffixFrequencies {
		if strings.HasSuffix(word, suffix) && commonSuffixes[suffix] {
			suffixes = append(suffixes, SuffixFrequency{suffix, freq})
		}
	}

	sort.Slice(suffixes, func(i, j int) bool {
		return suffixes[i].Frequency > suffixes[j].Frequency
	})
	return suffixes
}

