func filterString(tag tag.Tag, filters []string) string {

	if len(tag.Tokens) == 0 {
		return ""
	}
	var str strings.Builder
	for i, token := range tag.Tokens {
		filtered := false
		for _, filter := range filters {
			if tag.PosTag[i] == filter {

				filtered = true
			}
		}
		if !filtered {
			str.WriteString(token + " ")
		}
	}

	return strings.TrimSpace(str.String())

}

type Annealer struct {
	StartTemp	float32
	MinTemp		float32
	Decay		float32
	WarmUp		int	// Number of epochs to stay at StartTemp
}

// GetTemp calculates the temperature for the current epoch
func (a *Annealer) GetTemp(epoch int) float32 {

	if epoch < a.WarmUp {
		return a.StartTemp
	}

	decayEpoch := float64(epoch - a.WarmUp)
	temp := float32(float64(a.StartTemp) * math.Pow(float64(a.Decay), decayEpoch))

	if temp < a.MinTemp {
		return a.MinTemp
	}
	return temp
}

// WarpCommand takes a single command and generates several training variations.
// This forces the MoE architecture to learn the semantic intent rather than
// just memorizing exact token sequences.
func WarpCommand(input string) []string {
	variations := []string{input}
	words := strings.Fields(input)

	if len(words) > 0 {

		typoed := strings.Replace(input, "commit", "comit", 1)
		if typoed != input {
			variations = append(variations, typoed)
		}

		if strings.Contains(input, "create") {
			variations = append(variations, strings.Replace(input, "create", "cretae", 1))
		}
	}

	if len(words) > 3 {
		shuffled := make([]string, len(words))
		copy(shuffled, words)

		if len(shuffled) > 3 {
			rand.Shuffle(len(shuffled)-2, func(i, j int) {
				shuffled[i+2], shuffled[j+2] = shuffled[j+2], shuffled[i+2]
			})
			variations = append(variations, strings.Join(shuffled, " "))
		}
	}

	synonyms := map[string]string{
		"show":		"list",
		"list":		"show",
		"remove":	"delete",
		"delete":	"remove",
		"make":		"create",
		"create":	"make",
	}

	for key, value := range synonyms {
		if strings.Contains(strings.ToLower(input), key) {

			swapped := strings.Replace(strings.ToLower(input), key, value, 1)
			variations = append(variations, swapped)
		}
	}

	return variations
}

// ClipGradients applies global L2-norm clipping to a flat gradient slice.
// It preserves the direction of the gradient while capping its magnitude.
// This is the standard approach for MoE models because it avoids the
// "loud expert" problem where a single expert's large gradient overwhelms
// the rest of the network.
//
// Returns the raw norm before clipping and a bool indicating whether
// clipping was applied, useful for logging.
func ClipGradients(grads []float32, maxNorm float32) (rawNorm float32, clipped bool) {
	var sumSq float32
	for _, g := range grads {
		sumSq += g * g
	}

	rawNorm = float32(math.Sqrt(float64(sumSq)))
	if rawNorm > maxNorm {
		scale := maxNorm / (rawNorm + 1e-6)
		for i := range grads {
			grads[i] *= scale
		}
		clipped = true
	}
	return rawNorm, clipped
}

// ClipParamGrads applies ClipGradients across a set of parameter gradient
// slices, treating them as a single unified gradient vector.
// This is the correct way to clip across the full model, not layer by layer.
func ClipParamGrads(paramGrads [][]float32, maxNorm float32) (rawNorm float32, clipped bool) {
	// First pass: compute global L2 norm
	var sumSq float32
	for _, grads := range paramGrads {
		for _, g := range grads {
			sumSq += g * g
		}
	}

	rawNorm = float32(math.Sqrt(float64(sumSq)))
	if rawNorm > maxNorm {
		scale := maxNorm / (rawNorm + 1e-6)

		for _, grads := range paramGrads {
			for i := range grads {
				grads[i] *= scale
			}
		}
		clipped = true
	}
	return rawNorm, clipped
}

type PlateauState struct {
	BestPPL		float32
	BadEpochs	int
	CooldownTimer	int
}

// Update evaluates the current Perplexity and adjusts LR/Temperature if progress has stalled.
// It returns a status message describing the decision.
func (s *PlateauState) Update(currentPPL float32, config PlateauConfig, currentLR *float32, currentTemp *float32) string {
	if s.CooldownTimer > 0 {
		s.CooldownTimer--
		return "⏳ Cooldown active (waiting for stabilization)"
	}

	if currentPPL < s.BestPPL {
		s.BestPPL = currentPPL
		s.BadEpochs = 0
		return "✅ New best PPL achieved"
	}

	s.BadEpochs++
	if s.BadEpochs >= config.Patience {

		oldLR := *currentLR
		*currentLR = float32(math.Max(float64(config.MinLR), float64(*currentLR*config.Factor)))

		oldTemp := *currentTemp
		*currentTemp = float32(math.Max(0.1, float64(*currentTemp*config.TempDecay)))

		s.BadEpochs = 0
		s.CooldownTimer = config.Cooldown
		return fmt.Sprintf("📉 Plateau detected! Dropping LR (%.6f -> %.6f) and Router Temp (%.2f -> %.2f)",
			oldLR, *currentLR, oldTemp, *currentTemp)
	}

	return fmt.Sprintf("⚠️ No improvement in PPL (%d/%d epochs)", s.BadEpochs, config.Patience)
}

// GetLR calculates the current learning rate based on a Cosine Decay with Warmup.
// This prevents the model from diverging early (warmup) and helps fine-tune weights
// toward the end of training (cosine decay), preventing the model from getting
// stuck in local minima too early as often happens with step decay.
func GetLR(currentStep, totalSteps int, baseLR float32) float32 {

	warmupSteps := totalSteps / 50
	if warmupSteps == 0 {
		warmupSteps = 1
	}

	if currentStep < warmupSteps {

		return baseLR * float32(currentStep) / float32(warmupSteps)
	}

	if currentStep >= totalSteps {
		return 0.0
	}

	progress := float32(currentStep-warmupSteps) / float32(totalSteps-warmupSteps)

	return float32(0.5 * float64(baseLR) * (1.0 + math.Cos(math.Pi*float64(progress))))
}

type StagnancyTracker struct {
	Epsilon float32	// Threshold below which a weight is considered stagnant
}

// CalculateTimidMask identifies weights where the gradient velocity has dropped below Epsilon.
// Uses a simple moving average to avoid noise-driven triggers.
func (t *StagnancyTracker) CalculateTimidMask(accGrads []float32, currentGrads []float32) []bool {
	mask := make([]bool, len(currentGrads))

	if len(accGrads) != len(currentGrads) {
		return mask
	}

	const alpha float32 = 0.01
	const invAlpha float32 = 1.0 - alpha

	for i := range currentGrads {

		g := float32(math.Abs(float64(currentGrads[i])))
		accGrads[i] = (accGrads[i] * invAlpha) + (g * alpha)

		mask[i] = accGrads[i] < t.Epsilon
	}
	return mask
}

// PerturbStagnantWeights applies small Gaussian noise to weights identified as stagnant.
// This "shakes" the weights out of local minima where they might be stuck during a plateau.
func PerturbStagnantWeights(weights []float32, timidMask []bool, intensity float32) {
	if len(weights) != len(timidMask) {
		return
	}

	seed := time.Now().UnixNano()
	r := rand.New(rand.NewSource(seed))

	for i, isTimid := range timidMask {
		if isTimid {

			nudge := float32(r.NormFloat64()) * intensity
			weights[i] += nudge
		}
	}
}

// AnnotateScope analyzes Go source code and returns scope annotations for each
// significant code block. This is used to inject <SCOPE:...> tokens into FIM prompts.
func AnnotateScope(code string) ([]ScopeAnnotation, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	var annotations []ScopeAnnotation

	pkgName := f.Name.Name
	annotations = append(annotations, ScopeAnnotation{
		Kind:		"package",
		Name:		pkgName,
		Depth:		0,
		LineStart:	fset.Position(f.Package).Line,
	})

	ast.Inspect(f, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			start := fset.Position(node.Pos()).Line
			end := fset.Position(node.End()).Line
			receiver := ""
			if node.Recv != nil && len(node.Recv.List) > 0 {
				receiver = types.ExprString(node.Recv.List[0].Type)
			}

			kind := "func"
			if receiver != "" {
				kind = "method"
			}

			sig := buildFuncSignature(node, receiver)
			annotations = append(annotations, ScopeAnnotation{
				Kind:		kind,
				Name:		node.Name.Name,
				Receiver:	receiver,
				Signature:	sig,
				Depth:		1,
				LineStart:	start,
				LineEnd:	end,
			})

		case *ast.TypeSpec:
			start := fset.Position(node.Pos()).Line
			end := fset.Position(node.End()).Line
			kind := "type"
			if _, ok := node.Type.(*ast.StructType); ok {
				kind = "struct"
			} else if _, ok := node.Type.(*ast.InterfaceType); ok {
				kind = "interface"
			}
			annotations = append(annotations, ScopeAnnotation{
				Kind:		kind,
				Name:		node.Name.Name,
				Depth:		1,
				LineStart:	start,
				LineEnd:	end,
			})
		}
		return true
	})

	return annotations, nil
}

// buildFuncSignature constructs a human-readable function/method signature.
func buildFuncSignature(fn *ast.FuncDecl, receiver string) string {
	var parts []string
	if receiver != "" {
		parts = append(parts, "func ("+receiver+")")
	} else {
		parts = append(parts, "func")
	}
	parts = append(parts, fn.Name.Name+"(")

	// Parameters
	var params []string
	if fn.Type.Params != nil {
		for _, p := range fn.Type.Params.List {
			paramNames := make([]string, len(p.Names))
			for i, n := range p.Names {
				paramNames[i] = n.Name
			}
			paramStr := strings.Join(paramNames, ", ")
			if paramStr != "" {
				paramStr += " "
			}
			paramStr += types.ExprString(p.Type)
			params = append(params, paramStr)
		}
	}
	parts = append(parts, strings.Join(params, ", ")+")")

	if fn.Type.Results != nil {
		var results []string
		for _, r := range fn.Type.Results.List {
			results = append(results, types.ExprString(r.Type))
		}
		if len(results) > 0 {
			if len(results) == 1 {
				parts = append(parts, " "+results[0])
			} else {
				parts = append(parts, " ("+strings.Join(results, ", ")+")")
			}
		}
	}

	return strings.Join(parts, "")
}

// FormatScopeAnnotation formats a scope annotation as a special token for FIM prompts.
func FormatScopeAnnotation(a ScopeAnnotation) string {
	switch a.Kind {
	case "method":
		return fmt.Sprintf("<SCOPE: method %s>", a.Signature)
	case "func":
		return fmt.Sprintf("<SCOPE: func %s>", a.Signature)
	case "struct":
		return fmt.Sprintf("<SCOPE: struct %s>", a.Name)
	case "interface":
		return fmt.Sprintf("<SCOPE: interface %s>", a.Name)
	case "package":
		return fmt.Sprintf("<SCOPE: package %s>", a.Name)
	default:
		return fmt.Sprintf("<SCOPE: %s %s>", a.Kind, a.Name)
	}
}

// InjectScopeAnnotations adds scope annotation tokens to a FIM prompt.
// The annotations are placed before the <FIM_PRE> section.
func InjectScopeAnnotations(code string, fimPrompt string) string {
	annotations, err := AnnotateScope(code)
	if err != nil {
		return fimPrompt
	}

	var sb strings.Builder
	for _, a := range annotations {
		sb.WriteString(FormatScopeAnnotation(a))
		sb.WriteString("\n")
	}
	sb.WriteString(fimPrompt)
	return sb.String()
}

// ExtractProjectContext extracts a compressed project outline from Go source code.
// Returns exported structs, function signatures, and type definitions.
func ExtractProjectContext(code string) string {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return ""
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("package %s\n", f.Name.Name))

	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			if d.Tok == token.TYPE {
				for _, spec := range d.Specs {
					if ts, ok := spec.(*ast.TypeSpec); ok && ts.Name.IsExported() {
						sb.WriteString(fmt.Sprintf("type %s %s\n", ts.Name.Name, types.ExprString(ts.Type)))
					}
				}
			} else if d.Tok == token.VAR {
				for _, spec := range d.Specs {
					if vs, ok := spec.(*ast.ValueSpec); ok {
						for _, name := range vs.Names {
							if name.IsExported() {
								if vs.Type != nil {
									sb.WriteString(fmt.Sprintf("var %s %s\n", name.Name, types.ExprString(vs.Type)))
								}
							}
						}
					}
				}
			} else if d.Tok == token.CONST {
				for _, spec := range d.Specs {
					if vs, ok := spec.(*ast.ValueSpec); ok {
						for _, name := range vs.Names {
							if name.IsExported() {
								sb.WriteString(fmt.Sprintf("const %s\n", name.Name))
							}
						}
					}
				}
			}

		case *ast.FuncDecl:
			if d.Name.IsExported() {
				receiver := ""
				if d.Recv != nil && len(d.Recv.List) > 0 {
					receiver = types.ExprString(d.Recv.List[0].Type)
				}
				sig := buildFuncSignature(d, receiver)
				sb.WriteString(sig + "\n")
			}
		}
	}

	return sb.String()
}

// FormatProjectContext wraps the project context in the <PROJECT_CONTEXT> block.
func FormatProjectContext(context string) string {
	if context == "" {
		return ""
	}
	return fmt.Sprintf("<PROJECT_CONTEXT>\n%s</PROJECT_CONTEXT>\n", context)
}

// FormatContextTypes wraps type/function signatures in the <CONTEXT_TYPES> block.
func FormatContextTypes(signatures []string) string {
	if len(signatures) == 0 {
		return ""
	}
	return fmt.Sprintf("<CONTEXT_TYPES>\n%s\n</CONTEXT_TYPES>\n", strings.Join(signatures, "\n"))
}

// ExtractCallGraphSignatures extracts function signatures for all functions
// called within a given code block. This is used for call-graph ingestion.
func ExtractCallGraphSignatures(code string, targetFunc string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	// Find the target function
	var targetBody *ast.BlockStmt
	ast.Inspect(f, func(n ast.Node) bool {
		if fn, ok := n.(*ast.FuncDecl); ok && fn.Name.Name == targetFunc {
			targetBody = fn.Body
			return false
		}
		return true
	})

	if targetBody == nil {
		return nil, fmt.Errorf("function %q not found", targetFunc)
	}

	calledFuncs := make(map[string]bool)
	ast.Inspect(targetBody, func(n ast.Node) bool {
		if call, ok := n.(*ast.CallExpr); ok {
			if ident, ok := call.Fun.(*ast.Ident); ok {
				calledFuncs[ident.Name] = true
			} else if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				calledFuncs[sel.Sel.Name] = true
			}
		}
		return true
	})

	// Find signatures for called functions
	var signatures []string
	ast.Inspect(f, func(n ast.Node) bool {
		if fn, ok := n.(*ast.FuncDecl); ok {
			if calledFuncs[fn.Name.Name] {
				receiver := ""
				if fn.Recv != nil && len(fn.Recv.List) > 0 {
					receiver = types.ExprString(fn.Recv.List[0].Type)
				}
				sig := buildFuncSignature(fn, receiver)
				signatures = append(signatures, sig)
			}
		}
		return true
	})

	return signatures, nil
}

type MaskedNode struct {
	Kind		ASTNodeKind	`json:"kind"`
	Original	string		`json:"original"`	// The original code that was masked
	StartPos	int		`json:"start_pos"`
	EndPos		int		`json:"end_pos"`
}

type ASTMaskingConfig struct {
	// MaskProbability is the probability of masking a given eligible node (0.0-1.0)
	MaskProbability	float64
	// MaxMaskedNodes is the maximum number of nodes to mask in a single example
	MaxMaskedNodes	int
	// MinNodeSize is the minimum character length of a node to be eligible for masking
	MinNodeSize	int
	// MaxNodeSize is the maximum character length of a node to be eligible for masking
	MaxNodeSize	int
	// NodeWeights maps node kinds to their relative masking probability weights
	NodeWeights	map[ASTNodeKind]float64
	// PreserveTopLevel if true, prevents masking top-level declarations
	PreserveTopLevel	bool
}

type ASTMasker struct {
	config	ASTMaskingConfig
	rng	*rand.Rand
}

// NewASTMasker creates a new AST masker with the given configuration.
func NewASTMasker(config ASTMaskingConfig) *ASTMasker {
	return &ASTMasker{
		config:	config,
		rng:	rand.New(rand.NewSource(42)),
	}
}

// MaskASTNodes masks eligible AST nodes in the given Go source code.
// It returns the masked code and a list of what was masked.
func (m *ASTMasker) MaskASTNodes(code string) (*MaskResult, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	// Collect all eligible nodes
	var candidates []struct {
		kind		ASTNodeKind
		node		ast.Node
		original	string
		start		int
		end		int
	}

	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			return true
		}

		start := fset.Position(n.Pos()).Offset
		end := fset.Position(n.End()).Offset
		size := end - start

		if size < m.config.MinNodeSize || size > m.config.MaxNodeSize {
			return true
		}

		if m.config.PreserveTopLevel {
			switch n.(type) {
			case *ast.File, *ast.GenDecl, *ast.FuncDecl:
				return true
			}
		}

		var kind ASTNodeKind
		switch n.(type) {
		case *ast.IfStmt:
			kind = MaskIfBlock
		case *ast.ForStmt, *ast.RangeStmt:
			kind = MaskForBlock
		case *ast.SwitchStmt:
			kind = MaskSwitchBlock
		case *ast.TypeSwitchStmt:
			kind = MaskTypeSwitch
		case *ast.SelectStmt:
			kind = MaskSelectBlock
		case *ast.DeferStmt:
			kind = MaskDeferStmt
		case *ast.GoStmt:
			kind = MaskGoStmt
		case *ast.ReturnStmt:
			kind = MaskReturnStmt
		case *ast.AssignStmt:
			kind = MaskAssignStmt
		case *ast.ExprStmt:
			kind = MaskExprStmt
		case *ast.CallExpr:
			kind = MaskCallExpr
		case *ast.BinaryExpr:
			kind = MaskBinaryExpr
		case *ast.CompositeLit:
			kind = MaskCompositeLit
		case *ast.FuncLit:
			kind = MaskFuncLit
		case *ast.SendStmt:
			kind = MaskSendStmt
		case *ast.IncDecStmt:
			kind = MaskIncDecStmt
		case *ast.BranchStmt:
			kind = MaskBranchStmt
		case *ast.CommClause:
			kind = MaskCommClause
		default:
			return true
		}

		original := code[start:end]

		weight, hasWeight := m.config.NodeWeights[kind]
		if !hasWeight {
			weight = 0.5
		}

		candidates = append(candidates, struct {
			kind		ASTNodeKind
			node		ast.Node
			original	string
			start		int
			end		int
		}{
			kind:		kind,
			node:		n,
			original:	original,
			start:		start,
			end:		end,
		})

		if m.rng.Float64() < weight*m.config.MaskProbability {
			return false
		}
		return true
	})

	m.maskNodes(candidates, &code)

	result := &MaskResult{
		OriginalCode:	code,
		MaskedCode:	code,
	}

	return result, nil
}

// maskNodes selects and masks nodes from the candidates list.
func (m *ASTMasker) maskNodes(candidates []struct {
	kind		ASTNodeKind
	node		ast.Node
	original	string
	start		int
	end		int
}, code *string) {

	for i := len(candidates) - 1; i >= 0; i-- {
		c := candidates[i]

		weight := m.config.NodeWeights[c.kind]
		if weight == 0 {
			weight = 0.5
		}

		if m.rng.Float64() < weight*m.config.MaskProbability {

			maskToken := fmt.Sprintf("<MASK:%s>", string(c.kind))
			*code = (*code)[:c.start] + maskToken + (*code)[c.end:]
		}
	}
}

// CreateFIMMask creates a FIM example by masking an AST node and splitting
// the code into prefix/middle/suffix around the masked region.
func (m *ASTMasker) CreateFIMMask(code string) (*FIMExample, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	// Collect eligible nodes for masking
	type nodeInfo struct {
		kind		ASTNodeKind
		node		ast.Node
		original	string
		start		int
		end		int
	}

	var candidates []nodeInfo

	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			return true
		}

		start := fset.Position(n.Pos()).Offset
		end := fset.Position(n.End()).Offset
		size := end - start

		if size < m.config.MinNodeSize || size > m.config.MaxNodeSize {
			return true
		}

		if m.config.PreserveTopLevel {
			switch n.(type) {
			case *ast.File, *ast.GenDecl, *ast.FuncDecl:
				return true
			}
		}

		var kind ASTNodeKind
		switch n.(type) {
		case *ast.IfStmt:
			kind = MaskIfBlock
		case *ast.ForStmt, *ast.RangeStmt:
			kind = MaskForBlock
		case *ast.SwitchStmt:
			kind = MaskSwitchBlock
		case *ast.TypeSwitchStmt:
			kind = MaskTypeSwitch
		case *ast.SelectStmt:
			kind = MaskSelectBlock
		case *ast.DeferStmt:
			kind = MaskDeferStmt
		case *ast.GoStmt:
			kind = MaskGoStmt
		case *ast.ReturnStmt:
			kind = MaskReturnStmt
		case *ast.AssignStmt:
			kind = MaskAssignStmt
		case *ast.ExprStmt:
			kind = MaskExprStmt
		case *ast.CallExpr:
			kind = MaskCallExpr
		case *ast.BinaryExpr:
			kind = MaskBinaryExpr
		case *ast.CompositeLit:
			kind = MaskCompositeLit
		case *ast.FuncLit:
			kind = MaskFuncLit
		case *ast.SendStmt:
			kind = MaskSendStmt
		case *ast.IncDecStmt:
			kind = MaskIncDecStmt
		case *ast.BranchStmt:
			kind = MaskBranchStmt
		case *ast.CommClause:
			kind = MaskCommClause
		default:
			return true
		}

		original := code[start:end]
		candidates = append(candidates, nodeInfo{
			kind:		kind,
			node:		n,
			original:	original,
			start:		start,
			end:		end,
		})

		return false
	})

	if len(candidates) == 0 {
		return nil, fmt.Errorf("no eligible AST nodes found for masking")
	}

	selected := candidates[m.rng.Intn(len(candidates))]

	prefix := code[:selected.start]
	middle := selected.original
	suffix := code[selected.end:]

	return &FIMExample{
		Prefix:	prefix,
		Middle:	middle,
		Suffix:	suffix,
	}, nil
}

// CreateMaskFuncParams creates a FIM example that masks a function's parameter list.
func CreateMaskFuncParams(code string) (*FIMExample, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	// Find a function with parameters
	var targetFunc *ast.FuncDecl
	ast.Inspect(f, func(n ast.Node) bool {
		if fn, ok := n.(*ast.FuncDecl); ok && fn.Type.Params != nil && len(fn.Type.Params.List) > 0 {
			targetFunc = fn
			return false
		}
		return true
	})

	if targetFunc == nil {
		return nil, fmt.Errorf("no function with parameters found")
	}

	paramsStart := fset.Position(targetFunc.Type.Params.Opening).Offset
	paramsEnd := fset.Position(targetFunc.Type.Params.Closing).Offset + 1

	prefix := code[:paramsStart]
	middle := code[paramsStart:paramsEnd]
	suffix := code[paramsEnd:]

	return &FIMExample{
		Prefix:	prefix,
		Middle:	middle,
		Suffix:	suffix,
	}, nil
}

