// resolveListenAddr normalises a user-supplied address into a valid
// "host:port" string suitable for net.Listen / http.ListenAndServe.
//
//	":8080"          → ":8080"          (already a listen address)
//	"0.0.0.0:8080"   → "0.0.0.0:8080"  (already a host:port)
//	"8080"           → ":8080"          (bare port – prepend colon)
func resolveListenAddr(addr string) string {
	if strings.Contains(addr, ":") {
		return addr
	}
	return ":" + addr
}

// initMasterSocket normalizes the address and returns a bound TCP listener.
func initMasterSocket(addr string) net.Listener {
	listenAddr := resolveListenAddr(addr)

	displayPort := listenAddr
	if strings.HasPrefix(displayPort, ":") {
		displayPort = displayPort[1:]
	} else if parts := strings.Split(displayPort, ":"); len(parts) == 2 {
		displayPort = parts[1]
	}

	log.Printf("\n===================================================================")
	log.Printf("🌐 [Distributed] Master Node is Active & Listening!")
	log.Printf("📌 Bound Address : %s", listenAddr)
	log.Printf("🛠️  To connect a worker, run the same training command on the worker node")
	log.Printf("   with the following flags appended:")
	log.Printf("   -dist-mode=worker -dist-addr=<MASTER_IP>:%s", displayPort)
	log.Printf("   (Replace <MASTER_IP> with this machine's actual network IP if on another device)")
	log.Printf("===================================================================\n")

	listener, err := net.Listen("tcp", listenAddr)
	if err != nil {
		log.Fatalf("failed to bind master server to %s: %v", listenAddr, err)
	}

	return listener
}

// BlockAndRegisterWorkers blocks execution until expectedCount workers have successfully connected.
func BlockAndRegisterWorkers(listener net.Listener, expectedCount int, model *moe.IntentMoE) {
	var wg sync.WaitGroup
	connected := 0

	for connected < expectedCount {
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("⚠️ [Distributed] Connection drop during registration: %v", err)
			continue
		}

		connected++
		log.Printf("🌐 [Distributed] Worker %d/%d successfully joined cluster from %s",
			connected, expectedCount, conn.RemoteAddr().String())

		wg.Add(1)
		go handleWorkerSync(conn, &wg, model)
	}

}

func handleWorkerSync(conn net.Conn, wg *sync.WaitGroup, model *moe.IntentMoE) {
	defer wg.Done()
	defer conn.Close()

	for {
		// Read number of weights
		var numWeights int32
		if err := binary.Read(conn, binary.LittleEndian, &numWeights); err != nil {
			if err != io.EOF {
				log.Printf("⚠️  [Distributed] Connection error with worker %s: %v", conn.RemoteAddr(), err)
			}
			return
		}

		receivedWeights := make([]float32, numWeights)
		if err := binary.Read(conn, binary.LittleEndian, &receivedWeights); err != nil {
			log.Printf("⚠️  [Distributed] Failed to read weights from worker %s: %v", conn.RemoteAddr(), err)
			return
		}

		syncMutex.Lock()
		if moe.GlobalTelemetry != nil {
			moe.GlobalTelemetry.RecordPoolHit()
		}
		params := model.Parameters()
		idx := 0
		for _, p := range params {
			for i := range p.Data {
				if idx < len(receivedWeights) {

					p.Data[i] = (p.Data[i] + receivedWeights[idx]) / 2.0
					idx++
				}
			}
		}
		syncMutex.Unlock()

		log.Printf("🌐 [Distributed] Master successfully received and averaged %d weights from worker at %s.", len(receivedWeights), conn.RemoteAddr())

		ack := []byte("OK")
		_ = moe.EmitRuntimeTelemetry("logs/telemetry.json", nil)
		conn.Write(ack)
	}
}

// SyncWithMaster sends the current model weights to the master node.
func SyncWithMaster(model *moe.IntentMoE, masterAddr string) {
	workerConnMutex.Lock()
	if workerConn == nil {
		conn, err := net.Dial("tcp", masterAddr)
		if err != nil {
			log.Printf("⚠️  [Distributed] Worker failed to connect to master %s: %v", masterAddr, err)
			workerConnMutex.Unlock()
			return
		}
		workerConn = conn
		log.Printf("🌐 [Distributed] Worker connected to master at %s", masterAddr)
	}
	conn := workerConn
	workerConnMutex.Unlock()

	syncMutex.Lock()
	params := model.Parameters()
	var totalWeights int32
	for _, p := range params {
		totalWeights += int32(len(p.Data))
	}

	flatWeights := make([]float32, 0, totalWeights)
	for _, p := range params {
		flatWeights = append(flatWeights, p.Data...)
	}
	syncMutex.Unlock()

	if err := binary.Write(conn, binary.LittleEndian, totalWeights); err != nil {
		log.Printf("⚠️  [Distributed] Worker failed to send total weights: %v", err)
		workerConn.Close()
		workerConnMutex.Lock()
		workerConn = nil
		workerConnMutex.Unlock()
		return
	}

	if err := binary.Write(conn, binary.LittleEndian, flatWeights); err != nil {
		log.Printf("⚠️  [Distributed] Worker failed to send weights: %v", err)
		workerConn.Close()
		workerConnMutex.Lock()
		workerConn = nil
		workerConnMutex.Unlock()
		return
	}

	ack := make([]byte, 2)
	_ = moe.EmitRuntimeTelemetry("logs/telemetry.json", nil)
	if _, err := io.ReadFull(conn, ack); err != nil {
		log.Printf("⚠️  [Distributed] Worker failed to receive ACK from master: %v", err)
		workerConn.Close()
		workerConnMutex.Lock()
		workerConn = nil
		workerConnMutex.Unlock()
		return
	}

	log.Printf("🌐 [Distributed] Worker successfully synced %d weights with master.", totalWeights)
}

func ValidateModelHealth(model *moe.IntentMoE) bool {
	fmt.Println(" Performing Pre-Flight Health Check...")
	isHealthy := true

	for i, param := range model.Parameters() {
		var maxVal float32 = -1e18
		var minVal float32 = 1e18
		nanCount := 0

		for _, v := range param.Data {
			if math.IsNaN(float64(v)) || math.IsInf(float64(v), 0) {
				nanCount++
			}
			if v > maxVal {
				maxVal = v
			}
			if v < minVal {
				minVal = v
			}
		}

		if nanCount > 0 {
			fmt.Printf(" Param %d: Found %d NaN/Inf values!\n", i, nanCount)
			isHealthy = false
		}

		if maxVal > 100.0 || minVal < -100.0 {
			fmt.Printf("  Param %d: High saturation detected (Range: %.2f to %.2f)\n", i, minVal, maxVal)
		}
	}

	if isHealthy {
		fmt.Println(" Model weights are within safe numerical bounds.")
	}
	return isHealthy
}

func VerifyModelIntegrity(m *moe.IntentMoE) {
	if m.Decoder != nil && m.Decoder.OutputMoE != nil {
		w := m.Decoder.OutputMoE.GatingNetwork.Linear.Weights.Data
		var sum float32 = 0.0
		for _, v := range w {
			sum += float32(math.Abs(float64(v)))
		}
		if sum == 0 {
			fmt.Println(" CRITICAL: Decoder Router is empty! Resetting weights...")

			for i := range w {
				w[i] = float32((rand.Float64() - 0.5) * 0.1)
			}
		}
	}
}

func ValidateChat(model *moe.IntentMoE, valPairs []moe.TrainPair, useGPU bool) float32 {

	for _, layer := range moe.ActiveLayers {
		layer.SetMode(false)
	}
	defer func() {
		for _, layer := range moe.ActiveLayers {
			layer.SetMode(true)
		}
	}()

	var totalLoss float64
	var tokenCount int

	unkID := model.SentenceVocab.GetTokenID("UNK")
	if unkID == -1 {
		unkID = 0
	}

	for _, pair := range valPairs {

		qTokens := cleanTokenize(pair.Q)
		qIDs := make([]float32, max(1, len(qTokens)))
		for i, t := range qTokens {
			id := lookupVocab(t, model.SentenceVocab)
			qIDs[i] = float32(id)
		}
		if len(qTokens) == 0 {
			qIDs[0] = 0
		}

		aTokens := cleanTokenize(pair.A)
		aIDs := make([]int, len(aTokens)+2)
		aIDs[0] = model.SentenceVocab.BosID
		for i, t := range aTokens {
			id := model.SentenceVocab.GetTokenID(t)
			if id == -1 || (id == 0 && t != "<pad>") {
				aIDs[i+1] = unkID
			} else {
				aIDs[i+1] = id
			}
		}
		aIDs[len(aIDs)-1] = model.SentenceVocab.EosID

		inputT := tensor.NewTensor([]int{1, len(qIDs)}, qIDs, false)

		targets := aIDs[1:]

		targetTIDs := make([]float32, len(aIDs))
		for i, id := range aIDs {
			targetTIDs[i] = float32(id)
		}
		targetT := tensor.NewTensor([]int{1, len(targetTIDs)}, targetTIDs, false)

		if useGPU {
			inputT.ToGPU()
			targetT.ToGPU()
		}

		logits, _, err := model.Forward(0.0, inputT, targetT, nil)
		if err != nil || len(logits) == 0 {
			continue
		}

		valWeights := make([]float32, model.SentenceVocab.Size())
		for i := range valWeights {
			valWeights[i] = 1.0
		}
		valWeights[unkID] = 0.01
		valWeights[model.SentenceVocab.PaddingTokenID] = 0.0

		loss, _ := WeightedCrossEntropy(logits[0], targets, valWeights, 0.0, 0.0)
		totalLoss += float64(loss)
		tokenCount++

		model.Detach()
	}

	if tokenCount == 0 {
		return 0.0
	}

	avgLoss := totalLoss / float64(tokenCount)
	perplexity := float32(math.Exp(avgLoss))
	return perplexity
}

func calculateSequenceReward(predictedIDs []int, vocab *mainvocab.Vocabulary) float32 {
	if vocab == nil || len(predictedIDs) == 0 {
		return 1.0
	}
	var reward float32 = 1.0

	firstMeaningful := -1
	meaningfulCount := 0
	for _, id := range predictedIDs {
		if id != vocab.BosID && id != vocab.PaddingTokenID && id != vocab.EosID {
			if firstMeaningful == -1 {
				firstMeaningful = id
			}
			meaningfulCount++
		}
	}

	if meaningfulCount <= 1 {
		reward -= 1.5
	}

	if firstMeaningful >= 0 {
		w := strings.ToLower(vocab.GetWord(firstMeaningful))
		switch w {
		case "hello", "hi", "hey", "morning", "evening", "greetings", "howdy":
			reward += 0.3
		}
	}

	lastMeaningful := -1
	for i := len(predictedIDs) - 1; i >= 0; i-- {
		id := predictedIDs[i]
		if id != vocab.EosID && id != vocab.PaddingTokenID {
			lastMeaningful = id
			break
		}
	}

	if lastMeaningful >= 0 {
		w := vocab.GetWord(lastMeaningful)
		if w == "." || w == "!" || w == "?" {
			reward += 0.5
		}
	}

	for i := 0; i < len(predictedIDs)-1; i++ {
		if predictedIDs[i] == predictedIDs[i+1] &&
			predictedIDs[i] != vocab.PaddingTokenID {
			reward -= 0.8
		}
	}

	if reward < 0.01 {
		reward = 0.01
	}
	if reward > 2.0 {
		reward = 2.0
	}
	return reward
}

func scoreSentenceHeuristic(text string) float32 {
	if text == "[Still Silent]" || text == "" {
		return 0
	}
	words := strings.Fields(text)
	if len(words) == 0 {
		return 0
	}

	var score float32 = 10.0

	if len(words) == 1 {
		score -= 8.0
	} else if len(words) < 3 {
		score -= 5.0
	} else if len(words) < 5 {
		score -= 3.0
	}

	seen := make(map[string]int)
	for _, w := range words {
		seen[w]++
	}
	var repeatCost float32 = 0.0
	for _, count := range seen {
		if count > 1 {
			repeatCost += float32(math.Pow(float64(count), 1.5))
		}
	}
	score -= repeatCost * 0.5

	score += float32(len(seen)) * 0.2

	if strings.ContainsAny(text, ".!?") {
		score += 2.0
	}

	if score < 0 {
		score = 0
	}
	return score
}

func scoreGrammarHeuristic(text string) float32 {
	if text == "[Still Silent]" || text == "" {
		return 0
	}
	words := strings.Fields(text)
	if len(words) == 0 {
		return 0
	}
	var score float32 = 0.0

	if len(words) >= 2 {
		score += 1.0
	}

	var lastPos string
	for _, w := range words {
		pos := moe.MapWordToGrammarType(w)
		if pos != "OTHER" {
			score += 1.0
		}

		if pos == lastPos && pos != "OTHER" && pos != "PREP" && pos != "ADJ" {
			score -= 1.5
		}

		if lastPos == "PRON" && (pos == "VERB" || pos == "AUX") {
			score += 2.0
		}

		if lastPos == "AUX" && pos == "VERB" {
			score += 2.0
		}

		if lastPos == "VERB" && (pos == "PREP" || pos == "NOUN" || pos == "ADJ" || pos == "PRON") {
			score += 1.5
		}

		if lastPos == "GREET" && pos != "OTHER" {
			score += 1.0
		}

		if lastPos == "INTERROGATIVE" && (pos == "PRON" || pos == "AUX" || pos == "VERB") {
			score += 2.0
		}

		if lastPos == "ADJ" && pos == "NOUN" {
			score += 1.0
		}

		if lastPos == "PREP" && (pos == "NOUN" || pos == "PRON" || pos == "ADJ") {
			score += 0.5
		}
		lastPos = pos
	}
	if score < 0 {
		return 0
	}
	if score > 30.0 {
		return 30.0
	}
	return score
}

// StrictGenerateLowTemp is a near-argmax variant of StrictGenerate for evaluation probes.
// Uses temperature=0.1 and topK=5 to produce greedy-almost deterministic output,
// testing the model's actual argmax knowledge rather than noisy random token samples.
func StrictGenerateLowTemp(model *moe.IntentMoE, input string, maxLen int, repetitionPenalty float32, verbose bool, epoch int) (string, string, []*tensor.Tensor) {
	model.SetParamsRequiresGrad(false)

	oldTemps := make(map[*moe.MoELayer]float32)
	for _, layer := range moe.ActiveLayers {
		layer.SetMode(true)
		oldTemps[layer] = layer.RouterTemperature
		layer.RouterTemperature = 0.7
	}
	if model.Decoder.OutputMoE != nil {
		model.Decoder.OutputMoE.SetMode(true)
		oldTemps[model.Decoder.OutputMoE] = model.Decoder.OutputMoE.RouterTemperature
		model.Decoder.OutputMoE.RouterTemperature = 0.7
	}

	defer func() {
		model.SetParamsRequiresGrad(true)
		for layer, temp := range oldTemps {
			layer.SetMode(true)
			layer.RouterTemperature = temp
		}
		if model.Decoder.OutputMoE != nil {
			model.Decoder.OutputMoE.SetMode(true)
			model.Decoder.OutputMoE.RouterTemperature = oldTemps[model.Decoder.OutputMoE]
		}
	}()

	formattedInput := input
	tokens := cleanTokenize(formattedInput)
	if len(tokens) == 0 {
		log.Printf(" Skip empty prompt: %s", input)
		return "", "", nil
	}
	inputIDs := make([]float32, len(tokens))
	for i, t := range tokens {
		inputIDs[i] = float32(lookupVocab(t, model.SentenceVocab))
	}
	inputTensor := tensor.NewTensor([]int{1, len(inputIDs)}, inputIDs, false)

	ctx, err := model.EncoderForward(inputTensor, nil)
	if err != nil {
		log.Printf("StrictGenerateLowTemp Error (EncoderForward): %v", err)
		return "", "", nil
	}

	if ctx.Shape[1] == 0 {
		log.Printf("StrictGenerateLowTemp Error: encoder produced empty sequence")
		return "", "", nil
	}

	batchSize := 1
	hiddenSize := model.Decoder.LSTM.HiddenSize
	hiddenState, err := ctx.Mean(1)
	if err != nil {
		log.Printf("StrictGenerateLowTemp Error (Initial Hidden Mean): %v", err)
		return "", "", nil
	}
	hiddenState, _ = hiddenState.Reshape([]int{batchSize, ctx.Shape[2]})
	if hiddenState.Shape[1] != hiddenSize {
		if hiddenState.Shape[1] > hiddenSize {
			hiddenState, _ = hiddenState.Slice(1, 0, hiddenSize)
		} else {
			padding := tensor.NewTensor([]int{batchSize, hiddenSize - hiddenState.Shape[1]}, make([]float32, batchSize*(hiddenSize-hiddenState.Shape[1])), false)
			hiddenState, _ = tensor.Concat([]*tensor.Tensor{hiddenState, padding}, 1)
		}
	}
	cellState := tensor.NewTensor([]int{batchSize, hiddenSize}, make([]float32, batchSize*hiddenSize), false)

	resIDs := []int{model.SentenceVocab.BosID}
	currentTokenID := model.SentenceVocab.BosID
	counts := make(map[int]int)
	var pathSteps []string
	var allAtts []*tensor.Tensor
	lastPunctStep := -10

	const genTemp = float32(0.0)	// greedy/argmax for deterministic probe evaluation

	for i := 0; i < maxLen; i++ {
		inputT := tensor.NewTensor([]int{1, 1}, []float32{float32(currentTokenID)}, false)
		logits, nextHidden, nextCell, expertIDs, attWeights, err := model.Decoder.DecodeStepWithExpert(inputT, hiddenState, cellState, ctx, i)
		if err != nil {
			log.Printf("StrictGenerateLowTemp Error (DecodeStep): %v", err)
			break
		}
		hiddenState = nextHidden
		cellState = nextCell
		if attWeights != nil {
			allAtts = append(allAtts, attWeights)
		}

		var stepExperts []string
		for _, eid := range expertIDs {
			label := fmt.Sprintf("E%d", eid)
			stepExperts = append(stepExperts, label)
		}
		expertStr := strings.Join(stepExperts, "+")
		pathSteps = append(pathSteps, expertStr)

		if i == 0 {
			logits.Data[model.SentenceVocab.EosID] = -1e9
		}
		specialTokens := []string{"__intent__", "__ques__", "__ans__", "social", ":"}
		for _, st := range specialTokens {
			id := model.SentenceVocab.GetTokenID(st)
			if id != -1 && id < len(logits.Data) {
				logits.Data[id] = -1e9
			}
		}

		applyGrammarMask(logits, resIDs, model.SentenceVocab)

		consecutivePunct := 0
		for j := len(resIDs) - 1; j >= 0; j-- {
			w := model.SentenceVocab.GetWord(resIDs[j])
			if w == "." || w == "," || w == "!" || w == "?" || w == ";" || w == ":" {
				consecutivePunct++
			} else {
				break
			}
		}
		punctPenalty := float32(5.0)
		if consecutivePunct > 1 {
			punctPenalty = 10.0
		}
		if i-lastPunctStep < 4 || consecutivePunct > 1 {
			punctuation := []string{".", ",", "!", "?", ";", ":"}
			for _, p := range punctuation {
				id := model.SentenceVocab.GetTokenID(p)
				if id != -1 && id < len(logits.Data) {
					logits.Data[id] -= punctPenalty
				}
			}
		}

		if len(resIDs) >= 3 {
			fourgrams := make(map[[3]int]int)
			for j := 0; j+2 < len(resIDs); j++ {
				key := [3]int{resIDs[j], resIDs[j+1], resIDs[j+2]}
				fourgrams[key]++
			}
			tailKey := [3]int{resIDs[len(resIDs)-3], resIDs[len(resIDs)-2], resIDs[len(resIDs)-1]}
			if fourgrams[tailKey] >= 2 {
				for candidateID := range logits.Data {
					logits.Data[candidateID] -= 15.0
				}
			}
		}

		moe.ApplyRepetitionPenalty(logits, resIDs, repetitionPenalty)
		logits.Data[model.SentenceVocab.PaddingTokenID] = -1e9
		if unkID := model.SentenceVocab.GetTokenID("UNK"); unkID != -1 {
			logits.Data[unkID] = -1e9
		}

		if genTemp > 0 {
			ApplyTemperature(logits.Data, genTemp)
		}
		bestID := 0
		maxLogit := float32(-1e9)
		for tokenID, logitValue := range logits.Data {
			if logitValue > maxLogit {
				maxLogit = logitValue
				bestID = tokenID
			}
		}

		probs := tensor.Softmax(logits)
		if bestID == model.SentenceVocab.EosID {
			probs.Release()
			logits.Release()
			inputT.Release()
			break
		}

		resIDs = append(resIDs, bestID)
		counts[bestID]++
		currentTokenID = bestID

		word := model.SentenceVocab.GetWord(bestID)
		if word == "." || word == "," || word == "!" || word == "?" {
			lastPunctStep = i
		}

		probs.Release()
		logits.Release()
		inputT.Release()
	}

	result := ""
	for i, id := range resIDs {
		if i == 0 {
			continue
		}
		result += model.SentenceVocab.GetWord(id) + " "
	}

	inputTensor.Release()
	hiddenState.Release()
	cellState.Release()
	ctx.Release()
	model.ClearState()

	return strings.TrimSpace(result), strings.Join(pathSteps, " -> "), allAtts
}

func StrictGenerate(model *moe.IntentMoE, input string, maxLen int, repetitionPenalty float32, verbose bool, epoch int) (string, string, []*tensor.Tensor) {

