// findMoELayers returns all MoE layers in the model (encoder layers + decoder output layer).
func findMoELayers(m *moe.IntentMoE) []*moe.MoELayer {
	if m == nil {
		return nil
	}
	layers := m.Encoder.GetMoELayers()
	if m.Decoder != nil && m.Decoder.OutputMoE != nil {
		layers = append(layers, m.Decoder.OutputMoE)
	}
	return layers
}

// toFloat32 hashes string tokens to float32 IDs for tensor construction.
func toFloat32(tokens []string) []float32 {
	out := make([]float32, len(tokens))
	for i, t := range tokens {
		var h uint32
		for _, ch := range t {
			h = h*31 + uint32(ch)
		}
		out[i] = float32(h % 10000)
	}
	return out
}

// extractExpertRoutingInfo collects expert IDs and ACTUAL vocabulary token IDs from all MoE layers.
func extractExpertRoutingInfo(intentModel *moe.IntentMoE, inputTensor *tensor.Tensor, targetTensor *tensor.Tensor) ([]int, []int) {
	expertIDs := make([]int, 0)
	tokenIDs := make([]int, 0)

	for _, layer := range intentModel.Encoder.GetMoELayers() {
		if layer != nil && layer.ExpertTokenIndices != nil {
			for expertIdx, seqIndices := range layer.ExpertTokenIndices {
				for _, seqIdx := range seqIndices {
					if inputTensor != nil && seqIdx < len(inputTensor.Data) {
						vocabID := int(inputTensor.Data[seqIdx])
						expertIDs = append(expertIDs, expertIdx)
						tokenIDs = append(tokenIDs, vocabID)
					}
				}
			}
		}
	}

	if intentModel.Decoder.OutputMoE != nil {
		layer := intentModel.Decoder.OutputMoE
		if layer.ExpertTokenIndices != nil {
			for expertIdx, seqIndices := range layer.ExpertTokenIndices {
				for _, seqIdx := range seqIndices {
					if targetTensor != nil && seqIdx < len(targetTensor.Data) {
						vocabID := int(targetTensor.Data[seqIdx])
						expertIDs = append(expertIDs, expertIdx)
						tokenIDs = append(tokenIDs, vocabID)
					}
				}
			}
		}
	}

	return expertIDs, tokenIDs
}

func InitializeXavier(p *tensor.Tensor) {
	if p == nil || len(p.Shape) == 0 {
		return
	}
	fanIn := p.Shape[0]
	fanOut := 0
	if len(p.Shape) > 1 {
		fanOut = p.Shape[1]
	} else {
		fanOut = fanIn
	}
	limit := float32(math.Sqrt(6.0 / float64(fanIn+fanOut)))
	for i := range p.Data {
		p.Data[i] = (float32(rand.Float64()) * 2 * limit) - limit
	}
}

func InitializeHeNormal(p *tensor.Tensor) {
	if p == nil || len(p.Shape) < 2 {

		return
	}

	fanIn := float64(p.Shape[0])
	if fanIn == 0 {
		fanIn = 1
	}
	scale := float32(math.Sqrt(2.0 / fanIn))
	for i := range p.Data {
		p.Data[i] = float32(rand.NormFloat64()) * scale
	}
}

func InitializeRouterGating(weights, biases *tensor.Tensor) {
	if weights == nil {
		return
	}
	scale := float32(0.5)
	for i := range weights.Data {
		weights.Data[i] = (float32(rand.Float64())*2.0 - 1.0) * scale
	}
	if biases != nil {
		for i := range biases.Data {
			if i == 3 && len(biases.Data) > 3 {
				biases.Data[i] = -0.2
			} else {
				biases.Data[i] = 0.1
			}
		}
	}
}

func InitializeOrthogonal(param *tensor.Tensor, gain float32) {
	if param == nil || len(param.Shape) < 2 {
		InitializeXavier(param)
		return
	}

	for i := range param.Data {
		param.Data[i] = float32(rand.NormFloat64())
	}

	rows := param.Shape[0]
	cols := len(param.Data) / rows
	if cols == 0 {
		return
	}

	for i := 0; i < rows; i++ {
		rowI := param.Data[i*cols : (i+1)*cols]
		for j := 0; j < i; j++ {
			rowJ := param.Data[j*cols : (j+1)*cols]

			dot := 0.0
			for k := range rowI {
				dot += float64(rowI[k] * rowJ[k])
			}

			for k := range rowI {
				rowI[k] -= float32(dot) * rowJ[k]
			}
		}

		norm := 0.0
		for _, v := range rowI {
			norm += float64(v * v)
		}
		norm = math.Sqrt(norm + 1e-8)
		for k := range rowI {
			rowI[k] = (rowI[k] / float32(norm)) * gain
		}
	}
}

func InitializeLSTMBias(param *tensor.Tensor, hiddenSize int) {
	if param == nil {
		return
	}

	for i := range param.Data {
		param.Data[i] = 0
	}

	forgetStart := hiddenSize
	forgetEnd := 2 * hiddenSize
	if forgetEnd > len(param.Data) {
		forgetEnd = len(param.Data)
	}
	for i := forgetStart; i < forgetEnd; i++ {
		param.Data[i] = 1.0
	}

	if len(param.Data) == 8*hiddenSize {
		backwardForgetStart := 5 * hiddenSize
		backwardForgetEnd := 6 * hiddenSize
		for i := backwardForgetStart; i < backwardForgetEnd; i++ {
			param.Data[i] = 1.0
		}
	}
}

func isLSTMWeight(param *tensor.Tensor) bool {
	if param == nil || len(param.Shape) != 2 {
		return false
	}

	return param.Shape[0] > 1 && param.Shape[1] > 1
}

func isLSTMBias(param *tensor.Tensor, hiddenSize int) bool {
	if param == nil {
		return false
	}
	size := len(param.Data)

	return size == hiddenSize || size == 4*hiddenSize || size == 8*hiddenSize
}

func NewChatDataIterator(pairs []moe.TrainPair, vocab *mainvocab.Vocabulary, unkID int) *ChatDataIterator {

	rand.Shuffle(len(pairs), func(i, j int) { pairs[i], pairs[j] = pairs[j], pairs[i] })
	return &ChatDataIterator{
		pairs:	pairs,
		vocab:	vocab,
		unkID:	unkID,
		idx:	0,
		MaxLen:	48,
	}
}

func (it *ChatDataIterator) HasNext() bool {
	return it.idx < len(it.pairs)
}

// buildChatMLSequence builds a ChatML-formatted token sequence with loss mask
// from a TrainPair. Format:
//
//	<|im_start|>user\nQUERY<|im_end|>\n<|im_start|>assistant\nANSWER<|im_end|>
//
// lossMask[i] = 0.0 for user tokens, 1.0 for assistant tokens.
func (it *ChatDataIterator) buildChatMLSequence(pair moe.TrainPair) (inputIDs, targetIDs, lossMask []float32) {

	userMsg := fmt.Sprintf("<|im_start|>user\n%s<|im_end|>\n<|im_start|>assistant\n", pair.Q)
	assistantMsg := fmt.Sprintf("%s<|im_end|>", pair.A)

	userTokens := cleanTokenize(userMsg)
	userIDs := make([]float32, len(userTokens))
	for i, t := range userTokens {
		userIDs[i] = float32(lookupVocab(t, it.vocab))
	}

	assistantTokens := cleanTokenize(assistantMsg)
	assistantIDs := make([]float32, len(assistantTokens))
	for i, t := range assistantTokens {
		assistantIDs[i] = float32(lookupVocab(t, it.vocab))
	}

	fullTokens := make([]float32, len(userIDs)+len(assistantIDs))
	copy(fullTokens, userIDs)
	copy(fullTokens[len(userIDs):], assistantIDs)

	lm := make([]float32, len(fullTokens))
	for i := 0; i < len(userIDs); i++ {
		lm[i] = 0.0
	}
	for i := len(userIDs); i < len(fullTokens); i++ {
		lm[i] = 1.0
	}

	return fullTokens, fullTokens, lm
}

func (it *ChatDataIterator) Next() (*tensor.Tensor, *tensor.Tensor, *tensor.Tensor, *tensor.Tensor) {
	pair := it.pairs[it.idx]
	it.idx++

	q := pair.Q
	a := pair.A
	if rand.Float32() < 0.3 {
		synonyms := map[string]string{
			"hello":	"hi", "how are you": "how are you doing", "goodbye": "bye",
			"who are you":	"what is your name", "what is your name": "who are you",
		}
		for old, neu := range synonyms {
			if strings.Contains(strings.ToLower(q), old) {
				q = strings.ReplaceAll(q, old, neu)
				break
			}
		}
	}

	augmentedPair := moe.TrainPair{Q: q, A: a, Intent: pair.Intent}
	fullIDs, _, _ := it.buildChatMLSequence(augmentedPair)

	qIDs := fullIDs

	targetText := a
	aTokens := cleanTokenize(targetText)
	aIDs := make([]float32, len(aTokens)+2)
	aIDs[0] = float32(it.vocab.BosID)
	for i, t := range aTokens {
		aIDs[i+1] = float32(lookupVocab(t, it.vocab))
	}
	aIDs[len(aIDs)-1] = float32(it.vocab.EosID)

	aRoles := SimpleTagger(aTokens)
	gIDs := make([]float32, len(aIDs))
	gIDs[0] = 7
	for i := 0; i < len(aTokens); i++ {
		role := moe.GrammarRoleIndex(aRoles[i])
		if i > 0 && aRoles[i-1] == "PRON" && (aRoles[i] == "VERB" || aRoles[i] == "AUX") {
			gIDs[i+1] = float32(role) + 0.5
		} else {
			gIDs[i+1] = float32(role)
		}
	}
	gIDs[len(gIDs)-1] = 7

	qTokens := cleanTokenize(q)
	qRoles := SimpleTagger(qTokens)
	qgIDs := make([]float32, len(qIDs))
	for i := 0; i < len(qTokens) && i < len(qIDs); i++ {
		role := moe.GrammarRoleIndex(qRoles[i])
		qgIDs[i] = float32(role)
	}

	inputTensor := tensor.NewTensor([]int{1, len(qIDs)}, qIDs, false)
	targetTensor := tensor.NewTensor([]int{1, len(aIDs)}, aIDs, false)
	grammarTensor := tensor.NewTensor([]int{1, len(gIDs)}, gIDs, false)
	queryGrammarTensor := tensor.NewTensor([]int{1, len(qgIDs)}, qgIDs, false)
	return inputTensor, targetTensor, grammarTensor, queryGrammarTensor
}

func (it *ChatDataIterator) NextBatch(batchSize int) *Batch {
	var inputs [][]float32
	var targets [][]float32
	var grammars [][]float32
	var queryGrammars [][]float32
	var weights []float32
	var intents []string
	maxIn, maxOut := 0, 0

	for i := 0; i < batchSize && it.HasNext(); i++ {

		pair := it.pairs[it.idx]
		inp, tgt, gmr, qgmr := it.Next()

		if len(inp.Data) > it.MaxLen || len(tgt.Data) > it.MaxLen {
			continue
		}
		inputs = append(inputs, inp.Data)
		targets = append(targets, tgt.Data)
		grammars = append(grammars, gmr.Data)
		queryGrammars = append(queryGrammars, qgmr.Data)
		intents = append(intents, pair.Intent)

		w := pair.Weight
		if w == 0 {
			w = 1.0
		}
		weights = append(weights, w)

		if len(inp.Data) > maxIn {
			maxIn = len(inp.Data)
		}
		if len(tgt.Data) > maxOut {
			maxOut = len(tgt.Data)
		}
	}

	if len(inputs) == 0 {
		return &Batch{}
	}

	// SIMD alignment: round maxIn and maxOut up to the nearest multiple of 8
	// so that low-level vector operations always operate on aligned memory blocks.
	const simdAlign = 8
	if maxIn%simdAlign != 0 {
		maxIn = (maxIn/simdAlign + 1) * simdAlign
	}
	if maxOut%simdAlign != 0 {
		maxOut = (maxOut/simdAlign + 1) * simdAlign
	}

	paddedIn := make([]float32, len(inputs)*maxIn)
	paddedOut := make([]float32, len(targets)*maxOut)
	paddedGrammar := make([]float32, len(grammars)*maxOut)
	paddedQueryGrammar := make([]float32, len(queryGrammars)*maxIn)
	mask := make([]float32, len(targets)*maxOut)

	lossMask := make([]float32, len(targets)*maxOut)
	inputLogitMask := make([]float32, len(inputs)*maxIn)
	padID := float32(it.vocab.PaddingTokenID)

	for i := range inputs {

		inBase := i * maxIn
		copy(paddedIn[inBase:], inputs[i])

		for j := len(inputs[i]); j < maxIn; j++ {
			paddedIn[inBase+j] = padID
		}

		copy(paddedQueryGrammar[inBase:], queryGrammars[i])
		for j := len(queryGrammars[i]); j < maxIn; j++ {
			paddedQueryGrammar[inBase+j] = -1
		}

		for j := 0; j < len(inputs[i]); j++ {
			inputLogitMask[inBase+j] = 0.0
		}
		for j := len(inputs[i]); j < maxIn; j++ {
			inputLogitMask[inBase+j] = -1e9
		}

		outBase := i * maxOut
		copy(paddedOut[outBase:], targets[i])
		for j := len(targets[i]); j < maxOut; j++ {
			paddedOut[outBase+j] = padID
		}

		copy(paddedGrammar[outBase:], grammars[i])
		for j := len(grammars[i]); j < maxOut; j++ {
			paddedGrammar[outBase+j] = -1
		}

		realLen := len(targets[i])
		for j := 0; j < realLen; j++ {
			mask[outBase+j] = 1.0
			lossMask[outBase+j] = 1.0
		}

	}

	inputMaskTensor := tensor.NewTensor([]int{len(inputs), 1, 1, maxIn}, inputLogitMask, false)

	return &Batch{
		Input:		tensor.NewTensor([]int{len(inputs), maxIn}, paddedIn, false),
		Target:		tensor.NewTensor([]int{len(targets), maxOut}, paddedOut, false),
		Grammar:	tensor.NewTensor([]int{len(grammars), maxOut}, paddedGrammar, false),
		QueryGrammar:	tensor.NewTensor([]int{len(queryGrammars), maxIn}, paddedQueryGrammar, false),
		Mask:		mask,
		LossMask:	lossMask,
		InputMask:	inputMaskTensor,
		Intents:	intents,
		Weights:	weights,
	}
}

func (it *ChatDataIterator) Reset() {
	it.idx = 0
	rand.Shuffle(len(it.pairs), func(i, j int) { it.pairs[i], it.pairs[j] = it.pairs[j], it.pairs[i] })
	log.Println(" Shuffled training data for new epoch")
}

func WeightedCrossEntropy(logits *tensor.Tensor, targets []int, weights []float32, labelSmoothing float32, entropyWeight float32) (float32, *tensor.Tensor) {

	vocabSize := logits.Shape[len(logits.Shape)-1]
	numClasses := vocabSize
	numRows := len(logits.Data) / numClasses
	grad := tensor.NewTensor(logits.Shape, make([]float32, len(logits.Data)), false)

	var totalLoss float32
	var count float32
	lsLabel := labelSmoothing / float32(numClasses)

	// Pre-allocate a shifted-row scratch buffer for the SIMD label-smoothing path.
	// Reusing across rows avoids per-row heap allocations for the common case.
	var lsBuf []float32
	if labelSmoothing > 0 && entropyWeight == 0 {
		lsBuf = make([]float32, numClasses)
	}

	for i := 0; i < numRows; i++ {
		if i >= len(targets) {
			break
		}
		targetID := targets[i]

		if weights[targetID] == 0.0 {
			continue
		}

		offset := i * numClasses
		row := logits.Data[offset : offset+numClasses]

		sumExp := moe.SimdSoftmaxF32(row)

		if math.IsNaN(float64(sumExp)) || math.IsInf(float64(sumExp), 0) {
			if rand.Float32() < 0.01 {
				log.Printf(" [WeightedCrossEntropy] NaNs in row %d! Skipping.", i)
			}
			continue
		}

		prob := row[targetID]
		loss := -float32(math.Log(float64(prob + 1e-12)))

		currentWeight := weights[targetID]
		weightCap := float32(5.0)
		if currentWeight >= 50.0 {
			weightCap = 100.0
		}
		if currentWeight > weightCap {
			currentWeight = weightCap
		}
		if puncWeight, ok := ResolvedPunctuationWeights[targetID]; ok {
			currentWeight *= puncWeight
		}
		if weights[targetID] < 0.1 {
			currentWeight *= 0.5
		}

		totalLoss += loss * currentWeight
		count++

		gradOut := grad.Data[offset : offset+numClasses]

		if entropyWeight > 0 {
			// Slow path: entropy regularisation requires per-element log — stay scalar.
			var rowEntropy float32
			for j := 0; j < numClasses; j++ {
				sj := row[j]
				if sj > 1e-12 {
					rowEntropy -= sj * float32(math.Log(float64(sj)))
				}
			}
			if labelSmoothing > 0 {
				for j := 0; j < numClasses; j++ {
					sj := row[j]
					targetProb := lsLabel
					if j == targetID {
						targetProb += (1.0 - labelSmoothing)
					}
					g := sj - targetProb
					if sj > 1e-12 {
						g -= entropyWeight * sj * (rowEntropy + float32(math.Log(float64(sj))))
					}
					gradOut[j] = g * currentWeight
				}
			} else {
				for j := 0; j < numClasses; j++ {
					sj := row[j]
					g := sj
					if j == targetID {
						g -= 1.0
					}
					if sj > 1e-12 {
						g -= entropyWeight * sj * (rowEntropy + float32(math.Log(float64(sj))))
					}
					gradOut[j] = g * currentWeight
				}
			}
		} else if labelSmoothing > 0 {

			moe.SimdMulScalarF32(lsBuf, row, 1.0)

			for j := range lsBuf {
				lsBuf[j] -= lsLabel
			}

			moe.SimdMulScalarF32(gradOut, lsBuf, currentWeight)

			gradOut[targetID] -= (1.0 - labelSmoothing) * currentWeight
		} else {

			moe.SimdMulScalarF32(gradOut, row, currentWeight)
			gradOut[targetID] = (row[targetID] - 1.0) * currentWeight
		}
	}

	if count > 0 {
		avgLoss := totalLoss / count

		moe.SimdScaleF32(grad.Data, 1.0/count)
		return avgLoss, grad
	}
	return 0, grad
}

// ComputeTokenWeights calculates inverse-frequency weights for tokens in the corpus.
// This discourages the model from over-relying on common words like 'a', 'the', 'to'.
func ComputeTokenWeights(sentences []MLMSentence, vocab *mainvocab.Vocabulary) []float32 {
	vocabSize := vocab.Size()
	counts := make([]int, vocabSize)
	total := 0

	for _, s := range sentences {
		tokens := tokenizer.Tokenize(s.Text)
		for _, t := range tokens {
			id := vocab.GetTokenID(t)
			if id >= 0 && id < vocabSize {
				counts[id]++
				total++
			}
		}
	}

	weights := make([]float32, vocabSize)
	for i := 0; i < vocabSize; i++ {
		if counts[i] == 0 {
			weights[i] = 1.0
			continue
		}

		w := 1.0 / float32(math.Pow(math.Log(float64(counts[i])+1.1), 2.0))

		if counts[i] < 5 {
			w *= 10.0
		}

		weights[i] = w
	}

	// Normalize so mean weight is 1.0 (to keep loss scale comparable)
	var sum float32
	for _, w := range weights {
		sum += w
	}
	avg := sum / float32(vocabSize)
	for i := range weights {
		weights[i] /= avg
	}

	log.Printf("⚖️ Token Weighting: 'a' weight: %.4f | 'the' weight: %.4f | rarity boost active.", weights[vocab.GetTokenID("a")], weights[vocab.GetTokenID("the")])
	return weights
}

type MLMHead struct {
	Linear	*neuralnn.Linear
	Grammar	*neuralnn.Linear	// Branch for POS tagging
	Intent	*neuralnn.Linear	// Branch for Intent classification
}

func NewMLMHead(hiddenSize, vocabSize int) (*MLMHead, error) {
	linear, _ := neuralnn.NewLinear(hiddenSize, vocabSize)
	grammar, _ := neuralnn.NewLinear(hiddenSize, 10)
	intent, _ := neuralnn.NewLinear(hiddenSize, 20)

	InitializeHeNormal(linear.Weights)
	InitializeHeNormal(grammar.Weights)
	InitializeHeNormal(intent.Weights)

	return &MLMHead{
		Linear:		linear,
		Grammar:	grammar,
		Intent:		intent,
	}, nil
}

// Forward projects encoder outputs to vocabulary logits.
// Input shape: [batch, seq_len, hidden_size]
// Output shape: [batch, seq_len, vocab_size]
func (h *MLMHead) Forward(encoderOutput *tensor.Tensor) (*tensor.Tensor, error) {
	return h.Linear.Forward(encoderOutput)
}

// Backward propagates gradients through the MLM head.
func (h *MLMHead) Backward(grad *tensor.Tensor) error {
	return h.Linear.Backward(grad)
}

// Parameters returns all learnable parameters.
func (h *MLMHead) Parameters() []*tensor.Tensor {
	return h.Linear.Parameters()
}

// ClearState clears intermediate computation state.
func (h *MLMHead) ClearState() {
	h.Linear.ClearState()
}

type MLMBatch struct {
	// Input token IDs with some positions replaced by [MASK]
	MaskedInput	*tensor.Tensor	// [batch, seq_len]
	// Original token IDs (targets for prediction)
	OriginalIDs	*tensor.Tensor	// [batch, seq_len]
	// Boolean mask: 1.0 at masked positions, 0.0 elsewhere
	MaskPositions	*tensor.Tensor	// [batch, seq_len]
	// Attention mask for padding (0.0 for real, -1e9 for pad)
	AttentionMask	*tensor.Tensor	// [batch, 1, 1, seq_len]
	// Ground truth intent IDs for classification branch
	Intents	*tensor.Tensor	// [batch]
}

type MLMSentence struct {
	Text	string
	Intent	string
}

// NewMLMDataIterator creates a new MLM data iterator.
func NewMLMDataIterator(sentences []MLMSentence, vocab *mainvocab.Vocabulary, maskProb float32, intentToID map[string]int) *MLMDataIterator {

	if vocab.GetTokenID(MaskToken) == -1 {
		vocab.AddToken(MaskToken)
	}

	maskID := vocab.GetTokenID(MaskToken)
	padID := vocab.PaddingTokenID
	unkID := vocab.GetTokenID("UNK")

	rand.Shuffle(len(sentences), func(i, j int) {
		sentences[i], sentences[j] = sentences[j], sentences[i]
	})

	return &MLMDataIterator{
		sentences:	sentences,
		vocab:		vocab,
		intentToID:	intentToID,
		maskID:		maskID,
		padID:		padID,
		unkID:		unkID,
		idx:		0,
		maskProb:	maskProb,
		maxLen:		64,
	}
}

// HasNext returns true if there are more sentences to process.
func (it *MLMDataIterator) HasNext() bool {
	return it.idx < len(it.sentences)
}

// Reset reshuffles the data and resets the cursor.
func (it *MLMDataIterator) Reset() {
	it.idx = 0
	rand.Shuffle(len(it.sentences), func(i, j int) {
		it.sentences[i], it.sentences[j] = it.sentences[j], it.sentences[i]
	})
}

// NextBatch creates the next MLM batch.
func (it *MLMDataIterator) NextBatch(batchSize int) *MLMBatch {
	var allOriginal [][]float32
	var allMasked [][]float32
	var allMaskPos [][]float32
	var batchIntents []float32
	maxLen := 0

	for i := 0; i < batchSize && it.HasNext(); i++ {
		sentence := it.sentences[it.idx]
		it.idx++

		tokens := cleanTokenize(sentence.Text)
		if len(tokens) < 2 {
			continue
		}
		if len(tokens) > it.maxLen {
			tokens = tokens[:it.maxLen]
		}

		originalIDs := make([]float32, len(tokens))
		maskedIDs := make([]float32, len(tokens))
		maskPositions := make([]float32, len(tokens))

		for j, t := range tokens {
			id := lookupVocab(t, it.vocab)
			originalIDs[j] = float32(id)
			maskedIDs[j] = float32(id)
		}

		// --- SEQUENTIAL STRUCTURAL MASKING ---
		var candidates []int
		for j := 0; j < len(tokens); j++ {
			if !isPunctuation(tokens[j]) {
				candidates = append(candidates, j)
			}
		}

		if len(candidates) > 0 {

			maskIdx := candidates[it.epoch%len(candidates)]
			maskPositions[maskIdx] = 1.0
			maskedIDs[maskIdx] = float32(it.maskID)
		}

		allOriginal = append(allOriginal, originalIDs)
		allMasked = append(allMasked, maskedIDs)
		allMaskPos = append(allMaskPos, maskPositions)

		intentID := float32(-1)
		if it.intentToID != nil {
			if id, ok := it.intentToID[sentence.Intent]; ok {
				intentID = float32(id)
			}
		}
		batchIntents = append(batchIntents, intentID)

		if len(tokens) > maxLen {
			maxLen = len(tokens)
		}
	}

	if len(allOriginal) == 0 {
		return nil
	}

	actualBatch := len(allOriginal)
	padID := float32(it.padID)
	paddedOriginal := make([]float32, actualBatch*maxLen)
	paddedMasked := make([]float32, actualBatch*maxLen)
	paddedMaskPos := make([]float32, actualBatch*maxLen)
	attentionMask := make([]float32, actualBatch*maxLen)

	for i := 0; i < actualBatch; i++ {
		for j := 0; j < maxLen; j++ {
			if j < len(allOriginal[i]) {
				paddedOriginal[i*maxLen+j] = allOriginal[i][j]
				paddedMasked[i*maxLen+j] = allMasked[i][j]
				paddedMaskPos[i*maxLen+j] = allMaskPos[i][j]
				attentionMask[i*maxLen+j] = 0.0
			} else {
				paddedOriginal[i*maxLen+j] = padID
				paddedMasked[i*maxLen+j] = padID
				paddedMaskPos[i*maxLen+j] = 0.0
				attentionMask[i*maxLen+j] = -1e9
			}
		}
	}

	return &MLMBatch{
		MaskedInput:	tensor.NewTensor([]int{actualBatch, maxLen}, paddedMasked, false),
		OriginalIDs:	tensor.NewTensor([]int{actualBatch, maxLen}, paddedOriginal, false),
		MaskPositions:	tensor.NewTensor([]int{actualBatch, maxLen}, paddedMaskPos, false),
		AttentionMask:	tensor.NewTensor([]int{actualBatch, 1, 1, maxLen}, attentionMask, false),
		Intents:	tensor.NewTensor([]int{actualBatch}, batchIntents, false),
	}
}

func MLMCrossEntropy(logits *tensor.Tensor, targets []int, maskPositions []float32, vocabSize int, tokenWeights []float32, vocab *mainvocab.Vocabulary) (float32, *tensor.Tensor) {
	numPositions := len(targets)
	grad := tensor.NewTensor(logits.Shape, make([]float32, len(logits.Data)), false)
	var totalLoss float32
	var count float32

	labelSmoothing := float32(0.1)
	confidence := 1.0 - labelSmoothing
	smoothingValue := labelSmoothing / float32(vocabSize)

	predCounts := make(map[int]int)
	for i := 0; i < numPositions; i++ {
		if maskPositions[i] < 0.5 {
			continue
		}
		offset := i * vocabSize
		row := logits.Data[offset : offset+vocabSize]
		bestIdx := 0
		maxVal := float32(-1e9)
		for j, v := range row {
			if v > maxVal {
				maxVal = v
				bestIdx = j
			}
		}
		predCounts[bestIdx]++
	}

	numWorkers := runtime.NumCPU()
	if numWorkers > 16 {
		numWorkers = 16
	}
	jobs := make(chan struct{ start, end int }, numWorkers)
	var wg sync.WaitGroup
	var lossMutex sync.Mutex

	for w := 0; w < numWorkers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			localSoftmax := make([]float32, vocabSize)
			var localLoss float32
			var localCount float32
			for jb := range jobs {
				for i := jb.start; i < jb.end; i++ {
					if maskPositions[i] < 0.5 {
						continue
					}
					targetID := targets[i]
					if targetID < 0 || targetID >= vocabSize {
						continue
					}

					weight := float32(1.0)
					if tokenWeights != nil {
						weight = tokenWeights[targetID]
					}

					offset := i * vocabSize
					row := logits.Data[offset : offset+vocabSize]
					maxLogit := row[0]
					for _, v := range row {
						if v > maxLogit {
							maxLogit = v
						}
					}
					var sumExp float32
					for j, v := range row {
						localSoftmax[j] = float32(math.Exp(float64(v - maxLogit)))
						sumExp += localSoftmax[j]
					}
					invSumExp := float32(1.0) / (sumExp + 1e-8)

					obsessionPenalty := float32(1.0)
					predictedIdx := 0
					maxP := float32(-1e9)
					for j := 0; j < vocabSize; j++ {
						if localSoftmax[j] > maxP {
							maxP = localSoftmax[j]
							predictedIdx = j
						}
					}
					if predCounts[predictedIdx] > 3 && predictedIdx != targetID {
						obsessionPenalty = 8.0
					}

					targetWord := vocab.GetWord(targetID)
					targetType := moe.MapWordToGrammarType(targetWord)

					rule := moe.IntentRule{}
					prevType := "BOS"
					if i > 0 && targets[i-1] >= 0 {
						prevType = moe.MapWordToGrammarType(vocab.GetWord(targets[i-1]))
					}
					nextType := "EOS"
					if i < numPositions-1 && targets[i+1] >= 0 {
						nextType = moe.MapWordToGrammarType(vocab.GetWord(targets[i+1]))
					}

					if targetType != "OTHER" {
						for j := 0; j < vocabSize; j++ {
							if j == targetID {
								continue
							}
							w_j := vocab.GetWord(j)
							t_j := moe.MapWordToGrammarType(w_j)
							if t_j != targetType {
								logits.Data[offset+j] = -1e9
							}

							penalty := rule.EvaluateWindow(prevType, t_j, nextType)
							if penalty > 0 {
								logits.Data[offset+j] -= penalty * 5.0
							}
						}
					}

					maxLogit = logits.Data[offset]
					for j := 1; j < vocabSize; j++ {
						if logits.Data[offset+j] > maxLogit {
							maxLogit = logits.Data[offset+j]
						}
					}
					sumExp = 0
					for j := 0; j < vocabSize; j++ {
						localSoftmax[j] = float32(math.Exp(float64(logits.Data[offset+j] - maxLogit)))
						sumExp += localSoftmax[j]
					}
					invSumExp = float32(1.0) / (sumExp + 1e-8)

					prob := localSoftmax[targetID] * invSumExp
					wordLoss := -float32(math.Log(float64(prob)+1e-10)) * confidence

					localLoss += wordLoss * weight * obsessionPenalty
					localCount++

					for j := 0; j < vocabSize; j++ {
						sj := localSoftmax[j] * invSumExp
						targetProb := smoothingValue
						if j == targetID {
							targetProb += confidence
						}
						grad.Data[offset+j] = weight * obsessionPenalty * (sj - targetProb)
					}
				}
			}
			lossMutex.Lock()
			totalLoss += localLoss
			count += localCount
			lossMutex.Unlock()
		}()
	}

	chunkSize := (numPositions + numWorkers - 1) / numWorkers
	for i := 0; i < numPositions; i += chunkSize {
		end := i + chunkSize
		if end > numPositions {
			end = numPositions
		}
		jobs <- struct{ start, end int }{i, end}
	}
	close(jobs)
	wg.Wait()

	if count > 0 {
		avgLoss := totalLoss / count
		invCount := float32(1.0) / count
		for i := range grad.Data {
			grad.Data[i] *= invCount
		}
		return avgLoss, grad
	}
	return 0, grad
}

func RunMLMPreTraining(model *moe.IntentMoE, sentences []MLMSentence, mlmEpochs int, batchSize int, learningRate float32, maxGradNorm float32, useGPU bool, savePath string) error {
	log.Println("🎓 PHASE 0: MLM Pre-Training")
	vocabSize := model.SentenceVocab.Size()
	embeddingDim := model.EmbeddingDim
	mlmHead, _ := NewMLMHead(embeddingDim, vocabSize)
	for _, p := range mlmHead.Parameters() {
		if len(p.Shape) > 1 {
			InitializeHeNormal(p)
		} else {
			for i := range p.Data {
				p.Data[i] = 0
			}
		}
		p.RequiresGrad = true
	}
	if useGPU {
		mlmHead.Linear.ToGPU()
	}

	allParams := make([]*tensor.Tensor, 0)
	allParams = append(allParams, model.Embedding.Parameters()...)
	allParams = append(allParams, model.Encoder.Parameters()...)
	if model.EncoderNorm != nil {
		allParams = append(allParams, model.EncoderNorm.Parameters()...)
	}
	allParams = append(allParams, mlmHead.Parameters()...)
	allParams = append(allParams, mlmHead.Intent.Parameters()...)

	optimizer := neuralnn.NewOptimizer(allParams, learningRate, 0)

	intentToID := make(map[string]int)
	idToIntent := make(map[int]string)
	for _, s := range sentences {
		if s.Intent != "" {
			if _, ok := intentToID[s.Intent]; !ok {
				id := len(intentToID)
				if id < 20 {
					intentToID[s.Intent] = id
					idToIntent[id] = s.Intent
				}
			}
		}
	}
	iterator := NewMLMDataIterator(sentences, model.SentenceVocab, 0.15, intentToID)
	iterator.maxLen = 80
	model.SetMode(true)

	globalStep := model.StepCount
	totalSteps := mlmEpochs * (len(sentences) / batchSize)
	if totalSteps == 0 {
		totalSteps = 1000
	}
	var smoothLoss, smoothPPL float32
	var accuracy float32
	var intentAccuracy float32

	tokenWeights := ComputeTokenWeights(sentences, model.SentenceVocab)

	for epoch := 0; epoch < mlmEpochs; epoch++ {
		log.Printf("🎓 MLM Epoch %d/%d", epoch+1, mlmEpochs)
		iterator.Reset()
		iterator.epoch = epoch
		var epochLoss float32
		batches := 0
		for iterator.HasNext() {
			batch := iterator.NextBatch(batchSize)
			if batch == nil {
				continue
			}
			optimizer.ZeroGrad()

			encoderOutput, err := model.EncoderForward(batch.MaskedInput, batch.AttentionMask)
			if err != nil {
				continue
			}
			logits, err := mlmHead.Forward(encoderOutput)
			if err != nil {
				continue
			}

			intentInput, _ := encoderOutput.Mean(1)
			intentLogits, err := mlmHead.Intent.Forward(intentInput)

			logits.ToCPU()
			batchSz, seqLen := batch.OriginalIDs.Shape[0], batch.OriginalIDs.Shape[1]
			targets := make([]int, batchSz*seqLen)
			for j := range batch.OriginalIDs.Data {
				targets[j] = int(batch.OriginalIDs.Data[j])
			}

			loss, grad := MLMCrossEntropy(logits, targets, batch.MaskPositions.Data, vocabSize, tokenWeights, model.SentenceVocab)
			if loss > 100.0 {
				loss = 100.0
			}

			// Compute Intent Loss if labels are available
			var intentLoss float32
			var intentGrad *tensor.Tensor
			batchIntents := make([]int, batchSz)
			hasIntent := false
			for b := 0; b < batchSz; b++ {
				id := int(batch.Intents.Data[b])
				if id >= 0 {
					batchIntents[b] = id
					hasIntent = true
				} else {
					batchIntents[b] = -1
				}
			}
			if hasIntent {
				intentWeights := make([]float32, 20)
				for i := range intentWeights {
					intentWeights[i] = 1.0
				}

				intentGrad = tensor.NewTensor(intentLogits.Shape, make([]float32, len(intentLogits.Data)), false)
				intentLogitsCPU := intentLogits.ToCPU()
				var validCount float32

				for b := 0; b < batchSz; b++ {
					if batchIntents[b] == -1 {
						continue
					}

					rowLogits := tensor.NewTensor([]int{1, 20}, intentLogitsCPU.Data[b*20:(b+1)*20], false)
					l, g := WeightedCrossEntropy(rowLogits, []int{batchIntents[b]}, intentWeights, 0.1, 0.005)
					intentLoss += l
					for i := 0; i < 20; i++ {
						intentGrad.Data[b*20+i] = g.Data[i]
					}
					validCount++
				}
				if validCount > 0 {
					intentLoss /= validCount
					loss += intentLoss * 0.5
				}

				// Track Intent Accuracy
				var correct int
				for b := 0; b < batchSz; b++ {
					if batchIntents[b] == -1 {
						continue
					}
					row := intentLogits.Data[b*20 : (b+1)*20]
					if argMaxSlice(row) == batchIntents[b] {
						correct++
					}
				}
				intentAccuracy = float32(correct) / validCount
			}

			grad3D, _ := grad.Reshape(logits.Shape)
			if useGPU {
				grad3D.ToGPU()
			}
			if err := mlmHead.Backward(grad3D); err != nil {
				continue
			}

			if intentGrad != nil {
				if useGPU {
					intentGrad.ToGPU()
				}
				mlmHead.Intent.Backward(intentGrad)
			}

			encoderGrad := mlmHead.Linear.Input().Grad
			if intentGrad != nil && mlmHead.Intent.Input().Grad != nil {

				ig := mlmHead.Intent.Input().Grad
				for b := 0; b < batchSz; b++ {
					for s := 0; s < seqLen; s++ {
						for d := 0; d < embeddingDim; d++ {
							encoderGrad.Data[(b*seqLen+s)*embeddingDim+d] += ig.Data[b*embeddingDim+d] / float32(seqLen)
						}
					}
				}
			}

			if model.EncoderNorm != nil {
				model.EncoderNorm.Backward(encoderGrad)
				encoderGrad = model.EncoderNorm.Input().Grad
			}
			train.ClipParamGrads([][]float32{encoderGrad.Data}, maxGradNorm)
			model.Encoder.Backward(encoderGrad)

			gradBeforePos := model.Encoder.Inputs()[0].Grad
			if gradBeforePos != nil {
				if model.EncoderPos != nil {
					model.EncoderPos.Backward(gradBeforePos)
					if len(model.EncoderPos.Inputs()) > 0 {
						gradBeforePos = model.EncoderPos.Inputs()[0].Grad
					}
				}
				if gradBeforePos != nil {
					model.Embedding.Backward(gradBeforePos)
				}
			}

			allComponentParams := [][]*tensor.Tensor{model.Embedding.Parameters(), model.Encoder.Parameters(), mlmHead.Parameters(), mlmHead.Intent.Parameters()}
			if model.EncoderNorm != nil {
				allComponentParams = append(allComponentParams, model.EncoderNorm.Parameters())
			}
			for _, params := range allComponentParams {
				grads := make([][]float32, 0)
				for _, p := range params {
					if p.Grad != nil {
						grads = append(grads, p.Grad.Data)
					}
				}
				if len(grads) > 0 {
					train.ClipParamGrads(grads, maxGradNorm)
				}
			}

			if globalStep%5 == 0 {
				StabilizeParameters(model, 5.0, 2.0)
			}
			optimizer.Step()
			optimizer.SetLearningRate(train.GetLR(globalStep, totalSteps, learningRate))
			if useGPU {
				for _, p := range allParams {
					p.SyncToDevice()
				}
			}

			if smoothLoss == 0 {
				smoothLoss = loss
			} else {
				smoothLoss = 0.9*smoothLoss + 0.1*loss
			}

			// --- PREDICTIVE ACCURACY TRACKING (MLM) ---
			var correct int
			var total int
			logits.ToCPU()
			for i := range targets {
				if targets[i] < 0 || targets[i] >= vocabSize {
					continue
				}
				if batch.MaskPositions.Data[i] < 0.5 {
					continue
				}

				offset := i * vocabSize
				bestIdx := 0
				bestVal := float32(-1e9)
				for j := 0; j < vocabSize; j++ {
					if logits.Data[offset+j] > bestVal {
						bestVal = logits.Data[offset+j]
						bestIdx = j
					}
				}
				if bestIdx == targets[i] {
					correct++
				}
				total++
			}
			accuracy = float32(0)
			if total > 0 {
				accuracy = float32(correct) / float32(total)
			}

			if globalStep%50 == 0 {
				smoothPPL = float32(math.Exp(float64(smoothLoss)))
				log.Printf("🎓 MLM Step %d | Loss: %.4f | Accuracy: %.2f%% (Intent: %.2f%%) | PPL: %.1f", globalStep, loss, accuracy*100, intentAccuracy*100, smoothPPL)
				logMLMPrediction(model, mlmHead, batch, vocabSize, useGPU)
			}

			model.ClearState()
			mlmHead.ClearState()
			DetachMLMModel(model, mlmHead)
			epochLoss += loss
			batches++
			globalStep++

			if globalStep%500 == 0 && savePath != "" {
				model.StepCount = globalStep
				ckpt := &moe.Checkpoint{Model: model, StepCount: globalStep, Version: "mlm"}
				moe.SaveIntentMoECheckpoint(ckpt, savePath)
			}
		}

		log.Printf("🧪 MLM PROBE [Epoch %d]", epoch+1)
		RunMLMProbe(model, mlmHead, "[Intent: social] how are [mask] today", "you")
		RunMLMProbe(model, mlmHead, "[Intent: social] i am [mask] [mask] today", "doing", "fine")

		log.Printf("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
		log.Printf("📜  MLM PREDICTIVE SUMMARY — End of Epoch %d", epoch+1)
		log.Printf("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
		log.Printf("   AUDIT: 'Vocabulary Sensitivity' vs 'The Frequency Trap'")
		log.Printf("   ")
		log.Printf("   WHAT IT PREDICTS: Currently, the model is 'lazy' and ")
		log.Printf("   predicts '%s' because it's the safest statistical bet.", model.SentenceVocab.GetWord(0))
		log.Printf("   HOW TO FIX IT: We are increasing 'Inverse Frequency Weights'.")
		log.Printf("   This forces the experts to ignore common filler and ")
		log.Printf("   actually look at the sentence context to find rare words.")

		if accuracy > 0.30 {
			log.Printf("   🚀 STATUS: The Experts have broken the Frequency Trap!")
			log.Printf("      Model is now predicting specific content words.")
		} else if accuracy > 0.10 {
			log.Printf("   🔄 STATUS: Model is transitioning. Structure is emerging.")
			log.Printf("      It's starting to guess words other than 'the' or 'a'.")
		} else {
			log.Printf("   ⚠️ STATUS: OBSESSION DETECTED (Accuracy: %.2f%%)", accuracy*100)
			log.Printf("      ACTION: Model is repeating a single token for all masks.")
			log.Printf("      FIX: Applying 'Batch Repetition Penalty' (5.0x) to break obsession.")
		}
		log.Printf("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
	}
	model.TrainingPhase = 1
	model.StepCount = globalStep
	return nil
}

func isPunctuation(t string) bool {
	if len(t) == 0 {
		return false
	}
	if len(t) > 1 {

		if t == "..." || t == "--" {
			return true
		}
		return false
	}
	r := rune(t[0])
	return unicode.IsPunct(r) || r == '?' || r == '!' || r == '.' || r == ',' || r == ';' || r == ':' || r == '(' || r == ')' || r == '[' || r == ']' || r == '"' || r == '\''
}

func argMaxSlice(slice []float32) int {
	maxIdx := 0
	maxVal := slice[0]
	for i, v := range slice {
		if v > maxVal {
			maxVal = v
			maxIdx = i
		}
	}
	return maxIdx
}

func RunMLMProbe(model *moe.IntentMoE, mlmHead *MLMHead, template string, expected ...string) {
	tokens := cleanTokenize(template)
	seqLen := len(tokens)
	maskedIDs := make([]float32, seqLen)
	originalIDs := make([]int, seqLen)
	var maskIndices []int
	expectedIdx := 0
	for i, t := range tokens {
		id := lookupVocab(t, model.SentenceVocab)
		maskedIDs[i] = float32(id)
		originalIDs[i] = id
		if t == "[mask]" {
			maskIndices = append(maskIndices, i)
			maskedIDs[i] = float32(model.SentenceVocab.GetTokenID(MaskToken))
			if expectedIdx < len(expected) {
				originalIDs[i] = lookupVocab(expected[expectedIdx], model.SentenceVocab)
				expectedIdx++
			}
		}
	}
	logits, _ := model.EncoderForward(tensor.NewTensor([]int{1, seqLen}, maskedIDs, false), nil)
	output, _ := mlmHead.Forward(logits)
	output.ToCPU()
	for _, idx := range maskIndices {
		row := output.Data[idx*model.SentenceVocabSize : (idx+1)*model.SentenceVocabSize]
		log.Printf("    🔍 Probe '%s' → Expected: '%s' | Predicted: '%s'", template, model.SentenceVocab.GetWord(originalIDs[idx]), model.SentenceVocab.GetWord(argMaxSlice(row)))
	}
	model.ClearState()
	mlmHead.ClearState()
}

func logMLMPrediction(model *moe.IntentMoE, mlmHead *MLMHead, batch *MLMBatch, vocabSize int, useGPU bool) {
	model.SetMode(false)
	defer model.SetMode(true)
	for j := 0; j < batch.MaskedInput.Shape[1]; j++ {
		if batch.MaskPositions.Data[j] > 0.5 {
			logits, _ := model.EncoderForward(batch.MaskedInput, batch.AttentionMask)
			output, _ := mlmHead.Forward(logits)
			output.ToCPU()
			row := output.Data[j*vocabSize : (j+1)*vocabSize]

			targetWord := model.SentenceVocab.GetWord(int(batch.OriginalIDs.Data[j]))
			predWord := model.SentenceVocab.GetWord(argMaxSlice(row))

			targetType := moe.MapWordToGrammarType(targetWord)
			predType := moe.MapWordToGrammarType(predWord)

			log.Printf("    🔮 Prediction Audit: Expected '%s' (%s) | Model Guessed: '%s' (%s)", targetWord, targetType, predWord, predType)
			if targetType != predType && targetType != "OTHER" {
				log.Printf("    🚨 GRAMMAR ALERT: Model guessed a %s instead of a %s. Applying Structural Penalty.", predType, targetType)
			}
			if targetWord != predWord && predWord == "a" {
				log.Printf("    ⚠️  Note: Frequency Bias detected. Experts are coasting on 'a'.")
			}
			break
		}
	}
	model.ClearState()
	mlmHead.ClearState()
}

func DetachMLMModel(model *moe.IntentMoE, mlmHead *MLMHead) {
	for _, p := range model.Parameters() {
		if p != nil {
			p.Creator = nil
			p.Mask = nil
			p.Operation = nil
		}
	}
	if mlmHead != nil {
		for _, p := range mlmHead.Parameters() {
			if p != nil {
				p.Creator = nil
				p.Mask = nil
				p.Operation = nil
			}
		}
	}
	model.ClearState()
}

func ExtractMLMSentences(pairs []moe.TrainPair) []MLMSentence {
	seen := make(map[string]bool)
	var sentences []MLMSentence
	for _, pair := range pairs {
		if pair.Q != "" && !seen[pair.Q] {
			seen[pair.Q] = true
			sentences = append(sentences, MLMSentence{Text: pair.Q, Intent: pair.Intent})
		}
		if pair.A != "" && !seen[pair.A] {
			seen[pair.A] = true
			sentences = append(sentences, MLMSentence{Text: pair.A, Intent: pair.Intent})
		}
	}
	return sentences
}

// LoadComputerCSV parses the computer.csv dataset into TrainPairs.
func LoadComputerCSV(path string) []moe.TrainPair {
	var pairs []moe.TrainPair
	f, err := os.Open(path)
	if err != nil {
		return pairs
	}
	defer f.Close()
	reader := csv.NewReader(f)
	records, _ := reader.ReadAll()
	for i, record := range records {
		if i == 0 || len(record) < 2 {
			continue
		}
		intent := "computer"
		if len(record) >= 3 {
			intent = record[2]
		}
		pairs = append(pairs, moe.TrainPair{Q: record[0], A: record[1], Intent: intent})
	}
	return pairs
}

// setLayerFreezeQuiet sets expert freeze state without printing if unchanged.
func setLayerFreezeQuiet(layer *moe.MoELayer, expertID int, freeze bool) {
	if expertID < 0 || expertID >= len(layer.ExpertFrozen) {
		return
	}
	if layer.ExpertFrozen[expertID] == freeze {
		return
	}
	layer.SetExpertFreeze(expertID, freeze)
}

// applyPhaseFreeze sets the correct freeze pattern for the given phase on all layers.
// Phase 1: freeze experts >= freezeStart (cartridges), thaw 0..freezeStart-1 (conversational)
// Phase 2: freeze experts 0..freezeEnd-1 (conversational), thaw >= freezeEnd (cartridges)
// Phase 3: thaw everyone (freezeStart < 0)
func applyPhaseFreeze(layers []*moe.MoELayer, freezeStart, freezeEnd int) {
	for _, layer := range layers {
		for i := 0; i < len(layer.Experts); i++ {
			var shouldFreeze bool
			if freezeStart >= 0 && freezeEnd > freezeStart {

				shouldFreeze = i >= freezeStart && i < freezeEnd
			} else if freezeStart >= 0 {

				shouldFreeze = i >= freezeStart
			} else {
				shouldFreeze = false
			}
			setLayerFreezeQuiet(layer, i, shouldFreeze)
		}
	}
}

// svcIsCoherent returns true when a generated response looks like real language
// (not SALAD): needs at least 2 words and a type-token ratio above 0.5.
func svcIsCoherent(response string) bool {
	words := strings.Fields(strings.ToLower(response))
	if len(words) < 2 {
		return false
	}

	hasConversational := false
	socialTokens := map[string]bool{"hi": true, "hello": true, "assistant": true, "am": true, "gollemer": true, "how": true, "you": true, "i": true, "doing": true, "well": true, "great": true, "fine": true, "good": true, "thanks": true}
	techTokens := map[string]bool{"elasticsearch": true, "cloudflare": true, "/readyz": true, "goroutines": true, "asynchronous": true, "pub/sub": true, "cpu": true, "dataset": true}

	unique := make(map[string]struct{})
	for _, w := range words {
		wClean := strings.Trim(w, ".,!?")
		unique[w] = struct{}{}
		if socialTokens[wClean] {
			hasConversational = true
		}
		if techTokens[wClean] {
			return false
		}
	}

	ttr := float64(len(unique)) / float64(len(words))

	if len(words) <= 3 {
		return hasConversational
	}
	return ttr >= 0.5 && hasConversational
}

// phaseForEpoch returns the 1-based phase number for a given epoch index.
func phaseForEpoch(epoch int) int {
	p := epoch/epochsPerPhase + 1
	if p > 5 {
		return 5
	}
	return p
}

// TrainMultiPhaseCurriculum orchestrates the 5-phase, 200-epoch-per-phase curriculum.
// All hyperparameters are loaded from data/config/social_train.json.
// Phase boundaries are purely epoch-count based: phase = epoch/200 + 1 (clamped to 5).
func TrainMultiPhaseCurriculum(projectRoot string, useGPU bool, dataFile string) {
	log.Println("🚀 Starting 5-Phase Multi-Domain Curriculum Training (200 epochs/phase)...")
	for p := 1; p <= 5; p++ {
		log.Printf("   Phase %d: %s", p, phaseNames[p])
	}

	configPath := filepath.Join(projectRoot, "data/config/social_train.json")
	safeCfg, err := orchestrator.NewSafeConfig(configPath)
	if err != nil {
		log.Fatalf("❌ Failed to load config from %s: %v", configPath, err)
	}
	cfg := safeCfg.Get()

	// ── 1. Load datasets ──────────────────────────────────────────────────────
	var socialPairs []moe.TrainPair
	var computerPairs []moe.TrainPair

	conversationsCSVPath := filepath.Join(projectRoot, "data/training/trainingdata/conversations.csv")
	if f, err := os.Open(conversationsCSVPath); err == nil {
		reader := csv.NewReader(f)
		records, _ := reader.ReadAll()
		f.Close()
		type turn struct{ role, content string }
		convMap := make(map[string][]turn)
		convOrder := []string{}
		seen := map[string]bool{}
		for i, rec := range records {
			if i == 0 || len(rec) < 4 {
				continue
			}
			id, role, content := rec[0], rec[2], rec[3]
			convMap[id] = append(convMap[id], turn{role, content})
			if !seen[id] {
				seen[id] = true
				convOrder = append(convOrder, id)
			}
		}
		convCount := 0
		for _, id := range convOrder {
			turns := convMap[id]
			for i := 0; i+1 < len(turns); i++ {
				if strings.ToLower(turns[i].role) == "user" && strings.ToLower(turns[i+1].role) == "assistant" {
					q, a := strings.TrimSpace(turns[i].content), strings.TrimSpace(turns[i+1].content)
					if q != "" && a != "" {
						socialPairs = append(socialPairs, moe.TrainPair{Q: q, A: a, Intent: "social"})
						convCount++
					}
				}
			}
		}
		log.Printf("📚 Loaded %d pairs from conversations.csv", convCount)
	} else {
		log.Printf("⚠️ conversations.csv: %v", err)
	}

	conversingCSVPath := filepath.Join(projectRoot, "data/training/trainingdata/conversing.csv")
	if pairs, err := LoadConversingCSV(conversingCSVPath); err == nil {
		socialPairs = append(socialPairs, pairs...)
		log.Printf("📚 Loaded %d pairs from conversing.csv", len(pairs))
	} else {
		log.Printf("⚠️ conversing.csv: %v", err)
	}

	intentCorpusPath := filepath.Join(projectRoot, "data/training/intent_corpus.json")
	if raw, err := os.ReadFile(intentCorpusPath); err == nil {
		var corpus []struct {
			Intent		string		`json:"intent"`
			Examples	[]string	`json:"examples"`
		}
		if jsonErr := json.Unmarshal(raw, &corpus); jsonErr == nil {
			intentCount := 0
			for _, entry := range corpus {
				intentName := strings.ReplaceAll(entry.Intent, "_", " ")
				for _, example := range entry.Examples {
					if strings.TrimSpace(example) == "" {
						continue
					}

					if strings.Contains(entry.Intent, "edit") ||
						strings.Contains(entry.Intent, "code") ||
						strings.Contains(entry.Intent, "fix") ||
						strings.Contains(entry.Intent, "add") ||
						strings.Contains(entry.Intent, "refactor") ||
						strings.Contains(entry.Intent, "debug") {
						computerPairs = append(computerPairs, moe.TrainPair{
							Q:	example,
							A:	fmt.Sprintf("Sure, I will %s.", intentName),
							Intent:	"computer",
						})
					} else {
						socialPairs = append(socialPairs, moe.TrainPair{
							Q:	example,
							A:	fmt.Sprintf("Sure, I will %s.", intentName),
							Intent:	"social",
						})
					}
					intentCount++
				}
			}
			log.Printf("📚 Loaded %d intent examples from intent_corpus.json", intentCount)
		} else {
			log.Printf("⚠️ Failed to parse intent_corpus.json: %v", jsonErr)
		}
	} else {
		log.Printf("⚠️ intent_corpus.json: %v", err)
	}

	minedPatchesPath := filepath.Join(projectRoot, "data/training/mined_patches.json")
	if raw, err := os.ReadFile(minedPatchesPath); err == nil {
		var patches []struct {
			Instruction	string	`json:"instruction"`
			TargetPatch	string	`json:"target_patch"`
		}
		if jsonErr := json.Unmarshal(raw, &patches); jsonErr == nil {
			for _, p := range patches {
				q := strings.TrimSpace(p.Instruction)
				a := strings.TrimSpace(p.TargetPatch)
				if q != "" && a != "" {
					computerPairs = append(computerPairs, moe.TrainPair{Q: q, A: a, Intent: "computer"})
				}
			}
			log.Printf("📚 Loaded %d instruction-patch pairs from mined_patches.json", len(patches))
		} else {
			log.Printf("⚠️ Failed to parse mined_patches.json: %v", jsonErr)
		}
	} else {
		log.Printf("⚠️ mined_patches.json: %v", err)
	}

	minedFIMPath := filepath.Join(projectRoot, "data/training/mined_patches_fim.json")
	if raw, err := os.ReadFile(minedFIMPath); err == nil {
		var fimItems []struct {
			Prefix	string	`json:"prefix"`
			Middle	string	`json:"middle"`
			Suffix	string	`json:"suffix"`
		}
		if jsonErr := json.Unmarshal(raw, &fimItems); jsonErr == nil {
			fimCount := 0
			for _, item := range fimItems {
				middle := strings.TrimSpace(item.Middle)
				if middle == "" {
					continue
				}
				prefix := strings.TrimSpace(item.Prefix)
				suffix := strings.TrimSpace(item.Suffix)
				var q string
				if suffix != "" {
					q = fmt.Sprintf("complete the code: %s <fill> %s", prefix, suffix)
				} else {
					q = fmt.Sprintf("complete the code: %s", prefix)
				}
				computerPairs = append(computerPairs, moe.TrainPair{Q: q, A: middle, Intent: "computer"})
				fimCount++
			}
			log.Printf("📚 Loaded %d FIM examples from mined_patches_fim.json", fimCount)
		} else {
			log.Printf("⚠️ Failed to parse mined_patches_fim.json: %v", jsonErr)
		}
	} else {
		log.Printf("⚠️ mined_patches_fim.json: %v", err)
	}

	if len(socialPairs) == 0 || len(computerPairs) == 0 {
		log.Fatalf("❌ Missing required datasets (social=%d, computer=%d). Aborting.", len(socialPairs), len(computerPairs))
	}
	log.Printf("📚 Total social+technical pairs: %d | Computer pairs: %d", len(socialPairs), len(computerPairs))

	tmpVocab := mainvocab.NewVocabulary()
	for _, tok := range []string{"__ques__", "__ans__", "__intent__", "social", "computer", ":"} {
		tmpVocab.AddToken(tok)
	}

	for _, tok := range []string{"{", "}", "(", ")", "=", ":", ";", ".", ",", "!", "?", "nil", "err", "if", "else", "for", "range", "return", "func", "type", "struct", "int", "string", "bool", "float64", "true", "false", "package", "import", "var", "const", "make", "new", "len", "cap", "append", "fmt", "Println", "Sprintf", "Errorf", "error", "interface{}"} {
		tmpVocab.AddToken(tok)
	}
	for _, pair := range append(socialPairs, computerPairs...) {
		for _, t := range cleanTokenize(pair.Q + " " + pair.A) {
			tmpVocab.AddToken(t)
		}
	}

	// ── 3. Load or create model ───────────────────────────────────────────────
	var intentModel *moe.IntentMoE
	socialModelPath := filepath.Join(projectRoot, "data/models/gob_models/moe_social_model.gob")
	if _, err := os.Stat(socialModelPath); err == nil {
		log.Printf("⬇️ Loading existing model from %s", socialModelPath)
		intentModel, _ = moe.LoadIntentMoEModelWithFallback(socialModelPath)
	}

	modelDim := cfg.ModelDim
	if modelDim <= 0 {
		modelDim = 512
	}
	baseExperts := cfg.NumExperts
	if baseExperts <= 0 {
		baseExperts = 8
	}
	if intentModel == nil {
		intentModel, _ = moe.NewHybridIntentMoE(
			tmpVocab.Size(), modelDim, baseExperts,
			modelDim, modelDim, tmpVocab.Size(), 2, nil,
		)
		intentModel.Decoder, _ = moe.NewRNNDecoder(modelDim, tmpVocab.Size(), modelDim, 8, 1, 0.0, baseExperts)
		intentModel.RepairArchitecture()
		intentModel.RebuildActiveLayers()
		for _, p := range intentModel.Parameters() {
			InitializeHeNormal(p)
		}
		intentModel.Rules = moe.NewRuleBook()
	} else {
		intentModel.RepairArchitecture()
	}

	if intentModel.SentenceVocab == nil {
		intentModel.SentenceVocab = tmpVocab
	} else {
		for k := range tmpVocab.WordToToken {
			intentModel.SentenceVocab.AddToken(k)
		}
	}
	tokenizer.InjectIntoVocab(intentModel.SentenceVocab.WordToToken, &intentModel.SentenceVocab.TokenToWord)
	intentModel.SentenceVocabSize = intentModel.SentenceVocab.Size()
	intentModel.Decoder.ResizeOutputLayer(intentModel.SentenceVocabSize)
	intentModel.ResizeEmbeddings(intentModel.SentenceVocabSize)
	moe.ActiveLayers = findMoELayers(intentModel)

	if useGPU {
		intentModel.ToGPU()
	}

	baseLR := cfg.LearningRate
	if baseLR <= 0 {
		baseLR = 0.0005
	}
	optimizer := &neuralnn.CoolingOptimizer{
		Base: neuralnn.NewOptimizer(intentModel.Parameters(), baseLR, 1.0),
	}

	supervisor := moe.NewSupervisor()
	supervisor.SeedSystemExperts(intentModel)

	layers := findMoELayers(intentModel)

	batchSize := cfg.BatchSize
	if batchSize <= 0 {
		batchSize = 32
	}
	maxSeqLen := cfg.MaxSeqLen
	if maxSeqLen <= 0 {
		maxSeqLen = 24
	}
	maxEpochs := cfg.Epochs
	if maxEpochs <= 0 {
		maxEpochs = 2000
	}
	labelSmoothing := cfg.LabelSmoothing
	if labelSmoothing <= 0 {
		labelSmoothing = 0.05
	}

	lossWeights := buildDefaultLossWeights(intentModel.SentenceVocab, &cfg)

	currentPhase := phaseForEpoch(0)

	// ── Phase 1 LR scheduler state (still used within Phase 1 to reduce on stagnation) ─
	var phase1BestLoss float32 = 1e9
	var phase1StagnantEpochs int
	var phase1LRFactor float32 = 1.0
	const phase1LRDecayPatience = 35
	const phase1LRImprovementThreshold = 0.005
	// Never let Phase 1 LR fall below 25% of its base value. The previous 1/32
	// floor (0.03125) let the LR collapse to ~0.000016 after 4–5 stagnation
	// halvings — far too small to make progress before Phase 1 even ended,
	// leaving the social experts unable to form sentences.
	const phase1LRFactorMin = 0.25

	phaseBestLoss := make(map[int]float32)
	phaseWorstLoss := make(map[int]float32)
	for p := 1; p <= 5; p++ {
		phaseBestLoss[p] = 1e9
		phaseWorstLoss[p] = 0
	}

	phaseCfg := cfg.Phases[strconv.Itoa(currentPhase)]
	if phaseCfg != nil {
		applyPhaseFreeze(layers, phaseCfg.FreezeExpertsStart, phaseCfg.FreezeExpertsEnd)
	}

	for epoch := 0; epoch < maxEpochs; epoch++ {
		epochStart := time.Now()
		// ── Select dataset & set LR from config ────────────────────────────────
		var trainPairs []moe.TrainPair
		var phaseLR float32

		phaseCfg := cfg.Phases[strconv.Itoa(currentPhase)]
		if phaseCfg == nil {
			log.Fatalf("❌ Missing config for phase %d", currentPhase)
		}

		switch phaseCfg.Dataset {
		case "social":
			trainPairs = socialPairs
		case "computer":
			trainPairs = computerPairs
		case "all":
			trainPairs = make([]moe.TrainPair, 0, len(socialPairs)+len(computerPairs))
			trainPairs = append(trainPairs, socialPairs...)
			trainPairs = append(trainPairs, computerPairs...)
		default:
			trainPairs = socialPairs
		}

		phaseLR = phaseCfg.LearningRate
		for _, layer := range layers {
			atomic.StoreInt32(&layer.ResetCount, 0)
			layer.LoadBalancingWeight = phaseCfg.LoadBalancingWeight
			layer.RouterTemperature = phaseCfg.RouterTemperature
			layer.ExpertDropoutRate = phaseCfg.ExpertDropout
			if cfg.CapacityFactor > 0 {
				layer.CapacityFactor = cfg.CapacityFactor
			} else {
				layer.CapacityFactor = 2.0
			}

			if phaseCfg.ForceSingleExpertEpochs > 0 && epoch < phaseCfg.ForceSingleExpertEpochs {
				layer.ForceSingleExpert = true
			} else {
				layer.ForceSingleExpert = false
			}
		}
		optimizer.SetLearningRate(phaseLR)

		rand.Shuffle(len(trainPairs), func(i, j int) { trainPairs[i], trainPairs[j] = trainPairs[j], trainPairs[i] })

		// ── Inner batch loop ───────────────────────────────────────────────────
		var totalLoss float32
		batches := 0

		phaseBatchSize := phaseCfg.BatchSize
		if phaseBatchSize <= 0 {
			phaseBatchSize = batchSize
		}
		phaseMaxSeqLen := phaseCfg.MaxSeqLen
		if phaseMaxSeqLen <= 0 {
			phaseMaxSeqLen = maxSeqLen
		}

		for i := 0; i < len(trainPairs); i += phaseBatchSize {
			end := i + phaseBatchSize
			if end > len(trainPairs) {
				end = len(trainPairs)
			}
			batch := trainPairs[i:end]
			currentBatchSize := len(batch)

			optimizer.ZeroGrad()

			inputData := make([]float32, currentBatchSize*phaseMaxSeqLen)
			targetData := make([]float32, currentBatchSize*phaseMaxSeqLen)

			padID := intentModel.SentenceVocab.PaddingTokenID

			for bIdx, pair := range batch {
				qText := "__intent__ " + pair.Intent + " : __ques__ " + pair.Q
				qToks := cleanTokenize(qText)
				for t := 0; t < phaseMaxSeqLen && t < len(qToks); t++ {
					id := intentModel.SentenceVocab.GetTokenID(qToks[t])
					if id < 0 {
						id = padID
					}
					inputData[bIdx*phaseMaxSeqLen+t] = float32(id)
				}

				aToks := cleanTokenize(pair.A)
				eosID := intentModel.SentenceVocab.EosID
				if eosID < 0 {
					eosID = intentModel.SentenceVocab.GetTokenID("<EOS>")
				}
				for t := 0; t < phaseMaxSeqLen && t < len(aToks); t++ {
					id := intentModel.SentenceVocab.GetTokenID(aToks[t])
					if id < 0 {
						id = padID
					}
					targetData[bIdx*phaseMaxSeqLen+t] = float32(id)
				}
				if len(aToks) < phaseMaxSeqLen {
					targetData[bIdx*phaseMaxSeqLen+len(aToks)] = float32(eosID)
				}
			}

			inputTensor := tensor.NewTensor([]int{currentBatchSize, phaseMaxSeqLen}, inputData, false)
			targetTensor := tensor.NewTensor([]int{currentBatchSize, phaseMaxSeqLen}, targetData, false)

			for _, layer := range layers {
				layer.CurrentPhase = currentPhase
			}

			logits, _, err := intentModel.Forward(0.1, inputTensor, targetTensor)
			if err != nil {
				log.Printf("⚠️ Forward error (batch %d): %v", i/phaseBatchSize, err)
				intentModel.ClearState()
				continue
			}

			// ── Loss computation — mirrors chat.go approach ────────────────────
			var batchLoss float32
			var grads []*tensor.Tensor

			if len(logits) == 1 && len(logits[0].Shape) == 3 {

				targetSeqLen := phaseMaxSeqLen - 1
				targets := make([]int, currentBatchSize*targetSeqLen)
				var eosPenalty float32
				vocabSize := logits[0].Shape[2]
				eosID := intentModel.SentenceVocab.EosID
				if eosID < 0 {
					eosID = intentModel.SentenceVocab.GetTokenID("<EOS>")
				}

				for b := 0; b < currentBatchSize; b++ {
					eosExpectedAt := -1
					for t := 0; t < targetSeqLen; t++ {
						tID := int(targetData[b*phaseMaxSeqLen+t+1])
						targets[b*targetSeqLen+t] = tID
						if eosExpectedAt == -1 && tID == eosID {
							eosExpectedAt = t
						}
					}
					if eosExpectedAt != -1 {
						offset := (b*targetSeqLen + eosExpectedAt) * vocabSize
						maxLogit := float32(-1e9)
						predID := -1
						for v := 0; v < vocabSize; v++ {
							val := logits[0].Data[offset+v]
							if val > maxLogit {
								maxLogit = val
								predID = v
							}
						}
						if predID != eosID && predID != padID {
							eosPenalty += 0.15
						}
					}
				}
				loss, grad := WeightedCrossEntropy(logits[0].ToCPU(), targets, lossWeights, labelSmoothing, 0.005)
				if grad == nil {
					grad = tensor.NewTensor(logits[0].Shape, make([]float32, len(logits[0].Data)), false)
				}

				// DYNAMIC NORMALIZATION
				var sumWeights float32
				validTokens := 0
				for _, tID := range targets {
					if tID >= 0 && tID < len(lossWeights) && tID != padID {
						sumWeights += lossWeights[tID]
						validTokens++
					}
				}
				avgWeight := float32(1.0)
				if validTokens > 0 && sumWeights > 0 {
					avgWeight = sumWeights / float32(validTokens)
				}

				penaltyFactor := float32(1.0) + (eosPenalty / float32(currentBatchSize))
				batchLoss = (loss * penaltyFactor) / avgWeight

				scale := penaltyFactor / avgWeight
				if scale != 1.0 {
					for i := range grad.Data {
						grad.Data[i] *= scale
					}
				}
				grads = []*tensor.Tensor{grad}
			} else {

				grads = make([]*tensor.Tensor, len(logits))
				var stepTotal float32
				for t, logit := range logits {
					targets := make([]int, currentBatchSize)
					for b := 0; b < currentBatchSize; b++ {
						idx := b*phaseMaxSeqLen + t + 1
						if idx < len(targetData) {
							targets[b] = int(targetData[idx])
						} else {
							targets[b] = padID
						}
					}

					eosID := intentModel.SentenceVocab.EosID
					if eosID < 0 {
						eosID = intentModel.SentenceVocab.GetTokenID("<EOS>")
					}
					var eosPenalty float32
					vocabSize := logit.Shape[1]
					for b := 0; b < currentBatchSize; b++ {
						if targets[b] == eosID {
							offset := b * vocabSize
							maxLogit := float32(-1e9)
							predID := -1
							for v := 0; v < vocabSize; v++ {
								val := logit.Data[offset+v]
								if val > maxLogit {
									maxLogit = val
									predID = v
								}
							}
							if predID != eosID && predID != padID {
								eosPenalty += 0.15
							}
						}
					}
					l, g := WeightedCrossEntropy(logit.ToCPU(), targets, lossWeights, labelSmoothing, 0.005)
					if g == nil {
						g = tensor.NewTensor(logit.Shape, make([]float32, len(logit.Data)), false)
					}

					// DYNAMIC NORMALIZATION
					var sumWeights float32
					validTokens := 0
					for _, tID := range targets {
						if tID >= 0 && tID < len(lossWeights) && tID != padID {
							sumWeights += lossWeights[tID]
							validTokens++
						}
					}
					avgWeight := float32(1.0)
					if validTokens > 0 && sumWeights > 0 {
						avgWeight = sumWeights / float32(validTokens)
					}

					penaltyFactor := float32(1.0) + (eosPenalty / float32(currentBatchSize))
					stepTotal += (l * penaltyFactor) / avgWeight

					scale := penaltyFactor / avgWeight
					if scale != 1.0 {
						for i := range g.Data {
							g.Data[i] *= scale
						}
					}
					grads[t] = g
				}
				div := float32(len(logits))
				batchLoss = stepTotal / div
				for t := range grads {
					for i := range grads[t].Data {
						grads[t].Data[i] /= div
					}
				}
			}

			totalLoss += batchLoss
			if err := intentModel.Backward(grads...); err != nil {
				log.Printf("⚠️ Backward error: %v", err)
			} else {
				optimizer.ClipGradients()
				optimizer.Step()
			}
			intentModel.ClearState()
			batches++
		}

		avgLoss := float32(0.0)
		if batches > 0 {
			avgLoss = totalLoss / float32(batches)
		}
		epochDuration := time.Since(epochStart).Seconds()

		if avgLoss < phaseBestLoss[currentPhase] {
			phaseBestLoss[currentPhase] = avgLoss
		}
		if avgLoss > phaseWorstLoss[currentPhase] {
			phaseWorstLoss[currentPhase] = avgLoss
		}

		// ── Epoch log ─────────────────────────────────────────────────────────
		var activeExps []string
		if len(layers) > 0 {
			for i := 0; i < len(layers[0].ExpertFrozen); i++ {
				if !layers[0].ExpertFrozen[i] {
					activeExps = append(activeExps, fmt.Sprintf("%d", i))
				}
			}
		}

		effectiveLR := phaseLR
		if currentPhase == 1 {
			effectiveLR = phaseLR * phase1LRFactor
		}

		epochInPhase := epoch%epochsPerPhase + 1
		log.Printf("Phase %d [%d/%d] | Epoch %d | Loss: %.4f | LR: %.6f | Active: [%s] | EpochTime: %.1fs",
			currentPhase, epochInPhase, epochsPerPhase, epoch, avgLoss, effectiveLR,
			strings.Join(activeExps, ","), epochDuration)

		if currentPhase == 1 {
			if avgLoss < phase1BestLoss-phase1LRImprovementThreshold {
				phase1BestLoss = avgLoss
				phase1StagnantEpochs = 0
			} else {
				phase1StagnantEpochs++
			}
			if phase1StagnantEpochs >= phase1LRDecayPatience && phase1LRFactor > phase1LRFactorMin {
				phase1LRFactor *= 0.5
				if phase1LRFactor < phase1LRFactorMin {
					phase1LRFactor = phase1LRFactorMin
				}
				phase1StagnantEpochs = 0
				log.Printf("🔻 Phase 1 stagnant %d epochs → LR factor %.4f (effective %.6f)",
					phase1LRDecayPatience, phase1LRFactor, phaseCfg.LearningRate*phase1LRFactor)
			}
			optimizer.SetLearningRate(phaseCfg.LearningRate * phase1LRFactor)
		}

		isPhaseEnd := (epoch+1)%epochsPerPhase == 0
		nextPhase := phaseForEpoch(epoch + 1)

		if isPhaseEnd {

			runEndOfPhaseProbe(intentModel, layers, currentPhase, epoch, avgLoss,
				phaseBestLoss[currentPhase], phaseWorstLoss[currentPhase], len(activeExps))

			if nextPhase != currentPhase && nextPhase <= 5 {
				log.Printf("")
				log.Printf("⏩ Advancing: Phase %d → Phase %d (%s)", currentPhase, nextPhase, phaseNames[nextPhase])
				currentPhase = nextPhase
				nextPhaseCfg := cfg.Phases[strconv.Itoa(currentPhase)]
				if nextPhaseCfg != nil {
					applyPhaseFreeze(layers, nextPhaseCfg.FreezeExpertsStart, nextPhaseCfg.FreezeExpertsEnd)

					phase1LRFactor = 1.0
					phase1StagnantEpochs = 0
					optimizer.SetLearningRate(nextPhaseCfg.LearningRate)
				}
				moe.SaveIntentMoEModelToGOB(intentModel, socialModelPath)
			}
		}

		if epoch > 0 && epoch%10 == 0 {
			moe.SaveIntentMoEModelToGOB(intentModel, socialModelPath)
			log.Printf("💾 Checkpoint saved (epoch %d)", epoch)
		}
	}
}

// runEndOfPhaseProbe runs the diagnostic probe for the completed phase and logs
// a structured summary block with PASS/FAIL result.
func runEndOfPhaseProbe(intentModel *moe.IntentMoE, layers []*moe.MoELayer,
	phase, epoch int, finalLoss, bestLoss, worstLoss float32, activeExpertCount int) {

	banner := strings.Repeat("═", 65)
	log.Printf("%s", banner)
	log.Printf("📋 PHASE %d COMPLETE — %s", phase, phaseNames[phase])
	log.Printf("   Epochs: %d–%d  |  Active Experts: %d",
		(phase-1)*epochsPerPhase, epoch, activeExpertCount)
	log.Printf("   Loss → Best: %.4f  Worst: %.4f  Final: %.4f", bestLoss, worstLoss, finalLoss)

	var probeResult string
	var passed bool

	switch phase {
	case 1:

		gen, _, _ := StrictGenerateLowTemp(intentModel, "__intent__ social : __ques__ how are you", 20, 1.0, false, epoch)
		words := strings.Fields(strings.ToLower(gen))
		socialTokenSet := map[string]bool{"hi": true, "hello": true, "i": true, "you": true, "am": true, "great": true, "good": true, "fine": true, "doing": true, "well": true}
		hasSocial := false
		unique := make(map[string]struct{})
		for _, w := range words {
			unique[w] = struct{}{}
			if socialTokenSet[strings.Trim(w, ".,!?")] {
				hasSocial = true
			}
		}
		ttr := float32(0)
		if len(words) > 0 {
			ttr = float32(len(unique)) / float32(len(words))
		}
		passed = hasSocial && ttr >= 0.4 && len(words) >= 3
		probeResult = fmt.Sprintf("Social response: '%s'\n   TTR=%.2f, social_tokens=%v", gen, ttr, hasSocial)

	case 2:

		goKeywords := map[string]bool{"func": true, "return": true, "if": true, "var": true, "err": true,
			"nil":	true, "int": true, "string": true, "error": true, "for": true, "range": true, "type": true}
		gen, _, _ := StrictGenerateLowTemp(intentModel,
			"__intent__ computer : __ques__ write a go function", 25, 1.0, false, epoch)
		genLower := strings.ToLower(gen)
		foundKeyword := ""
		for kw := range goKeywords {
			if strings.Contains(genLower, kw) {
				foundKeyword = kw
				break
			}
		}
		passed = foundKeyword != ""
		probeResult = fmt.Sprintf("Code response: '%s'\n   First Go keyword found: %q", gen, foundKeyword)

	case 3:

		socialActive := 0
		codeActive := 0
		if len(layers) > 0 {
			for i, frozen := range layers[0].ExpertFrozen {
				if !frozen {
					if i < 8 {
						socialActive++
					} else {
						codeActive++
					}
				}
			}
		}
		passed = socialActive >= 1 && codeActive >= 1
		probeResult = fmt.Sprintf("Routing diversity: social experts active=%d, code experts active=%d", socialActive, codeActive)

	case 4:

		maxLoad := 0
		totalLoad := 0
		for _, layer := range layers {
			if len(layer.AccumulatedUtilization) == 0 {
				continue
			}
			for _, u := range layer.AccumulatedUtilization {
				if u > maxLoad {
					maxLoad = u
				}
				totalLoad += u
			}
		}
		maxFraction := float32(0)
		if totalLoad > 0 {
			maxFraction = float32(maxLoad) / float32(totalLoad)
		}
		passed = maxFraction <= 0.5
		probeResult = fmt.Sprintf("Load balance: max expert fraction=%.1f%%", maxFraction*100)

	case 5:

		socialGen, _, _ := StrictGenerateLowTemp(intentModel,
			"__intent__ social : __ques__ tell me about yourself", 20, 1.0, false, epoch)
		codeGen, _, _ := StrictGenerateLowTemp(intentModel,
			"__intent__ computer : __ques__ how do you handle errors in go", 25, 1.0, false, epoch)

		socialWords := strings.Fields(socialGen)
		socialPassed := len(socialWords) >= 3 && svcIsCoherent(socialGen)

		goKeywords := map[string]bool{"err": true, "error": true, "return": true, "nil": true, "if": true, "func": true}
		codeGenLower := strings.ToLower(codeGen)
		codeHasKeyword := false
		for kw := range goKeywords {
			if strings.Contains(codeGenLower, kw) {
				codeHasKeyword = true
				break
			}
		}
		passed = socialPassed && codeHasKeyword
		probeResult = fmt.Sprintf(
			"Social: '%s' (coherent=%v)\n   Code: '%s' (has_keyword=%v)",
			socialGen, socialPassed, codeGen, codeHasKeyword)
	}

	resultIcon := "✅ PASS"
	if !passed {
		resultIcon = "❌ FAIL"
	}
	log.Printf("   🧪 Phase %d Probe: %s", phase, probeResult)
	log.Printf("   %s", resultIcon)
	log.Printf("%s", banner)
}

// buildDefaultLossWeights builds a flat weight vector for WeightedCrossEntropy.
// High-frequency stop-words are down-weighted; BOS/EOS/terminal punctuation are boosted.
// For code-syntax tokens delimiters and structural Go keywords get higher weight.
func buildDefaultLossWeights(vocab *mainvocab.Vocabulary, cfg *orchestrator.TrainingConfig) []float32 {
	if vocab == nil {
		return nil
	}
	weights := make([]float32, vocab.Size())
	for i := range weights {
		weights[i] = 1.0
	}

	if cfg != nil && cfg.TokenWeights != nil {
		for token, weight := range cfg.TokenWeights {
			id := vocab.GetTokenID(token)
			if id >= 0 && id < len(weights) {
				weights[id] = float32(weight)
			}
		}
	} else {
		suppressed := []string{"it", "is", "a", "the", "i"}
		for _, w := range suppressed {
			id := vocab.GetTokenID(w)
			if id >= 0 && id < len(weights) {
				weights[id] = 0.3
			}
		}
		boosted := []string{".", "!", "?", "<BOS>", "<EOS>", "__ans__"}
		for _, w := range boosted {
			id := vocab.GetTokenID(w)
			if id >= 0 && id < len(weights) {
				weights[id] = 2.0
			}
		}
	}

	codeSyntaxBoosted := []string{"{", "}", "(", ")", "=", ":", ";", "if", "else", "for", "range", "func", "return", "package", "type", "struct", "err", "nil", ":= ", "==", "!="}
	for _, w := range codeSyntaxBoosted {
		id := vocab.GetTokenID(w)
		if id >= 0 && id < len(weights) {
			weights[id] = 3.0
		}
	}
	return weights
}

// extractGoSymbols extracts Go code symbols (keywords, identifiers, operators)
// from a generated string. Returns a deduplicated list of symbols found.
func extractGoSymbols(s string) []string {
	if s == "" {
		return nil
	}
	goKeywords := map[string]bool{
		"func":	true, "if": true, "for": true, "range": true, "return": true,
		"package":	true, "import": true, "type": true, "struct": true,
		"var":	true, "const": true, "make": true, "new": true, "len": true,
		"cap":	true, "append": true, "defer": true, "go": true, "select": true,
		"switch":	true, "case": true, "break": true, "continue": true,
		"fallthrough":	true, "else": true, "map": true, "chan": true,
		"interface":	true, "error": true, "nil": true, "true": true, "false": true,
	}
	goTypes := map[string]bool{
		"int":	true, "string": true, "bool": true, "float64": true,
		"float32":	true, "int64": true, "int32": true, "byte": true,
		"rune":	true, "uint": true, "uint64": true, "uint32": true,
	}
	operators := map[string]bool{
		"=":	true, ":=": true, "==": true, "!=": true, "<": true, ">": true,
		"+":	true, "-": true, "*": true, "/": true, "&": true, "|": true,
		"^":	true, "<<": true, ">>": true,
	}

	seen := make(map[string]bool)
	var symbols []string

	words := strings.Fields(s)
	for _, w := range words {

		w = strings.TrimRight(w, ".,;:(){}[]\"'`")
		if w == "" {
			continue
		}

		if goKeywords[w] || goTypes[w] || operators[w] {
			if !seen[w] {
				seen[w] = true
				symbols = append(symbols, w)
			}
			continue
		}

		if len(w) > 1 && ((w[0] >= 'a' && w[0] <= 'z') || (w[0] >= 'A' && w[0] <= 'Z') || w[0] == '_') {
			isAlpha := true
			for _, c := range w[1:] {
				if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
					isAlpha = false
					break
				}
			}
			if isAlpha && !seen[w] {
				seen[w] = true
				symbols = append(symbols, w)
			}
		}

		if strings.Contains(w, ".") {
			parts := strings.Split(w, ".")
			for _, p := range parts {
				if p != "" && !seen[p] {
					seen[p] = true
					symbols = append(symbols, p)
				}
			}
		}
	}
	return symbols
}

// codePassCondition evaluates a generated response for code-fix datasets.
// It returns true if:
//  1. The response is a non-empty string.
//  2. Balanced braces { } and parentheses ( ) — same number of opening and closing.
//  3. Contains at least one Go structural keyword (func, if, for, range, return, package, type, struct, var, const, import, make, append, import, defer, go, select, switch, case, break, continue, fallthrough, else).
//
// This replaces the natural-language svcIsCoherent check when training on code datasets.
func codePassCondition(response string) bool {
	response = strings.TrimSpace(response)
	if response == "" {
		return false
	}
	openBrace := strings.Count(response, "{")
	closeBrace := strings.Count(response, "}")
	if openBrace != closeBrace {
		return false
	}
	openParen := strings.Count(response, "(")
	closeParen := strings.Count(response, ")")
	if openParen != closeParen {
		return false
	}
	goKeywords := []string{"func ", "if ", "for ", "range ", "return ", "package ", "type ", "struct ", "var ", "const ", "import ", "make(", "append(", "defer ", "go ", "select {", "switch ", "case ", "break ", "continue ", "fallthrough ", "else ", "err ", "nil", "error", "interface", "map[", "[]", "chan ", "wg.", "http.", "fmt.", "json.", "io.", "os.", "ioutil."}
	lower := strings.ToLower(response)
	for _, kw := range goKeywords {
		if strings.Contains(lower, kw) {
			return true
		}
	}
	return false
}

type ollamaReq struct {
	Model	string	`json:"model"`
	Prompt	string	`json:"prompt"`
	Stream	bool	`json:"stream"`
	Format	string	`json:"format,omitempty"`
}

type ollamaResp struct {
	Response string `json:"response"`
}

// GradeAndCorrectWithTeacher uses a local Ollama model to evaluate a training generation.
// If the generation is poor, it returns a corrected sentence.
func GradeAndCorrectWithTeacher(query, studentResponse string) (passed bool, reason string, correction string) {
	prompt := fmt.Sprintf(`You are an expert AI teacher evaluating a student model's output.
The student was given the query: "%s"
The student responded with: "%s"

Task 1: Is the student's response coherent, natural, and grammatically flawless? (YES or NO)
Task 2: If NO, provide a one-sentence correction of what they should have said. If YES, briefly explain why it's good.

CRITICAL RULES FOR CORRECTION:
1. Provide ONLY the exact literal string the student should say.
2. DO NOT include placeholders like [name]. Use generic names like "John".
3. DO NOT include parentheses or alternative options (e.g., no "or you could say...").
4. DO NOT include quotes around the correction.
5. NO meta-commentary. Just the exact, final sentence.

Format your output exactly like this:
GRADE: YES (or NO)
REASON: <your reason>
CORRECTION: <your exact literal correction if NO, otherwise leave blank>
`, query, studentResponse)

	reqBody, _ := json.Marshal(ollamaReq{
		Model:	"qwen2.5:3b",
		Prompt:	prompt,
		Stream:	false,
	})

	client := &http.Client{Timeout: 120 * time.Second}
	resp, err := client.Post("http://127.0.0.1:11434/api/generate", "application/json", bytes.NewBuffer(reqBody))
	if err != nil {
		return true, fmt.Sprintf("Ollama connection failed: %v (defaulting to PASS)", err), ""
	}
	defer resp.Body.Close()

	var oResp ollamaResp
	if err := json.NewDecoder(resp.Body).Decode(&oResp); err != nil {
		return true, "Ollama JSON parse error", ""
	}

	lines := strings.Split(oResp.Response, "\n")
	passed = false
	reason = "Unclear"
	correction = ""

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "GRADE:") {
			gradeStr := strings.ToUpper(strings.TrimSpace(strings.TrimPrefix(line, "GRADE:")))
			if strings.Contains(gradeStr, "YES") {
				passed = true
			}
		} else if strings.HasPrefix(line, "REASON:") {
			reason = strings.TrimSpace(strings.TrimPrefix(line, "REASON:"))
		} else if strings.HasPrefix(line, "CORRECTION:") {
			correction = strings.TrimSpace(strings.TrimPrefix(line, "CORRECTION:"))
			correction = strings.Trim(correction, "\"'")
		}
	}

	return passed, reason, correction
}

// TeacherAuditAndPatch is the 30-epoch comprehensive Teacher review.
// It probes the model on canonical questions, packages all available metrics
// and config into a single prompt, asks Qwen to diagnose problems and output
// a JSON patch for social_train.json, then writes the patch back to disk.
// Returns a short human-readable summary string for the training log.
func TeacherAuditAndPatch(ctx TeacherAuditContext, configPath string) string {
	// ---- Build probe results section ----
	var probeLines strings.Builder
	for q, r := range ctx.Probes {
		probeLines.WriteString(fmt.Sprintf("  Q: %q\n  A: %q\n\n", q, r))
	}

	prompt := fmt.Sprintf(`You are an expert AI Training Supervisor performing a 30-epoch audit on a Mixture-of-Experts (MoE) language model called Gollemer.

=== CURRENT METRICS (Epoch %d) ===
  Average Loss    : %.4f
  Average Sim     : %.4f
  Grammar Score   : %.4f
  Training Rows   : %d

=== EPOCH HISTORY ===
%s

=== CURRENT CONFIG (social_train.json) ===
%s

=== MODEL OUTPUT PROBES ===
(These are the model's actual responses to canonical test questions right now.)
%s

=== YOUR TASK ===
1. Carefully analyze the metrics, historical trends, config, and model outputs above.
2. Diagnose what is going wrong (word salad, repetition, wrong intent, poor grammar, loss plateau, etc.). If the model's output in the probes is consistently a single word like "it", "is", or word salad, IT IS IN SEVERE MODE COLLAPSE!
3. To FIX mode collapse, YOU MUST RAISE the learning_rate (e.g., from 0.00005 to 0.0001 or 0.0002) to break out of the local minimum OR INCREASE router_temperature OR router_noise!
4. Output a JSON object containing ONLY the config keys you want to change and their new values.
   - Only include keys that already exist in the current config shown above.
   - If training looks perfectly healthy and the model outputs are coherent full sentences, output exactly: {}
   - Do NOT output any explanation outside the JSON.
   - Example: {"learning_rate": 0.00001, "router_temperature": 1.5, "router_noise": 0.3}

Output ONLY the raw JSON object. Nothing else.`,
		ctx.Epoch,
		ctx.AvgLoss,
		ctx.AvgSim,
		ctx.GrammarScore,
		ctx.TrainingRows,
		ctx.HistorySummary,
		ctx.ConfigJSON,
		probeLines.String(),
	)

	reqBody, _ := json.Marshal(ollamaReq{
		Model:	"qwen2.5:3b",
		Prompt:	prompt,
		Stream:	false,
		Format:	"json",
	})

	client := &http.Client{Timeout: 120 * time.Second}
	resp, err := client.Post("http://127.0.0.1:11434/api/generate", "application/json", bytes.NewBuffer(reqBody))
	if err != nil {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit] Ollama offline — skipping patch (epoch %d)", ctx.Epoch)
	}
	defer resp.Body.Close()

	var oResp ollamaResp
	if err := json.NewDecoder(resp.Body).Decode(&oResp); err != nil {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit] JSON decode error — skipping patch (epoch %d)", ctx.Epoch)
	}

	text := strings.TrimSpace(oResp.Response)
	if text == "" || text == "{}" {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Teacher sees healthy training. No config changes.", ctx.Epoch)
	}

	// Parse the teacher's recommended patch
	var patch map[string]interface{}
	if err := json.Unmarshal([]byte(text), &patch); err != nil {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Teacher output invalid JSON (%q) — skipping", ctx.Epoch, text)
	}
	if len(patch) == 0 {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Teacher sees healthy training. No config changes.", ctx.Epoch)
	}

	// Merge patch into current config and write back
	var currentCfg map[string]interface{}
	if cfgData, err := os.ReadFile(configPath); err == nil {
		_ = json.Unmarshal(cfgData, &currentCfg)
	}
	if currentCfg == nil {
		currentCfg = make(map[string]interface{})
	}

	var changedKeys []string
	for k, v := range patch {

		if _, exists := currentCfg[k]; exists {
			currentCfg[k] = v
			changedKeys = append(changedKeys, fmt.Sprintf("%s=%v", k, v))
		}
	}

	if len(changedKeys) == 0 {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Teacher suggested unknown keys — no patch applied", ctx.Epoch)
	}

	newCfgData, err := json.MarshalIndent(currentCfg, "", "  ")
	if err != nil {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Marshal error — patch not saved", ctx.Epoch)
	}
	if err := os.WriteFile(configPath, newCfgData, 0644); err != nil {
		return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] Write error — patch not saved: %v", ctx.Epoch, err)
	}

	return fmt.Sprintf("👨‍🏫 [TeacherAudit Epoch %d] ✅ Patched config: %s", ctx.Epoch, strings.Join(changedKeys, ", "))
}

// Next advances the scheduler and returns the new temperature and number of active layers.
func (s *ThawScheduler) Next() (float32, int) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.Step < s.MaxSteps {
		s.Step++
	}

	// Exponential decay: temp = start * e^(-rate * step)
	const rate = 0.001
	temp := s.StartTemp * float32(math.Exp(-rate*float64(s.Step)))
	if temp < s.MinTemp {
		temp = s.MinTemp
	}

	active := 0
	for _, t := range s.Thresholds {
		if temp <= t {
			active++
		}
	}

	if active == 0 {
		active = 1
	}

	return temp, active
}

type TrainingLogger struct {
	File	*os.File
	Writer	*csv.Writer
	Path	string
}

// NewTrainingLogger creates (or appends to) a CSV log file.
// If the file already exists its header is preserved; new rows are appended.
func NewTrainingLogger(filename string) (*TrainingLogger, error) {

	if err := os.MkdirAll(filepath.Dir(filename), 0o755); err != nil {
		return nil, fmt.Errorf("failed to create log directory: %w", err)
	}

	needsHeader := false
	if _, err := os.Stat(filename); os.IsNotExist(err) {
		needsHeader = true
	}

	f, err := os.OpenFile(filename, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, fmt.Errorf("failed to open training log: %w", err)
	}

	w := csv.NewWriter(f)
	if needsHeader {
		header := []string{
			"epoch", "avg_loss", "lb_loss", "perplexity", "learning_rate",
			"e0_util", "e1_util", "e2_util", "e3_util",
			"e4_util", "e5_util", "e6_util", "e7_util",
			"frozen_experts",
		}
		if err := w.Write(header); err != nil {
			return nil, fmt.Errorf("failed to write CSV header: %w", err)
		}
		w.Flush()
	}

	return &TrainingLogger{File: f, Writer: w, Path: filename}, nil
}

// LogEpoch appends one row of metrics to the CSV.
//   - utils: per-expert utilisation fractions (0-1), one per expert
//   - frozenExperts: IDs frozen by ThawScheduler this epoch
func (l *TrainingLogger) LogEpoch(epoch int, avgLoss, lbLoss, perplexity, lr float64, utils []float64, frozenExperts []int) {
	row := []string{
		strconv.Itoa(epoch),
		fmt.Sprintf("%.4f", avgLoss),
		fmt.Sprintf("%.4f", lbLoss),
		fmt.Sprintf("%.2f", perplexity),
		fmt.Sprintf("%.8f", lr),
	}

	for i := 0; i < 8; i++ {
		if i < len(utils) {
			row = append(row, fmt.Sprintf("%.4f", utils[i]))
		} else {
			row = append(row, "0.0000")
		}
	}

	frozenStr := ""
	for i, id := range frozenExperts {
		if i > 0 {
			frozenStr += ","
		}
		frozenStr += strconv.Itoa(id)
	}
	row = append(row, frozenStr)

	_ = l.Writer.Write(row)
	l.Writer.Flush()
}

// LogStep appends per-batch metrics to the CSV.
func (l *TrainingLogger) LogStep(m TrainingMetric) {

	coolingBit := 0
	if m.IsCooling {
		coolingBit = 1
	}

	_ = l.Writer.Write([]string{
		fmt.Sprintf("%d", m.Step),
		fmt.Sprintf("%.4f", m.Loss),
		fmt.Sprintf("%.4f", m.LearningRate),
		fmt.Sprintf("%d", coolingBit),
	})
	l.Writer.Flush()
}

// Close flushes and closes the underlying file.
func (l *TrainingLogger) Close() {
	l.Writer.Flush()
	_ = l.File.Close()
}

type ExpertCsvStat struct {
	ID	int
	AvgUtil	float64
	Growth	float64	// Δ utilisation over the last 10 epochs
}

// GenerateProgressReport reads logs/training_log.csv and prints a concise analysis.
func GenerateProgressReport(logPath string) {
	f, err := os.Open(logPath)
	if err != nil {
		fmt.Printf("⚠️  Could not open log file %s: %v\n", logPath, err)
		return
	}
	defer f.Close()

	r := csv.NewReader(f)
	records, err := r.ReadAll()
	if err != nil || len(records) < 2 {
		fmt.Println("⚠️  Not enough data in log file yet.")
		return
	}

	data := records[1:]
	numRows := len(data)

	// Columns: epoch, avg_loss, lb_loss, perplexity, lr, e0..e7, frozen
	const firstUtilCol = 5	// index of e0_util in each row
	const numExperts = 8

	utilSum := make([]float64, numExperts)
	utilRecent := make([]float64, numExperts)
	utilEarly := make([]float64, numExperts)
	recentWindow := 10
	earlyWindow := 10

	for rowIdx, row := range data {
		for e := 0; e < numExperts; e++ {
			col := firstUtilCol + e
			if col >= len(row) {
				continue
			}
			val, _ := strconv.ParseFloat(row[col], 64)
			utilSum[e] += val

			if numRows <= recentWindow || rowIdx >= numRows-recentWindow {
				utilRecent[e] += val
			}
			if rowIdx < earlyWindow {
				utilEarly[e] += val
			}
		}
	}

	recentCount := float64(min(recentWindow, numRows))
	earlyCount := float64(min(earlyWindow, numRows))

	stats := make([]ExpertCsvStat, numExperts)
	for e := 0; e < numExperts; e++ {
		stats[e].ID = e
		stats[e].AvgUtil = utilSum[e] / float64(numRows)
		if earlyCount > 0 && recentCount > 0 {
			stats[e].Growth = (utilRecent[e] / recentCount) - (utilEarly[e] / earlyCount)
		}
	}

	byCrowth := make([]ExpertCsvStat, numExperts)
	copy(byCrowth, stats)
	sort.Slice(byCrowth, func(i, j int) bool {
		return byCrowth[i].Growth > byCrowth[j].Growth
	})

	mvp := byCrowth[0]
	slacker := byCrowth[numExperts-1]

	byUtil := make([]ExpertCsvStat, numExperts)
	copy(byUtil, stats)
	sort.Slice(byUtil, func(i, j int) bool {
		return byUtil[i].AvgUtil > byUtil[j].AvgUtil
	})

	finalPPLStr := ""
	if len(data[numRows-1]) > 3 {
		finalPPLStr = data[numRows-1][3]
	}
	finalPPL, _ := strconv.ParseFloat(finalPPLStr, 64)

	fmt.Println("\n🏆 ─── Gollemer Expert MVP Report ───────────────────────")
	fmt.Printf("   📈 Epochs logged    : %d\n", numRows)
	fmt.Printf("   📉 Final Perplexity : %.2f\n", finalPPL)
	fmt.Println()
	fmt.Println("   Expert  │  Avg Util  │  Growth (last 10 vs first 10)")
	fmt.Println("   ────────┼────────────┼──────────────────────────────")
	for _, s := range byUtil {
		arrow := "→"
		if s.Growth > 0.01 {
			arrow = "↑"
		} else if s.Growth < -0.01 {
			arrow = "↓"
		}
		fmt.Printf("     E%-2d   │   %5.1f%%   │ %s  %.2f%%\n",
			s.ID, s.AvgUtil*100, arrow, s.Growth*100)
	}
	fmt.Println()
	fmt.Printf("   ✅ Current MVP    : Expert %d  (Growth +%.2f%%)\n", mvp.ID, mvp.Growth*100)
	fmt.Printf("   ⚠️  Action Needed : Expert %d  (Growth %.2f%% — consider Reset)\n", slacker.ID, slacker.Growth*100)
	fmt.Println("   ──────────────────────────────────────────────────────")
}

// SavePeriodicCheckpoint saves the model every N epochs to a dated file.
// It does NOT overwrite the "best" checkpoint — it is an insurance snapshot.
func SavePeriodicCheckpoint(model *moe.IntentMoE, checkpointDir string, epoch int, every int) {
	if epoch%every != 0 {
		return
	}
	if err := os.MkdirAll(checkpointDir, 0o755); err != nil {
		fmt.Printf("⚠️  Could not create checkpoint dir: %v\n", err)
		return
	}
	path := filepath.Join(checkpointDir, fmt.Sprintf("gollemer_epoch_%04d.gob", epoch))
	if err := moe.SaveIntentMoEModelToGOB(model, path); err != nil {
		fmt.Printf("⚠️  Periodic checkpoint save failed (epoch %d): %v\n", epoch, err)
	} else {
		fmt.Printf("💾 Periodic checkpoint saved: %s\n", path)
	}

	pruneOldCheckpoints(checkpointDir, 3)
}

// pruneOldCheckpoints keeps only the `keep` most recent *.gob files in dir.
func pruneOldCheckpoints(dir string, keep int) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	var gobs []string
	for _, e := range entries {
		if !e.IsDir() && filepath.Ext(e.Name()) == ".gob" {
			gobs = append(gobs, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(gobs)
	for len(gobs) > keep {
		_ = os.Remove(gobs[0])
		gobs = gobs[1:]
	}
}

// CollectUtilisationFractions builds a []float64 of per-expert utilisation
// fractions (0-1) from ALL active encoder MoE layers (averaged across layers).
func CollectUtilisationFractions() []float64 {
	allLayers := moe.ActiveLayers
	if len(allLayers) == 0 {
		return nil
	}

	numExperts := len(allLayers[0].Experts)
	totals := make([]float64, numExperts)
	var grandTotal float64

	for _, layer := range allLayers {
		for i, count := range layer.AccumulatedUtilization {
			if i < numExperts {
				totals[i] += float64(count)
				grandTotal += float64(count)
			}
		}
	}

	fracs := make([]float64, numExperts)
	if grandTotal > 0 {
		for i := range fracs {
			fracs[i] = totals[i] / grandTotal
		}
	}
	return fracs
}

// min returns the smaller of two ints (helper for logger, Go 1.21 generics not assumed).
func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// PrepareTrainingSequence flattens a ConversationSample into token IDs and a loss mask.
//
// Speaker turns are delimited by <|im_start|> and <|im_end|> control tokens.
// Loss masking:
//
//   - Control/role prefix tokens → 0.0 (never train on these)
//   - User content tokens        → 0.0
//   - Assistant content tokens   → 1.0 (only these drive the gradient)
//   - Padding tokens             → 0.0
//
// If windowSize > 0, the slices are padded or truncated to that length.
func PrepareTrainingSequence(
	conv ConversationSample,
	vocab *mainvocab.Vocabulary,
	windowSize int,
) (tokens []int32, lossMask []float32) {
	lookup := func(word string) int32 {
		if id, ok := vocab.WordToToken[word]; ok {
			return int32(id)
		}
		return int32(vocab.GetTokenID("UNK"))
	}

	imStart := lookup("<|im_start|>")
	imEnd := lookup("<|im_end|>")
	newline := lookup("\n")

	for _, turn := range conv.Dialogue {

		for _, id := range []int32{imStart, lookup(string(turn.Role)), newline} {
			tokens = append(tokens, id)
			lossMask = append(lossMask, 0.0)
		}

		// Content tokens — only assistant turns contribute to the gradient.
		var maskVal float32
		if turn.Role == RoleAssistant {
			maskVal = 1.0
		}
		for _, word := range cleanTokenize(turn.Content) {
			tokens = append(tokens, lookup(word))
			lossMask = append(lossMask, maskVal)
		}

		tokens = append(tokens, imEnd)
		lossMask = append(lossMask, 0.0)
	}

	if windowSize > 0 {
		padID := int32(vocab.PaddingTokenID)
		for len(tokens) < windowSize {
			tokens = append(tokens, padID)
			lossMask = append(lossMask, 0.0)
		}
		if len(tokens) > windowSize {
			tokens = tokens[:windowSize]
			lossMask = lossMask[:windowSize]
		}
	}

	return tokens, lossMask
}

