// ExtractInterfaceMethods extracts method signatures from a Go interface definition.
func ExtractInterfaceMethods(code string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", code, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse error: %w", err)
	}

	var methods []string
	ast.Inspect(f, func(n ast.Node) bool {
		if ts, ok := n.(*ast.TypeSpec); ok {
			if iface, ok := ts.Type.(*ast.InterfaceType); ok {
				for _, m := range iface.Methods.List {
					if len(m.Names) > 0 {
						methodName := m.Names[0].Name
						methodType := types.ExprString(m.Type)
						methods = append(methods, fmt.Sprintf("%s %s", methodName, methodType))
					}
				}
			}
		}
		return true
	})

	return methods, nil
}

// GenerateInterfaceStub generates a struct stub that implements the given interface.
func GenerateInterfaceStub(structName string, code string) (string, error) {
	methods, err := ExtractInterfaceMethods(code)
	if err != nil {
		return "", err
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("type %s struct {\n", structName))
	sb.WriteString("\t// TODO: add fields\n")
	sb.WriteString("}\n\n")

	sb.WriteString(fmt.Sprintf("var _ InterfaceName = (*%s)(nil)\n\n", structName))

	for _, m := range methods {

		parts := strings.SplitN(m, " ", 2)
		if len(parts) == 2 {
			methodName := parts[0]
			methodSig := parts[1]
			sb.WriteString(fmt.Sprintf("func (s *%s) %s %s {\n", structName, methodName, methodSig))
			sb.WriteString("\t// TODO: implement\n")

			if strings.Contains(methodSig, ")") {
				sb.WriteString("\treturn\n")
			}
			sb.WriteString("}\n\n")
		}
	}

	return sb.String(), nil
}

// DefaultRLAIFConfig returns sensible defaults for RLAIF training.
func DefaultRLAIFConfig() RLAIFConfig {
	return RLAIFConfig{
		MaxIterations:		1000,
		SamplesPerPrompt:	5,
		RewardSuccess:		1.0,
		RewardFailure:		-1.0,
		RewardVetWarn:		-0.5,
		GoModPath:		".",
		TempDir:		"/tmp/gollemer_rlaif",
		KeepFailedPatches:	true,
		MaxRetries:		3,
	}
}

type RLAIFTrainer struct {
	config		RLAIFConfig
	model		RLAIFTrainableModel
	outcomes	[]PatchOutcome
	mu		sync.Mutex
}

// NewRLAIFTrainer creates a new RLAIF trainer.
func NewRLAIFTrainer(config RLAIFConfig, model RLAIFTrainableModel) *RLAIFTrainer {
	return &RLAIFTrainer{
		config:		config,
		model:		model,
		outcomes:	make([]PatchOutcome, 0),
	}
}

// RunTrainingLoop runs the main RLAIF training loop.
// It takes training examples, generates patches, verifies them with Go toolchain,
// and updates the model based on compiler reward signals.
func (r *RLAIFTrainer) RunTrainingLoop(examples []RLTrainingExample) error {
	if len(examples) == 0 {
		return fmt.Errorf("no training examples provided")
	}

	if err := os.MkdirAll(r.config.TempDir, 0755); err != nil {
		return fmt.Errorf("create temp dir: %w", err)
	}

	log.Printf("Starting RLAIF training loop:")
	log.Printf("  Examples: %d", len(examples))
	log.Printf("  Max iterations: %d", r.config.MaxIterations)
	log.Printf("  Samples per prompt: %d", r.config.SamplesPerPrompt)
	log.Printf("  Reward scheme: +%.1f pass, %.1f fail, %.1f vet warn",
		r.config.RewardSuccess, r.config.RewardFailure, r.config.RewardVetWarn)

	totalReward := 0.0
	successCount := 0
	failureCount := 0

	for iter := 0; iter < r.config.MaxIterations; iter++ {

		ex := examples[iter%len(examples)]

		for sample := 0; sample < r.config.SamplesPerPrompt; sample++ {
			start := time.Now()

			patch, err := r.model.GeneratePatch(ex.Instruction, ex.BeforeCode)
			if err != nil {
				log.Printf("  Sample %d: patch generation failed: %v", sample, err)
				continue
			}

			outcome := r.verifyPatch(patch, ex.BeforeCode, ex.FilePath)
			outcome.Duration = time.Since(start).String()
			outcome.Patch = patch

			r.mu.Lock()
			r.outcomes = append(r.outcomes, outcome)
			r.mu.Unlock()

			if err := r.model.UpdateFromReward(outcome); err != nil {
				log.Printf("  Model update failed: %v", err)
			}

			totalReward += outcome.Reward
			if outcome.Reward > 0 {
				successCount++
			} else {
				failureCount++
			}

			if !outcome.ValidGo || !outcome.BuildPassed {
				if r.config.MaxRetries > 0 {
					r.errorIngestion(ex, outcome)
				}
			}

			if !outcome.ValidGo && r.config.KeepFailedPatches {
				r.saveFailedPatch(iter, sample, patch, outcome.CompilerErrors)
			}
		}

		if (iter+1)%10 == 0 {
			avgReward := totalReward / float64(max(1, (iter+1)*r.config.SamplesPerPrompt))
			log.Printf("Iteration %d/%d: avg_reward=%.4f success=%d failure=%d",
				iter+1, r.config.MaxIterations, avgReward, successCount, failureCount)
		}

		if (iter+1)%100 == 0 {
			r.saveCheckpoint(fmt.Sprintf("rlaif_iter_%d", iter+1))
		}
	}

	log.Printf("RLAIF training complete!")
	log.Printf("  Total reward: %.2f", totalReward)
	log.Printf("  Success rate: %.1f%%", float64(successCount)/float64(max(1, successCount+failureCount))*100)

	r.saveCheckpoint("rlaif_final")

	return nil
}

// verifyPatch applies the patch and runs Go toolchain verification.
func (r *RLAIFTrainer) verifyPatch(patch, beforeCode, filePath string) PatchOutcome {
	outcome := PatchOutcome{
		Reward:		r.config.RewardFailure,
		ValidGo:	true,
	}

	fset := token.NewFileSet()
	if _, err := parser.ParseFile(fset, "", beforeCode, parser.AllErrors); err != nil {
		outcome.ValidGo = false
		outcome.CompilerErrors = fmt.Sprintf("before code parse error: %v", err)
		return outcome
	}

	afterCode := extractAfterFromPatch(patch)
	if afterCode == "" {
		outcome.ValidGo = false
		outcome.CompilerErrors = "could not extract REPLACE section from patch"
		return outcome
	}

	fset = token.NewFileSet()
	if _, err := parser.ParseFile(fset, "", afterCode, parser.AllErrors); err != nil {
		outcome.ValidGo = false
		outcome.CompilerErrors = fmt.Sprintf("after code parse error: %v", err)
		return outcome
	}
	outcome.ValidGo = true

	if filePath == "" {
		filePath = "patch_output.go"
	}
	tempFile := filepath.Join(r.config.TempDir, filepath.Base(filePath))

	if err := os.WriteFile(tempFile, []byte(afterCode), 0644); err != nil {
		outcome.CompilerErrors = fmt.Sprintf("write temp file: %v", err)
		return outcome
	}

	cmd := exec.Command("go", "vet", tempFile)
	if output, err := cmd.CombinedOutput(); err != nil {
		outcome.VetPassed = false
		outcome.CompilerErrors = string(output)
		outcome.Reward = r.config.RewardVetWarn
		return outcome
	}
	outcome.VetPassed = true

	modDir := filepath.Dir(tempFile)
	if _, err := os.Stat(filepath.Join(modDir, "go.mod")); os.IsNotExist(err) {
		initCmd := exec.Command("go", "mod", "init", "gollemer_rlaif_sandbox")
		initCmd.Dir = modDir
		if err := initCmd.Run(); err != nil {
			log.Printf("Warning: go mod init failed: %v", err)
		}
	}

	buildCmd := exec.Command("go", "build", "-o", "/dev/null", tempFile)
	buildCmd.Dir = modDir
	if output, err := buildCmd.CombinedOutput(); err != nil {
		outcome.BuildPassed = false
		outcome.CompilerErrors = string(output)
		outcome.Reward = r.config.RewardFailure
		return outcome
	}
	outcome.BuildPassed = true

	outcome.Reward = r.config.RewardSuccess

	return outcome
}

// errorIngestion feeds compiler errors back to generate a corrected patch.
func (r *RLAIFTrainer) errorIngestion(ex RLTrainingExample, outcome PatchOutcome) {

	errorContext := fmt.Sprintf(
		"Compiler Error:\n%s\n\n"+
			"Original instruction: %s\n"+
			"Generate a corrected patch that fixes the compilation error.",
		outcome.CompilerErrors,
		ex.Instruction,
	)

	for attempt := 0; attempt < r.config.MaxRetries; attempt++ {
		correctivePatch, err := r.model.GeneratePatch(errorContext, ex.BeforeCode)
		if err != nil {
			continue
		}

		correctiveOutcome := r.verifyPatch(correctivePatch, ex.BeforeCode, ex.FilePath)
		if correctiveOutcome.ValidGo && correctiveOutcome.BuildPassed {

			correctiveOutcome.Reward = r.config.RewardSuccess * 0.8
			_ = r.model.UpdateFromReward(correctiveOutcome)

			r.mu.Lock()
			r.outcomes = append(r.outcomes, correctiveOutcome)
			r.mu.Unlock()

			log.Printf("  Error ingestion: corrected patch found (attempt %d)", attempt+1)
			return
		}
	}
}

// saveFailedPatch stores a failed patch for later analysis.
func (r *RLAIFTrainer) saveFailedPatch(iter, sample int, patch, errors string) {
	failedDir := filepath.Join(r.config.TempDir, "failed_patches")
	if err := os.MkdirAll(failedDir, 0755); err != nil {
		return
	}

	record := struct {
		Iteration	int	`json:"iteration"`
		Sample		int	`json:"sample"`
		Patch		string	`json:"patch"`
		Errors		string	`json:"errors"`
	}{
		Iteration:	iter,
		Sample:		sample,
		Patch:		patch,
		Errors:		errors,
	}

	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return
	}

	path := filepath.Join(failedDir, fmt.Sprintf("failed_%d_%d.json", iter, sample))
	_ = os.WriteFile(path, data, 0644)
}

// saveCheckpoint saves model state.
func (r *RLAIFTrainer) saveCheckpoint(name string) {
	dir := filepath.Join(r.config.TempDir, "checkpoints")
	if err := os.MkdirAll(dir, 0755); err != nil {
		log.Printf("Warning: cannot create checkpoint dir: %v", err)
		return
	}
	path := filepath.Join(dir, fmt.Sprintf("%s.bin", name))
	if err := r.model.SaveCheckpoint(path); err != nil {
		log.Printf("Warning: save checkpoint failed: %v", err)
	}
	log.Printf("Checkpoint saved: %s", path)
}

// GetStats returns training statistics.
func (r *RLAIFTrainer) GetStats() RLAIFStats {
	r.mu.Lock()
	defer r.mu.Unlock()

	stats := RLAIFStats{
		TotalPatches:	len(r.outcomes),
		Outcomes:	r.outcomes,
	}

	for _, o := range r.outcomes {
		if o.ValidGo {
			stats.ValidPatches++
		}
		if o.VetPassed {
			stats.VetPassed++
		}
		if o.BuildPassed {
			stats.BuildPassed++
		}
		if o.Reward > 0 {
			stats.SuccessfulPatches++
		}
	}

	return stats
}

type RLTrainingExample struct {
	Instruction	string	`json:"instruction"`
	BeforeCode	string	`json:"before_code"`
	FilePath	string	`json:"file_path,omitempty"`
	TargetPatch	string	`json:"target_patch,omitempty"`
}

// extractAfterFromPatch extracts the REPLACE section from a SEARCH/REPLACE patch.
func extractAfterFromPatch(patch string) string {

	parts := strings.Split(patch, "=======\n")
	if len(parts) != 2 {
		return ""
	}
	after := strings.TrimSuffix(parts[1], "\n>>>>>>> REPLACE")
	after = strings.TrimSuffix(after, ">>>>>>> REPLACE")
	return after
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

type ExpertHyperParams struct {
	LearningRate	float64
	DropoutPenalty	float64
	LossWeight	float64
}

// NewAdaptiveSupervisor initializes a new supervisor.
func NewAdaptiveSupervisor(experts, dim int, dataPath string) *AdaptiveSupervisor {
	reg := make(map[int]*ExpertHyperParams)
	for i := 0; i < experts; i++ {
		reg[i] = &ExpertHyperParams{
			LearningRate:	0.001,
			DropoutPenalty:	0.1,
			LossWeight:	1.0,
		}
	}
	return &AdaptiveSupervisor{
		ModelDim:		dim,
		CurrentExperts:		experts,
		MaxExperts:		16,
		ExpertRegistry:		reg,
		PathFailureCount:	make(map[string]int),
		TrainingDataPath:	dataPath,
	}
}

// AssessSpawningPacing dynamically sets the spawning gate based on the intent domain.
func (s *AdaptiveSupervisor) AssessSpawningPacing(intent string) int {
	if s.ActiveMode == "OverfitMode" && intent == "social" {
		return 20
	}
	if intent == "social" || intent == "grammar_baseline" {
		return 15
	}
	return 5
}

// EvaluateGate performs real-time model surgery upon quality gate failures.
func (s *AdaptiveSupervisor) EvaluateGate(path string, score float64, intent, question string) {
	const threshold = 0.05

	if score >= threshold {
		return
	}

	log.Printf("⚠️  AdaptiveSupervisor: Quality Gate Rejected (Score: %.4f < %.4f). Taking control...", score, threshold)

	if s.CurrentExperts >= s.MaxExperts {
		log.Printf("⚠️ [Supervisor] Hard cap reached. Freezing mutations.")
		return
	}

	s.PathFailureCount[path]++
	s.mutateRouting(path)

	if s.PathFailureCount[path] >= 3 && s.CurrentExperts < s.MaxExperts {
		id := s.CurrentExperts
		s.CurrentExperts++

		log.Printf("🔥 [Structural Expansion] Path %s collapsed. Allocating Expert %d", path, id)

		s.ExpertRegistry[id] = &ExpertHyperParams{
			LearningRate:	0.0005,
			DropoutPenalty:	0.05,
			LossWeight:	1.2,
		}
		s.PathFailureCount[path] = 0
	}

	s.EvolveDataset(question)
}

func (s *AdaptiveSupervisor) mutateRouting(path string) {
	parts := strings.FieldsFunc(path, func(r rune) bool {
		return r == '+' || r == '-' || r == '>' || r == ' '
	})

	for _, p := range parts {
		if !strings.HasPrefix(p, "E") {
			continue
		}
		var id int
		fmt.Sscanf(p, "E%d", &id)

		if params, ok := s.ExpertRegistry[id]; ok {
			log.Printf("🎯 [Mutation] Adjusting hyper-parameters for Expert %d", id)
			params.LossWeight *= 0.85
			params.LearningRate *= 1.10
		}
	}
}

// ResetMetrics clears historical tracking and resets hyper-parameters.
func (s *AdaptiveSupervisor) ResetMetrics() {
	log.Printf("🔄 [Supervisor] Cold-Resetting metrics.")
	s.PathFailureCount = make(map[string]int)

	for id, param := range s.ExpertRegistry {
		param.LearningRate = 0.001
		param.DropoutPenalty = 0.1
		param.LossWeight = 1.0
		log.Printf("🔄 [Supervisor] Reset Expert %d to base weights.", id)
	}
}

// EvolveDataset enriches the standard syntax trees for specific failing queries.
func (s *AdaptiveSupervisor) EvolveDataset(question string) {
	if s.TrainingDataPath == "" {
		return
	}

	log.Printf("📝 [Data Evolution] Scanning training assets for target: '%s'", question)

	paths := strings.Split(s.TrainingDataPath, ",")
	totalMutations := 0

	for _, path := range paths {
		path = strings.TrimSpace(path)
		f, err := os.Open(path)
		if err != nil {
			log.Printf("⚠️  [Data Evolution] Error opening data %s: %v", path, err)
			continue
		}

		var lines []string
		scan := bufio.NewScanner(f)
		mutations := 0

		for scan.Scan() {
			line := scan.Text()

			if !strings.Contains(line, "__ques__ "+question+" __ans__") && !strings.HasPrefix(line, question+",") {
				lines = append(lines, line)
				continue
			}

			repl := replaceTarget(question)
			if strings.Contains(line, "__ques__") {
				line = strings.Replace(line, "__ques__ "+question, "__ques__ "+repl, 1)
			} else {
				line = strings.Replace(line, question+",", repl+",", 1)
			}

			lines = append(lines, line)
			mutations++
		}
		f.Close()

		if mutations > 0 {

			out, err := os.Create(path)
			if err != nil {
				log.Printf("⚠️  [Data Evolution] Error writing dataset %s: %v", path, err)
				continue
			}
			w := bufio.NewWriter(out)
			for _, l := range lines {
				w.WriteString(l + "\n")
			}
			w.Flush()
			out.Close()
			totalMutations += mutations
		}
	}

	if totalMutations > 0 {
		log.Printf("✅ [Data Evolution] Success. Mutated %d references.", totalMutations)
	}
}

func replaceTarget(q string) string {
	switch strings.ToLower(q) {
	case "hello", "hi", "hey":
		return "i welcome you with " + q
	case "thanks", "thank you":
		return "i offer you my thanks"
	case "i am sad":
		return "i feel very sad today"
	default:
		return q
	}
}

// ComputeLogMelSpectrogram converts a raw PCM audio chunk into a feature vector
// optimized for Gollemer's TemporalEncoder (GRU).
func ComputeLogMelSpectrogram(pcm []int16) []float32 {

	windowed := applyHanningWindow(pcm)

	fftMagnitudes := naivePowerSpectrum(windowed)

	features := make([]float32, len(fftMagnitudes))
	for i, mag := range fftMagnitudes {
		features[i] = float32(math.Log(float64(mag) + 1e-5))
	}

	return features
}

func applyHanningWindow(samples []int16) []float64 {
	n := len(samples)
	out := make([]float64, n)
	for i := 0; i < n; i++ {

		window := 0.5 * (1.0 - math.Cos(2.0*math.Pi*float64(i)/float64(n-1)))
		out[i] = float64(samples[i]) * window
	}
	return out
}

func naivePowerSpectrum(input []float64) []float64 {

	return input[:len(input)/2]
}

type IntentPayload struct {
	Intent	string			`json:"intent"`
	Roles	map[string]string	`json:"roles"`
}

// HandleIntent routes the model's decision to the OS driver layer
func HandleIntent(payload IntentPayload) error {
	switch payload.Intent {
	case "CAMERA_CAPTURE", "CAMERA_CAPTURE_ANALYZE":
		return TriggerCameraCapture(payload.Roles["target"])

	case "AUDIO_VOLUME_UP", "AUDIO_VOLUME_DOWN":
		return AdjustSpeakerVolume(payload.Intent)

	case "MICROPHONE_MUTE":
		return ToggleMicrophone(false)

	case "MICROPHONE_UNMUTE":
		return ToggleMicrophone(true)

	default:
		return fmt.Errorf("intent %s recognized but no hardware routine mapped yet", payload.Intent)
	}
}

