func GetDirSize(path string) (int64, error) {
	var size int64
	err := filepath.Walk(path, func(_ string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {
			size += info.Size()
		}
		return nil
	})
	return size, err
}

func FormatBytes(b int64) string {
	const unit = 1024
	if b < unit {
		return fmt.Sprintf("%d B", b)
	}
	div, exp := int64(unit), 0
	for n := b / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.2f %cB", float64(b)/float64(div), "KMGTPE"[exp])
}

// ScanQuests scans source files for TODO and FIXME patterns.
func ScanQuests() []Quest {
	var quests []Quest
	filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if !info.IsDir() && filepath.Ext(path) == ".go" && !contains(path, "vendor") && !contains(path, ".git") {
			file, err := os.Open(path)
			if err != nil {
				return nil
			}
			defer file.Close()

			scanner := bufio.NewScanner(file)
			lineNum := 1
			for scanner.Scan() {
				line := scanner.Text()
				if strings.Contains(line, "// TODO:") || strings.Contains(line, "// FIXME:") {
					parts := strings.Split(line, "//")
					if len(parts) > 1 {
						cleanText := strings.TrimSpace(parts[1])
						quests = append(quests, Quest{File: path, Line: lineNum, Text: cleanText})
					}
				}
				lineNum++
			}
		}
		return nil
	})
	return quests
}

func contains(path, substr string) bool {
	return (len(path) >= len(substr) && (path[:len(substr)] == substr || path[len(path)-len(substr):] == substr || strings.Contains(path, substr)))
}

// LoadPersonalQuests reads tasks.txt from ~/.gollemer
func LoadPersonalQuests() []string {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil
	}
	path := filepath.Join(home, ".gollemer", "tasks.txt")

	file, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer file.Close()

	var tasks []string
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		task := strings.TrimSpace(scanner.Text())
		if task != "" && !strings.HasPrefix(task, "#") {
			tasks = append(tasks, task)
		}
	}
	return tasks
}

// GetGitBranch returns the current branch name or "main" fallback.
func GetGitBranch() string {
	data, err := os.ReadFile(".git/HEAD")
	if err != nil {
		return "main"
	}
	content := string(data)
	if strings.Contains(content, "ref: refs/heads/") {
		return strings.TrimSpace(strings.Replace(content, "ref: refs/heads/", "", 1))
	}
	return "main"
}

func QuickCheck(path string, state *FolderState) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.Size() != state.LastSize || info.ModTime().After(state.LastMod) {
		state.LastSize = info.Size()
		state.LastMod = info.ModTime()
		return true
	}
	return false
}

// ParseDSL parses a series of DSL commands and returns a ProjectConfig
func ParseDSL(commands []string) (*config.ProjectConfig, error) {
	cfg := &config.ProjectConfig{
		Project: config.ProjectDetails{
			Name:	"GeneratedProject",
			Database: config.DatabaseConfig{
				Type:			"sqlite",
				ConnectionString:	"orchestrator.db",
			},
		},
		DataModels:	[]config.DataModel{},
	}

	modelMap := make(map[string]*config.DataModel)

	modelRegex := regexp.MustCompile(`(?i)^MODEL\s+(\w+)\s+FROM\s+([^\s]+)(?:\s+AS\s+(\w+))?`)
	endpointRegex := regexp.MustCompile(`(?i)^ENDPOINT\s+([^\s]+)\s+ADD\s+CRUD(?:\s+WITH\s+AUTH)?`)

	for _, cmd := range commands {
		cmd = strings.TrimSpace(cmd)
		if cmd == "" || strings.HasPrefix(cmd, "#") {
			continue
		}

		if matches := modelRegex.FindStringSubmatch(cmd); matches != nil {
			structName := matches[1]
			source := matches[2]

			model := config.DataModel{
				Source:		source,
				StructName:	structName,
				Endpoints:	[]string{},
				FieldOverrides:	make(map[string]config.FieldOverride),
			}
			cfg.DataModels = append(cfg.DataModels, model)

			modelMap[structName] = &cfg.DataModels[len(cfg.DataModels)-1]

		} else if matches := endpointRegex.FindStringSubmatch(cmd); matches != nil {
			path := matches[1]
			// Try to guess which model this endpoint belongs to
			// e.g., /api/v1/customer -> Customer
			var targetModel *config.DataModel
			for i := range cfg.DataModels {
				model := &cfg.DataModels[i]
				if strings.Contains(strings.ToLower(path), strings.ToLower(model.StructName)) {
					targetModel = model
					break
				}
			}

			if targetModel != nil {
				targetModel.Endpoints = append(targetModel.Endpoints, "GET "+path)
				targetModel.Endpoints = append(targetModel.Endpoints, "POST "+path+"/create")

			} else {

				if len(cfg.DataModels) > 0 {
					model := &cfg.DataModels[len(cfg.DataModels)-1]
					model.Endpoints = append(model.Endpoints, "GET "+path)
				}
			}
		} else {
			return nil, fmt.Errorf("unknown command: %s", cmd)
		}
	}

	return cfg, nil
}

