func (m *Mascot) AnalyzeComplexity(path string) {
	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return
	}

	ast.Inspect(node, func(n ast.Node) bool {
		if fn, ok := n.(*ast.FuncDecl); ok {
			complexity := 1
			ast.Inspect(fn.Body, func(bn ast.Node) bool {
				switch bn.(type) {
				case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.CaseClause, *ast.CommClause:
					complexity++
				}
				return true
			})

			if complexity > 10 {
				line := fset.Position(fn.Pos()).Line
				m.ConfirmRepair(fmt.Sprintf("Complexity alert: The '%s' function in %s:%d has a score of %d.", fn.Name.Name, path, line, complexity), func() error {
					m.Say(Happy, "Splitting this into multiple testable helpers will reduce your cognitive load. Working on a suggested refactor...")
					return nil
				})
			}
		}
		return true
	})
}

func (m *Mascot) AuditMemoryLeaks(root string) {
	fset := token.NewFileSet()

	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.Contains(path, "vendor") || strings.Contains(path, "wasm") {
			return nil
		}

		node, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}

		ast.Inspect(node, func(n ast.Node) bool {

			if goStmt, ok := n.(*ast.GoStmt); ok {
				if _, ok := goStmt.Call.Fun.(*ast.FuncLit); ok {

					hasContext := false
					ast.Inspect(goStmt, func(cn ast.Node) bool {
						if id, ok := cn.(*ast.Ident); ok {
							if strings.Contains(strings.ToLower(id.Name), "ctx") || id.Name == "context" {
								hasContext = true
							}
						}
						return true
					})

					if !hasContext {
						m.Say(Alert, fmt.Sprintf("In %s, a goroutine is started without a clear 'context' or stop signal.", filepath.Base(path)))
						m.Say(Happy, "Adding a 'context.WithCancel' here will ensure the worker dies when you exit the app!")
					}
				}
			}
			return true
		})
		return nil
	})
}

// Spin runs a loading animation in a goroutine
func (m *Mascot) Spin(frames []string, label string, stop chan bool) {
	i := 0
	for {
		select {
		case <-stop:
			fmt.Print("\r\033[K")
			os.Stdout.Sync()
			return
		default:

			fmt.Printf("\r%s/ʕ%sʔ/ > %s...%s", m.Color, frames[i%len(frames)], label, ColorReset)
			os.Stdout.Sync()
			i++
			time.Sleep(150 * time.Millisecond)
		}
	}
}

