func (m *Mascot) AuditGlobalState(root string) {
	fset := token.NewFileSet()
	globals := make(map[string]bool)

	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.Contains(path, "vendor") || strings.Contains(path, "wasm") {
			return nil
		}

		node, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}

		ast.Inspect(node, func(n ast.Node) bool {
			if gd, ok := n.(*ast.GenDecl); ok && gd.Tok == token.VAR {
				for _, spec := range gd.Specs {
					if vs, ok := spec.(*ast.ValueSpec); ok {
						for _, name := range vs.Names {
							globals[name.Name] = true
						}
					}
				}
			}
			return true
		})

		ast.Inspect(node, func(n ast.Node) bool {
			if as, ok := n.(*ast.AssignStmt); ok {
				for _, lhs := range as.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						if globals[id.Name] {
							varName := id.Name
							filePath := path
							line := fset.Position(id.Pos()).Line
							m.ConfirmRepair(fmt.Sprintf("Found a mutable global '%s' in %s:%d.", varName, filePath, line), func() error {
								m.Say(Thinking, fmt.Sprintf("Encapsulating '%s' into a SystemState struct...", varName))

								fset := token.NewFileSet()
								node, err := parser.ParseFile(fset, filePath, nil, parser.ParseComments)
								if err != nil {
									return err
								}

								ast.Inspect(node, func(n ast.Node) bool {
									if id, ok := n.(*ast.Ident); ok && id.Name == varName {

										id.Name = "protected" + strings.ToUpper(varName[:1]) + varName[1:]
									}
									return true
								})

								m.ApplyRefactor(filePath, node)
								m.Say(Happy, fmt.Sprintf("Variable '%s' renamed to indicate it needs protected access. Refactor complete!", varName))
								return nil
							})
						}
					}
				}
			}
			return true
		})

		return nil
	})
}

// HuntDeadCode maps every exported and private identifier and cross-references them with their usage.
func (m *Mascot) HuntDeadCode(root string) {
	fset := token.NewFileSet()
	type declInfo struct {
		Path	string
		Line	int
	}
	declarations := make(map[string]declInfo)
	usageCounts := make(map[string]int)
	declPositions := make(map[token.Pos]bool)

	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.Contains(path, "vendor") || strings.Contains(path, "wasm") {
			return nil
		}

		node, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}

		ast.Inspect(node, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.FuncDecl:
				if x.Name.Name != "main" && x.Name.Name != "init" {
					declarations[x.Name.Name] = declInfo{Path: path, Line: fset.Position(x.Name.Pos()).Line}
					declPositions[x.Name.Pos()] = true
				}
			case *ast.TypeSpec:
				declarations[x.Name.Name] = declInfo{Path: path, Line: fset.Position(x.Name.Pos()).Line}
				declPositions[x.Name.Pos()] = true
			case *ast.ValueSpec:
				for _, name := range x.Names {
					declarations[name.Name] = declInfo{Path: path, Line: fset.Position(name.Pos()).Line}
					declPositions[name.Pos()] = true
				}
			case *ast.AssignStmt:
				if x.Tok == token.DEFINE {
					for _, lhs := range x.Lhs {
						if id, ok := lhs.(*ast.Ident); ok {
							declPositions[id.Pos()] = true
						}
					}
				}
			case *ast.Ident:
				usageCounts[x.Name]++
			}
			return true
		})
		return nil
	})

	trueUsages := make(map[string]int)
	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.Contains(path, "vendor") || strings.Contains(path, "wasm") {
			return nil
		}

		localFset := token.NewFileSet()
		node, _ := parser.ParseFile(localFset, path, nil, 0)
		ast.Inspect(node, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok {

				trueUsages[id.Name]++
			}
			return true
		})
		return nil
	})

	deadCount := 0
	for name, info := range declarations {

		if trueUsages[name] <= 1 && !strings.HasPrefix(name, "Test") {
			deadCount++
			m.ConfirmRepair(fmt.Sprintf("Potential unused declaration '%s' in %s:%d.", name, info.Path, info.Line), func() error {
				m.Say(Happy, fmt.Sprintf("I've flagged '%s' for removal. This will prune your binary size! 👻", name))
				return nil
			})
		}
	}

	if deadCount > 0 {
		m.Say(Happy, fmt.Sprintf("Removing these items will reduce your binary size and cognitive load!"))
	}
}

type FileState struct {
	Size	int64
	ModTime	time.Time
}

type Workspace struct {
	LastState map[string]FileState
}

func NewWorkspace() *Workspace {
	return &Workspace{LastState: make(map[string]FileState)}
}

// Scan checks for created or modified files and returns a map of changes
func (w *Workspace) Scan(root string) map[string]string {
	changes := make(map[string]string)
	newState := make(map[string]FileState)

	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || isHidden(path) {
			return nil
		}

		curr := FileState{Size: info.Size(), ModTime: info.ModTime()}
		newState[path] = curr

		if old, exists := w.LastState[path]; exists {
			if curr.Size != old.Size || !curr.ModTime.Equal(old.ModTime) {
				changes[path] = "modified"
			}
		} else if len(w.LastState) > 0 {
			changes[path] = "created"
		}
		return nil
	})

	w.LastState = newState
	return changes
}

func isHidden(path string) bool {
	base := filepath.Base(path)
	return strings.HasPrefix(base, ".") || strings.Contains(path, "vendor") || strings.Contains(path, "bin")
}

// IsSpecialToken returns true if tok is a registered hardware control token.
func IsSpecialToken(tok string) bool {
	for _, t := range SpecialHardwareTokens {
		if t == tok {
			return true
		}
	}
	return false
}

// InjectIntoVocab adds every special hardware token to the provided vocabulary
// map (word → id) and its reverse slice (id → word), starting from the next
// available ID.  Call this before training so the embedding matrix has fixed
// slots reserved for each control token.
func InjectIntoVocab(wordToToken map[string]int, tokenToWord *[]string) {
	for _, tok := range SpecialHardwareTokens {
		if _, exists := wordToToken[tok]; exists {
			continue
		}
		id := len(*tokenToWord)
		wordToToken[tok] = id
		*tokenToWord = append(*tokenToWord, tok)
	}
}

// Colorize applies foreground and background colors to a string and prints it.
func Colorize(ForegroundColor, BackgroundColor, line, prefix string, blink bool) {
	fcolor, ok := fgColors[ForegroundColor]
	if !ok {
		fcolor = fgColors["default"]
	}

	bcolor, ok := bgColors[BackgroundColor]
	if !ok {
		bcolor = bgColors["default"]
	}

	blinkCode := ""
	if blink {
		blinkCode = "5;"
	}

	combineCode := ""
	if bcolor != "" {
		combineCode = bcolor
	}
	if fcolor != 0 {
		if combineCode != "" {
			combineCode += ";"
		}
		combineCode += fmt.Sprintf("%d", fcolor)
	}
	if blinkCode != "" {
		if combineCode != "" {
			combineCode += ";"
		}
		combineCode += blinkCode[:len(blinkCode)-1]
	}

	fmt.Printf("%s\x1b[%sm%s\x1b[0m", prefix, combineCode, line)
}

// ShowSpinner displays a terminal spinner with a message for a given duration.
func ShowSpinner(message, fgColor, bgColor string, duration time.Duration) {
	spinnerChars := []rune{'—', '\\', '|', '/'}
	i := 0
	clearLine := "\r\033[K"

	startTime := time.Now()
	for time.Since(startTime) < duration {
		spinnerChar := string(spinnerChars[i%len(spinnerChars)])

		fcolor, ok := fgColors[fgColor]
		if !ok {
			fcolor = fgColors["default"]
		}

		bcolor, ok := bgColors[bgColor]
		if !ok {
			bcolor = bgColors["default"]
		}

		fmt.Printf("%s\x1b[%s;%dm%s %s\x1b[0m", clearLine, bcolor, fcolor, spinnerChar, message)

		i++
		time.Sleep(100 * time.Millisecond)
	}
	fmt.Print(clearLine)
}

// AnimatedOutput first shows a spinner for a duration, then prints the final output.
func AnimatedOutput(ForegroundColor, BackgroundColor, line string, animationDuration time.Duration) {
	ShowSpinner("Processing...", ForegroundColor, BackgroundColor, animationDuration)
	ColorizeOutPut(ForegroundColor, BackgroundColor, line)
}

func ColorizeCol(ForegroundColor, BackgroundColor, line string) {
	Colorize(ForegroundColor, BackgroundColor, line, "", false)
	fmt.Printf("\x1b[0m\n")
}

func ColorizeOutPut(ForegroundColor, BackgroundColor, line string) {
	Colorize(ForegroundColor, BackgroundColor, line, " ", false)
	fmt.Printf("\x1b[0m\n")
}

// Typewriter prints a message with a typing effect.
func Typewriter(message string, delay time.Duration) {
	for _, char := range message {
		fmt.Printf("%c", char)
		os.Stdout.Sync()
		time.Sleep(delay)
		if char == '.' || char == '!' || char == '?' {
			time.Sleep(200 * time.Millisecond)
		}
	}
	fmt.Println()
}

