func findTensors(v reflect.Value, totalParams *int, tensorCount *int) {
	if !v.IsValid() {
		return
	}

	if v.Type() == reflect.TypeOf(&tensor.Tensor{}) && !v.IsNil() {
		t := v.Interface().(*tensor.Tensor)
		*tensorCount++
		*totalParams += len(t.Data)
		return
	}

	switch v.Kind() {
	case reflect.Ptr, reflect.Interface:
		if !v.IsNil() {
			findTensors(v.Elem(), totalParams, tensorCount)
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			findTensors(v.Field(i), totalParams, tensorCount)
		}
	case reflect.Slice, reflect.Array:
		for i := 0; i < v.Len(); i++ {
			findTensors(v.Index(i), totalParams, tensorCount)
		}
	case reflect.Map:
		for _, key := range v.MapKeys() {
			findTensors(v.MapIndex(key), totalParams, tensorCount)
		}
	}
}

type Pair struct {
	Key	string
	Value	int
}

func extractTokens(obj interface{}, counter map[string]int) {
	switch v := obj.(type) {
	case map[string]interface{}:
		for k, val := range v {
			counter[k]++
			extractTokens(val, counter)
		}
	case []interface{}:
		for _, item := range v {
			extractTokens(item, counter)
		}
	default:
		token := fmt.Sprintf("%v", v)
		counter[token]++
	}
}

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run analyze_token_frequency.go <path_to_json>")
		os.Exit(1)
	}
	path := os.Args[1]

	file, err := os.ReadFile(path)
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		os.Exit(1)
	}

	var data []map[string]interface{}
	if err := json.Unmarshal(file, &data); err != nil {
		fmt.Printf("Error unmarshalling json: %v\n", err)
		os.Exit(1)
	}

	counter := make(map[string]int)
	for _, entry := range data {
		if semanticOutput, ok := entry["semantic_output"]; ok {
			extractTokens(semanticOutput, counter)
		}
	}

	p := make(PairList, len(counter))
	i := 0
	for k, v := range counter {
		p[i] = Pair{k, v}
		i++
	}

	sort.Sort(sort.Reverse(p))

	fmt.Println("Token Frequency:")
	for _, k := range p {
		fmt.Printf("%s: %d\n", k.Key, k.Value)
	}
}

func main() {
	dirPath := flag.String("path", ".", "Directory to scan for Go files")
	flag.Parse()

	var goFiles []string

	err := filepath.WalkDir(*dirPath, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() && (d.Name() == "vendor" || d.Name() == ".build" || d.Name() == ".git") {
			return filepath.SkipDir
		}
		if !d.IsDir() && strings.HasSuffix(d.Name(), ".go") {
			goFiles = append(goFiles, path)
		}
		return nil
	})

	if err != nil {
		log.Fatalf("Error scanning directory: %v", err)
	}

	if len(goFiles) == 0 {
		log.Fatalf("No Go source files found under path: %s", *dirPath)
	}

	fmt.Printf("🔍 Benchmark scanning %d Go files under '%s'...\n\n", len(goFiles), *dirPath)

	if len(goFiles) > 50 {
		goFiles = goFiles[:50]
	}

	fmt.Printf("🔬 Go Tokenizer Compression Benchmark\n")
	fmt.Printf("   Files sampled: %d\n", len(goFiles))
	fmt.Println(strings.Repeat("─", 72))

	bpePlain := tokenizer.NewBPETokenizer(16384)
	bpeGo := tokenizer.NewBPETokenizer(16384)

	tokenizer.AddGoTokensToTokenizer(bpeGo)

	for _, tok := range []string{"<|im_start|>", "<|im_end|>", "<pad>", "<s>", "</s>", "UNK", "\n"} {
		bpePlain.AddSpecialToken(tok)
	}

	// Track statistics
	type fileStats struct {
		path		string
		size		int
		plainTokens	int
		goTokens	int
		compression	float64
	}

	var stats []fileStats
	totalPlain := 0
	totalGo := 0
	totalSize := 0

	for _, path := range goFiles {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		content := string(data)
		size := len(content)

		plainIDs := bpePlain.Encode(content)
		plainCount := len(plainIDs)

		preprocessedContent := tokenizer.GoTokenizePreprocess(content)

		goIDs := bpeGo.Encode(preprocessedContent)
		goCount := len(goIDs)
		compression := 0.0
		if plainCount > 0 {
			compression = (1.0 - float64(goCount)/float64(plainCount)) * 100.0
		}

		totalPlain += plainCount
		totalGo += goCount
		totalSize += size

		stats = append(stats, fileStats{
			path:		path,
			size:		size,
			plainTokens:	plainCount,
			goTokens:	goCount,
			compression:	compression,
		})
	}

	fmt.Printf("\n%-55s %8s %8s %8s %8s\n", "File", "Size", "Plain", "Go", "Δ%")
	fmt.Println(strings.Repeat("─", 72))
	for _, s := range stats {
		delta := fmt.Sprintf("%+.1f%%", s.compression)
		fmt.Printf("%-55s %8d %8d %8d %8s\n",
			truncatePath(s.path, 55),
			s.size,
			s.plainTokens,
			s.goTokens,
			delta,
		)
	}

	fmt.Println(strings.Repeat("─", 72))
	avgCompression := 0.0
	if len(stats) > 0 {
		avgCompression = (1.0 - float64(totalGo)/float64(totalPlain)) * 100.0
	}
	fmt.Printf("%-55s %8d %8d %8d %+.1f%%\n",
		"TOTAL",
		totalSize,
		totalPlain,
		totalGo,
		avgCompression,
	)
	fmt.Println(strings.Repeat("─", 72))

	fmt.Printf("\n📊 Analysis:\n")
	fmt.Printf("   Total plain tokens:  %d\n", totalPlain)
	fmt.Printf("   Total Go tokens:     %d\n", totalGo)
	fmt.Printf("   Tokens saved:        %d (%.1f%% reduction)\n",
		totalPlain-totalGo, avgCompression)
	fmt.Printf("   Go vocab tokens:     %d\n", len(tokenizer.GoHighFreqTokens()))

	fmt.Printf("\n🏆 Top token-saving patterns:\n")
	patternSavings := countPatternSavings(goFiles, bpePlain, bpeGo)
	for i, ps := range patternSavings {
		if i >= 10 {
			break
		}
		fmt.Printf("   %3d. %-30s saved %d tokens across %d files\n",
			i+1, truncateString(ps.pattern, 30), ps.savings, ps.files)
	}

	fmt.Printf("\n✅ Benchmark complete\n")
}

type patternSaving struct {
	pattern	string
	savings	int
	files	int
}

func countPatternSavings(files []string, plain, goTok *tokenizer.BPETokenizer) []patternSaving {
	patterns := tokenizer.GoHighFreqTokens()
	var results []patternSaving

	for _, p := range patterns {
		if len(p) < 5 {
			continue
		}
		totalSavings := 0
		fileCount := 0
		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			content := string(data)
			count := strings.Count(content, p)
			if count > 0 {

				savings := count * 3
				totalSavings += savings
				fileCount++
			}
		}
		if totalSavings > 0 {
			results = append(results, patternSaving{
				pattern:	p,
				savings:	totalSavings,
				files:		fileCount,
			})
		}
	}

	for i := 0; i < len(results); i++ {
		for j := i + 1; j < len(results); j++ {
			if results[j].savings > results[i].savings {
				results[i], results[j] = results[j], results[i]
			}
		}
	}

	return results
}

func truncatePath(path string, maxLen int) string {
	if len(path) <= maxLen {
		return path
	}
	return "..." + path[len(path)-maxLen+3:]
}

func truncateString(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-3] + "..."
}

type Pair struct {
	Key	string
	Value	int
}

func findMissing(obj interface{}, vocab map[string]int, missing map[string]int) {
	switch v := obj.(type) {
	case map[string]interface{}:
		for k, val := range v {
			if _, exists := vocab[k]; !exists {
				missing[k]++
			}
			findMissing(val, vocab, missing)
		}
	case []interface{}:
		for _, item := range v {
			findMissing(item, vocab, missing)
		}
	default:
		token := fmt.Sprintf("%v", v)
		if _, exists := vocab[token]; !exists {
			missing[token]++
		}
	}
}

